class CleanEngineeringModel(SourceModel, Node):
    practice = "clean_engineering"
    _semantic_type_name = "CleanEngineeringModel"

    def load_module(self, source: SourceModule) -> Module:
        if isinstance(source, BoundedContext):
            from practices.ddd.model.codeql.codeql_model import BoundedContext as GraphBoundedContext

            return GraphBoundedContext(source.name, source.sequential_order)
        if isinstance(source, Aggregate):
            from practices.ddd.model.codeql.codeql_model import Aggregate as GraphAggregate

            return GraphAggregate(source.name, source.sequential_order)
        return Module(source.name, source.sequential_order)

    def module_named(self, name: str, *, order: int) -> Module:
        mod = self.load_module(Module(name, order))
        self.graph.register(mod)
        self.modules.append(mod)
        self.relate(Kind.OWNS, mod)
        return mod


    def ensure(self, graph: "PracticeGraph", rows: GraphMemberRows) -> None:
        self._rows = rows
        self._graph = graph
        if graph.ce_model is None and (rows.classes or rows.properties or rows.operations):
            graph.ce_model = type(self)("CleanEngineering", 1)
            graph.register(graph.ce_model)
        self._model = graph.ce_model
        self._modules = {mod.name.lower(): mod for mod in graph.nodes_of_type(Module)}
        self._classes, self._files = self._indexed_types()
        self._order = 1
        self._span = SourceSpan(getattr(graph, "root", None))
        self._ensure_classes()
        self._ensure_properties()
        self._ensure_operations()

    def _indexed_types(self) -> tuple[Dict[str, OoadClass], Dict[str, File]]:
        classes: Dict[str, OoadClass] = {}
        files: Dict[str, File] = {}
        for node in self._graph.nodes.values():
            if isinstance(node, OoadClass):
                classes[node.name.lower()] = node
            if isinstance(node, File):
                files[node.name.replace("\\", "/").lower()] = node
        return classes, files

    def _ensure_classes(self) -> None:
        for entry in self._rows.classes:
            module_name = entry.get("module") or ""
            name = entry.get("name") or ""
            if not name or not module_name:
                continue
            mod = self._modules.get(module_name.lower())
            if mod is None:
                mod = self._model.module_named(module_name, order=self._order)
                self._order += 1
                self._modules[module_name.lower()] = mod
            if name.lower() in self._classes:
                self._span.bind(self._classes[name.lower()], entry)
                continue
            self._classes[name.lower()] = mod.accept_class(name, entry.get("stereotypes") or [])
            self._span.bind(self._classes[name.lower()], entry)

    def _ensure_properties(self) -> None:
        for prop in self._rows.properties:
            owned = self._classes.get(str(prop.get("class_name") or "").replace("\\", "/").lower())
            if owned is None:
                continue
            owned.accept_property(prop.get("name") or "", prop.get("type_hint") or "")
            node = next((p for p in owned.property_nodes if p.name == (prop.get("name") or "")), None)
            if node is not None:
                self._span.bind(node, prop)

    def _ensure_operations(self) -> None:
        for op in self._rows.operations:
            owned = self._member_owner(op)
            if owned is None:
                continue
            owned.accept_operation(op.get("name") or "", op.get("return_type") or "", op.get("parameters") or [])
            node = next((o for o in owned.operation_nodes if o.name == (op.get("name") or "")), None)
            if node is not None:
                self._span.bind(node, op)
        for row in self._rows.parameters:
            owned = self._member_owner(row)
            if owned is None:
                continue
            operation = next((o for o in owned.operation_nodes if o.name == row.get("operation")), None)
            if operation is None:
                continue
            operation.accept_parameter(row.get("name") or "")
            param = next((p for p in operation.parameters if p.name == (row.get("name") or "")), None)
            if param is not None:
                self._span.bind(param, row)

    def _member_owner(self, row):
        class_name = str(row.get("class_name") or "").replace("\\", "/")
        owned = self._classes.get(class_name.lower())
        if owned is not None:
            return owned
        if "/" not in class_name and not class_name.endswith(".py"):
            return None
        key = class_name.lower()
        if key not in self._files:
            file_path = str(row.get("file") or class_name).replace("\\", "/")
            self._files[key] = self._module_for_path(file_path).accept_file(file_path)
            self._span.bind(self._files[key], {"file": file_path, "line": 1, "end_line": 1})
        return self._files[key]

    def _module_for_path(self, path: str):
        normalized = path.replace("\\", "/")
        matches = [
            mod
            for mod in self._modules.values()
            if normalized == mod.name.replace(".", "/")
            or normalized.startswith(mod.name.replace(".", "/") + "/")
            or normalized.startswith(mod.name + "/")
        ]
        if matches:
            return max(matches, key=lambda mod: len(mod.name))
        folder = str(Path(normalized).parent).replace("\\", "/")
        if folder in (".", ""):
            folder = normalized
        key = folder.lower()
        if key not in self._modules:
            self._modules[key] = self._model.module_named(folder, order=self._order)
            self._order += 1
        return self._modules[key]

    def wire_calls(self, graph: "PracticeGraph", calls: List[dict]) -> None:
        seen: set[tuple] = set()
        for call in calls:
            key = (
                call.get("caller_class"),
                call.get("caller_operation"),
                call.get("callee_class"),
                call.get("callee_operation"),
            )
            if key in seen:
                continue
            seen.add(key)
            caller = graph.operation_named(call.get("caller_class") or "", call.get("caller_operation") or "")
            callee = graph.operation_named(call.get("callee_class") or "", call.get("callee_operation") or "")
            if isinstance(caller, Operation) and isinstance(callee, Operation):
                caller.invokes(callee)

class Module(SourceModule, Node):
    practice = "clean_engineering"
    _semantic_type_name = "Module"

    def load_class(self, source: SourceClass) -> OoadClass:
        return OoadClass(source.name, source.sequential_order)

    def accept_class(self, name: str, stereotypes: List[str] | None = None) -> OoadClass:
        from practices.ddd.model.codeql.codeql_model import ddd_graph_class_for

        decorated = name
        marks = stereotypes or []
        if marks:
            decorated = f"{name} {' '.join(f'<<{s}>>' for s in marks)}"
        stub = OoadClass(decorated, len(self.classes) + 1)
        if marks or ddd_class_kind(decorated):
            cls = ddd_graph_class_for(stub)
        else:
            cls = self.load_class(stub)
        self.classes.append(cls)
        self.graph.register(cls)
        self.relate(Kind.OWNS, cls)
        cls.relate(Kind.BELONGS_TO, self)
        return cls

    def accept_file(self, path: str) -> "File":
        node = File(path.replace("\\", "/"), len(self.classes) + 1)
        self.graph.register(node)
        self.relate(Kind.OWNS, node)
        node.relate(Kind.BELONGS_TO, self)
        return node

    @property
    def external_classes(self) -> List[OoadClass]:
        return [cls for cls in self.related(Kind.DEPENDS_ON) if isinstance(cls, OoadClass)]

    @property
    def dependency_modules(self) -> List["Module"]:
        return [mod for mod in self.related(Kind.DEPENDS_ON) if isinstance(mod, Module)]

    @property
    def callers(self) -> List["Module"]:
        return [mod for mod in self.used_by if isinstance(mod, Module)]

class OoadClass(_Members, SourceClass, Node):
    practice = "clean_engineering"
    _semantic_type_name = "OoadClass"

    def sync_tree_from_legacy(self) -> None:
        self.property_nodes = [
            Property.from_field(field, index)
            for index, field in enumerate(self.properties, start=1)
        ]
        self.operation_nodes = [
            Operation.from_field(field, index)
            for index, field in enumerate(self.operations, start=1)
        ]

    @property
    def external_classes(self) -> List["OoadClass"]:
        return [cls for cls in self.related(Kind.DEPENDS_ON) if isinstance(cls, OoadClass)]

class OoadNode:
    _semantic_type_name: str = "OoadNode"

    def __init__(self, name: str, sequential_order: int) -> None:
        self.name = name
        self.sequential_order = sequential_order

    def semantic_type(self) -> str:
        return self._semantic_type_name

    def translate_from(self, source: "OoadNode") -> UpdateReport:
        if self.semantic_type() != source.semantic_type():
            raise TranslationError(
                f"Cannot translate from {source.semantic_type()} into {self.semantic_type()}"
            )
        report = UpdateReport()
        self.update_self(source)
        for pair in self.child_collections(source):
            self._reconcile_collection(pair, report)
        return report

    def update_self(self, source: "OoadNode") -> None:
        raise NotImplementedError(f"{type(self).__name__} must implement update_self")

    def child_collections(self, source: "OoadNode") -> List[ChildCollectionPair]:
        raise NotImplementedError(f"{type(self).__name__} must implement child_collections")

    def _reconcile_collection(self, pair: ChildCollectionPair, report: UpdateReport) -> None:
        consumed_ids: set = set()
        reconciled: List[OoadNode] = []

        for source_child in pair.source_children:
            match = self._find_match(source_child, pair.self_children, consumed_ids)
            if match is not None:
                consumed_ids.add(id(match))
                match.translate_from(source_child)
                reconciled.append(match)
                report.add_exact_match(match.name)
            else:
                new_child = pair.load(source_child)
                new_child.translate_from(source_child)
                reconciled.append(new_child)
                report.add_new(new_child, parent_name=self.name)

        for existing in pair.self_children:
            if id(existing) not in consumed_ids:
                report.add_removed(existing, parent_name=self.name)

        pair.self_children[:] = reconciled

    @staticmethod
    def _find_match(
        source: "OoadNode",
        candidates: List["OoadNode"],
        consumed_ids: set,
    ) -> Optional["OoadNode"]:
        for c in candidates:
            if id(c) not in consumed_ids and c.name == source.name:
                return c
        for c in candidates:
            if id(c) not in consumed_ids and c.sequential_order == source.sequential_order:
                return c
        return None

class PropertyField:
    name: str
    type_hint: str = ""
    description: str = ""
    sequential_order: int = 0

    def as_record(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "typeHint": self.type_hint,
            "description": self.description,
        }

    def update_self(self, source: "PropertyField") -> None:
        self.name = source.name
        self.type_hint = source.type_hint
        self.description = source.description
        self.sequential_order = source.sequential_order

    def translate_from(self, source: "PropertyField") -> UpdateReport:
        self.update_self(source)
        return UpdateReport()

    def render(self) -> str:
        if self.type_hint:
            return f"{self.name}: {self.type_hint}"
        return self.name

class Relationship:
    """Explicit edge: from — kind — to."""

    def __init__(self, kind: str, from_node: "Node", to_node: "Node") -> None:
        self.kind = kind
        self.from_node = from_node
        self.to_node = to_node

    @property
    def from_id(self) -> str:
        return self.from_node.node_id

    @property
    def to_id(self) -> str:
        return self.to_node.node_id

class Operation(OoadNode):
    _semantic_type_name = "Operation"

    def __init__(
        self,
        name: str,
        sequential_order: int,
        return_type: str = "",
        description: str = "",
        callees: List[str] | None = None,
    ) -> None:
        super().__init__(name, sequential_order)
        self.return_type = return_type
        self.description = description
        self.callees: List[str] = list(callees) if callees is not None else []
        self.parameters: List[Parameter] = []
        self._legacy_parameters: List[str] = []

    @property
    def legacy_parameters(self) -> List[str]:
        return list(self._legacy_parameters)

    @legacy_parameters.setter
    def legacy_parameters(self, values: List[str]) -> None:
        self._legacy_parameters = list(values)

    @classmethod
    def from_field(cls, field: OperationField, sequential_order: int) -> "Operation":
        op = cls(
            name=field.name,
            sequential_order=sequential_order,
            return_type=field.return_type,
            description=field.description,
            callees=list(field.callees),
        )
        op._legacy_parameters = list(field.parameters)
        op._sync_parameters_from_legacy()
        return op

    def _sync_parameters_from_legacy(self) -> None:
        from practices.clean_engineering.model.type_refs import parse_parameter

        self.parameters = []
        for index, raw in enumerate(self._legacy_parameters, start=1):
            name, type_hint = parse_parameter(raw)
            self.parameters.append(
                Parameter(name or f"arg{index}", index, type_hint=type_hint)
            )

    def to_field(self) -> OperationField:
        params = [
            f"{p.name}: {p.type_hint}" if p.type_hint else p.name for p in self.parameters
        ] or list(self._legacy_parameters)
        return OperationField(
            name=self.name,
            parameters=params,
            return_type=self.return_type,
            description=self.description,
            callees=list(self.callees),
        )

    def as_record(self) -> dict:
        return self.to_field().as_record()

    def render(self) -> str:
        return self.to_field().render()

    def update_self(self, source: OoadNode) -> None:
        assert isinstance(source, Operation)
        self.name = source.name
        self.sequential_order = source.sequential_order
        self.return_type = source.return_type
        self.description = source.description
        self.callees = list(source.callees)
        self.legacy_parameters = list(source.legacy_parameters)

    def load_parameter(self, source: Parameter) -> Parameter:
        return Parameter(source.name, source.sequential_order, source.type_hint)

    def child_collections(self, source: OoadNode) -> List[ChildCollectionPair]:
        assert isinstance(source, Operation)
        if source.parameters:
            return [
                ChildCollectionPair(
                    self_children=self.parameters,
                    source_children=source.parameters,
                    load=self.load_parameter,
                )
            ]
        return []

class Parameter(OoadNode):
    _semantic_type_name = "Parameter"

    def __init__(self, name: str, sequential_order: int, type_hint: str = "") -> None:
        super().__init__(name, sequential_order)
        self.type_hint = type_hint

    def as_record(self) -> dict:
        return {"name": self.name, "typeHint": self.type_hint}

    def update_self(self, source: OoadNode) -> None:
        assert isinstance(source, Parameter)
        self.name = source.name
        self.sequential_order = source.sequential_order
        self.type_hint = source.type_hint

    def child_collections(self, source: OoadNode) -> List[ChildCollectionPair]:
        return []

class Property(OoadNode):
    _semantic_type_name = "Property"

    def __init__(
        self,
        name: str,
        sequential_order: int,
        type_hint: str = "",
        description: str = "",
    ) -> None:
        super().__init__(name, sequential_order)
        self.type_hint = type_hint
        self.description = description

    @classmethod
    def from_field(cls, field: PropertyField, sequential_order: int) -> "Property":
        return cls(
            name=field.name,
            sequential_order=sequential_order,
            type_hint=field.type_hint,
            description=field.description,
        )

    def to_field(self) -> PropertyField:
        return PropertyField(
            name=self.name,
            type_hint=self.type_hint,
            description=self.description,
        )

    def as_record(self) -> dict:
        return {
            "name": self.name,
            "typeHint": self.type_hint,
            "description": self.description,
        }

    def render(self) -> str:
        return self.to_field().render()

    def update_self(self, source: OoadNode) -> None:
        assert isinstance(source, Property)
        self.name = source.name
        self.sequential_order = source.sequential_order
        self.type_hint = source.type_hint
        self.description = source.description

    def child_collections(self, source: OoadNode) -> List[ChildCollectionPair]:
        return []

class UpdateReport:
    changes: List[Change] = field(default_factory=list)

    def add_exact_match(self, name: str) -> None:
        self.changes.append(Change(kind=ChangeKind.EXACT_MATCH, from_name=name, to_name=name))

    def add_new(self, node: "UxNode", parent_name: Optional[str] = None) -> None:
        self.changes.append(
            Change(kind=ChangeKind.ADD, node_name=node.name, parent_name=parent_name)
        )

    def add_removed(self, node: "UxNode", parent_name: Optional[str] = None) -> None:
        self.changes.append(
            Change(kind=ChangeKind.REMOVE, node_name=node.name, parent_name=parent_name)
        )

class WorkSession:
    """One named work session — owns openTurn, turns, repairs, git; session.md kit."""

    default_workspace_folder: str = "."
    context_index_key: str = ""
    _START_FIELD_KEYS = ("date", "path", "goal", "fidelities", "contexts")
    _END_FIELD_KEYS = ("ended", "outcome", "handoff")
    _END_HEADING = "## End"

    def __init__(
        self,
        workspace: Workspace | str | None = None,
        name: str = "",
        *,
        session: str = "",
        goal: str = "",
        fidelities: str = "",
        contexts: str = "",
        path: str = "",
        git: GitRepo | None = None,
        started: str | None = None,
        ended: str = "",
        outcome: str = "",
        handoff: str = "",
        body: str = "",
        format: str | None = None,
        workspace_root: str | None = None,
        context_index_key: str | None = None,
        default_workspace_folder: str | None = None,
        tool: Any | None = None,
        isolate: bool = True,
    ) -> None:
        if isinstance(workspace, Workspace):
            parent = workspace
        else:
            root = (workspace or "").strip() or "."
            found = Repo(root).find_root()
            parent = Workspace(str(found) if found is not None else root)
        name = (name or session).strip()
        if not name:
            git_root = Repo(parent.path).find_root()
            if git_root is not None:
                branch = GitRepo(git_root).current_branch
                if isinstance(branch, str) and branch.startswith("session/"):
                    name = branch[len("session/") :]
        requested_path = path
        self.workspace = parent
        self.name = name
        self.goal = goal
        self.fidelities = fidelities
        self.contexts = contexts
        self.path = path or parent.path
        self.workspace_root = workspace_root if workspace_root is not None else parent.path
        self.git = git if git is not None else self._default_git()
        self.open_turn: Turn | None = None
        self.turns: list[Turn] = []
        self.repairs = Repairs(self)
        self.decisions = RecordDecisions()
        self.scope_paths: list[str] = [str(self.git.root)]
        self.trail: list[ToolCall] = []
        self.format = format
        self._tool = tool
        self._context_index: str | None = None
        if context_index_key is not None:
            self.context_index_key = context_index_key
        if default_workspace_folder is not None:
            self.default_workspace_folder = default_workspace_folder
        if not requested_path:
            self.path = self._resolve_working_area(None)
        self.started = started if started is not None else date.today().isoformat()
        self.ended = ended
        self.outcome = outcome
        self.handoff = handoff
        self.body = body
        self.cli_doer = ""
        self.cli_judge = ""
        self.cli_doer_pid = 0
        self.cli_judge_pid = 0
        self._transcript_home: Path | None = None
        self.venv_note = ""
        # False → session folders / turns / logs on the current checkout (no sibling worktree).
        self.isolate = isolate

    def _default_git(self) -> GitRepo:
        root = Repo(self.workspace.path).find_root()
        if root is None:
            return NullGitRepo(self.workspace.path)
        return GitRepo(root)

    @property
    def session_branch(self) -> str:
        return f"session/{self.name}"

    @property
    def is_default_work_session(self) -> bool:
        return self.name == SessionModel.DEFAULT_SESSION

    def _main_branch_names(self) -> set[str]:
        default = getattr(self.git, "default_branch", "main") or "main"
        return {default, "main", "master"}

    def _on_main_branch(self) -> bool:
        branch = getattr(self.git, "current_branch", "") or ""
        return branch in self._main_branch_names()

    @property
    def sync_only_close(self) -> bool:
        """Default session on main — commit session artifacts, no branch landing."""
        return self.is_default_work_session and self._on_main_branch()

    def branch_warning(self) -> str:
        if self._on_main_branch():
            return ""
        branch = getattr(self.git, "current_branch", "") or ""
        default = getattr(self.git, "default_branch", "main") or "main"
        return (
            f"warning: current branch is {branch!r}, not {default!r} — "
            "staying on this branch (no switch)"
        )

    @property
    def dirty(self) -> bool:
        return self.git.is_dirty(untracked=False)

    @property
    def turn(self) -> Turn:
        """Optional in-memory turn for mistake/correction during a session."""
        if self.open_turn is None:
            hanging = Turn(root=str(self.git.root))
            if self.context_index_key:
                hanging.context_tool = self.context_index_key
            self.open_turn = hanging
        return self.open_turn

    @property
    def docs_dir(self) -> Path:
        """Durable artifacts: sketches, generated files, grill-answers — ``{path}/.context/``."""
        return SessionPaths().docs_dir(self.path)

    @property
    def folder(self) -> Path:
        """Session temps in the working path: session.md, handoff, logs."""
        if not self.name:
            raise ValueError(
                "session name is not set - confirm working path and session slug with the "
                "user, then call open before grill/sketch/handoff"
            )
        return SessionPaths().session_dir(self.path, self.name)

    @property
    def log(self) -> Path:
        return self.folder / "logs"

    @property
    def session_md(self) -> Path:
        return self.folder / "session.md"

    @property
    def cli_agent_file(self) -> Path:
        return self.folder / "cli-agent.json"

    @property
    def model_file(self) -> Path:
        return self.folder / SessionModel.FILENAME

    @property
    def session_model(self) -> str:
        """Preferred IDE/CLI model for this session, or empty when unset."""
        if self.model_file.is_file():
            try:
                return self.model_file.read_text(encoding="utf-8").strip()
            except OSError:
                return ""
        return SessionModel(self.path or self.workspace.path).read(self.name)

    def set_session_model(self, model: str) -> str:
        """Persist *model* under this session folder and return the value written."""
        path = SessionModel(self.path or self.workspace.path).write(model, self.name)
        return path.read_text(encoding="utf-8").strip()

    def _inherit_session_model(self) -> None:
        """Copy model from primary (session or default) into this session folder when missing."""
        if self.model_file.is_file():
            return
        primary: Path | None = None
        git = self.git
        if git is not None and not getattr(git, "_memory", False):
            try:
                primary = Path(git.primary_root())
            except Exception:
                primary = None
        if primary is None:
            primary = Path(self.workspace.path)
        SessionModel(primary).copy_into(self.folder, self.name)

    def load_cli_sessions(self) -> None:
        binding = self.cli_agent_binding
        if binding.doer or binding.judge:
            self.cli_doer = binding.doer
            self.cli_judge = binding.judge
            self.cli_doer_pid = binding.doer_pid
            self.cli_judge_pid = binding.judge_pid
            return
        path = self.cli_agent_file
        if not path.is_file():
            return
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return
        self.cli_doer = str(data.get("doer") or "").strip()
        self.cli_judge = str(data.get("judge") or "").strip()
        self.cli_doer_pid = int(data.get("doer_pid") or 0)
        self.cli_judge_pid = int(data.get("judge_pid") or 0)

    def save_cli_sessions(self) -> None:
        self.folder.mkdir(parents=True, exist_ok=True)
        self.cli_agent_file.write_text(
            json.dumps(
                {
                    "doer": self.cli_doer,
                    "judge": self.cli_judge,
                    "doer_pid": self.cli_doer_pid,
                    "judge_pid": self.cli_judge_pid,
                },
                indent=2,
            ),
            encoding="utf-8",
        )
        self._write_cli_agent_tag()

    def associate_cli(self, role: str, chat_id: str) -> None:
        chat_id = (chat_id or "").strip()
        if role == "judge":
            self.cli_judge = chat_id
        else:
            self.cli_doer = chat_id
        self.save_cli_sessions()

    def close_cli_sessions(self) -> None:
        """Clear doer/judge chat bindings and stop their processes if still alive.

        Does not close the work session — only the CLI agent processes/bindings.
        """
        for pid in (self.cli_doer_pid, self.cli_judge_pid):
            pid = int(pid or 0)
            if pid <= 0:
                continue
            try:
                if os.name == "nt":
                    subprocess.run(
                        ["taskkill", "/PID", str(pid), "/T", "/F"],
                        capture_output=True,
                        check=False,
                    )
                else:
                    os.kill(pid, 15)
            except OSError:
                pass
        self.cli_doer = ""
        self.cli_judge = ""
        self.cli_doer_pid = 0
        self.cli_judge_pid = 0
        if self.cli_agent_file.is_file():
            self.cli_agent_file.unlink()
        self._write_cli_agent_tag(status="closed")

    @property
    def agent_open(self) -> bool:
        return self.cli_agent_binding.open

    @property
    def cli_agent(self):
        """Bound CliAgent for this session, or None if none ran."""
        self.load_cli_sessions()
        binding = self.cli_agent_binding
        if not (self.cli_doer or self.cli_judge or binding.doer or binding.judge):
            return None
        from cli_agent.cli_agent import CliAgent

        self.workspace.current_work_session = self
        agent = CliAgent(workspace=str(self.path), session=self.name)
        agent._work = self.workspace
        return agent

    @property
    def cli_agent_binding(self):
        from git.git import CliAgentBinding

        git = self.git
        reader = getattr(git, "read_cli_agent_tag", None)
        if reader is None:
            return CliAgentBinding()
        try:
            return reader(self.session_branch)
        except Exception:
            return CliAgentBinding()

    def _write_cli_agent_tag(self, status: str = "open") -> None:
        from git.git import CliAgentBinding

        git = self.git
        binding = CliAgentBinding(
            status=status if (self.cli_doer or self.cli_judge) else "closed",
            doer=self.cli_doer,
            doer_pid=self.cli_doer_pid,
            judge=self.cli_judge,
            judge_pid=self.cli_judge_pid,
        )
        if status == "closed":
            binding.status = "closed"
        try:
            binding.write_tag(git, self.session_branch)
        except Exception:
            return

    @property
    def context_index(self) -> str:
        return self._context_index or ""

    @property
    def module_dir(self) -> Path:
        return Path(inspect.getfile(type(self))).resolve().parent

    @property
    def domain_slug(self) -> str:
        return "workspace_session"

    @markdown
    def session_guidance(self) -> str: ...

    @property
    def active(self) -> WorkSession:
        return self

    @staticmethod
    def _normalize_session_path(stored: str, checkout: str | Path) -> str:
        """Resolve ``path: .`` (or other relative paths) against the active checkout."""
        raw = (stored or "").strip()
        base = Path(checkout or ".")
        if not raw:
            return str(base.resolve())
        candidate = Path(raw)
        if not candidate.is_absolute():
            candidate = base / candidate
        return str(candidate.resolve())

    def _take_from(self, other: WorkSession) -> None:
        self.path = other.path
        self.name = other.name
        self.goal = other.goal
        self.fidelities = other.fidelities
        self.contexts = other.contexts
        self.started = other.started
        self.ended = other.ended
        self.outcome = other.outcome
        self.handoff = other.handoff
        self.body = other.body

    def _bind_session_log(self) -> None:
        if self.name:
            from workspace.legacy.session_log import SessionLog

            SessionLog.instance().bind(self)

    def attach_tool(self, tool: Any) -> None:
        self._tool = tool

    def _resolve_working_area(self, working_area: str | None) -> str:
        if working_area is not None:
            return working_area
        key = self.context_index_key or ""
        indexed = ContextIndex.lookup_root(self.workspace_root, key) if key else None
        if indexed:
            return ContextIndex.root_glob_to_path(self.workspace_root, indexed)
        folder = self.default_workspace_folder or "."
        if folder in (".", ""):
            return self.workspace_root
        return str(Path(self.workspace_root) / folder)

    def to_dict(self) -> dict[str, str | None]:
        try:
            folder = str(self.folder)
        except ValueError:
            folder = None
        return {
            "path": self.path,
            "name": self.name,
            "folder": folder,
            "goal": self.goal or None,
            "fidelities": self.fidelities or None,
            "contexts": self.contexts or None,
            "started": self.started or None,
            "ended": self.ended or None,
            "outcome": self.outcome or None,
            "handoff": self.handoff or None,
            "body": self.body or None,
        }

    def __repr__(self) -> str:
        return f"WorkSession(path={self.path!r}, name={self.name!r})"

    @classmethod
    def load(cls, path: str, name: str) -> WorkSession:
        parent = Workspace(path)
        session = cls(parent, name, path=path, workspace_root=path)
        session._attach_existing_session_worktree()
        md = session.session_md
        if not md.is_file():
            return session
        return cls._parse(md.read_text(encoding="utf-8"), path=path, name=name)

    def _retarget_git(self, root: Path) -> None:
        self.git = GitRepo.open(root)
        self.path = str(root)
        self.workspace_root = str(root)
        self.scope_paths = [str(root)]

    def _session_branch_is_default(self) -> bool:
        if self.is_default_work_session:
            return True
        default = getattr(self.git, "default_branch", "main") or "main"
        if self.name in {default, "main", "master"}:
            return True
        return self.session_branch in {default, "main", "master"}

    def _attach_existing_session_worktree(self) -> None:
        git = self.git
        if getattr(git, "_memory", False) or not self.name:
            return
        if not self.isolate or self._session_branch_is_default():
            return
        existing = git.worktree_for(self.session_branch)
        if existing is None:
            return
        if existing.path.resolve() != Path(git.root).resolve():
            self._retarget_git(existing.path)

    def _ensure_session_worktree(self) -> None:
        git = self.git
        if getattr(git, "_memory", False):
            if not self.isolate or self._session_branch_is_default():
                return
            git.checkout_or_create(self.session_branch)
            return
        if not self.isolate or self._session_branch_is_default():
            self._try_fetch_pull()
            return
        self._attach_existing_session_worktree()
        git = self.git
        if git.current_branch == self.session_branch:
            self._try_fetch_pull()
            return
        existing = git.worktree_for(self.session_branch)
        if existing is not None:
            self._retarget_git(existing.path)
            self._try_fetch_pull()
            return
        self._try_fetch()
        primary = git.primary_root()
        dest = primary.parent / self._worktree_dirname(primary.name, self.name)
        tree = git.add_worktree(dest, self.session_branch)
        primary = Path(primary)
        self._retarget_git(tree)
        self.folder.mkdir(parents=True, exist_ok=True)
        SessionModel(primary).copy_into(self.folder, self.name)
        self._try_fetch_pull()

    def _ensure_worktree_venv(self) -> None:
        """Point at this checkout's .venv — one interpreter for the CDD repo."""
        git = self.git
        if getattr(git, "_memory", False):
            return
        venv = Path(git.root) / ".venv"
        python = venv / ("Scripts" if os.name == "nt" else "bin") / (
            "python.exe" if os.name == "nt" else "python"
        )
        self.venv_note = "" if python.is_file() else f"no venv at {venv}"

    @staticmethod
    def _abbrev_repo_name(folder: str) -> str:
        """Abbreviate a clone folder: first token, then first letter of each later token."""
        tokens = [part for part in re.split(r"[-_]+", folder or "") if part]
        if not tokens:
            return folder
        if len(tokens) == 1:
            return tokens[0]
        return tokens[0] + "-" + "".join(token[0] for token in tokens[1:])

    @classmethod
    def _worktree_dirname(cls, repo_folder: str, session_name: str) -> str:
        """Sibling directory `{abbrev}-{ticket-or-short-slug}` next to the primary clone."""
        slug = (session_name or "").strip().strip("-")
        ticket = re.search(r"-(\d+)$", slug)
        short = ticket.group(1) if ticket else slug
        if ticket is None and len(short) > 24:
            short = short[:24].rstrip("-")
        return f"{cls._abbrev_repo_name(repo_folder)}-{short}"

    def _try_fetch(self) -> None:
        try:
            self.git.fetch()
        except GitConnectError:
            return

    def _try_fetch_pull(self) -> None:
        self._try_fetch()
        try:
            self.git.pull()
        except GitConnectError:
            return

    def _try_push(self) -> None:
        try:
            self.git.push()
        except GitConnectError:
            return

    def _land_on_default_branch(self) -> None:
        if not self.isolate or self._session_branch_is_default():
            self._try_push()
            return
        default = self.git.default_branch
        for candidate in (default, f"origin/{default}", "main", "origin/main"):
            try:
                self.git.merge_from(
                    candidate,
                    message=f"merge {candidate} into {self.session_branch}",
                )
                break
            except GitConnectError:
                continue
        self._try_push()
        try:
            self.git.push_to(default)
        except GitConnectError:
            pass
        occupier = self.git.worktree_for(default)
        if occupier is None:
            try:
                self.git._git("branch", "-f", default, "HEAD")
            except GitConnectError:
                return
            return
        if occupier.path.resolve() == Path(self.git.root).resolve():
            return
        other = GitRepo(occupier.path)
        other.clear_stash()
        if other.is_dirty():
            return
        try:
            other.merge_from(
                self.session_branch,
                message=f"merge {self.session_branch} into {default}",
            )
        except GitConnectError:
            return

    def _remove_session_worktree_if_clean(self) -> None:
        git = self.git
        if getattr(git, "_memory", False) or not self.isolate:
            return
        self._try_push()
        # Shared/session stash must not keep worktrees around — drop it and remove.
        git.clear_stash()
        # Untracked .context session temps must not block removal — agent BDD and
        # finish_work_session leave disposable CliAgent files that are gitignored.
        if git.is_dirty(untracked=False) or git.has_unpushed_commits():
            return
        if git.is_linked_worktree():
            try:
                GitRepo(git.primary_root()).remove_worktree(git.root)
            except GitConnectError:
                pass
        self._remove_empty_checkout_dir()

    def _repository_root(self) -> Path:
        git = self.git
        if not getattr(git, "_memory", False):
            try:
                return SessionPaths().repository_root(git.primary_root())
            except (AttributeError, TypeError, ValueError):
                pass
        return SessionPaths().repository_root(
            self.workspace_root or self.path or self.workspace.path
        )

    @staticmethod
    def _closed_sessions_dir(repo_root: Path) -> Path:
        closed = repo_root / ".sessions" / "closed"
        closed.mkdir(parents=True, exist_ok=True)
        return closed

    def _closed_archive_search_roots(self) -> list[Path]:
        """Checkouts that may hold ``.sessions/closed/{name}/`` from a prior close."""
        roots: list[Path] = []
        seen: set[str] = set()

        def add(root: Path) -> None:
            try:
                key = str(root.resolve())
            except OSError:
                key = str(root)
            if key in seen:
                return
            seen.add(key)
            closed = root / ".sessions" / "closed"
            if closed.is_dir():
                roots.append(closed)

        try:
            add(self._archive_root())
        except (AttributeError, TypeError, ValueError):
            pass
        add(Path(self.path or self.workspace.path))
        add(self._repository_root())
        git = self.git
        if git is not None and not getattr(git, "_memory", False):
            try:
                add(Path(git.primary_root()))
            except (AttributeError, TypeError, ValueError):
                pass
        return roots

    @staticmethod
    def _closed_archive_content_root(closed_dir: Path, name: str) -> Path | None:
        nested = closed_dir / name
        if (nested / "session.md").is_file():
            return nested
        if (closed_dir / "session.md").is_file():
            return closed_dir
        try:
            if closed_dir.is_dir() and any(closed_dir.iterdir()):
                return closed_dir
        except OSError:
            return None
        return None

    @staticmethod
    def _force_rmtree(path: Path) -> None:
        """Remove a directory tree on Windows even when files are read-only."""
        if not path.exists():
            return
        for root, dirs, files in os.walk(path, topdown=False):
            for name in files:
                item = Path(root) / name
                try:
                    item.chmod(stat.S_IWRITE)
                    item.unlink(missing_ok=True)
                except OSError:
                    pass
            for name in dirs:
                item = Path(root) / name
                try:
                    item.chmod(stat.S_IWRITE)
                    item.rmdir()
                except OSError:
                    pass
        try:
            path.chmod(stat.S_IWRITE)
            path.rmdir()
        except OSError:
            shutil.rmtree(path, ignore_errors=True)

    def _move_tree_contents(self, source: Path, dest: Path) -> None:
        dest.mkdir(parents=True, exist_ok=True)
        for item in source.iterdir():
            target = dest / item.name
            if target.exists():
                if target.is_dir():
                    try:
                        self._force_rmtree(target)
                    except OSError:
                        self._move_tree_contents(item, target)
                else:
                    try:
                        target.chmod(stat.S_IWRITE)
                        target.unlink(missing_ok=True)
                    except OSError:
                        pass
            shutil.move(str(item), str(target))

    def _find_closed_session_archive(self) -> tuple[Path, Path] | None:
        """Return ``(closed_entry, content_root)`` for the best closed archive match."""
        name = (self.name or "").strip()
        if not name:
            return None
        candidates: list[Path] = []
        for closed_root in self._closed_archive_search_roots():
            exact = closed_root / name
            if exact.is_dir():
                candidates.append(exact)
            prefix = f"{name}-"
            try:
                for item in closed_root.iterdir():
                    if item.is_dir() and item.name.startswith(prefix):
                        candidates.append(item)
            except OSError:
                continue
        if not candidates:
            return None
        exact_matches = [path for path in candidates if path.name == name]
        pool = exact_matches or candidates
        pool.sort(
            key=lambda path: path.stat().st_mtime if path.exists() else 0,
            reverse=True,
        )
        for closed_dir in pool:
            content = self._closed_archive_content_root(closed_dir, name)
            if content is not None:
                return closed_dir, content
        return None

    def _restore_closed_session_if_needed(self) -> bool:
        """Move ``.sessions/closed/{name}/`` back to ``.sessions/{name}/`` on reopen."""
        found = self._find_closed_session_archive()
        if found is None:
            return False
        closed_dir, content = found
        dest = self.folder
        dest.mkdir(parents=True, exist_ok=True)
        self._move_tree_contents(content, dest)
        if closed_dir != content:
            for item in closed_dir.iterdir():
                if item.resolve() == content.resolve():
                    continue
                target = dest / item.name
                if item.is_dir():
                    if target.exists():
                        self._move_tree_contents(item, target)
                        self._force_rmtree(item)
                    else:
                        shutil.move(str(item), str(target))
                elif not target.exists():
                    shutil.move(str(item), str(target))
        self._force_rmtree(closed_dir)
        return True

    def _reactivate_on_reopen(self) -> None:
        """Drop ``## End`` on reopen — a resumed session is active again."""
        text = ""
        if self.session_md.is_file():
            text = self.session_md.read_text(encoding="utf-8")
        if self._END_HEADING not in text and not self.ended:
            return
        self.ended = ""
        self.outcome = ""
        self.handoff = ""
        if self.session_md.is_file():
            self.session_md.write_text(self._render(), encoding="utf-8")

    def _archive_root(self) -> Path:
        """Repository root that owns ``.sessions/closed/`` archives."""
        return self._repository_root()

    def _archive_session_folder(self) -> Path | None:
        """Move session temps to ``{checkout}/.sessions/closed/{name}/``."""
        if not self.name:
            return None
        try:
            source = self.folder
        except ValueError:
            return None
        if not source.is_dir():
            return None
        closed_dir = self._closed_sessions_dir(self._archive_root())
        dest = closed_dir / self.name
        if dest.exists():
            stamp = (self.ended or date.today().isoformat()).replace(":", "-")
            dest = closed_dir / f"{self.name}-{stamp}"
        shutil.move(str(source), str(dest))
        return dest

    def _consolidate_session_for_archive(self) -> None:
        root = Path(self.path or self.git.root)
        SessionLogs(root).consolidate_logs_for_close(self.name)
        self.folder.mkdir(parents=True, exist_ok=True)
        self.log.mkdir(parents=True, exist_ok=True)

    def _commit_closed_archive(self, archived: Path | None) -> None:
        if archived is None or not archived.is_dir():
            return
        closed_root = archived.parent
        if not closed_root.is_dir():
            return
        try:
            self.git.commit(
                [str(closed_root)],
                f"archive session {self.name}",
                untracked=True,
            )
        except (GitConnectError, ValueError):
            pass

    def _commit_active_session_removal(self) -> None:
        """Stage tracked deletions under ``.sessions/{name}/`` after archive move."""
        slug = (self.name or "").strip()
        if not slug:
            return
        root = Path(self.path or self.git.root)
        session_path = SessionPaths().sessions_root(root) / slug
        if session_path.is_dir():
            return
        try:
            self.git.commit(
                [str(session_path)],
                f"remove active session {slug}",
            )
        except (GitConnectError, ValueError):
            pass

    def _ticket_number_from_session_name(self) -> int | None:
        match = re.search(r"-(\d+)$", (self.name or "").strip())
        if not match:
            return None
        return int(match.group(1))

    def _embed_ticket_context(self) -> None:
        """When the session slug ends in -{issue}, copy that ticket and linked sub-issues into session.md."""
        if (self.body or "").strip():
            return
        number = self._ticket_number_from_session_name()
        if number is None:
            return
        try:
            from workflow.work_ticket import format_session_ticket_context

            gh_repo = Repo.open(str(self._repository_root()))
        except (GitConnectError, ValueError):
            return
        body, contexts = format_session_ticket_context(gh_repo, number)
        if body and not (self.body or "").strip():
            self.body = body
        if contexts and not (self.contexts or "").strip():
            self.contexts = contexts

    def _bind_active_session_logs(self) -> None:
        root = Path(self.path or self.git.root)
        SessionLogs(root).write_active_session(self.name or SessionModel.DEFAULT_SESSION)

    def _remove_empty_checkout_dir(self) -> None:
        root = Path(self.path)
        if not root.is_dir():
            return
        try:
            if any(root.iterdir()):
                return
            root.rmdir()
        except OSError:
            return

    def ensure_started(
        self,
        *,
        goal: str = "",
        fidelities: str = "",
        contexts: str = "",
    ) -> Path:
        if not self.name:
            raise ValueError("session name is required to create a sprint folder")
        SessionPaths().migrate_legacy_session_folder(
            self._repository_root(), self.folder
        )
        self._ensure_session_worktree()
        self._restore_closed_session_if_needed()
        self.folder.mkdir(parents=True, exist_ok=True)
        creating = not self.session_md.is_file()
        if not creating:
            checkout = self.path
            loaded = type(self).load(checkout, self.name)
            self._take_from(loaded)
            self._ensure_session_worktree()
            self.path = str(Path(self.git.root).resolve())
            self._reactivate_on_reopen()
        if creating:
            if goal:
                self.goal = goal
            if fidelities:
                self.fidelities = fidelities
            if contexts:
                self.contexts = contexts
            if not self.started:
                self.started = date.today().isoformat()
            self._embed_ticket_context()
            self.session_md.write_text(self._render(), encoding="utf-8")
        self._ensure_worktree_venv()
        self._inherit_session_model()
        return self.session_md

    def open(
        self,
        name: str = "",
        goal: str = "",
        fidelities: str = "",
        contexts: str = "",
        path: str = "",
        isolate: bool | None = None,
    ) -> str:
        if name:
            self.name = name
        if goal:
            self.goal = goal
        if fidelities:
            self.fidelities = fidelities
        if contexts:
            self.contexts = contexts
        if path:
            self.path = path
        if isolate is not None:
            self.isolate = isolate
        if not self.name:
            self.name = SessionModel.DEFAULT_SESSION
            self.isolate = False
        self.ensure_started(goal=goal, fidelities=fidelities, contexts=contexts)
        self._bind_active_session_logs()
        self._bind_session_log()
        self.load_cli_sessions()
        self.read_context_index()
        self.record_context_root()
        consumed = self.consume_handoff()
        opened = (
            "Workspace open. "
            "durable root = path; "
            "sprint docs = folder; "
            "context index loaded when present."
        )
        if self.venv_note:
            opened = f"rebuilt .venv in {self.path} — {self.venv_note}\n{opened}"
        warning = self.branch_warning()
        if warning:
            opened = f"{warning}\n{opened}"
        if not consumed:
            return opened
        return (
            f"{opened} Consumed and deleted the handoff. "
            "Use this text only for this open. "
            "After that, grill-answers, sketches, and generated files are the source of truth.\n\n"
            f"{consumed}"
        )

    def _handoff_search_roots(self) -> list[Path]:
        roots: list[Path] = []
        try:
            roots.append(self.folder)
        except ValueError:
            pass
        roots.append(self.docs_dir)
        if self.name:
            sibling = self.docs_dir / self.name
            if sibling.is_dir() and sibling not in roots:
                roots.append(sibling)
        return roots

    def consume_handoff(self) -> str:
        """Read a live handoff once, then delete it.

        Deletes ``handoff-latest.md``, ``handoff.md``, and ``handoffs/`` under
        the session folder and docs_dir. A consumed handoff is not session state.
        """
        text = ""
        for root in self._handoff_search_roots():
            for name in ("handoff-latest.md", "handoff.md"):
                path = root / name
                if not path.is_file():
                    continue
                if not text:
                    text = path.read_text(encoding="utf-8")
                path.unlink()
            archive = root / "handoffs"
            if archive.is_dir():
                shutil.rmtree(archive)
        if text:
            self.handoff = ""
        return text

    def _ensure_sprint(
        self,
        name: str = "",
        goal: str = "",
        fidelities: str = "",
        contexts: str = "",
        path: str = "",
    ) -> str:
        effective_path = path.strip() or self.path
        effective_name = SessionModel().session_slug(name.strip() or (self.name or ""))
        loaded = type(self).load(effective_path, effective_name)
        if loaded.session_md.is_file():
            self._take_from(loaded)
        else:
            self.path = effective_path
            self.name = effective_name
            self.goal = goal
            self.fidelities = fidelities
            self.contexts = contexts
            self.ended = ""
            self.outcome = ""
            self.handoff = ""
            self.started = date.today().isoformat()
        self.ensure_started(goal=goal, fidelities=fidelities, contexts=contexts)
        self._bind_active_session_logs()
        self._bind_session_log()
        return str(self.session_md.resolve())

    def chat_tag_name(self) -> str:
        return f"chat/{self.session_branch}"

    def save_chat(self, message: str, *, sha: str = "") -> None:
        text = (message or "").strip()
        if not text:
            return
        target = (sha or "").strip() or self.git.current_commit
        self.git.note(target, {"chat": text}, ref="refs/notes/chats")
        existing = [
            line
            for line in self.git.read_annotated_tag(self.chat_tag_name()).splitlines()
            if line.strip()
        ]
        if text not in existing:
            existing.append(text)
        self.git._annotated_tag_target = target
        self.git.write_annotated_tag(self.chat_tag_name(), "\n".join(existing))

    def chats(self) -> list[str]:
        return [
            line
            for line in self.git.read_annotated_tag(self.chat_tag_name()).splitlines()
            if line.strip()
        ]

    @staticmethod
    def _session_slug(name: str) -> str:
        slug = (name or "").strip()
        if slug.startswith("session/"):
            return slug[len("session/") :]
        return slug

    @agent_tool
    def worksession_chat(
        self,
        tools: list[Any] | None = None,
        name: str = "",
    ) -> list[str]:
        """worksession-chat — list chat transcript paths attached to a work session.

        Reads the append-only annotated tag ``chat/session/{name}``. Omit ``name`` to
        use the current work session (or this session). Pass the kebab session name or
        ``session/...`` branch when looking up a closed session from another chat.
        """
        slug = self._session_slug(name)
        if tools:
            for item in tools:
                workspace = getattr(item, "workspace", None)
                if workspace is None:
                    continue
                current = getattr(workspace, "current_work_session", None)
                if not slug and current is not None:
                    return current.chats()
                if slug:
                    git = current.git if current is not None else None
                    return WorkSession(workspace, slug, git=git).chats()
        if not slug or slug == self.name:
            return self.chats()
        return WorkSession(self.workspace, slug, git=self.git).chats()

    @staticmethod
    def cursor_project_slug(workspace: str) -> str:
        raw = str(Path(workspace).resolve())
        return (
            raw.replace(":", "")
            .replace("\\", "-")
            .replace("/", "-")
            .replace("_", "-")
        )

    def cursor_chat_file(self, chat_id: str, *, workspace: str = "") -> Path:
        chat_id = (chat_id or "").strip()
        home = self._transcript_home or Path.home()
        root = workspace or self.path or self.workspace_root
        return (
            Path(home)
            / ".cursor"
            / "projects"
            / self.cursor_project_slug(root)
            / "agent-transcripts"
            / chat_id
            / f"{chat_id}.jsonl"
        )

    def current_cursor_chat_file(self) -> Path | None:
        """This chat's transcript — ``CURSOR_CONVERSATION_ID`` (per agent process, not mtime).

        Tests may set ``_conversation_id`` to a uuid, or to ``\"\"`` to ignore the process env.
        """
        if getattr(self, "_conversation_id", None) is not None:
            chat_id = (self._conversation_id or "").strip()
        else:
            chat_id = (os.environ.get("CURSOR_CONVERSATION_ID") or "").strip()
        if not chat_id:
            return None
        transcripts = (os.environ.get("AGENT_TRANSCRIPTS") or "").strip()
        if transcripts and getattr(self, "_conversation_id", None) is None:
            root = Path(transcripts)
            nested = root / chat_id / f"{chat_id}.jsonl"
            flat = root / f"{chat_id}.jsonl"
            if nested.is_file():
                return nested
            if flat.is_file():
                return flat
            return nested
        return self.cursor_chat_file(chat_id)

    def _running_chat_paths(self) -> list[str]:
        """CliAgent doer/judge chats when bound, plus this Cursor chat when present."""
        paths: list[str] = []
        seen: set[str] = set()

        def _add(path: str) -> None:
            if path and path not in seen:
                seen.add(path)
                paths.append(path)

        current = self.current_cursor_chat_file()
        if current is not None:
            _add(str(current))
        for chat_id in (self.cli_doer, self.cli_judge):
            if not chat_id:
                continue
            _add(str(self.cursor_chat_file(chat_id)))
        return paths

    def close(self, *, outcome: str = "", handoff: str = "handoff.md") -> Path:
        running_chats = self._running_chat_paths()
        turn = self.open_turn or Turn(root=str(self.git.root))
        turn.turn(
            message=outcome or "session close",
            utility="finish-work-session",
            context_tool=turn.context_tool or self.context_index_key,
        )
        self.open_turn = None
        agent = self.cli_agent
        if agent is not None:
            agent.cleanup()
        self.close_cli_sessions()
        if not self.session_md.is_file():
            self.ensure_started()
        self.ended = date.today().isoformat()
        if handoff:
            self.handoff = handoff
        if not outcome and self.handoff:
            outcome = "handoff written"
        if outcome:
            self.outcome = outcome
        self.session_md.write_text(self._render(), encoding="utf-8")
        self._consolidate_session_for_archive()
        if self.git.is_dirty():
            try:
                self.git.commit(self._commit_paths(), "close")
            except (GitConnectError, ValueError):
                pass
        for path in running_chats:
            self.save_chat(path)
        archived = self._archive_session_folder()
        self._commit_closed_archive(archived)
        self._commit_active_session_removal()
        SessionLogs(Path(self.path or self.git.root)).clear_active_session()
        if not self.sync_only_close:
            self._land_on_default_branch()
            self._remove_session_worktree_if_clean()
        if archived is not None:
            return archived / "session.md"
        return self.session_md

    def close_session(self, outcome: str = "", handoff: str = "handoff.md") -> str:
        md = self.close(outcome=outcome, handoff=handoff)
        return str(md.resolve())

    @agent_tool
    def start_work_session(
        self,
        tools: list[Any] | None = None,
        name: str = "",
        goal: str = "",
        fidelities: str = "",
        contexts: str = "",
        path: str = "",
        tool: Any | None = None,
        isolate: bool = True,
    ) -> WorkSession:
        """start_work_session — agent starts or resumes a named work session.

        Non-default session branches isolate in a sibling worktree named
        ``{abbrev}-{ticket}`` (or a short slug) next to the primary clone.
        Stay in the primary clone when the session branch is the default branch.
        That checkout gets its own ``.venv`` — rebuilt via ``setup.ps1`` when it is
        missing or was built for another machine or worktree.
        Pass ``isolate: false`` to keep session folders / turns / logs on the
        current checkout (no sibling worktree) — e.g. track work on main.

        When the session name ends in ``-{issue}``, ``session.md`` gets a
        ``## Tickets`` section with that issue and every linked sub-issue (parent
        plus children, or child plus parent and siblings).

        Do not call this from a /cli-agent parent. CliAgent opens the session,
        switches to that path, and binds doer/judge. Resume does not rewrite Start.
        """
        if tools:
            for item in tools:
                workspace = getattr(item, "workspace", None)
                if workspace is not None:
                    return workspace.open(
                        tool=item,
                        name=name,
                        goal=goal,
                        fidelities=fidelities,
                        contexts=contexts,
                        path=path,
                        isolate=isolate,
                    )
        if tool is not None:
            workspace = getattr(tool, "workspace", None)
            if workspace is not None:
                return workspace.open(
                    tool=tool,
                    name=name or self.name,
                    goal=goal,
                    fidelities=fidelities,
                    contexts=contexts,
                    path=path,
                    isolate=isolate,
                )
        self.open(
            name=name,
            goal=goal,
            fidelities=fidelities,
            contexts=contexts,
            path=path,
            isolate=isolate,
        )
        self.workspace.current_work_session = self
        return self

    def _finish_without_session(self, *, outcome: str = "") -> str:
        """No open session: commit via Turn, attach this chat, push."""
        git = self.git
        Turn(root=str(git.root)).turn(
            message=outcome or "finish without session",
            utility="finish-work-session",
        )

        prior_name = self.name
        if not prior_name:
            self.name = "default"
        try:
            for path in self._running_chat_paths():
                self.save_chat(path)
        finally:
            self.name = prior_name

        try:
            git.push()
        except GitConnectError:
            pass
        return "finished without work session"

    @agent_tool
    def finish_work_session(
        self,
        tools: list[Any] | None = None,
        outcome: str = "",
        handoff: str = "handoff.md",
    ) -> str:
        """finish_work_session — close the current work session.

        Before calling: in the session worktree run ``git status``. Delete only temps
        you know are ephemeral from this session (examples: ``Harness.install``
        output under ``.cursor/commands`` and ``.cursor/skills``, agent BDD run logs
        under ``.context/.agent_bdd_sessions/`` from spec runs, ``_req*.yaml`` scratch
        files). Use session context — do not delete durable generate, product files, or
        anything you cannot attribute to disposable temps. Never ask the user whether
        to delete the worktree.

        Then: treats the worktree as the unit of isolation, commits every modified, staged,
        deleted, and untracked file under the repository root, pushes, and merges onto main.
        Do not filter by scope paths, session artifacts, author, or which changes you recognize.
        Clear any stash (stash must never keep a worktree), and remove the sibling worktree when
        the tree is clean and pushed. If untracked or dirty files remain after the full-root commit,
        leave the worktree and report what blocked removal.

        When no work session is open (e.g. work landed on main without ``start_work_session``),
        skips session.md / worktree removal and still finishes the turn (commit dirty checkout),
        attaches this chat, and pushes.
        """
        if tools:
            for item in tools:
                workspace = getattr(item, "workspace", None)
                current = getattr(workspace, "current_work_session", None)
                if current is not None:
                    return current.close_session(outcome=outcome, handoff=handoff)
        if not self.name:
            parent = (
                self.workspace
                if isinstance(self.workspace, Workspace)
                else Workspace(str(self.path or "."))
            )
            default = parent.open_work_session(
                SessionModel.DEFAULT_SESSION,
                path=self.path or parent.path,
                isolate=False,
                git=self.git,
            )
            conv = getattr(self, "_conversation_id", None)
            if conv is not None:
                default._conversation_id = conv
            return default.close_session(outcome=outcome, handoff=handoff)
        return self.close_session(outcome=outcome, handoff=handoff)

    def cleanup(self) -> None:
        """Remove CliAgent temps; session logs are archived on close, not deleted."""
        agent = self.cli_agent
        if agent is not None:
            agent.cleanup()

    def _wipe_session_logs(self) -> None:
        """Remove events.log only — hook logs move to closed archive on close."""
        log_dir = self.log
        events = log_dir / "events.log"
        if events.is_file():
            events.unlink()

    def _session_artifact_paths(self) -> list[str]:
        return [str(self.session_md)]

    def _commit_paths(self) -> list[str]:
        """Commit the complete worktree; the worktree is the isolation boundary."""
        return [str(self.git.root)]

    def append_trail(self, call: ToolCall) -> None:
        self.trail.append(call)
        log_dir = self.log
        log_dir.mkdir(parents=True, exist_ok=True)
        ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
        line = (
            f"{ts} toolset={call.toolset} name={call.name} ok={call.ok} "
            f"summary={call.summary}"
        )
        if call.role:
            line += f" role={call.role}"
        if call.error:
            line += f" error={call.error}"
        with (log_dir / "events.log").open("a", encoding="utf-8") as handle:
            handle.write(line + "\n")
        if self.open_turn is not None:
            self.open_turn.tool_calls.append(call)

    def read_context_index(self) -> str:
        path = ContextIndex.context_index_path(self.workspace_root)
        if not path.is_file():
            self._context_index = None
            return f"missing: {path.as_posix()} (no roots recorded yet)"
        text = path.read_text(encoding="utf-8")
        self._context_index = text
        return text

    def record_context_root(self, root: str = "", note: str = "") -> str:
        key = getattr(self, "context_index_key", "") or ""
        if not key:
            return "skipped: this toolset has no context_index_key"
        working = root if root else self.path
        glob = ContextIndex.path_to_root_glob(self.workspace_root, working)
        path = ContextIndex.upsert_entry(self.workspace_root, key, glob, note=note)
        if path.is_file():
            self._context_index = path.read_text(encoding="utf-8")
        return str(path.resolve())

    def _render(self) -> str:
        lines = [
            f"# Session: {self.name}",
            "",
            "## Start",
            "",
            f"- **date:** {self.started}",
            f"- **path:** {self.path}",
            f"- **goal:** {self.goal or '(unset)'}",
            f"- **fidelities:** {self.fidelities or '(unset)'}",
            f"- **contexts:** {self.contexts or '(unset)'}",
            "",
        ]
        if self.body:
            lines.append(self.body.strip("\n"))
            lines.append("")
        if self.ended or self.outcome or self.handoff:
            lines.extend(
                [
                    "## End",
                    "",
                    f"- **ended:** {self.ended or '(unset)'}",
                    f"- **outcome:** {self.outcome or '(unset)'}",
                    f"- **handoff:** {self.handoff or '(unset)'}",
                    "",
                ]
            )
        return "\n".join(lines)

    @classmethod
    def _extract_body(cls, lines: list[str], end_idx: int | None) -> str:
        scope_end = end_idx if end_idx is not None else len(lines)
        last_start_field_idx = -1
        for i in range(scope_end):
            stripped = lines[i].strip()
            if not stripped.startswith("- **") or ":**" not in stripped:
                continue
            key = stripped.partition(":**")[0].removeprefix("- **").strip()
            if key in cls._START_FIELD_KEYS:
                last_start_field_idx = i
        body_start = last_start_field_idx + 1
        if body_start < scope_end and not lines[body_start].strip():
            body_start += 1
        return "\n".join(lines[body_start:scope_end]).strip("\n")

    @classmethod
    def _parse(cls, text: str, *, path: str, name: str) -> WorkSession:
        lines = text.splitlines()
        end_idx = next(
            (i for i, line in enumerate(lines) if line.strip() == cls._END_HEADING),
            None,
        )
        fields: dict[str, str] = {}
        for line in lines:
            stripped = line.strip()
            if not stripped.startswith("- **") or ":**" not in stripped:
                continue
            key, _, value = stripped.partition(":**")
            key = key.removeprefix("- **").strip()
            value = value.strip()
            if value.startswith("(") and value.endswith(")"):
                value = ""
            fields[key] = value
        body = cls._extract_body(lines, end_idx)
        parent = Workspace(path)
        return cls(
            parent,
            name,
            path=cls._normalize_session_path(fields.get("path") or path, path),
            goal=fields.get("goal", ""),
            fidelities=fields.get("fidelities", ""),
            contexts=fields.get("contexts", ""),
            started=fields.get("date", "") or date.today().isoformat(),
            ended=fields.get("ended", ""),
            outcome=fields.get("outcome", ""),
            handoff=fields.get("handoff", ""),
            body=body,
            workspace_root=path,
        )

class WorkSessionGuidance(PracticeGuidance):
    """Work guidelines file for a work session."""

    # rules section is a WorkSessionRulesCollection

    def __init__(self, work_session: WorkSession) -> None:
        self._work_session = work_session
        self.module_dir = work_session.folder

    def _guidelines_path(self) -> Path:
        return self._work_session.folder / "work-guidelines.md"

    @property
    def path(self) -> Path:
        return self._guidelines_path()

    @markdownCollection("work-guidelines")
    def rules(self) -> WorkSessionRulesCollection:
        """Work session rules from work-guidelines.md."""

class WorkSessionRulesCollection(RulesCollection):
    """Session rules: add, band, and inject by guidance and fidelity."""

    # changing inclusion, exclude, or detail leaves rules on the collection
    # the next inject_rules uses the new settings

    def __init__(
        self,
        entries: dict[str, Rule | RulesCollection] | None = None,
        applies_to: Any = None,
        parent: Any = None,
    ) -> None:
        super().__init__(entries, applies_to=applies_to, parent=parent)
        self.priority_inclusion = 1
        self.relevant_inclusion = 2
        self.context_inclusion = 3
        self.exclude = 5
        self.priority_detail = "examples"
        self.relevant_detail = "examples"
        self.context_detail = "slug"

    @classmethod
    def from_markdown(
        cls,
        text: str,
        fidelity: str | None = None,
        parent: Any = None,
    ) -> WorkSessionRulesCollection:
        applies_to = AppliesTo.from_markdown(text)
        entries: dict[str, Rule | RulesCollection] = {}
        current: WorkSessionRule | None = None
        for raw in AppliesTo.strip_fence(text).splitlines():
            stripped = raw.strip()
            if re.match(r"^[-*]\s+", stripped):
                rule = WorkSessionRule.from_bullet(stripped, fidelity=fidelity)
                entries[rule.slug] = rule
                current = rule
                continue
            if current is not None:
                current.apply_field(raw)
        collection = cls(entries, applies_to=applies_to, parent=parent)
        collection.markdown = text
        return collection

    def formatted(self) -> str:
        lines = ["#### Rules", ""]
        for rule in self:
            if isinstance(rule, WorkSessionRule):
                lines.extend(rule.to_markdown().splitlines())
            else:
                lines.append(f"- **{rule.slug}** — {rule.body}")
            lines.append("")
        return "\n".join(lines).rstrip() + "\n"

    def add(self, work_session_rule: WorkSessionRule) -> WorkSessionRule:
        # no matching base rule → insert new WorkSessionRule
        # matching base rule → add the example, star += 1, move up when highest star
        # guidance and fidelity may both be set, guidance only (practice-wide), or neither (global)
        # -> self._matching_work_session_rule
        # -> self._matching_practice_rule
        # -> self._place_by_star
        matching = self._matching_work_session_rule(work_session_rule)
        if matching is not None:
            for example in work_session_rule.examples:
                matching.examples.add(example)
            matching.star += 1
            matching.last_fail = 1
            self._place_by_star(matching)
            self._write()
            return matching
        self._apply_practice_rule(work_session_rule)
        if work_session_rule.star == 0:
            work_session_rule.star = 1
        work_session_rule.last_fail = 1
        self.entries[work_session_rule.slug] = work_session_rule
        self._place_by_star(work_session_rule)
        self._write()
        return work_session_rule

    def _apply_practice_rule(self, work_session_rule: WorkSessionRule) -> None:
        practice_rule = self._matching_practice_rule(work_session_rule)
        if practice_rule is None:
            return
        if not work_session_rule.slug:
            work_session_rule.slug = practice_rule.slug
        if not work_session_rule.body:
            work_session_rule.body = practice_rule.body

    def _matching_work_session_rule(
        self, work_session_rule: WorkSessionRule
    ) -> WorkSessionRule | None:
        found = self.entries.get(work_session_rule.slug)
        if isinstance(found, WorkSessionRule):
            return found
        return None

    def _matching_practice_rule(self, work_session_rule: WorkSessionRule) -> Rule | None:
        # -> practiceGuidance.rules
        if not work_session_rule.slug:
            return None
        practice = self._practice_guidance(work_session_rule)
        if practice is None:
            return None
        for bag in self._practice_rule_bags(practice):
            found = bag.entries.get(work_session_rule.slug)
            if isinstance(found, Rule):
                return found
        return None

    def _practice_rule_bags(self, practice: PracticeGuidance) -> list[RulesCollection]:
        bags = [practice.rules]
        fidelities = getattr(practice, "fidelities", None)
        if fidelities is None:
            return bags
        for child in fidelities:
            child_rules = getattr(child, "rules", None)
            if isinstance(child_rules, RulesCollection):
                bags.append(child_rules)
        return bags

    def _practice_guidance(self, work_session_rule: WorkSessionRule) -> PracticeGuidance | None:
        name = work_session_rule.guidance
        if not name:
            return None
        from harness.agent_tools.agent_tools import AgentToolSet

        module = name.replace("-", "_")
        class_name = "".join(part.title() for part in module.split("_"))
        return AgentToolSet.instantiate(
            f"practices.{module}.{module}:{class_name}"
        )

    def _place_by_star(self, work_session_rule: WorkSessionRule) -> None:
        ranked = sorted(
            (
                rule
                for rule in self.entries.values()
                if isinstance(rule, WorkSessionRule)
            ),
            key=lambda rule: rule.star,
            reverse=True,
        )
        self.entries = {rule.slug: rule for rule in ranked}

    def inject_rules(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        # practice rules being injected this turn
        # called from HookServer after handlers merge
        # -> self._matching_rules
        # -> self._merge_injected
        # -> self._band
        # -> self._render
        # -> self._write_last_chat_injected
        matching = self._matching_rules(payload)
        injected = ((payload or {}).get("additional_context") or "").strip()
        if injected:
            body = self._merge_injected(injected, matching)
        else:
            body = "\n\n".join(
                self._render(rule, self._detail_for(rule)) for rule in matching
            )
        self._write_last_chat_injected(body)
        return {"additional_context": body}

    def _write_last_chat_injected(self, body: str) -> None:
        destination = self._last_chat_injected_path()
        if destination is None:
            return
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(body, encoding="utf-8")

    def _last_chat_injected_path(self) -> Path | None:
        path = getattr(self.parent, "path", None)
        if path is None:
            return None
        return Path(path).parent / "last-chat-injected-rules.md"

    def _merge_injected(
        self, injected: str, matching: list[WorkSessionRule]
    ) -> str:
        overwrite_slugs = {rule.slug for rule in matching}
        parts = [
            self._render(rule, self._detail_for(rule)) for rule in matching
        ]
        remaining = self._without_slugs(injected, overwrite_slugs)
        if remaining:
            parts.append(remaining)
        return "\n\n".join(part for part in parts if part)

    def _without_slugs(self, injected: str, slugs: set[str]) -> str:
        lines: list[str] = []
        skip_indent = False
        for line in injected.splitlines():
            stripped = line.strip()
            if re.match(r"^[-*]\s+", stripped):
                skip_indent = Rule.from_bullet(stripped).slug in slugs
                if skip_indent:
                    continue
            elif skip_indent and line[:1].isspace():
                continue
            else:
                skip_indent = False
            if not skip_indent:
                lines.append(line)
        return "\n".join(lines).strip()

    def _matching_rules(
        self, payload: dict[str, Any] | None = None
    ) -> list[WorkSessionRule]:
        # match when rule.guidance is empty or equals that generate's guidance
        # and rule.fidelity is empty or equals that generate's fidelity
        # last fail at exclude turns ago or older → not injected
        # same match for specific, practice-wide, and global
        data = payload or {}
        guidances = self._names(
            data.get("injected_practices") or data.get("guidance")
        )
        fidelities = self._names(
            data.get("injected_fidelities") or data.get("fidelity")
        )
        injected_slugs = self._injected_slugs(
            (data.get("additional_context") or "").strip()
        )
        matched = [
            rule
            for rule in self
            if isinstance(rule, WorkSessionRule)
            and rule.last_fail < self.exclude
            and self._in_injected_set(rule, injected_slugs, guidances, fidelities)
        ]
        matched.sort(key=lambda rule: rule.star, reverse=True)
        return matched

    def _in_injected_set(
        self,
        rule: WorkSessionRule,
        injected_slugs: set[str],
        guidances: list[str],
        fidelities: list[str],
    ) -> bool:
        if injected_slugs and rule.slug in injected_slugs:
            return self._tags_match(rule, guidances, fidelities) or not guidances
        return self._tags_match(rule, guidances, fidelities)

    def _injected_slugs(self, injected: str) -> set[str]:
        slugs: set[str] = set()
        for line in injected.splitlines():
            stripped = line.strip()
            if re.match(r"^[-*]\s+", stripped):
                slugs.add(Rule.from_bullet(stripped).slug)
        return slugs

    def _names(self, value: Any) -> list[str]:
        if value is None or value == "":
            return []
        if isinstance(value, str):
            return [value]
        return [str(item) for item in value if item]

    def _tags_match(
        self,
        rule: WorkSessionRule,
        guidances: list[str] | str | None,
        fidelities: list[str] | str | None,
    ) -> bool:
        names = self._names(guidances)
        fidelity_names = self._names(fidelities)
        guidance_ok = not rule.guidance or rule.guidance in names
        fidelity_ok = not rule.fidelity or rule.fidelity in fidelity_names
        return guidance_ok and fidelity_ok

    def _band(self, work_session_rule: WorkSessionRule) -> str:
        # priority | relevant | context from inclusion counts and turn age
        age = work_session_rule.last_fail
        if age <= self.priority_inclusion:
            return "priority"
        if age <= self.relevant_inclusion:
            return "relevant"
        if age <= self.context_inclusion:
            return "context"
        return "excluded"

    def _detail_for(self, work_session_rule: WorkSessionRule) -> str:
        band = self._band(work_session_rule)
        return {
            "priority": self.priority_detail,
            "relevant": self.relevant_detail,
            "context": self.context_detail,
        }.get(band, "slug")

    def _render(self, work_session_rule: WorkSessionRule, detail: str) -> str:
        # examples | body | slug
        if detail == "examples":
            parts = [work_session_rule.body]
            for example in work_session_rule.examples:
                parts.append(example.mistake)
                parts.append(example.correction)
            return "\n".join(part for part in parts if part)
        if detail == "body":
            return work_session_rule.body
        return f"{work_session_rule.slug} ★{work_session_rule.star}"

    def _write(self) -> None:
        text = self.formatted()
        self.markdown = text
        path = getattr(self.parent, "path", None)
        if path is None:
            return
        destination = Path(path)
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(text, encoding="utf-8")

class WorkSessionRule(Rule):
    """A session rule tagged for a practice generate, with star and examples."""

    # empty guidance and empty fidelity → global
    # guidance set, fidelity empty → practice-wide

    def __init__(
        self,
        slug: str = "",
        body: str = "",
        guidance: str | None = None,
        fidelity: str | None = None,
        star: int = 0,
        examples: list[Example] | Examples | None = None,
        last_fail: int = 0,
    ) -> None:
        super().__init__(slug=slug, body=body, fidelity=fidelity)
        self._guidance = guidance
        self.star = star
        self.examples = (
            examples if isinstance(examples, Examples) else Examples(examples)
        )
        self.last_fail = last_fail

    @property
    def guidance(self) -> str | None:
        return self._guidance

    @guidance.setter
    def guidance(self, value: str | None) -> None:
        self._guidance = value

    @classmethod
    def from_bullet(cls, text: str, fidelity: str | None = None) -> WorkSessionRule:
        parsed = Rule.from_bullet(text, fidelity=fidelity)
        return cls(slug=parsed.slug, body=parsed.body, fidelity=parsed.fidelity)

    @classmethod
    def from_markdown(cls, text: str, fidelity: str | None = None) -> WorkSessionRule:
        lines = text.splitlines()
        rule = cls.from_bullet(lines[0] if lines else "", fidelity=fidelity)
        for line in lines[1:]:
            rule.apply_field(line)
        return rule

    def apply_field(self, line: str) -> None:
        field = self._field(line)
        if field is None:
            return
        name, value = field
        if name == "star":
            self.star = int(value or "0")
        elif name == "guidance":
            self.guidance = value or None
        elif name == "fidelity":
            self.fidelity = value or None
        elif name == "mistake":
            self.examples.add(Example(mistake=value))
        elif name == "correction":
            if self.examples:
                self.examples[-1].correction = value
            else:
                self.examples.add(Example(correction=value))
        elif name == "last-fail":
            self.last_fail = int(value or "0")

    @staticmethod
    def _field(line: str) -> tuple[str, str] | None:
        if not line[:1].isspace() or ":" not in line:
            return None
        name, value = line.strip().split(":", 1)
        name = name.strip()
        if name not in (
            "star",
            "guidance",
            "fidelity",
            "mistake",
            "correction",
            "last-fail",
        ):
            return None
        return name, value.strip()

    def to_markdown(self) -> str:
        lines = [f"- `{self.slug}` — {self.body}"]
        if self.star:
            lines.append(f"  star: {self.star}")
        if self.guidance:
            lines.append(f"  guidance: {self.guidance}")
        if self.fidelity:
            lines.append(f"  fidelity: {self.fidelity}")
        if self.last_fail:
            lines.append(f"  last-fail: {self.last_fail}")
        for example in self.examples:
            if example.mistake:
                lines.append(f"  mistake: {example.mistake}")
            if example.correction:
                lines.append(f"  correction: {example.correction}")
        return "\n".join(lines)

class Example(StoryNode):
    _semantic_type_name = "Example"

    def __init__(
        self,
        name: str,
        sequential_order: int,
        fields: Dict[str, str] | None = None,
        scope: str = "scenario",
    ) -> None:
        super().__init__(name=name, sequential_order=sequential_order)
        self.fields: Dict[str, str] = dict(fields) if fields is not None else {}
        self.scope = scope

    def update_self(self, source: "Example") -> None:
        self.name = source.name
        self.sequential_order = source.sequential_order
        self.fields = dict(source.fields)
        self.scope = source.scope

    def child_collections(self, source: "Example") -> List[ChildCollectionPair]:
        return []

    def value_for(self, field_name: str) -> str:
        return self.fields.get(field_name, "")

    def matches_export(self, export_name: str) -> bool:
        export_lower = (export_name or "").lower()
        name_lower = self.name.lower()
        return export_lower in name_lower or name_lower in export_lower

class Examples:
    """Examples on a work session rule — each entry is a mistake and a correction."""

