class Repo:
    """Local git clone with optional GitHub project + tickets."""

    NOTES_REF = "refs/notes/eval-mistakes"

    def __init__(
        self,
        root: str | Path,
        *,
        memory: bool = False,
        owner: str = "",
        repo_name: str = "",
    ) -> None:
        self.root = Path(root).resolve()
        self.default_branch = "main"
        self._memory = memory
        self._owner = owner
        self._repo_name = repo_name
        self._project: Project | None = None
        self._tickets: dict[int, Ticket] = {}
        self._ticket_project_state: dict[int, str] = {}
        self._ticket_project_theme: dict[int, str] = {}
        self._ticket_project_fields: dict[int, dict[str, str]] = {}
        self._ticket_children: dict[int, list[int]] = {}
        self._ticket_parents: dict[int, int] = {}
        self._ticket_comments: dict[int, list[str]] = {}
        self._closed_tickets: set[int] = set()
        self._archived_project_tickets: set[int] = set()
        self._annotated_tag_target = "HEAD"
        if memory:
            self._init_memory_state()

    @property
    def in_memory(self) -> bool:
        return self._memory

    @property
    def tickets(self) -> dict[int, Ticket]:
        return dict(self._tickets)

    def has_ticket(self, number: int) -> bool:
        return number in self._tickets

    def mark_closed(self, number: int) -> None:
        self._closed_tickets.add(number)

    def find_root(self) -> Path | None:
        current = self.root
        if current.is_file():
            current = current.parent
        for candidate in (current, *current.parents):
            if (candidate / ".git").exists():
                return candidate
        return None

    @classmethod
    def open(cls, start: str | Path) -> Repo:
        root = cls(start).find_root()
        if root is None:
            raise GitConnectError(f"not a git clone: {start!r}")
        return cls(root)

    @classmethod
    def memory(cls, root: str | Path = ".", *, owner: str = "demo-org", repo_name: str = "demo-repo") -> Repo:
        return cls(root, memory=True, owner=owner, repo_name=repo_name)

    @classmethod
    def git(cls, root: str | Path, *args: str) -> str:
        found = shutil.which("git")
        if not found:
            for candidate in (
                Path(r"C:\Program Files\Git\cmd\git.exe"),
                Path(r"C:\Program Files\Git\bin\git.exe"),
            ):
                if candidate.is_file():
                    found = str(candidate)
                    break
        if not found:
            raise GitConnectError("Cannot connect git: `git` is not available.")
        try:
            completed = subprocess.run(
                [found, "-c", "core.longpaths=true", "-C", str(root), *args],
                capture_output=True,
                text=True,
                encoding="utf-8",
                check=False,
            )
        except OSError as exc:
            raise GitConnectError(f"Cannot connect git: {exc}.") from exc
        if completed.returncode != 0:
            err = (completed.stderr or completed.stdout or "").strip()
            raise GitConnectError(
                f"Cannot connect git: git {' '.join(args)} failed in {root}: "
                f"{err}."
            )
        return (completed.stdout or "").strip()

    @classmethod
    def gh(
        cls,
        *args: str,
        cwd: str | Path | None = None,
        stdin: str | None = None,
    ) -> str:
        found = shutil.which("gh")
        if not found:
            for candidate in (
                Path(r"C:\Program Files\GitHub CLI\gh.exe"),
                Path.home() / "AppData" / "Local" / "GitHub CLI" / "gh.exe",
            ):
                if candidate.is_file():
                    found = str(candidate)
                    break
        if not found:
            raise GhConnectError("Cannot connect gh: `gh` is not available.")
        try:
            completed = subprocess.run(
                [found, *args],
                capture_output=True,
                text=True,
                encoding="utf-8",
                check=False,
                cwd=str(cwd) if cwd is not None else None,
                input=stdin,
            )
        except OSError as exc:
            raise GhConnectError(f"Cannot connect gh: {exc}.") from exc
        if completed.returncode != 0:
            err = (completed.stderr or completed.stdout or "").strip()
            shown = " ".join(a for a in args if a != stdin)
            raise GhConnectError(
                f"Cannot connect gh: gh {shown} failed: {err}."
            )
        return (completed.stdout or "").strip()

    def run_gh(self, *args: str, stdin: str | None = None) -> str:
        return type(self).gh(*args, cwd=self.root, stdin=stdin)

    def _git(self, *args: str) -> str:
        return type(self).git(self.root, *args)

    def _gh(self, *args: str, stdin: str | None = None) -> str:
        return self.run_gh(*args, stdin=stdin)

    def _init_memory_state(self) -> None:
        self._branch_names: set[str] = {"main"}
        self._branch = "main"
        self._commit = "sha-init"
        self._commits: list[tuple[list[str], str]] = []
        self._pushes: list[str] = []
        self._dirty = False
        self._notes: dict[str, dict[str, str]] = {}
        self._project_links: list[tuple[str, int, str]] = []
        self._org_issue_types: list[dict[str, str]] = []
        self._worktrees: list[Worktree] = [Worktree(self.root, "main")]
        self._fetches: list[str] = []
        self._pulls: list[str] = []
        self._stash = False
        self._annotated_tags: dict[str, str] = {}
        self._notes_by_ref: dict[tuple[str, str], dict[str, str]] = {}

    @property
    def project(self) -> Project | None:
        return self._project

    def attach_project(self, owner: str, number: int) -> Project:
        self._project = Project(self, owner, number)
        self._project.link_repository()
        self._project.refresh_states()
        return self._project

    @property
    def branch(self) -> Branch:
        return Branch(self, self.current_branch)

    def branch_named(self, name: str) -> Branch:
        return Branch(self, name)

    def cli_agent_tag_name(self, branch: str) -> str:
        slug = (branch or "").strip() or "HEAD"
        return f"cli-agent/{slug}"

    def read_cli_agent_tag(self, branch: str) -> CliAgentBinding:
        return CliAgentBinding.from_message(
            self.read_annotated_tag(self.cli_agent_tag_name(branch))
        )

    def write_annotated_tag(self, name: str, message: str) -> None:
        name = (name or "").strip()
        if not name:
            raise ValueError("annotated tag requires a name")
        if self._memory:
            self._annotated_tags[name] = message
            return
        self._git("tag", "-f", "-a", name, "-m", message, self._annotated_tag_target)

    def read_annotated_tag(self, name: str) -> str:
        name = (name or "").strip()
        if not name:
            return ""
        if self._memory:
            return self._annotated_tags.get(name, "")
        try:
            return self._git("tag", "-l", "--format=%(contents)", name)
        except GitConnectError:
            return ""

    def list_annotated_tags(self, prefix: str = "") -> dict[str, str]:
        prefix = prefix or ""
        if self._memory:
            return {
                name: text
                for name, text in self._annotated_tags.items()
                if name.startswith(prefix)
            }
        try:
            listing = self._git("tag", "-l", f"{prefix}*") if prefix else self._git("tag", "-l")
        except GitConnectError:
            return {}
        return {
            name: self.read_annotated_tag(name)
            for name in listing.splitlines()
            if name.strip()
        }

    @property
    def branch(self) -> str:
        return self.current_branch

    @branch.setter
    def branch(self, name: str) -> None:
        self.current_branch = name

    @property
    def current_branch(self) -> str:
        if self._memory:
            return self._branch
        return self._git("rev-parse", "--abbrev-ref", "HEAD")

    @current_branch.setter
    def current_branch(self, name: str) -> None:
        if self.is_dirty() and name != self.current_branch:
            raise DirtyBranchSwitchError(self.current_branch, name)
        if self._memory:
            if name not in self._branch_names:
                raise GitConnectError(f"unknown branch {name}")
            self._branch = name
            return
        self._git( "checkout", name)

    @property
    def current_commit(self) -> str:
        if self._memory:
            return self._commit
        return self._git("rev-parse", "HEAD")

    def list_issue_types(self) -> list[dict[str, str]]:
        if self._memory:
            return [dict(item) for item in getattr(self, "_org_issue_types", [])]
        owner, _ = self.owner_repo()
        raw = self._gh("api", f"orgs/{owner}/issue-types")
        payload = json.loads(raw or "[]")
        return [dict(item) for item in payload] if isinstance(payload, list) else []

    def ensure_issue_type(
        self,
        name: str,
        *,
        description: str = "",
        color: str = "gray",
    ) -> str:
        wanted = (name or "").strip()
        if not wanted:
            return ""
        for item in self.list_issue_types():
            existing = str(item.get("name") or "").strip()
            if existing.lower() == wanted.lower():
                return existing
        record = {
            "name": wanted,
            "description": description,
            "color": color,
            "is_enabled": True,
        }
        if self._memory:
            types = getattr(self, "_org_issue_types", None)
            if types is None:
                self._org_issue_types = []
                types = self._org_issue_types
            types.append(record)
            return wanted
        owner, _ = self.owner_repo()
        self._gh(
            "api",
            "--method",
            "POST",
            f"orgs/{owner}/issue-types",
            "--input",
            "-",
            stdin=json.dumps(
                {
                    "name": wanted,
                    "is_enabled": True,
                    "description": description or None,
                    "color": color,
                }
            ),
        )
        return wanted

    def owner_repo(self) -> tuple[str, str]:
        if self._memory:
            return self._owner, self._repo_name
        raw = self._gh("repo", "view", "--json", "nameWithOwner")
        payload = json.loads(raw or "{}")
        name = payload.get("nameWithOwner", "")
        if "/" not in name:
            raise GhConnectError(f"Cannot resolve owner/repo for {self.root}.")
        owner, repo = name.split("/", 1)
        return owner, repo

    def is_dirty(
        self, path: str | Path | None = None, *, untracked: bool = True
    ) -> bool:
        if self._memory:
            return self._dirty
        args = [
            "status",
            "--porcelain",
            "--untracked-files=normal" if untracked else "--untracked-files=no",
        ]
        if path is not None:
            args.extend(["--", self._rel(path)])
        return any(
            not self._is_runtime_log(line)
            for line in self._git(*args).splitlines()
            if line.strip()
        )

    @staticmethod
    def _is_runtime_log(porcelain_line: str) -> bool:
        raw = porcelain_line[3:] if len(porcelain_line) >= 3 else porcelain_line
        name = raw.split(" -> ")[-1].replace("\\", "/").strip()
        return Path(name).name == "events.log"

    def mark_dirty(self, dirty: bool = True) -> None:
        if not self._memory:
            raise RuntimeError("mark_dirty is only supported on Repo.memory()")
        self._dirty = dirty

    def create_branch(self, name: str) -> None:
        if self._memory:
            self._branch_names.add(name)
            return
        self._git("branch", name)

    def checkout_or_create(self, name: str) -> str:
        if self.current_branch == name:
            return name
        if self.is_dirty():
            raise DirtyBranchSwitchError(self.current_branch, name)
        if self._memory:
            self._branch_names.add(name)
            self._branch = name
            return name
        existing = self._git( "branch", "--list", name)
        if existing:
            self._git( "checkout", name)
        else:
            self._git( "checkout", "-b", name)
        return name

    def commit(
        self, paths: list[str], message: str, *, untracked: bool = False
    ) -> str:
        if not paths:
            raise ValueError("commit requires at least one path")
        if self._memory:
            self._commits.append((list(paths), message))
            self._commit = f"commit-{len(self._commits)}"
            self._dirty = False
            return self._commit
        merge_in_progress = (self.root / ".git" / "MERGE_HEAD").is_file()
        if merge_in_progress:
            add_flag = "-A" if untracked else "-u"
            self._git("add", add_flag)
            staged = self._git("diff", "--cached", "--name-only")
            if not staged:
                return self.current_commit
            self._git("commit", "-m", message)
            return self.current_commit
        rels = [self._rel(path) for path in paths]
        add_flag = "-A" if untracked else "-u"
        self._git("add", add_flag, "--", *rels)
        staged = self._git("diff", "--cached", "--name-only", "--", *rels)
        if not staged:
            return self.current_commit
        self._git("commit", "-m", message, "--", *rels)
        return self.current_commit

    def push(self) -> None:
        if self._memory:
            self._pushes.append(self.current_branch)
            return
        self._git( "push", "-u", "origin", self.current_branch)

    def has_unpushed_commits(self) -> bool:
        if self._memory:
            return False
        try:
            count = self._git("rev-list", "@{upstream}..HEAD", "--count").strip()
            return int(count or "0") > 0
        except GitConnectError:
            return False

    def list_worktrees(self) -> list[Worktree]:
        if self._memory:
            return list(self._worktrees)
        trees: list[Worktree] = []
        path = ""
        branch = ""
        for line in self._git("worktree", "list", "--porcelain").splitlines():
            path, branch, trees = self._accumulate_worktree_line(
                line, path, branch, trees
            )
        return self._flush_worktree(
            Worktree(Path(path), branch) if path else None, trees
        )

    def _accumulate_worktree_line(
        self,
        line: str,
        path: str,
        branch: str,
        trees: list[Worktree],
    ) -> tuple[str, str, list[Worktree]]:
        if line.startswith("worktree "):
            return (
                line[len("worktree ") :],
                "",
                self._flush_worktree(
                    Worktree(Path(path), branch) if path else None, trees
                ),
            )
        if line.startswith("branch "):
            return path, self._branch_from_porcelain(line), trees
        if line == "":
            return (
                "",
                "",
                self._flush_worktree(
                    Worktree(Path(path), branch) if path else None, trees
                ),
            )
        return path, branch, trees

    def _branch_from_porcelain(self, line: str) -> str:
        ref = line[len("branch ") :]
        if ref.startswith("refs/heads/"):
            return ref[len("refs/heads/") :]
        return ref

    def _flush_worktree(
        self, tree: Worktree | None, trees: list[Worktree]
    ) -> list[Worktree]:
        if tree is None:
            return trees
        return trees + [tree]

    def worktree_for(self, branch: str) -> Worktree | None:
        wanted = (branch or "").strip()
        for tree in self.list_worktrees():
            if tree.branch == wanted:
                return tree
        return None

    def add_worktree(self, path: str | Path, branch: str) -> Path:
        dest = Path(path)
        existing = self.worktree_for(branch)
        if existing is not None:
            return existing.path
        if self._memory:
            self._branch_names.add(branch)
            self._worktrees.append(Worktree(dest, branch))
            return dest
        dest.parent.mkdir(parents=True, exist_ok=True)
        if self._ref_exists(f"refs/heads/{branch}"):
            self._git("worktree", "add", str(dest), branch)
        else:
            start = self._worktree_start_point()
            args = ["worktree", "add", "-b", branch, str(dest)]
            if start:
                args.append(start)
            self._git(*args)
        return dest.resolve()

    def remove_worktree(self, path: str | Path) -> None:
        dest = Path(path)
        if self._memory:
            self._worktrees = [tree for tree in self._worktrees if tree.path != dest]
            return
        try:
            self._git("worktree", "remove", "--force", str(dest))
        except GitConnectError as exc:
            logger.info("worktree remove failed; forcing directory delete: %s", exc)
            self._force_remove_directory_windows(dest)
        if dest.exists():
            shutil.rmtree(dest, ignore_errors=True)
        if dest.exists():
            self._force_remove_directory_windows(dest)
        if dest.exists():
            return
        try:
            self._git("worktree", "prune")
        except GitConnectError as exc:
            logger.info("worktree prune failed: %s", exc)

    def _force_remove_directory_windows(self, path: Path) -> bool:
        """Last resort when git/shutil cannot delete a locked checkout (Windows only)."""
        if os.name != "nt":
            return False
        target = path.resolve()
        if not target.exists():
            return True
        user = os.environ.get("USERNAME", "").strip()
        if not user:
            return False
        self._take_windows_ownership(target, user)
        self._rmtree_logged(target)
        if target.exists():
            self._powershell_remove_item(target)
        return not target.exists()

    def _take_windows_ownership(self, target: Path, user: str) -> None:
        for args in (
            ("takeown", "/f", str(target), "/r", "/d", "y"),
            ("icacls", str(target), "/grant", f"{user}:(F)", "/t"),
        ):
            try:
                subprocess.run(list(args), capture_output=True, check=False)
            except OSError as exc:
                logger.info("windows ownership command failed: %s", exc)

    def _rmtree_logged(self, target: Path) -> None:
        try:
            shutil.rmtree(target, ignore_errors=True)
        except OSError as exc:
            logger.info("rmtree failed for %s: %s", target, exc)

    def _powershell_remove_item(self, target: Path) -> None:
        try:
            subprocess.run(
                [
                    "powershell",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    (
                        f'Remove-Item -LiteralPath "{target}" '
                        "-Recurse -Force -ErrorAction SilentlyContinue"
                    ),
                ],
                capture_output=True,
                check=False,
            )
        except OSError as exc:
            logger.info("powershell Remove-Item failed for %s: %s", target, exc)

    def fetch(self) -> None:
        if self._memory:
            self._fetches.append("origin")
            return
        self._git("fetch", "origin")

    def pull(self) -> None:
        if self._memory:
            self._pulls.append(self.current_branch)
            return
        self._git("pull", "--ff-only")

    def fetch_pull(self) -> None:
        self.fetch()
        self.pull()

    def merge_from(self, other: str, message: str = "") -> str:
        """Merge *other* into the current branch without checking *other* out."""
        if not other or other == self.current_branch:
            return self.current_commit
        if self._memory:
            text = message or f"merge {other} into {self.current_branch}"
            self._commits.append(([], text))
            self._commit = f"merge-{other}-into-{self.current_branch}"
            return self._commit
        if message:
            self._git("merge", other, "-m", message)
        else:
            self._git("merge", other, "--no-edit")
        return self.current_commit

    def push_to(self, branch: str) -> None:
        if self._memory:
            self._pushes.append(branch)
            return
        self._git("push", "origin", f"HEAD:{branch}")

    def has_stash(self) -> bool:
        if self._memory:
            return self._stash
        return bool(self._git("stash", "list"))

    def clear_stash(self) -> None:
        """Drop every stash entry. Session close must not leave worktrees for stash."""
        if self._memory:
            self._stash = False
            return
        if not self.has_stash():
            return
        self._git("stash", "clear")

    def is_linked_worktree(self) -> bool:
        return (self.root / ".git").is_file()

    def primary_root(self) -> Path:
        if self._memory:
            return self.root
        common = Path(self._git("rev-parse", "--git-common-dir"))
        if not common.is_absolute():
            common = (self.root / common).resolve()
        else:
            common = common.resolve()
        return common.parent if common.name == ".git" else common

    def _ref_exists(self, ref: str) -> bool:
        try:
            self._git("show-ref", "--verify", "--quiet", ref)
            return True
        except GitConnectError:
            return False

    def _worktree_start_point(self) -> str:
        for candidate in (
            f"origin/{self.default_branch}",
            "origin/main",
            "origin/master",
        ):
            try:
                self._git("rev-parse", "--verify", candidate)
                return candidate
            except GitConnectError:
                continue
        return ""

    def merge_branch(self, source: str, into: str = "main", message: str = "") -> str:
        if self.is_dirty(untracked=False):
            raise DirtyBranchSwitchError(self.current_branch, into)
        if self._memory:
            if source not in self._branch_names:
                self._branch_names.add(source)
            self._branch = into
            text = message or f"merge {source} into {into}"
            self._commits.append(([], text))
            self._commit = f"merge-{source}-into-{into}"
            return self._commit
        target = self.worktree_for(into)
        merge_root = Path(target.path) if target is not None else Path(self.root)
        if target is None and self.current_branch != into:
            self._git("checkout", into)
            merge_root = Path(self.root)
        merge_git = type(self)
        if message:
            merge_git.git(merge_root, "merge", source, "-m", message)
        else:
            merge_git.git(merge_root, "merge", source, "--no-edit")
        return merge_git.git(merge_root, "rev-parse", "HEAD")

    def note(
        self,
        sha: str,
        payload: dict[str, str],
        *,
        ref: str | None = None,
    ) -> None:
        note_ref = ref or self.NOTES_REF
        if self._memory:
            self._notes[sha] = dict(payload)
            self._notes_by_ref[(note_ref, sha)] = dict(payload)
            return
        text = Commit.note_text(payload)
        self._git(
            "notes",
            f"--ref={note_ref}",
            "add",
            "-f",
            "-m",
            text,
            sha,
        )

    def read_notes(self, sha: str, *, ref: str | None = None) -> dict[str, str]:
        note_ref = ref or self.NOTES_REF
        if self._memory:
            keyed = self._notes_by_ref.get((note_ref, sha))
            if keyed is not None:
                return dict(keyed)
            if note_ref == self.NOTES_REF:
                return dict(self._notes.get(sha, {}))
            return {}
        try:
            raw = self._git("notes", f"--ref={note_ref}", "show", sha)
        except GitConnectError:
            return {}
        return Commit(sha="", message=raw).note_payload()

    def find_mistakes(
        self, entry_ids: list[str], *, ref: str | None = None
    ) -> list[dict[str, str]]:
        note_ref = ref or self.NOTES_REF
        wanted = set(entry_ids)
        if self._memory:
            return self._memory_mistakes(wanted)
        return self._listed_mistakes(note_ref, wanted)

    def _memory_mistakes(self, wanted: set[str]) -> list[dict[str, str]]:
        found: list[dict[str, str]] = []
        for sha, payload in self._notes.items():
            if payload.get("entry_id") in wanted:
                row = dict(payload)
                row.setdefault("introducing_commit", sha)
                found.append(row)
        return found

    def _listed_mistakes(
        self, note_ref: str, wanted: set[str]
    ) -> list[dict[str, str]]:
        found: list[dict[str, str]] = []
        listing = self._git("notes", f"--ref={note_ref}", "list")
        for line in listing.splitlines():
            parts = line.split()
            if len(parts) < 2:
                continue
            sha = parts[1]
            payload = self.read_notes(sha, ref=note_ref)
            if payload.get("entry_id") in wanted:
                payload.setdefault("introducing_commit", sha)
                found.append(payload)
        return found

    def ticket(self, ref: str) -> Ticket | None:
        if self.in_memory:
            return self._memory_ticket(ref)
        return self._github_ticket(ref)

    def _memory_ticket(self, ref: str) -> Ticket | None:
        number = Ticket.from_number(ref)
        ticket = self._tickets.get(number)
        if ticket is None:
            return None
        ticket.bind_repo(self)
        state_name = self._ticket_project_state.get(number)
        if state_name:
            ticket.state = TicketState(state_name)
        ticket.data["closed"] = "true" if number in self._closed_tickets else "false"
        ticket.sub_issue_numbers = list(self._ticket_children.get(number, []))
        ticket.parent_number = self._ticket_parents.get(number)
        return ticket

    def _github_ticket(self, ref: str) -> Ticket | None:
        number = Ticket.from_number(ref)
        try:
            raw = self.run_gh(
                "issue",
                "view",
                str(number),
                "--json",
                "number,title,body,url,state,parent,subIssues",
            )
        except GhConnectError as exc:
            message = str(exc).lower()
            if "could not resolve" in message or "not found" in message:
                return None
            raise
        payload = json.loads(raw or "{}")
        if not payload:
            return None
        return self._ticket_from_payload(payload)

    def create_ticket(self, title: str, body: str) -> Ticket:
        if self.in_memory:
            number = (max(self._tickets.keys(), default=0) + 1) if self._tickets else 1
            owner, repo_name = self.owner_repo()
            ticket = Ticket(
                number=number,
                title=title,
                body=body,
                url=f"https://github.com/{owner}/{repo_name}/issues/{number}",
            )
            ticket.bind_repo(self)
            self._tickets[number] = ticket
            return ticket
        raw = self.run_gh(
            "issue",
            "create",
            "--title",
            title,
            "--body-file",
            "-",
            stdin=body,
        )
        url = (raw or "").strip().splitlines()[-1].strip() if raw else ""
        if "/issues/" not in url:
            raise GhConnectError(f"Cannot parse issue URL from gh issue create: {raw!r}.")
        number = int(url.rstrip("/").rsplit("/", 1)[-1])
        ticket = self.ticket(str(number))
        if ticket is None:
            return self._ticket_from_payload(
                {"number": number, "title": title, "body": body, "url": url}
            )
        ticket.body = body
        ticket.title = title
        return ticket

    def workflow_commit_message(
        self,
        subject: str,
        issue_number: int,
        workflow_state: str,
        *,
        reviewed_by: str = "",
    ) -> str:
        owner, repo = self.owner_repo()
        trailers = {
            "GitHub-Issue": Ticket.github_ref(owner, repo, issue_number),
            "Workflow-State": workflow_state,
        }
        if reviewed_by.strip():
            trailers["Reviewed-By"] = reviewed_by.strip()
        return Commit.format(subject, trailers)

    def _ticket_from_payload(self, payload: dict[str, Any]) -> Ticket:
        number = int(payload["number"])
        parent_data = payload.get("parent")
        parent_number = (
            int(parent_data["number"])
            if isinstance(parent_data, dict) and parent_data.get("number")
            else None
        )
        sub_issues_data = payload.get("subIssues") or []
        if isinstance(sub_issues_data, dict):
            sub_issues_data = sub_issues_data.get("nodes") or []
        sub_numbers = [
            int(item["number"])
            for item in sub_issues_data
            if isinstance(item, dict) and item.get("number")
        ]
        ticket = Ticket(
            number=number,
            title=str(payload.get("title") or ""),
            body=str(payload.get("body") or ""),
            url=str(payload.get("url") or ""),
            parent_number=parent_number,
            sub_issue_numbers=sub_numbers,
        )
        ticket.bind_repo(self)
        self._tickets[number] = ticket
        return ticket

    def _last_commit_message(self) -> str:
        if self._memory:
            if not self._commits:
                return ""
            return self._commits[-1][1]
        return self._git("log", "-1", "--pretty=%B")

    def _rel(self, path: str | Path) -> str:
        resolved = Path(path).resolve()
        try:
            return str(resolved.relative_to(self.root)).replace("\\", "/")
        except ValueError:
            return str(resolved).replace("\\", "/")

    # Legacy test surface (was NullGitRepo)
    @property
    def commits(self) -> list[tuple[list[str], str]]:
        if not self._memory:
            raise RuntimeError("commits is only available on Repo.memory()")
        return self._commits

    @property
    def pushes(self) -> list[str]:
        if not self._memory:
            raise RuntimeError("pushes is only available on Repo.memory()")
        return self._pushes

    @property
    def _branches(self) -> set[str]:
        if not self._memory:
            raise RuntimeError("_branches is only available on Repo.memory()")
        return self._branch_names

class HILCheck:
    """Human-in-the-loop check hanging on a Turn."""

    validation: str | None = None

class Plan:
    """Plan front-end to git, based on a reusable or newly named Workflow."""

    def __init__(self, seed: PlanSeed) -> None:
        self._attachments = seed.attachments
        self._name = seed.name
        self._workspace = seed.workspace
        self._workflow = seed.workflow
        self._workflow_name = seed.workflow_name
        self._turns: list[Turn] = []
        self._work_session: WorkSession | None = None

    @property
    def name(self) -> str:
        return self._name

    @property
    def workspace(self) -> Workspace | None:
        return self._workspace

    @property
    def workflow_name(self) -> str:
        return self._workflow_name

    @property
    def turns(self) -> list[Turn]:
        return list(self._turns)

    @property
    def work_session(self) -> WorkSession | None:
        return self._work_session

    @work_session.setter
    def work_session(self, session: WorkSession | None) -> None:
        self._work_session = session

    @property
    def attachments(self) -> TurnAttachments:
        return self._attachments

    @classmethod
    def create(cls, seed: PlanSeed) -> Plan:
        plan = cls(seed)
        cls._register_on_workspace(plan)
        return plan

    @classmethod
    def from_workflow(cls, seed: PlanSeed) -> Plan:
        """Build a Plan on a reusable Workflow; load prebaked Turns when named."""
        if not seed.name:
            seed = PlanSeed(
                workspace=seed.workspace,
                attachments=seed.attachments,
                name=seed.workflow_name,
                workflow=seed.workflow,
                workflow_name=seed.workflow_name,
            )
        plan = cls.create(seed)
        plan._load_prebaked_turns(seed.workflow_name)
        return plan

    @staticmethod
    def _register_on_workspace(plan: Plan) -> None:
        workspace = plan.workspace
        if workspace is None:
            return
        plans = getattr(workspace, "plans", None)
        if plans is None:
            workspace.plans = []  # type: ignore[attr-defined]
            plans = workspace.plans
        plans.append(plan)

    def add_turn(self, turn: Turn | None = None, **fields: Any) -> Turn:
        if turn is None:
            turn = Turn()
        for field_name, field_value in fields.items():
            setattr(turn, field_name, field_value)
        if not hasattr(turn, "state") or turn.state is None:  # type: ignore[attr-defined]
            turn.state = TicketState.backlog()  # type: ignore[attr-defined]
        if not hasattr(turn, "judge_checkpoint"):
            turn.judge_checkpoint = None  # type: ignore[attr-defined]
        if not hasattr(turn, "hil_check"):
            turn.hil_check = None  # type: ignore[attr-defined]
        self._turns.append(turn)
        return turn

    def _load_prebaked_turns(self, workflow_name: str) -> None:
        for template in _PREBAKED_WORKFLOWS.get(workflow_name, []):
            self.add_turn(
                action=template.action,
                fidelity=template.fidelity,
                format=template.format,
                context=template.context,
                tool_keys=list(template.tool_keys),
            )

class PlanExecution:
    """Runs a Plan: start, execute, judge record, advance, fix."""

    def __init__(self, plan: Plan) -> None:
        self._plan = plan

    def start(self) -> WorkSession:
        workspace = self._plan.workspace
        if workspace is None:
            raise RuntimeError("Plan.start requires a Workspace")
        session = workspace.open_work_session(
            name=self._plan.name or "plan",
            path=getattr(workspace, "path", ".") or ".",
        )
        self._plan.work_session = session
        turns = self._plan.turns
        if turns:
            first = turns[0]
            first.state = TicketState.in_progress()  # type: ignore[attr-defined]
            session.open_turn = first
        return session

    def execute_turn(self) -> Turn | None:
        turn = self._open_turn()
        if turn is None:
            return None
        if hasattr(turn, "perform_turn"):
            turn.perform_turn()
        if not getattr(turn, "result", ""):
            turn.result = turn.action or "executed"
        return turn

    def validate_with_human(self, validation: str) -> HILCheck | None:
        turn = self._open_turn()
        if turn is None:
            return None
        return self._plan.attachments.add_hil(turn, HILCheck(validation=validation))

    def evaluate_results(self, judge_result: str) -> JudgeCheckpoint | None:
        turn = self._open_turn()
        if turn is None:
            return None
        check = getattr(turn, "judge_checkpoint", None)
        if check is None:
            return None
        check.judge_result = judge_result
        return check

    def review_progress(self) -> ProgressView | None:
        turn = self._open_turn()
        if turn is None:
            return None
        hil = getattr(turn, "hil_check", None)
        judge = getattr(turn, "judge_checkpoint", None)
        return ProgressView(
            state=getattr(turn, "state", None),
            result=getattr(turn, "result", None),
            hil_validation=getattr(hil, "validation", None) if hil else None,
            judge_result=getattr(judge, "judge_result", None) if judge else None,
        )

    def advance_turn(self) -> Turn | None:
        session = self._plan.work_session
        turn = self._open_turn()
        if session is None or turn is None:
            return None
        turn.state = TicketState.done()  # type: ignore[attr-defined]
        turn.finish(
            prompt=getattr(turn, "prompt", ""),
            result=getattr(turn, "result", ""),
            context=getattr(turn, "context", ""),
        )
        return self._promote_next(session, turn)

    def fix_and_rerun(self, mistake: str, correction: str) -> Turn | None:
        turn = self._open_turn()
        if turn is None:
            return None
        if hasattr(turn, "record_mistake"):
            turn.record_mistake(mistake)
        if hasattr(turn, "record_correction"):
            turn.record_correction(correction)
        return self.execute_turn()

    def _open_turn(self) -> Turn | None:
        session = self._plan.work_session
        if session is None:
            return None
        return session.open_turn

    def _promote_next(self, session: WorkSession, current: Turn) -> Turn | None:
        turns = self._plan.turns
        idx = turns.index(current) if current in turns else -1
        nxt = turns[idx + 1] if 0 <= idx < len(turns) - 1 else None
        if nxt is not None:
            nxt.state = TicketState.in_progress()  # type: ignore[attr-defined]
            session.open_turn = nxt
        else:
            session.open_turn = None
        return nxt

class SmallWorkRunner:
    """Execute prebaked small-work Plan against themed issues one at a time.

    Thin context → Grill + HIL Grill interrupt (judge replies via hil_reply).
    Enough context → process issue, advance to next. Report when Done.
    """

    def __init__(
        self,
        workspace: str = ".",
        *,
        issues: list[ThemedIssue] | None = None,
        state_path: Path | None = None,
    ) -> None:
        self._workspace = (workspace or ".").strip() or "."
        self._fixture_issues = issues
        self._state_path = state_path or (
            Path(self._workspace) / ".context" / "small-work-run.json"
        )

    @staticmethod
    def parse_theme(context: str) -> str:
        text = (context or "").strip()
        if not text:
            return ""
        match = _THEME_RE.search(text)
        if match:
            return match.group("theme").strip()
        if text.startswith("theme:"):
            return text.split(":", 1)[1].strip()
        return text

    @staticmethod
    def enough_context(body: str) -> bool:
        text = (body or "").strip()
        if not text:
            return False
        lowered = text.lower()
        if any(marker in lowered for marker in _ENOUGH_MARKERS):
            return True
        return len(text) >= _MIN_ENOUGH_CHARS

    @staticmethod
    def grill_questions_for(issue: ThemedIssue) -> list[str]:
        return [
            f"What is the root cause for #{issue.number} ({issue.title})?",
            "What acceptance criteria prove the fix?",
            "Which module owns the change?",
        ]

    def state_path(self) -> Path:
        return self._state_path

    def load_state(self) -> SmallWorkState | None:
        path = self._state_path
        if not path.is_file():
            return None
        raw = json.loads(path.read_text(encoding="utf-8"))
        return SmallWorkState(**raw)

    def save_state(self, state: SmallWorkState) -> None:
        path = self._state_path
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(asdict(state), indent=2), encoding="utf-8")

    def clear_state(self) -> None:
        path = self._state_path
        if path.is_file():
            path.unlink()

    def list_themed_issues(self, theme: str) -> list[ThemedIssue]:
        if self._fixture_issues is not None:
            label = theme if theme.startswith("theme:") else f"theme:{theme}"
            bare = theme.removeprefix("theme:")
            return [
                issue
                for issue in self._fixture_issues
                if label in issue.labels
                or bare in issue.labels
                or f"theme:{bare}" in issue.labels
            ]
        return self._list_from_gh(theme)

    def _list_from_gh(self, theme: str) -> list[ThemedIssue]:
        label = theme if theme.startswith("theme:") else f"theme:{theme}"
        raw = Repo.gh(
            "issue",
            "list",
            "--label",
            label,
            "--state",
            "open",
            "--json",
            "number,title,body,labels",
            "--limit",
            "50",
            cwd=self._workspace,
        )
        rows = json.loads(raw or "[]")
        issues: list[ThemedIssue] = []
        for row in rows:
            labels = [
                str(item.get("name") or item)
                for item in (row.get("labels") or [])
            ]
            issues.append(
                ThemedIssue(
                    number=int(row["number"]),
                    title=str(row.get("title") or ""),
                    body=str(row.get("body") or ""),
                    labels=labels,
                )
            )
        return sorted(issues, key=lambda item: item.number)

    def run(
        self,
        theme: str,
        *,
        hil_reply: str = "",
        issue: str | int = "",
        plan_meta: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        theme_name = theme.removeprefix("theme:")
        state = self.load_state()
        if hil_reply.strip():
            if state is None or state.pending_hil is None:
                raise RuntimeError(
                    "hil_reply requires a pending HIL Grill interrupt "
                    "(judge replies; parent does not)"
                )
            return self._continue_with_hil(state, hil_reply, plan_meta=plan_meta)

        if state is not None and state.status == "hil_interrupt" and not hil_reply:
            return self._interrupt_payload(state, plan_meta=plan_meta)

        issues = self.list_themed_issues(theme_name)
        wanted = str(issue or "").strip()
        if wanted:
            number = int("".join(ch for ch in wanted if ch.isdigit()) or "0")
            issues = [item for item in issues if item.number == number]
            if not issues:
                raise RuntimeError(
                    f"no themed issue #{number} under theme:{theme_name}"
                )
        state = SmallWorkState(
            theme=theme_name,
            issues=[asdict(item) for item in issues],
            index=0,
            report=[],
            pending_hil=None,
            grill_questions=[],
            status="running",
        )
        self.save_state(state)
        return self._advance(state, plan_meta=plan_meta)

    def _continue_with_hil(
        self,
        state: SmallWorkState,
        hil_reply: str,
        *,
        plan_meta: dict[str, Any] | None,
    ) -> dict[str, Any]:
        pending = state.pending_hil or {}
        number = int(pending["number"])
        issue_row = state.issues[state.index]
        enriched = (
            f"{issue_row.get('body') or ''}\n\n"
            f"## Grill answers (judge HIL reply)\n\n{hil_reply.strip()}\n"
        )
        issue_row["body"] = enriched
        state.issues[state.index] = issue_row
        state.report.append(
            {
                "number": number,
                "title": issue_row.get("title") or "",
                "outcome": "hil_filled",
                "context_enough": False,
                "hil_reply_by": "judge",
            }
        )
        state.pending_hil = None
        state.grill_questions = []
        # Process this issue now that context is filled, then advance.
        self._complete_issue(state, ThemedIssue(**issue_row))
        state.index += 1
        state.status = "running"
        self.save_state(state)
        return self._advance(state, plan_meta=plan_meta)

    def _advance(
        self,
        state: SmallWorkState,
        *,
        plan_meta: dict[str, Any] | None,
    ) -> dict[str, Any]:
        while state.index < len(state.issues):
            row = state.issues[state.index]
            issue = ThemedIssue(**row)
            if not issue.context_enough:
                questions = self.grill_questions_for(issue)
                hil = HILCheck(
                    validation=(
                        "HIL Grill — judge must reply with enough context "
                        f"for #{issue.number} before work continues"
                    )
                )
                state.pending_hil = {
                    "number": issue.number,
                    "title": issue.title,
                    "validation": hil.validation,
                    "replier": "judge",
                }
                state.grill_questions = questions
                state.status = "hil_interrupt"
                self.save_state(state)
                return self._interrupt_payload(state, plan_meta=plan_meta)

            self._complete_issue(state, issue)
            state.index += 1
            self.save_state(state)

        state.status = "done"
        self.save_state(state)
        return self._done_payload(state, plan_meta=plan_meta)

    def _complete_issue(self, state: SmallWorkState, issue: ThemedIssue) -> None:
        # Logical Workflow spine: Backlog → In Progress → Done (no live branch).
        state.report.append(
            {
                "number": issue.number,
                "title": issue.title,
                "outcome": "done",
                "context_enough": issue.context_enough,
                "ticket_flow": ["Backlog", "In Progress", "Done"],
            }
        )

    def _interrupt_payload(
        self,
        state: SmallWorkState,
        *,
        plan_meta: dict[str, Any] | None,
    ) -> dict[str, Any]:
        pending = state.pending_hil or {}
        payload: dict[str, Any] = {
            "status": "hil_interrupt",
            "theme": state.theme,
            "themed_source": f"theme:{state.theme}",
            "current_issue": pending.get("number"),
            "grill": True,
            "hil_grill": True,
            "hil_replier": "judge",
            "grill_questions": list(state.grill_questions),
            "hil_validation": pending.get("validation"),
            "mixed_context": True,
            "report": list(state.report),
            "remaining": len(state.issues) - state.index,
        }
        if plan_meta:
            payload.update(plan_meta)
        return payload

    def _done_payload(
        self,
        state: SmallWorkState,
        *,
        plan_meta: dict[str, Any] | None,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "status": "done",
            "theme": state.theme,
            "themed_source": f"theme:{state.theme}",
            "mixed_context": any(
                not item.get("context_enough", True)
                or item.get("outcome") == "hil_filled"
                for item in state.report
            )
            or any(
                not SmallWorkRunner.enough_context(str(row.get("body") or ""))
                for row in state.issues
            ),
            "report": list(state.report),
            "issues_done": sum(
                1 for item in state.report if item.get("outcome") == "done"
            ),
            "hil_interrupts": sum(
                1 for item in state.report if item.get("outcome") == "hil_filled"
            ),
        }
        if plan_meta:
            payload.update(plan_meta)
        self.clear_state()
        return payload

