class Improvement(GuidanceAction):
    """Slash ``/repair`` runs this kit with ``arguments.guidance``; not composed on Guidance."""

    @property
    def module_dir(self) -> Path:
        """Directory of this module — used by @markdown extract."""
        return Path(inspect.getfile(type(self))).resolve().parent

    @markdown(label="repair")
    def repair_loop(self) -> str:
        """Deep root-cause recipe — why the toolset's expected behavior failed."""

    @Mcp
    @Skill
    @agent_instructions
    def repair(self, guidance: GuidanceArg, asset: str, violation: str) -> str:
        """Open a domain repair on each passed Guidance and instruct the fix. Pass a string to repair that text once."""
        self.repair_loop

        def on(item) -> None:
            if isinstance(item, str):
                return
            current = self._session()
            if current is None:
                raise ValueError("No current work session — open failed")
            repair = current.repairs.for_violation(asset, violation)
            repair.open(item, asset, violation)
            item.contexts
            item.examples
            item.templates

        self.run(guidance, on, action="repair")
        return (
            "Diagnose why the toolset's expected behavior failed for {{asset}} "
            "(run cdd_guidance.actions.diagnose.diagnose:Diagnose). State the proposed kit change "
            "before any test. Do not list tactical file fixes. Then fail-first "
            "at the seam. See repair.md."
        )

    @Mcp
    @Skill
    @agent_tool
    def verify_fix(self, guidance: GuidanceArg, theme: str) -> str:
        """Re-run the regression check for a themed repair bucket on each listed Guidance. Open the work session first. Pass a string to verify that text once."""
        def on(item) -> str:
            current = self.workspace.current_work_session
            if current is None:
                raise ValueError("No current work session — open first")
            return current.repairs[theme].verify_fix()

        self._bind_guidance(guidance)
        lines = [line for line in self.each(on) if line]
        return "\n".join(lines) if lines else f"verify_fix theme={theme}"

class TypeScriptStoryMap(CodeStoryMap):
    LEAF_EXTENSION = ".ts"
    LANGUAGE_LINE_COMMENT = "//"

    def __init__(self, tests_root: str | None = None) -> None:
        super().__init__(tests_root=tests_root)

    def _make_story_map(self) -> _TypeScriptStoryMap:
        return _TypeScriptStoryMap()

    def _make_epic(self, name: str, order: int) -> TypeScriptEpic:
        return TypeScriptEpic(name, order)

    def _make_sub_epic(self, name: str, order: int) -> TypeScriptSubEpic:
        return TypeScriptSubEpic(name, order)

    def render(
        self, canonical: StoryMap, previous: Optional[Dict[str, str]] = None
    ) -> Dict[str, str]:
        tree = render_ts_tree(canonical, tests_root=self.tests_root, include_shared=True)
        if previous:
            for path, body in list(tree.items()):
                if path in previous and self._is_gwt_leaf(path):
                    tree[path] = self._preserve_hand_written(previous[path], body)
        return tree

    def leaf_files_of(self, tree: Dict[str, str]) -> List[str]:
        return sorted(p for p in tree if self._is_gwt_leaf(p))

    def _is_gwt_leaf(self, path: str) -> bool:
        name = path.replace("\\", "/").rsplit("/", 1)[-1]
        if name in _SKIP_NAMES or name.endswith("-helper.ts"):
            return False
        if "/examples/" in path.replace("\\", "/"):
            return False
        return name.endswith(_STORY_TEST_SUFFIX)

    def _story_slug_from_filename(self, name: str) -> str | None:
        if not name.endswith(_STORY_TEST_SUFFIX):
            return None
        stem = name[: -len(_STORY_TEST_SUFFIX)]
        return stem.replace("_", "-")

    def _render_leaf_file(self, sub_epic: SubEpic, owning_epic: Epic) -> str:
        raise NotImplementedError("TypeScriptStoryMap.render uses render_ts_tree")

    def parse(self, external: Dict[str, str]) -> StoryMap:
        if not isinstance(external, dict):
            raise CodeStoryMapError("TypeScript story map parse expects a path->content dict")
        story_map = self._make_story_map()
        seen: set[tuple[str, ...]] = set()
        for path, content in sorted(external.items()):
            if not self._is_gwt_leaf(path):
                continue
            parts = path.strip("/").replace("\\", "/").split("/")
            stripped = self.strip_tests_root_prefix(parts)
            if stripped is None:
                continue
            parts = stripped
            if len(parts) < 3:
                continue
            filename = parts[-1]
            story_slug = self._story_slug_from_filename(filename)
            if not story_slug:
                continue
            epic_slug, sub_slugs = parts[0], parts[1:-1]
            if sub_slugs and sub_slugs[-1] == story_slug:
                sub_slugs = sub_slugs[:-1]
            if not sub_slugs:
                continue
            key = (epic_slug, *sub_slugs, story_slug)
            if key in seen:
                continue
            seen.add(key)
            epic = self._ensure_epic(story_map, epic_slug)
            sub = self._ensure_sub_path(epic, sub_slugs)
            story = self._parse_story_file(content, story_slug)
            if story:
                sub.stories.append(story)
        return story_map

    def _ensure_epic(self, story_map: StoryMap, epic_slug: str) -> Epic:
        for epic in story_map.epics:
            if to_kebab(epic.name) == epic_slug:
                return epic
        epic = self._make_epic(epic_slug.replace("-", " ").title(), len(story_map.epics) + 1)
        story_map.append_epic(epic)
        return epic

    def _ensure_sub_path(self, epic: Epic, sub_slugs: List[str]) -> SubEpic:
        parent_subs = epic.sub_epics
        current: SubEpic | None = None
        for slug in sub_slugs:
            found = next((s for s in parent_subs if to_kebab(s.name) == slug), None)
            if found is None:
                found = self._make_sub_epic(slug.replace("-", " ").title(), len(parent_subs) + 1)
                parent_subs.append(found)
            current = found
            parent_subs = found.sub_epics
        assert current is not None
        return current

    def _parse_story_file(self, content: str, story_slug: str) -> Story | None:
        name_match = re.search(r"\*\s*Story:\s*(.+)", content)
        story_name = name_match.group(1).strip() if name_match else story_slug.replace("-", " ").title()
        story_name = re.sub(r"\s*\([^)]*\)\.?\s*$", "", story_name).strip()
        story = Story(story_name, 1)
        actor_match = re.search(r"\*\s*Actor:\s*(.+)", content)
        if actor_match:
            story.users = [actor_match.group(1).strip()]
        for i, sc in enumerate(re.findall(r"scenario\(\s*['\"]([^'\"]+)['\"]", content), start=1):
            story.scenarios.append(Scenario(name=sc, sequential_order=i))
        return story

class Branch:
    """Named branch on a repo — checkout, commit, merge."""

    __slots__ = ("_repo", "name")

    def __init__(self, repo: Repo, name: str) -> None:
        self._repo = repo
        self.name = name

    def checkout(self) -> Branch:
        self._repo.checkout_or_create(self.name)
        return self

    def cli_agent(self) -> CliAgentBinding:
        return self._repo.read_cli_agent_tag(self.name)

    @property
    def head(self) -> Commit:
        return Commit.from_message(
            self._repo.current_commit,
            self._repo._last_commit_message(),
        )

    def commit(self, paths: list[str], message: str) -> Commit:
        sha = self._repo.commit(paths, message)
        return Commit.from_message(sha, message)

    def merge(self, other: Branch, *, message: str = "") -> Commit:
        sha = self._repo.merge_branch(other.name, self.name, message=message)
        return Commit.from_message(sha, message or f"merge {other.name} into {self.name}")

class CliAgentBinding:
    """Doer/judge CLI on a session branch — status and pids live on a git tag."""

    status: str = "closed"
    doer: str = ""
    doer_pid: int = 0
    judge: str = ""
    judge_pid: int = 0

    @property
    def open(self) -> bool:
        return self.status == "open" and self.pid_is_alive(self.doer_pid)

    def message(self) -> str:
        return Commit.note_text(
            {
                "status": self.status,
                "doer": self.doer,
                "doer_pid": str(self.doer_pid or ""),
                "judge": self.judge,
                "judge_pid": str(self.judge_pid or ""),
            }
        )

    @classmethod
    def from_message(cls, text: str) -> CliAgentBinding:
        data = Commit(sha="", message=text).note_payload()
        binding = cls()
        return cls(
            status=(data.get("status") or "closed").strip() or "closed",
            doer=(data.get("doer") or "").strip(),
            doer_pid=binding._as_pid(data.get("doer_pid")),
            judge=(data.get("judge") or "").strip(),
            judge_pid=binding._as_pid(data.get("judge_pid")),
        )

    def pid_is_alive(self, pid: int) -> bool:
        if pid <= 0:
            return False
        if os.name == "nt":
            return self._windows_pid_is_alive(pid)
        try:
            os.kill(pid, 0)
        except OSError:
            return False
        return True

    def _windows_pid_is_alive(self, pid: int) -> bool:
        import ctypes

        handle = ctypes.windll.kernel32.OpenProcess(0x1000, 0, int(pid))
        if not handle:
            return False
        ctypes.windll.kernel32.CloseHandle(handle)
        return True

    def _as_pid(self, raw: str | None) -> int:
        text = (raw or "").strip()
        if not text.isdigit():
            return 0
        return int(text)

    def write_tag(self, repo: Repo, branch_name: str) -> None:
        repo._annotated_tag_target = branch_name
        repo.write_annotated_tag(
            repo.cli_agent_tag_name(branch_name),
            self.message(),
        )

class Commit:
    sha: str
    message: str
    data: dict[str, str] = field(default_factory=dict)

    @classmethod
    def format(cls, subject: str, trailers: dict[str, str] | None = None) -> str:
        lines = [subject.strip()]
        for key, value in (trailers or {}).items():
            text = (value or "").strip()
            if text:
                lines.append(f"{key}: {text}")
        return "\n".join(lines)

    @classmethod
    def from_message(cls, sha: str, message: str) -> Commit:
        commit = cls(sha=sha, message=message)
        commit.data = commit.trailers()
        return commit

    def trailers(self) -> dict[str, str]:
        lines = (self.message or "").splitlines()
        if not lines:
            return {}
        data: dict[str, str] = {}
        for line in lines[1:]:
            if ": " not in line:
                continue
            key, value = line.split(": ", 1)
            data[key.strip()] = value.strip()
        return data

    @classmethod
    def note_text(cls, fields: dict[str, str]) -> str:
        return "\n".join(f"{key}: {value}" for key, value in fields.items())

    def note_payload(self) -> dict[str, str]:
        out: dict[str, str] = {}
        for line in (self.message or "").splitlines():
            if ": " not in line:
                continue
            key, value = line.split(": ", 1)
            out[key.strip()] = value
        return out

