class Project:
    """GitHub Project board on a repo — owns ticket states."""

    __slots__ = ("_repo", "owner", "number", "states", "text_field_name")

    def __init__(self, repo: Repo, owner: str, number: int) -> None:
        self._repo = repo
        self.owner = owner
        self.number = number
        self.states = [TicketState(name) for name in DEFAULT_PROJECT_STATES]
        self.text_field_name = "Ultimate Parent"

    def refresh_states(self) -> list[str]:
        """Load Status column names from GitHub and replace the in-memory state list."""
        names = self.status_option_names()
        if names:
            self.states = [TicketState(name) for name in names]
        return names

    def state_named(self, name: str) -> TicketState:
        options = self.status_option_names()
        resolved = self.github_status_option(name, options)
        candidates = options or [state.name for state in self.states]
        for state_name in candidates:
            if state_name.lower() == resolved.lower():
                return TicketState(state_name)
        raise ValueError(
            f"unknown project state: {name!r}; board columns: {candidates}"
        )

    def status_option_names(self) -> list[str]:
        """Live GitHub Status field option names, or empty when listing fails."""
        if self._repo.in_memory:
            return [state.name for state in self.states]
        try:
            payload = self._field_list_payload()
        except GhConnectError as exc:
            raise self._project_scope_error(exc) from exc
        return self._option_names_for_field("Status", payload)

    def ticket_rows(self) -> list[dict[str, str | int]]:
        """Return project issues with their board status."""
        if self._repo.in_memory:
            return self._memory_ticket_rows()
        raw = self._repo.run_gh(
            "project",
            "item-list",
            str(self.number),
            "--owner",
            self.owner,
            "--limit",
            "1000",
            "--format",
            "json",
        )
        payload = json.loads(raw or "{}")
        return self._ticket_rows_from_items(payload.get("items") or [])

    def write_status(self, item_id: str, state_name: str) -> str:
        """Write the Status column for one item; returns the GitHub option name sent."""
        field_id, options = self._single_select_field("Status")
        option_names = [str(option.get("name") or "") for option in options]
        gh_value = self.github_status_option(state_name, option_names)
        option_id = self._option_id_for_name(options, gh_value)
        self._edit_single_select(item_id, (field_id, option_id))
        return gh_value

    def write_theme(self, item_id: str, theme_slug: str) -> str:
        """Write the Theme column for one item; returns the GitHub option name sent."""
        field_id, options = self._single_select_field("Theme")
        option_names = [str(option.get("name") or "") for option in options]
        gh_value = self.github_theme_option(theme_slug, option_names)
        option_id = self._option_id_for_name(options, gh_value)
        self._edit_single_select(item_id, (field_id, option_id))
        return gh_value

    @classmethod
    def github_status_option(
        cls, state_name: str, option_names: list[str] | tuple[str, ...] | None = None
    ) -> str:
        """Pick a Status option: exact match first, then a known synonym."""
        wanted = (state_name or "").strip()
        names = [str(item).strip() for item in (option_names or ()) if str(item).strip()]
        if wanted in names:
            return wanted
        aliases = GITHUB_STATUS_ALIASES.get(wanted, ())
        for alias in aliases:
            if not names or alias in names:
                return alias
        return wanted

    @classmethod
    def github_theme_option(
        cls, theme: str, option_names: list[str] | tuple[str, ...] | None = None
    ) -> str:
        """Pick a project Theme option matching the slug (case-insensitive)."""
        wanted = theme_slug(theme)
        if not wanted:
            return ""
        names = [str(item).strip() for item in (option_names or ()) if str(item).strip()]
        if wanted in names:
            return wanted
        lower = wanted.lower()
        for name in names:
            if name.lower() == lower:
                return name
        return wanted

    def write_text_field(self, ticket_number: int, value: str) -> None:
        """Write this project's text field on one issue's project item."""
        if self._repo.in_memory:
            self._repo._ticket_project_fields.setdefault(ticket_number, {})[
                self.text_field_name
            ] = value
            return
        field_id = self._ensure_text_field(self.text_field_name)
        item_id = self.item_id_for(ticket_number)
        project_id = self._project_id()
        self._repo.run_gh(
            "project",
            "item-edit",
            "--id",
            item_id,
            "--project-id",
            project_id,
            "--field-id",
            field_id,
            "--text",
            value,
        )

    def _edit_single_select(self, item_id: str, field_option: tuple[str, str]) -> None:
        field_id, option_id = field_option
        self._repo.run_gh(
            "project",
            "item-edit",
            "--id",
            item_id,
            "--project-id",
            self._project_id(),
            "--field-id",
            field_id,
            "--single-select-option-id",
            option_id,
        )

    def archive_ticket(self, ticket_number: int) -> None:
        """Archive an issue's project item without deleting the issue."""
        if self._repo.in_memory:
            self._repo._archived_project_tickets.add(ticket_number)
            return
        self._repo.run_gh(
            "project",
            "item-archive",
            str(self.number),
            "--owner",
            self.owner,
            "--id",
            self.item_id_for(ticket_number),
        )

    def _project_id(self) -> str:
        raw = self._repo.run_gh(
            "project",
            "view",
            str(self.number),
            "--owner",
            self.owner,
            "--format",
            "json",
        )
        project_id = str(json.loads(raw or "{}").get("id") or "")
        if not project_id:
            raise ValueError(f"project {self.owner}/{self.number} has no id")
        return project_id

    def _field_rows(self) -> list[dict[str, object]]:
        raw = self._repo.run_gh(
            "project",
            "field-list",
            str(self.number),
            "--owner",
            self.owner,
            "--format",
            "json",
        )
        payload = json.loads(raw or "{}")
        return [row for row in payload.get("fields") or [] if isinstance(row, dict)]

    def _single_select_field(self, field_name: str) -> tuple[str, list[dict[str, object]]]:
        for field in self._field_rows():
            if str(field.get("name") or "") != field_name:
                continue
            field_id = str(field.get("id") or "")
            options = [
                option
                for option in (field.get("options") or [])
                if isinstance(option, dict)
            ]
            if not field_id:
                raise ValueError(f"project field has no id: {field_name}")
            return field_id, options
        raise ValueError(f"project field not found: {field_name}")

    def _option_id_for_name(
        self, field_options: list[dict[str, object]], name: str
    ) -> str:
        wanted = (name or "").strip()
        for option in field_options:
            label = str(option.get("name") or "").strip()
            if label == wanted or label.lower() == wanted.lower():
                option_id = str(option.get("id") or "")
                if option_id:
                    return option_id
        raise ValueError(f"unknown project option: {name!r}")

    def add_item(self, url: str) -> str:
        item_raw = self._repo.run_gh(
            "project",
            "item-add",
            str(self.number),
            "--owner",
            self.owner,
            "--url",
            url,
            "--format",
            "json",
        )
        item = json.loads(item_raw or "{}")
        return str(item.get("id") or "")

    def _ensure_text_field(self, field_name: str) -> str:
        for field in self._field_rows():
            if str(field.get("name") or "") == field_name:
                return str(field.get("id") or "")
        raw = self._repo.run_gh(
            "project",
            "field-create",
            str(self.number),
            "--owner",
            self.owner,
            "--name",
            field_name,
            "--data-type",
            "TEXT",
            "--format",
            "json",
        )
        field_id = str(json.loads(raw or "{}").get("id") or "")
        if not field_id:
            raise ValueError(f"project field was not created: {field_name}")
        return field_id

    def item_id_for(self, number: int) -> str:
        raw = self._repo.run_gh(
            "project",
            "item-list",
            str(self.number),
            "--owner",
            self.owner,
            "--limit",
            "1000",
            "--format",
            "json",
        )
        for item in json.loads(raw or "{}").get("items") or []:
            content = item.get("content") if isinstance(item, dict) else None
            if isinstance(content, dict) and content.get("number") == number:
                return str(item.get("id") or "")
        raise ValueError(f"ticket {number} is not on the project board")

    def _memory_ticket_rows(self) -> list[dict[str, str | int]]:
        rows: list[dict[str, str | int]] = []
        for number, ticket in self._repo.tickets.items():
            status = self._repo._ticket_project_state.get(number, "")
            if not status:
                continue
            rows.append(
                {
                    "number": number,
                    "title": ticket.title,
                    "url": ticket.url,
                    "status": status,
                }
            )
        return rows

    def _ticket_rows_from_items(
        self, items: list[dict[str, object]]
    ) -> list[dict[str, str | int]]:
        rows: list[dict[str, str | int]] = []
        for item in items:
            content = item.get("content")
            if not isinstance(content, dict) or content.get("type") != "Issue":
                continue
            rows.append(
                {
                    "number": int(content.get("number") or 0),
                    "title": str(content.get("title") or item.get("title") or ""),
                    "url": str(content.get("url") or ""),
                    "status": str(item.get("status") or ""),
                }
            )
        return rows

    def theme_option_names(self) -> list[str]:
        """Live GitHub Theme field option names, or empty when listing fails."""
        if self._repo.in_memory:
            return ["cli-agent", "workspace", "workflow", "tools"]
        try:
            payload = self._field_list_payload()
        except GhConnectError:
            return []
        return self._option_names_for_field("Theme", payload)

    def _field_list_payload(self) -> object:
        raw = self._repo.run_gh(
            "project",
            "field-list",
            str(self.number),
            "--owner",
            self.owner,
            "--format",
            "json",
        )
        return json.loads(raw or "{}")

    def _option_names_for_field(self, field_name: str, payload: object) -> list[str]:
        fields = payload
        if isinstance(payload, dict):
            fields = payload.get("fields") or payload.get("items") or []
        names: list[str] = []
        for field in fields or []:
            names.extend(self._labels_from_field(field, field_name))
        return names

    def _labels_from_field(self, field: object, field_name: str) -> list[str]:
        if not isinstance(field, dict):
            return []
        if str(field.get("name") or "") != field_name:
            return []
        names: list[str] = []
        for option in field.get("options") or []:
            if isinstance(option, dict):
                label = str(option.get("name") or "").strip()
            else:
                label = str(option).strip()
            if label:
                names.append(label)
        return names

    def _project_scope_error(self, exc: GhConnectError) -> GhConnectError:
        message = str(exc)
        if "read:project" in message or "missing required scopes" in message:
            return GhConnectError(f"{message} {GH_PROJECT_SCOPES_HINT}")
        return exc

    def link_repository(self) -> None:
        """Attach this org project to the current GitHub repository."""
        repo = self._repo
        owner, name = repo.owner_repo()
        if repo.in_memory:
            repo._project_links.append((self.owner, self.number, f"{owner}/{name}"))
            return
        repo.run_gh(
            "project",
            "link",
            str(self.number),
            "--owner",
            self.owner,
            "--repo",
            f"{owner}/{name}",
        )

class Ticket:
    number: int
    title: str
    body: str
    url: str = ""
    state: TicketState | None = None
    issue_type: str = ""
    labels: list[str] = field(default_factory=list)
    data: dict[str, str] = field(default_factory=dict)
    parent_number: int | None = None
    sub_issue_numbers: list[int] = field(default_factory=list)
    _repo: Repo | None = field(default=None, repr=False, compare=False)

    def bind_repo(self, repo: Repo) -> Ticket:
        self._repo = repo
        return self

    def _require_repo(self, operation: str) -> Repo:
        if self._repo is None:
            raise RuntimeError(f"Ticket.{operation} requires a repo")
        return self._repo

    @property
    def closed(self) -> bool:
        return self.data.get("closed") == "true"

    def close(self) -> None:
        repo = self._require_repo("close")
        if repo.in_memory:
            if not repo.has_ticket(self.number):
                raise TicketNotFoundError(f"GitHub issue not found: {self.number}")
            repo.mark_closed(self.number)
            self.data["closed"] = "true"
            return
        repo.run_gh("issue", "close", str(self.number))
        self.data["closed"] = "true"

    def update(self, *, title: str | None = None, body: str | None = None) -> Ticket:
        """Update supplied issue fields while leaving omitted fields unchanged."""
        repo = self._require_repo("update")
        arguments = ["issue", "edit", str(self.number)]
        if title is not None:
            arguments.extend(["--title", title])
        if body is not None:
            arguments.extend(["--body-file", "-"])
        if len(arguments) == 3:
            return self
        if not repo.in_memory:
            repo.run_gh(*arguments, stdin=body)
        self.title = title if title is not None else self.title
        self.body = body if body is not None else self.body
        return self

    def comment(self, body: str) -> Ticket:
        """Add a comment to this issue."""
        repo = self._require_repo("comment")
        if repo.in_memory:
            repo._ticket_comments.setdefault(self.number, []).append(body)
            return self
        repo.run_gh("issue", "comment", str(self.number), "--body-file", "-", stdin=body)
        return self

    def add_child(self, child: Ticket) -> Ticket:
        """Attach an existing issue as a direct sub-issue of this issue."""
        repo = self._require_repo("add_child")
        if child.number not in self.sub_issue_numbers:
            self.sub_issue_numbers.append(child.number)
        child.parent_number = self.number
        if repo.in_memory:
            children = repo._ticket_children.setdefault(self.number, [])
            if child.number not in children:
                children.append(child.number)
            repo._ticket_parents[child.number] = self.number
            return child
        repo.run_gh(
            "issue",
            "edit",
            str(self.number),
            "--add-sub-issue",
            child.url or str(child.number),
        )
        return child

    def add_label(self, name: str) -> Ticket:
        """Put a label on this issue (sidebar chip). Empty name is a no-op."""
        label = (name or "").strip()
        if not label:
            return self
        repo = self._require_repo("add_label")
        if label not in self.labels:
            self.labels.append(label)
        if repo.in_memory:
            return self
        repo.run_gh("label", "create", label, "--force")
        repo.run_gh("issue", "edit", str(self.number), "--add-label", label)
        return self

    def remove_label(self, name: str) -> Ticket:
        """Take a label off this issue. Empty or absent name is a quiet no-op."""
        label = (name or "").strip()
        if not label:
            return self
        repo = self._require_repo("remove_label")
        if label in self.labels:
            self.labels.remove(label)
        if repo.in_memory:
            return self
        repo.run_gh("issue", "edit", str(self.number), "--remove-label", label)
        return self

    def add_theme(self, theme: str) -> Ticket:
        """Apply theme on the issue label and the project board Theme field."""
        self.add_label(issue_theme_label(theme))
        return self.write_project_theme(theme)

    def write_project_theme(self, theme: str) -> Ticket:
        """Write the GitHub project board Theme single-select field for this issue."""
        slug = theme_slug(theme)
        if not slug:
            return self
        repo = self._require_repo("write_project_theme")
        project = repo.project
        if project is None:
            return self
        if repo.in_memory:
            repo._ticket_project_theme[self.number] = slug
            return self
        project.write_theme(self.project_item_id(project), slug)
        return self

    def project_item_id(self, project: Project) -> str:
        try:
            return project.item_id_for(self.number)
        except ValueError:
            logger.info("adding missing project item for issue %s", self.number)
        item_id = project.add_item(self.url)
        if not item_id:
            raise GhConnectError("Could not add issue to project.")
        return item_id

    def write_type(self, name: str) -> Ticket:
        """Apply a GitHub issue Type name (org type). Mapping lives on WorkTicket."""
        text = (name or "").strip()
        if not text:
            return self
        self.issue_type = text
        repo = self._require_repo("write_type")
        if repo.in_memory:
            return self
        repo.run_gh("issue", "edit", str(self.number), "--type", text)
        return self

    def set_status(self, state_name: str) -> Ticket:
        repo = self._require_repo("set_status")
        project = repo.project
        if project is None:
            raise RuntimeError("attach_project before setting ticket status")
        state = project.state_named(state_name)
        if repo.in_memory:
            repo._ticket_project_state[self.number] = state.name
            self.state = state
            return self
        resolved = project.write_status(self.project_item_id(project), state.name)
        self.state = project.state_named(resolved)
        return self

    @classmethod
    def from_number(cls, ref: str | int) -> int:
        if isinstance(ref, int):
            return ref
        cleaned = str(ref).strip()
        if not cleaned:
            raise ValueError(f"not a GitHub issue reference: {ref!r}")
        if cleaned.startswith("#"):
            return int(cleaned[1:])
        if "#" in cleaned:
            suffix = cleaned.rsplit("#", 1)[-1]
            if _ISSUE_NUMBER.match(suffix):
                return int(suffix)
        if "/issues/" in cleaned:
            suffix = cleaned.rstrip("/").split("/")[-1]
            if _ISSUE_NUMBER.match(suffix):
                return int(suffix)
        if _ISSUE_NUMBER.match(cleaned):
            return int(cleaned)
        raise ValueError(f"not a GitHub issue reference: {ref!r}")

    @classmethod
    def github_ref(cls, owner: str, repo: str, number: int) -> str:
        return f"{owner}/{repo}#{number}"

class TicketState:
    name: str

    @classmethod
    def backlog(cls) -> TicketState:
        return cls(DEFAULT_PROJECT_STATES[0])

    @classmethod
    def in_progress(cls) -> TicketState:
        return cls(DEFAULT_PROJECT_STATES[1])

    @classmethod
    def done(cls) -> TicketState:
        return cls(DEFAULT_PROJECT_STATES[2])

class Transformer:
    _logical_template = ""
    _tests_folder = "tests"

    def children(self) -> List[Any]:
        return []

    def get_templates_for(self, kind: str) -> list:
        if kind != "logical" or self._environment is None:
            return []
        if not self._logical_template:
            return []
        try:
            return [self._environment.get_template(f"{self._logical_template}.j2")]
        except TemplateNotFound:
            return []

    def render(self, kind: str) -> dict[str, str]:
        self._ensure_file_store()
        templates = self.get_templates_for(kind)
        if templates:
            for template in templates:
                self._apply_template(template)
        for child in self.children():
            self._render_child(child, kind)
        return self._root_files()

    def attach_environment(self, environment: Environment, root: "Transformer" | None = None) -> None:
        self._environment = environment
        self._file_root = root or self
        if root is None:
            self._files = {}
        for child in self.children():
            if isinstance(child, Transformer):
                child.attach_environment(environment, self._file_root)

    def _ensure_file_store(self) -> None:
        if getattr(self, "_file_root", None) is None:
            self._file_root = self
            self._files = {}
        if getattr(self, "_environment", None) is None:
            self._environment = None

    def _apply_template(self, template) -> None:
        path = self._output_path()
        if not path:
            return
        self._file_root._files[path] = template.render(node=self)

    def _render_child(self, child: Any, kind: str) -> None:
        if not isinstance(child, Transformer):
            return
        child._tests_folder = self._child_folder()
        child.render(kind)

    def _output_path(self) -> str:
        return ""

    def _child_folder(self) -> str:
        return self._tests_folder

    def _root_files(self) -> dict[str, str]:
        return getattr(self._file_root, "_files", {})

class Transformers:
    domain_slug = "transformers"

    @mcp
    @Skill
    @agent_tool
    def transform_sketch(self, sketch: str) -> list:
        """Load each practice transformer from the sketch and render logical templates on that root."""
        environment = Environment(loader=FileSystemLoader(str(_logical_python_root())), autoescape=False)
        practice_models = []
        for practice in self.determine_practices_from(sketch):
            transformer_type = getattr(getattr(practice, "model", None), "transformer", None)
            if transformer_type is None:
                continue
            node = transformer_type.load(sketch)
            if not isinstance(node, Transformer):
                continue
            node.attach_environment(environment)
            node.render("logical")
            practice_models.append(node)
        return practice_models

    def determine_practices_from(self, sketch: str) -> list:
        practices = []
        if _has_lens(sketch, "stories:"):
            practices.append(Stories())
        return practices

class MarkdownStoryMap(StoryMap):
    """Markdown story-map I/O. IS the format-typed tree root.

    parse / render / sync implement the Uniform Callable Surface.
    attach_source_locations stamps SourceLocation onto nodes after parsing.
    """

    def load_epic(self, source: MarkdownEpic) -> MarkdownEpic:
        return MarkdownEpic(source.name, source.sequential_order)

    def load_increment(self, source: Increment) -> MarkdownIncrement:
        return MarkdownIncrement(source.name, source.sequential_order)

    @classmethod
    def from_workspace(cls, root: "Path") -> Optional["MarkdownStoryMap"]:
        """Find story-map.md files under *root*, merge, and return; None if absent."""
        root = Path(root).resolve()
        if root.is_file():
            candidates = [root]
        else:
            candidates = (
                [root / "story-map.md"] if (root / "story-map.md").exists()
                else list(root.rglob("story-map.md"))
            )
        if not candidates:
            return None
        merged = cls()
        for md_path in candidates:
            text = md_path.read_text(encoding="utf-8")
            try:
                parsed = cls().parse(text)
            except MarkdownParseError:
                continue
            for epic in parsed.epics:
                merged.epics.append(epic)
            if root.is_file():
                rel = root.name
            else:
                rel = str(md_path.relative_to(root)).replace("\\", "/")
            merged.attach_source_locations(text, rel)
            if not getattr(merged, "source", None):
                from practices.stories.model.source_location import SourceLocation as _SL
                merged.source = _SL(rel, 1)
        return merged if merged.epics else None

    # -- Uniform Callable Surface ----------------------------------------------

    def render(self, story_map: "MarkdownStoryMap", previous: Optional[str] = None) -> str:
        if self._should_render_outline(story_map, previous):
            return self._render_outline(story_map)
        lines: List[str] = []
        for epic in story_map.epics:
            self._render_epic(epic, lines, depth=1)
        return "\n".join(lines)

    def _should_render_outline(self, story_map: "MarkdownStoryMap", previous: Optional[str]) -> bool:
        if previous and self._contains_outline_structure(previous.splitlines()):
            return True
        for epic in story_map.epics:
            if getattr(epic, "estimate", ""):
                return True
            for sub in epic.sub_epics:
                if self._sub_tree_has_outline_signal(sub):
                    return True
        return False

    def _sub_tree_has_outline_signal(self, sub: MarkdownSubEpic) -> bool:
        if getattr(sub, "estimate", ""):
            return True
        for nested in sub.sub_epics:
            if self._sub_tree_has_outline_signal(nested):
                return True
        return False

    def strip_backticks(self, text: str) -> str:
        return MarkdownScenario().strip_backticks(text)

    def _render_outline(self, story_map: "MarkdownStoryMap") -> str:
        self._outline_lines: List[str] = []
        self._outline_indent = 4
        for epic in story_map.epics:
            self._outline_lines.append(f"(E) {self.strip_backticks(epic.name)}")
            factory_line = render_md_factory_line(epic.collected_example_factories())
            if factory_line:
                self._outline_lines.append(f"    {factory_line}")
            if getattr(epic, "estimate", ""):
                self._outline_lines.append(f"    * {epic.estimate}")
            self._render_outline_sub_epics(epic.sub_epics)
        return "\n".join(self._outline_lines)

    def _render_outline_sub_epics(self, subs: List[MarkdownSubEpic]) -> None:
        pad = " " * self._outline_indent
        story_pad = " " * (self._outline_indent + 4)
        for sub in subs:
            self._outline_lines.append(f"{pad}(E) {self.strip_backticks(sub.name)}")
            self._render_outline_stories(sub, story_pad)
            if getattr(sub, "estimate", ""):
                self._outline_lines.append(f"{story_pad}* {sub.estimate}")
            self._outline_indent += 4
            self._render_outline_sub_epics(sub.sub_epics)
            self._outline_indent -= 4

    def _render_outline_stories(self, sub: MarkdownSubEpic, story_pad: str) -> None:
        for story in sub.stories:
            actor = story.users[0] if story.users else ""
            name = self.strip_backticks(story.name)
            if actor:
                actor_name = self.strip_backticks(actor)
                self._outline_lines.append(f"{story_pad}(S) {actor_name} --> {name}")
                continue
            self._outline_lines.append(f"{story_pad}(S) --> {name}")

    def parse(self, text: str) -> "MarkdownStoryMap":
        if not isinstance(text, str) or text.strip() == "":
            return MarkdownStoryMap()
        lines = text.splitlines()
        if self._looks_like_scenario_document(lines):
            return self._parse_scenario_document(text)
        self._guard_has_structure(lines)
        if self._contains_outline_structure(lines):
            return self._parse_outline_lines(lines)
        return self._parse_lines(lines)

    def _looks_like_scenario_document(self, lines: List[str]) -> bool:
        if self._contains_outline_structure(lines):
            return False
        has_scenario = any(_SCENARIO_H3.match(line) for line in lines)
        has_clause = any(
            line.strip().startswith("*Given*")
            or line.strip().startswith("*When*")
            or line.strip().startswith("*Then*")
            for line in lines
        )
        return has_scenario and has_clause

    def _parse_scenario_document(self, text: str) -> "MarkdownStoryMap":
        scenarios = MarkdownScenario.from_text(text, "story-scenarios.md")
        story_map = MarkdownStoryMap()
        stories: dict[str, MarkdownStory] = {}
        epic = MarkdownEpic("Stories", 1)
        sub = MarkdownSubEpic("Scenarios", 1)
        for scenario in scenarios:
            name = (scenario.story_name or "Story").strip()
            story = stories.get(name)
            if story is None:
                story = MarkdownStory(name, len(stories) + 1, StoryType.USER)
                stories[name] = story
                sub.stories.append(story)
            story.scenarios.append(scenario)
        if stories:
            epic.sub_epics.append(sub)
            story_map.epics.append(epic)
        return story_map

    def sync(self, text: str, canonical: "MarkdownStoryMap") -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    # -- Source location stamping ----------------------------------------------

    def attach_source_locations(self, text: str, rel_file: str) -> None:
        """Stamp SourceLocation onto each Epic/SubEpic/Story from the markdown text."""
        lines = text.splitlines()
        is_outline = any(
            _OUTLINE_EPIC_RE.match(l) or _OUTLINE_STORY_RE.match(l) for l in lines
        )
        epic_index = 0
        for i, raw in enumerate(lines, start=1):
            if not raw.strip():
                continue
            m_epic_out = _OUTLINE_EPIC_RE.match(raw)
            m_story_out = _OUTLINE_STORY_RE.match(raw)
            m_heading = _HEADING_RE.match(raw)
            m_bullet = _BULLET_RE.match(raw)

            if m_epic_out:
                indent = len(m_epic_out.group(1)) // 4
                name = self.strip_backticks(m_epic_out.group(2))
                if indent == 0:
                    if epic_index < len(self.epics):
                        self.epics[epic_index].source = SourceLocation(rel_file, i)
                        epic_index += 1
                else:
                    self._stamp_sub_epic(name, SourceLocation(rel_file, i))
                continue
            if m_story_out:
                name = self.strip_backticks(m_story_out.group(2).split("-->", 1)[-1] if "-->" in m_story_out.group(2) else m_story_out.group(2))
                self._stamp_story(name, SourceLocation(rel_file, i))
                continue
            if is_outline:
                continue
            if m_heading:
                depth = len(m_heading.group(1))
                name = m_heading.group(2).strip()
                if any(name.lower().startswith(p) for p in _DOC_TITLE_PREFIXES):
                    continue
                if depth == 1 and epic_index < len(self.epics):
                    self.epics[epic_index].source = SourceLocation(rel_file, i)
                    epic_index += 1
                elif depth >= 2:
                    self._stamp_sub_epic(name, SourceLocation(rel_file, i))
                continue
            if m_bullet:
                self._stamp_story(m_bullet.group(2).strip(), SourceLocation(rel_file, i))

    def _stamp_sub_epic(self, name: str, loc: SourceLocation) -> None:
        for sub in self.all_sub_epics():
            if sub.name == name and not getattr(sub, "source", None):
                sub.source = loc
                return

    def _stamp_story(self, name: str, loc: SourceLocation) -> None:
        for story in self.all_stories():
            if story.name == name and not getattr(story, "source", None):
                story.source = loc
                return

    # -- render helpers --------------------------------------------------------

    def _render_epic(self, epic: MarkdownEpic, lines: List[str], depth: int) -> None:
        lines.append(f"{'#' * depth} {epic.name}")
        factory_line = render_md_factory_line(epic.collected_example_factories())
        if factory_line:
            lines.append(factory_line)
        for sub in epic.sub_epics:
            self._render_sub_epic(sub, lines, depth + 1)

    def _render_sub_epic(self, sub: MarkdownSubEpic, lines: List[str], depth: int) -> None:
        lines.append(f"{'#' * depth} {sub.name}")
        for nested in sub.sub_epics:
            self._render_sub_epic(nested, lines, depth + 1)
        for story in sub.stories:
            lines.append(f"- {story.name}")
            for scenario in story.scenarios:
                lines.append(f"  - {scenario.name}")

    # -- parse helpers ---------------------------------------------------------

    def _guard_has_structure(self, lines: List[str]) -> None:
        for line in lines:
            if (
                _HEADING_PATTERN.match(line) or _BULLET_PATTERN.match(line)
                or _OUTLINE_EPIC_PATTERN.match(line) or _OUTLINE_STORY_PATTERN.match(line)
                or _OUTLINE_ESTIMATE_PATTERN.match(line)
            ):
                return
        raise MarkdownParseError("Not a valid Markdown story map: no recognised structure found")

    def _contains_outline_structure(self, lines: List[str]) -> bool:
        return any(
            _OUTLINE_EPIC_PATTERN.match(l) or _OUTLINE_STORY_PATTERN.match(l)
            for l in lines
        )

    def _parse_lines(self, lines: List[str]) -> "MarkdownStoryMap":
        self._story_map = MarkdownStoryMap()
        self._current_epic: Optional[MarkdownEpic] = None
        self._sub_epic_stack: List[MarkdownSubEpic] = []
        self._current_story: Optional[MarkdownStory] = None
        self._epic_heading_depth: Optional[int] = None
        self._ignored_heading_depth: Optional[int] = None
        for raw in lines:
            if not raw.strip():
                continue
            self._raw_line = raw
            if self._skip_ignored_section():
                continue
            if self._accept_map_heading():
                continue
            if self._accept_map_bullet():
                continue
            if self._accept_map_numbered():
                continue
            self._accept_map_factory_line()
        return self._story_map

    def _skip_ignored_section(self) -> bool:
        heading = _HEADING_PATTERN.match(self._raw_line)
        if self._ignored_heading_depth is None:
            return False
        if heading is None:
            return True
        if len(heading.group(1)) > self._ignored_heading_depth:
            return True
        self._ignored_heading_depth = None
        return False

    def _accept_map_heading(self) -> bool:
        heading = _HEADING_PATTERN.match(self._raw_line)
        if heading is None:
            return False
        depth = len(heading.group(1))
        name = heading.group(2).strip()
        if self._is_document_title(name):
            return True
        if self._is_non_story_section_heading(name):
            self._ignored_heading_depth = depth
            return True
        if name.lower().startswith("story:"):
            self._append_named_story(name.split(":", 1)[1].strip() or name)
            return True
        if self._is_epic_heading(depth):
            self._begin_epic(name, depth)
            return True
        if self._current_epic is not None:
            self._accept_nested_heading(name, depth)
        return True

    def _is_epic_heading(self, depth: int) -> bool:
        if self._current_epic is None:
            return True
        if depth == 1:
            return True
        if self._epic_heading_depth is not None and depth <= self._epic_heading_depth:
            return True
        return False

    def _begin_epic(self, name: str, depth: int) -> None:
        if self._epic_heading_depth is None:
            self._epic_heading_depth = depth
        self._current_epic = MarkdownEpic(name, len(self._story_map.epics) + 1)
        self._story_map.epics.append(self._current_epic)
        self._sub_epic_stack = []
        self._current_story = None

    def _accept_nested_heading(self, name: str, depth: int) -> None:
        if self._epic_heading_depth is None:
            self._epic_heading_depth = 1
        relative_depth = max(depth - self._epic_heading_depth, 1)
        if relative_depth >= 2:
            self._append_named_story(name)
            return
        while len(self._sub_epic_stack) >= relative_depth:
            self._sub_epic_stack.pop()
        parent_children = (
            self._sub_epic_stack[-1].sub_epics
            if self._sub_epic_stack
            else self._current_epic.sub_epics
        )
        sub = MarkdownSubEpic(name, len(parent_children) + 1)
        parent_children.append(sub)
        self._sub_epic_stack.append(sub)
        self._current_story = None

    def _append_named_story(self, story_name: str) -> None:
        parent = self._ensure_sub_epic()
        self._current_story = MarkdownStory(story_name, len(parent.stories) + 1, StoryType.USER)
        parent.stories.append(self._current_story)

    def _accept_map_bullet(self) -> bool:
        bullet = _BULLET_PATTERN.match(self._raw_line)
        if bullet is None:
            return False
        indent = len(bullet.group(1)) // 2
        text = bullet.group(2).strip()
        if indent == 0 and self._current_epic is not None:
            self._append_named_story(text)
            return True
        if indent >= 1 and self._current_story is not None:
            self._current_story.scenarios.append(
                MarkdownScenario(text, len(self._current_story.scenarios) + 1, self._current_story.name)
            )
        return True

    def _accept_map_numbered(self) -> bool:
        numbered = _NUMBERED_PATTERN.match(self._raw_line)
        if numbered is None or self._current_story is None:
            return False
        text = numbered.group(2).strip()
        text = re.sub(r"^\*\*(WHEN|THEN|AND|BUT)\*\*\s*", "", text, flags=re.IGNORECASE)
        self._current_story.scenarios.append(
            MarkdownScenario(text, len(self._current_story.scenarios) + 1, self._current_story.name)
        )
        return True

    def _accept_map_factory_line(self) -> None:
        factories = parse_md_factory_line(self._raw_line.strip())
        if not factories or self._current_epic is None:
            return
        for factory in factories:
            if factory not in self._current_epic.example_factories:
                self._current_epic.example_factories.append(factory)

    def _is_document_title(self, name: str) -> bool:
        lower = name.lower()
        return any(lower.startswith(p) for p in _DOC_TITLE_PREFIXES)

    def _is_non_story_section_heading(self, name: str) -> bool:
        return name.lower() in {"context gaps", "validation results"}

    def _ensure_sub_epic(self) -> MarkdownSubEpic:
        if self._sub_epic_stack:
            return self._sub_epic_stack[-1]
        if self._current_epic is None:
            self._current_epic = MarkdownEpic("Imported", len(self._story_map.epics) + 1)
            self._story_map.epics.append(self._current_epic)
        sub = MarkdownSubEpic(self._current_epic.name, len(self._current_epic.sub_epics) + 1)
        self._current_epic.sub_epics.append(sub)
        self._sub_epic_stack.append(sub)
        return sub

    def _parse_outline_lines(self, lines: List[str]) -> "MarkdownStoryMap":
        self._story_map = MarkdownStoryMap()
        self._current_epic = None
        self._sub_epic_stack = []
        for raw in lines:
            if not raw.strip():
                continue
            self._raw_line = raw
            if self._accept_outline_epic():
                continue
            if self._accept_outline_story():
                continue
            if self._accept_outline_estimate():
                continue
            self._accept_map_factory_line()
        return self._story_map

    def _accept_outline_epic(self) -> bool:
        match = _OUTLINE_EPIC_PATTERN.match(self._raw_line)
        if match is None:
            return False
        indent = len(match.group(1)) // 4
        name = self.strip_backticks(match.group(2))
        if indent <= 0:
            self._current_epic = MarkdownEpic(name, len(self._story_map.epics) + 1)
            self._story_map.epics.append(self._current_epic)
            self._sub_epic_stack = []
            return True
        if self._current_epic is None:
            return True
        while len(self._sub_epic_stack) >= indent:
            self._sub_epic_stack.pop()
        parent_children = (
            self._sub_epic_stack[-1].sub_epics
            if self._sub_epic_stack
            else self._current_epic.sub_epics
        )
        sub = MarkdownSubEpic(name, len(parent_children) + 1)
        parent_children.append(sub)
        self._sub_epic_stack.append(sub)
        return True

    def _accept_outline_story(self) -> bool:
        match = _OUTLINE_STORY_PATTERN.match(self._raw_line)
        if match is None or self._current_epic is None:
            return False
        if not self._sub_epic_stack:
            self._ensure_sub_epic()
        actor, story_name = self._split_outline_story(match.group(2))
        story = MarkdownStory(story_name, len(self._sub_epic_stack[-1].stories) + 1, StoryType.USER)
        if actor:
            story.users = [actor]
        self._sub_epic_stack[-1].stories.append(story)
        return True

    def _split_outline_story(self, raw_text: str) -> tuple[str, str]:
        if "-->" not in raw_text:
            return "", self.strip_backticks(raw_text)
        actor_part, story_part = raw_text.split("-->", 1)
        return self.strip_backticks(actor_part), self.strip_backticks(story_part)

    def _accept_outline_estimate(self) -> bool:
        match = _OUTLINE_ESTIMATE_PATTERN.match(self._raw_line)
        if match is None:
            return False
        estimate = match.group(2).strip()
        if self._sub_epic_stack:
            self._sub_epic_stack[-1].estimate = estimate
            return True
        if self._current_epic is not None:
            self._current_epic.estimate = estimate
        return True

class AppliesTo:
    """Cursor attach data for a rules section — owned in the practice markdown fence."""

    def __init__(self, always_apply: bool | None = None, globs: str = "") -> None:
        self.always_apply = always_apply
        self.globs = globs

    @property
    def alwaysApply(self) -> bool | None:
        return self.always_apply

    @classmethod
    def from_value(cls, value: Any) -> AppliesTo:
        if isinstance(value, cls):
            return value
        if not isinstance(value, dict):
            return cls()
        always = value.get("alwaysApply", value.get("always_apply"))
        globs: Any = value.get("globs", "")
        if not isinstance(globs, str):
            globs = "" if globs is None else str(globs)
        always_apply = None
        if isinstance(always, bool):
            always_apply = always
        elif always not in (None, ""):
            always_apply = str(always).casefold() in {"true", "yes", "1"}
        return cls(always_apply=always_apply, globs=globs)

    @classmethod
    def from_markdown(cls, text: str) -> AppliesTo:
        from harness.markdown.markdown import YamlBinder

        return cls.from_value(YamlBinder().yaml_fields(text))

    @classmethod
    def strip_fence(cls, text: str) -> str:
        from harness.markdown.markdown import strip_yaml_fences

        return strip_yaml_fences(text)

