class MiroStoryMap(StoryMap):
    """Miro story-map I/O. IS the format-typed tree root.

    parse / render / sync implement the Uniform Callable Surface.
    render_thin_slice and render_scenario are render-only views.
    """

    def load_epic(self, source: MiroEpic) -> MiroEpic:
        return MiroEpic(source.name, source.sequential_order)

    def load_increment(self, source: Increment) -> MiroIncrement:
        return MiroIncrement(source.name, source.sequential_order)

    # -- Uniform Callable Surface ----------------------------------------------

    def render(self, canonical: "MiroStoryMap", previous: Optional[str] = None) -> str:
        """Render a story-map SVG in the Miro canvas-composer DSL.

        Returns an SVG string with one rect per Epic/SubEpic/Story, each carrying
        a data-role attribute encoding its type and depth. Post with
        canvas_create_from_svg to create on an actual Miro board.

        Elements are emitted in depth-first tree order so that parse() can
        reconstruct the hierarchy by processing in document order.
        """
        lines = self._build_rect_lines(canonical)
        body = "\n".join(lines)
        return (
            "<?xml version='1.0' encoding='utf-8'?>\n"
            '<svg xmlns="http://www.w3.org/2000/svg">\n'
            + body
            + "\n</svg>"
        )

    def render_chunks(self, canonical: "MiroStoryMap", chunk_size: int = 80) -> List[str]:
        """Render story-map SVG as a list of valid SVG chunks for incremental Miro upload.

        Each chunk is self-contained and has at most chunk_size rect elements.
        Attribute values use single quotes to avoid JSON escaping issues when
        passing SVG strings to canvas_create_from_svg via MCP tool calls.

        Usage: call canvas_create_from_svg(is_repository=True, svg=chunk) for
        each returned chunk in sequence.
        """
        lines = self._build_rect_lines(canonical)
        lines_sq = [re.sub(r'="([^"]*)"', r"='\1'", line) for line in lines]
        header = "<?xml version='1.0' encoding='utf-8'?>\n<svg xmlns='http://www.w3.org/2000/svg'>"
        footer = "</svg>"
        chunks = []
        for i in range(0, len(lines_sq), chunk_size):
            body = "\n".join(lines_sq[i:i + chunk_size])
            chunks.append(f"{header}\n{body}\n{footer}")
        return chunks

    def render_api_shapes(self, canonical: "MiroStoryMap") -> List[dict]:
        """Return a flat list of shape descriptors for direct Miro REST API upload.

        Each dict has: id, x, y, w, h, rx, fill, stroke, stroke_width,
        content, role, font_size — all in SVG-coordinate space.
        Multiply x/y/w/h by a scale factor to convert to Miro board units.
        """
        return self._build_shape_dicts(canonical)

    def _build_shape_dicts(self, canonical: "MiroStoryMap") -> List[dict]:
        """Core layout engine: build one shape dict per visible node."""
        self._shapes: List[dict] = []
        epic_x = LEFT_MARGIN_X
        self._story_y = self._story_row_y(canonical)
        for epic_index, epic in enumerate(canonical.epics, start=1):
            epic_width = self._epic_width(epic)
            eid = f"epic-{epic_index}-{self._slugify(epic.name)}"
            self._shapes.append({
                "id": eid, "x": epic_x, "y": EPIC_ROW_Y,
                "w": epic_width, "h": EPIC_HEIGHT, "rx": 6,
                "fill": _FILL_EPIC, "stroke": _STROKE_EPIC, "stroke_width": 2,
                "content": epic.name, "role": "epic", "font_size": 11,
            })
            self._shape_depth = 0
            self._shape_parent_id = eid
            self._shape_start_x = epic_x + EPIC_CONTENT_INSET
            self._collect_sub_epic_shapes(epic.sub_epics)
            epic_x += epic_width + EPIC_GAP
        return self._shapes

    def _build_rect_lines(self, canonical: "MiroStoryMap") -> List[str]:
        """Build the flat list of SVG rect lines for the full story map."""
        return [self._shape_to_svg_line(s) for s in self._build_shape_dicts(canonical)]

    @staticmethod
    def _shape_to_svg_line(s: dict) -> str:
        return (
            f'  <rect id="{s["id"]}" x="{s["x"]}" y="{s["y"]}" '
            f'width="{s["w"]}" height="{s["h"]}" rx="{s["rx"]}" '
            f'fill="{s["fill"]}" stroke="{s["stroke"]}" stroke-width="{s["stroke_width"]}" '
            f'data-content="{self._xe(s["content"])}" data-role="{s["role"]}" '
            f'data-font-size="{s["font_size"]}" />'
        )

    def parse(self, text: str) -> "MiroStoryMap":
        """Parse a canvas-composer SVG back into a MiroStoryMap.

        Processes rect elements in document order (depth-first tree order as
        emitted by render). The stack-based algorithm mirrors DrawIO's parse:
        the depth encoded in data-role="subepic:{depth}" drives stack management.
        """
        try:
            root_el = ET.fromstring(
                text.split("\n", 1)[1] if text.startswith("<?") else text
            )
        except ET.ParseError as err:
            raise MiroParseError(f"Not valid SVG: {err}") from err

        def _all_rects_in_order(el: ET.Element):
            """Yield rect elements with data-role in document (DFS) order."""
            for child in el:
                tag = child.tag.split("}")[-1] if "}" in child.tag else child.tag
                if tag == "rect" and child.get("data-role"):
                    yield child
                yield from _all_rects_in_order(child)

        tagged = list(_all_rects_in_order(root_el))

        if not tagged:
            raise MiroParseError("No story-map nodes found in SVG (missing data-role attributes)")

        story_map = MiroStoryMap()
        current_epic: MiroEpic | None = None
        current_sub_epic_stack: List[MiroSubEpic] = []

        for el in tagged:
            role = el.get("data-role", "")
            label = el.get("data-content", "")
            if role == "epic":
                current_epic = MiroEpic(label, len(story_map.epics) + 1)
                story_map.epics.append(current_epic)
                current_sub_epic_stack = []
            elif role.startswith("subepic:") and current_epic is not None:
                depth = int(role.split(":", 1)[1])
                while len(current_sub_epic_stack) > depth:
                    current_sub_epic_stack.pop()
                parent_children = (
                    current_sub_epic_stack[-1].sub_epics
                    if current_sub_epic_stack
                    else current_epic.sub_epics
                )
                sub_epic = MiroSubEpic(label, len(parent_children) + 1)
                parent_children.append(sub_epic)
                current_sub_epic_stack.append(sub_epic)
            elif role.startswith("story:") and current_sub_epic_stack:
                parent = current_sub_epic_stack[-1]
                story = MiroStory(label, len(parent.stories) + 1, StoryType.USER)
                actor = el.get("data-actor", "").strip()
                if actor:
                    story.users = [actor]
                parent.stories.append(story)

        return story_map

    def sync(self, text: str, canonical: "MiroStoryMap") -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    # -- Thin-slice view -------------------------------------------------------

    def render_thin_slice(self, canonical: StoryMap) -> str:
        """Render a swim-lane grid: increment rows x epic/subepic columns.

        Returns an SVG with a Miro table widget (foreignObject data-type="table").
        Each row = one increment; columns show the epic/subepic breakdown and which
        stories belong to that increment.
        """
        # Build column headers (one per leaf sub-epic)
        headers: List[str] = ["Increment"]
        sub_epic_cols: List[SubEpic] = []
        for epic in canonical.epics:
            for sub in epic.sub_epics:
                self._collect_leaf_sub_epics(sub, sub_epic_cols)
                if not sub.sub_epics:
                    headers.append(f"{epic.name} / {sub.name}")
                else:
                    for leaf in self._leaf_sub_epics(sub):
                        headers.append(f"{epic.name} / … / {leaf.name}")

        # Build story -> column index map
        story_col: Dict[str, int] = {}
        col_idx = 1
        for epic in canonical.epics:
            for sub in epic.sub_epics:
                for leaf in self._leaf_sub_epics(sub):
                    for story in leaf.stories:
                        story_col[story.name] = col_idx
                    col_idx += 1

        # Generate table header row
        th_cells = "".join(f"<th>{self._xe(h)}</th>" for h in headers)
        # Generate increment rows
        tbody_rows: List[str] = []
        for inc in canonical.increments:
            cells = [""] * len(headers)
            cells[0] = inc.name
            for story_name in inc.stories:
                ci = story_col.get(story_name)
                if ci is not None and ci < len(cells):
                    cells[ci] = story_name
            row_html = "".join(f"<td>{self._xe(c)}</td>" for c in cells)
            tbody_rows.append(f"<tr>{row_html}</tr>")

        tbody = "\n        ".join(tbody_rows)
        col_count = len(headers)
        table_width = INC_LANE_LABEL_WIDTH + (col_count - 1) * (STORY_PITCH_X + 20)
        table_height = 60 + len(canonical.increments) * 40

        table_xml = (
            f'<foreignObject id="thin-slice-table" x="0" y="0" '
            f'width="{table_width}" height="{table_height}" '
            f'data-type="table" data-title="Thin Slicing">'
            f"<table><thead><tr>{th_cells}</tr></thead>"
            f"<tbody>\n        {tbody}\n      </tbody></table>"
            f"</foreignObject>"
        )
        return (
            "<?xml version='1.0' encoding='utf-8'?>\n"
            '<svg xmlns="http://www.w3.org/2000/svg">\n'
            f"  {table_xml}\n"
            "</svg>"
        )

    def parse_thin_slice(self, text: str) -> List[MiroIncrement]:
        """Parse a thin-slice SVG back into increment nodes.

        The foreignObject body contains an HTML table; ET parses it with the SVG
        namespace inherited from the root, so all lookups use namespace-agnostic
        tag matching (split on "}" to get local name).
        """
        try:
            root_el = ET.fromstring(
                text.split("\n", 1)[1] if text.startswith("<?") else text
            )
        except ET.ParseError as err:
            raise MiroParseError(f"Not valid SVG: {err}") from err

        fo = self._find_foreign_object(root_el, "table")
        if fo is None:
            raise MiroParseError("No table foreignObject found in thin-slice SVG")

        def _local(el: ET.Element) -> str:
            tag = el.tag
            return tag.split("}")[-1] if "}" in tag else tag

        # Find tbody using namespace-agnostic iteration
        tbody_el: ET.Element | None = None
        for el in fo.iter():
            if _local(el) == "tbody":
                tbody_el = el
                break
        if tbody_el is None:
            return []

        increments: List[MiroIncrement] = []
        order = 1
        for tr_el in tbody_el:
            if _local(tr_el) != "tr":
                continue
            cells = [td_el.text or "" for td_el in tr_el if _local(td_el) == "td"]
            if not cells:
                continue
            inc_name = cells[0].strip()
            if not inc_name:
                continue
            inc = MiroIncrement(inc_name, order)
            for story_name in cells[1:]:
                story_name = story_name.strip()
                if story_name:
                    inc.stories.append(story_name)
            increments.append(inc)
            order += 1
        return increments

    # -- Scenario view ---------------------------------------------------------

    def render_scenario(self, canonical: StoryMap) -> str:
        """Render scenario view as a Miro doc widget.

        Returns an SVG with a foreignObject data-type="doc" containing Markdown
        that lists every story with its scenarios and clauses.
        """
        md_lines: List[str] = []
        for story in self._walk_stories_with_scenarios(canonical):
            md_lines.append(f"# {story.name}")
            for scenario in story.scenarios:
                md_lines.append(f"\n## {scenario.name}\n")
                if scenario.given:
                    for clause in scenario.given:
                        prefix = "" if clause.is_continuation else "**Given** "
                        md_lines.append(f"{prefix}{clause.text}  ")
                for interaction in scenario.interactions:
                    for clause in interaction.when:
                        prefix = "" if clause.is_continuation else "**When** "
                        md_lines.append(f"{prefix}{clause.text}  ")
                    for clause in interaction.then:
                        prefix = "" if clause.is_continuation else "**Then** "
                        md_lines.append(f"{prefix}{clause.text}  ")
            md_lines.append("")

        markdown = "\n".join(md_lines).strip()
        if not markdown:
            markdown = "# (no scenarios)"

        escaped_md = self._xe(markdown)
        doc_xml = (
            f'<foreignObject id="scenario-doc" x="0" y="0" '
            f'width="784" height="1105" data-type="doc">'
            f"{escaped_md}"
            f"</foreignObject>"
        )
        return (
            "<?xml version='1.0' encoding='utf-8'?>\n"
            '<svg xmlns="http://www.w3.org/2000/svg">\n'
            f"  {doc_xml}\n"
            "</svg>"
        )

    # -- Private helpers -------------------------------------------------------

    def _slugify(self, name: str) -> str:
        s = name.lower()
        s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
        return s or "node"


    def _xe(self, value: str) -> str:
        """XML-escape a string for use in SVG attributes and text."""
        return html.escape(value, quote=True)


    def _subepic_style(self, depth: int) -> str:
        """Slightly darker fill for each nesting depth."""
        darken = min(depth * 12, 40)
        return f"#{max(0xd5 - darken, 0xa0):02x}{max(0xe8 - darken, 0xc0):02x}{max(0xd4 - darken, 0xa0):02x}"


    def _subepic_y_for_depth(self, depth: int) -> int:
        return SUBEPIC_ROW_Y + depth * (SUBEPIC_HEIGHT + SUBEPIC_DEPTH_GAP)


    def _max_sub_epic_depth(self, story_map: StoryMap) -> int:
        def depth_of(sub_epic: SubEpic, depth: int) -> int:
            if not sub_epic.sub_epics:
                return depth
            return max(depth_of(child, depth + 1) for child in sub_epic.sub_epics)

        return max(
            (
                depth_of(sub_epic, 0)
                for epic in story_map.epics
                for sub_epic in epic.sub_epics
            ),
            default=0,
        )

    def _story_row_y(self, story_map: StoryMap) -> int:
        deepest_bottom = self._subepic_y_for_depth(self._max_sub_epic_depth(story_map)) + SUBEPIC_HEIGHT
        return max(
            STORY_ROW_Y,
            deepest_bottom + ACTOR_LABEL_HEIGHT + ACTOR_LABEL_GAP + DETAIL_BELOW_SUBEPIC_PAD,
        )

    def _collect_sub_epic_shapes(self, sub_epics: List[SubEpic]) -> None:
        sub_x = self._shape_start_x
        depth = self._shape_depth
        parent_id = self._shape_parent_id
        for sub_index, sub in enumerate(sub_epics, start=1):
            span = max(sub.diagram_span_columns(), 1)
            width = span * STORY_PITCH_X - SUBEPIC_TIGHTEN * 2
            sub_y = self._subepic_y_for_depth(depth)
            sid = f"{parent_id}/sub-{sub_index}-{self._slugify(sub.name)}-d{depth}"
            self._shapes.append({
                "id": sid, "x": sub_x, "y": sub_y,
                "w": width, "h": SUBEPIC_HEIGHT, "rx": 4,
                "fill": self._subepic_style(depth), "stroke": _STROKE_SUBEPIC, "stroke_width": 1,
                "content": sub.name, "role": f"subepic:{depth}", "font_size": 10,
            })
            self._story_parent_id = sid
            self._story_origin_x = sub_x
            self._append_story_shapes(sub)
            nested_x = sub_x + len(sub.stories) * STORY_PITCH_X
            saved_start, saved_depth, saved_parent = (
                self._shape_start_x, self._shape_depth, self._shape_parent_id
            )
            self._shape_start_x = nested_x
            self._shape_depth = depth + 1
            self._shape_parent_id = sid
            self._collect_sub_epic_shapes(sub.sub_epics)
            self._shape_start_x = saved_start
            self._shape_depth = saved_depth
            self._shape_parent_id = saved_parent
            sub_x += span * STORY_PITCH_X

    def _append_story_shapes(self, sub: SubEpic) -> None:
        current_actor = ""
        for index, story in enumerate(sub.stories):
            story_x = self._story_origin_x + SUBEPIC_TIGHTEN + index * STORY_PITCH_X
            actor = story.users[0].strip() if story.users else ""
            story_id = f"{self._story_parent_id}/story-{index + 1}-{self._slugify(story.name)}"
            if actor and actor != current_actor:
                self._shapes.append({
                    "id": f"{story_id}/actor",
                    "x": story_x,
                    "y": self._story_y - ACTOR_LABEL_HEIGHT - ACTOR_LABEL_GAP,
                    "w": STORY_SIZE, "h": ACTOR_LABEL_HEIGHT, "rx": 0,
                    "fill": _FILL_SCENARIO, "stroke": _STROKE_SCENARIO, "stroke_width": 1,
                    "content": actor, "role": "actor", "font_size": 7,
                })
                current_actor = actor
            self._shapes.append({
                "id": story_id,
                "x": story_x, "y": self._story_y,
                "w": STORY_SIZE, "h": STORY_SIZE, "rx": 0,
                "fill": _FILL_STORY, "stroke": _STROKE_STORY, "stroke_width": 1,
                "content": story.name,
                "role": f"story:{story.story_type.value}",
                "font_size": 8,
                "actor": actor,
            })

    def _epic_width(self, epic: Epic) -> int:
        if not epic.sub_epics:
            return STORY_PITCH_X
        return sum(
            max(sub_epic.diagram_span_columns(), 1) * STORY_PITCH_X
            for sub_epic in epic.sub_epics
        )

    def _leaf_sub_epics(self, sub: SubEpic) -> List[SubEpic]:
        if not sub.sub_epics:
            return [sub]
        result: List[SubEpic] = []
        for child in sub.sub_epics:
            result.extend(self._leaf_sub_epics(child))
        return result

    def _collect_leaf_sub_epics(
        self, sub: SubEpic, out: List[SubEpic]
    ) -> None:
        if not sub.sub_epics:
            out.append(sub)
        else:
            for child in sub.sub_epics:
                self._collect_leaf_sub_epics(child, out)

    def _find_foreign_object(
        self, root_el: ET.Element, data_type: str
    ) -> Optional[ET.Element]:
        for el in root_el.iter():
            tag = el.tag.split("}")[-1] if "}" in el.tag else el.tag
            if tag == "foreignObject" and el.get("data-type") == data_type:
                return el
        return None

    def _walk_stories_with_scenarios(self, canonical: StoryMap) -> List[Story]:
        result: List[Story] = []
        for epic in canonical.epics:
            for sub in epic.sub_epics:
                self._collect_stories_with_scenarios(sub, result)
        return result

    def _collect_stories_with_scenarios(
        self, sub_epic: SubEpic, out: List[Story]
    ) -> None:
        for story in sub_epic.stories:
            if getattr(story, "scenarios", None):
                out.append(story)
        for nested in sub_epic.sub_epics:
            self._collect_stories_with_scenarios(nested, out)

class Iterate(GuidanceAction):
    """Iterate formal generate output with scanners - tiny grilled slices only; never dump a whole artifact in one tick."""

    def _grill_context(self) -> GrillContext:
        """GrillContext toolset for in-method composition (not a tool)."""
        return GrillContext()

    def _generate(self):
        from generate.generate import Generate

        return Generate()

    @Mcp
    @agent_tool
    def mark_iterate_tick(self) -> str:
        """Record that an iterate show/validate/fix tick is due (no I/O).
        Call only after 2-3 grill answers that unlock ONE small slice - never as a prelude to dumping the whole artifact."""
        return "iterate-tick"

    @Mcp
    @Skill
    @agent_instructions
    def iterate(self, guidance: GuidanceArg, tools: list[str] = None) -> str:
        """Grill the plan with grill: ask short framed questions and wait for answers. After each small batch of answers, generate or revise only the final deliverable slice those answers unlocked, validate it, apply one fix pass, and get user feedback before asking more. Work in short cycles until the deliverables are agreed. Do not dump the whole product in one tick, and do not sketch — iterate the formal artifacts. Pass a string to iterate that text once."""
        self.run(guidance, self._iterate_item, action="iterate")
        return "Iterate complete; generate instructions applied."

    def _iterate_item(self, item) -> None:
        self._grill_context().grill_with_context()
        self.mark_iterate_tick()
        self._generate().generate(item if isinstance(item, str) else [item])

class AgentResult:
    """Outcome of a single agent instruct run."""

    exit_code: int
    text: str
    stderr: str
    elapsed_seconds: float

    @property
    def stdout(self) -> str:
        """Alias for text — the agent's captured stdout."""
        return self.text

    def ok(self) -> bool:
        return self.exit_code == 0

class AgentSession:
    """Persistent cursor-agent chat session backed by a JSON file."""

    chat_id: str
    session_file: Path

    def __post_init__(self) -> None:
        self._log = HarnessLog("cursor_channel")

    @classmethod
    def launcher(cls) -> str | None:
        from cli_agent.cli_agent import CursorCli

        return CursorCli().launcher()

    @classmethod
    def load(cls, session_file: Path) -> AgentSession | None:
        if not session_file.is_file():
            return None
        try:
            data = json.loads(session_file.read_text(encoding="utf-8"))
            chat_id = str(data.get("chat_id", "")).strip()
        except (OSError, json.JSONDecodeError):
            return None
        return cls(chat_id=chat_id, session_file=session_file) if chat_id else None

    def save(self) -> None:
        self.session_file.parent.mkdir(parents=True, exist_ok=True)
        self.session_file.write_text(
            json.dumps({"chat_id": self.chat_id}, indent=2),
            encoding="utf-8",
        )

    @classmethod
    def from_workspace(
        cls, session_file: Path, workspace: Path, *, fresh: bool = False
    ) -> AgentSession:
        log = HarnessLog("cursor_channel")
        if not fresh:
            existing = cls.load(session_file)
            if existing is not None:
                log.write(f"session resumed: {existing.chat_id} ({session_file.name})")
                return existing
        from cli_agent.cli_agent import CursorCli

        log.write(f"creating new session for {session_file.name} in {workspace} ...")
        chat_id = CursorCli().create_chat(str(workspace.resolve()))
        session = cls(chat_id=chat_id, session_file=session_file)
        session.save()
        log.write(f"session created: {session.chat_id}")
        return session

    def run(self, prompt: str, workspace: Path, *, timeout_seconds: int = 300) -> AgentResult:
        from cli_agent.cli_agent import CursorCli

        self._log.write(
            f"agent run starting (session={self.chat_id[:8]}..., timeout={timeout_seconds}s)"
        )
        args = CursorCli(resume=self.chat_id).command(prompt, str(workspace.resolve()))
        started = time.perf_counter()
        completed = self._run_cursor_cli(args, workspace, timeout_seconds)
        elapsed = time.perf_counter() - started
        if completed.stderr:
            sys.__stderr__.write(completed.stderr)
            sys.__stderr__.flush()
        narrative = self._narrative_from_cli_stdout(completed.stdout or "")
        text = narrative or (completed.stdout or "")
        if text:
            sys.__stdout__.write(text if text.endswith("\n") else text + "\n")
            sys.__stdout__.flush()
        return AgentResult(
            exit_code=completed.returncode,
            text=text,
            stderr=completed.stderr or "",
            elapsed_seconds=elapsed,
        )

    def _run_cursor_cli(
        self, args: list[str], workspace: Path, timeout_seconds: int
    ) -> subprocess.CompletedProcess[str]:
        try:
            return subprocess.run(
                args,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=timeout_seconds,
                check=False,
                cwd=str(workspace.resolve()),
            )
        except subprocess.TimeoutExpired as exc:
            raise AgentHarnessError(
                f"cursor-agent timed out after {timeout_seconds}s",
                stdout=str(exc.stdout or ""),
                stderr=str(exc.stderr or ""),
            ) from exc

    def _narrative_from_cli_stdout(self, stdout: str) -> str:
        narrative: list[str] = []
        for raw in (stdout or "").splitlines():
            event = self._json_event(raw)
            if event is None:
                continue
            text = self._narrative_from_event(event)
            if text:
                narrative.append(text)
        return "".join(narrative)

    def _json_event(self, raw: str) -> dict[str, Any] | None:
        try:
            event = json.loads(raw.strip())
        except json.JSONDecodeError:
            return None
        return event if isinstance(event, dict) else None

    def _narrative_from_event(self, event: dict[str, Any]) -> str:
        etype = event.get("type", "")
        if etype == "assistant":
            return self._assistant_text(event)
        if etype == "result":
            return str(event.get("result", "") or "")
        return ""

    def _assistant_text(self, event: dict[str, Any]) -> str:
        parts: list[str] = []
        for block in (event.get("message") or {}).get("content") or []:
            if isinstance(block, dict) and block.get("type") == "text":
                text = str(block.get("text", ""))
                if text:
                    parts.append(text)
        return "".join(parts)

class AgentSpecManifest:
    spec_path: Path
    command: str
    harness: str
    session: str | None
    chat_instruction: str | None

    @property
    def in_chat(self) -> bool:
        return self.harness in {"in_chat", "chat"}

    @property
    def judge_session(self) -> str | None:
        if not self.session:
            return None
        path = Path(self.session)
        stem = path.stem
        return path.with_name(f"{stem}-judge.json").as_posix()

class AgentSpecRunbook:
    harness: str = ""
    workspace: str = ""
    spec_path: str = ""
    chat_instruction: str | None = None
    scenarios: list[_RunbookScenario] = field(default_factory=list)

    def to_dict(self) -> _AgentSpecRunbookDocument:
        return {
            "harness": self.harness,
            "workspace": self.workspace,
            "spec_path": self.spec_path,
            "chat_instruction": self.chat_instruction,
            "scenarios": [self._scenario_to_dict(scenario) for scenario in self.scenarios],
        }

    def _scenario_to_dict(self, scenario: _RunbookScenario) -> dict[str, Any]:
        return {
            "name": scenario.name,
            "session": scenario.session,
            "setup": [
                {
                    "kind": step.kind,
                    "prompt": step.prompt,
                    "save_as": step.save_as,
                    "timeout_seconds": step.timeout_seconds,
                }
                for step in scenario.setup
            ],
            "assertions": [
                {"description": item.description, "expression": item.expression}
                for item in scenario.assertions
            ],
            "judges": [
                {
                    "description": item.description,
                    "output": item.output,
                    "rubric": item.rubric,
                }
                for item in scenario.judges
            ],
        }

    @classmethod
    def from_spec(cls, spec_path: Path, workspace: Path | None = None) -> AgentSpecRunbook:
        runbook = cls()
        runbook._assemble(spec_path, workspace)
        return runbook

    def _assemble(self, spec_path: Path, workspace: Path | None) -> None:
        self._manifest = read_manifest(spec_path)
        self._root_start = spec_path.resolve().parent
        repo_root = workspace or self._infer_repo_root()
        self._source = spec_path.read_text(encoding="utf-8")
        self._tree = ast.parse(self._source)
        self.harness = self._manifest.harness
        self.workspace = str(repo_root.resolve())
        self.spec_path = str(self._manifest.spec_path)
        self.chat_instruction = self._manifest.chat_instruction
        self.scenarios = self._extract_scenarios()

    def _infer_repo_root(self) -> Path:
        for parent in [self._root_start, *self._root_start.parents]:
            if (parent / "harness").is_dir() and (parent / "contexts").is_dir():
                return parent
        return self._root_start.parent.parent

    def _find_marker_command(self) -> str | None:
        for line in self._source.splitlines():
            command = self._marker_command_from_line(line)
            if command is not None:
                return command
            if self._stops_header_scan(line):
                return None
        return None

    def _stops_header_scan(self, line: str) -> bool:
        stripped = line.strip()
        if stripped.startswith("#"):
            return False
        if not stripped or stripped.startswith('"""') or stripped.startswith("'''"):
            return False
        return True

    def _marker_command_from_line(self, line: str) -> str | None:
        stripped = line.strip()
        if not stripped.startswith("#"):
            return None
        body = stripped.lstrip("#").strip()
        if AGENT_SPEC_MARKER not in body:
            return None
        remainder = body.split(AGENT_SPEC_MARKER, 1)[1].strip()
        if remainder.startswith(":"):
            remainder = remainder[1:].strip()
        return remainder or None

    def _extract_scenarios(self) -> list[_RunbookScenario]:
        self._collected: list[_RunbookScenario] = []
        self._current_name = "default"
        self._current_session = self._manifest.session
        self._setup_steps: list[_RunbookStep] = []
        self._pending_it: str | None = None
        for node in ast.walk(self._tree):
            self._ingest_node(node)
        self._append_remaining_setup()
        return self._merged_scenarios()

    def _ingest_node(self, node: ast.AST) -> None:
        if isinstance(node, ast.With):
            self._ingest_with(node)
        if isinstance(node, ast.Call):
            self._ingest_call(node)

    def _ingest_with(self, node: ast.With) -> None:
        context_name = self._with_context_name(node)
        if context_name:
            self._begin_named_context(context_name)
        it_desc = self._it_description(node)
        if it_desc:
            self._pending_it = it_desc

    def _begin_named_context(self, context_name: str) -> None:
        if self._setup_steps or self._pending_it:
            self._collected.append(
                _RunbookScenario(
                    name=self._current_name,
                    session=self._current_session,
                    setup=list(self._setup_steps),
                )
            )
            self._setup_steps = []
        self._current_name = context_name
        if "agent" in context_name.lower():
            self._current_session = self._manifest.session

    def _ingest_call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Attribute):
            self._ingest_attribute_call(node)
        if self._is_expect_call(node):
            self._record_expect(node)

    def _ingest_attribute_call(self, node: ast.Call) -> None:
        attr = node.func.attr
        if attr in {"instruct", "instruct_use_tool"}:
            self._record_instruct(node, attr)
            return
        if attr == "ai_judge":
            self._record_judge(node)

    def _record_instruct(self, node: ast.Call, attr: str) -> None:
        prompt = self._prompt_arg(node, 0)
        if not prompt:
            return
        self._setup_steps.append(
            _RunbookStep(
                kind=attr,
                prompt=prompt,
                save_as=self._assignment_target(node),
                timeout_seconds=self._keyword_int(node, "timeout_seconds"),
            )
        )

    def _record_judge(self, node: ast.Call) -> None:
        output = self._expression_source(node.args[0]) if node.args else ""
        rubric = self._prompt_arg(node, 1) or ""
        self._collected.append(
            _RunbookScenario(
                name=self._current_name,
                session=self._current_session,
                setup=list(self._setup_steps),
                judges=[
                    _RunbookJudge(
                        description=self._pending_it or "ai_judge",
                        output=output,
                        rubric=rubric,
                    )
                ],
            )
        )
        self._setup_steps = []
        self._pending_it = None

    def _record_expect(self, node: ast.Call) -> None:
        desc = self._pending_it or "assertion"
        expression = self._expression_source(node)
        scenario = self._scenario_for_expect()
        scenario.assertions.append(_RunbookAssertion(description=desc, expression=expression))
        self._pending_it = None

    def _scenario_for_expect(self) -> _RunbookScenario:
        if self._collected and self._collected[-1].name == self._current_name and not self._collected[-1].setup:
            return self._collected[-1]
        for scenario in self._collected:
            if scenario.name == self._current_name:
                return scenario
        scenario = _RunbookScenario(
            name=self._current_name,
            session=self._current_session,
            setup=list(self._setup_steps),
        )
        self._collected.append(scenario)
        return scenario

    def _append_remaining_setup(self) -> None:
        if not self._setup_steps:
            return
        self._collected.append(
            _RunbookScenario(
                name=self._current_name,
                session=self._current_session,
                setup=list(self._setup_steps),
            )
        )

    def _merged_scenarios(self) -> list[_RunbookScenario]:
        by_name: dict[str, _RunbookScenario] = {}
        for scenario in self._collected:
            self._merge_named_scenario(by_name, scenario)
        merged = list(by_name.values())
        if merged or not self._manifest.session:
            return merged
        return [
            _RunbookScenario(name="default", session=self._manifest.session, setup=self._setup_steps),
        ]

    def _merge_named_scenario(
        self, by_name: dict[str, _RunbookScenario], scenario: _RunbookScenario
    ) -> None:
        existing = by_name.get(scenario.name)
        if existing is None:
            by_name[scenario.name] = scenario
            return
        existing.setup.extend(scenario.setup)
        existing.assertions.extend(scenario.assertions)
        existing.judges.extend(scenario.judges)
        if scenario.session:
            existing.session = scenario.session

    def _with_context_name(self, node: ast.With) -> str | None:
        for item in node.items:
            name = self._context_call_name(item.context_expr)
            if name is not None:
                return name
        return None

    def _context_call_name(self, expr: ast.AST) -> str | None:
        if not isinstance(expr, ast.Call):
            return None
        func = expr.func
        named = isinstance(func, ast.Name) and func.id == "context"
        attributed = isinstance(func, ast.Attribute) and func.attr == "context"
        if not (named or attributed):
            return None
        if expr.args and isinstance(expr.args[0], ast.Constant):
            return str(expr.args[0].value)
        return None

    def _it_description(self, node: ast.With) -> str | None:
        for item in node.items:
            name = self._it_call_name(item.context_expr)
            if name is not None:
                return name
        return None

    def _it_call_name(self, expr: ast.AST) -> str | None:
        if not isinstance(expr, ast.Call):
            return None
        func = expr.func
        if not (isinstance(func, ast.Name) and func.id == "it"):
            return None
        if expr.args and isinstance(expr.args[0], ast.Constant):
            return str(expr.args[0].value)
        return None

    def _string_arg(self, node: ast.Call, index: int) -> str | None:
        if len(node.args) <= index:
            return None
        arg = node.args[index]
        if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
            return arg.value
        return None

    def _prompt_arg(self, node: ast.Call, index: int) -> str | None:
        literal = self._string_arg(node, index)
        if literal is not None:
            return literal
        if len(node.args) <= index:
            return None
        return self._resolve_string_expr(node.args[index])

    def _resolve_string_expr(self, arg: ast.AST) -> str | None:
        if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
            return arg.value
        if isinstance(arg, ast.JoinedStr):
            return self._joined_string(arg)
        segment = ast.get_source_segment(self._source, arg)
        if segment is None:
            return None
        if (segment.startswith('"') and segment.endswith('"')) or (
            segment.startswith("'") and segment.endswith("'")
        ):
            return ast.literal_eval(segment)
        if segment.startswith('f"') or segment.startswith("f'"):
            return None
        return segment

    def _joined_string(self, arg: ast.JoinedStr) -> str | None:
        parts: list[str] = []
        for piece in arg.values:
            if isinstance(piece, ast.Constant) and isinstance(piece.value, str):
                parts.append(piece.value)
                continue
            if not isinstance(piece, ast.FormattedValue):
                return None
            resolved = self._resolve_formatted_value(piece)
            if resolved is None:
                return None
            parts.append(resolved)
        return "".join(parts)

    def _resolve_formatted_value(self, piece: ast.FormattedValue) -> str | None:
        value = piece.value
        if isinstance(value, ast.Name):
            return self._assigned_name_value(value.id)
        if isinstance(value, ast.Constant):
            return str(value.value)
        return ast.get_source_segment(self._source, value)

    def _assigned_name_value(self, name: str) -> str | None:
        for stmt in self._tree.body:
            if not isinstance(stmt, ast.Assign):
                continue
            for target in stmt.targets:
                if isinstance(target, ast.Name) and target.id == name:
                    if isinstance(stmt.value, ast.Constant):
                        return str(stmt.value.value)
        return None

    def _keyword_int(self, node: ast.Call, name: str) -> int | None:
        for keyword in node.keywords:
            if keyword.arg == name and isinstance(keyword.value, ast.Constant):
                if isinstance(keyword.value.value, int):
                    return keyword.value.value
        return None

    def _is_expect_call(self, node: ast.Call) -> bool:
        func = node.func
        return isinstance(func, ast.Name) and func.id == "expect"

    def _expression_source(self, node: ast.AST) -> str:
        try:
            return ast.get_source_segment(self._source, node) or ""
        except (TypeError, ValueError):
            return ""

    def _assignment_target(self, call_node: ast.Call) -> str | None:
        named = self._assign_name_for_call(call_node)
        if named is not None:
            return named
        prompt = self._prompt_arg(call_node, 0) or ""
        slug = re.sub(r"[^a-z0-9]+", "_", prompt[:40].lower()).strip("_")
        return slug or None

    def _assign_name_for_call(self, call_node: ast.Call) -> str | None:
        self._call_node = call_node
        self._call_line = getattr(call_node, "lineno", None)
        if self._call_line is None:
            return None
        for node in ast.walk(self._tree):
            found = self._target_if_matching_assign(node)
            if found is not None:
                return found
        return None

    def _target_if_matching_assign(self, node: ast.AST) -> str | None:
        if not isinstance(node, ast.Assign) or not isinstance(node.value, ast.Call):
            return None
        if not self._assign_matches_call(node.value):
            return None
        if len(node.targets) != 1:
            return None
        return self._name_from_assign_target(node.targets[0])

    def _assign_matches_call(self, value: ast.Call) -> bool:
        if value is self._call_node:
            return True
        return (
            getattr(value, "lineno", None) == self._call_line
            and getattr(value, "col_offset", None) == getattr(self._call_node, "col_offset", None)
        )

    def _name_from_assign_target(self, target: ast.AST) -> str | None:
        if isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name):
            return f"{target.value.id}.{target.attr}"
        if isinstance(target, ast.Name):
            return target.id
        return None

class JudgeResult:
    """Structured outcome from an AI judge run."""

    verdict: str
    reason: str
    elapsed_seconds: float = 0.0

    def passed(self) -> bool:
        return self.verdict == "PASS"

    def failed(self) -> bool:
        return self.verdict == "FAIL"

    @classmethod
    def from_stdout(cls, stdout: str, elapsed_seconds: float = 0.0) -> JudgeResult:
        parsed = cls(verdict="ERROR", reason="")._parsed(stdout)
        return cls(
            verdict=parsed.verdict,
            reason=parsed.reason,
            elapsed_seconds=elapsed_seconds,
        )

    def _parsed(self, stdout: str) -> JudgeResult:
        line_verdict = self._verdict_from_json_lines(stdout)
        if line_verdict is not None:
            return JudgeResult(verdict=line_verdict[0], reason=line_verdict[1])
        embedded = self._preferred_embedded_verdict(stdout)
        if embedded is not None:
            return JudgeResult(verdict=embedded[0], reason=embedded[1])
        return JudgeResult(
            verdict="ERROR",
            reason=f"no parseable verdict in output:\n{stdout[:500]}",
        )

    def _verdict_from_json_lines(self, stdout: str) -> tuple[str, str] | None:
        last_fail: tuple[str, str] | None = None
        for line in reversed(stdout.splitlines()):
            parsed = self._parse_judge_json(line.strip())
            if parsed is None:
                continue
            verdict, reason = parsed
            if verdict == "PASS":
                return verdict, reason
            if verdict == "FAIL":
                last_fail = (verdict, reason)
        return last_fail

    def _preferred_embedded_verdict(self, stdout: str) -> tuple[str, str] | None:
        embedded = self._embedded_judge_verdicts(stdout)
        for verdict, reason in reversed(embedded):
            if verdict == "PASS":
                return verdict, reason
        for verdict, reason in reversed(embedded):
            if verdict == "FAIL":
                return verdict, reason
        return None

    def _parse_judge_json(self, text: str) -> tuple[str, str] | None:
        if not text.startswith("{"):
            return None
        try:
            obj = json.loads(text)
        except json.JSONDecodeError:
            return None
        if not isinstance(obj, dict):
            return None
        verdict = str(obj.get("verdict", "")).strip().upper()
        reason = str(obj.get("reason", "")).strip()
        if verdict not in {"PASS", "FAIL"}:
            return None
        return verdict, reason

    def _embedded_judge_verdicts(self, text: str) -> list[tuple[str, str]]:
        self._judge_text = text
        self._decoder = json.JSONDecoder()
        found: list[tuple[str, str]] = []
        index = 0
        while index < len(self._judge_text):
            start = self._next_verdict_start(index)
            if start < 0:
                break
            parsed, index = self._decode_embedded_verdict(start)
            if parsed is not None:
                found.append(parsed)
        return found

    def _next_verdict_start(self, index: int) -> int:
        start = self._judge_text.find('{"verdict"', index)
        if start >= 0:
            return start
        return self._judge_text.find('{"Verdict"', index)

    def _decode_embedded_verdict(self, start: int) -> tuple[tuple[str, str] | None, int]:
        try:
            obj, end = self._decoder.raw_decode(self._judge_text, start)
        except json.JSONDecodeError:
            return None, start + 1
        return self._parse_judge_json(json.dumps(obj)), end

class AgentBlockLocal:
    """Thread-local holder for the active `with agent(...)` block."""

    def __init__(self) -> None:
        self._local = threading.local()

    def current(self) -> Any:
        block = getattr(self._local, "block", None)
        if block is None:
            raise RuntimeError("instruct/instruct_use_tool/ai_judge called outside of `with agent(...)`")
        return block

    def use(self, block: object) -> None:
        self._local.block = block

    def clear(self) -> None:
        self._local.block = None

class PartitionIndex:
    """The shared partition index at ``{session.path}/.context/{subject}-index.md``."""

    def __init__(
        self,
        path: Path,
        text: str,
        completeness: SegmentCompletenessConfig,
    ) -> None:
        self._path = path
        self._text = text
        self._completeness = completeness

    @classmethod
    def from_text(cls, path: Path, text: str) -> PartitionIndex:
        return cls(path, text, cls._completeness_from_text(text))

    @classmethod
    def resolve_near(cls, segment_path: str | Path) -> Path | None:
        """Walk up from a segment file to session ``.context/*-index.md``."""
        path = Path(segment_path)
        start = path.parent
        if start.name == ".context":
            start = start.parent
        for folder in [start, *start.parents]:
            context_dir = folder / ".context"
            if not context_dir.is_dir():
                continue
            indexes = sorted(context_dir.glob("*-index.md"))
            if indexes:
                return indexes[0].resolve()
        return None

    @property
    def path(self) -> Path:
        return self._path

    @property
    def text(self) -> str:
        return self._text

    @property
    def completeness(self) -> SegmentCompletenessConfig:
        return self._completeness

    @property
    def non_entry_headers(self) -> frozenset[str]:
        return self._completeness.non_entry_headers

    @property
    def short_body_pattern(self) -> re.Pattern[str] | None:
        return self._completeness.short_body_pattern

    @property
    def min_body_chars(self) -> int:
        return self._completeness.min_body_chars

    @classmethod
    def _completeness_from_text(cls, text: str) -> SegmentCompletenessConfig:
        raw = cls._parse_config(text)
        return SegmentCompletenessConfig(
            min_body_chars=cls._min_body_chars(raw),
            non_entry_headers=cls._non_entry_headers(raw),
            short_body_pattern=cls._short_body_pattern(raw),
        )

    @staticmethod
    def _parse_config(text: str) -> dict[str, Any]:
        match = _PARTITION_CONFIG.search(text)
        if not match:
            return {}
        loaded = yaml.safe_load(match.group(1))
        return loaded if isinstance(loaded, dict) else {}

    @staticmethod
    def _non_entry_headers(raw: dict[str, Any]) -> frozenset[str]:
        headers_raw = raw.get("non-entry-headers", [])
        if isinstance(headers_raw, str):
            parts = re.split(r"[\n|,;]+", headers_raw)
        else:
            parts = list(headers_raw or [])
        return frozenset(
            str(part).upper().strip() for part in parts if str(part).strip()
        )

    @staticmethod
    def _short_body_pattern(raw: dict[str, Any]) -> re.Pattern[str] | None:
        pattern_raw = raw.get("short-body-pattern")
        if not pattern_raw:
            return None
        return re.compile(str(pattern_raw), re.I)

    @staticmethod
    def _min_body_chars(raw: dict[str, Any]) -> int:
        chars_raw = raw.get("min-body-chars", 120)
        try:
            return int(chars_raw)
        except (TypeError, ValueError):
            return 120

class Partition(GuidanceAction):
    """Corpus partition: index, segment, completeness.

    Real toolset (not a mixin). Slash ``/partition`` runs this kit with
    ``arguments.guidance``. Workspace open and the hanging session turn come from
    ``GuidanceAction.begin`` / ``end``.
    """

    @property
    def module_dir(self) -> Path:
        return Path(inspect.getfile(type(self))).resolve().parent

    @Mcp
    @agent_tool
    def verify_segment_completeness(
        self,
        segment_path: str,
        expected_names: str = "",
        min_body_chars: int = 120,
        index_path: str = "",
    ) -> str:
        """Run named-entry completeness on a ``*-segment.md`` chunk."""
        path = Path(segment_path)
        if not path.is_file():
            return f"completeness: FAIL\nerror: segment not found: {segment_path}\n"
        segment = self._segment_for(path, expected_names, min_body_chars, index_path)
        return segment.completeness_report()

    def _segment_for(
        self,
        path: Path,
        expected_names: str,
        min_body_chars: int,
        index_path: str,
    ) -> Segment:
        index = self._read_partition_index(path, index_path)
        config = (
            index.completeness
            if index is not None
            else SegmentCompletenessConfig(min_body_chars=int(min_body_chars))
        )
        return Segment.from_text(
            path.resolve(),
            path.read_text(encoding="utf-8", errors="replace"),
            config,
            expected_names=expected_names,
        )

    @markdown
    def partition_guidance(self) -> str: ...

    def _read_partition_index(
        self, segment_path: Path, index_path: str
    ) -> PartitionIndex | None:
        resolved = (
            Path(index_path)
            if index_path.strip()
            else PartitionIndex.resolve_near(segment_path)
        )
        if resolved is None or not resolved.is_file():
            return None
        return PartitionIndex.from_text(
            resolved.resolve(),
            resolved.read_text(encoding="utf-8", errors="replace"),
        )

    @Mcp
    @agent_tool
    def index(self, context: str, out_root: str | None = None) -> str:
        """Write the partition index for this corpus under the session .context folder. Name every expected segment so completeness can be checked later."""
        return (
            "Index written for {{context}} under {session.path}/.context/ "
            "(out_root overrides session.path when set)."
        )

    @Mcp
    @agent_tool
    def segment(self, out_root: str | None = None) -> str:
        """Write verbatim source chunks from the index into segment files under the session path. Completeness must use named entries, not length alone."""
        return (
            "Verbatim source chunks written under {session.path}/{artifact}/.context/ "
            "from {subject}-index.md. "
            "Named-entry completeness verified (length-only is a false PASS)."
        )

    @agent_instructions
    def partition_corpus(self,
        context: str,
        mode: str = "one_go",
        out_root: str | None = None,
        slug: str = "",
        scaffold: str = ""

    ) -> str:
        """Build the index and segment files for one corpus. Fail if any new chunk misses a named entry the index required."""
        self.partition_guidance
        self.index(context, out_root)
        self.segment(out_root)
        self.verify_segment_completeness(
            segment_path="{artifact}-segment.md", index_path="{subject}-index.md"
        )
        return (
            "Partition of {{context}} finished (mode {{mode}}); "
            "docs under {session.path}/.context/. "
            "Hard fail if any new chunk fails named-entry completeness."
        )

    @Mcp
    @Skill
    @agent_instructions
    def partition(self,
        guidance: GuidanceArg,
        context: str,
        mode: str = "one_go",
        out_root: str | None = None,
    ) -> str:
        """Split the given context into an index plus verbatim segments for each listed Guidance. Fail if any new chunk misses a named entry the index required. Pass a string to partition that text once."""
        def on(item) -> None:
            if isinstance(item, str):
                self.partition_corpus(context, mode, out_root)
                return
            item.contexts
            self.partition_corpus(
                context,
                mode,
                out_root,
                slug=getattr(item, "context_index_key", None),
                scaffold=item.scaffold,
            )

        self.run(guidance, on, action="partition")
        return (
            "Partition of {{context}} finished (mode {{mode}}); "
            "docs under {session.path}/.context/. "
            "Hard fail if any new chunk fails named-entry completeness."
        )

class Segment:
    """A partitioned ``*-segment.md`` chunk on disk (or in memory)."""

    def __init__(
        self,
        path: Path,
        text: str,
        config: SegmentCompletenessConfig,
        *,
        expected_names: list[str] | None = None,
    ) -> None:
        self._path = path
        self._text = text
        self._config = config
        self._expected_names = (
            list(expected_names)
            if expected_names is not None
            else self._names_from_marker(text)
        )

    @classmethod
    def from_text(
        cls,
        path: Path,
        text: str,
        config: SegmentCompletenessConfig,
        *,
        expected_names: str = "",
    ) -> Segment:
        """Build a segment from already-loaded text."""
        names = (
            cls._split_names(expected_names) if expected_names.strip() else None
        )
        return cls(path, text, config, expected_names=names)

    @property
    def path(self) -> Path:
        return self._path

    @property
    def text(self) -> str:
        return self._text

    @property
    def config(self) -> SegmentCompletenessConfig:
        return self._config

    @property
    def expected_names(self) -> list[str]:
        return list(self._expected_names)

    @property
    def has_expected_names(self) -> bool:
        return bool(self._expected_names)

    def entries(self) -> list[SegmentEntry]:
        lines = self._content_lines(self._text)
        return [self._entry_for(name, lines) for name in self._expected_names]

    @property
    def is_complete(self) -> bool:
        found = self.entries()
        return bool(found) and all(entry.is_complete for entry in found)

    def completeness_report(self) -> str:
        if not self.has_expected_names:
            return (
                f"segment: {self._path}\n"
                "completeness: FAIL\n"
                "error: no expected_names argument and no "
                "<!-- expected-entries --> marker in segment\n"
            )
        entries = self.entries()
        ok_count = sum(1 for entry in entries if entry.is_complete)
        total = len(entries)
        incomplete = total - ok_count
        overall = "PASS" if incomplete == 0 and total > 0 else "FAIL"
        lines = self._report_header(overall, ok_count, total, incomplete)
        lines.extend(self._report_rows(entries, incomplete, total))
        if overall == "FAIL":
            lines.extend(self._fail_footer())
        return "\n".join(lines) + "\n"

    def _report_header(
        self, overall: str, ok_count: int, total: int, incomplete: int
    ) -> list[str]:
        return [
            f"segment: {self._path}",
            f"min_body_chars: {self._config.min_body_chars}",
            (
                f"completeness: {overall} "
                f"({ok_count}/{total} OK, {incomplete} incomplete)"
            ),
            "note: span length alone is a false PASS - named-entry completeness is required",
            "",
            "| Entry | Status | Body chars |",
            "|-------|--------|------------|",
        ]

    @staticmethod
    def _fail_footer() -> list[str]:
        return [
            "",
            "HARD FAIL: do not lock story inventory from this chunk.",
            "Repair the segment (re-extract / re-OCR) until completeness PASS.",
        ]

    def _entry_for(self, name: str, lines: list[str]) -> SegmentEntry:
        header = name.upper().strip()
        idxs = [i for i, line in enumerate(lines) if line.strip() == header]
        if not idxs:
            return SegmentEntry(name, None, self._config)
        body = self._body_after_header(lines, idxs[0], header)
        return SegmentEntry(name, body, self._config)

    def _body_after_header(
        self, lines: list[str], header_index: int, header: str
    ) -> str:
        start = header_index + 1
        body_end = len(lines)
        for index in range(start, len(lines)):
            candidate = lines[index].strip()
            if candidate and self._is_entry_header(candidate, header):
                body_end = index
                break
        return "\n".join(lines[start:body_end]).strip()

    def _is_entry_header(self, candidate: str, current_header: str) -> bool:
        if not _ALL_CAPS.match(candidate):
            return False
        if (
            candidate in self._config.non_entry_headers
            or candidate == current_header
        ):
            return False
        if re.fullmatch(r"\d{2,3}", candidate):
            return False
        return True

    def _report_rows(
        self, entries: list[SegmentEntry], incomplete: int, total: int
    ) -> list[str]:
        rows = [
            f"| {entry.name} | {entry.status} | {entry.body_chars} |"
            for entry in entries
            if not entry.is_complete
        ]
        if incomplete == 0 and total > 0:
            rows.append(
                f"| - | (all expected entries) | OK | "
                f">={self._config.min_body_chars} |"
            )
        return rows

    @classmethod
    def _names_from_marker(cls, text: str) -> list[str]:
        block = _EXPECTED_BLOCK.search(text)
        if block:
            return cls._split_names(block.group(1))
        inline = _EXPECTED_INLINE.search(text)
        if inline:
            return cls._split_names(inline.group(1))
        return []

    @staticmethod
    def _content_lines(segment_text: str) -> list[str]:
        return _HTML_COMMENT.sub("", segment_text).splitlines()

    @staticmethod
    def _split_names(raw: str) -> list[str]:
        names: list[str] = []
        for part in re.split(r"[\n|,;]+", raw):
            name = part.strip().strip("-").strip()
            if not name or name.startswith("#"):
                continue
            names.append(name)
        seen: set[str] = set()
        out: list[str] = []
        for name in names:
            key = name.casefold()
            if key in seen:
                continue
            seen.add(key)
            out.append(name)
        return out

class SegmentEntry:
    """One expected named entry inside a segment chunk."""

    def __init__(
        self,
        name: str,
        body: str | None,
        config: SegmentCompletenessConfig,
    ) -> None:
        self._name = name
        self._body = body
        self._config = config

    @property
    def name(self) -> str:
        return self._name

    @property
    def body(self) -> str | None:
        return self._body

    @property
    def body_chars(self) -> int:
        return 0 if self._body is None else len(self._body)

    @property
    def status(self) -> str:
        if self._body is None:
            return "MISSING_HEADER"
        n = len(self._body)
        pattern = self._config.short_body_pattern
        short_ok = n >= 40 and pattern is not None and bool(pattern.search(self._body))
        if n >= self._config.min_body_chars or short_ok:
            return "OK"
        return "STUB"

    @property
    def is_complete(self) -> bool:
        return self.status == "OK"

class Rows(list):
    """Decoded CodeQL select tuples as dict rows."""

    def entity_name(self, item) -> str:
        raw = item.get("label", item) if isinstance(item, dict) else str(item)
        text = str(raw)
        for prefix in ("Class ", "Function ", "Module ", "File ", "Script "):
            if text.startswith(prefix):
                return text[len(prefix) :]
        return text

    def entity_location(self, item) -> tuple[str, int]:
        if not isinstance(item, dict):
            return "", 0
        url = item.get("url")
        if isinstance(url, dict):
            return self._file_from_uri(str(url.get("uri") or "")), int(
                url.get("startLine") or 0
            )
        if isinstance(url, str) and url:
            path, _, rest = url.partition(":")
            if path.startswith("file"):
                file, line = self._split_file_url(url)
                return file, line
            line = 0
            if rest:
                try:
                    line = int(rest.split(":")[0])
                except ValueError:
                    line = 0
            return self._file_from_uri(path), line
        return "", 0

    def _split_file_url(self, url: str) -> tuple[str, int]:
        stripped = url
        if stripped.startswith("file://"):
            stripped = stripped[7:]
            if stripped.startswith("/") and len(stripped) > 2 and stripped[2] == ":":
                stripped = stripped[1:]
        file_part, _, rest = stripped.partition(":")
        if len(file_part) == 1 and rest:
            drive, _, rest = rest.partition(":")
            file_part = f"{file_part}:{drive}"
        line = 0
        if rest:
            try:
                line = int(rest.split(":")[0])
            except ValueError:
                line = 0
        return file_part.replace("\\", "/"), line

    def _file_from_uri(self, uri: str) -> str:
        text = uri
        if text.startswith("file://"):
            text = text[7:]
            if text.startswith("/") and len(text) > 2 and text[2] == ":":
                text = text[1:]
        return text.split("?")[0].replace("\\", "/")

    def entity_kind(self, item) -> str:
        raw = item.get("label", item) if isinstance(item, dict) else str(item)
        text = str(raw)
        for prefix, kind in (
            ("Class ", "Class"),
            ("Function ", "Function"),
            ("Module ", "Module"),
            ("File ", "File"),
            ("Script ", "Module"),
        ):
            if text.startswith(prefix):
                return kind
        return ""

    @classmethod
    def from_tuples(cls, tuples: List[list]) -> "Rows":
        decoder = cls()
        return cls([decoder._row_from_tuple(item) for item in tuples if item])

    def _row_from_tuple(self, item: list) -> dict:
        message = item[1] if len(item) > 1 else ""
        if isinstance(message, dict):
            message = message.get("label", "")
        file, line = self.entity_location(item[0])
        row = {"name": self.entity_name(item[0]), "message": str(message)}
        kind = self.entity_kind(item[0])
        if kind:
            row["kind"] = kind
        if file:
            row["file"] = file
        if line:
            row["line"] = line
        if len(item) > 2:
            contributor = self.entity_name(item[2])
            if contributor:
                row["contributor"] = contributor
        return row

class Node(NodeWalk, NodeRelations, NodeView):
    """Mixed into live Epic, Module, OoadClass, … — wrap or extend, do not scrape."""

    _graph: Optional["PracticeGraph"] = None
    _node_id: str = ""
    practice: str = ""
    source = None

    def semantic_type(self) -> str:
        return getattr(type(self), "_semantic_type_name", type(self).__name__)

    def slug(self, name: str) -> str:
        return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")

    def join(self, graph: "PracticeGraph", node_id: Optional[str] = None) -> "Node":
        if node_id is None:
            node_id = graph.id_for(self)
        self._graph = graph
        self._node_id = node_id
        return self

    @property
    def graph(self) -> "PracticeGraph":
        if self._graph is None:
            raise RuntimeError(f"{type(self).__name__} is not registered on a PracticeGraph")
        return self._graph

    @property
    def node_id(self) -> str:
        return self._node_id

    @property
    def used_by(self) -> List["Node"]:
        return self.related(Kind.USED_BY, direction="in")

    @property
    def home_module(self) -> Optional["Node"]:
        try:
            owners = self._module_owners()
            if owners:
                return owners[0]
            error: BaseException = RuntimeError(f"{self.name} has no owning Module")
        except Exception as caught:
            error = caught
        graph = getattr(self, "_graph", None)
        if graph is not None:
            graph.record_partial_failure(f"home_module {getattr(self, 'name', self.node_id)}", error)
            return None
        raise error

    def _module_owners(self) -> List["Node"]:
        owners = [
            n for n in self.related(Kind.BELONGS_TO) if n.semantic_type() == "Module"
        ]
        if owners:
            return owners
        owners = [
            n
            for n in self.related(Kind.OWNS, direction="in")
            if n.semantic_type() == "Module"
        ]
        if owners:
            return owners
        for parent in self.related(Kind.BELONGS_TO):
            nested = parent.home_module
            if nested is not None:
                return [nested]
        return []

    @property
    def rules(self) -> "NodeRules":
        from .node_rules import NodeRules

        return NodeRules(self)

class RuleRegistry:
    def __init__(self) -> None:
        self.rules: List[GraphRule] = []

    @classmethod
    def load(cls) -> "RuleRegistry":
        registry = cls()
        registry.load_from_practices()
        return registry

    def load_from_practices(self) -> None:
        from .guidance_rules_loader import load_graph_rules_from_markdown

        self.rules = load_graph_rules_from_markdown()

    def runnable(
        self,
        *,
        slugs: Optional[Set[str]] = None,
        skip: Optional[Set[str]] = None,
    ) -> tuple[List[GraphRule], List[GraphRule]]:
        seen: Set[str] = set()
        runnable: List[GraphRule] = []
        skipped: List[GraphRule] = []
        for rule in self.rules:
            if not rule.graph_evaluated or rule.slug in seen:
                continue
            if slugs is not None and rule.slug not in slugs:
                continue
            seen.add(rule.slug)
            if skip is not None and rule.slug in skip:
                skipped.append(rule)
                continue
            runnable.append(rule)
        return runnable, skipped

    def evaluate(
        self,
        graph,
        *,
        slugs: Optional[Set[str]] = None,
        skip: Optional[Set[str]] = None,
    ) -> Dict[str, List[RuleViolation]]:
        return graph._evaluate_graph_rules(slugs=slugs, skip=skip)

    def rules_for_node(
        self,
        *,
        practice: str,
        semantic_type: str,
        fidelity: Optional[str] = None,
        direct_only: bool = False,
    ) -> List[GraphRule]:
        matched: List[GraphRule] = []
        closest = closest_fidelity(practice, semantic_type)
        for rule in self.rules:
            if rule.practice != practice:
                continue
            if fidelity is not None and rule.fidelity != fidelity and not rule.shared:
                continue
            if rule.shared:
                if semantic_type not in rule.applies_to and not fidelity:
                    continue
            elif semantic_type not in rule.applies_to:
                continue
            if direct_only:
                if rule.shared:
                    continue
                if rule.fidelity != closest:
                    continue
            matched.append(rule)
        return matched

    def __iter__(self) -> Iterator[GraphRule]:
        return iter(self.rules)

class NodeRules:
    def __init__(
        self,
        node: Node,
        *,
        practice: Optional[str] = None,
        fidelity: Optional[str] = None,
        rule_slug: Optional[str] = None,
        direct_only: bool = False,
    ) -> None:
        self._node = node
        self._practice = practice
        self._fidelity = fidelity
        self._rule_slug = rule_slug
        self._direct_only = direct_only

    @property
    def graph(self) -> "PracticeGraph":
        return self._node.graph

    @property
    def violations(self) -> List[RuleViolation]:
        hits = self._matching()
        if self._practice is not None:
            hits = [hit for hit in hits if hit.practice == self._practice]
        if self._fidelity is not None:
            hits = [hit for hit in hits if hit.fidelity == self._fidelity]
        if self._direct_only:
            closest = closest_fidelity(self._node.practice, self._node.semantic_type())
            hits = [hit for hit in hits if hit.fidelity == closest]
        if self._rule_slug is not None:
            hits = [hit for hit in hits if hit.rule_slug == self._rule_slug]
        return hits

    @property
    def direct(self) -> "NodeRules":
        return NodeRules(self._node, direct_only=True)

    def practice(self, name: str) -> "NodeRules":
        return NodeRules(self._node, practice=name)

    def fidelity(self, name: str) -> "NodeRules":
        return NodeRules(
            self._node,
            practice=self._practice,
            fidelity=name,
        )

    def slug(self, name: str) -> "NodeRules":
        return NodeRules(self._node, rule_slug=name)

    @property
    def closest_fidelity(self) -> Optional[str]:
        return closest_fidelity(self._node.practice, self._node.semantic_type())

    @property
    def applicable_rule_slugs(self) -> List[str]:
        rules = self.graph.rule_registry.rules_for_node(
            practice=self._node.practice,
            semantic_type=self._node.semantic_type(),
        )
        return [rule.slug for rule in rules]

    def _matching(self) -> List[RuleViolation]:
        return self._dedupe(
            list(self.graph.violations_for(self._node)) + self._inherited(self._node)
        )

    def _inherited(self, node: Node) -> List[RuleViolation]:
        inherited: List[RuleViolation] = []
        for parent in node.related(Kind.OWNS, direction="in"):
            for violation in self.graph.violations_for(parent):
                if violation.rule_slug in (
                    "scenario-scopes-example",
                    "keep-classes-single-responsibility",
                ):
                    continue
                inherited.append(violation)
            inherited.extend(self._inherited(parent))
        return inherited

    def _dedupe(self, violations: List[RuleViolation]) -> List[RuleViolation]:
        seen: set[tuple] = set()
        out: List[RuleViolation] = []
        for violation in violations:
            key = (violation.rule_slug, violation.node_id, violation.message)
            if key in seen:
                continue
            seen.add(key)
            out.append(violation)
        return out

class KnowledgeGraph:
    """Always reads the working copy — never master."""

    domain_slug = "knowledge-graph"

    def __init__(
        self,
        practice_graphs: List[PracticeGraph] | None = None,
        root: Path | None = None,
    ) -> None:
        self._practice_graphs = list(practice_graphs or [])
        self._root = Path(root) if root is not None else None

    @property
    def root(self) -> Path:
        if self._root is not None:
            return self._root
        if self._practice_graphs:
            return self._practice_graphs[0].root
        return Path.cwd()

    @property
    def practice_graphs(self) -> List[PracticeGraph]:
        return list(self._practice_graphs)

    def refresh_master(self) -> KnowledgeGraph:
        from .codeql import CodeQL
        from .practice_graph import PracticeGraph

        codeql = CodeQL(self.root)
        master = codeql.rewrite_master()
        graph = PracticeGraph(self.root)
        codeql.populate(graph, database=master, results_path=master / "practice-graph.json")
        codeql.copy_master_to_working_copy()
        self._practice_graphs = [graph]
        return self

    @mcp
    @Skill
    @agent_tool
    def reload_working_copy(self, root: str | None = None) -> KnowledgeGraph:
        """Reload the working copy from the tree, populate from it, and copy it to master. Optional root is the repo folder that already has a CodeQL database."""
        from .codeql import CodeQL
        from .practice_graph import PracticeGraph

        if root:
            self._root = Path(root)
            self._practice_graphs = []
        codeql = CodeQL(self.root)
        working = codeql.rewrite_working_copy()
        graph = PracticeGraph(self.root)
        codeql.populate(
            graph,
            database=working,
            results_path=working / "practice-graph.json",
        )
        codeql.copy_working_copy_to_master()
        self._practice_graphs = [graph]
        return self

    @mcp
    @Skill
    @agent_tool
    def create_database(self, root: str | None = None) -> KnowledgeGraph:
        """Create a CodeQL master database in the repo folder and copy it to the working copy. Optional root is the repo folder to point the Knowledge Graph at."""
        from .codeql import CodeQL

        if root:
            self._root = Path(root)
            self._practice_graphs = []
        codeql = CodeQL(self.root)
        codeql.rewrite_master()
        codeql.copy_master_to_working_copy()
        self._practice_graphs = []
        return self

    @mcp
    @Skill
    @agent_tool
    def update_working_copy(
        self,
        paths: list[str] | None = None,
        root: str | None = None,
    ) -> KnowledgeGraph:
        """Update the working copy from dirty files, populate from it, and attach story tests. Pass paths as repo-relative or absolute file paths. Optional root is the repo folder that already has a CodeQL database."""
        from .codeql import CodeQL
        from .practice_graph import PracticeGraph

        if root:
            self._root = Path(root)
            self._practice_graphs = []
        dirty = [Path(path) for path in (paths or [])]
        codeql = CodeQL(self.root)
        working = codeql.extract_working_copy(dirty)
        graph = PracticeGraph(self.root)
        codeql.populate(
            graph,
            database=working,
            results_path=working / "practice-graph.json",
        )
        from .loader import attach_story_tests

        attach_story_tests(graph, dirty)
        self._practice_graphs = [graph]
        return self

    def validate(self, rule=None) -> KnowledgeGraph:
        from .codeql import CodeQL
        from .practice_graph import RuleSlugs

        slugs = RuleSlugs([rule.slug]) if rule is not None else None
        working = CodeQL(self.root).working_copy
        instructions: list[str] = []
        for graph in self._practice_graphs:
            graph.evaluate_rules(slugs=slugs, database=working)
            instructions.extend(self._markdown_instructions(graph, rule))
        self.markdown_instructions = "\n".join(instructions)
        return self

    def _markdown_instructions(self, graph, rule) -> list[str]:
        texts: list[str] = []
        for item in graph.rule_registry.rules:
            if rule is not None and item.slug != rule.slug:
                continue
            if getattr(item, "graphQuery", None) is not None:
                continue
            texts.append(item.validate())
        return texts

    @mcp
    @Skill
    @agent_tool
    def return_nodes(
        self,
        filter: Filter | None = None,
        root: str | None = None,
    ) -> str:
        """Return matching graph nodes as JSON. Always includes ancestors, children, and relationships of matched nodes. Optional root is a folder that already has .codeql/results/practice-graph.json."""
        if root:
            self._root = Path(root)
            self._practice_graphs = []
        return json.dumps(self._nodes_as_json(Filter.from_value(filter)), indent=2)

    @mcp
    @Skill
    @agent_instructions
    def get_fix_violation_instructions(
        self,
        filter: Filter | None = None,
        root: str | None = None,
    ) -> str:
        """Return copy-to-prompt instructions together with Knowledge Graph rule violations under a node and its children. This does not fix anything. If you already have the violations, do not call this method. Always includes the node and its children. Only nodes that have violations are included. Optional root is a folder that already has .codeql/results/practice-graph.json."""
        return self._violation_prompt_text(Filter.from_value(filter), root)

    def _graphs(self) -> List[PracticeGraph]:
        if self._practice_graphs:
            return self._practice_graphs
        try:
            from .codeql import CodeQL

            graph = PracticeGraph(self.root)
            codeql = CodeQL(self.root)
            codeql.populate(graph, populate=False)
            graph.evaluate_rules(database=codeql.working_copy)
            self._practice_graphs = [graph]
        except Exception:
            self._practice_graphs = []
        return self._practice_graphs

    def _nodes_as_json(self, filt: Filter) -> list[dict]:
        matched: list[dict] = []
        for graph in self._graphs():
            seeds = {
                node.node_id
                for node in graph.nodes.values()
                if filt.matches(node)
            }
            kept = filt.expand_ids(seeds, graph) if filt.constrains else set(graph.nodes)
            for node in graph.nodes.values():
                if node.node_id not in kept:
                    continue
                matched.append(
                    self._node_as_json(
                        node,
                        graph,
                        seed=node.node_id in seeds,
                        kept=kept,
                    )
                )
        return matched

    def _nodes_along(self, graph, parts: list[str]):
        keys = [part.strip().casefold() for part in parts if part.strip()]
        if not keys:
            return list(graph.nodes.values())
        current = [node for node in graph.nodes.values() if self._key_matches(node, keys[0])]
        for key in keys[1:]:
            current = [
                child
                for node in current
                for child in self._children(node)
                if self._key_matches(child, key)
            ]
        return current

    def _key_matches(self, node, key: str) -> bool:
        return self._name_key(node) == key or node.node_id.casefold() == key

    def _name_key(self, node) -> str:
        return str(getattr(node, "name", "") or node.semantic_type()).casefold()

    def _children(self, node):
        owned = node.related(Kind.OWNS)
        return owned if owned else node.related()

    def _dotted_path(self, node) -> str:
        names = [str(getattr(node, "name", "") or node.semantic_type())]
        current = node
        for _ in range(8):
            parents = current.related(Kind.BELONGS_TO) or current.related(
                Kind.OWNS, direction="in"
            )
            if not parents:
                break
            current = parents[0]
            names.append(str(getattr(current, "name", "") or current.semantic_type()))
        return ".".join(reversed(names))

    def _node_as_json(self, node, graph, seed: bool = True, kept: set | None = None) -> dict:
        src = getattr(node, "source", None)
        hits = graph.violations_for(node)
        kept_ids = kept if kept is not None else {node.node_id}
        relationships = []
        for edge in graph.edges_at(node):
            if edge.from_id not in kept_ids or edge.to_id not in kept_ids:
                continue
            other = edge.to_node if edge.from_id == node.node_id else edge.from_node
            relationships.append(
                {
                    "kind": edge.kind,
                    "from_id": edge.from_id,
                    "to_id": edge.to_id,
                    "name": getattr(other, "name", None) or other.semantic_type(),
                }
            )
        return {
            "path": self._dotted_path(node),
            "node_id": node.node_id,
            "name": getattr(node, "name", None) or node.semantic_type(),
            "practice": getattr(node, "practice", "") or "",
            "semantic_type": node.semantic_type(),
            "seed": seed,
            "source": None
            if src is None
            else {
                "file": str(getattr(src, "file", "") or ""),
                "start_line": int(getattr(src, "line", 0) or 0),
                "end_line": int(getattr(src, "end_line", 0) or 0),
                "text": str(getattr(src, "text", "") or ""),
            },
            "relationships": relationships,
            "violations": [
                {
                    "rule_slug": hit.rule_slug,
                    "message": hit.message,
                    "practice": hit.practice,
                    "fidelity": hit.fidelity,
                }
                for hit in hits
            ],
        }

    def _violation_prompt_text(self, filt: Filter, root: str | None = None) -> str:
        if root:
            self._root = Path(root)
            self._practice_graphs = []
        prompts = [
            prompt
            for graph in self._graphs()
            for prompt in self._graph_violation_prompts(graph, filt)
        ]
        return self._violation_task_list(prompts)

    def _violation_task_list(self, prompts: list[str]) -> str:
        if not prompts:
            return ""
        return "\n\n---\n\n".join([_VIOLATION_TASK_PROCESS, *prompts])

    def _graph_violation_prompts(self, graph, filt: Filter) -> list[str]:
        kept = self._violation_subtree_ids(graph, filt)
        hit = filt.without_scope()
        hit.violations = True
        prompts: list[str] = []
        for node in graph.nodes.values():
            if node.node_id not in kept:
                continue
            if not hit.matches(node):
                continue
            self._prompt_filter = hit
            prompts.extend(self._node_violation_prompts(node))
        return prompts

    def _violation_subtree_ids(self, graph, filt: Filter) -> set:
        scope = filt.scope()
        if not scope.constrains:
            return set(graph.nodes)
        seeds = {
            node.node_id
            for node in graph.nodes.values()
            if scope.matches(node)
        }
        return filt.subtree_ids(seeds, graph)

    def _node_violation_prompts(self, node) -> list[str]:
        filt = self._prompt_filter
        graph = node.graph
        rules = filt.listed(("rules", "rule"))
        prompts: list[str] = []
        for hit in graph.violations_for(node):
            if rules and hit.rule_slug not in rules:
                continue
            prompts.append(self._violation_prompt(node, hit, graph))
        return prompts

    def _violation_prompt(self, node, hit, graph) -> str:
        file = self._source_span(getattr(node, "source", None))
        body = self._rule_body(graph, hit.rule_slug)
        return "\n".join(
            line
            for line in (
                "Fix this Violation.",
                "[ ] done",
                f"Node: {self._dotted_path(node)} ({node.semantic_type()})",
                f"File: {file}" if file else "",
                f"Rule: {hit.rule_slug}",
                f"Practice: {hit.practice}" if getattr(hit, "practice", "") else "",
                f"Fidelity: {hit.fidelity}" if getattr(hit, "fidelity", "") else "",
                body,
                f"Violation: {hit.message}",
            )
            if line
        )

    def _source_span(self, src) -> str:
        if src is None:
            return ""
        file = str(getattr(src, "file", "") or "")
        if not file:
            return ""
        start = int(getattr(src, "line", 0) or 0)
        end = int(getattr(src, "end_line", 0) or 0)
        if start >= 1:
            return f"{file}:{start}-{end}"
        return file

    def _rule_body(self, graph, slug: str) -> str:
        for item in getattr(graph.rule_registry, "rules", []) or []:
            if getattr(item, "slug", "") == slug:
                return str(
                    getattr(item, "body", None) or getattr(item, "markdown", None) or ""
                )
        return ""

class PracticeGraph:
    """Registry of nodes and relationships for one working area."""

    def __init__(self, root: Path, rule_registry: RuleRegistry | None = None) -> None:
        self.root = root.resolve()
        self.story_map = None
        self.ce_model = None
        self.nodes: Dict[str, Node] = {}
        self.relationships: List[Relationship] = []
        self._used_by: Dict[str, List[str]] = {}
        self._outgoing: Dict[str, List[Relationship]] = {}
        self._incoming: Dict[str, List[Relationship]] = {}
        self._violations_by_node: Dict[str, List[RuleViolation]] = {}
        self.partial_failures: List[str] = []
        self.rule_timings: List[RuleTiming] = []
        self.rule_registry = rule_registry if rule_registry is not None else RuleRegistry.load()
        self.modules: Dict[str, Node] = {}
        self.epics: Dict[str, Node] = {}
        self.descriptions: Dict[str, Node] = {}

    def violations_for(self, node: Node) -> List[RuleViolation]:
        return list(self._violations_by_node.get(node.node_id, []))

    def working_context(self) -> Path:
        folder = self.root / ".context"
        folder.mkdir(parents=True, exist_ok=True)
        return folder

    @classmethod
    def load(
        cls,
        path: str | Path,
        *,
        codeql_results: str | Path | None = None,
        populate: bool = True,
    ) -> "PracticeGraph":
        from .loader import GraphLoader

        return GraphLoader(path, codeql_results).load(evaluate=populate)

    def register(self, node: Node, node_id: Optional[str] = None) -> Node:
        node.join(self, node_id)
        self.nodes[node.node_id] = node
        return node

    def id_for(self, node: Node) -> str:
        practice = getattr(node, "practice", "node")
        semantic = node.semantic_type()
        return f"{practice}:{semantic}:{Node().slug(node.name)}:{id(node)}"

    def relate(self, edge: Relationship) -> Relationship:
        self.relationships.append(edge)
        self._used_by.setdefault(edge.to_id, []).append(edge.from_id)
        self._outgoing.setdefault(edge.from_id, []).append(edge)
        self._incoming.setdefault(edge.to_id, []).append(edge)
        return edge

    def edges_from(self, node: Node) -> List[Relationship]:
        return list(self._outgoing.get(node.node_id, ()))

    def edges_to(self, node: Node) -> List[Relationship]:
        return list(self._incoming.get(node.node_id, ()))

    def edges_at(self, node: Node) -> List[Relationship]:
        return self.edges_from(node) + self.edges_to(node)

    def users_of(self, node: Node) -> List[str]:
        return list(self._used_by.get(node.node_id, []))

    def named_nodes(self) -> Dict[str, list]:
        names: Dict[str, list] = {}
        for candidate in self.nodes.values():
            names.setdefault(getattr(candidate, "name", None), []).append(candidate)
        return names

    def nodes_of_type(self, cls: Type[T]) -> List[T]:
        return [n for n in self.nodes.values() if isinstance(n, cls)]

    def class_named(self, name: str) -> Optional[Node]:
        plain = (name or "").strip()
        if not plain:
            return None
        for node in self.nodes.values():
            if node.name == plain and node.semantic_type() in _CLASS_SEMANTICS:
                return node
        return None

    def operation_named(self, class_name: str, operation_name: str) -> Optional[Node]:
        owner = self.class_named(class_name)
        if owner is None:
            wanted = (class_name or "").replace("\\", "/")
            for node in self.nodes.values():
                if node.semantic_type() != "File":
                    continue
                if node.name.replace("\\", "/") == wanted:
                    owner = node
                    break
        if owner is None:
            return None
        for node in owner.related(Kind.OWNS):
            if node.semantic_type() == "Operation" and node.name == operation_name:
                return node
        return None

    def find_class(self, name: str) -> Optional[Node]:
        return self.class_named(name)

    def find_operation(self, class_name: str, operation_name: str) -> Optional[Node]:
        return self.operation_named(class_name, operation_name)

    def outgoing_nodes(self, node: Node, kind: str) -> List[Node]:
        return node.related(kind)

    def incoming_nodes(self, node: Node, kind: str) -> List[Node]:
        return node.related(kind, direction="in")

    def index_module(self, module: Node) -> None:
        self.modules[module.name] = module

    def index_epic(self, epic: Node) -> None:
        self.epics[epic.name] = epic

    def index_description(self, description: Node) -> None:
        self.descriptions[description.name] = description

    def evaluate_rules(
        self,
        slugs: RuleSlugs | None = None,
        skip: RuleSlugs | None = None,
        *,
        codeql_results: str | Path | None = None,
        database: Path | None = None,
    ) -> Failures:
        wanted = set(slugs.names) if slugs is not None and slugs.names else None
        skipped = set(skip.names) if skip is not None and skip.names else None
        by_node = self._evaluate_graph_rules(
            slugs=wanted, skip=skipped, database=database
        )
        if wanted:
            self._merge_rule_hits(by_node, wanted)
        else:
            self._violations_by_node = by_node
        self._merge_codeql_violations(
            self._violations_by_node,
            Path(codeql_results) if codeql_results else None,
        )
        drop_cloned_operation_hits(self, self._violations_by_node)
        for node_id, violations in self._violations_by_node.items():
            node = self.nodes.get(node_id)
            if node is None:
                continue
            for violation in violations:
                try:
                    violation.direct = self._is_direct_violation(node, violation)
                except Exception as error:
                    self.record_partial_failure(
                        f"direct-flag {violation.rule_slug} on {getattr(node, 'name', node_id)}",
                        error,
                    )
        return Failures(list(self.partial_failures))

    def zero_hit_slugs(self) -> RuleSlugs:
        names: List[str] = []
        for item in self.rule_timings:
            if item.slug.startswith("run-queries:") or item.slug.startswith(
                "decode-facts:"
            ):
                continue
            if item.error and item.error != "skipped":
                continue
            if item.hits == 0:
                names.append(item.slug)
        return RuleSlugs(names)

    def _merge_rule_hits(
        self,
        by_node: Dict[str, List[RuleViolation]],
        slugs: Optional[set],
    ) -> None:
        if slugs is None:
            for node_id, hits in by_node.items():
                self._violations_by_node.setdefault(node_id, []).extend(hits)
            return
        for node_id, existing in list(self._violations_by_node.items()):
            self._violations_by_node[node_id] = [
                hit for hit in existing if hit.rule_slug not in slugs
            ]
        for node_id, hits in by_node.items():
            self._violations_by_node.setdefault(node_id, []).extend(hits)

    def record_partial_failure(self, part: str, error: BaseException) -> None:
        import logging
        import traceback

        message = f"{part}: {type(error).__name__}: {error}"
        logging.getLogger("harness.knowledge_graph").error(message, exc_info=True)
        self.partial_failures.append(message)
        log_dir = self.root / ".codeql" / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        with (log_dir / "partial-failures.log").open("a", encoding="utf-8") as log:
            log.write(message + "\n")
            log.write("".join(traceback.format_exception(error)))
            log.write("\n")

    def record_rule_timing(self, timing: RuleTiming) -> None:
        self.rule_timings.append(timing)

    def _is_direct_violation(self, node: Node, violation: RuleViolation) -> bool:
        closest = closest_fidelity(node.practice, node.semantic_type())
        if violation.fidelity is not None:
            return violation.fidelity == closest
        return violation.practice == node.practice

    def _merge_codeql_violations(
        self,
        by_node: Dict[str, List[RuleViolation]],
        codeql_results: Path | None,
    ) -> None:
        import json

        from .codeql import CodeQL

        export_path = CodeQL(self.root).results_path(codeql_results)
        if export_path is None:
            return
        raw = json.loads(export_path.read_text(encoding="utf-8"))
        for entry in raw.get("rule_violations", []):
            node = RuleViolation.from_entry(self, entry)
            if node is None:
                continue
            by_node.setdefault(node.node_id, []).append(
                RuleViolation(
                    rule_slug=entry.get("rule_slug", ""),
                    message=entry.get("message", ""),
                    practice=entry.get("practice", ""),
                    fidelity=entry.get("fidelity") or None,
                    node_id=node.node_id,
                    location=entry.get("file", ""),
                    line=int(entry.get("line") or 0),
                    source="codeql",
                )
                )

    def _evaluate_graph_rules(
        self,
        *,
        slugs: Optional[set] = None,
        skip: Optional[set] = None,
        database: Path | None = None,
    ) -> Dict[str, List[RuleViolation]]:
        from collections import defaultdict

        from .codeql import CodeQL, Rows

        by_node: Dict[str, List[RuleViolation]] = {}
        runnable, skipped_rules = self.rule_registry.runnable(slugs=slugs, skip=skip)
        self._record_skipped_rules(skipped_rules)
        by_pack = defaultdict(list)
        for rule in runnable:
            if rule.graphQuery is None and rule.pack_rules_query is None:
                continue
            by_pack[rule.query_pack].append(rule)
        codeql = CodeQL(self.root)
        self._codeql = codeql
        self._named = self.named_nodes()
        self._hits_by_node = by_node
        self._rule_database = database
        for pack, pack_rules in by_pack.items():
            self._pack = pack
            self._pack_rules = pack_rules
            self._evaluate_pack()
        return by_node

    def _record_skipped_rules(self, skipped_rules) -> None:
        for rule in skipped_rules:
            print(f"skip {rule.slug} (0 hits)", flush=True)
            self.record_rule_timing(RuleTiming(rule.slug, 0.0, 0, "skipped"))

    def _evaluate_pack(self) -> None:
        import time

        pack = self._pack
        pack_rules = self._pack_rules
        if not pack_rules:
            return
        database = self._rule_database or self._codeql._ready_database()
        if database is None:
            print(f"skip {pack.name} (no codeql database)", flush=True)
            return
        print(f"run-queries {pack.name} ({len(pack_rules)} rules) ...", flush=True)
        started = time.perf_counter()
        try:
            batch = self._rule_rows()
        except Exception as error:
            self._record_pack_error(started, error)
            return
        seconds = time.perf_counter() - started
        self.record_rule_timing(
            RuleTiming(
                f"run-queries:{pack.name}",
                seconds,
                sum(len(batch.get(rule.slug) or []) for rule in pack_rules),
            )
        )
        print(f"run-queries {pack.name}  {seconds:.2f}s", flush=True)
        self._map_pack_hits(batch)

    def _record_pack_error(self, started: float, error: Exception) -> None:
        import time

        pack = self._pack
        seconds = time.perf_counter() - started
        self.record_rule_timing(
            RuleTiming(
                f"run-queries:{pack.name}",
                seconds,
                0,
                f"{type(error).__name__}: {error}",
            )
        )
        self.record_partial_failure(f"run-queries {pack.name}", error)
        print(f"run-queries {pack.name}  {seconds:.2f}s  ERROR {error}", flush=True)

    def _map_pack_hits(self, batch) -> None:
        import time

        from .codeql import Rows

        for rule in self._pack_rules:
            print(f"rule {rule.slug} ...", flush=True)
            mapped = time.perf_counter()
            try:
                hits = rule.evaluate(
                    self,
                    hits=Rows.from_tuples(batch.get(rule.slug) or []),
                    by_name=self._named,
                )
            except Exception as error:
                elapsed = time.perf_counter() - mapped
                self.record_rule_timing(
                    RuleTiming(rule.slug, elapsed, 0, f"{type(error).__name__}: {error}")
                )
                self.record_partial_failure(f"rule {rule.slug}", error)
                print(f"rule {rule.slug}  {elapsed:.2f}s  ERROR {error}", flush=True)
                continue
            elapsed = time.perf_counter() - mapped
            self.record_rule_timing(RuleTiming(rule.slug, elapsed, len(hits)))
            print(f"rule {rule.slug}  {elapsed:.2f}s  hits={len(hits)}", flush=True)
            for violation in hits:
                self._hits_by_node.setdefault(violation.node_id, []).append(violation)

    def _rule_rows(self) -> Dict[str, list]:
        hits_lib = self._pack / "rule_hits.qll"
        self._combined_slugs = []
        self._leftover_queries = []
        for rule in self._pack_rules:
            self._collect_pack_query(rule, hits_lib)
        batch: Dict[str, list] = {}
        if self._combined_slugs:
            batch.update(self._combined_rule_rows())
        self._leftover_rule_rows(batch)
        return batch

    def _collect_pack_query(self, rule, hits_lib) -> None:
        if rule.graphQuery is None:
            return
        if not self._codeql.query_matches_pack(rule.graphQuery):
            print(
                f"skip {rule.slug} (query language does not match pack)",
                flush=True,
            )
            return
        if hits_lib.is_file():
            self._combined_slugs.append(rule.slug)
            return
        self._leftover_queries.append(rule.graphQuery)

    def _combined_rule_rows(self) -> Dict[str, list]:
        pack = self._pack
        combined = pack / "rules.ql"
        language = self._codeql.query_language(combined) if combined.is_file() else (
            self._codeql.pack_language(pack) or "python"
        )
        self._codeql.write_rules_query(pack)
        db = self._rule_database if self._rule_database is not None else self._codeql.ensure_database(language)
        return self._codeql.run_rules(pack / "rules.ql", self._combined_slugs, database=db)

    def _leftover_rule_rows(self, batch: Dict[str, list]) -> None:
        by_language: Dict[str, list] = {}
        for query in self._leftover_queries:
            language = self._codeql.query_language(query)
            by_language.setdefault(language, []).append(query)
        for language, queries in by_language.items():
            try:
                db = (
                    self._rule_database
                    if self._rule_database is not None
                    else self._codeql.ensure_database(language)
                )
                batch.update(self._codeql.run_queries(queries, database=db))
            except Exception as error:
                print(f"run-queries leftover/{language}  ERROR {error}", flush=True)

    @property
    def dot_graph(self) -> str:
        from .dot_graph import dot_graph_from_roots

        owned = {edge.to_id for edge in self.relationships if edge.kind == Kind.OWNS}
        roots = [node for node in self.nodes.values() if node.node_id not in owned]
        if not roots:
            return "digraph practice_graph {}\n"
        return dot_graph_from_roots(roots, graph_name="practice_graph")

class RuleSlugs:
    names: List[str] = field(default_factory=list)

    @classmethod
    def from_path(cls, path: Path) -> "RuleSlugs":
        if not path.is_file():
            return cls()
        names = [
            line.strip()
            for line in path.read_text(encoding="utf-8").splitlines()
            if line.strip() and not line.startswith("#")
        ]
        return cls(names)

    def write(self, path: Path) -> None:
        ordered = sorted(set(self.names))
        path.write_text(("\n".join(ordered) + "\n") if ordered else "", encoding="utf-8")

class ContainmentForest:
    """Path nesting and dependency depth for module ordering. Shared by both channels."""

    def __init__(
        self,
        by_name: Dict[str, Module],
        children_of: Dict[str, List[str]],
        roots: List[str],
        synthetic: set,
    ) -> None:
        self.by_name = by_name
        self.children_of = children_of
        self.roots = roots
        self.synthetic = synthetic
        self._depth_cache: Dict[str, int] = {}
        self._visiting: set = set()

    @classmethod
    def build(cls, modules: List[Module], synthesize_parents: bool = False) -> 'ContainmentForest':
        by_name: Dict[str, Module] = {m.name: m for m in modules}
        synthetic: set = set()
        if synthesize_parents:
            synthetic = cls._synthesize_parents(by_name)
        children_of: Dict[str, List[str]] = {n: [] for n in by_name}
        roots: List[str] = []
        for name in by_name:
            parent = path_parent(name)
            if parent and parent in by_name:
                children_of[parent].append(name)
            else:
                roots.append(name)
        for parent in children_of:
            children_of[parent].sort(key=lambda n: (by_name[n].sequential_order or 0, n))
        roots.sort(key=lambda n: (by_name[n].sequential_order or 0, n))
        return cls(by_name, children_of, roots, synthetic)

    @classmethod
    def _synthesize_parents(cls, by_name: Dict[str, Module]) -> set:
        synthetic: set = set()
        needed: List[str] = []
        for name in list(by_name):
            p = path_parent(name)
            while p:
                if p not in by_name:
                    needed.append(p)
                p = path_parent(p)
        for prefix in sorted(set(needed), key=lambda s: s.count('/')):
            by_name[prefix] = Module(
                name=prefix, sequential_order=0, description='nested modules', seam_terms=[]
            )
            synthetic.add(prefix)
        return synthetic

    def module_dep_depth(self, name: str) -> int:
        if name in self._depth_cache:
            return self._depth_cache[name]
        if name in self._visiting:
            self._depth_cache[name] = 0
            return 0
        self._visiting.add(name)
        root_deps = [self._root_of(dep) for dep in self._dep_names_for(name)]
        depths = [self.module_dep_depth(dep) for dep in root_deps if dep and dep != name]
        self._visiting.discard(name)
        d = 0 if not depths else 1 + max(depths)
        self._depth_cache[name] = d
        return d

    def _dep_names_for(self, name: str) -> List[str]:
        module = self.by_name[name]
        node = DiagramModule(
            name=module.name,
            sequential_order=module.sequential_order,
            dependencies=list(module.dependencies),
        )
        dep_names = list(node.external_deps())
        if name in self.synthetic or (
            self.children_of.get(name)
            and not module.public_terms()
            and not module.dependencies
        ):
            for child in self.children_of.get(name, []):
                nested = self.by_name[child]
                dep_names.extend(
                    DiagramModule(
                        name=nested.name,
                        sequential_order=nested.sequential_order,
                        dependencies=list(nested.dependencies),
                    ).external_deps()
                )
        return dep_names

    def _root_of(self, dep: str) -> Optional[str]:
        if dep not in self.by_name:
            return None
        cur = dep
        while True:
            parent = path_parent(cur)
            if not parent or parent not in self.by_name:
                break
            cur = parent
        if cur in self.roots:
            return cur
        return None

class DiagramClass(OoadClass, DiagramNode):
    """OoadClass on a page: name, members, height. Channel fills the label."""

    def __init__(self, name: str = '', sequential_order: int = 1, **kwargs) -> None:
        OoadClass.__init__(self, name, sequential_order, **kwargs)
        DiagramNode.__init__(self)
        self.geometry = Geometry(0, 0, CELL_WIDTH, float(self.height()))

    def height(self) -> int:
        n_content = len(self.properties) + len(self.operations)
        return max(CELL_MIN_HEIGHT, 30 + n_content * LINE_HEIGHT + 2 * SECTION_PAD)

    def display_name(self) -> str:
        n = re.sub('\\*+', '', self.name)
        n = re.sub('<<[^>]+>>', '', n)
        n = re.sub('\\s+extends\\s+.+$', '', n, flags=re.IGNORECASE)
        return n.strip()

    def tactical_stereotypes(self) -> list[str]:
        n = re.sub('\\*+', '', self.name)
        return [s.strip() for s in re.findall('<<[^>]+>>', n)]

    def extends_base_name(self) -> Optional[str]:
        n = re.sub('\\*+', '', self.name)
        n = re.sub('<<[^>]+>>', '', n)
        m = re.search('\\bextends\\s+([A-Z]\\w*)', n, flags=re.IGNORECASE)
        return m.group(1) if m else None

class DiagramModule(Module, DiagramNode):
    """Module on a page: purpose, seam, nesting, height. Channel fills the label."""

    def __init__(self, name: str = '', sequential_order: int = 1, **kwargs) -> None:
        Module.__init__(self, name, sequential_order, **kwargs)
        DiagramNode.__init__(self)
        self.children: List['DiagramModule'] = []
        self.nested = False
        self.geometry = Geometry(0, 0, MODULE_CELL_WIDTH, float(self.height()))

    def load_class(self, source: OoadClass) -> DiagramClass:
        loaded = DiagramClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def height(self) -> int:
        return self.header_height()

    def header_height(self) -> int:
        terms = self.public_terms()
        if not terms:
            return MODULE_HEADER_HEIGHT + MODULE_LINE_HEIGHT
        n = min(MODULE_MAX_SEAM_BULLETS, len(terms))
        if len(terms) > MODULE_MAX_SEAM_BULLETS:
            n += 1
        return max(MODULE_CELL_MIN_HEIGHT, MODULE_HEADER_HEIGHT + n * MODULE_LINE_HEIGHT + 24)

    def external_deps(self) -> List[str]:
        parent = path_parent(self.name)
        return [d for d in self.dependencies if d != parent]

    def purpose_line(self) -> str:
        purpose = self.description.strip() or '{one-line purpose}'
        purpose_line = purpose.splitlines()[0].strip()
        if len(purpose_line) > MODULE_PURPOSE_MAX_CHARS:
            purpose_line = purpose_line[:MODULE_PURPOSE_MAX_CHARS - 1].rstrip() + '...'
        return purpose_line

    def shown_seam_terms(self) -> List[str]:
        terms = self.public_terms()
        shown = terms[:MODULE_MAX_SEAM_BULLETS]
        if len(terms) > MODULE_MAX_SEAM_BULLETS:
            return shown + ['...']
        return shown

class DiagramNode(ABC):
    """One placed cell. HTML vs Mermaid is the channel; the box is shared."""

    def __init__(self) -> None:
        self.geometry = Geometry(0, 0, CELL_WIDTH, CELL_MIN_HEIGHT)
        self.cell_id = ''
        self.parent_id = '1'
        self._previous_boxes: Dict[str, Tuple[float, float, float, float]] = {}

    @abstractmethod
    def height(self) -> int:
        ...

    def keep_or_place(self, default: Geometry) -> Geometry:
        saved = self._previous_boxes.get(self.cell_id)
        if saved is None:
            return default
        return Geometry(saved[0], saved[1], saved[2], saved[3])

    def draw(self, page) -> object:
        self.geometry = self.keep_or_place(self.geometry)
        return page.place(self)

class ImportedClass(DiagramClass):
    """Compact card for a class owned by another aggregate."""

    def __init__(
        self,
        name: str = '',
        sequential_order: int = 1,
        from_module: str = '',
        **kwargs,
    ) -> None:
        super().__init__(name, sequential_order, **kwargs)
        self.from_module = from_module

    def height(self) -> int:
        n = min(4, len(self.properties)) + 2
        return max(CELL_MIN_HEIGHT - 10, 30 + n * LINE_HEIGHT + 2 * SECTION_PAD)

    def key_properties(self):
        return self.properties[:4]

class Geometry(NamedTuple):
    """x, y, width, height of one placed node."""

    x: float
    y: float
    width: float
    height: float

    def overlaps(self, other: 'Geometry') -> bool:
        return not (
            self.x + self.width <= other.x
            or other.x + other.width <= self.x
            or self.y + self.height <= other.y
            or other.y + other.height <= self.y
        )

    def shifted(self, dx: float, dy: float) -> 'Geometry':
        return Geometry(self.x + dx, self.y + dy, self.width, self.height)

