        self.sequential_order = source.sequential_order
        self.scope = source.scope
        self.story_references = source.story_references
        self.object_references = source.object_references
        self.context.translate_from(source.context)
        self.transitions.translate_from(source.transitions)
        self.content_types.translate_from(source.content_types)
        self.nav_components.translate_from(source.nav_components)

    def child_collections(self, source: "UxMap") -> List[ChildCollectionPair]:
        return [
            ChildCollectionPair(
                self_children=self.screens,
                source_children=source.screens,
                load=self.load_screen,
            ),
        ]

    def load_screen(self, source: Screen) -> Screen:
        return Screen(source.name, source.sequential_order, source.slug, source.layout)

    def snapshot_fields(self) -> dict:
        return {
            "scope": self.scope,
            "story_references": self.story_references.as_list(),
            "object_references": self.object_references.as_list(),
        }

    def all_story_names(self) -> List[str]:
        names: List[str] = []
        for screen in self.screens:
            for story_name in screen.story_names:
                if story_name not in names:
                    names.append(story_name)
        return names

class Workspace:
    """Everything a scanner needs, already parsed."""

    root: Path
    story_map: StoryMap
    scenarios: List[Scenario] = field(default_factory=list)
    test_suites: List[TestSuite] = field(default_factory=list)
    story_contexts: List[StoryContext] = field(default_factory=list)

    @classmethod
    def load(cls, root: Path) -> "Workspace":
        """Discover and parse every artifact kind under *root*."""
        return cls._from_root(Path(root).resolve())

    @classmethod
    def _from_root(cls, root: Path) -> "Workspace":
        loader = cls(root=root, story_map=StoryMap())
        story_map = loader._discover_story_map(root)
        scenarios = loader._load_scenarios(root, story_map)
        test_suites = loader._load_test_suites(root, story_map)
        return cls(
            root=root,
            story_map=story_map,
            scenarios=scenarios,
            test_suites=test_suites,
            story_contexts=StoryContext.from_workspace(root),
        )

    def _discover_story_map(self, root: Path) -> StoryMap:
        from practices.stories.model.json.nodes import JsonStoryMap
        from practices.stories.model.markdown.nodes import MarkdownStoryMap

        story_map_root = root.parent if root.is_file() else root
        story_map_file = self._story_map_markdown_path(story_map_root)
        if story_map_file:
            loaded = MarkdownStoryMap.from_workspace(story_map_file)
            if loaded:
                return loaded
        return (
            JsonStoryMap.from_workspace(story_map_root)
            or MarkdownStoryMap.from_workspace(story_map_root)
            or StoryMap()
        )

    def _story_map_markdown_path(self, story_map_root: Path) -> Path | None:
        story_map_dir = story_map_root
        while story_map_dir and story_map_dir != story_map_dir.parent:
            candidate = story_map_dir / "story-map.md"
            if candidate.exists():
                return candidate
            story_map_dir = story_map_dir.parent
        return None

    def _load_scenarios(self, root: Path, story_map: StoryMap) -> List[Scenario]:
        from practices.stories.model.markdown.nodes import MarkdownIncrement, MarkdownScenario

        scenarios = MarkdownScenario.from_workspace(root)
        story_map.attach_scenarios(scenarios)
        if not story_map.increments:
            for inc in MarkdownIncrement.from_workspace(root):
                story_map.increments.append(inc)
        return scenarios

    def _load_test_suites(self, root: Path, story_map: StoryMap) -> List[TestSuite]:
        from practices.stories.model.java.nodes import JavaStoryMap
        from practices.stories.model.javascript.nodes import JavaScriptStoryMap
        from practices.stories.model.python.nodes import PythonStoryMap
        from practices.stories.model.typescript.nodes import TypeScriptStoryMap

        test_suites: List[TestSuite] = []
        for channel in (
            TypeScriptStoryMap,
            JavaScriptStoryMap,
            PythonStoryMap,
            JavaStoryMap,
        ):
            test_suites.extend(channel.from_workspace(root))
        story_map.attach_test_suites(test_suites)
        return test_suites

    # -- canonical guards ----------------------------------------------------

    def has_story_map(self) -> bool:
        try:
            return bool(self.story_map and getattr(self.story_map, "epics", None))
        except Exception:
            return False

    def has_increments(self) -> bool:
        return bool(getattr(self.story_map, "increments", None))

    def has_scenarios(self) -> bool:
        return bool(self.scenarios)

    def has_test_suites(self) -> bool:
        return bool(self.test_suites)

    def has_story_contexts(self) -> bool:
        return bool(self.story_contexts)

    # -- convenience views ---------------------------------------------------

    @property
    def increments(self) -> List[Increment]:
        """Flat list of Increments living on `story_map.increments`."""
        return list(getattr(self.story_map, "increments", []) or [])

    @property
    def tests(self) -> List[TestSuite]:
        """Alias for `test_suites` - scanner-facing name for the flat suite list."""
        return list(self.test_suites)

    def iter_test_cases(self) -> Iterator:
        """Yield every TestCase across every TestSuite (rarely useful; scanners
        usually walk `suite.cases` themselves)."""
        for suite in self.test_suites:
            for case in suite.cases:
                yield case

