    def __init__(
        self,
        repo: Repo,
        workflow: Workflow | None = None,
        issue: Ticket | None = None,
    ) -> None:
        self.repo = repo
        self.workflow = workflow
        self._issue = issue
        self._type = issue.issue_type if issue is not None else ""
        self._theme = self._theme_from_issue(issue)

    @staticmethod
    def _theme_from_issue(issue: Ticket | None) -> str:
        if issue is None:
            return ""
        for label in issue.labels:
            if label.startswith("theme:"):
                return label.split(":", 1)[1]
        return ""

    @property
    def issue(self) -> Ticket | None:
        return self._issue

    @property
    def number(self) -> int:
        return 0 if self._issue is None else self._issue.number

    @property
    def title(self) -> str:
        return "" if self._issue is None else self._issue.title

    @property
    def body(self) -> str:
        return "" if self._issue is None else self._issue.body

    @property
    def url(self) -> str:
        return "" if self._issue is None else self._issue.url

    @property
    def type(self) -> str:
        if self._type:
            return self._type
        if self._issue is not None:
            return self._issue.issue_type
        return ""

    @property
    def theme(self) -> str:
        return self._theme

    @property
    def state(self) -> str:
        if self._issue is None:
            return ""
        if self._issue.state is not None:
            return self._issue.state.name
        return self.repo._ticket_project_state.get(self._issue.number, "")

    @classmethod
    def resolve_type(cls, category: str) -> str:
        text = (category or "").strip()
        if not text:
            return ""
        key = " ".join(text.lower().replace("_", " ").replace("-", " ").split())
        if key in cls.TYPE_ALIASES:
            return cls.TYPE_ALIASES[key]
        for name in cls.TYPES:
            if name.lower() == text.lower():
                return name
        raise ValueError(
            f"unknown ticket type {category!r}; use defect, small change, refactor, or feature"
        )

    @classmethod
    def infer_type(cls, text: str) -> str:
        blob = (text or "").lower()
        if any(marker in blob for marker in cls._DEFECT_MARKERS):
            return "Defect"
        if any(marker in blob for marker in cls._REFACTOR_MARKERS):
            return "Refactor"
        if any(marker in blob for marker in cls._SMALL_CHANGE_MARKERS):
            return "Small change"
        if any(marker in blob for marker in cls._FEATURE_MARKERS):
            return "Feature"
        return "Small change"

    @classmethod
    def _workflow_packages_path(cls, repo_root: Path | str | None) -> Path | None:
        if not repo_root:
            return None
        path = Path(repo_root) / ".context" / "workflow-packages.yaml"
        return path if path.is_file() else None

    @classmethod
    def _package_entries(cls, repo_root: Path | str | None = None) -> list[dict[str, str]]:
        path = cls._workflow_packages_path(repo_root)
        if path is None:
            return []
        payload = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
        packages = payload.get("packages") if isinstance(payload, dict) else None
        if not isinstance(packages, list):
            return []
        entries: list[dict[str, str]] = []
        for item in packages:
            if not isinstance(item, dict):
                continue
            location = str(item.get("location") or "").strip()
            theme = str(item.get("theme") or "").strip()
            layer = str(item.get("layer") or "").strip()
            if location and theme:
                entries.append(
                    {"location": location, "theme": theme, "layer": layer}
                )
        return entries

    @classmethod
    def infer_theme(cls, text: str, repo_root: Path | str | None = None) -> str:
        blob = (text or "").replace("\\", "/")
        for entry in cls._package_entries(repo_root):
            location = entry["location"]
            if location in blob:
                return entry["theme"]
            layer = entry.get("layer") or ""
            if layer and layer.lower() in blob.lower():
                return entry["theme"]
        for theme in sorted(cls.THEMES, key=len, reverse=True):
            pattern = rf"\b{theme.replace('-', '[- ]')}\b"
            if re.search(pattern, blob, re.IGNORECASE):
                return theme
        return ""

    def ensure_types(self) -> list[str]:
        """Create org issue types the repo is missing."""
        existing = {
            str(item.get("name", "")).lower()
            for item in self.repo.list_issue_types()
        }
        added: list[str] = []
        for name, description, color in self.REQUIRED_TYPES:
            self.repo.ensure_issue_type(name, description=description, color=color)
            if name.lower() not in existing:
                added.append(name)
        return added

    def set_type(self, category: str) -> WorkTicket:
        name = self.resolve_type(category)
        self._type = name
        if name and self._issue is not None:
            self._issue.write_type(name)
        return self

    def set_theme(self, theme: str) -> WorkTicket:
        slug = (theme or "").strip()
        if slug.lower().startswith("theme:"):
            slug = slug.split(":", 1)[1].strip()
        self._theme = slug
        if slug and self._issue is not None:
            self._issue.add_theme(slug)
        return self

    def create(
        self,
        title: str,
        body: str,
        *,
        type: str = "",
        theme: str = "",
        status: str = "Backlog",
        infer_from: str = "",
    ) -> WorkTicket:
        self.ensure_types()
        clue = infer_from or f"{title}\n{body}"
        resolved_type = self.resolve_type(type) if type.strip() else self.infer_type(clue)
        resolved_theme = theme.strip() or self.infer_theme(clue, repo_root=self.repo.root)
        if resolved_theme.lower().startswith("theme:"):
            resolved_theme = resolved_theme.split(":", 1)[1].strip()
        issue = self.repo.create_ticket(title, body)
        issue.set_status(status)
        self._issue = issue
        if resolved_type:
            self.set_type(resolved_type)
        if resolved_theme:
            self.set_theme(resolved_theme)
        return self

    def as_dict(self, project_status: str = "") -> dict[str, str | int]:
        status = project_status or self.state
        payload: dict[str, str | int] = {
            "number": self.number,
            "title": self.title,
            "body": self.body,
            "url": self.url,
            "project_status": status,
        }
        if self.theme:
            label = issue_theme_label(self.theme)
            payload["theme"] = label
            if self._issue is not None and self._issue.labels:
                payload["labels"] = ", ".join(self._issue.labels)
        if self.type:
            payload["category"] = self.type
            payload["type"] = self.type
        return payload

class Workflow:
    """Slash /backlog, /start-ticket, /finish-ticket — GitHub issue + session lifecycle."""

    def __init__(
        self,
        workspace: str = "",
        *,
        repo: Repo | None = None,
    ) -> None:
        self._workspace_path = workspace.strip()
        self._repo_override = repo
        self._workspaces: dict[str, Workspace] = {}
        self._repos: dict[str, Repo] = {}

    def _repo_root(self, workspace: str = "") -> Path:
        start = workspace.strip() or self._workspace_path or "."
        root = Repo(start).find_root()
        if root is None:
            raise ValueError(f"not a git clone: {start!r}")
        return root

    def _repo(self, workspace: str = "") -> Repo:
        if self._repo_override is not None:
            return self._repo_override
        root = str(self._repo_root(workspace))
        cached = self._repos.get(root)
        if cached is not None:
            return cached
        repo = Repo.open(root)
        self._repos[root] = repo
        return repo

    def _workspace(self, workspace: str = "") -> Workspace:
        root = str(self._repo_root(workspace))
        cached = self._workspaces.get(root)
        if cached is not None:
            return cached
        ws = Workspace(root)
        ws.load()
        self._workspaces[root] = ws
        return ws

    def _kebab(self, text: str) -> str:
        cleaned = "".join(ch.lower() if ch.isalnum() else "-" for ch in text.strip())
        while "--" in cleaned:
            cleaned = cleaned.replace("--", "-")
        return cleaned.strip("-") or "idea"

    def _session_name_from_issue(self, title: str, number: int) -> str:
        slug = self._kebab(title)
        return f"{slug}-{number}" if slug else f"issue-{number}"

    def _ticket_from_session_name(self, session_name: str) -> str:
        """Trailing ``-{n}`` on the work-session slug is the GitHub issue number."""
        match = re.search(r"-(\d+)$", (session_name or "").strip())
        return match.group(1) if match else ""

    def _resolve_finish_ticket(self, ticket: str, session_name: str) -> str:
        resolved = (ticket or "").strip() or self._ticket_from_session_name(session_name)
        if not resolved:
            raise ValueError(
                "finish-ticket needs a ticket (pass ticket=) or a session name ending "
                "in -{issue-number} so the project card can move to Done"
            )
        return resolved

    def _workflow_config_path(self, repo_root: Path) -> Path:
        return repo_root / ".context" / "workflow.yaml"

    def _workflow_rules_path(self, repo_root: Path) -> Path:
        return repo_root / ".context" / "workflow-rules.yaml"

    def _load_workflow_rules(self, workspace: str = "") -> list[str]:
        """Read the repo's agentic workflow rules; empty when the file is absent."""
        path = self._workflow_rules_path(self._repo_root(workspace))
        if not path.is_file():
            return []
        payload = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
        rules = payload.get("rules") if isinstance(payload, dict) else payload
        return [str(rule).strip() for rule in (rules or []) if str(rule).strip()]

    def _load_workflow_config(self, repo_root: Path) -> WorkflowConfig:
        path = self._workflow_config_path(repo_root)
        if not path.is_file():
            raise FileNotFoundError(
                f"missing workflow config: {path.as_posix()} "
                "(need project_owner and project_number)"
            )
        payload = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
        owner = str(payload.get("project_owner") or "").strip()
        number = payload.get("project_number")
        if not owner or number is None:
            raise ValueError(
                "workflow.yaml requires project_owner and project_number"
            )
        return WorkflowConfig(
            project_owner=owner,
            project_number=int(number),
            default_branch=str(payload.get("default_branch") or "main").strip()
            or "main",
        )

    def _ensure_project(self, repo: Repo, repo_root: Path):
        if repo.project is not None:
            repo.project.refresh_states()
            return repo.project
        config = self._load_workflow_config(repo_root)
        return repo.attach_project(config.project_owner, config.project_number)

    @agent_tool
    @mcp
    @skill
    def backlog(
        self,
        focus: str,
        context: str = "",
        workspace: str = "",
        theme: str = "",
        category: str = "",
        body: str = "",
    ) -> dict[str, str | int]:
        """Capture an idea on the backlog — GitHub issue + Project Backlog.

        With no ``body``, commits the current turn, builds the handoff, and returns
        a ``sub_agent_task``. Launch a non-blocking sub-agent with that prompt; it
        calls this same tool again with the enriched ``body`` to file the issue.

        Infer `category` and `theme` unless the user sets them. Types:

        - Defect: unexpected or wrong current behavior (the kit should already do this).
        - Small change: a change to an existing feature, utility, or tool. Those are all Small changes unless the addition is very large.
        - Refactor: changing code and where things are without changing functionality.
        - Feature: standing up a new module (a new folder). Example: creating the CLI agent. A small change to an existing feature is not a Feature.
        """
        if body.strip():
            return self._create_backlog_issue(
                focus=focus,
                body=body,
                workspace=workspace,
                theme=theme,
                category=category,
                infer_from=f"{focus}\n{body}",
            )
        destination = str(self._repo_root(workspace))

        self._commit_if_dirty(workspace, focus)
        transcript_path = self._find_transcript_path(workspace)

        handoff = self._handoff()
        handoff_md = handoff._render_handoff_markdown(
            handoff._collect_state(destination), next_focus=focus
        )
        body = self._backlog_issue_body(handoff_md, focus=focus, context=context)

        return {
            "committed": "yes",
            "tools": "workflow.workflow:Workflow",
            "sub_agent_task": self._backlog_task_prompt(
                focus=focus,
                body=body,
                workspace=destination,
                theme=theme,
                category=category,
                infer_from=f"{focus}\n{context}",
                transcript_path=transcript_path,
            ),
        }

    def _backlog_issue_body(self, handoff_md: str, focus: str, context: str) -> str:
        parts = [(handoff_md or "").strip()]
        request: list[str] = []
        if focus.strip():
            request.append(f"**Focus:** {focus.strip()}")
        if context.strip():
            request.append(context.strip())
        if request:
            parts.extend(["", "## Request", "", *request])
        return "\n".join(part for part in parts if part is not None).strip() + "\n"

    def _find_transcript_path(self, workspace: str = "") -> str:
        """Locate the most recent Cursor agent transcript for this workspace."""
        try:
            root = self._repo_root(workspace)
            raw = str(root.resolve())
            slug = raw.replace(":", "").replace("\\", "-").replace("/", "-").lower()
            transcripts_dir = Path.home() / ".cursor" / "projects" / slug / "agent-transcripts"
            if not transcripts_dir.is_dir():
                return ""
            files = sorted(
                transcripts_dir.rglob("*.jsonl"),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            return str(files[0]) if files else ""
        except Exception:
            return ""

    def _commit_if_dirty(self, workspace: str = "", focus: str = "") -> str:
        """Commit staged/tracked changes to close the current turn before staging the backlog."""
        try:
            ws = self._workspace(workspace)
            session = ws.current_work_session
            repo = self._repo(workspace)
            if not repo.is_dirty(untracked=False):
                return repo.current_commit
            subject = (
                f"backlog: {focus.strip()[:60]}" if focus.strip() else "backlog: close turn"
            )
            if session is not None:
                turn = session.open_turn or Turn(root=str(repo.root))
                turn.turn(
                    commit_message=subject,
                    utility="backlog",
                    subject=session.name,
                )
            return repo.current_commit
        except Exception:
            try:
                return self._repo(workspace).current_commit
            except Exception:
                return ""

    def _backlog_task_prompt(
        self,
        focus: str,
        body: str,
        workspace: str,
        theme: str,
        category: str,
        infer_from: str,
        transcript_path: str,
    ) -> str:
        """Build the task prompt for the backlog sub-agent."""
        lines = [f"Backlog task — {focus!r}", ""]
        if transcript_path:
            lines += [
                f"Transcript: {transcript_path}",
                "",
                "Read the transcript and identify which chat turn first noticed this issue.",
                "Determine whether the change that caused it is in the current commit",
                "(shown in the Turn Context below) or an earlier one, and note the branch",
                "and commit SHA. Update the Turn Context section in the body accordingly.",
                "",
            ]
        lines += [
            "Then call backlog with:",
            f"  focus: {focus!r}",
            f"  body: (the body below, updated with transcript findings)",
            f"  workspace: {workspace!r}",
            f"  theme: {theme!r}",
            f"  category: {category!r}",
            "",
            "--- body ---",
            body.rstrip(),
        ]
        return "\n".join(lines)

    def _create_backlog_issue(
        self,
        focus: str,
        body: str,
        workspace: str = "",
        theme: str = "",
        category: str = "",
        infer_from: str = "",
    ) -> dict[str, str | int]:
        issue_body = self._handoff_issue_body(body)
        return self.create_ticket(
            title=focus.strip() or "backlog",
            body=issue_body,
            workspace=workspace,
            project_status="Backlog",
            theme=theme,
            category=category,
            infer_from=infer_from or f"{focus}\n{body}",
        )

    def _handoff_issue_body(self, body: str) -> str:
        text = body.strip()
        path = Path(text)
        if text and path.is_file():
            text = path.read_text(encoding="utf-8")
        return text


    @agent_tool
    @mcp
    @skill
    def start(
        self,
        ticket: str,
        instructions: str = "",
        workspace: str = "",
        copy_body: bool = False,
        workflow_state: str = "specification",
    ) -> dict[str, str | int]:
        """Start work from a GitHub issue — In Progress, WorkSession, session branch.

        ``kind: sub_agent`` / ``launch: non_blocking`` — the parent launches a sub-agent
        for this operation and does not wait. Inside that sub-agent, run start (In Progress,
        open WorkSession, session branch) then continue the ticket work.
        """
        viewed = self.view_ticket(ticket, workspace=workspace)
        self.set_ticket_project_status(ticket, "In Progress", workspace=workspace)
        opened = self.open_ticket_session(
            ticket,
            instructions=instructions,
            workspace=workspace,
            workflow_state=workflow_state,
        )
        if copy_body:
            self.copy_issue_body_to_session(
                ticket, str(opened["session_name"]), workspace=workspace
            )
        ws = self._workspace(workspace)
        session = ws.current_work_session
        if session is not None and session.git.is_dirty(untracked=False):
            message = self.turn_commit_message(
                subject=f"start {session.name}",
                ticket=ticket,
                workflow_state=workflow_state,
                workspace=workspace,
            )
            turn = session.open_turn or Turn(root=str(session.git.root))
            turn.turn(commit_message=message, utility="start-ticket")
        if session is not None:
            session.git.checkout_or_create(session.session_branch)
        return {**viewed, **opened}

    @agent_tool
    @mcp
    @skill
    def finish(
        self,
        outcome: str = "",
        workspace: str = "",
        ticket: str = "",
        reviewed_by: str = "",
    ) -> dict[str, str]:
        """Finish the open WorkSession — merge to main, Done on the project board, close issue, close session.

        Always moves the GitHub Project Status to **Done** (not issue-closed alone).
        Pass ``ticket`` or rely on the session slug's trailing ``-{issue}``.

        Before calling: in the session worktree run ``git status``. Delete only temps
        you know are ephemeral from this session (deploy output, agent BDD run logs,
        scratch request files). Use session context — do not delete durable artifacts.
        Then call finish so merge and worktree removal can proceed on a clean tree.
        """
        session_name = self.require_open_session(workspace=workspace)
        resolved_ticket = self._resolve_finish_ticket(ticket, session_name)
        ws = self._workspace(workspace)
        session = ws.current_work_session
        if session is not None and session.git.is_dirty(untracked=False):
            Turn(root=str(session.git.root)).turn(
                message=outcome or "finish",
                utility="finish-ticket",
                subject=session_name,
            )
            session.open_turn = None
        sha = self.merge_session_to_main(
            workspace=workspace, ticket=resolved_ticket, reviewed_by=reviewed_by
        )
        # Always move the Kanban Status to Done, then close the GitHub issue.
        self.set_ticket_project_status(resolved_ticket, "Done", workspace=workspace)
        self.close_ticket(resolved_ticket, workspace=workspace)
        if session is not None:
            session.close_session(outcome=outcome or "finished")
        return {
            "commit": sha,
            "session_name": session_name,
            "ticket": resolved_ticket,
            "project_status": "Done",
        }

    def _handoff(self) -> Handoff:
        return Handoff()

    def workspace_tool(self, path: str = "") -> Workspace:
        return self._workspace(path)

    def load_project_config(self, workspace: str = "") -> dict[str, str | int]:
        repo_root = self._repo_root(workspace)
        config = self._load_workflow_config(repo_root)
        return {
            "project_owner": config.project_owner,
            "project_number": config.project_number,
            "default_branch": config.default_branch,
        }

    @agent_tool
    def read_ticket_rules(self, workspace: str = "") -> dict[str, object]:
        """Read the repo's workflow rules that govern every ticket action."""
        return {"rules": self._load_workflow_rules(workspace)}

    @agent_tool
    @mcp
    @skill
    def update_ticket_labels(
        self,
        ticket: str,
        add: str = "",
        remove: str = "",
        workspace: str = "",
    ) -> dict[str, str | int]:
        """Update ticket labels: add and/or remove comma-separated labels."""
        issue = self._require_ticket(self._repo(workspace), ticket)
        for label in (part.strip() for part in remove.split(",")):
            issue.remove_label(label)
        for label in (part.strip() for part in add.split(",")):
            issue.add_label(label)
        return {
            "number": issue.number,
            "title": issue.title,
            "labels": ", ".join(sorted(set(issue.labels))),
        }

    @skill(name="tickets")
    @mcp
    @agent_instructions
    def manage_tickets(self, request: str, workspace: str = "") -> str:
        """Manage project tickets from {{request}}.

        Start by calling read_ticket_rules and follow every rule it returns; the repo's
        rules override defaults. Display each available ticket tool name and purpose
        before acting. Call list_project_statuses when you need the board columns.
        Then review ticket statuses so board state and left-to-right column order are
        known. Then call only the tool needed to move a ticket, add a
        child ticket, merge a completed child into its parent, update a ticket, update
        labels, align children to parent, or report board status. Never infer a ticket
        number when the request is ambiguous.
        """
        self.read_ticket_rules(workspace=workspace)
        self.review_ticket_statuses(workspace=workspace)
        self.move_ticket(ticket="", destination="", workspace=workspace)
        self.add_child_ticket(parent="", title="", workspace=workspace)
        self.merge_child_into_parent(child="", summary="", workspace=workspace)
        self.update_ticket(ticket="", workspace=workspace)
        self.update_ticket_labels(ticket="", workspace=workspace)
        self.align_child_tickets_to_parent(parent="", workspace=workspace)
        return "Ticket request completed."

    def parse_ticket(self, ticket: str) -> int:
        return Ticket.from_number(ticket)

    def session_name_for_issue(self, title: str, number: int) -> str:
        return self._session_name_from_issue(title, number)

    def turn_commit_message(
        self,
        subject: str,
        ticket: str,
        workflow_state: str,
        workspace: str = "",
        reviewed_by: str = "",
    ) -> str:
        repo = self._repo(workspace)
        return repo.workflow_commit_message(
            subject,
            Ticket.from_number(ticket),
            workflow_state,
            reviewed_by=reviewed_by,
        )

    def view_ticket(self, ticket: str, workspace: str = "") -> dict[str, str | int]:
        repo = self._repo(workspace)
        issue = repo.ticket(ticket)
        if issue is None:
            raise TicketNotFoundError(f"GitHub issue not found: {ticket}")
        return {
            "number": issue.number,
            "title": issue.title,
            "body": issue.body,
            "url": issue.url,
        }

    @agent_tool
    @mcp
    def list_project_statuses(self, workspace: str = "") -> dict[str, object]:
        """List GitHub Project Status columns left-to-right for move_ticket destinations."""
        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        project = self._ensure_project(repo, repo_root)
        statuses = project.status_option_names()
        return {
            "project": f"{project.owner}#{project.number}",
            "statuses": statuses,
            "hint": "Pass any status name to move_ticket(destination=...), or use next/previous.",
        }

    @agent_tool
    @mcp
    @skill
    def move_ticket(
        self,
        ticket: str,
        destination: str,
        workspace: str = "",
        align_children: bool = True,
    ) -> dict[str, object]:
        """Move a ticket to any Project Status column, or to next/previous. Follow the repo workflow rules (read_ticket_rules)."""
        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        project = self._ensure_project(repo, repo_root)
        issue = self._require_ticket(repo, ticket)
        status = self._destination_status(project, issue.number, destination)
        issue.set_status(status)
        result: dict[str, object] = {
            **self.view_ticket(ticket, workspace),
            "project_status": status,
        }
        if align_children:
            aligned = self._align_child_tickets_for_parent(
                project, issue, workspace, self._board_status_map(project)
            )
            if aligned:
                result["aligned_children"] = aligned
        return result

    def _destination_status(self, project, ticket_number: int, destination: str) -> str:
        requested = destination.strip()
        if not requested:
            raise ValueError("destination requires a board state, next, or previous")
        direction = requested.lower()
        if direction not in ("next", "previous", "prev"):
            return project.state_named(requested).name
        statuses = project.status_option_names()
        current = self._ticket_status(project, ticket_number)
        if not current:
            raise ValueError(f"ticket {ticket_number} is not on the project board")
        index = statuses.index(current)
        offset = 1 if direction == "next" else -1
        target = max(0, min(index + offset, len(statuses) - 1))
        return statuses[target]

    def _ticket_status(self, project, ticket_number: int) -> str:
        for row in project.ticket_rows():
            if row["number"] == ticket_number:
                return str(row["status"])
        return ""

    @agent_tool
    def add_child_ticket(
        self,
        parent: str,
        title: str,
        body: str = "",
        workspace: str = "",
        project_status: str = "Backlog",
        theme: str = "",
        category: str = "",
    ) -> dict[str, str | int]:
        """Create a project ticket and attach it as a direct child of a parent issue. Follow the repo workflow rules (read_ticket_rules)."""
        repo = self._repo(workspace)
        parent_issue = self._require_ticket(repo, parent)
        created = self.create_ticket(
            title=title,
            body=body,
            workspace=workspace,
            project_status=project_status,
            theme=theme,
            category=category,
        )
        child = self._require_ticket(repo, str(created["number"]))
        parent_issue.add_child(child)
        project = self._ensure_project(repo, self._repo_root(workspace))
        ancestors = self._ticket_ancestors(repo, parent_issue)
        ultimate_parent = ancestors[-1]
        for issue in (child, *ancestors):
            project.write_text_field(issue.number, ultimate_parent.title)
        return {
            **created,
            "parent": parent_issue.number,
            "ultimate_parent": ultimate_parent.title,
        }

    def _ticket_ancestors(self, repo: Repo, issue: Ticket) -> list[Ticket]:
        ancestors = [issue]
        seen = {issue.number}
        while ancestors[-1].parent_number is not None:
            parent = self._require_ticket(repo, str(ancestors[-1].parent_number))
            if parent.number in seen:
                raise ValueError(f"cycle in ticket parents at {parent.number}")
            ancestors.append(parent)
            seen.add(parent.number)
        return ancestors

    @agent_tool
    def merge_child_into_parent(
        self,
        child: str,
        summary: str,
        workspace: str = "",
    ) -> dict[str, str | int]:
        """Roll a completed child result into its parent.

        Close and archive the child while preserving the sub-issue relationship.
        """
        repo = self._repo(workspace)
        child_issue = self._require_ticket(repo, child)
        if child_issue.parent_number is None:
            raise ValueError(f"ticket {child_issue.number} has no parent")
        parent = self._require_ticket(repo, str(child_issue.parent_number))
        result = summary.strip()
        if not result:
            raise ValueError("summary is required")
        child_link = child_issue.url or f"#{child_issue.number}"
        heading = f"## Completed child: [{child_issue.title}]({child_link})"
        merged_section = f"{heading}\n\n{result}"
        if heading not in parent.body:
            parent.update(body=f"{parent.body.rstrip()}\n\n{merged_section}\n")
        child_issue.comment(
            f"Result merged into parent #{parent.number}.\n\n{result}"
        )
        project = self._ensure_project(repo, self._repo_root(workspace))
        child_issue.set_status(project.state_named("Done").name)
        child_issue.close()
        project.archive_ticket(child_issue.number)
        return {
            "child": child_issue.number,
            "parent": parent.number,
            "project_status": "Done",
            "archived": "yes",
        }

    def _require_ticket(self, repo: Repo, ticket: str) -> Ticket:
        issue = repo.ticket(ticket)
        if issue is None:
            raise TicketNotFoundError(f"GitHub issue not found: {ticket}")
        return issue

    @agent_tool
    def update_ticket(
        self,
        ticket: str,
        title: str | None = None,
        body: str | None = None,
        workspace: str = "",
    ) -> dict[str, str | int]:
        """Update a ticket title and/or body; omitted values remain unchanged. Follow the repo workflow rules (read_ticket_rules)."""
        issue = self._require_ticket(self._repo(workspace), ticket)
        normalized_title = title.strip() if title is not None else None
        issue.update(title=normalized_title, body=body)
        return self.view_ticket(ticket, workspace)

    @agent_tool
    def review_ticket_statuses(
        self,
        workspace: str = "",
        status: str = "",
    ) -> dict[str, object]:
        """List project tickets by board columns from left to right, optionally filtered. Follow the repo workflow rules (read_ticket_rules)."""
        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        project = self._ensure_project(repo, repo_root)
        statuses = project.status_option_names()
        if status.strip():
            statuses = [project.state_named(status.strip()).name]
        rows = project.ticket_rows()
        columns = [self._ticket_column(name, rows) for name in statuses]
        return {
            "columns": columns,
            "total": sum(len(column["tickets"]) for column in columns),
        }

    @agent_tool
    def align_child_tickets_to_parent(
        self,
        parent: str = "",
        workspace: str = "",
    ) -> dict[str, object]:
        """Align child tickets so no child is in a board column prior to its parent. Follow the repo workflow rules (read_ticket_rules)."""
        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        project = self._ensure_project(repo, repo_root)
        aligned: list[dict[str, object]] = []

        if parent.strip():
            parent_issue = self._require_ticket(repo, parent)
            aligned.extend(
                self._align_child_tickets_for_parent(
                    project, parent_issue, workspace, self._board_status_map(project)
                )
            )
        else:
            statuses_by_number = self._board_status_map(project)
            for number in statuses_by_number:
                parent_issue = repo.ticket(str(number))
                if parent_issue and parent_issue.sub_issue_numbers:
                    aligned.extend(
                        self._align_child_tickets_for_parent(
                            project, parent_issue, workspace, statuses_by_number
                        )
                    )

        return {
            "parent": parent if parent.strip() else "all",
            "aligned": aligned,
            "total_aligned": len(aligned),
        }

    def _board_status_map(self, project) -> dict[int, str]:
        """Read the board once and map ticket number to its column."""
        return {
            int(row["number"]): str(row["status"])
            for row in project.ticket_rows()
        }

    def _align_child_tickets_for_parent(
        self,
        project,
        parent_issue: Ticket,
        workspace: str,
        statuses_by_number: dict[int, str],
    ) -> list[dict[str, object]]:
        aligned: list[dict[str, object]] = []
        parent_status = statuses_by_number.get(parent_issue.number, "")
        if not parent_status:
            return aligned
        statuses = project.status_option_names()
        if parent_status not in statuses:
            return aligned
        parent_idx = statuses.index(parent_status)

        repo = self._repo(workspace)
        for child_num in list(parent_issue.sub_issue_numbers):
            child_status = statuses_by_number.get(child_num, "")
            if not child_status or child_status not in statuses:
                continue
            child_idx = statuses.index(child_status)
            if child_idx < parent_idx:
                child_issue = repo.ticket(str(child_num))
                if child_issue:
                    child_issue.set_status(parent_status)
                    statuses_by_number[child_num] = parent_status
                    aligned.append(
                        {
                            "child": child_num,
                            "from_status": child_status,
                            "to_status": parent_status,
                        }
                    )
                    if child_issue.sub_issue_numbers:
                        aligned.extend(
                            self._align_child_tickets_for_parent(
                                project, child_issue, workspace, statuses_by_number
                            )
                        )
        return aligned

    def _ticket_column(
        self, status: str, rows: list[dict[str, str | int]]
    ) -> dict[str, object]:
        tickets = [row for row in rows if row["status"] == status]
        tickets.sort(key=lambda row: int(row["number"]))
        return {"status": status, "tickets": tickets}

    def create_ticket(
        self,
        title: str,
        body: str,
        workspace: str = "",
        project_status: str = "Backlog",
        theme: str = "",
        category: str = "",
        infer_from: str = "",
    ) -> dict[str, str | int]:
        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        self._ensure_project(repo, repo_root)
        work = WorkTicket(repo, self).create(
            title,
            body,
            type=category,
            theme=theme,
            status=project_status,
            infer_from=infer_from or f"{title}\n{body}",
        )
        return work.as_dict(project_status=project_status)

    def set_ticket_project_status(
        self,
        ticket: str,
        status: str,
        workspace: str = "",
    ) -> str:
        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        issue = repo.ticket(ticket)
        if issue is None:
            raise TicketNotFoundError(f"GitHub issue not found: {ticket}")
        self._ensure_project(repo, repo_root)
        issue.set_status(status)
        return status

    def copy_issue_body_to_session(
        self,
        ticket: str,
        session_name: str,
        workspace: str = "",
        filename: str = "issue-body.md",
    ) -> str:
        from workflow.work_ticket import format_session_ticket_context

        repo_root = self._repo_root(workspace)
        repo = self._repo(workspace)
        issue = repo.ticket(ticket)
        if issue is None:
            raise TicketNotFoundError(f"GitHub issue not found: {ticket}")
        session_folder = repo_root / ".sessions" / session_name
        session_folder.mkdir(parents=True, exist_ok=True)
        target = session_folder / filename
        body, _ = format_session_ticket_context(repo, issue.number)
        target.write_text(body or issue.body, encoding="utf-8")
        return str(target.resolve())

    def open_ticket_session(
        self,
        ticket: str,
        instructions: str = "",
        workspace: str = "",
        workflow_state: str = "specification",
    ) -> dict[str, str]:
        repo_root = self._repo_root(workspace)
        issue = self._repo(workspace).ticket(ticket)
        if issue is None:
            raise TicketNotFoundError(f"GitHub issue not found: {ticket}")
        session_name = self._session_name_from_issue(issue.title, issue.number)
        ws = self._workspace(workspace)
        git = NullGitRepo(repo_root) if self._repo_override is not None else None
        goal = instructions.strip() or issue.title
        session = ws.open_work_session(
            name=session_name,
            goal=goal,
            path=str(repo_root),
            git=git,
        )
        open_turn = session.turn
        open_turn.action = "start"
        if instructions.strip():
            open_turn.prompt = instructions.strip()
        return {
            "session_name": session.name,
            "branch": session.session_branch,
            "issue_number": str(issue.number),
            "issue_url": issue.url,
            "workflow_state": workflow_state,
        }

    def require_open_session(self, workspace: str = "") -> str:
        ws = self._workspace(workspace)
        session = ws.current_work_session
        if session is None:
            branch = self._repo(workspace).current_branch
            if isinstance(branch, str) and branch.startswith("session/"):
                ws.open(
                    name=branch[len("session/") :],
                    path=str(self._repo_root(workspace)),
                )
                session = ws.current_work_session
        if session is None:
            raise RuntimeError("no open work session")
        return session.name

    def merge_session_to_main(
        self,
        workspace: str = "",
        ticket: str = "",
        reviewed_by: str = "",
    ) -> str:
        ws = self._workspace(workspace)
        session = ws.current_work_session
        if session is None:
            raise RuntimeError("no open work session")
        if session.git.is_dirty(untracked=False):
            raise RuntimeError("working tree is dirty")
        config = self._load_workflow_config(self._repo_root(workspace))
        source = session.session_branch
        subject = f"finish {session.name}"
        message = subject
        if ticket.strip():
            message = self._repo(workspace).workflow_commit_message(
                subject,
                Ticket.from_number(ticket),
                "done",
                reviewed_by=reviewed_by,
            )
        session.git.merge_branch(source, config.default_branch, message=message)
        return session.git.current_commit

    def close_ticket(self, ticket: str, workspace: str = "") -> str:
        issue = self._repo(workspace).ticket(ticket)
        if issue is None:
            raise TicketNotFoundError(f"GitHub issue not found: {ticket}")
        issue.close()
        return f"closed {ticket}"

class JsonStoryMap(StoryMap):
    """JSON story-map I/O. IS the format-typed tree root.

    parse / render / sync implement the Uniform Callable Surface.
    Factory overrides ensure every child is Json-typed throughout the tree.
    """

    def load_epic(self, source: JsonEpic) -> JsonEpic:
        return JsonEpic(source.name, source.sequential_order)

    def load_increment(self, source: Increment) -> JsonIncrement:
        return JsonIncrement(source.name, source.sequential_order)

    # -- Uniform Callable Surface ----------------------------------------------

    def render(self, story_map: "JsonStoryMap", previous: Optional[str] = None) -> str:
        payload: Dict[str, Any] = {
            "epics": [self._epic_to_dict(e) for e in story_map.epics],
        }
        if story_map.increments:
            payload["increments"] = [
                self._increment_to_dict(i) for i in story_map.increments
            ]
        return json.dumps(payload, indent=2)

    def parse(self, text: str) -> "JsonStoryMap":
        try:
            payload = json.loads(text)
        except json.JSONDecodeError as err:
            raise JsonParseError(f"Not valid JSON: {err}") from err
        self._guard_schema(payload)
        story_map = JsonStoryMap()
        for epic_dict in payload.get("epics", []):
            story_map.epics.append(self._epic_from_dict(epic_dict))
        for inc_dict in payload.get("increments", []):
            story_map.increments.append(self._increment_from_dict(inc_dict))
        return story_map

    def sync(self, text: str, canonical: "JsonStoryMap") -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    def attach_source_locations(self, file_name: str) -> None:
        """Stamp a single SourceLocation (the JSON file) onto every node."""
        loc = SourceLocation(file_name, 0)
        for epic in self.epics:
            epic.source = loc
        for sub in self.all_sub_epics():
            sub.source = loc
        for story in self.all_stories():
            story.source = loc

    @classmethod
    def from_workspace(cls, root: "Path") -> Optional["JsonStoryMap"]:
        """Find story-graph.json in *root* and parse it; return None if absent."""
        from pathlib import Path as _Path
        root = _Path(root).resolve()
        json_path = root / "story-graph.json"
        if not json_path.exists():
            return None
        try:
            text = json_path.read_text(encoding="utf-8")
            sm = cls().parse(text)
            sm.attach_source_locations(json_path.name)
            sm.source = SourceLocation(json_path.name, 1)
            return sm
        except Exception:
            return None

    # -- render helpers --------------------------------------------------------

    def _epic_to_dict(self, epic: JsonEpic) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "name": epic.name,
            "sequentialOrder": epic.sequential_order,
            "subEpics": [self._sub_epic_to_dict(s) for s in epic.sub_epics],
        }
        if epic.estimate:
            payload["estimate"] = epic.estimate
        factories = list(getattr(epic, "example_factories", None) or [])
        if factories:
            payload["exampleFactories"] = factories
        return payload

    def _sub_epic_to_dict(self, sub_epic: JsonSubEpic) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "name": sub_epic.name,
            "sequentialOrder": sub_epic.sequential_order,
            "subEpics": [self._sub_epic_to_dict(s) for s in sub_epic.sub_epics],
            "stories": [self._story_to_dict(s) for s in sub_epic.stories],
        }
        if sub_epic.estimate:
            payload["estimate"] = sub_epic.estimate
        factories = list(getattr(sub_epic, "example_factories", None) or [])
        if factories:
            payload["exampleFactories"] = factories
        return payload

    def _story_to_dict(self, story: JsonStory) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "name": story.name,
            "sequentialOrder": story.sequential_order,
            "storyType": story.story_type.value,
            "scenarios": [self._scenario_to_dict(s) for s in story.scenarios],
        }
        if story.users:
            payload["users"] = list(story.users)
        if getattr(story, "domain_terms", None):
            payload["domainTerms"] = list(story.domain_terms)
        if getattr(story, "evidence", None):
            payload["evidence"] = list(story.evidence)
        return payload

    def _scenario_to_dict(self, scenario: JsonScenario) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "name": scenario.name,
            "sequentialOrder": scenario.sequential_order,
        }
        rows = list(getattr(scenario, "example_rows", None) or [])
        if rows:
            payload["exampleRows"] = rows
        return payload

    def _increment_to_dict(self, inc: JsonIncrement) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "name": inc.name,
            "sequentialOrder": inc.sequential_order,
            "stories": list(inc.stories),
        }
        if inc.outcome:
            payload["outcome"] = inc.outcome
        if inc.decision_prompt:
            payload["decisionPrompt"] = inc.decision_prompt
        if inc.slicing_notes:
            payload["slicingNotes"] = inc.slicing_notes
        return payload

    # -- parse helpers ---------------------------------------------------------

    def _guard_schema(self, payload: Any) -> None:
        if not isinstance(payload, dict):
            raise JsonParseError("Root must be an object")
        if "epics" not in payload:
            raise JsonParseError("Missing required 'epics' key")
        if not isinstance(payload["epics"], list):
            raise JsonParseError("'epics' must be a list")

    def _epic_from_dict(self, epic_record: Dict[str, Any]) -> JsonEpic:
        epic = JsonEpic(epic_record["name"], int(epic_record.get("sequentialOrder", 0)))
        epic.estimate = str(epic_record.get("estimate", "") or "")
        factories = epic_record.get("exampleFactories") or []
        if factories:
            epic.example_factories = list(factories)
        for sub in epic_record.get("subEpics", []):
            epic.sub_epics.append(self._sub_epic_from_dict(sub))
        return epic

    def _sub_epic_from_dict(self, sub_epic_record: Dict[str, Any]) -> JsonSubEpic:
        sub_epic = JsonSubEpic(sub_epic_record["name"], int(sub_epic_record.get("sequentialOrder", 0)))
        sub_epic.estimate = str(sub_epic_record.get("estimate", "") or "")
        factories = sub_epic_record.get("exampleFactories") or []
        if factories:
            sub_epic.example_factories = list(factories)
        for nested in sub_epic_record.get("subEpics", []):
            sub_epic.sub_epics.append(self._sub_epic_from_dict(nested))
        for story in sub_epic_record.get("stories", []):
            sub_epic.stories.append(self._story_from_dict(story))
        return sub_epic

    def _story_from_dict(self, story_record: Dict[str, Any]) -> JsonStory:
        story = JsonStory(
            story_record["name"],
            int(story_record.get("sequentialOrder", 0)),
            StoryType(story_record.get("storyType", "user")),
        )
        users = story_record.get("users")
        if users is None and story_record.get("actor"):
            users = [story_record["actor"]]
        if users:
            story.users = list(users) if isinstance(users, list) else [str(users)]
        if story_record.get("domainTerms"):
            story.domain_terms = list(story_record["domainTerms"])
        if story_record.get("evidence"):
            story.evidence = list(story_record["evidence"])
        for sc in story_record.get("scenarios", []):
            story.scenarios.append(self._scenario_from_dict(sc))
        return story

    def _scenario_from_dict(self, scenario_record: Dict[str, Any]) -> JsonScenario:
        scenario = JsonScenario(
            name=scenario_record.get("name", "Scenario"),
            sequential_order=int(scenario_record.get("sequentialOrder", 0)),
        )
        rows = scenario_record.get("exampleRows") or []
        if rows:
            scenario.example_rows = list(rows)
        return scenario

    def _increment_from_dict(self, increment_record: Dict[str, Any]) -> JsonIncrement:
        inc = JsonIncrement(
            name=increment_record["name"],
            sequential_order=int(increment_record.get("sequentialOrder", 0)),
        )
        inc.stories = list(increment_record.get("stories", []))
        inc.outcome = str(increment_record.get("outcome", "") or "")
        inc.decision_prompt = str(increment_record.get("decisionPrompt", "") or "")
        inc.slicing_notes = str(increment_record.get("slicingNotes", "") or "")
        return inc

class MiroCleanEngineeringModel(CleanEngineeringModel):

    def load_module(self, source: Module) -> MiroModule:
        loaded = MiroModule(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        loaded.classes = list(source.classes)
        return loaded

    def load_class(self, source: OoadClass) -> MiroClass:
        loaded = MiroClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def _imported_class(self, source: OoadClass, from_module: str = '') -> MiroImportedClass:
        loaded = MiroImportedClass(
            name=source.name,
            sequential_order=source.sequential_order,
            from_module=from_module,
        )
        loaded.update_self(source)
        return loaded

    def _is_modules_view(self, canonical: CleanEngineeringModel) -> bool:
        return is_modules_view(canonical)

    def _is_mermaid_modules(self, source: str) -> bool:
        stripped = source.strip()
        return stripped.startswith("flowchart") or stripped.startswith("graph")




    # ------------------------------------------------------------------
    # Uniform callable surface
    # ------------------------------------------------------------------

    def render(
        self,
        canonical: CleanEngineeringModel,
        previous: Optional[str] = None,
    ) -> str:
        if self._is_modules_view(canonical):
            return self._render_modules(canonical)
        return self._render_classes(canonical)

    def parse(self, text: str) -> "MiroCleanEngineeringModel":
        """Parse a canvas-composer SVG back into a MiroCleanEngineeringModel.

        Extracts the Mermaid source from the foreignObject body and delegates
        to _parse_modules or _parse_classes based on the diagram header.
        """
        diagrams = self._extract_diagrams(text)
        if not diagrams:
            return type(self)(name="", sequential_order=1)
        mermaid_src = diagrams[0][1]
        if self._is_mermaid_modules(mermaid_src):
            return self._parse_modules(mermaid_src)

        model = type(self)(name=diagrams[0][0].get("data-system", ""), sequential_order=1)
        for element, source in diagrams:
            parsed = self._parse_classes(
                source,
                module_name=element.get("data-module", ""),
            )
            model.modules.extend(parsed.modules)
        return model

    def sync(
        self,
        text: str,
        canonical: "MiroCleanEngineeringModel",
    ) -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    # ------------------------------------------------------------------
    # Modules view
    # ------------------------------------------------------------------

    def _render_modules(self, canonical: CleanEngineeringModel) -> str:
        forest = ContainmentForest.build(canonical.modules, synthesize_parents=False)
        nodes = {m.name: self.load_module(m) for m in canonical.modules}
        lines: List[str] = ["flowchart LR"]
        for name in forest.roots:
            node = nodes[name]
            kids = [nodes[c] for c in forest.children_of.get(name, []) if c in nodes]
            if kids:
                lines.append(f'    subgraph {node.mermaid_id()}["{node.mermaid_label()}"]')
                for child in kids:
                    lines.append(f'        {child.mermaid_id()}["{child.mermaid_label()}"]')
                lines.append("    end")
            else:
                lines.append(f'    {node.mermaid_id()}["{node.mermaid_label()}"]')
        for name, node in nodes.items():
            parent = path_parent(name)
            for dep in node.external_deps():
                if dep == parent:
                    continue
                dep_node = nodes.get(dep)
                dep_id = dep_node.mermaid_id() if dep_node else MiroModule(name=dep, sequential_order=0).mermaid_id()
                lines.append(f"    {node.mermaid_id()} --> {dep_id}")
        title = f"{canonical.name or 'System'} - Modules"
        return self._wrap_diagram("\n".join(lines), title)

    def _parse_modules(self, mermaid_src: str) -> "MiroCleanEngineeringModel":
        """Parse a Mermaid flowchart back into a module model."""
        model = type(self)(name="", sequential_order=1)
        order = 1

        # Extract system name from title comment if present (e.g. %% System - Modules)
        title_m = re.search(r"%%\s*(.+?)\s*-\s*Modules?", mermaid_src)
        if title_m:
            model.name = title_m.group(1).strip()

        # Parse subgraph declarations to find nesting
        # subgraph id["label"] ... end
        subgraph_re = re.compile(
            r"subgraph\s+(\w+)\[\"([^\"]+)\"\]", re.MULTILINE
        )
        node_re = re.compile(
            r"^\s{0,8}(\w+)\[\"([^\"]+)\"\]", re.MULTILINE
        )
        edge_re = re.compile(
            r"(\w+)\s*-->\s*(\w+)", re.MULTILINE
        )

        id_to_module: Dict[str, MiroModule] = {}

        def _parse_label(raw_label: str) -> Tuple[str, str, List[str]]:
            """Decode \\n-separated label into (name, purpose, seam_terms)."""
            parts = raw_label.replace("\\n", "\n").split("\n")
            name = parts[0].strip()
            purpose = ""
            terms: List[str] = []
            in_terms = False
            for part in parts[1:]:
                p = part.strip()
                if p == "---":
                    in_terms = True
                    continue
                if in_terms and p.startswith("\u2022 "):
                    terms.append(p[2:].strip())
                elif not in_terms and p:
                    purpose = p
            return name, purpose, terms

        # Collect all nodes (both subgraph headers and plain nodes)
        seen_ids: set = set()
        for m in subgraph_re.finditer(mermaid_src):
            mid, label = m.group(1), m.group(2)
            if mid in seen_ids:
                continue
            seen_ids.add(mid)
            name, purpose, terms = _parse_label(label)
            if not name:
                continue
            module = MiroModule(
                name=name, sequential_order=order,
                description=purpose, seam_terms=terms,
            )
            model.modules.append(module)
            id_to_module[mid] = module
            order += 1

        for m in node_re.finditer(mermaid_src):
            mid, label = m.group(1), m.group(2)
            if mid in seen_ids or mid in ("LR", "TD", "RL", "BT"):
                continue
            seen_ids.add(mid)
            name, purpose, terms = _parse_label(label)
            if not name:
                continue
            module = MiroModule(
                name=name, sequential_order=order,
                description=purpose, seam_terms=terms,
            )
            model.modules.append(module)
            id_to_module[mid] = module
            order += 1

        # Parse dependency edges
        for m in edge_re.finditer(mermaid_src):
            src_id, tgt_id = m.group(1), m.group(2)
            src_mod = id_to_module.get(src_id)
            tgt_mod = id_to_module.get(tgt_id)
            if src_mod is None or tgt_mod is None:
                continue
            if tgt_mod.name not in src_mod.dependencies:
                src_mod.dependencies.append(tgt_mod.name)

        return model

    # ------------------------------------------------------------------
    # Class view
    # ------------------------------------------------------------------

    _REL_ARROWS = {
        "inheritance": "<|--",
        "composition": "*--",
        "aggregation": "o--",
        "association": "-->",
    }
    _ARROW_TO_KIND = {v: k for k, v in _REL_ARROWS.items()}

    def _render_classes(self, canonical: CleanEngineeringModel) -> str:
        modules = [module for module in canonical.modules if module.classes]
        if not modules:
            return self._wrap_diagram(
                "classDiagram", f"{canonical.name or 'System'} - Class Diagram"
            )

        all_classes = list(canonical.classes)
        class_nodes = {self.load_class(oclass).mermaid_id(): self.load_class(oclass) for oclass in all_classes}
        class_by_id = {cid: node for cid, node in class_nodes.items()}
        module_by_id = {
            self.load_class(oclass).mermaid_id(): module.name
            for module in modules
            for oclass in module.classes
        }
        relationships = self._class_relationships(all_classes, class_by_id)

        page = Page(canonical.name or "System")
        for index, module in enumerate(modules):
            local_nodes = [self.load_class(oclass) for oclass in module.classes]
            local_ids = [node.mermaid_id() for node in local_nodes]
            local_set = set(local_ids)
            import_ids: set[str] = set()
            for source_id, target_id, kind in relationships:
                if source_id in local_set and target_id not in local_set:
                    import_ids.add(target_id)
                elif (
                    kind == "inheritance"
                    and target_id in local_set
                    and source_id not in local_set
                ):
                    import_ids.add(source_id)

            visible_ids = local_set | import_ids
            lines: List[str] = ["classDiagram"]
            for class_id in local_ids + sorted(import_ids):
                oclass_node = class_by_id[class_id]
                if class_id in import_ids:
                    imported = self._imported_class(
                        oclass_node, module_tab_label(module_by_id.get(class_id, "other"))
                    )
                    lines.extend(imported.mermaid_lines())
                else:
                    lines.extend(oclass_node.mermaid_lines())

            for source_id, target_id, kind in relationships:
                if source_id not in visible_ids or target_id not in visible_ids:
                    continue
                arrow = self._REL_ARROWS.get(kind, "-->")
                if kind == "inheritance":
                    lines.append(f"    {target_id} {arrow} {source_id}")
                else:
                    lines.append(f"    {source_id} {arrow} {target_id} : {kind}")

            placed = self.load_module(module)
            placed.geometry = Geometry(1000 + index * 3500, 2000, 1600, 900)
            page.place(placed, "\n".join(lines))
        return page.svg()

    def _class_relationships(
        self,
        classes: List[OoadClass],
        class_by_id: Dict[str, MiroClass],
    ) -> List[Tuple[str, str, str]]:
        relationships: List[Tuple[str, str, str]] = []
        aliases = {
            alias: class_id
            for class_id, oclass in class_by_id.items()
            for alias in (oclass.name, oclass.display_name())
        }
        for oclass in classes:
            node = self.load_class(oclass)
            source_id = node.mermaid_id()
            for relationship in oclass.relationships:
                target_id = aliases.get(relationship.target)
                if target_id is None:
                    continue
                item = (source_id, target_id, relationship.kind or "association")
                if item not in relationships:
                    relationships.append(item)
            base_name = node.extends_base_name()
            target_id = aliases.get(base_name or "")
            item = (source_id, target_id or "", "inheritance")
            if target_id and item not in relationships:
                relationships.append(item)
        return relationships

    def _parse_classes(
        self,
        mermaid_src: str,
        module_name: str = "",
    ) -> "MiroCleanEngineeringModel":
        """Parse a Mermaid classDiagram back into a class model."""
        model = type(self)(name="", sequential_order=1)
        module = MiroModule(name=module_name, sequential_order=1)
        model.modules.append(module)
        order = 1
        id_to_class: Dict[str, MiroClass] = {}

        # Parse class blocks
        class_block_re = re.compile(
            r"class\s+(\w+)\s*\{([^}]*)\}", re.MULTILINE | re.DOTALL
        )
        prop_re = re.compile(r"\+(.+?)\s+(\w+)\s*$")
        op_re = re.compile(r"\+(\w+)\((.*)\)\s+(.+?)\s*$")
        local_names = set(
            re.findall(r"^\s*%%\s+local:\s+(\w+)\s*$", mermaid_src, re.MULTILINE)
        )

        for m in class_block_re.finditer(mermaid_src):
            name = m.group(1)
            if local_names and name not in local_names:
                continue
            body = m.group(2)
            props: List[Property] = []
            ops: List[Operation] = []
            for line in body.splitlines():
                line = line.strip()
                if not line:
                    continue
                op_m = op_re.match(line)
                if op_m:
                    parameters = [
                        parameter.strip()
                        for parameter in op_m.group(2).split(",")
                        if parameter.strip()
                    ]
                    ops.append(
                        Operation(
                            name=op_m.group(1),
                            parameters=parameters,
                            return_type=op_m.group(3),
                        )
                    )
                    continue
                prop_m = prop_re.match(line)
                if prop_m:
                    props.append(Property(name=prop_m.group(2), type_hint=prop_m.group(1)))
            oclass = MiroClass(
                name=name, sequential_order=order,
                properties=props, operations=ops,
            )
            module.classes.append(oclass)
            id_to_class[name] = oclass
            order += 1

        # Parse relationships
        rel_re = re.compile(
            r"(\w+)\s+(<\|--|o--|[*]--|-->|<\.\.|\.\.[>|])\s+(\w+)"
        )
        for m in rel_re.finditer(mermaid_src):
            src_name, arrow, tgt_name = m.group(1), m.group(2), m.group(3)
            if arrow == "<|--":
                src_name, tgt_name = tgt_name, src_name
            src_cls = id_to_class.get(src_name)
            if src_cls is None:
                continue
            kind = self._ARROW_TO_KIND.get(arrow, "association")
            already = any(
                r.target == tgt_name for r in src_cls.relationships
            )
            if not already:
                src_cls.relationships.append(Relationship(target=tgt_name, kind=kind))

        return model

    # ------------------------------------------------------------------
    # SVG wrapping
    # ------------------------------------------------------------------

    def _wrap_diagram(self, mermaid: str, title: str) -> str:
        """Wrap Mermaid source in a canvas-composer SVG foreignObject."""
        escaped = (
            mermaid
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
        )
        return (
            "<?xml version='1.0' encoding='utf-8'?>\n"
            '<svg xmlns="http://www.w3.org/2000/svg">\n'
            f'  <foreignObject id="CleanEngineering-model" x="0" y="0" '
            f'width="1600" height="900" data-type="diagram" '
            f'data-title="{title}">'
            f"{escaped}"
            f"</foreignObject>\n"
            "</svg>"
        )

    def _extract_mermaid(self, text: str) -> Optional[str]:
        """Extract Mermaid source from a canvas-composer SVG string."""
        diagrams = self._extract_diagrams(text)
        return diagrams[0][1] if diagrams else None

    def _extract_diagrams(self, text: str) -> List[Tuple[ET.Element, str]]:
        """Extract every Mermaid diagram widget from a canvas-composer SVG."""
        try:
            root_el = ET.fromstring(
                text.split("\n", 1)[1] if text.startswith("<?") else text
            )
        except ET.ParseError:
            return []

        diagrams: List[Tuple[ET.Element, str]] = []
        for el in root_el.iter():
            tag = el.tag.split("}")[-1] if "}" in el.tag else el.tag
            if tag == "foreignObject" and el.get("data-type") == "diagram":
                diagrams.append((el, (el.text or "").strip()))
        return diagrams

class DrawioViolation:

    def __init__(self, rule: str, message: str, *, location: str='', line: int | None=None, severity: str='error') -> None:
        self.rule = rule
        self.message = message
        self.location = location
        self.line = line
        self.severity = severity

    def to_dict(self) -> dict[str, Any]:
        return {'rule': self.rule, 'violation_message': self.message, 'severity': self.severity, 'line_number': self.line, 'location': self.location}

class DrawioScanner:
    """Scanners that read `.drawio` mxfile pages via ``drawio_tools``."""
    _explicit_paths: frozenset[Path] = frozenset()

    def __init__(self, rule: str | None=None) -> None:
        self.rule = rule or getattr(type(self), 'RULE', type(self).__name__)
        self.workspace_root: Path | str | None = None

    @contextmanager
    def explicitly_requested(self, paths: Iterable[Path]) -> Iterator[None]:
        previous = DrawioScanner._explicit_paths
        DrawioScanner._explicit_paths = frozenset((Path(path).resolve() for path in paths))
        try:
            yield
        finally:
            DrawioScanner._explicit_paths = previous

    def is_skipped_path(self, path: Path) -> bool:
        p = Path(path)
        if DrawioScanner._explicit_paths and p.resolve() in DrawioScanner._explicit_paths:
            return False
        if p.stem.lower() in _REPAIR_FIXTURE_NAMES:
            return False
        if any((part.lower() in _REPAIR_FIXTURE_DIRS for part in p.parts)):
            return False
        return any((part in SKIP_DIR_NAMES for part in p.parts))

    def filter_scan_files(self, files: list[Path]) -> list[Path]:
        return [path for path in files if not self.is_skipped_path(path)]

    def scan(self, root: Path, files: list[Path]) -> list[DrawioViolation]:
        root = root.resolve()
        violations: list[DrawioViolation] = []
        for file_path in self.filter_scan_files(files):
            path = file_path if file_path.is_absolute() else root / file_path
            if not path.is_file():
                continue
            if self.is_skipped_path(path):
                continue
            violations.extend(self.scan_file(root, path))
        return violations

    def scan_file(self, root: Path, file_path: Path) -> list[DrawioViolation]:
        del root
        if file_path.suffix.lower() not in DRAWIO_EXTENSIONS:
            return []
        try:
            _, mxfile = self._load_drawio(str(file_path))
        except Exception as exc:
            return [self.violation(f'Could not load drawio file: {exc}', location=str(file_path))]
        violations = []
        for diagram in mxfile.findall('diagram'):
            page_name = diagram.get('name') or '(unnamed)'
            _, page_root = self._get_page(mxfile, page_name)
            if page_root is None:
                continue
            self._scan_file_path = file_path
            self._scan_page_name = page_name
            violations.extend(self.scan_page(page_root))
        return violations

    def scan_page(self, page_root) -> list:
        return []

    def violation(self, message: str, *, location: str='', line: int | None=None, severity: str='error') -> DrawioViolation:
        return DrawioViolation(self.rule, message, location=location, line=line, severity=severity)

    def discover(self) -> dict[str, type[DrawioScanner]]:
        discovered: dict[str, type[DrawioScanner]] = {}
        scanners_dir = Path(__file__).resolve().parent
        for script in sorted(scanners_dir.glob('*_scanner.py')):
            scanner_class = self._load_scanner_class(script)
            if scanner_class is None:
                continue
            slug = getattr(scanner_class, 'RULE', None)
            if not isinstance(slug, str) or not slug.strip():
                stem = script.stem
                if stem.endswith('_scanner'):
                    stem = stem[:-len('_scanner')]
                slug = stem.replace('_', '-')
            discovered[slug.strip()] = scanner_class
        return discovered

    def _load_scanner_class(self, script: Path) -> type[DrawioScanner] | None:
        parent = str(script.parent)
        sys.path.insert(0, parent)
        previous_alias = sys.modules.get('_drawio_base')
        sys.modules['_drawio_base'] = sys.modules[type(self).__module__]
        try:
            spec = importlib.util.spec_from_file_location(script.stem, script)
            if spec is None or spec.loader is None:
                return None
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            for value in vars(module).values():
                if isinstance(value, type) and issubclass(value, DrawioScanner) and (value is not DrawioScanner) and (value.__module__ == module.__name__):
                    return value
            return None
        finally:
            if previous_alias is None:
                sys.modules.pop('_drawio_base', None)
            else:
                sys.modules['_drawio_base'] = previous_alias
            if parent in sys.path:
                sys.path.remove(parent)

    def run_report(self, paths: list[str]) -> dict[str, Any]:
        scan_root = Path(self.workspace_root) if self.workspace_root is not None else Path.cwd()
        files = [Path(path) for path in paths]
        discovered = self.discover()
        with self.explicitly_requested(files):
            violations: list[DrawioViolation] = []
            for slug, scanner_class in discovered.items():
                violations.extend(scanner_class(slug).scan(scan_root, files))
        result = {'ok': len(violations) == 0, 'rules': sorted(discovered), 'violations': [item.to_dict() for item in violations]}
        if self.rule is not None:
            result['violations'] = [item for item in result['violations'] if item['rule'] == self.rule]
            result['ok'] = len(result['violations']) == 0
        return result

    def run_main(self, argv: list[str] | None=None) -> int:
        parser = argparse.ArgumentParser(description='Run one Draw.io scanner')
        parser.add_argument('--workspace', type=Path, default=Path.cwd(), help='Project root (default: cwd).')
        args = parser.parse_args(argv)
        workspace = args.workspace.resolve()
        files = self.collect_drawio_files(workspace)
        scanner = type(self)(getattr(type(self), 'RULE', type(self).__name__))
        violations = scanner.scan(workspace, files)
        if not violations:
            return 0
        for violation in violations:
            print(violation.to_dict(), file=sys.stderr)
        return 1

    def collect_drawio_files(self, root: Path) -> list[Path]:
        files: list[Path] = []
        for path in root.rglob('*'):
            if not path.is_file():
                continue
            if path.suffix.lower() not in DRAWIO_EXTENSIONS:
                continue
            if self.is_skipped_path(path):
                continue
            files.append(path)
        return files

    def _escape(self, text):
        return html.escape(str(text), quote=True)

    def _unescape(self, text):
        return html.unescape(str(text))

    def _load_drawio(self, path):
        """Load a DrawIO file. Returns (tree, root_element)."""
        path = Path(path)
        if not path.exists():
            raise FileNotFoundError(f'File not found: {path}')
        tree = ET.parse(str(path))
        return (tree, tree.getroot())

    def _save_drawio(self, path, root_element):
        """Write an mxfile element tree to disk."""
        path = Path(path)
        tree = ET.ElementTree(root_element)
        ET.indent(tree, space='  ')
        tree.write(str(path), encoding='unicode', xml_declaration=False)

    def _create_empty_mxfile(self):
        """Create a new empty mxfile element."""
        return ET.fromstring('<mxfile host="drawio_tools.py"></mxfile>')

    def _get_page(self, mxfile, page_name=None):
        """Get a diagram page by name. Returns (diagram_element, root_cell_parent).
    If page_name is None, returns the first page."""
        diagrams = mxfile.findall('diagram')
        if page_name:
            for d in diagrams:
                if d.get('name') == page_name:
                    model = d.find('mxGraphModel')
                    root = model.find('root') if model is not None else None
                    return (d, root)
            return (None, None)
        if diagrams:
            d = diagrams[0]
            model = d.find('mxGraphModel')
            root = model.find('root') if model is not None else None
            return (d, root)
        return (None, None)

    def _add_page(self, mxfile, _rest):
        page_name, page_width, page_height = _rest
        'Add a new diagram page to the mxfile. Returns (diagram, root).'
        diagram = ET.SubElement(mxfile, 'diagram')
        diagram.set('id', f"page_{page_name.replace(' ', '_').lower()}")
        diagram.set('name', page_name)
        model = ET.SubElement(diagram, 'mxGraphModel')
        model.set('dx', '1200')
        model.set('dy', '800')
        model.set('grid', '1')
        model.set('gridSize', '10')
        model.set('guides', '1')
        model.set('tooltips', '1')
        model.set('connect', '1')
        model.set('arrows', '1')
        model.set('fold', '1')
        model.set('page', '1')
        model.set('pageScale', '1')
        model.set('pageWidth', str(page_width))
        model.set('pageHeight', str(page_height))
        model.set('math', '0')
        model.set('shadow', '0')
        root = ET.SubElement(model, 'root')
        cell0 = ET.SubElement(root, 'mxCell')
        cell0.set('id', '0')
        cell1 = ET.SubElement(root, 'mxCell')
        cell1.set('id', '1')
        cell1.set('parent', '0')
        return (diagram, root)

    def _next_id(self, root):
        """Find the next available integer cell id."""
        max_id = 1
        for cell in root.iter('mxCell'):
            try:
                max_id = max(max_id, int(cell.get('id', '0')))
            except ValueError:
                pass
        return max_id + 1

    def _extract_class_name(self, value):
        """Extract class name from the HTML value of a class cell.
    The name is in the <b> tag. Stereotype (if any) is in a separate <i> tag."""
        if not value:
            return None
        match = re.search('<b[^>]*>(.*?)</b>', self._unescape(value), re.IGNORECASE | re.DOTALL)
        if match:
            name = re.sub('\\s+', ' ', match.group(1)).strip()
            if ' : ' in name:
                name = name.split(' : ')[0].strip()
            return name or None
        return None

    def _find_cell_by_name(self, root, class_name):
        """Find a class mxCell by its displayed name."""
        for cell in root.findall('mxCell'):
            value = cell.get('value', '')
            extracted = self._extract_class_name(value)
            if extracted == class_name:
                return cell
        return None

    def _find_cell_by_id(self, root, cell_id):
        """Find an mxCell by its id attribute."""
        for cell in root.findall('mxCell'):
            if cell.get('id') == str(cell_id):
                return cell
        return None

    def _get_all_classes(self, root):
        """Return list of (cell_id, class_name, x, y, w, h) for all class cells."""
        classes = []
        for cell in root.iter('mxCell'):
            if cell.get('vertex') != '1':
                continue
            name = self._extract_class_name(cell.get('value', ''))
            if not name:
                continue
            geo = self._get_geometry(cell)
            if geo:
                classes.append((cell.get('id'), name, *geo))
        return classes

    def _get_all_edges(self, root):
        """Return list of (cell_id, edge_type, source_id, target_id) for all edges."""
        edges = []
        for cell in root.findall('mxCell'):
            if cell.get('edge') != '1':
                continue
            style = cell.get('style', '')
            source = cell.get('source', '')
            target = cell.get('target', '')
            edge_type = self._classify_edge(style)
            edges.append((cell.get('id'), edge_type, source, target))
        return edges

    def _rect_clear_gap(self, a: tuple[float, float, float, float], b: tuple[float, float, float, float]) -> float:
        """Exterior gap between two axis-aligned boxes (0 if they touch/overlap)."""
        ax, ay, aw, ah = a
        bx, by, bw, bh = b
        dx = max(0.0, max(ax - (bx + bw), bx - (ax + aw)))
        dy = max(0.0, max(ay - (by + bh), by - (ay + ah)))
        x_overlap = not (ax + aw < bx or bx + bw < ax)
        y_overlap = not (ay + ah < by or by + bh < ay)
        if x_overlap and y_overlap:
            return 0.0
        if x_overlap:
            return dy
        if y_overlap:
            return dx
        return (dx ** 2 + dy ** 2) ** 0.5

    def _edge_waypoint_count(self, edge_cell) -> int:
        geo = edge_cell.find('mxGeometry')
        if geo is None:
            return 0
        arr = geo.find('Array')
        if arr is None:
            return 0
        return len(list(arr))

    def _check_prefer_short_routes(self, root) -> list[tuple[str, str]]:
        """Return (edge_desc, reason) for edges that are unnecessarily long/doglegged."""
        self._id_to_geo, self._id_to_name = self._vertex_geo_and_names(root)
        violations: list[tuple[str, str]] = []
        for cell in root.iter('mxCell'):
            violations.extend(self._short_route_hits(cell))
        return violations

    def _vertex_geo_and_names(self, root):
        id_to_geo: dict[str, tuple[float, float, float, float]] = {}
        id_to_name: dict[str, str] = {}
        for cell in root.iter('mxCell'):
            if cell.get('vertex') != '1':
                continue
            geo = self._get_geometry(cell)
            if not geo:
                continue
            cid = cell.get('id') or ''
            if not cid:
                continue
            id_to_geo[cid] = geo
            id_to_name[cid] = self._extract_class_name(cell.get('value', '')) or cid
        return (id_to_geo, id_to_name)

    def _short_route_hits(self, cell) -> list[tuple[str, str]]:
        if cell.get('edge') != '1':
            return []
        src = cell.get('source', '')
        tgt = cell.get('target', '')
        id_to_geo = self._id_to_geo
        if src not in id_to_geo or tgt not in id_to_geo:
            return []
        sn = self._id_to_name.get(src, src)
        tn = self._id_to_name.get(tgt, tgt)
        desc = f'{sn} → {tn}'
        nwp = self._edge_waypoint_count(cell)
        gap = self._rect_clear_gap(id_to_geo[src], id_to_geo[tgt])
        hits: list[tuple[str, str]] = []
        if nwp > SHORT_ROUTE_MAX_WAYPOINTS and gap <= SHORT_ROUTE_MAX_BOX_GAP:
            hits.append((desc, f'{nwp} waypoints across a {gap:.0f}px gap (max {SHORT_ROUTE_MAX_WAYPOINTS}) — prefer a short orthogonal route'))
        if gap > SHORT_ROUTE_MAX_BOX_GAP:
            hits.append((desc, f'endpoint gap {gap:.0f}px (max {SHORT_ROUTE_MAX_BOX_GAP}) — place related classes closer'))
        return hits

    def _classify_edge(self, style):
        """Determine edge type from style string."""
        is_orthogonal = 'orthogonalEdgeStyle' in style
        if 'endFill=0' in style and 'endArrow=block' in style:
            return 'inheritance-orthogonal' if is_orthogonal else 'inheritance'
        if 'startFill=1' in style and 'diamondThin' in style:
            return 'composition'
        if 'startFill=0' in style and 'diamondThin' in style:
            return 'aggregation'
        if 'dashed=1' in style and 'endArrow=open' in style:
            return 'dependency-orthogonal' if is_orthogonal else 'dependency'
        if 'endArrow=open' in style:
            return 'association'
        return 'unknown'

    def _get_geometry(self, cell):
        """Return (x, y, width, height) from a cell's mxGeometry, or None."""
        geo = cell.find('mxGeometry')
        if geo is None:
            return None
        return (float(geo.get('x', '0')), float(geo.get('y', '0')), float(geo.get('width', '0')), float(geo.get('height', '0')))

    def _set_geometry(self, cell, _rest):
        x, y, w, h = _rest
        "Update position and/or size on a cell's mxGeometry."
        geo = cell.find('mxGeometry')
        if geo is None:
            geo = ET.SubElement(cell, 'mxGeometry')
            geo.set('as', 'geometry')
        if x is not None:
            geo.set('x', str(int(x)))
        if y is not None:
            geo.set('y', str(int(y)))
        if w is not None:
            geo.set('width', str(int(w)))
        if h is not None:
            geo.set('height', str(int(h)))

    def _check_overlaps(self, classes):
        """Return list of overlapping pairs: [(name_a, name_b), ...]."""
        overlaps = []
        for i, (_, name_a, xa, ya, wa, ha) in enumerate(classes):
            for j, (_, name_b, xb, yb, wb, hb) in enumerate(classes):
                if j <= i:
                    continue
                if xa < xb + wb and xa + wa > xb and (ya < yb + hb) and (ya + ha > yb):
                    overlaps.append((name_a, name_b))
        return overlaps

    def _rect_center(self, rect):
        """Return center point of a rectangle."""
        x, y, w, h = rect
        return (x + w / 2, y + h / 2)

    def _line_intersects_rect(self, segment, rect):
        """Check if line segment passes through rectangle.

    Uses margin to detect near-misses (edges that visually touch).
    """
        start_x, start_y, end_x, end_y = segment
        left, top, width, height, margin = rect
        if margin is None:
            margin = 5
        left -= margin
        top -= margin
        width += 2 * margin
        height += 2 * margin
        self._ccw_third = (end_x, end_y)
        if self._rect_sides_cross_segment((start_x, start_y), (left, top, width, height)):
            return True
        if left <= start_x <= left + width and top <= start_y <= top + height:
            return True
        return False

    def _rect_sides_cross_segment(self, start, rect) -> bool:
        start_x, start_y = start
        left, top, width, height = rect
        corners = [(left, top), (left + width, top), (left + width, top + height), (left, top + height)]
        sides = [(corners[0], corners[1]), (corners[1], corners[2]), (corners[2], corners[3]), (corners[3], corners[0])]
        end_x, end_y = self._ccw_third
        for first, second in sides:
            if self._segments_cross_2d((start_x, start_y, end_x, end_y), (first[0], first[1], second[0], second[1])):
                return True
        return False

    def _ccw_2d(self, first, second) -> bool:
        ax, ay = first
        bx, by = second
        cx, cy = self._ccw_third
        return (cy - ay) * (bx - ax) > (by - ay) * (cx - ax)

    def _segments_cross_2d(self, first, second) -> bool:
        ax, ay, bx, by = first
        cx, cy, dx, dy = second
        self._ccw_third = (dx, dy)
        first_turn = self._ccw_2d((ax, ay), (cx, cy)) != self._ccw_2d((bx, by), (cx, cy))
        self._ccw_third = (cx, cy)
        second_turn = self._ccw_2d((ax, ay), (bx, by))
        self._ccw_third = (dx, dy)
        return first_turn and second_turn != self._ccw_2d((ax, ay), (bx, by))

    def _orthogonal_crosses_rect(self, src_geo, tgt_geo):
        """Approximate check: does an orthogonal edge between two classes cross a third?

    Orthogonal edges go horizontal then vertical (or vice versa). We check both
    possible L-shaped paths and report a crossing if BOTH paths hit the obstacle.
    """
        rx, ry, rw, rh = self._obstacle_rect
        margin = self._hit_margin
        scx, scy = self._rect_center(src_geo)
        tcx, tcy = self._rect_center(tgt_geo)
        path_a_crosses = self._line_intersects_rect((scx, scy, tcx, scy), (rx, ry, rw, rh, margin)) or self._line_intersects_rect((tcx, scy, tcx, tcy), (rx, ry, rw, rh, margin))
        path_b_crosses = self._line_intersects_rect((scx, scy, scx, tcy), (rx, ry, rw, rh, margin)) or self._line_intersects_rect((scx, tcy, tcx, tcy), (rx, ry, rw, rh, margin))
        return path_a_crosses and path_b_crosses

    def _check_edge_crossings(self, root):
        """Check if any edge passes through a class it is not connected to.
    Returns list of (edge_desc, crossed_class_name) tuples."""
        classes = self._get_all_classes(root)
        edges = self._get_all_edges(root)
        self._scan_classes = classes
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        crossings = []
        for _eid, etype, src_id, tgt_id in edges:
            self._edge_type = etype
            self._edge_src_id = src_id
            self._edge_tgt_id = tgt_id
            crossings.extend(self._crossings_for_edge())
        return crossings

    def _crossings_for_edge(self):
        src_id, tgt_id = self._edge_src_id, self._edge_tgt_id
        src_geo = self._id_to_geo.get(src_id)
        tgt_geo = self._id_to_geo.get(tgt_id)
        if src_geo is None or tgt_geo is None:
            return []
        src_name = self._id_to_name.get(src_id, '?')
        tgt_name = self._id_to_name.get(tgt_id, '?')
        etype = self._edge_type
        is_straight = etype in ('inheritance', 'dependency', 'association-straight', 'composition-straight', 'aggregation-straight')
        desc = f'{src_name}->{tgt_name} ({etype})'
        hits = []
        for cid, cname, cx, cy, cw, ch in self._scan_classes:
            if cid in (src_id, tgt_id):
                continue
            self._obstacle_box = (cx, cy, cw, ch)
            if self._edge_hits_class(is_straight, (src_geo, tgt_geo)):
                hits.append((desc, cname))
        return hits

    def _edge_hits_class(self, is_straight, geos) -> bool:
        src_geo, tgt_geo = geos
        cx, cy, cw, ch = self._obstacle_box
        if is_straight:
            scx, scy = self._rect_center(src_geo)
            tcx, tcy = self._rect_center(tgt_geo)
            return self._line_intersects_rect((scx, scy, tcx, tcy), (cx, cy, cw, ch, None))
        self._obstacle_rect = (cx, cy, cw, ch)
        self._hit_margin = None
        return self._orthogonal_crosses_rect(src_geo, tgt_geo)

    def _check_shared_anchors(self, root):
        """Detect edges that share the same anchor point on the same class.

    Groups edges by the (class_id, exit/entry_x, exit/entry_y) anchor.  When
    explicit anchors are set in the style, those are used; otherwise the
    default center anchor is assumed.  Reports a conflict only when two or
    more edges share the *exact same* anchor coordinates on the same class.
    """
        classes = self._get_all_classes(root)
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        self._anchor_map = {}
        for cell in root.findall('mxCell'):
            self._record_edge_anchors(cell)
        return self._anchor_conflicts()

    def _record_edge_anchors(self, cell) -> None:
        if cell.get('edge') != '1':
            return
        style = cell.get('style', '')
        src_id = cell.get('source', '')
        tgt_id = cell.get('target', '')
        src_name = self._id_to_name.get(src_id, '?')
        tgt_name = self._id_to_name.get(tgt_id, '?')
        etype = self._classify_edge(style)
        desc = f'{src_name}->{tgt_name} ({etype})'
        ex = self._parse_style_float(style, 'exitX')
        ey = self._parse_style_float(style, 'exitY')
        src_anchor = (round(ex, 2) if ex is not None else 'def', round(ey, 2) if ey is not None else 'def')
        nx = self._parse_style_float(style, 'entryX')
        ny = self._parse_style_float(style, 'entryY')
        tgt_anchor = (round(nx, 2) if nx is not None else 'def', round(ny, 2) if ny is not None else 'def')
        self._anchor_map.setdefault((src_id, 'exit', src_anchor), []).append(desc)
        self._anchor_map.setdefault((tgt_id, 'entry', tgt_anchor), []).append(desc)

    def _anchor_conflicts(self):
        conflicts = []
        for (cid, end, anchor), descs in self._anchor_map.items():
            if len(descs) <= 1:
                continue
            cls_name = self._id_to_name.get(cid, '?')
            anchor_label = f'{end}({anchor[0]},{anchor[1]})'
            conflicts.append((cls_name, anchor_label, descs))
        return conflicts

    def _parse_style_float(self, style, key):
        """Extract a float value from a Draw.io style string, e.g. 'exitX=0.3'."""
        m = re.search(f'{key}=([0-9.]+)', style)
        return float(m.group(1)) if m else None

    def _edge_anchor_point(self, style, _rest):
        cell_geo, end = _rest
        'Compute the absolute (x, y) anchor point for one end of an edge.\n\n    Reads exitX/exitY or entryX/entryY from the style.  Falls back to the\n    centre of the class box when no explicit anchor is set.\n    '
        x, y, w, h = cell_geo
        ax = self._parse_style_float(style, f'{end}X')
        ay = self._parse_style_float(style, f'{end}Y')
        if ax is not None and ay is not None:
            return (x + w * ax, y + h * ay)
        return self._rect_center((x, y, w, h))

    def _compute_edge_segments(self, edge_cell, id_to_geo):
        """Compute the polyline segments of an edge.

    For straight edges: one segment from source anchor to target anchor.
    For orthogonal edges with explicit waypoints: follow those waypoints.
    For orthogonal edges without waypoints: approximate using both possible
    L-shaped routes (H-V and V-H) and return the one less likely to cross.

    Returns a list of ((x1,y1),(x2,y2)) segments, and a boolean
    ``is_approximate`` indicating whether the route is a best-guess.
    Callers that need is_approximate can call _compute_edge_segments_ex.
    """
        segs, _ = self._compute_edge_segments_ex(edge_cell, id_to_geo)
        return segs

    def _compute_edge_segments_ex(self, edge_cell, id_to_geo):
        """Like _compute_edge_segments but also returns is_approximate flag."""
        style = edge_cell.get('style', '')
        src_id = edge_cell.get('source', '')
        tgt_id = edge_cell.get('target', '')
        src_geo = id_to_geo.get(src_id)
        tgt_geo = id_to_geo.get(tgt_id)
        if src_geo is None or tgt_geo is None:
            return ([], False)
        p1 = self._edge_anchor_point(style, (src_geo, 'exit'))
        p2 = self._edge_anchor_point(style, (tgt_geo, 'entry'))
        is_orthogonal = 'orthogonal' in style.lower() or 'edgestyle=orthogonal' in style.lower()
        if not is_orthogonal:
            return ([(p1, p2)], False)
        geo = edge_cell.find('mxGeometry')
        waypoints = []
        if geo is not None:
            arr = geo.find('Array')
            if arr is not None:
                for pt in arr.findall('mxPoint'):
                    px = float(pt.get('x', '0'))
                    py = float(pt.get('y', '0'))
                    waypoints.append((px, py))

        def _expand_orthogonal_seg(pa, _rest):
            pb, prev_dir = _rest
            'Return list of points (excluding ``pa``) representing the H-V or\n        V-H expansion of segment ``pa→pb`` (or a single point if it is\n        already axis-aligned). ``prev_dir`` is the direction of the\n        previous segment ("h", "v" or None).\n        '
            ax, ay = pa
            bx, by = pb
            if abs(bx - ax) < 1 or abs(by - ay) < 1:
                return ([(bx, by)], 'v' if abs(bx - ax) < 1 else 'h')
            if prev_dir == 'v':
                corner = (ax, by)
                return ([corner, (bx, by)], 'h')
            corner = (bx, ay)
            return ([corner, (bx, by)], 'v')
        if waypoints:
            points = [p1] + waypoints + [p2]
            expanded = [points[0]]
            prev_dir = None
            for i in range(len(points) - 1):
                next_pts, prev_dir = _expand_orthogonal_seg(expanded[-1], (points[i + 1], prev_dir))
                expanded.extend(next_pts)
            return ([(expanded[i], expanded[i + 1]) for i in range(len(expanded) - 1)], False)
        x1, y1 = p1
        x2, y2 = p2
        if abs(x2 - x1) < 1 or abs(y2 - y1) < 1:
            return ([(p1, p2)], False)
        mid_x = (x1 + x2) / 2
        return ([(p1, (mid_x, y1)), ((mid_x, y1), (mid_x, y2)), ((mid_x, y2), p2)], True)

    def _segments_overlap_1d(self, a_start, _rest):
        a_end, b_start, b_end, threshold = _rest
        'Check whether two 1D intervals overlap by more than *threshold* pixels.'
        lo_a, hi_a = (min(a_start, a_end), max(a_start, a_end))
        lo_b, hi_b = (min(b_start, b_end), max(b_start, b_end))
        overlap = min(hi_a, hi_b) - max(lo_a, lo_b)
        return overlap > threshold

    def _edge_segments_overlap(self, seg_a, _rest):
        seg_b, proximity = _rest
        'Check whether two line segments visually overlap (run parallel and\n    close together for a shared span).  Works for axis-aligned segments\n    produced by orthogonal routing.\n    '
        (ax1, ay1), (ax2, ay2) = seg_a
        (bx1, by1), (bx2, by2) = seg_b
        a_horiz = abs(ay2 - ay1) < 2
        a_vert = abs(ax2 - ax1) < 2
        b_horiz = abs(by2 - by1) < 2
        b_vert = abs(bx2 - bx1) < 2
        if a_horiz and b_horiz:
            if abs(ay1 - by1) < proximity:
                if self._segments_overlap_1d(ax1, (ax2, bx1, bx2, None)):
                    return True
        if a_vert and b_vert:
            if abs(ax1 - bx1) < proximity:
                if self._segments_overlap_1d(ay1, (ay2, by1, by2, None)):
                    return True
        return False

    def _check_edge_on_edge_overlaps(self, root):
        """Detect pairs of edges whose route segments visually overlap.

    Returns list of (edge_a_desc, edge_b_desc, detail) tuples.
    """
        classes = self._get_all_classes(root)
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        edge_info = [self._edge_segment_info(cell) for cell in root.findall('mxCell') if cell.get('edge') == '1']
        overlaps = []
        for i, (desc_a, segs_a) in enumerate(edge_info):
            overlaps.extend(self._overlaps_against_later_edges(desc_a, (segs_a, edge_info[i + 1:])))
        return overlaps

    def _edge_segment_info(self, cell):
        src_id = cell.get('source', '')
        tgt_id = cell.get('target', '')
        src_name = self._id_to_name.get(src_id, '?')
        tgt_name = self._id_to_name.get(tgt_id, '?')
        etype = self._classify_edge(cell.get('style', ''))
        desc = f'{src_name}->{tgt_name} ({etype})'
        segs = self._compute_edge_segments(cell, self._id_to_geo)
        return (desc, segs)

    def _overlaps_against_later_edges(self, desc_a, later):
        segs_a, later_edges = later
        overlaps = []
        for desc_b, segs_b in later_edges:
            detail = self._first_segment_overlap(segs_a, segs_b)
            if detail:
                overlaps.append((desc_a, desc_b, detail))
        return overlaps

    def _first_segment_overlap(self, segs_a, segs_b):
        for sa in segs_a:
            for sb in segs_b:
                if self._edge_segments_overlap(sa, (sb, None)):
                    return f'segments {self._fmt_seg(sa)} and {self._fmt_seg(sb)} overlap'
        return None

    def _fmt_seg(self, seg):
        (x1, y1), (x2, y2) = seg
        return f'({x1:.0f},{y1:.0f})->({x2:.0f},{y2:.0f})'

    def _check_edges_crossing_classes(self, root):
        """Check edges whose route segments pass through a class box they are
    not connected to.

    For straight edges and orthogonal edges with explicit waypoints the
    route is known exactly.  For orthogonal edges WITHOUT waypoints the
    route is approximated — Draw.io's auto-router may find a better path.
    Approximate crossings are tagged ``(approx)`` in the description so
    the agent can decide whether to fix or ignore them.

    Returns list of (edge_desc, crossed_class_name) tuples.
    """
        classes = self._get_all_classes(root)
        self._scan_classes = classes
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        crossings = []
        for cell in root.findall('mxCell'):
            crossings.extend(self._class_hits_for_edge_cell(cell))
        return crossings

    def _class_hits_for_edge_cell(self, cell):
        if cell.get('edge') != '1':
            return []
        src_id = cell.get('source', '')
        tgt_id = cell.get('target', '')
        src_name = self._id_to_name.get(src_id, '?')
        tgt_name = self._id_to_name.get(tgt_id, '?')
        etype = self._classify_edge(cell.get('style', ''))
        segs, is_approx = self._compute_edge_segments_ex(cell, self._id_to_geo)
        suffix = ' (approx)' if is_approx else ''
        desc = f'{src_name}->{tgt_name} ({etype}){suffix}'
        hits = []
        for cid, cname, cx, cy, cw, ch in self._scan_classes:
            if cid in (src_id, tgt_id):
                continue
            if self._any_seg_hits_rect(segs, (cx, cy, cw, ch)):
                hits.append((desc, cname))
        return hits

    def _any_seg_hits_rect(self, segs, rect) -> bool:
        cx, cy, cw, ch = rect
        for (x1, y1), (x2, y2) in segs:
            if self._line_intersects_rect((x1, y1, x2, y2), (cx, cy, cw, ch, 3)):
                return True
        return False

    def _validate_layout(self, root):
        """Validate diagram against class_diagram rules. Returns list of (rule, message) violations."""
        violations = []
        classes = self._get_all_classes(root)
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._name_to_geo = {name: (x, y, w, h) for cid, name, x, y, w, h in classes}
        for name_a, name_b in self._check_overlaps(classes):
            violations.append(('class_overlap', f'{name_a} overlaps {name_b}'))
        for edge_desc, crossed in self._check_edges_crossing_classes(root):
            violations.append(('edge_crosses_class', f'Edge {edge_desc} crosses through {crossed}'))
        for desc_a, desc_b, detail in self._check_edge_on_edge_overlaps(root):
            violations.append(('edge_on_edge_overlap', f'{desc_a} overlaps {desc_b} — {detail}'))
        for cls_name, side, descs in self._check_shared_anchors(root):
            violations.append(('shared_anchor', f"{cls_name} {side}: {len(descs)} edges share default anchor — {', '.join(descs)}"))
        violations.extend(self._inheritance_flow_violations(self._get_all_edges(root)))
        return violations

    def _inheritance_flow_violations(self, edges):
        violations = []
        for _eid, etype, src_id, tgt_id in edges:
            if etype not in ('inheritance', 'inheritance-orthogonal'):
                continue
            src_name = self._id_to_name.get(src_id)
            tgt_name = self._id_to_name.get(tgt_id)
            if src_name is None or tgt_name is None:
                continue
            src_geo = self._name_to_geo.get(src_name)
            tgt_geo = self._name_to_geo.get(tgt_name)
            if src_geo is None or tgt_geo is None:
                continue
            _, child_y, _, _ = src_geo
            _, parent_y, _, _ = tgt_geo
            if child_y <= parent_y:
                violations.append(('hierarchy_flow', f'Inheritance: {src_name} (y={child_y}) should be below parent {tgt_name} (y={parent_y}); base at top, children below'))
        return violations

    def _audit_diagram(self, path, page_name=None):
        """Run all layout checks on one or all pages.  Returns a dict:
    {page_name: {"pass": bool, "violations": [(rule, msg), ...]}}
    Designed to be called from CLI or by the agent after every render.
    """
        _, mxfile = self._load_drawio(path)
        pages = []
        if page_name:
            pages = [(page_name,)]
        else:
            for d in mxfile.findall('diagram'):
                pages.append((d.get('name'),))
        results = {}
        for pname, in pages:
            _, root = self._get_page(mxfile, pname)
            if root is None:
                results[pname] = {'pass': False, 'violations': [('page_missing', f"Page '{pname}' not found")]}
                continue
            v = self._validate_layout(root)
            results[pname] = {'pass': len(v) == 0, 'violations': v}
        return results

    def _audit_diagram_report(self, path, page_name=None):
        """Human-readable audit report. Returns the text string."""
        results = self._audit_diagram(path, page_name)
        lines = []
        all_pass = True
        for pname, info in results.items():
            status = 'PASS' if info['pass'] else 'FAIL'
            if not info['pass']:
                all_pass = False
            lines.append(f'\n=== Page: {pname} — {status} ===')
            if info['violations']:
                for rule, msg in info['violations']:
                    lines.append(f'  [{rule}] {msg}')
            else:
                lines.append('  No issues found.')
        summary = 'ALL PAGES PASS' if all_pass else 'VIOLATIONS FOUND'
        lines.insert(0, f'Audit: {summary}')
        return '\n'.join(lines)

    def _calc_cell_height(self, props_count, _rest):
        ops_count, inv_count = _rest
        'Compute cell height from content line counts.'
        sections = 2
        if inv_count > 0:
            sections = 3
        content_lines = props_count + ops_count + inv_count
        return max(CELL_MIN_HEIGHT, 30 + content_lines * LINE_HEIGHT + sections * SECTION_PAD)

    def _build_class_html(self, name, _rest):
        base, properties, operations, invariants, stereotype = _rest
        'Build the HTML value string for a UML class cell.'
        properties = properties or []
        operations = operations or []
        invariants = invariants or []
        base_label = f' : {self._escape(base)}' if base else ''
        stereotype_html = f'<i style="font-size:9px;color:#888;">{self._escape(stereotype)}</i><br/>' if stereotype else ''
        props_html = self._member_lines_html(properties)
        ops_html = self._member_lines_html(operations)
        label = f'<p style="margin:0px;margin-top:4px;text-align:center;">{stereotype_html}<b>{self._escape(name)}{base_label}</b></p><hr size="1"/><p style="margin:0px;margin-left:4px;font-size:10px;">{props_html}</p><hr size="1"/><p style="margin:0px;margin-left:4px;font-size:10px;">{ops_html}</p>'
        return label + self._invariants_html(invariants)

    def _member_lines_html(self, items):
        html = ''.join((f'+ {self._escape(p)}<br/>' for p in items))
        return html or '<br/>'

    def _invariants_html(self, invariants):
        if not invariants:
            return ''
        inv_html = ''
        for inv in invariants:
            short = inv[:80] + '...' if len(inv) > 80 else inv
            inv_html += f'<i>{self._escape(short)}</i><br/>'
        return f'<hr size="1"/><p style="margin:0px;margin-left:4px;font-size:9px;color:#666;">{inv_html}</p>'

    def _parse_class_html(self, value):
        """Extract (name, base, properties, operations, invariants) from class cell HTML."""
        text = self._unescape(value)
        name = None
        base = None
        match = re.search('<b>([^<]+)</b>', text)
        if match:
            raw = match.group(1).strip()
            if ' : ' in raw:
                name, base = raw.split(' : ', 1)
                name = name.strip()
                base = base.strip()
            else:
                name = raw
        sections = re.split('<hr size="1"\\s*/?>', text)
        properties = []
        operations = []
        invariants = []

        def extract_items(section_html):
            items = []
            for line in re.findall('\\+\\s*([^<]+)', section_html):
                line = line.strip()
                if line:
                    items.append(line)
            return items

        def extract_invariants(section_html):
            items = []
            for line in re.findall('<i>([^<]+)</i>', section_html):
                line = line.strip()
                if line:
                    items.append(line)
            return items
        if len(sections) >= 3:
            properties = extract_items(sections[1])
            operations = extract_items(sections[2])
        if len(sections) >= 4:
            invariants = extract_invariants(sections[3])
        return (name, base, properties, operations, invariants)

    def _create_class_cell(self, root, name):
        """Create and append a class mxCell to root. Returns the cell element.

    If imported_from is set, the class is rendered with dashed border and the
    source module name shown as a stereotype.
    """
        properties = self._cell_properties or []
        operations = self._cell_operations or []
        invariants = self._cell_invariants or []
        imported_from = self._from_module
        cell_id = str(self._next_id(root))
        stereotype = f'«from: {imported_from}»' if imported_from else None
        label = self._build_class_html(name, (self._cell_base, properties, operations, invariants, stereotype))
        height = self._imported_or_local_height((properties, operations, invariants))
        return self._append_vertex_cell(root, (cell_id, label, height))

    def _imported_or_local_height(self, counts):
        properties, operations, invariants = counts
        height = self._calc_cell_height(len(properties), (len(operations), len(invariants)))
        if self._from_module:
            height += LINE_HEIGHT
        return height

    def _append_vertex_cell(self, root, cell):
        cell_id, label, height = cell
        style = CLASS_STYLE_IMPORT if self._from_module else CLASS_STYLE
        cell = ET.SubElement(root, 'mxCell')
        cell.set('id', cell_id)
        cell.set('value', label)
        cell.set('style', style)
        cell.set('vertex', '1')
        cell.set('parent', '1')
        geo = ET.SubElement(cell, 'mxGeometry')
        geo.set('x', str(int(self._cell_x)))
        geo.set('y', str(int(self._cell_y)))
        geo.set('width', str(CELL_WIDTH))
        geo.set('height', str(int(height)))
        geo.set('as', 'geometry')
        return cell

    def _update_class_cell(self, cell, _rest):
        name, base, properties, operations, invariants = _rest
        "Update an existing class cell's content. Recalculates height."
        old_name, old_base, old_props, old_ops, old_invs = self._parse_class_html(self._unescape(cell.get('value', '')))
        new_name = name if name is not None else old_name
        new_base = base if base is not None else old_base
        new_props = properties if properties is not None else old_props
        new_ops = operations if operations is not None else old_ops
        new_invs = invariants if invariants is not None else old_invs
        label = self._build_class_html(new_name, (new_base, new_props, new_ops, new_invs, None))
        cell.set('value', label)
        height = self._calc_cell_height(len(new_props), (len(new_ops), len(new_invs)))
        self._set_geometry(cell, (None, None, None, height))

    def _create_edge(self, root) -> ET.Element:
        """Create and append an edge mxCell. Returns the cell element.

    Anchor points (0.0–1.0) control where the edge leaves/arrives on the
    class box.  0,0 = top-left; 1,1 = bottom-right; 0.5,0 = top-center.
    When multiple edges share a side, callers MUST supply distinct anchors.
    """
        if self._edge_kind not in EDGE_STYLES:
            raise ValueError(f'Unknown edge type: {self._edge_kind}. Use: {list(EDGE_STYLES.keys())}')
        cell = ET.SubElement(root, 'mxCell')
        cell.set('id', str(self._next_id(root)))
        cell.set('value', self._edge_label or '')
        cell.set('style', self._scanner_edge_style())
        cell.set('edge', '1')
        cell.set('parent', '1')
        cell.set('source', str(self._edge_src_id))
        cell.set('target', str(self._edge_tgt_id))
        geo = ET.SubElement(cell, 'mxGeometry')
        geo.set('relative', '1')
        geo.set('as', 'geometry')
        return cell

    def _scanner_edge_style(self) -> str:
        style = EDGE_STYLES[self._edge_kind]
        parts = self._scanner_anchor_parts()
        if parts:
            style = style.rstrip(';') + ';' + ';'.join(parts) + ';'
        return style

    def _scanner_anchor_parts(self) -> list:
        parts = []
        if self._exit_x is not None:
            parts.append(f'exitX={self._exit_x}')
        if self._exit_y is not None:
            parts.append(f'exitY={self._exit_y}')
        if self._entry_x is not None:
            parts.append(f'entryX={self._entry_x}')
        if self._entry_y is not None:
            parts.append(f'entryY={self._entry_y}')
        if not parts:
            return parts
        if self._exit_x is not None or self._exit_y is not None:
            parts.extend(['exitDx=0', 'exitDy=0'])
        if self._entry_x is not None or self._entry_y is not None:
            parts.extend(['entryDx=0', 'entryDy=0'])
        return parts

    def _add_edge_waypoints(self, edge_cell, points):
        """Attach ``<Array as="points">`` waypoints to an edge's geometry.

    ``points`` is a sequence of ``(x, y)`` tuples in absolute page coordinates.
    Existing waypoints on the edge are replaced.

    Draw.io's orthogonal router honours these waypoints, so callers can use them
    to dog-leg an edge around an intervening class.
    """
        if not points:
            return
        geo = edge_cell.find('mxGeometry')
        if geo is None:
            geo = ET.SubElement(edge_cell, 'mxGeometry')
            geo.set('relative', '1')
            geo.set('as', 'geometry')
        for existing in geo.findall('Array'):
            geo.remove(existing)
        arr = ET.SubElement(geo, 'Array')
        arr.set('as', 'points')
        for x, y in points:
            pt = ET.SubElement(arr, 'mxPoint')
            pt.set('x', str(int(round(x))))
            pt.set('y', str(int(round(y))))

    def _set_edge_anchors(self, cell, _rest):
        exit_x, exit_y, entry_x, entry_y = _rest
        'Set or update exit/entry anchor points on an existing edge cell.'
        style = cell.get('style', '')
        for key in ('exitX', 'exitY', 'entryX', 'entryY', 'exitDx', 'exitDy', 'entryDx', 'entryDy'):
            style = re.sub(f'{key}=[^;]*;?', '', style)
        style = style.rstrip(';') + ';'
        parts = self._anchor_style_parts((exit_x, exit_y, entry_x, entry_y))
        if parts:
            style += ';'.join(parts) + ';'
        cell.set('style', style)

    def _anchor_style_parts(self, anchors):
        exit_x, exit_y, entry_x, entry_y = anchors
        parts = []
        if exit_x is not None:
            parts.append(f'exitX={exit_x}')
        if exit_y is not None:
            parts.append(f'exitY={exit_y}')
        if exit_x is not None or exit_y is not None:
            parts.append('exitDx=0')
            parts.append('exitDy=0')
        if entry_x is not None:
            parts.append(f'entryX={entry_x}')
        if entry_y is not None:
            parts.append(f'entryY={entry_y}')
        if entry_x is not None or entry_y is not None:
            parts.append('entryDx=0')
            parts.append('entryDy=0')
        return parts

    def _delete_cell(self, root, cell):
        """Remove a cell from root."""
        root.remove(cell)

    def _delete_class_and_edges(self, root, class_name):
        """Remove a class cell and all edges connected to it."""
        cell = self._find_cell_by_name(root, class_name)
        if cell is None:
            return False
        cell_id = cell.get('id')
        edges_to_remove = []
        for edge in root.findall('mxCell'):
            if edge.get('edge') != '1':
                continue
            if edge.get('source') == cell_id or edge.get('target') == cell_id:
                edges_to_remove.append(edge)
        for e in edges_to_remove:
            root.remove(e)
        root.remove(cell)
        return True

    def _delete_edge_between(self, root, _rest):
        source_name, target_name = _rest
        'Remove edge(s) between two named classes. Returns count removed.'
        source_cell = self._find_cell_by_name(root, source_name)
        target_cell = self._find_cell_by_name(root, target_name)
        if source_cell is None or target_cell is None:
            return 0
        source_id = source_cell.get('id')
        target_id = target_cell.get('id')
        to_remove = []
        for edge in root.findall('mxCell'):
            if edge.get('edge') != '1':
                continue
            s, t = (edge.get('source', ''), edge.get('target', ''))
            if s == source_id and t == target_id or (s == target_id and t == source_id):
                to_remove.append(edge)
        for e in to_remove:
            root.remove(e)
        return len(to_remove)

    def _read_classes_from_page(self, root):
        """Read all class data from a DrawIO page root. Returns list of concept dicts."""
        concepts = []
        for cell in root.findall('mxCell'):
            if cell.get('vertex') != '1':
                continue
            value = cell.get('value', '')
            name = self._extract_class_name(value)
            if not name:
                continue
            full_name, base, props, ops, invs = self._parse_class_html(value)
            concepts.append({'name': full_name or name, 'base': base, 'properties': props, 'operations': ops, 'invariants': invs})
        return concepts

    def _concept_to_md(self, concept):
        """Render a single concept dict to domain-model.md format."""
        name = concept['name']
        base = concept.get('base')
        header = f'**{name}**' + (f' : {base}' if base else '')
        lines = [header]
        for p in concept.get('properties', []):
            lines.append(f'- {p}')
        ops = concept.get('operations', [])
        if ops:
            lines.append('- Operations:')
            for o in ops:
                lines.append(f'  - {o}')
        for inv in concept.get('invariants', []):
            lines.append(f'- Invariant: {inv}')
        return '\n'.join(lines)

    def _parse_model_sections(self, md_text):
        """Parse domain-model.md into sections by foundational model name."""
        self._section_state = {
            'sections': {},
            'current_name': None,
            'current_start': None,
            'preamble_lines': [],
            'domain_model_started': False,
            'concepts_lines': [],
            'extensions_lines': [],
            'in_extensions': False,
        }
        for i, line in enumerate(md_text.split('\n')):
            self._consume_model_section_line(i, line)
        self._flush_model_section()
        return self._section_state['sections']

    def _flush_model_section(self) -> None:
        state = self._section_state
        if not state['current_name']:
            return
        state['sections'][state['current_name']] = {
            'preamble': '\n'.join(state['preamble_lines']),
            'concepts_text': '\n'.join(state['concepts_lines']),
            'extensions_text': '\n'.join(state['extensions_lines']),
            'start': state['current_start'],
        }

    def _consume_model_section_line(self, index, line) -> None:
        state = self._section_state
        if line.startswith('## ') and (not line.startswith('###')):
            self._flush_model_section()
            state['current_name'] = line[3:].strip()
            state['current_start'] = index
            state['preamble_lines'] = []
            state['concepts_lines'] = []
            state['extensions_lines'] = []
            state['domain_model_started'] = False
            state['in_extensions'] = False
            return
        if line.strip() == '### Domain Model':
            state['domain_model_started'] = True
            return
        if line.strip().startswith('### Extensions'):
            state['in_extensions'] = True
            return
        if not state['current_name']:
            return
        if not state['domain_model_started'] and (not state['in_extensions']):
            state['preamble_lines'].append(line)
            return
        if state['in_extensions']:
            state['extensions_lines'].append(line)
            return
        if state['domain_model_started']:
            state['concepts_lines'].append(line)

    def _parse_concepts_from_md(self, concepts_text):
        """Parse concept blocks from the concepts portion of a model section."""
        self._md_concepts = []
        self._md_current = None
        self._md_in_operations = False
        for line in concepts_text.split('\n'):
            self._apply_md_concept_line(line.strip())
        if self._md_current:
            self._md_concepts.append(self._md_current)
        return self._md_concepts

    def _apply_md_concept_line(self, stripped) -> None:
        if stripped.startswith('**') and (not stripped.startswith('**Rollable extensions')):
            self._start_md_concept(stripped)
            return
        current = self._md_current
        if current is None:
            return
        if stripped == '- Operations:':
            self._md_in_operations = True
            return
        if stripped.startswith('- Invariant:'):
            self._md_in_operations = False
            current['invariants'].append(stripped[len('- Invariant:'):].strip())
            return
        if stripped.startswith('- examples:'):
            self._md_in_operations = False
            return
        if self._md_in_operations and stripped.startswith('- '):
            current['operations'].append(stripped[2:].strip())
            return
        if (not self._md_in_operations) and stripped.startswith('- ') and (not stripped.startswith('- Operations')):
            prop = stripped[2:].strip()
            if prop:
                current['properties'].append(prop)

    def _start_md_concept(self, stripped) -> None:
        match = re.match('\\*\\*(\\w+)\\*\\*(?:\\s*:\\s*(\\w+))?', stripped)
        if not match:
            return
        if self._md_current:
            self._md_concepts.append(self._md_current)
        self._md_current = {'name': match.group(1), 'base': match.group(2), 'properties': [], 'operations': [], 'invariants': []}
        self._md_in_operations = False

    def _diff_concept(self, old, new):
        """Compare two concept dicts. Returns list of diff strings, empty if identical."""
        diffs = []
        if old.get('base') != new.get('base'):
            diffs.append(f"base: {old.get('base') or '(none)'} -> {new.get('base') or '(none)'}")
        diffs.extend(self._diff_named_list(old['properties'], (new['properties'], 'prop')))
        diffs.extend(self._diff_named_list(old['operations'], (new['operations'], 'op')))
        diffs.extend(self._diff_named_list(old['invariants'], (new['invariants'], 'inv')))
        return diffs

    def _diff_named_list(self, old_items, labeled):
        new_items, label = labeled
        diffs = []
        for item in new_items:
            if item not in old_items:
                diffs.append(f'+ {label}: {item}')
        for item in old_items:
            if item not in new_items:
                diffs.append(f'- {label}: {item}')
        return diffs

    def _sync_page_to_model(self, drawio_path, _rest):
        page_name, md_path = _rest
        'Sync classes from a DrawIO page back to domain-model.md.\n    Returns a dict describing changes: {added: [], removed: [], updated: []}.\n    '
        _, mxfile = self._load_drawio(drawio_path)
        _, root = self._get_page(mxfile, page_name)
        if root is None:
            raise ValueError(f"Page '{page_name}' not found in {drawio_path}")
        diagram_concepts = self._read_classes_from_page(root)
        md_text = Path(md_path).read_text(encoding='utf-8')
        sections = self._parse_model_sections(md_text)
        if page_name not in sections:
            raise ValueError(f"Section '{page_name}' not found in {md_path}")
        section = sections[page_name]
        changes = self._sync_concept_changes(diagram_concepts, self._parse_concepts_from_md(section['concepts_text']))
        self._rewrite_model_section((md_path, md_text, page_name, section, diagram_concepts))
        return changes

    def _sync_concept_changes(self, diagram_concepts, md_concepts):
        diagram_by_name = {c['name']: c for c in diagram_concepts}
        md_by_name = {c['name']: c for c in md_concepts}
        changes = {'added': [], 'removed': [], 'updated': []}
        for name in diagram_by_name:
            if name not in md_by_name:
                changes['added'].append({'name': name, 'concept': diagram_by_name[name]})
        for name in md_by_name:
            if name not in diagram_by_name:
                changes['removed'].append({'name': name, 'concept': md_by_name[name]})
        for name in diagram_by_name:
            if name not in md_by_name:
                continue
            diffs = self._diff_concept(md_by_name[name], diagram_by_name[name])
            if diffs:
                changes['updated'].append({'name': name, 'diffs': diffs})
        return changes

    def _rewrite_model_section(self, parts) -> None:
        md_path, md_text, page_name, section, diagram_concepts = parts
        new_concepts_lines = []
        for dc in diagram_concepts:
            new_concepts_lines.append('')
            new_concepts_lines.append(self._concept_to_md(dc))
        new_section_body = section['preamble'].rstrip() + '\n\n### Domain Model\n' + '\n'.join(new_concepts_lines) + '\n\n### Extensions\n' + section['extensions_text']
        lines = md_text.split('\n')
        end_line = self._section_end_line(lines, (section['start'], page_name))
        new_lines = lines[:section['start']]
        new_lines.append(f'## {page_name}')
        new_lines.append('')
        new_lines.append(new_section_body.rstrip())
        new_lines.append('')
        new_lines.extend(lines[end_line:])
        Path(md_path).write_text('\n'.join(new_lines), encoding='utf-8')

    def _section_end_line(self, lines, span) -> int:
        section_start, page_name = span
        next_section_start = len(lines)
        found_current = False
        for i, line in enumerate(lines):
            if not (line.startswith('## ') and (not line.startswith('###'))):
                continue
            if found_current:
                next_section_start = i
                break
            if line[3:].strip() == page_name:
                found_current = True
        for i in range(next_section_start - 1, section_start, -1):
            if lines[i].strip() == '---':
                return i
        return next_section_start

    def _eap_parse_style(self, style: str) -> dict:
        out: dict = {}
        for kv in (style or '').split(';'):
            if '=' not in kv:
                continue
            key, value = kv.split('=', 1)
            try:
                out[key] = float(value)
            except ValueError:
                continue
        return out

    def _eap_anchor_side(self, frac_x, frac_y):
        if frac_x is None or frac_y is None:
            return None
        if abs(frac_x - 0) < 0.001:
            return 'left'
        if abs(frac_x - 1) < 0.001:
            return 'right'
        if abs(frac_y - 0) < 0.001:
            return 'top'
        if abs(frac_y - 1) < 0.001:
            return 'bottom'
        return None

    def _eap_seg_orient(self, seg):
        (x1, y1), (x2, y2) = seg
        dx, dy = (abs(x2 - x1), abs(y2 - y1))
        if dx < 1 and dy < 1:
            return None
        if dx < 1:
            return 'v'
        if dy < 1:
            return 'h'
        return None

    def _eap_seg_dir_signed(self, seg):
        (x1, y1), (x2, y2) = seg
        dx, dy = (x2 - x1, y2 - y1)
        if abs(dx) < 1 and abs(dy) < 1:
            return None
        if abs(dx) >= abs(dy):
            return 'right' if dx > 0 else 'left'
        return 'down' if dy > 0 else 'up'

    def _eap_expected_orient(self, side):
        return {'left': 'h', 'right': 'h', 'top': 'v', 'bottom': 'v'}.get(side or '')

    def _eap_outward(self, side):
        return {'left': 'left', 'right': 'right', 'top': 'up', 'bottom': 'down'}.get(side or '')

    def _eap_inward(self, side):
        return {'left': 'right', 'right': 'left', 'top': 'down', 'bottom': 'up'}.get(side or '')

    def _eap_classify_edge(self, style: str) -> str:
        style = (style or '').lower()
        if 'endarrow=block' in style and 'startarrow=block' not in style:
            if 'endfill=0' in style:
                return 'inheritance-orthogonal' if 'orthogonal' in style else 'inheritance'
            return 'association'
        if 'startarrow=diamondthin' in style or 'startarrow=diamond' in style:
            return 'composition' if 'startfill=1' in style else 'aggregation'
        return 'association'

    def _check_edges_approach_perpendicular(self, root) -> list:
        """Return list of (edge_desc, end, side, expected_dir, actual_dir) for violations."""
        classes = self._get_all_classes(root)
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        violations = []
        for cell in root.findall('mxCell'):
            self._record_eap_edge(cell, violations)
        return violations

    def _record_eap_edge(self, cell, violations) -> None:
        if cell.get('edge') != '1':
            return
        src_id = cell.get('source', '')
        tgt_id = cell.get('target', '')
        if src_id not in self._id_to_name or tgt_id not in self._id_to_name:
            return
        style = cell.get('style', '')
        attrs = self._eap_parse_style(style)
        segs, _ = self._compute_edge_segments_ex(cell, self._id_to_geo)
        if not segs:
            return
        etype = self._eap_classify_edge(style)
        self._approach_desc = f'{self._id_to_name[src_id]}->{self._id_to_name[tgt_id]} ({etype})'
        self._approach_end = 'source'
        self._approach_side = self._eap_anchor_side(attrs.get('exitX'), attrs.get('exitY'))
        self._append_eap_end(violations, segs[0])
        self._approach_end = 'target'
        self._approach_side = self._eap_anchor_side(attrs.get('entryX'), attrs.get('entryY'))
        self._append_eap_end(violations, segs[-1])

    def _append_eap_end(self, violations, seg) -> None:
        side = self._approach_side
        end = self._approach_end
        desc = self._approach_desc
        expected = self._eap_expected_orient(side)
        actual = self._eap_seg_orient(seg)
        if expected and actual and (actual != expected):
            violations.append((desc, end, side, expected, actual))
            return
        want = self._eap_outward(side) if end == 'source' else self._eap_inward(side)
        got = self._eap_seg_dir_signed(seg)
        if want and got and (got != want):
            violations.append((desc, end, side, want, got))

    def _check_leaf_nodes_horizontal_row(self, root) -> list:
        """Return list of violation strings for hubs with 4+ leaves in a wide horizontal row."""
        self._leaf_geo = self._page_vertex_geo(root)
        neighbours = self._hub_neighbours(root)
        violations = []
        for hub_id, leaf_ids in neighbours.items():
            violations.extend(self._wide_leaf_row_hits(root, (hub_id, leaf_ids)))
        return violations

    def _page_vertex_geo(self, root) -> dict:
        geo: dict = {}
        for cell in root.findall('mxCell'):
            if cell.get('vertex') != '1':
                continue
            geometry = cell.find('mxGeometry')
            if geometry is None:
                continue
            w = geometry.get('width')
            h = geometry.get('height')
            if w is None or h is None:
                continue
            geo[cell.get('id', '')] = (float(geometry.get('x', 0)), float(geometry.get('y', 0)), float(w), float(h))
        return geo

    def _hub_neighbours(self, root) -> dict:
        neighbours: dict = {}
        geo = self._leaf_geo
        for cell in root.findall('mxCell'):
            if cell.get('edge') != '1':
                continue
            src = cell.get('source')
            tgt = cell.get('target')
            if src and tgt and (src in geo):
                neighbours.setdefault(src, set()).add(tgt)
        return neighbours

    def _wide_leaf_row_hits(self, root, hub) -> list:
        hub_id, leaf_ids = hub
        if len(leaf_ids) < _LEAF_ROW_MIN_SIZE:
            return []
        geo = self._leaf_geo
        hits = []
        for members in self._leaf_row_groups(leaf_ids).values():
            hit = self._wide_row_message(root, (hub_id, members))
            if hit:
                hits.append(hit)
        return hits

    def _leaf_row_groups(self, leaf_ids) -> dict:
        geo = self._leaf_geo
        row_groups: dict = {}
        for lid in leaf_ids:
            if lid not in geo:
                continue
            bucket = round(geo[lid][1] / _LEAF_ROW_Y_TOLERANCE)
            row_groups.setdefault(bucket, []).append(lid)
        return row_groups

    def _wide_row_message(self, root, members) -> str | None:
        hub_id, member_ids = members
        if len(member_ids) < _LEAF_ROW_MIN_SIZE:
            return None
        geo = self._leaf_geo
        y_vals = [geo[m][1] for m in member_ids]
        x_vals = [geo[m][0] for m in member_ids]
        y_spread = max(y_vals) - min(y_vals)
        x_spread = max(x_vals) - min(x_vals)
        if y_spread > _LEAF_ROW_Y_TOLERANCE or x_spread <= 600:
            return None
        hub_name = self._hub_display_name(root, hub_id)
        return f'{hub_name} has {len(member_ids)} leaf neighbours in a horizontal row (y~{int(sum(y_vals) / len(y_vals))}, x-span={int(x_spread)}px)'

    def _hub_display_name(self, root, hub_id) -> str:
        hub_cell = root.find(f"mxCell[@id='{hub_id}']")
        if hub_cell is None:
            return hub_id
        raw = hub_cell.get('value') or hub_id
        text = re.sub('<[^>]+>', '', raw)
        text = re.sub('&[a-z]+;', ' ', text)
        return re.split('[\\s+]', text.strip())[0] or hub_id

