class ToolsRunYaml:
    """Parse, replay, and fence toolset-run YAML from prompts and shell captures."""

    def __init__(self, workspace: Path | None = None, prefix: str = "") -> None:
        self._workspace = workspace
        self._prefix = prefix
        self._fence = YamlFence()

    def looks_like_tools_run_output(self, text: str) -> bool:
        has_ok_line = any(line.strip().startswith("ok:") for line in text.splitlines())
        if not has_ok_line:
            return False
        return any(
            line.strip().startswith(prefix)
            for line in text.splitlines()
            for prefix in ("resources:", "instructions:", "action:", "tool:")
        )

    def fenced_yaml_from_text(self, text: str) -> str | None:
        if "ok:" not in text:
            return None
        for match in re.finditer(r"```(?:yaml)?\s*\n(.*?)```", text, re.DOTALL | re.IGNORECASE):
            block = match.group(1)
            if self.looks_like_tools_run_output(block):
                return self._fence.fenced(block.strip())
        return None

    def extract_yaml_from_command(self, command: str) -> str | None:
        powershell = re.search(r'@"\s*\r?\n(.*?)\"@', command, re.DOTALL)
        if powershell:
            return powershell.group(1).strip()
        bash = re.search(r"<<-?\s*['\"]?(\w+)['\"]?\s*\r?\n(.*?)^\1", command, re.DOTALL | re.MULTILINE)
        if bash:
            return bash.group(2).strip()
        return None

    def yaml_from_prompt(self, prompt: str) -> str | None:
        heredoc = self.extract_yaml_from_command(prompt)
        if heredoc and heredoc.strip().startswith("toolset:"):
            return self._sanitize_yaml_body(heredoc)
        marker = re.search(
            r"(?:stdin:|YAML on stdin:)\s*\n+(toolset:.*?)(?:\n\nIMPORTANT:|\Z)",
            prompt,
            re.DOTALL | re.IGNORECASE,
        )
        if marker:
            return self._sanitize_yaml_body(marker.group(1))
        if "toolset:" not in prompt:
            return None
        return self._toolset_block_from_prompt(prompt)

    def _toolset_block_from_prompt(self, prompt: str) -> str | None:
        lines: list[str] = []
        collecting = False
        for line in prompt.splitlines():
            stripped = line.strip()
            if stripped.startswith("toolset:"):
                collecting = True
            if not collecting:
                continue
            if stripped.startswith("IMPORTANT:") or stripped.startswith("Return the complete"):
                break
            if stripped == '"@' or stripped == '@"':
                break
            lines.append(line)
        return "\n".join(lines).strip() or None

    def _sanitize_yaml_body(self, body: str) -> str:
        lines: list[str] = []
        for line in body.splitlines():
            stripped = line.strip()
            if stripped.startswith("IMPORTANT:"):
                break
            if stripped.startswith("Return the complete"):
                break
            lines.append(line)
        return "\n".join(lines).strip()

    def expected_run_fields_from_prompt(self, prompt: str) -> dict[str, str]:
        body = self.yaml_from_prompt(prompt)
        if not body:
            return {}
        expected: dict[str, str] = {}
        for line in body.splitlines():
            stripped = line.strip()
            if stripped.startswith("action:"):
                expected["action"] = stripped.split(":", 1)[1].strip()
            elif stripped.startswith("tool:"):
                expected["tool"] = stripped.split(":", 1)[1].strip()
        return expected

    def run_request(self, yaml_body: str) -> str:
        if yaml is None:
            raise AgentHarnessError("PyYAML required to parse run request", prefix=self._prefix)
        parsed = yaml.safe_load(yaml_body)
        if not isinstance(parsed, dict):
            raise AgentHarnessError("run request must be a mapping", prefix=self._prefix)
        response = invoke_run_request(parsed)
        return self._fence.fenced(self._fence.dump_manifest(response_to_dict(response)))

    def replay(self, command: str) -> str | None:
        if not _TOOLS_RUN.search(command):
            return None
        yaml_body = self.extract_yaml_from_command(command)
        if not yaml_body:
            return None
        try:
            return self.run_request(yaml_body)
        except AgentHarnessError:
            return None

class ToolsetInvoke:
    """Expand an action or invoke a tool on a live toolset instance."""

    def __init__(self, instance: Any, toolset_path: str) -> None:
        self._instance = instance
        self._toolset_path = toolset_path
        self._context: dict[str, Any] = {}
        self._arguments: dict[str, Any] = {}
        self._action_name: str | None = None
        self._tool_name: str | None = None

    @classmethod
    def create(cls, request: dict[str, Any]) -> ToolsetInvoke:
        from harness.agent_tools.agent_tools import AgentToolSet

        toolset_path = request.get("toolset")
        if not toolset_path:
            raise AgentHarnessError("request missing toolset")
        session = request.get("session")
        if session is not None:
            from workspace import SessionLog

            SessionLog.instance().set_session(str(session))
        context = dict(request.get("context") or {})
        arguments = dict(request.get("arguments") or {})
        try:
            instance = AgentToolSet.instantiate({"toolset": str(toolset_path), "context": context})
        except TypeError as exc:
            raise AgentHarnessError(str(exc)) from exc
        invoke = cls(instance, str(toolset_path))
        invoke._context = context
        invoke._arguments = arguments
        invoke._action_name = str(request["action"]) if request.get("action") else None
        invoke._tool_name = str(request["tool"]) if request.get("tool") else None
        return invoke

    def response(self) -> RunResponse:
        if self._action_name:
            return self.expanded_action()
        if not self._tool_name:
            raise AgentHarnessError("request missing tool or action")
        return self.invoked_tool()

    def expanded_action(self) -> RunResponse:
        try:
            expanded = self._instance.instructions[self._action_name].expand(
                self._context, self._arguments
            )
        except KeyError as exc:
            raise AgentHarnessError(f"unknown action {self._action_name!r}") from exc
        return RunResponse(
            ok=True,
            toolset=self._toolset_path,
            action=self._action_name,
            result=expanded.result,
            instructions=expanded.instructions,
            tools=list(expanded.tools),
            arguments=self._arguments,
            resources={},
        )

    def invoked_tool(self) -> RunResponse:
        from harness.agent_tools.agent_tools import AgentOperation

        member = self._instance.tools.get(self._tool_name)
        if member is None:
            raise AgentHarnessError(f"unknown tool {self._tool_name!r}")
        try:
            result = self._invoke_member(member)
        except TypeError as exc:
            raise AgentHarnessError(str(exc)) from exc
        return RunResponse(
            ok=True,
            toolset=self._toolset_path,
            tool=self._tool_name,
            result=result,
            resources={},
        )

    def _invoke_member(self, member: Any) -> Any:
        from harness.agent_tools.agent_tools import AgentOperation

        if isinstance(member, AgentOperation):
            return member.invoke(self._arguments)
        return getattr(self._instance, self._tool_name)(**self._arguments)

class AgentToolSet(AgentToolSetOrigin, AgentToolSetTools):
    """Injected by @agent_toolset — operations and @agent_instructions on one toolset."""

    _mode: str = "instructions"
    _MEMBER_MARKS = ("_is_agent_tool", "_is_agent_instructions", "_hook")

    @property
    def mode(self) -> ExpansionMode:
        """Execution mode for @agent_instructions calls into this instance.
        instructions = expand inline; tool = list action in tools, defer its body."""
        return ExpansionMode(self._mode)

    @mode.setter
    def mode(self, new_mode: str | ExpansionMode) -> None:
        value = new_mode.value if isinstance(new_mode, ExpansionMode) else new_mode
        if value not in ("instructions", "tool"):
            raise ValueError(f"mode must be 'instructions' or 'tool', got {value!r}")
        self._mode = value

    def _discover_operations(self) -> dict[str, AgentOperation]:
        discovered: dict[str, AgentOperation] = {}
        for name, member in self._marked_members(type(self)):
            if getattr(member, "_is_agent_tool", False):
                discovered[name] = AgentOperation(
                    name=name,
                    callable=self._bound_callable(name, member),
                    toolset=self,
                )
        return discovered

    def _discover_instruction_members(self) -> dict[str, AgentInstructions]:
        discovered: dict[str, AgentInstructions] = {}
        for name, member in self._marked_members(type(self)):
            if getattr(member, "_is_agent_instructions", False):
                discovered[name] = AgentInstructions(
                    name=name,
                    callable=self._bound_callable(name, member),
                    toolset=self,
                )
        return discovered

    def _discover_hook_members(self) -> dict[str, AgentTool]:
        discovered: dict[str, AgentTool] = {}
        for name, member in self._marked_members(type(self)):
            if getattr(member, "_hook", False):
                discovered[name] = AgentTool(
                    name=name,
                    callable=self._bound_callable(name, member),
                    toolset=self,
                )
        return discovered

    def _discover_collection_tools(self) -> dict[str, AgentTool]:
        found: dict[str, AgentTool] = {}
        for _key, collection in self._own_tool_collections():
            found.update(self._rehost_collection_tools(collection, prefix=""))
        for key, collection in self._nested_tool_collections():
            found.update(self._rehost_collection_tools(collection, prefix=f"{key}."))
        return found

    def _own_tool_collections(self) -> list[tuple[str, Any]]:
        return self._collections_on(self)

    def _nested_tool_collections(self) -> list[tuple[str, Any]]:
        items: list[tuple[str, Any]] = []
        for collection in self.toolset_collections:
            for key, child in getattr(collection, "entries", {}).items():
                items.extend(
                    (key, bag) for _name, bag in self._collections_on(child)
                )
        return items

    def _rehost_collection_tools(self, collection: Any, prefix: str) -> dict[str, AgentTool]:
        found: dict[str, AgentTool] = {}
        for name, tool in (getattr(collection, "tools", None) or {}).items():
            if prefix and name == "inject_rules":
                continue
            found[f"{prefix}{name}"] = AgentTool(
                name=name,
                callable=getattr(tool, "callable", None) or getattr(collection, name),
                toolset=self,
            )
        return found

    def _collections_on(self, instance: Any) -> list[tuple[str, Any]]:
        if instance is None:
            return []
        found: list[tuple[str, Any]] = []
        owner = type(instance)
        for name, member in self._annotated_members(owner):
            if name in self._COLLECTION_SKIP:
                continue
            annotation = self._return_type(member, owner)
            marked = any(getattr(member, mark, False) for mark in (*self._MEMBER_MARKS, "_rules"))
            if not self._is_collection_type(annotation) and not marked:
                continue
            value = getattr(instance, name, None)
            if value is instance or not self._is_tool_collection(value):
                continue
            found.append((name, value))
        return found

    def _return_type(self, member: Any, owner: type) -> Any:
        annot = getattr(member, "__annotations__", {}).get("return")
        if isinstance(annot, type):
            return annot
        if isinstance(annot, str):
            resolved = getattr(member, "__globals__", {}).get(annot)
            module = sys.modules.get(owner.__module__)
            if resolved is None and module is not None:
                resolved = getattr(module, annot, None)
            return resolved
        return annot

    def _is_collection_type(self, annotation: Any) -> bool:
        if not isinstance(annotation, type):
            return False
        if issubclass(annotation, ToolSetCollection):
            return True
        return bool(
            getattr(annotation, "_is_toolset_collection", False)
            or getattr(annotation, "_is_agent_toolset", False)
        )

    def _is_tool_collection(self, value: Any) -> bool:
        if value is None:
            return False
        if isinstance(value, ToolSetCollection):
            return True
        return bool(
            getattr(type(value), "_is_toolset_collection", False)
            or getattr(type(value), "_is_agent_toolset", False)
        )

    def _annotated_members(self, owner: type) -> list[tuple[str, Any]]:
        seen: set[str] = set()
        members: list[tuple[str, Any]] = []
        for name, member in inspect.getmembers(owner, predicate=inspect.isfunction):
            seen.add(name)
            members.append((name, member))
        for name, member in inspect.getmembers(owner, predicate=inspect.isdatadescriptor):
            getter = getattr(member, "fget", None)
            if getter is not None and name not in seen:
                members.append((name, getter))
        return members

    def _marked_members(self, owner: type) -> list[tuple[str, Any]]:
        return [
            (name, member)
            for name, member in self._annotated_members(owner)
            if any(getattr(member, mark, False) for mark in self._MEMBER_MARKS)
        ]

    def _bound_callable(self, name: str, member: Any) -> Any:
        attr = getattr(type(self), name, None)
        if inspect.isfunction(member) and attr is member:
            return getattr(self, name)
        return member

    def marked_tool_names(self, toolset_cls: type) -> set[str]:
        return {
            name
            for name, member in self._marked_members(toolset_cls)
            if getattr(member, "_is_agent_tool", False)
        }

    def instruction_names(self, toolset_cls: type) -> frozenset[str]:
        return frozenset(
            name
            for name, member in self._marked_members(toolset_cls)
            if getattr(member, "_is_agent_instructions", False)
        )


    class _InstructionBodyValidator(ast.NodeVisitor):
        """Validate ``tools(...)`` and ``instructions(...)`` in one ``@agent_instructions`` body.

        Invoked from ``_validate_action`` when an ``@agent_toolset`` class is registered.
        Walks the action AST and raises ``AgentToolValidationError`` when a wrapper
        names a member that is not an allowed ``@agent_tool``, ``@agent_instructions``
        peer, loop-bound companion, or recognized cross-toolset provider. The visit
        performs the check — not a passive tree walk for something else to interpret.
        """

        def __init__(
            self,
            *,
            allowed_names: set[str],
            all_providers: set[str],
            class_name: str,
            action_name: str,
            host: AgentToolSet,
            instructions: AgentInstructions,
        ) -> None:
            self._allowed_names = allowed_names
            self._all_providers = all_providers
            self._class_name = class_name
            self._action_name = action_name
            self._host = host
            self._instructions = instructions
            self._loop_vars: list[str] = []

        def visit_For(self, node: ast.For) -> None:
            if isinstance(node.target, ast.Name):
                self._loop_vars.append(node.target.id)
                self.generic_visit(node)
                self._loop_vars.pop()
                return
            self.generic_visit(node)

        def _validate_wrapper_arg(self, wrapper: str, arg: ast.AST | None) -> bool:
            if arg is None:
                if wrapper == "tools":
                    raise AgentToolValidationError(
                        f"{wrapper}(...) requires one argument",
                        class_name=self._class_name,
                        action_name=self._action_name,
                    )
                return False
            if self._host.provider_cross_call(arg) is not None:
                return True
            if self._loop_vars and self._host.provider_cross_call(
                arg, frozenset(self._loop_vars)
            ) is not None:
                return True
            if isinstance(arg, ast.Call) and isinstance(arg.func, ast.Attribute):
                if isinstance(arg.func.value, ast.Name) and arg.func.value.id in self._loop_vars:
                    return True
            if isinstance(arg, ast.Attribute) and isinstance(arg.value, ast.Name):
                if arg.value.id in self._loop_vars:
                    return True
            member = self._instructions.self_member_name(arg)
            if member is not None:
                self._check_member(member)
                return True
            if wrapper == "tools":
                raise AgentToolValidationError(
                    f"{wrapper}(...) argument is not a recognized tool step",
                    class_name=self._class_name,
                    action_name=self._action_name,
                )
            return False

        def _check_member(self, member_name: str) -> None:
            if member_name in self._allowed_names or member_name in self._all_providers:
                return
            raise AgentToolValidationError(
                f"{member_name!r} is not an allowed tool step",
                class_name=self._class_name,
                action_name=self._action_name,
            )

        def visit_Call(self, node: ast.Call) -> None:
            if isinstance(node.func, ast.Name) and node.func.id == "tools":
                if self._validate_wrapper_arg("tools", node.args[0] if node.args else None):
                    return
            if isinstance(node.func, ast.Name) and node.func.id == "instructions":
                if self._validate_wrapper_arg(
                    "instructions", node.args[0] if node.args else None
                ):
                    return
            self.generic_visit(node)

    def _validate_self_param(self, action_func: Callable[..., Any]) -> None:
        params = list(inspect.signature(action_func).parameters.values())
        class_name = self._validating_class_name
        action_name = action_func.__name__
        if not params or params[0].name != "self":
            raise AgentToolValidationError(
                "first parameter must be named 'self'",
                class_name=class_name,
                action_name=action_name,
            )
        if params[0].default is not inspect.Parameter.empty:
            raise AgentToolValidationError(
                "self parameter must not have a default",
                class_name=class_name,
                action_name=action_name,
            )

    def _validate_action(self, action_func: Callable[..., Any]) -> None:
        self._validate_self_param(action_func)
        instructions = AgentInstructions.for_callable(action_func)
        body_ast = instructions.parse_source(action_func)
        all_providers = self._cross_instance_providers(body_ast) | self._for_each_providers(
            body_ast
        )
        self._InstructionBodyValidator(
            allowed_names=self._allowed_names,
            all_providers=all_providers,
            class_name=self._validating_class_name,
            action_name=action_func.__name__,
            host=self,
            instructions=instructions,
        ).visit(body_ast)

    def _validate_toolset_class(self, toolset_cls: type) -> None:
        self._validating_class_name = toolset_cls.__name__
        self._allowed_names = self.marked_tool_names(toolset_cls) | set(
            self.instruction_names(toolset_cls)
        )
        for name, member in inspect.getmembers(toolset_cls, predicate=inspect.isfunction):
            if not getattr(member, "_is_agent_instructions", False):
                continue
            self._validate_action(member)

    def _validate_toolset(self, toolset_cls: type) -> None:
        self._validate_toolset_class(toolset_cls)

    def provider_cross_call(
        self,
        node: ast.AST,
        roots: frozenset[str] = frozenset({"self"}),
    ) -> tuple[str, str] | None:
        """Match ``<root>.<provider>().<member>()``, ``<root>.<provider>.<member>()``,
        or the same chains as a property (no trailing call)."""
        member, provider_node = self._cross_member_and_provider(node)
        if member is None:
            return None
        provider_attr = provider_node.func if isinstance(provider_node, ast.Call) else provider_node
        if not isinstance(provider_attr, ast.Attribute):
            return None
        if not isinstance(provider_attr.value, ast.Name) or provider_attr.value.id not in roots:
            return None
        return provider_attr.attr, member

    def _cross_member_and_provider(self, node: ast.AST) -> tuple[str | None, ast.AST | None]:
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            return node.func.attr, node.func.value
        if isinstance(node, ast.Attribute):
            return node.attr, node.value
        return None, None

    def _cross_instance_call(self, node: ast.AST) -> tuple[str, str] | None:
        return self.provider_cross_call(node, frozenset({"self"}))

    def _cross_instance_providers(self, body: ast.Module) -> set[str]:
        providers: set[str] = set()
        for node in ast.walk(body):
            cross = self._cross_instance_call(node)
            if cross is not None:
                providers.add(cross[0])
        return providers

    def _for_each_providers(self, body: ast.Module) -> set[str]:
        providers: set[str] = set()
        names = AgentInstructions.for_callable(lambda self: None)
        for node in ast.walk(body):
            if not isinstance(node, ast.For):
                continue
            iter_member = names.self_member_name(node.iter)
            if iter_member is not None:
                providers.add(iter_member)
        return providers

    @classmethod
    def instantiate(cls, item: Any = None) -> Any:
        if item is None:
            return cls()
        if isinstance(item, dict) and "toolset" in item:
            loaded = cls._load(str(item["toolset"]))
            context = dict(item.get("context") or {})
            for key, value in item.items():
                if key not in {"toolset", "context"}:
                    context.setdefault(key, value)
            return loaded(**context)
        if isinstance(item, dict):
            return cls(**item)
        if isinstance(item, str):
            return cls._load(item)()
        if isinstance(item, type):
            return item()
        return item

    @classmethod
    def instantiate_all(cls, items: list) -> list:
        return [cls.instantiate(item) for item in items]

    @classmethod
    def from_items(
        cls,
        items: list[Any],
        *,
        context: dict[str, object] | None = None,
        skip_errors: bool = False,
    ) -> list[Any]:
        prepared: list[Any] = []
        for item in items:
            if isinstance(item, str) and context is not None:
                prepared.append({"toolset": item, "context": dict(context)})
            else:
                prepared.append(item)
        unique: list[Any] = []
        seen: set[type] = set()
        for item in prepared:
            try:
                instance = cls.instantiate(item)
            except Exception:
                if skip_errors:
                    continue
                raise
            owner = type(instance)
            if owner in seen:
                continue
            seen.add(owner)
            unique.append(instance)
        return unique

    @classmethod
    def _check_toolset(cls, candidate: type) -> bool:
        return isinstance(candidate, type) and getattr(candidate, "_is_agent_toolset", False)

    @classmethod
    def _load(cls, path: str) -> type:
        module_name, _, class_name = path.partition(":")
        if not class_name:
            raise ValueError(f"expected <module>:<Class>, got {path!r}")
        try:
            module = __import__(module_name, fromlist=[class_name])
        except ModuleNotFoundError:
            module = cls()._load_hyphenated(module_name)
        loaded = getattr(module, class_name)
        if not cls._check_toolset(loaded):
            raise TypeError(f"{path} is not a @agent_toolset class")
        return loaded

    def _file_under_root(self, root: Path, parts: list[str]) -> Path | None:
        search = root
        for part in parts[:-1]:
            hyphenated = part.replace("_", "-")
            candidate = search / hyphenated
            search = candidate if candidate.is_dir() else search / part
        candidate_file = search / f"{parts[-1]}.py"
        if candidate_file.exists():
            return candidate_file
        return None

    def _hyphenated_module_file(self, module_name: str) -> Path:
        parts = module_name.split(".")
        repo = Path(__file__).resolve().parents[2]
        search_roots = [repo] + [
            repo / name
            for name in (
                "harness",
                "tools",
                "practices",
                "actions",
                "builders",
                "installation",
            )
        ]
        for root in search_roots:
            located = self._file_under_root(root, parts)
            if located is not None:
                return located
        raise ModuleNotFoundError(
            f"No module named {module_name!r} (also tried under {search_roots})"
        )

    def _load_hyphenated(self, module_name: str):
        module_file = self._hyphenated_module_file(module_name)
        spec = importlib.util.spec_from_file_location(module_name, module_file)
        if spec is None or spec.loader is None:
            raise ModuleNotFoundError(f"Cannot create spec for {module_file}")
        mod = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = mod
        spec.loader.exec_module(mod)  # type: ignore[union-attr]
        return mod

    def validate(self) -> None:
        self._validate_toolset_class(type(self))

class SessionLog(ISessionLog):
    """Append-only session log with optional full payload files."""

    _instance: SessionLog | None = None

    @staticmethod
    def _session_cls():
        from workspace.legacy.workspace import WorkSession, Workspace

        return WorkSession, Workspace

    def __init__(self, sessions_root: Path | None = None) -> None:
        # Test override only: when set, log_dir = sessions_root / session.name
        self._sessions_root = sessions_root
        work_session_cls, workspace_cls = SessionLog._session_cls()
        self._session = work_session_cls(workspace_cls("."), "default")
        self._last_payload: _LastPayload | None = None
        self._event_count = 0

    @classmethod
    def instance(cls) -> SessionLog:
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    @classmethod
    def set_instance(cls, log: SessionLog | None) -> None:
        cls._instance = log

    @property
    def session(self) -> WorkSession:
        return self._session

    @property
    def session_name(self) -> str:
        return self._session.name or "default"

    @property
    def log_dir(self) -> Path:
        if self._sessions_root is not None:
            return self._sessions_root / self.session_name
        return self._session.log

    @property
    def last_payload(self) -> _LastPayload | None:
        return self._last_payload

    def bind(self, session: WorkSession) -> None:
        """Bind a WorkSession; events go under ``session.log``."""
        self._session = session

    def set_session(self, session: str | WorkSession | None) -> None:
        """Bind a WorkSession, or a name (legacy) as ``WorkSession(Workspace("."), name)``."""
        work_session_cls, workspace_cls = SessionLog._session_cls()
        if isinstance(session, work_session_cls):
            self.bind(session)
            return
        name = (session or "").strip() or "default"
        self._session = work_session_cls(workspace_cls("."), name)

    def append(
        self,
        *,
        toolset: str,
        name: str,
        summary: str,
        ok: bool,
        error: str | None = None,
        role: str = "",
        kind: str | None = None,
        payload: dict[str, Any] | None = None,
    ) -> None:
        self._event_count += 1
        index = self._event_count
        self.log_dir.mkdir(parents=True, exist_ok=True)
        payload_ref = self._maybe_write_payloads(index, payload)
        effective_role = role or (kind if kind in ("expansion", "run") else "")
        line = self._format_event_line(
            toolset=toolset,
            name=name,
            summary=summary,
            ok=ok,
            error=error,
            role=effective_role,
            kind=kind,
            payload_ref=payload_ref,
        )
        with (self.log_dir / "events.log").open("a", encoding="utf-8") as fh:
            fh.write(line + "\n")
        if payload is not None:
            self._last_payload = _LastPayload(
                event_index=index,
                request=payload.get("request"),
                response=payload.get("response"),
            )
        self._mirror_to_open_turn(
            toolset=toolset,
            name=name,
            summary=summary,
            ok=ok,
            error=error,
            role=effective_role,
        )

    def _mirror_to_open_turn(
        self,
        *,
        toolset: str,
        name: str,
        summary: str,
        ok: bool,
        error: str | None,
        role: str,
    ) -> None:
        open_turn = getattr(self._session, "open_turn", None)
        if open_turn is None:
            return
        from workspace.legacy.workspace import ToolCall

        open_turn.tool_calls.append(
            ToolCall(
                toolset=toolset,
                name=name,
                summary=summary,
                ok=ok,
                error=error or "",
                role=role,
            )
        )

    def _maybe_write_payloads(
        self, index: int, payload: dict[str, Any] | None
    ) -> str | None:
        # Verbose payload files are author-opt-in via payload only when writing
        # companion files is requested by passing payload and keeping last_payload.
        if payload is None:
            return None
        return None

    def _write_payload_files(self, index: int, payload: dict[str, Any]) -> tuple[str, str]:
        req_name = f"event-{index:03d}-request.yaml"
        res_name = f"event-{index:03d}-response.yaml"
        (self.log_dir / req_name).write_text(
            self._dump_yamlish(payload.get("request")),
            encoding="utf-8",
        )
        (self.log_dir / res_name).write_text(
            self._dump_yamlish(payload.get("response")),
            encoding="utf-8",
        )
        return req_name, res_name

    @staticmethod
    def _format_event_line(
        *,
        toolset: str,
        name: str,
        summary: str,
        ok: bool,
        error: str | None,
        role: str,
        kind: str | None,
        payload_ref: str | None,
    ) -> str:
        ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
        parts = [
            ts,
            f"toolset={toolset}",
            f"name={name}",
            f"ok={'true' if ok else 'false'}",
            f"summary={summary}",
        ]
        if kind:
            parts.insert(1, f"kind={kind}")
        if role:
            parts.append(f"role={role}")
        if error:
            parts.append(f"error={error}")
        if payload_ref:
            parts.append(f"payload={payload_ref}")
        return " ".join(parts)

    @staticmethod
    def _dump_yamlish(value: Any) -> str:
        try:
            import yaml

            return yaml.safe_dump(value, sort_keys=False)
        except (ImportError, TypeError, ValueError):
            return json.dumps(value, indent=2, default=str)

