class MiroApiError(Exception):
    """Raised on non-retryable API errors."""

    def __init__(self, status: int, body: str) -> None:
        super().__init__(f"HTTP {status}: {body}")
        self.status = status
        self.body = body

class MiroApiClient:
    """Thin wrapper around the Miro REST API v2."""

    def __init__(self, token: Optional[str] = None) -> None:
        self.token = token or self._resolve_token()

    @classmethod
    def create(cls, token: Optional[str] = None) -> "MiroApiClient":
        client = cls(token)
        if client.token:
            return client
        raise MiroAuthError(
            "Miro API token not found. "
            "Set MIRO_TOKEN env var, create ~/.miro-token, "
            "or get a PAT at https://miro.com/app/settings/user-profile/apps"
        )

    # ------------------------------------------------------------------
    # Board shape CRUD
    # ------------------------------------------------------------------

    def create_shape(
        self,
        board_id: str,
        x: float,
        y: float,
        w: float,
        h: float,
        fill: str,
        stroke: str,
        stroke_width: float = 1.0,
        content: str = "",
        rx: int = 0,
        font_size: int = 14,
    ) -> dict:
        """Create a rectangle (or round_rectangle) shape on the board.

        ``x`` / ``y`` are the **centre** of the shape in Miro board units,
        relative to canvas_center.
        """
        shape_type = "round_rectangle" if rx > 0 else "rectangle"
        payload: dict[str, Any] = {
            "data": {"shape": shape_type, "content": f"<p>{self._html_escape(content)}</p>"},
            "style": {
                "fillColor": fill,
                "fillOpacity": "1.0",
                "borderColor": stroke,
                "borderWidth": str(float(stroke_width)),
                "borderOpacity": "1.0",
                "borderStyle": "normal",
                "textAlign": "center",
                "textAlignVertical": "middle",
                "fontSize": str(max(12, int(font_size))),
                "fontFamily": "open_sans",
                "color": "#1a1a1a",
            },
            "geometry": {"width": w, "height": h},
            "position": {"x": x, "y": y},
        }
        return self._request("POST", f"/boards/{self._encode(board_id)}/shapes", payload)

    def delete_shape(self, board_id: str, shape_id: str) -> None:
        """Delete one shape. Silently ignores 404 (already gone)."""
        try:
            self._request("DELETE", f"/boards/{self._encode(board_id)}/shapes/{shape_id}")
        except MiroApiError as exc:
            if exc.status != 404:
                raise

    def list_shapes(self, board_id: str) -> Iterator[dict]:
        """Paginate through all shapes on the board."""
        cursor: Optional[str] = None
        while True:
            params: dict[str, Any] = {"limit": 50}
            if cursor:
                params["cursor"] = cursor
            page = self._request("GET", f"/boards/{self._encode(board_id)}/shapes", params=params)
            for item in page.get("data", []):
                yield item
            cursor = page.get("cursor")
            has_more = page.get("has_more", False)
            if not has_more or not cursor:
                break

    # ------------------------------------------------------------------
    # Internal
    # ------------------------------------------------------------------

    def _request(
        self,
        method: str,
        path: str,
        body: Optional[dict] = None,
        params: Optional[dict] = None,
        retries: int = 0,
    ) -> dict:
        url = _API_BASE + path
        if params:
            url += "?" + urllib.parse.urlencode(params)
        data = json.dumps(body).encode() if body else None
        req = urllib.request.Request(
            url,
            data=data,
            method=method,
            headers={
                "Authorization": f"Bearer {self.token}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )
        try:
            with urllib.request.urlopen(req) as resp:
                raw = resp.read()
                return json.loads(raw) if raw else {}
        except urllib.error.HTTPError as exc:
            status = exc.code
            raw_body = exc.read().decode(errors="replace")
            if status == 429 and retries < _MAX_RETRIES:
                time.sleep(_RATE_LIMIT_SLEEP_S)
                return self._request(method, path, body, params, retries + 1)
            if status in (500, 502, 503, 504) and retries < _MAX_RETRIES:
                time.sleep(_RETRY_SLEEP_S * (retries + 1))
                return self._request(method, path, body, params, retries + 1)
            raise MiroApiError(status, raw_body) from exc

    def _resolve_token(self) -> Optional[str]:
        tok = os.environ.get("MIRO_TOKEN", "").strip()
        if tok:
            return tok
        for candidate in [
            os.path.expanduser("~/.miro-token"),
            os.path.join(".cursor", "miro-token.txt"),
        ]:
            if os.path.isfile(candidate):
                raw = open(candidate, encoding="utf-8-sig").read().strip()
                return raw or None
        return None


    def _encode(self, board_id: str) -> str:
        return urllib.parse.quote(board_id, safe="")

    def _html_escape(self, text: str) -> str:
        return (
            text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;")
        )

class ArchitectureContext:
    _KNOWN_TIER_HINTS = (
        "server", "client", "e2e", "domain", "api", "web", "unit", "integration",
        "ui", "browser", "cli", "mobile", "playwright",
    )

    _TIER_LINE = re.compile(
        r"^\s*[-*]?\s*(?:tiers?|testing\s+tiers?)\s*[:=]\s*(.+)$",
        re.IGNORECASE,
    )
    _TIER_BULLET = re.compile(r"^\s*[-*]\s+`?(?P<tier>[a-z][a-z0-9-]{1,20})`?\b")
    _SPEC_FILE_TIER_RE = re.compile(
        r"^[a-z0-9-]+-(?P<tier>[a-z][a-z0-9]{0,20})\.(?:ts|tsx|js|py|java)$"
    )
    _TEST_FILE_TIER_RE = re.compile(
        r"^[a-z0-9-]+-(?P<tier>[a-z][a-z0-9]{0,20})\.test\.(?:ts|tsx|js|py|java)$"
    )

    def read_tiers(
        self,
        architecture_context_path: Optional[Path],
        tests_root: Optional[Path] = None,
    ) -> Tuple[str, ...]:
        if architecture_context_path is not None and architecture_context_path.exists():
            tiers = self._read_from_prose(architecture_context_path.read_text(encoding="utf-8"))
            if tiers:
                return tiers
        if tests_root is not None and tests_root.exists():
            return self._infer_from_filesystem(tests_root)
        return ()

    def _read_from_prose(self, text: str) -> Tuple[str, ...]:
        lines = text.splitlines()
        for line in lines:
            m = self._TIER_LINE.match(line)
            if m:
                return self._split_tier_list(m.group(1))
        return self._tiers_from_heading(lines)

    def _tiers_from_heading(self, lines: Sequence[str]) -> Tuple[str, ...]:
        heading_re = re.compile(r"^#+\s+.*tiers?\b", re.IGNORECASE)
        for i, line in enumerate(lines):
            if heading_re.match(line):
                collected = self._collect_tier_bullets(lines, i)
                if collected:
                    return self._dedupe_ordered(collected)
        return ()

    def _collect_tier_bullets(self, lines: Sequence[str], heading_index: int) -> list[str]:
        collected: list[str] = []
        for j in range(heading_index + 1, len(lines)):
            raw = lines[j]
            if raw.startswith("#"):
                break
            m = self._TIER_BULLET.match(raw)
            if not m:
                if raw.strip() == "" or raw.startswith(" ") or raw.startswith("\t"):
                    continue
                if raw.strip() and not raw.startswith("-") and not raw.startswith("*"):
                    break
                continue
            tier = m.group("tier").lower()
            if tier in self._KNOWN_TIER_HINTS or self._looks_like_tier(tier):
                collected.append(tier)
        return collected

    def _split_tier_list(self, raw: str) -> Tuple[str, ...]:
        parts = re.split(r"[,/|]+|\s+and\s+|\s{2,}", raw)
        cleaned = []
        for p in parts:
            slug = p.strip().strip("`*_").lower()
            if not slug:
                continue
            slug = slug.split()[0]
            if self._looks_like_tier(slug):
                cleaned.append(slug)
        return self._dedupe_ordered(cleaned)

    def _looks_like_tier(self, candidate: str) -> bool:
        return bool(re.fullmatch(r"[a-z][a-z0-9-]{1,20}", candidate))

    def _dedupe_ordered(self, items: Iterable[str]) -> Tuple[str, ...]:
        seen: set[str] = set()
        ordered: list[str] = []
        for item in items:
            if item in seen:
                continue
            seen.add(item)
            ordered.append(item)
        return tuple(ordered)

    def _infer_from_filesystem(self, tests_root: Path) -> Tuple[str, ...]:
        tiers: list[str] = []
        for candidate in tests_root.rglob("*"):
            if not candidate.is_file():
                continue
            m = self._TEST_FILE_TIER_RE.match(candidate.name)
            if m is None:
                m = self._SPEC_FILE_TIER_RE.match(candidate.name)
                if m is None:
                    continue
                if m.group("tier") == "stories":
                    continue
            tier = m.group("tier").lower()
            if tier == "stories":
                continue
            tiers.append(tier)
        return self._dedupe_ordered(tiers)

class TypeScriptScanner(MERNScanner):
    """MERNScanner backed by tree-sitter TypeScript AST analysis.

    Falls back to returning no structured results when tree-sitter is not
    installed (``pip install "tree-sitter>=0.23" tree-sitter-typescript``) -
    subclasses relying purely on structured extraction return no violations
    rather than raising.
    """

    TREE_SITTER_AVAILABLE: bool = _TREE_SITTER_AVAILABLE

    def _txt(self, node) -> str:
        if node is None:
            return ""
        b = node.text
        return b.decode("utf-8", errors="replace") if isinstance(b, bytes) else str(b or "")


    def _find_all(self, node, *types: str) -> list:
        results: list = []
        if node.type in types:
            results.append(node)
        for child in node.children:
            results.extend(self._find_all(child, *types))
        return results


    _MODIFIER_TYPES = frozenset(
        {"public", "private", "protected", "abstract", "static", "readonly", "async", "override", "declare"}
    )


    def _get_modifiers(self, node) -> List[str]:
        mods: List[str] = []
        for child in node.children:
            if child.type in self._MODIFIER_TYPES:
                mods.append(child.type)
            elif child.type == "accessibility_modifier":
                mods.append(self._txt(child))
        return mods


    def _parse_method_node(self, method_node) -> MethodInfo:
        name_node = method_node.child_by_field_name("name")
        name = self._txt(name_node)
        modifiers = self._get_modifiers(method_node)
        return_type_node = method_node.child_by_field_name("return_type")
        return_type = self._txt(return_type_node).lstrip(":").strip() if return_type_node else None
        params_node = method_node.child_by_field_name("parameters")
        param_count = 0
        if params_node:
            param_count = sum(1 for c in params_node.children if c.type not in (",", "(", ")", "comment"))
        return MethodInfo(
            name=name,
            is_async="async" in modifiers,
            is_static="static" in modifiers,
            is_abstract="abstract" in modifiers,
            modifiers=modifiers,
            return_type=return_type,
            param_count=param_count,
            start_line=method_node.start_point[0] + 1,
            end_line=method_node.end_point[0] + 1,
        )


    def _parse_property_node(self, prop_node) -> PropertyInfo:
        name_node = prop_node.child_by_field_name("name")
        name = self._txt(name_node)
        modifiers = self._get_modifiers(prop_node)
        type_node = prop_node.child_by_field_name("type")
        type_ann = self._txt(type_node).lstrip(":").strip() if type_node else None
        return PropertyInfo(
            name=name,
            type_annotation=type_ann,
            modifiers=modifiers,
            start_line=prop_node.start_point[0] + 1,
        )


    def _type_name_from_item(self, item) -> str:
        if item.type in ("type_identifier", "identifier"):
            return self._txt(item)
        if item.type == "generic_type":
            inner = item.child_by_field_name("name")
            return self._txt(inner) if inner else self._txt(item)
        return ""


    def _parse_class_node(self, class_node, is_exported: bool = False) -> ClassInfo:
        name_node = class_node.child_by_field_name("name")
        name = self._txt(name_node)
        start_line = class_node.start_point[0] + 1
        end_line = class_node.end_point[0] + 1
        is_abstract = any(c.type == "abstract" for c in class_node.children)
        extends, implements = self._class_heritage(class_node)
        methods: List[MethodInfo] = []
        properties: List[PropertyInfo] = []
        body = class_node.child_by_field_name("body")
        if body:
            for member in body.children:
                if member.type in ("method_definition", "abstract_method_signature"):
                    methods.append(self._parse_method_node(member))
                elif member.type in ("public_field_definition", "field_definition"):
                    properties.append(self._parse_property_node(member))
        return ClassInfo(
            name=name,
            implements=implements,
            extends=extends,
            methods=methods,
            properties=properties,
            is_abstract=is_abstract,
            is_exported=is_exported,
            start_line=start_line,
            end_line=end_line,
        )


    def _class_heritage(self, class_node) -> tuple[Optional[str], List[str]]:
        extends: Optional[str] = None
        implements: List[str] = []
        for child in class_node.children:
            if child.type != "class_heritage":
                continue
            for clause in child.children:
                if clause.type == "extends_clause":
                    extends = self._first_type_in_clause(clause) or extends
                elif clause.type == "implements_clause":
                    implements.extend(self._type_names_in_clause(clause))
        return extends, implements


    def _first_type_in_clause(self, clause) -> str:
        for item in clause.children:
            name = self._type_name_from_item(item)
            if name:
                return name
        return ""


    def _type_names_in_clause(self, clause) -> List[str]:
        names: List[str] = []
        for item in clause.children:
            name = self._type_name_from_item(item)
            if name:
                names.append(name)
        return names


    def _named_import_names(self, clause) -> tuple[list[str], Optional[str], bool]:
        names: List[str] = []
        default_name: Optional[str] = None
        is_type_only = False
        for sub in clause.children:
            if sub.type == "type":
                is_type_only = True
            elif sub.type == "identifier":
                default_name = self._txt(sub)
            elif sub.type == "named_imports":
                names.extend(self._specifier_names(sub))
        return names, default_name, is_type_only

    def _specifier_names(self, named_imports) -> List[str]:
        names: List[str] = []
        for spec in named_imports.children:
            if spec.type != "import_specifier":
                continue
            nm = spec.child_by_field_name("name")
            if nm:
                names.append(self._txt(nm))
        return names

    def _parse_imports_from_root(self, root) -> List[ImportInfo]:
        imports: List[ImportInfo] = []
        for node in self._find_all(root, "import_statement"):
            source_node = node.child_by_field_name("source")
            source = self._txt(source_node).strip("\"'`") if source_node else ""
            names: List[str] = []
            default_name: Optional[str] = None
            is_type_only = any(c.type == "type" for c in node.children)
            for child in node.children:
                if child.type != "import_clause":
                    continue
                extra, default_name, typed = self._named_import_names(child)
                names.extend(extra)
                is_type_only = is_type_only or typed
            imports.append(
                ImportInfo(
                    source=source,
                    names=names,
                    default_name=default_name,
                    is_type_only=is_type_only,
                    start_line=node.start_point[0] + 1,
                )
            )
        return imports


    def _interface_members(self, body) -> tuple[List[str], List[str]]:
        method_names: List[str] = []
        property_names: List[str] = []
        if body is None:
            return method_names, property_names
        for member in body.children:
            if member.type == "method_signature":
                mn = member.child_by_field_name("name")
                if mn:
                    method_names.append(self._txt(mn))
            elif member.type == "property_signature":
                pn = member.child_by_field_name("name")
                if pn:
                    property_names.append(self._txt(pn))
        return method_names, property_names

    def _parse_interfaces_from_root(self, root) -> List[InterfaceInfo]:
        interfaces: List[InterfaceInfo] = []
        for node in self._find_all(root, "interface_declaration"):
            name = self._txt(node.child_by_field_name("name"))
            methods, properties = self._interface_members(node.child_by_field_name("body"))
            interfaces.append(
                InterfaceInfo(
                    name=name,
                    method_names=methods,
                    property_names=properties,
                    is_exported=node.parent is not None and node.parent.type == "export_statement",
                    start_line=node.start_point[0] + 1,
                )
            )
        self._append_exported_interfaces(root, interfaces)
        return interfaces

    def _append_exported_interfaces(self, root, interfaces: List[InterfaceInfo]) -> None:
        for node in self._find_all(root, "export_statement"):
            inner = node.child_by_field_name("declaration")
            if inner is None or inner.type != "interface_declaration":
                continue
            name = self._txt(inner.child_by_field_name("name"))
            if any(i.name == name for i in interfaces):
                continue
            methods, properties = self._interface_members(inner.child_by_field_name("body"))
            interfaces.append(
                InterfaceInfo(
                    name=name,
                    method_names=methods,
                    property_names=properties,
                    is_exported=True,
                    start_line=inner.start_point[0] + 1,
                )
            )


    def _parse_calls_from_root(self, root) -> List[CallInfo]:
        calls: List[CallInfo] = []
        for node in self._find_all(root, "call_expression"):
            fn_node = node.child_by_field_name("function")
            args_node = node.child_by_field_name("arguments")
            calls.append(
                CallInfo(
                    callee=self._txt(fn_node) if fn_node else "",
                    args_text=self._txt(args_node) if args_node else "",
                    start_line=node.start_point[0] + 1,
                )
            )
        return calls

    def parse_file(self, path: Path):
        self._tree = None
        if not _TREE_SITTER_AVAILABLE:
            return None
        try:
            content = path.read_bytes()
            parser = _TSX_PARSER if path.suffix == ".tsx" else _TS_PARSER
            self._tree = parser.parse(content).root_node
            return self._tree
        except Exception:
            return None

    def find_nodes(self, node, *types: str) -> list:
        return self._find_all(node, *types) if node is not None else []

    def node_text(self, node) -> str:
        return self._txt(node)

    @property
    def classes(self) -> List[ClassInfo]:
        root = getattr(self, "_tree", None)
        if root is None:
            return []
        return self._classes_from_tree(root)

    def _classes_from_tree(self, root) -> List[ClassInfo]:
        classes: List[ClassInfo] = []
        seen_names: set = set()
        for node in self._find_all(root, "export_statement"):
            inner = node.child_by_field_name("declaration")
            if inner and inner.type == "class_declaration":
                ci = self._parse_class_node(inner, is_exported=True)
                seen_names.add(ci.name)
                classes.append(ci)
        for node in self._find_all(root, "class_declaration"):
            if node.parent is not None and node.parent.type == "export_statement":
                continue
            ci = self._parse_class_node(node, is_exported=False)
            if ci.name not in seen_names:
                classes.append(ci)
        return classes

    @property
    def imports(self) -> List[ImportInfo]:
        root = getattr(self, "_tree", None)
        return self._parse_imports_from_root(root) if root is not None else []

    @property
    def interfaces(self) -> List[InterfaceInfo]:
        root = getattr(self, "_tree", None)
        return self._parse_interfaces_from_root(root) if root is not None else []

    @property
    def calls(self) -> List[CallInfo]:
        root = getattr(self, "_tree", None)
        return self._parse_calls_from_root(root) if root is not None else []

    def has_import_from(self, source: str) -> bool:
        return any(imp.source == source for imp in self.imports)

    def imported_names_from(self, source: str) -> List[str]:
        for imp in self.imports:
            if imp.source == source:
                return imp.names
        return []

    def calls_matching(self, *patterns: str) -> List[CallInfo]:
        import re

        return [call for call in self.calls if any(re.search(p, call.callee) for p in patterns)]

    def source_files(self, directory: Path) -> List[Path]:
        files: List[Path] = []
        for f in sorted(directory.rglob("*.ts")):
            if "node_modules" not in f.parts:
                files.append(f)
        for f in sorted(directory.rglob("*.tsx")):
            if "node_modules" not in f.parts:
                files.append(f)
        return files

class ArgNamingScanner(TypeScriptScanner):
    """Check that argument names are preserved across shared/controller/service."""

    RULE = "preserve-arg-names-across-layers"

    def _extract_param_names(self, params_str: str) -> List[str]:
        names = []
        for part in params_str.split(","):
            part = part.strip()
            if not part:
                continue
            m = _PARAM_NAME_RE.match(part)
            if m:
                names.append(m.group(1))
        return names

    def _extract_methods_with_params(self, path: Path) -> Dict[str, List[str]]:
        result: Dict[str, List[str]] = {}
        try:
            content = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return result
        for m in _METHOD_WITH_PARAMS_RE.finditer(content):
            name = m.group(1)
            if name == "constructor" or name[0].isupper():
                continue
            params = self._extract_param_names(m.group(2))
            if params:
                result[name] = params
        return result

    RULE = "preserve-arg-names-across-layers"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []

        for domain_path in self._find_domain_packages(root):
            violations += self._check_domain(domain_path)

        return violations

    def _check_domain(self, domain_path: Path) -> List[Violation]:
        violations: List[Violation] = []

        shared_dir = domain_path / "shared"
        server_dir = domain_path / "server"
        if not shared_dir.exists() or not server_dir.exists():
            return violations

        shared_methods: Dict[str, List[str]] = {}
        for ts_file in shared_dir.glob("*.ts"):
            if ts_file.name in ("index.ts",) or ts_file.name.endswith(".schema.ts"):
                continue
            shared_methods.update(self._extract_methods_with_params(ts_file))

        service_methods: Dict[str, List[str]] = {}
        for ts_file in server_dir.glob("*.service.ts"):
            service_methods.update(self._extract_methods_with_params(ts_file))

        for method_name, shared_params in shared_methods.items():
            if method_name in service_methods:
                service_params = service_methods[method_name]
                service_domain_params = [p for p in service_params if p not in ("req", "res", "body")]
                for i, (sp, svc_p) in enumerate(zip(shared_params, service_domain_params)):
                    if sp != svc_p:
                        violations.append(
                            self.v(
                                f"Arg name drift in '{method_name}': shared/ uses "
                                f"'{sp}' but service uses '{svc_p}' at position {i}. "
                                "Keep the same name across layers.",
                                str(server_dir),
                                severity="warning",
                            )
                        )

        return violations

class LERNScanner(Scanner):
    """Base class for domain-first LERN architecture scanners.

    Concrete scanners override ``scan(self, root, files)`` (project-wide
    checks - package structure, cross-file naming) or ``scan_file`` (one file
    at a time, via the inherited ``Scanner.scan`` loop).
    """

    RULE: str = ""

    def v(
        self,
        message: str,
        location: str = "",
        line: int = 0,
        severity: str = "error",
    ) -> Violation:
        """Old-world shorthand for ``self.violation(...)`` - kept so ported
        scanner bodies need no call-site changes beyond the base class."""
        return self.violation(message, location=location, line=line, severity=severity)

    def _find_domain_packages(self, project_root: Path) -> List[Path]:
        """Domain dirs under packages/ — either top-level or nested inside a
        feature package (e.g. ``packages/wires/recipients/``). A domain dir
        has the three-file layout (``<domain>.ts``, ``<domain>-server.ts``,
        ``<domain>-client.tsx``) or legacy ``shared/`` / ``client/`` /
        ``server/`` folders. Excludes composition roots."""
        packages_dir = project_root / "packages"
        if not packages_dir.exists():
            return []

        excluded = {"node_modules"}
        domain_packages: List[Path] = []

        def consider(path: Path) -> None:
            if self._is_domain_dir(path) and path not in domain_packages:
                domain_packages.append(path)

        for child in packages_dir.iterdir():
            if not child.is_dir():
                continue
            if child.name in excluded or child.name.startswith("."):
                continue
            consider(child)
            # Feature packages nest domain modules one level down
            # (packages/wires/recipients/).
            if self._domain_core_file(child) is None:
                for nested in child.iterdir():
                    if not nested.is_dir() or nested.name.startswith("."):
                        continue
                    if nested.name in {"node_modules", "dist", "build"}:
                        continue
                    consider(nested)
        return domain_packages

    def _is_domain_dir(self, path: Path) -> bool:
        if self._domain_core_file(path) is not None and (
            self._server_file(path) is not None or self._client_file(path) is not None
        ):
            return True
        return any((path / tier).is_dir() for tier in ("shared", "client", "server"))

    def _domain_core_file(self, domain_path: Path) -> Path | None:
        """``<domain>.ts`` — framework-free domain core (was shared/)."""
        candidates = [
            domain_path / f"{domain_path.name}.ts",
            domain_path / f"{domain_path.name.rstrip('s')}.ts",
        ]
        for path in candidates:
            if path.is_file():
                return path
        for path in sorted(domain_path.glob("*.ts")):
            name = path.name
            if name in {"index.ts", "app.ts", "serve.ts", "main.ts"}:
                continue
            if name.endswith("-server.ts"):
                continue
            if name.endswith(".test.ts") or name.endswith(".spec.ts"):
                continue
            if name.endswith("-client.ts"):
                continue
            return path
        return None

    def _server_file(self, domain_path: Path) -> Path | None:
        """``<domain>-server.ts`` (not feature-package ``serve.ts`` / ``app.ts``)."""
        singular = domain_path.name.rstrip("s")
        for name in (
            f"{singular}-server.ts",
            f"{domain_path.name}-server.ts",
        ):
            path = domain_path / name
            if path.is_file():
                return path
        matches = sorted(domain_path.glob("*-server.ts"))
        return matches[0] if matches else None

    def _client_file(self, domain_path: Path) -> Path | None:
        """``<domain>-client.tsx`` (or legacy ``client.tsx``)."""
        singular = domain_path.name.rstrip("s")
        for name in (
            f"{singular}-client.tsx",
            f"{singular}-client.ts",
            f"{domain_path.name}-client.tsx",
            f"{domain_path.name}-client.ts",
            "client.tsx",
            "client.ts",
        ):
            path = domain_path / name
            if path.is_file():
                return path
        matches = sorted(domain_path.glob("*-client.tsx")) + sorted(
            domain_path.glob("*-client.ts")
        )
        return matches[0] if matches else None

    def _find_tier_files(self, domain_path: Path, tier: str, pattern: str = "*.ts") -> List[Path]:
        """Files for one tier. Prefers the three-file layout; falls back to
        legacy ``<tier>/`` directories."""
        if tier in ("shared", "domain", "core"):
            core = self._domain_core_file(domain_path)
            return [core] if core is not None else []
        if tier == "server":
            server = self._server_file(domain_path)
            if server is not None:
                return [server]
        if tier == "client":
            client = self._client_file(domain_path)
            if client is not None:
                return [client]
        tier_dir = domain_path / tier
        if not tier_dir.exists():
            return []
        return list(tier_dir.glob(pattern))

    def _find_test_folders(self, project_root: Path) -> List[Path]:
        """Lowest-level sub-epic test folders under tests/."""
        tests_dir = project_root / "tests"
        if not tests_dir.exists():
            return []

        sub_epic_folders = []
        for epic_dir in tests_dir.iterdir():
            if not epic_dir.is_dir() or epic_dir.name.startswith("."):
                continue
            for sub_epic_dir in epic_dir.rglob("*"):
                if not sub_epic_dir.is_dir():
                    continue
                has_test_files = any(
                    f.name.endswith((".test.ts", ".test.tsx", ".spec.ts"))
                    for f in sub_epic_dir.iterdir()
                    if f.is_file()
                )
                if has_test_files:
                    sub_epic_folders.append(sub_epic_dir)
        return sub_epic_folders

    def _read_file_content(self, file_path: Path) -> Optional[str]:
        try:
            return file_path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            return None

class AskCrossAggregateSyncScanner(LERNScanner):
    """When two or more aggregates exist, grill-answers must record the sync choice."""

    RULE = "ask-cross-aggregate-sync"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        domains = self._find_domain_packages(root)
        if len(domains) < 2:
            return []

        answers = self._read_grill_answers(root)
        if answers is None:
            return [
                self.v(
                    "This slice has more than one aggregate and no "
                    ".context/grill-answers.md. AskQuestion for cross-aggregate "
                    "sync (event-based orchestration vs direct repository calls "
                    "by the client) before generating stories.",
                    str(root),
                )
            ]

        lower = answers.lower()
        if _HEADING not in lower:
            return [
                self.v(
                    ".context/grill-answers.md is missing heading 'Cross-aggregate sync'. "
                    "AskQuestion and record event-based orchestration, direct "
                    "repository calls by the client, or single-aggregate.",
                    str(self._grill_answers_path(root)),
                )
            ]
        if not any(marker in lower for marker in _CHOICE_MARKERS):
            return [
                self.v(
                    "Cross-aggregate sync heading is present but no choice is recorded. "
                    "Name event-based orchestration or direct repository calls by the client.",
                    str(self._grill_answers_path(root)),
                )
            ]
        return []

    def _grill_answers_path(self, root: Path) -> Path:
        return root / ".context" / "grill-answers.md"

    def _read_grill_answers(self, root: Path) -> str | None:
        direct = self._grill_answers_path(root)
        if direct.is_file():
            return direct.read_text(encoding="utf-8", errors="replace")
        sessions = root / ".context" / "sessions"
        if sessions.is_dir():
            matches = sorted(sessions.rglob("grill-answers.md"))
            if matches:
                return matches[0].read_text(encoding="utf-8", errors="replace")
        return None

class StoryNode:
    """Abstract base. Subclasses declare `_semantic_type_name` so cross-format nodes
    (e.g. MarkdownEpic vs JsonEpic) share one semantic axis and translate cleanly."""

    _semantic_type_name: str = "StoryNode"

    def __init__(self, name: str, sequential_order: int):
        self.name = name
        self.sequential_order = sequential_order
        # Shaping outline sizing (e.g. "approx 2-3 more stories (...)").
        # Meaningful on Epic/SubEpic; empty on Story and below.
        self.estimate: str = ""

    def semantic_type(self) -> str:
        return self._semantic_type_name

    def translate_from(self, source: "StoryNode") -> UpdateReport:
        if self.semantic_type() != source.semantic_type():
            raise TranslationError(
                f"Cannot translate from {source.semantic_type()} into "
                f"{self.semantic_type()}"
            )
        report = UpdateReport()
        report.capture_snapshot(self)
        self.update_self(source)
        for pair in self.child_collections(source):
            self._reconcile_collection(pair, report)
        return report

    def update_self(self, source: "StoryNode") -> None:
        raise NotImplementedError(
            f"{type(self).__name__} must implement update_self"
        )

    def child_collections(self, source: "StoryNode") -> List[ChildCollectionPair]:
        raise NotImplementedError(
            f"{type(self).__name__} must implement child_collections"
        )

    def children(self) -> List["StoryNode"]:
        # WHY: NodeSnapshot walks the tree without knowing shape; pull children from
        # the same pairs that translate_from reconciles, using self as its own source.
        result: List[StoryNode] = []
        try:
            for pair in self.child_collections(self):
                result.extend(pair.self_children)
        except NotImplementedError:
            pass
        return result

    def snapshot_fields(self) -> dict:
        # WHY: allow subclasses to include type-specific fields in the snapshot;
        # base returns empty and leaf classes override.
        return {}

    def restore_snapshot_fields(self, fields: dict) -> None:
        for key, value in fields.items():
            setattr(self, key, value)

    def reverse(self, report: UpdateReport) -> None:
        report.reverse_on(self)

    def _reconcile_collection(
        self, pair: ChildCollectionPair, report: UpdateReport
    ) -> None:
        self._consumed_ids: set = set()
        reconciled: List[StoryNode] = []

        for source_child in pair.source_children:
            match = self._find_match(source_child, pair.self_children)
            if match is not None:
                old_name = match.name
                self._consumed_ids.add(id(match))
                match.translate_from(source_child)
                reconciled.append(match)
                if old_name == source_child.name:
                    report.add_exact_match(match.name, source_child.name)
                else:
                    report.add_rename(old_name, source_child.name, confidence=1.0)
            else:
                new_child = pair.load(source_child)
                new_child.translate_from(source_child)
                reconciled.append(new_child)
                report.add_new(new_child, parent_name=self.name)

        for existing in pair.self_children:
            if id(existing) not in self._consumed_ids:
                report.add_removed(existing, parent_name=self.name)

        previous_kept_order = [c for c in pair.self_children if id(c) in self._consumed_ids]
        for i, node in enumerate(reconciled):
            if i >= len(previous_kept_order):
                break
            if previous_kept_order[i] is not node:
                report.add_reorder(previous_kept_order[i].name, node.name)
                break

        pair.self_children[:] = reconciled

    def _find_match(
        self,
        source_child: "StoryNode",
        candidates: List["StoryNode"],
    ) -> Optional["StoryNode"]:
        for candidate in candidates:
            if id(candidate) in self._consumed_ids:
                continue
            if candidate.name == source_child.name:
                return candidate
        for candidate in candidates:
            if id(candidate) in self._consumed_ids:
                continue
            if candidate.sequential_order == source_child.sequential_order:
                return candidate
        return None

class BaseAboveDerivedScanner(DrawioScanner):
