class Skill(Destination):
    flag = "_skill"

    def __new__(cls, fn: Any = None, name: str | None = None):
        inst = object.__new__(cls)
        if isinstance(fn, str):
            inst.name = fn
            return inst
        inst.name = name
        if callable(fn):
            return inst.annotate(fn)
        return inst

class Mcp(Destination):
    flag = "_mcp"

    def __new__(cls, fn: Any = None):
        inst = object.__new__(cls)
        inst.name = None
        if callable(fn):
            return inst.annotate(fn)
        return inst

class CasingTransformScanner(TypeScriptScanner):
    """Check property casing conventions across TS and JSON boundaries."""

    RULE = "property-casing-transform"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []

        for domain_path in self._find_domain_packages(root):
            violations += self._check_ts_properties(domain_path)
            violations += self._check_json_bodies(domain_path)

        return violations

    def _check_ts_properties(self, domain_path: Path) -> List[Violation]:
        violations: List[Violation] = []
        for ts_file in self._domain_ts_files(domain_path):
            violations.extend(self._snake_case_properties_in(ts_file))
        return violations

    def _domain_ts_files(self, domain_path: Path):
        for tier in ("shared", "client", "server"):
            yield from self._find_tier_files(domain_path, tier)

    def _snake_case_properties_in(self, ts_file: Path) -> List[Violation]:
        content = self._read_file_content(ts_file)
        if content is None:
            return []
        violations: List[Violation] = []
        for block_match in _INTERFACE_BLOCK_RE.finditer(content):
            if _RAW_TYPE_RE.match(block_match.group(1)):
                continue
            violations.extend(self._snake_props_in_block(ts_file, block_match.group(2)))
        return violations

    def _snake_props_in_block(self, ts_file: Path, block: str) -> List[Violation]:
        violations: List[Violation] = []
        for prop_match in _SNAKE_CASE_PROP_RE.finditer(block):
            prop = prop_match.group(1)
            if prop.startswith("_"):
                continue
            camel = self._to_camel(prop)
            violations.append(
                self.v(
                    f"Property '{prop}' in {ts_file.name} uses snake_case. "
                    f"TypeScript properties must be camelCase: '{camel}'.",
                    str(ts_file),
                    severity="error",
                )
            )
        return violations

    def _check_json_bodies(self, domain_path: Path) -> List[Violation]:
        client = self._client_file(domain_path)
        if client is None:
            return []
        content = self._read_file_content(client)
        if content is None:
            return []
        return self._camel_keys_in_json_bodies(client, content)

    def _camel_keys_in_json_bodies(self, client: Path, content: str) -> List[Violation]:
        violations: List[Violation] = []
        for body_match in _CAMEL_IN_JSON_RE.finditer(content):
            for key_match in _CAMEL_KEY_IN_OBJ_RE.finditer(body_match.group(1)):
                key = key_match.group(1)
                snake = self._to_snake(key)
                violations.append(
                    self.v(
                        f"JSON body key '{key}' in {client.name} uses camelCase. "
                        f"HTTP bodies must use snake_case: '{snake}'.",
                        str(client),
                        severity="error",
                    )
                )
        return violations

    def _to_camel(self, snake: str) -> str:
        parts = snake.split("_")
        return parts[0] + "".join(p.capitalize() for p in parts[1:])

    def _to_snake(self, camel: str) -> str:
        return re.sub(r"([A-Z])", r"_\1", camel).lower().lstrip("_")

class FidelityGuidance(Guidance):
    def __init__(
        self,
        name: str = "",
        stage: str = "",
        default_format: str = "",
        practice_guidance: PracticeGuidance | None = None,
        clean_engineering: FidelityGuidance | None = None,
    ) -> None:
        super().__init__(format=default_format)
        self.name = name
        self.stage = stage
        self.default_format = default_format
        self.parent = practice_guidance
        self.fidelity = name
        if clean_engineering is not None:
            self.clean_engineering = clean_engineering

    @property
    def practice_guidance(self) -> PracticeGuidance | None:
        parent = getattr(self, "parent", None)
        while parent is not None and not isinstance(parent, PracticeGuidance):
            parent = getattr(parent, "parent", None)
        return parent

    @property
    def context_index_key(self) -> str:
        practice = self.practice_guidance
        if practice is not None:
            return practice.context_index_key
        return AssetLocator(self, "").class_file_directory().name

    @property
    def default_format(self) -> str:
        return getattr(self, "_default_format", "")

    @default_format.setter
    def default_format(self, value: str) -> None:
        self._default_format = value or ""
        if self._default_format:
            self.format = self._default_format

    @property
    def clean_engineering(self) -> FidelityGuidance | None:
        stored = getattr(self, "_clean_engineering", None)
        if isinstance(stored, FidelityGuidance):
            return stored
        if not isinstance(stored, str) or not stored:
            return None
        from practices.clean_engineering.clean_engineering import CleanEngineering

        companion = CleanEngineering().fidelities[stored]
        host = self.practice_guidance
        practice = companion.practice_guidance
        if (
            host is not None
            and practice is not None
            and getattr(host, "format", None) in getattr(host, "_code_formats", ())
        ):
            practice.format = host.format
        self._clean_engineering = companion
        return companion

    @clean_engineering.setter
    def clean_engineering(self, value: Any) -> None:
        self._clean_engineering = value

    @property
    def slug(self) -> str:
        parent = self.practice_guidance.slug if self.practice_guidance is not None else super().slug
        leaf = (self.name or "").replace("_", "-")
        return f"{parent}-{leaf}" if leaf else parent

    @property
    def install_folder(self) -> Path:
        practice = self.practice_guidance
        base = practice.install_folder if practice is not None else AssetLocator(self, "").class_file_directory()
        leaf = (self.name or "").replace(" ", "-")
        return base / leaf if leaf else base

    @property
    def overview(self) -> str:  # type: ignore[override]
        return Markdown.from_label(self, "overview").extract()

    @markdown
    def guidance(self) -> str:
        """Fidelity guidance section."""

    @markdownCollection
    @rules
    @agent_tool
    def rules(self) -> GraphRulesCollection:
        """Fidelity rules section."""

    @property
    @echo
    @mcp
    @skill
    @command
    @agent_instructions
    def instructions(self) -> str:
        """overview"""
        practice = self.practice_guidance
        parent = ()
        templates = ""
        companion_text = ""
        if practice is not None:
            parent = (
                (practice.overview or "").strip(),
                Markdown.from_label(practice, "guidance").extract().strip(),
                (practice.rules.markdown or "").strip(),
            )
            companion = self.clean_engineering
            companion_text = (
                companion.instructions if isinstance(companion, FidelityGuidance) else ""
            )
            previous = practice.fidelities.current
            previous_format = practice.format
            practice.fidelities.current = practice.fidelities[self.name]
            practice.format = self.format or self.default_format
            try:
                templates = (practice.templates or "").strip()
            finally:
                practice.fidelities.current = previous
                practice.format = previous_format
            if templates:
                templates = f"#### Template\n\n{templates}"
        return "\n\n".join(
            part
            for part in (
                *parent,
                (self.overview or "").strip(),
                (self.guidance or "").strip(),
                (self.rules.markdown or "").strip(),
                templates,
                companion_text,
            )
            if part
        )

