class JsonCleanEngineeringModel(CleanEngineeringModel):
    def load_module(self, source: Module) -> JsonModule:
        loaded = JsonModule(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def parse(self, text: str) -> "JsonCleanEngineeringModel":
        try:
            data = json.loads(text)
        except json.JSONDecodeError as exc:
            raise JsonParseError(f"Invalid JSON: {exc}") from exc
        model = type(self)(name=data.get("name", ""))
        if "modules" in data:
            for index, record in enumerate(data["modules"], 1):
                model.modules.append(JsonModule.from_record(record, index))
        elif "classes" in data:
            module = JsonModule(name="", sequential_order=1)
            for index, record in enumerate(data["classes"], 1):
                module.classes.append(JsonOoadClass.from_record(record, index))
            if module.classes:
                model.modules.append(module)
        else:
            raise JsonParseError("JSON must contain a 'modules' or 'classes' key")
        return model

    def render(self, canonical: Optional[CleanEngineeringModel] = None, previous: Optional[str] = None) -> str:
        if canonical is not None:
            self.translate_from(canonical)
        return json.dumps(self.as_record(), indent=2)

    def sync(self, text: str, canonical: CleanEngineeringModel) -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    @classmethod
    def from_workspace(cls, root: Path) -> Optional["JsonCleanEngineeringModel"]:
        candidates = list(root.glob("**/CleanEngineering-model.json")) + list(
            root.glob("**/*.CleanEngineering.json")
        )
        for path in sorted(candidates):
            try:
                return cls().parse(path.read_text(encoding="utf-8"))
            except (JsonParseError, KeyError):
                continue
        return None

class MarkdownCleanEngineeringModel(CleanEngineeringModel):

    def load_module(self, source: Module) -> MarkdownModule:
        loaded = MarkdownModule(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def load_class(self, source: OoadClass) -> MarkdownOoadClass:
        loaded = MarkdownOoadClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def parse(self, text: str) -> "MarkdownCleanEngineeringModel":
        model = type(self)(name="", sequential_order=1)
        self._module_order = 1
        for block in re.split(r"(?m)^(?=#\s)", text):
            module = self._module_from_h1(block.strip())
            if module is None:
                continue
            model.modules.append(module)
            self._module_order += 1
        return model

    def _module_from_h1(self, block: str) -> MarkdownModule | None:
        if not block:
            return None
        heading = re.match(r"^#\s+(.+)", block)
        if not heading:
            return None
        body_after_h1 = block[heading.end():].lstrip("\n")
        module = MarkdownModule(name=heading.group(1).strip(), sequential_order=self._module_order)
        h2_split = re.split(r"(?m)^(?=##\s)", body_after_h1, maxsplit=1)
        self._apply_module_preamble(module, h2_split[0].strip())
        self._append_h2_classes(module, h2_split[1] if len(h2_split) > 1 else "")
        return module

    def _apply_module_preamble(self, module: MarkdownModule, pre_h2: str) -> None:
        if not pre_h2:
            return
        purpose, seam_terms, deps, leftover = self._parse_module_meta(pre_h2)
        if purpose:
            module.description = purpose
        elif leftover:
            module.description = leftover
        else:
            module.description = pre_h2
        module.seam_terms = seam_terms
        module.dependencies = deps
        if seam_terms and not module.seam:
            module.seam = ", ".join(seam_terms)

    def _append_h2_classes(self, module: MarkdownModule, classes_text: str) -> None:
        class_order = 1
        for class_block in re.split(r"(?m)^(?=##\s)", classes_text):
            class_block = class_block.strip()
            heading = re.match(r"^##\s+(.+)", class_block) if class_block else None
            if heading is None:
                continue
            class_name = heading.group(1).strip()
            if class_name.lower() in self._MODULE_META_HEADINGS:
                self._section_heading = class_name
                self._apply_module_section(module, class_block[heading.end():])
                continue
            if " : " in class_name:
                class_name = class_name.split(" : ", 1)[0].strip()
            module.classes.append(
                MarkdownOoadClass.parse_body(
                    class_name,
                    class_block[heading.end():].lstrip("\n"),
                    class_order,
                )
            )
            class_order += 1

    def render(self, canonical: Optional[CleanEngineeringModel] = None, previous: Optional[str] = None) -> str:
        if canonical is not None:
            self.translate_from(canonical)
        return "\n".join(module.render() for module in self.modules)

    def sync(self, text: str, canonical: CleanEngineeringModel) -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    @classmethod
    def from_workspace(cls, root: Path) -> Optional["MarkdownCleanEngineeringModel"]:
        for path in sorted(root.glob("**/*.md")):
            text = path.read_text(encoding="utf-8", errors="ignore")
            if "practices.clean_engineering.clean_engineering:CleanEngineering" in text and "@toolset-manifest" in text:
                return cls().parse(text)
        return None

    _MODULE_META_HEADINGS = frozenset({
        "seam",
        "dependencies",
        "modules fidelity",
        "purpose",
    })


    def _parse_term_list(self, raw: str) -> List[str]:
        text = raw.strip()
        text = re.sub(r"^\*\(?none\)?\*$", "", text, flags=re.IGNORECASE).strip()
        if not text or text.lower() in {"*(none)*", "(none)", "none", "-", "-"}:
            return []
        # Strip surrounding backticks per token
        parts = re.split(r"[,;]", text)
        out: List[str] = []
        for p in parts:
            term = p.strip().strip("`").strip()
            term = re.sub(r"^\*\*?|\*\*?$", "", term).strip()
            if term:
                out.append(term)
        return out


    def _parse_module_meta(self, text: str) -> tuple[str, List[str], List[str], str]:
        """Parse Purpose / Seam / Dependencies bullets from a modules-fidelity block.

        Returns (purpose, seam_terms, dependencies, leftover_prose).
        """
        purpose = ""
        seam_terms: List[str] = []
        deps: List[str] = []
        leftover_lines: List[str] = []

        for line in text.splitlines():
            stripped = line.strip()
            m_purpose = re.match(r"^-?\s*\*\*Purpose:\*\*\s*(.+)$", stripped, re.IGNORECASE)
            m_seam = re.match(
                r"^-?\s*\*\*Seam(?:\s*\(terms\))?:\*\*\s*(.+)$", stripped, re.IGNORECASE
            )
            m_deps = re.match(
                r"^-?\s*\*\*Dependencies(?:\s*\(one-way\))?:\*\*\s*(.+)$",
                stripped,
                re.IGNORECASE,
            )
            m_build = re.match(r"^-?\s*\*\*Build order:\*\*", stripped, re.IGNORECASE)
            if m_purpose:
                purpose = m_purpose.group(1).strip()
            elif m_seam:
                seam_terms = self._parse_term_list(m_seam.group(1))
            elif m_deps:
                deps = self._parse_term_list(m_deps.group(1))
            elif m_build:
                continue
            elif re.match(r"^###\s+Module\s+", stripped, re.IGNORECASE):
                continue
            elif re.match(r"^##\s+Modules fidelity", stripped, re.IGNORECASE):
                continue
            else:
                leftover_lines.append(line)

        leftover = "\n".join(leftover_lines).strip()
        # Nested "### Module `path`" blocks often put purpose only in the bullet
        if not purpose and leftover:
            # Keep leftover as description when it is prose (not only bullets we already ate)
            prose = "\n".join(
                ln for ln in leftover.splitlines()
                if ln.strip() and not ln.strip().startswith("- **")
            ).strip()
            if prose:
                purpose = prose.splitlines()[0].strip() if not purpose else purpose
        return purpose, seam_terms, deps, leftover


    def _apply_module_section(self, module: Module, body: str) -> None:
        heading = self._section_heading
        key = heading.lower().strip()
        if key == "modules fidelity":
            purpose, seam_terms, deps, _leftover = self._parse_module_meta(body)
            if purpose and not module.description:
                module.description = purpose
            if seam_terms:
                module.seam_terms = seam_terms
                if not module.seam:
                    module.seam = ", ".join(seam_terms)
            if deps:
                module.dependencies = deps
            return
        if key == "seam":
            # Narrative seam section - keep as seam prose; pull backticked names as terms
            module.seam = body.strip()
            if not module.seam_terms:
                module.seam_terms = [
                    t for t in re.findall(r"`([^`]+)`", body)
                    if t.strip() and "." not in t  # skip Check.resolve style
                ]
        elif key == "dependencies":
            # Prefer a "**Formal (modules):** a, b" line; else comma list on first line
            formal = re.search(
                r"\*\*Formal\s*\(modules\):\*\*\s*(.+)", body, re.IGNORECASE
            )
            if formal:
                module.dependencies = self._parse_term_list(formal.group(1))
            else:
                first = next((ln.strip() for ln in body.splitlines() if ln.strip()), "")
                module.dependencies = self._parse_term_list(first)
        elif key == "purpose":
            module.description = body.strip()

    def _parse_class(self, name: str, body: str) -> OoadClass:
        parts6 = re.split(r"(?m)^-{6}\s*$", body, maxsplit=1)
        pre6 = parts6[0] if parts6 else ""
        post6 = parts6[1] if len(parts6) > 1 else ""

        intent = ""
        for line in pre6.splitlines():
            stripped = line.strip()
            if stripped and not re.match(r"^\w[\w\s]*\(", stripped):
                intent = stripped
                break

        parts4 = re.split(r"(?m)^-{4}\s*$", post6, maxsplit=1)
        props_text = parts4[0] if parts4 else ""
        ops_text = parts4[1] if len(parts4) > 1 else ""

        props, rels = self._parse_properties_and_relationships(props_text)
        ops, op_rels = self._parse_operations_and_relationships(ops_text)
        return MarkdownOoadClass(
            name=name,
            sequential_order=self._class_order,
            intent=intent,
            properties=props,
            operations=ops,
            relationships=self._dedupe_relationships(rels + op_rels),
        )


    _CE_STEREOTYPE_KINDS = {
        "composition": "composition",
        "aggregation": "aggregation",
        "association": "association",
    }


    def _strip_ce_prefix(self, line: str) -> tuple[str, str | None]:
        """Strip CE OOAD format prefix from a property/operation line.

        Handles lines like:
          + << composition >> identity: Identity
          + name: string
          + save(): void
          - privateOp(): void
        Returns (bare_line, stereotype_kind | None).
        stereotype_kind is one of "composition", "aggregation", "association" or None.
        """
        # Strip leading "+" (public) visibility marker used in CE OOAD markdown
        if line.startswith("+"):
            line = line[1:].strip()
        # Extract and strip UML stereotype annotation like "<< composition >>"
        kind: str | None = None
        m = re.match(r"^<<\s*(\w+)\s*>>\s*", line)
        if m:
            raw_kind = m.group(1).lower()
            kind = self._CE_STEREOTYPE_KINDS.get(raw_kind)
            line = line[m.end():].strip()
        return line, kind


    def _parse_properties_and_relationships(self, text: str) -> tuple[List[Property], List[Relationship]]:
        """Parse properties AND extract Relationship objects from CE OOAD stereotype annotations.

        A line like ``+ << composition >> identity: Identity`` produces both a
        Property(name="identity", type_hint="Identity") and a
        Relationship(kind="composition", target="Identity").
        """
        props: List[Property] = []
        rels: List[Relationship] = []
        for line in text.splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if stripped.startswith("//") or stripped.startswith("->"):
                continue
            stripped, rel_kind = self._strip_ce_prefix(stripped)
            if not stripped:
                continue
            # Skip lines that look like operations
            if re.match(r"^_?\w+\s*\(", stripped):
                continue
            # Optional props may be written `name?: Type` or `name: Type | null`.
            m = re.match(r"^(\w+)\??:\s*(.+)", stripped)
            if m:
                prop_name = m.group(1)
                # Strip array marker and optional suffix (e.g. "Subscription[]" → "Subscription")
                type_raw = m.group(2).strip()
                # Remove trailing " | null" or "| None" suffix for relationship target resolution
                type_clean = re.split(r"\s*\|", type_raw)[0].strip().rstrip("[]").strip()
                props.append(Property(name=prop_name, type_hint=type_raw))
                if rel_kind and type_clean and re.match(r"^[A-Z]\w*$", type_clean):
                    rels.append(Relationship(kind=rel_kind, target=type_clean))
            elif re.match(r"^\w+$", stripped):
                props.append(Property(name=stripped))
        return props, rels


    def _parse_properties(self, text: str) -> List[Property]:
        props, _ = self._parse_properties_and_relationships(text)
        return props


    def _parse_operations(self, text: str) -> List[Operation]:
        ops, _ = self._parse_operations_and_relationships(text)
        return ops


    _NON_DOMAIN_TYPE_NAMES = frozenset({
        "String", "Number", "Boolean", "Void", "Any", "Unknown", "Object",
        "Record", "Array", "Promise", "Partial", "Omit", "Pick", "RegExp",
        "Date", "Error", "Map", "Set", "Readonly", "Required", "NonNullable",
    })


    def _domain_type_names(self, type_raw: str) -> List[str]:
        """PascalCase type names from a CE type hint (returns, params, props)."""
        if not type_raw:
            return []
        names: List[str] = []
        for m in re.finditer(r"\b([A-Z][A-Za-z0-9]*)\b", type_raw):
            name = m.group(1)
            if name in self._NON_DOMAIN_TYPE_NAMES or name in names:
                continue
            names.append(name)
        return names


    def _dedupe_relationships(self, rels: List[Relationship]) -> List[Relationship]:
        """One edge per target; stronger ownership (composition > aggregation > association) wins."""
        rank = {"composition": 3, "aggregation": 2, "association": 1}
        best: dict[str, Relationship] = {}
        for rel in rels:
            kind = (rel.kind or "association").lower()
            if kind not in rank:
                kind = "association"
            prev = best.get(rel.target)
            if prev is None or rank[kind] > rank.get((prev.kind or "association").lower(), 1):
                best[rel.target] = Relationship(
                    kind=kind,
                    target=rel.target,
                    cardinality=rel.cardinality,
                    description=rel.description,
                )
        return list(best.values())


    def _parse_operations_and_relationships(self, 
        text: str,
    ) -> tuple[List[Operation], List[Relationship]]:
        """Parse operations and infer association edges from return/param types.

        Property stereotypes remain the place for composition/aggregation. Method
        signatures default to association so return types like ``viewPortability():
        Portability`` and params like ``portNumber(info: PortingInfo)`` become edges.
        An optional ``<< composition|aggregation|association >>`` on the op line
        applies to the return type only.
        """
        ops: List[Operation] = []
        rels: List[Relationship] = []
        for line in text.splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if stripped.startswith("//") or stripped.startswith("->"):
                continue
            private = stripped.startswith("- ")
            body = stripped[2:].strip() if private else stripped
            body, ret_kind = self._strip_ce_prefix(body)
            m = re.match(r"^(_?\w+)\(([^)]*)\)(?::\s*(.+))?", body)
            if not m:
                continue
            op_name = ("_" if private and not m.group(1).startswith("_") else "") + m.group(1)
            params = [p.strip() for p in m.group(2).split(",") if p.strip()]
            ret = (m.group(3) or "").strip()
            ops.append(Operation(name=op_name, parameters=params, return_type=ret))

            kind = ret_kind or "association"
            for target in self._domain_type_names(ret):
                rels.append(Relationship(kind=kind, target=target))
            for param in params:
                # name: Type  or  name?: Type
                pm = re.match(r"^(\w+)\??:\s*(.+)$", param)
                if not pm:
                    continue
                for target in self._domain_type_names(pm.group(2)):
                    rels.append(Relationship(kind="association", target=target))
        return ops, rels

class PythonCleanEngineeringModel(CleanEngineeringModel):

    def load_module(self, source: Module) -> PythonModule:
        return PythonModule(name=source.name, sequential_order=source.sequential_order)

    def parse(self, text: str) -> "PythonCleanEngineeringModel":
        return self.parse_detailed(text).model

    def parse_detailed(self, text: str) -> ParsedPython:
        """Single parse entry - prefer ast (metrics); fall back to regex stubs."""
        self._text = text
        lines = text.split("\n")
        try:
            tree = ast.parse(text)
        except SyntaxError:
            model = self._parse_regex(text)
            return ParsedPython(model=model, content=text, lines=lines, tree=None)
        model = self._parse_ast(tree)
        return ParsedPython(model=model, content=text, lines=lines, tree=tree)

    def parse_file(self, path: Path) -> ParsedPython | None:
        if not path.is_file():
            return None
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            return None
        try:
            return self.parse_detailed(content)
        except SyntaxError:
            return None

    def render(self, canonical: CleanEngineeringModel, previous: Optional[str] = None) -> str:
        header = "from __future__ import annotations\nfrom abc import ABC, abstractmethod\n"
        parts = [header]
        for module in canonical.modules:
            if module.name:
                parts.append(f"# === {module.name} ===")
                if module.description:
                    for line in module.description.splitlines():
                        parts.append(f"# {line}" if line.strip() else "#")
                parts.append("")
            known = [c.name for c in module.classes]
            for oclass in module.classes:
                parts.append(self._render_class(oclass, known_names=known))
        return "\n\n".join(parts) + "\n"

    def sync(self, text: str, canonical: CleanEngineeringModel) -> UpdateReport:
        return canonical.translate_from(self.parse(text))

    def _parse_regex(self, text: str) -> "PythonCleanEngineeringModel":
        model = type(self)(name="", sequential_order=1)
        segments = _MODULE_MARKER.split(text)

        if len(segments) <= 1:
            module = PythonModule(name="", sequential_order=1)
            self._populate_classes_regex(text, module)
            if module.classes:
                model.modules.append(module)
        else:
            module_order = 1
            for i in range(1, len(segments), 2):
                name = segments[i].strip()
                body = segments[i + 1] if i + 1 < len(segments) else ""
                module = PythonModule(name=name, sequential_order=module_order)
                self._populate_classes_regex(body, module)
                model.modules.append(module)
                module_order += 1
        return model

    def _parse_ast(self, tree: ast.AST) -> "PythonCleanEngineeringModel":
        model = type(self)(name="", sequential_order=1)
        module = PythonModule(name="", sequential_order=1)
        class_order = 1
        for node in tree.body:
            if not isinstance(node, ast.ClassDef):
                continue
            module.classes.append(self._class_from_ast(node, class_order))
            class_order += 1
        self._attach_top_level_ops(module, tree)
        if module.classes:
            model.modules.append(module)
        return model

    def _class_from_ast(self, node: ast.ClassDef, class_order: int) -> PythonOoadClass:
        intent = ast.get_docstring(node) or ""
        oclass = PythonOoadClass(
            name=node.name,
            sequential_order=class_order,
            intent=intent.strip(),
            line=node.lineno,
        )
        name_words = set(node.name.lower().replace("_", " ").split())
        doc_words = set(intent.lower().strip(".").split()) if intent else set()
        oclass.docstring_parrots_name = bool(name_words and doc_words and doc_words <= name_words)
        oclass.operations = self._operations_from_class(node)
        oclass.properties = self._properties_from_class(node)
        narr, code_c = self._file_comment_issues(self._text)
        oclass.narration_comment_lines = narr
        oclass.commented_code_lines = code_c
        return oclass

    def _attach_top_level_ops(self, module: PythonModule, tree: ast.AST) -> None:
        top_ops = [
            self._operation_from_function(n)
            for n in tree.body
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]
        if not top_ops:
            return
        narr, code_c = self._file_comment_issues(self._text)
        if not module.classes:
            holder = PythonOoadClass(name="_module", sequential_order=1)
            holder.operations = top_ops
            holder.narration_comment_lines = narr
            holder.commented_code_lines = code_c
            module.classes.append(holder)
            return
        module.classes[0].operations.extend(top_ops)


    def _operations_from_class(self, class_node: ast.ClassDef) -> list[Operation]:
        ops: list[Operation] = []
        for node in class_node.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                ops.append(self._operation_from_function(node))
        return ops


    def _operation_from_function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> Operation:
        params = [a.arg for a in node.args.args if a.arg != "self"]
        params += [a.arg for a in node.args.kwonlyargs]
        ret = ""
        if node.returns is not None:
            ret = ast.unparse(node.returns)
        line_count = 0
        if getattr(node, "end_lineno", None) and node.lineno:
            line_count = node.end_lineno - node.lineno + 1
        bare_except_lines, swallowed_except_lines = self._collect_except_issues(node)
        doc = (ast.get_docstring(node) or "").strip()
        name_words = set(node.name.lower().replace("_", " ").split())
        doc_words = set(doc.lower().strip(".").split()) if doc else set()
        return Operation(
            name=node.name,
            parameters=params,
            return_type=ret,
            description=doc,
            line=node.lineno,
            line_count=line_count,
            nesting_depth=self._max_nesting(node.body, 0),
            callees=self._collect_callees(node),
            literals=self._collect_literals(node),
            param_count=len(params),
            has_calculation=self._has_calculation(node),
            has_validation=self._has_validation(node),
            bare_except_lines=bare_except_lines,
            swallowed_except_lines=swallowed_except_lines,
            assigned_names=self._collect_assigned_names(node),
            loop_target_names=self._collect_loop_targets(node),
            body_fingerprint=self._body_fingerprint(node),
            constructed_types=self._constructed_types(node),
            public_attr_assigns=self._public_attr_assigns(node),
            is_property=self._is_property(node),
            returns_private_attr=self._returns_private_attr(node),
            magic_numbers=self._magic_numbers(node),
            docstring_parrots_name=bool(name_words and doc_words and doc_words <= name_words),
        )


    def _properties_from_class(self, class_node: ast.ClassDef) -> list[Property]:
        props: list[Property] = []
        for node in class_node.body:
            if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                hint = ast.unparse(node.annotation) if node.annotation else ""
                props.append(Property(name=node.target.id, type_hint=hint))
        return props


    def _max_nesting(self, body: list, depth: int) -> int:
        deepest = depth
        for node in body:
            if isinstance(node, _NESTING_TYPES):
                child_depth = depth + 1
                for field_name in ("body", "orelse", "handlers", "finalbody"):
                    children = getattr(node, field_name, None)
                    if children:
                        deepest = max(deepest, self._max_nesting(children, child_depth))
            elif hasattr(node, "body") and isinstance(node.body, list):
                deepest = max(deepest, self._max_nesting(node.body, depth))
        return deepest


    def _collect_callees(self, func: ast.AST) -> list[str]:
        names: list[str] = []
        for child in ast.walk(func):
            if isinstance(child, ast.Call):
                if isinstance(child.func, ast.Name):
                    names.append(child.func.id)
                elif isinstance(child.func, ast.Attribute):
                    names.append(child.func.attr)
        return names


    def _collect_literals(self, func: ast.AST) -> list[str]:
        out: list[str] = []
        for child in ast.walk(func):
            if isinstance(child, ast.Constant) and isinstance(child.value, str):
                out.append(child.value)
        return out


    _CALC_OPS = (
        ast.BinOp,
        ast.BoolOp,
        ast.Compare,
        ast.ListComp,
        ast.SetComp,
        ast.DictComp,
        ast.GeneratorExp,
    )


    def _has_calculation(self, func: ast.AST) -> bool:
        return any(isinstance(child, type(self)._CALC_OPS) for child in ast.walk(func))


    def _has_validation(self, func: ast.AST) -> bool:
        for child in ast.walk(func):
            if isinstance(child, ast.Call) and isinstance(child.func, ast.Attribute):
                if any(
                    child.func.attr.startswith(v)
                    for v in ("validate", "check", "verify", "assert", "ensure")
                ):
                    return True
            if isinstance(child, ast.If) and isinstance(child.test, ast.Compare):
                if any(isinstance(stmt, ast.Raise) for stmt in child.body):
                    return True
        return False


    def _collect_except_issues(self, func: ast.AST) -> tuple[list[int], list[int]]:
        bare: list[int] = []
        swallowed: list[int] = []
        for child in ast.walk(func):
            if not isinstance(child, ast.ExceptHandler):
                continue
            line = child.lineno
            if child.type is None:
                bare.append(line)
            body = child.body
            if len(body) == 1 and isinstance(body[0], ast.Pass):
                swallowed.append(line)
            elif (
                len(body) == 1
                and isinstance(body[0], ast.Expr)
                and isinstance(body[0].value, ast.Constant)
                and isinstance(body[0].value.value, str)
            ):
                swallowed.append(line)
        return bare, swallowed


    def _collect_assigned_names(self, func: ast.AST) -> list[tuple[str, int]]:
        names: list[tuple[str, int]] = []
        for child in ast.walk(func):
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Store):
                names.append((child.id, child.lineno))
            elif isinstance(child, ast.arg) and child.arg not in {"self", "cls"}:
                names.append((child.arg, getattr(child, "lineno", 0) or 0))
        return names


    def _collect_loop_targets(self, func: ast.AST) -> list[tuple[str, int]]:
        targets: list[tuple[str, int]] = []
        for child in ast.walk(func):
            if isinstance(child, (ast.For, ast.AsyncFor)):
                if isinstance(child.target, ast.Name):
                    targets.append((child.target.id, child.target.lineno))
                elif isinstance(child.target, ast.Tuple):
                    for elt in child.target.elts:
                        if isinstance(elt, ast.Name):
                            targets.append((elt.id, elt.lineno))
        return targets


    def _body_fingerprint(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> str:
        import hashlib

        normalized = ast.dump(ast.Module(body=node.body, type_ignores=[]))
        return hashlib.sha256(normalized.encode()).hexdigest()


    def _constructed_types(self, func: ast.AST) -> list[tuple[str, int]]:
        out: list[tuple[str, int]] = []
        for child in ast.walk(func):
            if isinstance(child, ast.Call) and isinstance(child.func, ast.Name):
                if child.func.id and child.func.id[0].isupper():
                    out.append((child.func.id, child.lineno))
        return out


    def _public_attr_assigns(self, func: ast.AST) -> list[tuple[str, int]]:
        out: list[tuple[str, int]] = []
        for child in ast.walk(func):
            if not isinstance(child, ast.Assign):
                continue
            for target in child.targets:
                if (
                    isinstance(target, ast.Attribute)
                    and isinstance(target.value, ast.Name)
                    and target.value.id == "self"
                    and not target.attr.startswith("_")
                ):
                    out.append((target.attr, child.lineno))
        return out


    def _is_property(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
        return any(isinstance(d, ast.Name) and d.id == "property" for d in node.decorator_list)


    def _returns_private_attr(self, func: ast.AST) -> bool:
        for child in ast.walk(func):
            if not isinstance(child, ast.Return) or child.value is None:
                continue
            val = child.value
            if (
                isinstance(val, ast.Attribute)
                and isinstance(val.value, ast.Name)
                and val.value.id == "self"
                and val.attr.startswith("_")
            ):
                return True
        return False


    def _magic_numbers(self, func: ast.AST) -> list[tuple[float, int]]:
        safe = {0, 1, 2, -1, 0.0, 1.0, 0.5, 100, 10, True, False, None}
        out: list[tuple[float, int]] = []
        for child in ast.walk(func):
            if isinstance(child, ast.Constant) and isinstance(child.value, (int, float)):
                if child.value not in safe:
                    out.append((float(child.value), child.lineno))
        return out


    def _file_comment_issues(self, text: str) -> tuple[list[int], list[int]]:
        import re

        narration = re.compile(
            r"^\s*#\s*(get|set|return|handle|create|init|import|increment|decrement|define|declare)\s",
            re.I,
        )
        commented = re.compile(
            r"^\s*#\s*(def |class |import |from |if |for |while |return |raise |try:)",
        )
        useful = re.compile(
            r"^\s*#\s*(TODO|FIXME|HACK|NOTE|XXX|BUG|WARN|WHY|REASON|LEGAL|LICENSE|COPYRIGHT|type:\s*ignore|noqa)",
            re.I,
        )
        narr_lines: list[int] = []
        code_lines: list[int] = []
        for i, line in enumerate(text.splitlines(), start=1):
            stripped = line.strip()
            if not stripped.startswith("#") or useful.match(stripped):
                continue
            if narration.match(stripped):
                narr_lines.append(i)
            elif commented.match(stripped):
                code_lines.append(i)
        return narr_lines, code_lines


    def _populate_classes_regex(self, text: str, module: PythonModule) -> None:
        order = len(module.classes) + 1
        for m in _CLASS_PATTERN.finditer(text):
            oclass = PythonOoadClass(
                name=m.group(1),
                sequential_order=order,
                intent=m.group(2).strip(),
            )
            module.classes.append(oclass)
            order += 1
        if not module.classes:
            for m in _CLASS_NAME_ONLY.finditer(text):
                module.classes.append(PythonOoadClass(name=m.group(1), sequential_order=order))
                order += 1


    def _render_class(self, oclass: OoadClass, known_names: List[str] | None = None) -> str:
        self._known_names = known_names or []
        iface = companion_interface_name(oclass.name, self._known_names)
        bases = iface if iface and not is_interface_name(oclass.name) else "ABC"
        lines: List[str] = [f"class {oclass.name}({bases}):"]
        if oclass.intent:
            lines.append(f'    """{oclass.intent}"""')
            lines.append("")
        self._render_properties(lines, oclass)
        self._render_init(lines, oclass)
        for op in oclass.operations:
            params = ", ".join(op.parameters)
            ret = op.return_type or "None"
            lines.append("    @abstractmethod")
            lines.append(f"    def {op.name}(self, {params}) -> {ret}: ...")
            lines.append("")
        while lines and lines[-1] == "":
            lines.pop()
        if not [ln for ln in lines[1:] if ln.strip()]:
            lines.append("    pass")
        return "\n".join(lines)

    def _render_properties(self, lines: List[str], oclass: OoadClass) -> None:
        iface = companion_interface_name(oclass.name, self._known_names)
        for prop in oclass.properties:
            hint = prop.type_hint or "object"
            if is_interface_name(oclass.name) or not iface:
                lines.append("    @property")
                lines.append("    @abstractmethod")
                lines.append(f"    def {prop.name}(self) -> {hint}: ...")
                lines.append("")
            else:
                lines.append(f"    {prop.name}: {hint}")
        if oclass.properties and not is_interface_name(oclass.name) and iface:
            lines.append("")

    def _render_init(self, lines: List[str], oclass: OoadClass) -> None:
        if not oclass.properties:
            return
        param_sig = ", ".join(
            f"{p.name}: {p.type_hint}" if p.type_hint else p.name for p in oclass.properties
        )
        lines.append("    @abstractmethod")
        lines.append(f"    def __init__(self, {param_sig}) -> None: ...")
        lines.append("")

class TypeScriptCleanEngineeringModel(CleanEngineeringModel):
    def load_module(self, source: Module) -> TypeScriptModule:
        loaded = TypeScriptModule(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def load_class(self, source: OoadClass) -> TypeScriptOoadClass:
        loaded = TypeScriptOoadClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    @classmethod
    def parse(cls, text: str) -> "TypeScriptCleanEngineeringModel":
        return CFamilyParse(
            model_factory=lambda: cls(name="", sequential_order=1),
            class_factory=lambda **kw: TypeScriptOoadClass(**kw),
        ).parse(text)

    @classmethod
    def parse_detailed(cls, text: str):
        from practices.clean_engineering.model.python.python_class_model import ParsedPython

        model = cls.parse(text)
        return ParsedPython(model=model, content=text, lines=text.split("\n"), tree=None)

    @classmethod
    def parse_file(cls, path: Path):
        try:
            return cls.parse_detailed(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError):
            return None

    def render(self, canonical: Optional[CleanEngineeringModel] = None, previous: Optional[str] = None) -> str:
        if canonical is not None:
            self.translate_from(canonical)
        known_names = [loaded.name for loaded in self.classes]
        rendered = "\n\n".join(module.render(known_names) for module in self.modules)
        return rendered + ("\n" if rendered else "")

    @classmethod
    def sync(cls, text: str, canonical: CleanEngineeringModel) -> UpdateReport:
        return canonical.translate_from(cls.parse(text))

class CodeStoryMap:
    """Abstract base for source-tree backends of a Story Map."""

    LEAF_EXTENSION: str = ""
    LANGUAGE_LINE_COMMENT: str = "//"

    def __init__(self, tests_root: str | None = None):
        self._tests_root = ("tests" if tests_root is None else tests_root).strip("/")

    def strip_tests_root_prefix(self, parts: list[str]) -> list[str] | None:
        """Drop the workspace-relative deploy prefix from a rendered file path."""
        if not self._tests_root:
            return parts
        root_parts = [p for p in self._tests_root.split("/") if p]
        if not root_parts:
            return parts
        if len(parts) < len(root_parts) or parts[: len(root_parts)] != root_parts:
            return None
        return parts[len(root_parts) :]

    @property
    def tests_root(self) -> str:
        return self._tests_root

    def render(
        self,
        canonical: StoryMap,
        previous: Optional[Dict[str, str]] = None,
    ) -> Dict[str, str]:
        """Return a `{file_path: content}` mapping for the whole canonical tree.

        If `previous` is provided, every hand-written region in a matching
        existing file is copied through byte-for-byte.
        """

        tree: Dict[str, str] = {}
        previous_tree = previous or {}
        for epic in canonical.epics:
            self._render_epic(
                epic=epic,
                epic_slug=self._folder_slug(epic, canonical.epics),
                tree=tree,
                previous_tree=previous_tree,
            )
        return tree

    def parse(self, external: Dict[str, str]) -> StoryMap:
        # WHY: reconstruct by walking every leaf file path - the shape encodes
        # the Epic/SubEpic hierarchy uniquely.
        if not isinstance(external, dict):
            raise CodeStoryMapError("Tree must be a mapping of paths to file content")

        story_map = self._make_story_map()
        epics_by_slug: Dict[str, Epic] = {}

        for path in sorted(external):
            parts = path.split("/")
            if not parts or parts[0] != self._tests_root:
                continue
            if len(parts) < 3:
                continue
            _, epic_slug, *rest = parts

            epic = epics_by_slug.get(epic_slug)
            if epic is None:
                epic = self._make_epic(epic_slug, len(story_map.epics) + 1)
                epics_by_slug[epic_slug] = epic
                story_map.epics.append(epic)

            if len(rest) < 2:
                continue
            *sub_epic_slugs, _file_name = rest

            current_sub_epics = epic.sub_epics
            current_sub_epic: Optional[SubEpic] = None
            for slug in sub_epic_slugs:
                existing = next(
                    (s for s in current_sub_epics if to_kebab(s.name) == slug),
                    None,
                )
                if existing is None:
                    existing = self._make_sub_epic(slug, len(current_sub_epics) + 1)
                    current_sub_epics.append(existing)
                current_sub_epics = existing.sub_epics
                current_sub_epic = existing

            if current_sub_epic is not None:
                self._leaf_file_name = _file_name
                self._leaf_content = external[path]
                self._hydrate_leaf_sub_epic_from_content(current_sub_epic)

        if not story_map.epics and external:
            raise CodeStoryMapError(
                "Tree contains no recognisable Epic folders under the tests root"
            )
        return story_map

    def _make_story_map(self) -> StoryMap:
        """Factory - overridden by concrete subclasses to return format-typed root."""
        return StoryMap()

    def _make_epic(self, name: str, order: int) -> Epic:
        """Factory - overridden by concrete subclasses to return format-typed Epic."""
        return Epic(name, order)

    def _make_sub_epic(self, name: str, order: int) -> SubEpic:
        """Factory - overridden by concrete subclasses to return format-typed SubEpic."""
        return SubEpic(name, order)

    def _hydrate_leaf_sub_epic_from_content(self, current_sub_epic: SubEpic) -> None:
        # WHY: language backends override this to reconstruct story and scenario
        # structure when parsing generated source trees back into StoryMap.
        return None

    def sync(
        self, external: Dict[str, str], canonical: StoryMap
    ) -> UpdateReport:
        parsed = self.parse(external)
        return canonical.translate_from(parsed)

    def leaf_files_of(self, tree: Dict[str, str]) -> List[str]:
        return sorted(
            p for p in tree if p.endswith(self.LEAF_EXTENSION) and self._is_leaf_path(p)
        )

    def folders_of(self, tree: Dict[str, str]) -> List[str]:
        folders: set = set()
        for path in tree:
            parts = path.split("/")
            for i in range(1, len(parts)):
                folders.add("/".join(parts[:i]))
        return sorted(folders)

    def _is_leaf_path(self, path: str) -> bool:
        parts = path.split("/")
        return len(parts) >= 4 and parts[-1].endswith(self.LEAF_EXTENSION)

    def _render_epic(
        self,
        epic: Epic,
        epic_slug: str,
        tree: Dict[str, str],
        previous_tree: Dict[str, str],
    ) -> None:
        epic_root = f"{self._tests_root}/{epic_slug}"
        helper_content = self._render_epic_helper(epic)
        if helper_content is not None:
            helper_path = self._epic_helper_path(epic_root, epic)
            tree[helper_path] = helper_content
        if not epic.sub_epics and helper_content is None:
            tree[self._epic_marker_path(epic_root)] = self._render_epic_marker(epic)
        for sub_epic in epic.sub_epics:
            self._render_sub_epic(
                sub_epic=sub_epic,
                sibling_sub_epics=epic.sub_epics,
                parent_path=epic_root,
                owning_epic=epic,
                tree=tree,
                previous_tree=previous_tree,
            )

    def _render_sub_epic(
        self,
        sub_epic: SubEpic,
        sibling_sub_epics: List[SubEpic],
        parent_path: str,
        owning_epic: Epic,
        tree: Dict[str, str],
        previous_tree: Dict[str, str],
    ) -> None:
        folder = f"{parent_path}/{self._folder_slug(sub_epic, sibling_sub_epics)}"
        for nested in sub_epic.sub_epics:
            self._render_sub_epic(
                sub_epic=nested,
                sibling_sub_epics=sub_epic.sub_epics,
                parent_path=folder,
                owning_epic=owning_epic,
                tree=tree,
                previous_tree=previous_tree,
            )
        if sub_epic.stories or not sub_epic.sub_epics:
            leaf_path = f"{folder}/{to_kebab(sub_epic.name)}{self.LEAF_EXTENSION}"
            generated = self._render_leaf_file(sub_epic, owning_epic)
            previous = previous_tree.get(leaf_path)
            if previous is not None:
                generated = self._preserve_hand_written(previous, generated)
            tree[leaf_path] = generated

    def _epic_helper_path(self, epic_root: str, epic: Epic) -> str:
        return ""  # WHY: only backends that need a helper (Python, Java) override.

    def _render_epic_helper(self, epic: Epic) -> Optional[str]:
        # WHY: TypeScript backend needs no per-Epic helper file; Python/Java do.
        return None

    def _epic_marker_path(self, epic_root: str) -> str:
        return f"{epic_root}/.epic"

    def _render_epic_marker(self, epic: Epic) -> str:
        return f"epic:{epic.name}\n"

    def _folder_slug(
        self,
        node: Union[Epic, SubEpic],
        siblings: List[Union[Epic, SubEpic]],
    ) -> str:
        base = to_kebab(node.name)
        duplicate_count = sum(
            1 for sibling in siblings if to_kebab(sibling.name) == base
        )
        if duplicate_count <= 1:
            return base
        return f"{base}--{node.sequential_order}"

    def _render_leaf_file(self, sub_epic: SubEpic, owning_epic: Epic) -> str:
        raise NotImplementedError

    def _preserve_hand_written(self, previous: str, generated: str) -> str:
        # WHY: every HAND-WRITTEN region in `previous` survives regeneration
        # byte-for-byte. Blocks whose label matches a placeholder in `generated`
        # are inlined at that placeholder; every other hand-written block is
        # appended to the end of the generated file in original order.
        line_comment = self.LANGUAGE_LINE_COMMENT
        marker_start = f"{line_comment} HAND-WRITTEN START"
        marker_end = f"{line_comment} HAND-WRITTEN END"
        pattern = re.compile(
            re.escape(marker_start) + r"\s*(\S*)\s*\n(.*?)\n" + re.escape(marker_end),
            re.DOTALL,
        )

        found_blocks = []
        for match in pattern.finditer(previous):
            found_blocks.append((match.group(1), match.group(2)))
        if not found_blocks:
            return generated

        labels_in_generated = {m.group(1) for m in pattern.finditer(generated)}

        def substitute(match: re.Match) -> str:
            label = match.group(1)
            for stored_label, stored_body in found_blocks:
                if stored_label == label:
                    return f"{marker_start} {label}\n{stored_body}\n{marker_end}"
            return match.group(0)

        result = pattern.sub(substitute, generated)

        appended = [
            f"{marker_start} {label}\n{body}\n{marker_end}"
            for label, body in found_blocks
            if label not in labels_in_generated
        ]
        if appended:
            if not result.endswith("\n"):
                result += "\n"
            result += "\n" + "\n".join(appended) + "\n"
        return result

