class CodeQLPopulate:
    def __init__(self, graph: PracticeGraph) -> None:
        self.graph = graph
        self.root: Path = graph.root
        self.results_path: Path | None = None
        self.export: CodeQLPracticeGraphExport
        self.modules: Dict[str, GraphModule] = {}
        self.classes: Dict[str, OoadClass] = {}
        self._module_order = 1
        self._examples_by_name: Dict[str, List[GraphExample]] = {}

    def apply(self) -> bool:
        export_path = resolve_codeql_results_path(self.root, self.results_path)
        if export_path is None:
            return False
        self.export = load_codeql_export(export_path)
        self._ensure_ce_nodes()
        self._wire_codeql_calls()
        self._wire_story_calls()
        self._wire_story_observations()
        self._wire_example_demonstrates()
        return True

    def _ensure_ce_nodes(self) -> None:
        self.modules = {}
        for mod in self.graph.nodes_of_type(GraphModule):
            self.modules[mod.name.lower()] = mod
        self.classes = {}
        for cls in self.graph.nodes.values():
            if isinstance(cls, OoadClass):
                self.classes[cls.name.lower()] = cls
        self._module_order = 1
        self._ensure_modules_and_classes()
        self._ensure_properties()
        self._ensure_operations()

    def _ensure_modules_and_classes(self) -> None:
        for entry in self.export.classes:
            mod = self._module_for(entry)
            self._class_for(entry, mod)

    def _module_for(self, entry) -> GraphModule:
        key = entry.module.lower()
        existing = self.modules.get(key)
        if existing is not None:
            return existing
        mod = GraphModule(entry.module, self._module_order)
        self._module_order += 1
        self.graph.register(mod)
        self.graph.index_module(mod)
        self.modules[key] = mod
        if self.graph.ce_model is None:
            return mod
        self.graph.ce_model.modules.append(mod)
        self.graph.ce_model.relate(Kind.OWNS, mod)
        return mod

    def _class_for(self, entry, mod: GraphModule) -> OoadClass:
        existing = self.classes.get(entry.name.lower())
        if existing is not None:
            return existing
        decorated = entry.name
        if entry.stereotypes:
            decorated = f"{entry.name} {' '.join(f'<<{s}>>' for s in entry.stereotypes)}"
        stub = OoadClass(decorated, len(mod.classes) + 1)
        if entry.stereotypes or ddd_class_kind(decorated):
            cls = graph_ddd_class_for(stub)
        else:
            cls = GraphClass(entry.name, len(mod.classes) + 1)
        mod.classes.append(cls)
        self.classes[entry.name.lower()] = cls
        self.graph.register(cls)
        mod.relate(Kind.OWNS, cls)
        cls.relate(Kind.BELONGS_TO, mod)
        return cls

    def _ensure_properties(self) -> None:
        for prop in self.export.properties:
            cls = self.classes.get(prop.class_name.lower())
            if cls is None:
                continue
            if any(p.name == prop.name for p in cls.property_nodes):
                continue
            self._add_property(cls, prop)

    def _add_property(self, cls: OoadClass, prop) -> None:
        if not cls.property_nodes and cls.properties:
            cls.sync_tree_from_legacy()
        node = GraphProperty(
            prop.name,
            len(cls.property_nodes) + 1,
            type_hint=prop.type_hint,
        )
        cls.property_nodes.append(node)
        self.graph.register(node)
        cls.relate(Kind.OWNS, node)
        node.relate(Kind.BELONGS_TO, cls)
        target = self.graph.find_class(prop.type_hint.split("|")[0].strip().rstrip("[]"))
        if target is None:
            return
        node.relate(Kind.HAS_TYPE, target)

    def _ensure_operations(self) -> None:
        for op in self.export.operations:
            cls = self.classes.get(op.class_name.lower())
            if cls is None:
                continue
            if any(o.name == op.name for o in cls.operation_nodes):
                continue
            self._add_operation(cls, op)

    def _add_operation(self, cls: OoadClass, op) -> None:
        if not cls.operation_nodes and cls.operations:
            cls.sync_tree_from_legacy()
        node = GraphOperation(
            op.name,
            len(cls.operation_nodes) + 1,
            return_type=op.return_type,
        )
        node.legacy_parameters = list(op.parameters)
        node._sync_parameters_from_legacy()
        cls.operation_nodes.append(node)
        self.graph.register(node)
        cls.relate(Kind.OWNS, node)
        node.relate(Kind.BELONGS_TO, cls)
        ret = self.graph.find_class(op.return_type.split("|")[0].strip().rstrip("[]"))
        if ret is None:
            return
        node.relate(Kind.RETURNS, ret)

    def _wire_codeql_calls(self) -> None:
        for call in self.export.calls:
            caller = self.graph.find_operation(call.caller_class, call.caller_operation)
            callee = self.graph.find_operation(call.callee_class, call.callee_operation)
            if caller is None or callee is None:
                continue
            caller.relate(Kind.INVOKES, callee)

    def _wire_story_calls(self) -> None:
        for story_call in self.export.story_calls:
            step = self._find_step(story_call)
            operation = self.graph.find_operation(
                story_call.callee_class, story_call.callee_operation
            )
            if step is None or operation is None:
                continue
            step.relate(Kind.INVOKES, operation)

    def _wire_story_observations(self) -> None:
        for obs in self.export.story_observations:
            step = self._find_step(obs)
            if step is None:
                continue
            cls = self.graph.find_class(obs.target_class)
            if cls is None:
                continue
            target = self._observation_target(cls, obs)
            if target is None:
                continue
            step.relate(Kind.OBSERVES, target)

    def _observation_target(self, cls, obs):
        for owned in self.graph.outgoing_nodes(cls, Kind.OWNS):
            if (
                obs.member_kind == "operation"
                and isinstance(owned, GraphOperation)
                and owned.name == obs.target_member
            ):
                return owned
            if (
                obs.member_kind == "property"
                and isinstance(owned, GraphProperty)
                and owned.name == obs.target_member
            ):
                return owned
        return None

    def _wire_example_demonstrates(self) -> None:
        self._examples_by_name = {}
        for example in self.graph.nodes_of_type(GraphExample):
            self._examples_by_name.setdefault(example.name.lower(), []).append(example)
        for entry in self.export.example_exports:
            if not entry.demonstrates:
                continue
            self._relate_demonstrates(entry)

    def _relate_demonstrates(self, entry) -> None:
        for example in self._match_examples(entry):
            self._demonstrate_classes(example, entry.demonstrates)

    def _demonstrate_classes(self, example: GraphExample, cls_names: List[str]) -> None:
        for class_name in cls_names:
            cls = self.graph.find_class(class_name)
            if cls is None:
                continue
            example.relate(Kind.DEMONSTRATES, cls)

    def _match_examples(self, entry) -> List[GraphExample]:
        export_lower = entry.export_name.lower()
        if export_lower in self._examples_by_name:
            return self._examples_by_name[export_lower]
        stem = Path(entry.file).stem.replace(".examples", "").replace("-", " ")
        if stem.lower() in self._examples_by_name:
            return self._examples_by_name[stem.lower()]
        out: List[GraphExample] = []
        for examples in self._examples_by_name.values():
            for ex in examples:
                if export_lower in ex.name.lower() or ex.name.lower() in export_lower:
                    out.append(ex)
        return out

    def _find_step(self, story_call) -> Optional[GraphStep]:
        step_text = getattr(story_call, "step_text", "")
        normalized = story_call.story_file.replace("\\", "/").lstrip("./")
        best: Tuple[int, Optional[GraphStep]] = (1_000_000, None)
        for step in self.graph.nodes_of_type(GraphStep):
            if step_text and step_text.lower() in step.text.lower():
                return step
            src = getattr(step, "source", None)
            if src is None:
                continue
            src_file = str(src.file).replace("\\", "/").lstrip("./")
            if src_file != normalized and not src_file.endswith(normalized):
                continue
            if story_call.line <= 0:
                return step
            delta = abs(int(src.line) - story_call.line)
            if delta < best[0]:
                best = (delta, step)
        if best[1] is not None and best[0] <= 5:
            return best[1]
        return None

class StorySourceQuery:
    def __init__(self, root: Path) -> None:
        self.root = Path(root).resolve()
        self._source = ""
        self._calls: List[_Call] = []
        self._story_calls: List[_Call] = []
        self._scenario_calls: List[_Call] = []
        self._background_calls: List[_Call] = []
        self._file = ""

    def run(self) -> CodeQLPracticeGraphExport:
        stories: List[CodeQLStory] = []
        scenarios: List[CodeQLScenario] = []
        backgrounds: List[CodeQLBackground] = []
        steps: List[CodeQLStep] = []
        examples: List[CodeQLExampleExport] = []
        for path in self._iter_files():
            rel = self._rel(path)
            if _STORY_FILE.match(path.name) and path.name != "story-test.ts":
                s, sc, bg, st = self._query_story_file(path, rel)
                stories.extend(s)
                scenarios.extend(sc)
                backgrounds.extend(bg)
                steps.extend(st)
            if _EXAMPLE_FILE.match(path.name):
                examples.extend(self._query_example_file(path, rel))
        return CodeQLPracticeGraphExport(
            stories=stories,
            scenarios=scenarios,
            backgrounds=backgrounds,
            steps=steps,
            example_exports=examples,
        )

    def _iter_files(self) -> Iterable[Path]:
        for path in self.root.rglob("*"):
            if not path.is_file():
                continue
            if any(part in _SKIP_DIRS for part in path.parts):
                continue
            yield path

    def _rel(self, path: Path) -> str:
        return str(path.resolve().relative_to(self.root)).replace("\\", "/")

    def _query_story_file(
        self, path: Path, rel: str
    ) -> Tuple[List[CodeQLStory], List[CodeQLScenario], List[CodeQLBackground], List[CodeQLStep]]:
        self._source = path.read_text(encoding="utf-8", errors="replace")
        self._file = rel
        calls = self._scan_calls(self._source)
        self._attach_bodies(calls)
        epic, sub_epic = self._owners_from_story_path(rel)
        self._story_calls = [c for c in calls if c.name == "story" and c.text]
        self._scenario_calls = [c for c in calls if c.name == "scenario" and c.text]
        self._background_calls = [c for c in calls if c.name == "background"]
        stories = [
            CodeQLStory(c.text, rel, epic=epic, sub_epic=sub_epic, line=c.line)
            for c in self._story_calls
        ]
        scenarios = self._scenarios()
        backgrounds = self._backgrounds()
        steps = self._steps([c for c in calls if c.name in _KEYWORD])
        return stories, scenarios, backgrounds, steps

    def _story_for(self, pos: int) -> str:
        for story in self._story_calls:
            if story.contains(pos):
                return story.text
        return self._story_calls[0].text if self._story_calls else ""

    def _scenarios(self) -> List[CodeQLScenario]:
        scenarios: List[CodeQLScenario] = []
        for call in self._scenario_calls:
            scenarios.append(
                CodeQLScenario(call.text, self._story_for(call.start), self._file, line=call.line)
            )
        return scenarios

    def _backgrounds(self) -> List[CodeQLBackground]:
        backgrounds: List[CodeQLBackground] = []
        for call in self._background_calls:
            end_line = self._source[: max(call.body_end, call.start)].count("\n") + 1
            backgrounds.append(
                CodeQLBackground(
                    call.text or "background",
                    self._story_for(call.start),
                    self._file,
                    line=call.line,
                    end_line=end_line,
                    scope=call.text if call.text in {"each", "all"} else "each",
                )
            )
        return backgrounds

    def _steps(self, step_calls: List[_Call]) -> List[CodeQLStep]:
        steps: List[CodeQLStep] = []
        last_phase_by_parent: dict[tuple[str, str], str] = {}
        for call in step_calls:
            scenario_name, background_name = self._step_parent(call.start)
            parent = (self._file, scenario_name or background_name)
            if call.name in _PHASE:
                last_phase_by_parent[parent] = _PHASE[call.name]
                phase = _PHASE[call.name]
            else:
                phase = last_phase_by_parent.get(parent, "then")
            steps.append(
                CodeQLStep(
                    keyword=_KEYWORD[call.name],
                    text=call.text,
                    file=self._file,
                    line=call.line,
                    story=self._story_for(call.start),
                    scenario=scenario_name,
                    background=background_name,
                    phase=phase,
                )
            )
        return steps

    def _step_parent(self, pos: int) -> Tuple[str, str]:
        for scenario in self._scenario_calls:
            if scenario.contains(pos):
                return scenario.text, ""
        for background in self._background_calls:
            if background.contains(pos):
                return "", background.text or "background"
        return "", ""

    def _owners_from_story_path(self, rel: str) -> Tuple[str, str]:
        parts = rel.replace("\\", "/").split("/")
        if "stories" not in parts:
            return "", ""
        idx = parts.index("stories") + 1
        rest = [p for p in parts[idx:] if p != "examples"]
        epic = self._display(rest[0]) if rest else ""
        sub = ""
        if len(rest) >= 2 and not _STORY_FILE.match(rest[1]):
            sub = self._display(rest[1])
        return epic, sub

    def _owners_from_example_path(self, rel: str) -> Tuple[str, str]:
        parts = rel.replace("\\", "/").split("/")
        if "examples" not in parts:
            return "", ""
        folder = parts[parts.index("examples") - 1] if parts.index("examples") > 0 else ""
        if folder == "stories":
            return "", ""
        kind = "sub_epic"
        if "stories" in parts:
            after = parts[parts.index("stories") + 1 :]
            if after and after[0] == folder:
                kind = "epic"
        return self._display(folder), kind

    def _display(self, slug: str) -> str:
        if not slug:
            return ""
        if " " in slug:
            return slug
        return slug.replace("-", " ").replace("_", " ").title()

    def _query_example_file(self, path: Path, rel: str) -> List[CodeQLExampleExport]:
        self._source = path.read_text(encoding="utf-8", errors="replace")
        owner, owner_kind = self._owners_from_example_path(rel)
        out: List[CodeQLExampleExport] = []
        matches = list(_EXPORT.finditer(self._source))
        for index, match in enumerate(matches):
            start = match.end()
            end = matches[index + 1].start() if index + 1 < len(matches) else len(self._source)
            chunk = self._source[start:end]
            demonstrates = list(dict.fromkeys(_NEW_CLASS.findall(chunk)))
            out.append(
                CodeQLExampleExport(
                    export_name=match.group(1),
                    file=rel,
                    demonstrates=demonstrates,
                    line=self._source[: match.start()].count("\n") + 1,
                    owner=owner,
                    owner_kind=owner_kind,
                )
            )
        return out

    def _scan_calls(self, source: str) -> List[_Call]:
        self._source = source
        self._calls = []
        i = 0
        n = len(source)
        while i < n:
            if source[i] in " \t\r\n":
                i += 1
                continue
            nxt = self._skip_comment(i)
            if nxt != i:
                i = nxt
                continue
            if source[i] in "'\"`":
                i = self._skip_string(i)
                continue
            chain = self._scan_chain_call(i)
            if chain is not None:
                i = chain
                continue
            named = self._scan_named_call(i)
            if named is not None:
                i = named
                continue
            i += 1
        return self._calls

    def _scan_chain_call(self, i: int) -> Optional[int]:
        source = self._source
        n = len(source)
        if source[i] != "." or i + 1 >= n:
            return None
        if not self._is_ident_start(source[i + 1]):
            return None
        name, j = self._read_ident(i + 1)
        if name not in _CHAIN_NAMES:
            return None
        j = self._skip_ws(j)
        if j >= n or source[j] != "(":
            return None
        text, _end = self._first_string_arg(j)
        if text is not None:
            self._calls.append(_Call(name, text, i, self._line(i)))
        return j + 1

    def _scan_named_call(self, i: int) -> Optional[int]:
        source = self._source
        n = len(source)
        if not self._is_ident_start(source[i]):
            return None
        if i != 0 and self._is_ident_char(source[i - 1]):
            return None
        name, j = self._read_ident(i)
        if name not in _CALL_NAMES:
            return None
        j = self._skip_ws(j)
        if j >= n or source[j] != "(":
            return None
        text, _end = self._first_string_arg(j)
        if name == "background":
            self._calls.append(_Call(name, text or "background", i, self._line(i)))
            return j + 1
        if text is not None:
            self._calls.append(_Call(name, text, i, self._line(i)))
        return j + 1

    def _attach_bodies(self, calls: List[_Call]) -> None:
        for call in calls:
            if call.name not in {"story", "scenario", "background"}:
                continue
            span = self._callback_body_span(call.start)
            if span is None:
                continue
            call.body_start, call.body_end = span

    def _callback_body_span(self, call_pos: int) -> Optional[Tuple[int, int]]:
        paren_at = self._source.find("(", call_pos)
        if paren_at < 0:
            return None
        return self._skip_in_parens(paren_at + 1)

    def _skip_in_parens(self, i: int) -> Optional[Tuple[int, int]]:
        source = self._source
        n = len(source)
        depth = 1
        saw_arrow = False
        while i < n and depth > 0:
            nxt = self._skip_comment(i)
            if nxt != i:
                i = nxt
                continue
            ch = source[i]
            if ch in "'\"`":
                i = self._skip_string(i)
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth -= 1
                i += 1
                continue
            if source.startswith("=>", i):
                saw_arrow = True
                i += 2
                continue
            span = self._body_after_arrow(saw_arrow, i)
            if span is not None:
                return span
            i += 1
        return None

    def _body_after_arrow(self, saw_arrow: bool, i: int) -> Optional[Tuple[int, int]]:
        if not saw_arrow:
            return None
        if self._source[i] != "{":
            return None
        end = self._match_brace(i)
        if end < 0:
            return None
        return (i, end)

    def _match_brace(self, open_idx: int) -> int:
        depth = 0
        i = open_idx
        n = len(self._source)
        while i < n:
            nxt = self._skip_comment(i)
            if nxt != i:
                i = nxt
                continue
            ch = self._source[i]
            if ch in "'\"`":
                i = self._skip_string(i)
                continue
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return i + 1
            i += 1
        return -1

    def _first_string_arg(self, paren_idx: int) -> Tuple[Optional[str], int]:
        i = self._skip_ws(paren_idx + 1)
        if i < len(self._source) and self._source[i] in "'\"`":
            text, end = self._read_string(i)
            return text, end
        return None, paren_idx

    def _read_string(self, start: int) -> Tuple[str, int]:
        source = self._source
        quote = source[start]
        i = start + 1
        n = len(source)
        chars: List[str] = []
        while i < n:
            ch = source[i]
            if ch == "\\" and i + 1 < n:
                chars.append(source[i + 1])
                i += 2
                continue
            if quote == "`" and ch == "$" and i + 1 < n and source[i + 1] == "{":
                i = self._read_interpolation(i, chars)
                continue
            if ch == quote:
                return "".join(chars), i + 1
            if ch == "\n" and quote != "`":
                return "".join(chars), i
            chars.append(ch)
            i += 1
        return "".join(chars), i

    def _read_interpolation(self, i: int, chars: List[str]) -> int:
        chars.append("${")
        i += 2
        source = self._source
        n = len(source)
        depth = 1
        while i < n and depth:
            if source[i] == "{":
                depth += 1
                i += 1
                continue
            if source[i] != "}":
                chars.append(source[i])
                i += 1
                continue
            depth -= 1
            if depth == 0:
                chars.append("}")
                return i + 1
            i += 1
        return i

    def _skip_string(self, start: int) -> int:
        _text, end = self._read_string(start)
        return end

    def _skip_comment(self, i: int) -> int:
        source = self._source
        if source.startswith("//", i):
            nl = source.find("\n", i)
            return len(source) if nl < 0 else nl + 1
        if source.startswith("/*", i):
            end = source.find("*/", i + 2)
            return len(source) if end < 0 else end + 2
        return i

    def _skip_ws(self, i: int) -> int:
        source = self._source
        n = len(source)
        while i < n and source[i] in " \t\r\n":
            i += 1
        return i

    def _is_ident_start(self, ch: str) -> bool:
        return ch.isalpha() or ch == "_" or ch == "$"

    def _is_ident_char(self, ch: str) -> bool:
        return ch.isalnum() or ch in {"_", "$"}

    def _read_ident(self, i: int) -> Tuple[str, int]:
        j = i
        source = self._source
        while j < len(source) and self._is_ident_char(source[j]):
            j += 1
        return source[i:j], j

    def _line(self, pos: int) -> int:
        return self._source[:pos].count("\n") + 1

class CodeQLQueryServer:
    """One `codeql execute query-server2` process for the life of the host."""

    def __init__(self, repo: Path | str, codeql: CodeQL) -> None:
        self.repo = Path(repo)
        self._codeql = codeql
        self._process: subprocess.Popen | None = None
        self._next_id = 1
        self._registered: set[str] = set()
        self._lock = threading.Lock()
        self._last_progress = ""
        self._on_line = None

    @classmethod
    def from_repo(cls, repo: Path | str) -> CodeQLQueryServer:
        root = Path(repo)
        return cls(root, CodeQL(root))

    @property
    def alive(self) -> bool:
        return self._process is not None and self._process.poll() is None

    @property
    def pid(self) -> int | None:
        if self._process is None:
            return None
        return self._process.pid

    def start(self) -> None:
        if self.alive:
            return
        executable = self._codeql.executable()
        ram = subprocess.run(
            [executable, "resolve", "ram", "--"],
            check=False,
            capture_output=True,
            text=True,
        )
        ram_args = [line.strip() for line in (ram.stdout or "").splitlines() if line.strip()]
        command = [
            executable,
            "execute",
            "query-server2",
            "--threads=0",
            "-q",
            *ram_args,
        ]
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if sys.platform == "win32" else 0
        self._process = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=str(self._codeql.repo_root()),
            creationflags=flags,
        )
        if self._process.stdout is None or self._process.stdin is None:
            raise CodeQLRunError("codeql query server produced no stdio streams")
        threading.Thread(target=self._drain_stderr, daemon=True).start()
        self._registered.clear()

    def stop(self) -> None:
        process = self._process
        self._process = None
        self._registered.clear()
        if process is None:
            return
        if process.stdin is not None:
            try:
                process.stdin.close()
            except OSError:
                pass
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                self._kill_tree(process.pid)
                process.wait(timeout=5)
        elif process.pid:
            self._kill_tree(process.pid)

    def run_queries(self, queries, database: Path, on_line) -> dict[str, Path]:
        """Evaluate one batch on the warm server. Returns resolved query path to bqrs."""
        with self._lock:
            if not self.alive:
                raise QueryServerDown("codeql query server is not running")
            self._on_line = on_line
            self._last_progress = ""
            db = str(Path(database).resolve())
            self._register(db)
            folder = Path(database) / "results" / "query-server"
            folder.mkdir(parents=True, exist_ok=True)
            inputs = []
            outputs: dict[str, Path] = {}
            for query in queries:
                resolved = str(Path(query).resolve())
                bqrs = folder / f"{Path(query).stem}.bqrs"
                dil = bqrs.with_suffix(".dil")
                inputs.append(
                    {
                        "queryPath": resolved,
                        "outputPath": str(bqrs),
                        "dilPath": str(dil),
                    }
                )
                outputs[resolved] = bqrs
            result = self._request(
                "evaluation/runQueries",
                {
                    "inputOutputPaths": inputs,
                    "db": db,
                    "additionalPacks": [],
                    "externalInputs": {},
                    "singletonExternalInputs": {},
                },
            )
            failures: list[str] = []
            produced: dict[str, Path] = {}
            by_path = {
                str(Path(path).resolve()): value
                for path, value in (result or {}).items()
                if isinstance(value, dict)
            }
            for resolved, bqrs in outputs.items():
                entry = by_path.get(resolved) or {}
                result_type = entry.get("resultType", 1)
                if result_type != 0 or not bqrs.is_file():
                    message = entry.get("message") or f"resultType={result_type}"
                    failures.append(f"{Path(resolved).stem}: {message}")
                else:
                    produced[resolved] = bqrs
                dil = bqrs.with_suffix(".dil")
                if dil.is_file():
                    dil.unlink()
            if failures and not produced:
                raise CodeQLRunError("codeql query server failed: " + "; ".join(failures))
            if failures and on_line is not None:
                on_line("query-server partial: " + "; ".join(failures))
            return produced

    def _register(self, database: str) -> None:
        if database in self._registered:
            return
        self._request("evaluation/registerDatabases", {"databases": [database]})
        self._registered.add(database)

    def _request(self, method: str, body: dict) -> dict:
        request_id = self._next_id
        self._next_id += 1
        progress_id = self._next_id
        self._next_id += 1
        payload = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": {"progressId": progress_id, "body": body},
        }
        raw = json.dumps(payload).encode("utf-8")
        process = self._process
        if process is None or process.stdin is None or process.stdout is None:
            raise QueryServerDown("codeql query server is not running")
        try:
            process.stdin.write(f"Content-Length: {len(raw)}\r\n\r\n".encode("ascii") + raw)
            process.stdin.flush()
        except OSError as error:
            raise QueryServerDown(f"codeql query server stdin closed: {error}") from error
        while True:
            message = self.read_message(process.stdout)
            if message.get("id") != request_id:
                if message.get("method") == "ql/progressUpdated":
                    self._note_progress(message.get("params") or {})
                continue
            if "error" in message:
                err = message["error"]
                detail = err.get("message", err) if isinstance(err, dict) else err
                raise CodeQLRunError(f"{method} failed: {detail}")
            result = message.get("result")
            return result if isinstance(result, dict) else {}

    def _note_progress(self, params: dict) -> None:
        message = str(params.get("message") or "").strip()
        if not message or message == self._last_progress or message.startswith("("):
            return
        self._last_progress = message
        phase = message.split(" ", 1)[0]
        if ".ql" not in message and phase not in _PHASES:
            return
        if self._on_line is not None:
            self._on_line(message)

    def _drain_stderr(self) -> None:
        process = self._process
        if process is None or process.stderr is None:
            return
        for line in process.stderr:
            text = line.decode("utf-8", errors="replace").rstrip("\r\n")
            if text and self._on_line is not None:
                self._on_line(text)

    @staticmethod
    def read_message(stream) -> dict:
        headers: dict[str, str] = {}
        while True:
            line = stream.readline()
            if not line:
                raise QueryServerDown("codeql query server closed the stream")
            if line in (b"\r\n", b"\n"):
                break
            key, value = line.decode("ascii").split(":", 1)
            headers[key.strip().lower()] = value.strip()
        length = int(headers["content-length"])
        chunks: list[bytes] = []
        remaining = length
        while remaining:
            chunk = stream.read(remaining)
            if not chunk:
                raise QueryServerDown("codeql query server closed the stream")
            chunks.append(chunk)
            remaining -= len(chunk)
        return json.loads(b"".join(chunks))

    def _kill_tree(self, pid: int) -> None:
        if sys.platform == "win32":
            subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(pid)],
                check=False,
                capture_output=True,
            )
            return
        try:
            os.kill(pid, 9)
        except OSError:
            logger = __import__("logging").getLogger(__name__)
            logger.debug("process %s already gone", pid)
            return

class QueryServerClient:
    alive = True

    def __init__(self, host: str = _HOST, port: int = 0, pid: int | None = None) -> None:
        self.host = host
        self.port = port
        self.pid = pid

    def state_path(self, repo: Path) -> Path:
        return CodeQL(repo).repo_root() / ".codeql" / "query-server.json"

    def ensure_query_server(self, repo: Path):
        """Return a client to a long-lived query daemon; spawn it if needed."""
        path = self.state_path(repo)
        client = self._connect(path)
        if client is not None:
            return client
        self._spawn(repo, path)
        deadline = time.time() + _WAIT_SECONDS
        while time.time() < deadline:
            client = self._connect(path)
            if client is not None:
                return client
            time.sleep(0.2)
        raise CodeQLRunError("codeql query daemon did not become ready")

    def _connect(self, path: Path) -> QueryServerClient | None:
        if not path.is_file():
            return None
        try:
            state = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            return None
        host = state.get("host") or _HOST
        port = state.get("port")
        if not port:
            return None
        try:
            result = _rpc(host, int(port), {"method": "ping"})
        except OSError:
            return None
        if not result.get("ok"):
            return None
        return QueryServerClient(host, int(port), state.get("pid"))

    def _spawn(self, repo: Path, path: Path) -> None:
        root = str(CodeQL(repo).repo_root())
        env = os.environ.copy()
        extra = [
            root,
            str(Path(root) / "tools"),
            str(Path(root) / "practices"),
            str(Path(root) / "actions"),
        ]
        existing = env.get("PYTHONPATH", "")
        env["PYTHONPATH"] = os.pathsep.join(
            [*extra, *(existing.split(os.pathsep) if existing else ())]
        )
        flags = 0
        if sys.platform == "win32":
            flags = getattr(subprocess, "DETACHED_PROCESS", 0) | getattr(
                subprocess, "CREATE_NEW_PROCESS_GROUP", 0
            )
        log = path.parent / "query-server.log"
        stream = open(log, "a", encoding="utf-8")
        subprocess.Popen(
            [sys.executable, "-m", "harness.mcp.codeql_query_daemon", root],
            cwd=root,
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=stream,
            stderr=subprocess.STDOUT,
            creationflags=flags,
            close_fds=True,
        )

    def run_queries(self, queries, database: Path, on_line) -> dict[str, Path]:
        result = _rpc(
            self.host,
            self.port,
            {
                "method": "runQueries",
                "queries": [str(Path(query).resolve()) for query in queries],
                "database": str(Path(database).resolve()),
            },
        )
        for line in result.get("log") or []:
            if on_line is not None:
                on_line(line)
        if result.get("error"):
            raise CodeQLRunError(result["error"])
        return {
            key: Path(value)
            for key, value in (result.get("produced") or {}).items()
        }

    def start(self) -> None:
        return

    def stop(self) -> None:
        return

class GraphQueryRun:
    def execute(self, ql_path: Path, root: Path) -> List[dict]:
        if shutil.which("codeql") is None:
            return []
        database = self._database(root)
        if database is None:
            return []
        with tempfile.TemporaryDirectory() as folder:
            bqrs = Path(folder) / "results.bqrs"
            decoded = Path(folder) / "results.json"
            run = subprocess.run(
                [
                    "codeql",
                    "query",
                    "run",
                    str(ql_path),
                    "--database",
                    str(database),
                    "--output",
                    str(bqrs),
                ],
                check=False,
                capture_output=True,
                text=True,
            )
            if run.returncode != 0 or not bqrs.is_file():
                return []
            decode = subprocess.run(
                [
                    "codeql",
                    "bqrs",
                    "decode",
                    str(bqrs),
                    "--format=json",
                    f"--output={decoded}",
                ],
                check=False,
                capture_output=True,
                text=True,
            )
            if decode.returncode != 0 or not decoded.is_file():
                return []
            payload = json.loads(decoded.read_text(encoding="utf-8"))
        return self._rows(payload)

    def _database(self, root: Path) -> Optional[Path]:
        codeql = root / ".codeql"
        if not codeql.is_dir():
            return None
        for child in codeql.iterdir():
            if child.is_dir() and child.name.endswith("-db"):
                return child
        return None

    def _rows(self, payload: dict) -> List[dict]:
        from .codeql import Rows as CodeQLRows

        decoder = CodeQLRows()
        tuples = payload.get("#select", {}).get("tuples", [])
        rows: List[dict] = []
        for item in tuples:
            if not item:
                continue
            rows.append(self._row(decoder, item))
        return rows

    def _row(self, decoder, item: list) -> dict:
        first = item[0]
        name = decoder.entity_name(first)
        message = item[1] if len(item) > 1 else ""
        if isinstance(message, dict):
            message = message.get("label", "")
        contributor = item[2] if len(item) > 2 else None
        if isinstance(contributor, dict):
            contributor = contributor.get("label")
        file, line = decoder.entity_location(first)
        row = {"name": name, "message": str(message)}
        kind = decoder.entity_kind(first)
        if kind:
            row["kind"] = kind
        if file:
            row["file"] = file
        if line:
            row["line"] = line
        if contributor:
            row["contributor"] = str(contributor)
        return row

class McpHost:
    """stdio MCP process — one CDD runtime, many protocol requests."""

    def __init__(self, runtime: McpServer) -> None:
        self._runtime = runtime
        self._server = Server("cdd")
        self.codeql_server = None
        self._codeql_closed = False
        self._codeql_lock = threading.Lock()
        self._register_handlers()

    def input_schema_for_callable(self, callable: Callable[..., object]) -> dict[str, Any]:
        hints = self._callable_hints(callable)
        properties: dict[str, Any] = {}
        required: list[str] = []
        for name, param in inspect.signature(callable).parameters.items():
            if not self._is_schema_parameter(name, param):
                continue
            properties[name] = self._parameter_schema(hints, name, param)
            if param.default is inspect.Parameter.empty:
                required.append(name)
        result: dict[str, Any] = {"type": "object", "properties": properties}
        if required:
            result["required"] = required
        return result

    def _callable_hints(self, callable: Callable[..., object]) -> dict[str, Any]:
        function = getattr(callable, "__func__", callable)
        try:
            return get_type_hints(function)
        except (NameError, TypeError, AttributeError):
            return {}

    def _is_schema_parameter(self, name: str, param: inspect.Parameter) -> bool:
        if name == "self":
            return False
        return param.kind in (
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        )

    def _parameter_schema(
        self, hints: dict[str, Any], name: str, param: inspect.Parameter
    ) -> dict[str, Any]:
        annotation = hints.get(name, param.annotation)
        if annotation is inspect.Parameter.empty:
            return {"type": "string"}
        return self._annotation_schema(annotation)

    def _annotation_schema(self, annotation: object) -> dict[str, Any]:
        origin = get_origin(annotation)
        if origin in _UNION_ORIGINS:
            return self._union_schema(annotation)
        if annotation is list or origin in _ARRAY_ORIGINS:
            return self._array_schema(annotation)
        if annotation is dict or origin in _OBJECT_ORIGINS:
            return self._object_schema(annotation)
        return self._scalar_schema(annotation)

    def _union_schema(self, annotation: object) -> dict[str, Any]:
        variants = [self._annotation_schema(arg) for arg in get_args(annotation)]
        if len(variants) == 1:
            return variants[0]
        return {"anyOf": variants}

    def _array_schema(self, annotation: object) -> dict[str, Any]:
        args = get_args(annotation)
        item_schema = self._annotation_schema(args[0]) if args else {"type": "string"}
        return {"type": "array", "items": item_schema}

    def _object_schema(self, annotation: object) -> dict[str, Any]:
        args = get_args(annotation)
        schema: dict[str, Any] = {"type": "object"}
        if len(args) >= 2:
            schema["additionalProperties"] = self._annotation_schema(args[1])
        return schema

    def _scalar_schema(self, annotation: object) -> dict[str, Any]:
        if inspect.isclass(annotation) and annotation not in (
            str,
            int,
            float,
            bool,
            type(None),
            Path,
            bytes,
        ):
            return {"type": "object"}
        if annotation is str:
            return {"type": "string"}
        if annotation is int:
            return {"type": "integer"}
        if annotation is float:
            return {"type": "number"}
        if annotation is bool:
            return {"type": "boolean"}
        if annotation is type(None):
            return {"type": "null"}
        return {"type": "string"}

    def _register_handlers(self) -> None:
        @self._server.list_tools()
        async def handle_list_tools() -> list[types.Tool]:
            tools = [
                types.Tool(
                    name=BUILTIN_PING_TOOL,
                    description="Health check for the CDD MCP host process.",
                    inputSchema={"type": "object", "properties": {}},
                )
            ]
            tools.extend(
                listed
                for listed in (
                    self._listed_tool(tool) for tool in self._runtime._tools.values()
                )
                if listed is not None
            )
            tools.extend(
                listed
                for listed in (
                    self._listed_prompt_tool(prompt)
                    for prompt in self._runtime._prompts.values()
                )
                if listed is not None
            )
            return tools

        @self._server.call_tool()
        async def handle_call_tool(
            name: str, arguments: dict[str, object] | None
        ) -> Sequence[types.TextContent | types.ImageContent | types.EmbeddedResource]:
            try:
                name = self._runtime.resolve_call_name(name)
                if name == BUILTIN_PING_TOOL:
                    return self._content_blocks("pong")
                if name in self._runtime._prompts:
                    return self._content_blocks(
                        self._runtime.invoke_prompt(name, dict(arguments or {}))
                    )
                return self._content_blocks(
                    self._runtime.invoke_tool(name, dict(arguments or {}))
                )
            except Exception as error:
                logger.exception("MCP tool %s failed", name)
                return self._content_blocks(f"{type(error).__name__}: {error}")

        @self._server.list_prompts()
        async def handle_list_prompts() -> list[types.Prompt]:
            return []

        @self._server.get_prompt()
        async def handle_get_prompt(
            name: str, arguments: dict[str, str] | None
        ) -> types.GetPromptResult:
            prompt = self._runtime._prompts.get(name)
            if prompt is None:
                raise ValueError(f"unknown prompt: {name}")
            return types.GetPromptResult(
                description=prompt.prompt_text or None,
                messages=[
                    types.PromptMessage(
                        role="user",
                        content=types.TextContent(
                            type="text",
                            text=prompt.prompt_text or "",
                        ),
                    )
                ],
            )

    def _mcp_tool(self, tool: McpTool) -> types.Tool:
        return types.Tool(
            name=tool.mcp_name,
            description=tool.description or None,
            inputSchema=self.input_schema_for_callable(tool.callable),
        )

    def _listed_tool(self, tool: McpTool) -> types.Tool | None:
        try:
            return self._mcp_tool(tool)
        except Exception as error:
            self._runtime.skip(tool.mcp_name, error)
            return None

    def _mcp_prompt_tool(self, prompt: McpPrompt) -> types.Tool:
        return types.Tool(
            name=prompt.mcp_name,
            description=prompt.prompt_text or None,
            inputSchema=self.input_schema_for_callable(prompt.callable),
        )

    def _listed_prompt_tool(self, prompt: McpPrompt) -> types.Tool | None:
        try:
            return self._mcp_prompt_tool(prompt)
        except Exception as error:
            self._runtime.skip(prompt.mcp_name, error)
            return None

    def _as_prompt(self, prompt: McpPrompt) -> types.Prompt:
        return types.Prompt(
            name=prompt.mcp_name,
            description=prompt.prompt_text or None,
        )

    def _content_blocks(self, value: object) -> list[types.TextContent]:
        text = value if isinstance(value, str) else json.dumps(value, default=str)
        return [types.TextContent(type="text", text=text)]

    async def run_stdio(self) -> None:
        init_options = InitializationOptions(
            server_name="cdd",
            server_version="0.1.0",
            capabilities=self._server.get_capabilities(
                notification_options=NotificationOptions(),
                experimental_capabilities={},
            ),
        )
        async with stdio_server() as (read_stream, write_stream):
            await self._server.run(
                read_stream,
                write_stream,
                init_options,
                raise_exceptions=False,
            )

    def run(self) -> None:
        threading.Thread(
            target=self._start_codeql_server,
            name="codeql-query-server",
            daemon=True,
        ).start()
        try:
            while True:
                try:
                    anyio.run(self.run_stdio)
                    return
                except (KeyboardInterrupt, SystemExit):
                    raise
                except Exception:
                    logger.exception("MCP stdio host crashed; restarting")
        finally:
            self._stop_codeql_server()

    def _start_codeql_server(self) -> None:
        from harness.knowledge_graph.model.codeql import attach_query_server
        from harness.mcp.codeql_query_daemon import QueryServerClient

        try:
            server = QueryServerClient().ensure_query_server(Path(self._runtime.repo))
        except Exception:
            logger.exception("CodeQL query server did not start; queries will use the CLI")
            return
        with self._codeql_lock:
            if self._codeql_closed:
                return
            self.codeql_server = server
            attach_query_server(server)
        logger.info("codeql query-server daemon pid=%s", getattr(server, "pid", None))

    def _stop_codeql_server(self) -> None:
        from harness.knowledge_graph.model.codeql import detach_query_server

        with self._codeql_lock:
            self._codeql_closed = True
            server = self.codeql_server
            self.codeql_server = None
        if server is None:
            return
        detach_query_server(server)

    def ping(self) -> str:
        return "pong"

    def diagnose(self) -> dict[str, Any]:
        reply = self.ping()
        if reply != "pong":
            raise McpStandupFailed("diagnose", self, "MCP host ping failed")
        tools = [
            BUILTIN_PING_TOOL,
            *sorted(self._runtime.tools),
            *sorted(self._runtime.prompts),
        ]
        exceptions = [
            {"tool": item.tool, "reason": item.reason}
            for item in self._runtime.exceptions
        ]
        server = self.codeql_server
        return {
            "ok": True,
            "ping": reply,
            "tools": tools,
            "exceptions": exceptions,
            "notice": self.notice(),
            "codeqlServer": server.pid if server is not None and server.alive else None,
        }

    def notice(self) -> str:
        if not self._runtime.exceptions:
            return ""
        lines = ["MCP standup skipped illegitimate tools and continued:"]
        for item in self._runtime.exceptions:
            lines.append(f"- {item.tool}: {item.reason}")
        return "\n".join(lines)

    def notify_exceptions(self) -> None:
        text = self.notice()
        if text:
            print(text, file=sys.stderr)

    def _arg_after(self, args: list[str], flag: str) -> str:
        if flag not in args:
            return ""
        index = args.index(flag)
        if index + 1 >= len(args):
            return ""
        return str(args[index + 1])

    def server_key(self, repo: Path | str) -> str:
        return "cdd"

    def server_entry_from_manifest(
        self, servers: Mapping[str, Any] | Path | str
    ) -> dict[str, Any]:
        raw = self._mcp_servers(servers)
        if not isinstance(raw, Mapping):
            return {}
        preferred = raw.get("cdd")
        if isinstance(preferred, dict) and preferred:
            return preferred
        named = self._named_cdd_server(raw)
        if named:
            return named
        hosted = self._hosted_cdd_server(raw)
        if hosted:
            return hosted
        first = next(iter(raw.values()), {})
        return first if isinstance(first, dict) else {}

    def _mcp_servers(self, servers: Mapping[str, Any] | Path | str) -> object:
        if not isinstance(servers, (Path, str)):
            return servers
        path = Path(servers)
        if not path.is_file():
            return {}
        return json.loads(path.read_text(encoding="utf-8")).get("mcpServers") or {}

    def _named_cdd_server(self, raw: Mapping[str, Any]) -> dict[str, Any]:
        for name, spec in raw.items():
            if isinstance(spec, dict) and str(name).startswith("cdd"):
                return spec
        return {}

    def _hosted_cdd_server(self, raw: Mapping[str, Any]) -> dict[str, Any]:
        for spec in raw.values():
            if not isinstance(spec, dict):
                continue
            blob = " ".join(str(item) for item in spec.get("args") or [])
            if "start_host.py" in blob or "harness.mcp" in blob:
                return spec
        return {}

    def refs_from_manifest(self, manifest: Path | str) -> tuple[str, ...]:
        args = [str(item) for item in self.server_entry_from_manifest(manifest).get("args") or []]
        raw = self._arg_after(args, "--toolsets")
        return tuple(ref.strip() for ref in raw.split(",") if ref.strip())

    @classmethod
    def standup(cls, manifest: Path | str, *, repo: Path | str | None = None) -> McpHost:
        resolved = Path(repo).resolve() if repo is not None else Path(__file__).resolve().parents[2]
        refs = cls.from_refs((), repo=str(resolved), project=str(resolved)).refs_from_manifest(
            Path(manifest)
        )
        if not refs:
            from installation.installer import Installer

            refs = tuple(Installer(repo=resolved).collect_toolsets())
        try:
            return cls.from_refs(refs, repo=str(resolved), project=str(resolved))
        except Exception as error:
            raise McpStandupFailed("standup", None, str(error), error) from error

    @classmethod
    def from_refs(
        cls,
        toolset_refs: tuple[str, ...],
        *,
        constructor_context: dict[str, object] | None = None,
        repo: str | None = None,
        project: str | None = None,
    ) -> McpHost:
        runtime = McpServer(repo=repo, project=project)
        if toolset_refs:
            runtime.start(toolset_refs, constructor_context=constructor_context)
        host = cls(runtime)
        host.notify_exceptions()
        return host

class UxNode:
    """Subclasses declare `_semantic_type_name` so cross-format nodes translate cleanly."""

    _semantic_type_name: str = "UxNode"

    def __init__(self, name: str, sequential_order: int) -> None:
        self.name = name
        self.sequential_order = sequential_order

    def semantic_type(self) -> str:
        return self._semantic_type_name

    def translate_from(self, source: "UxNode") -> UpdateReport:
        if self.semantic_type() != source.semantic_type():
            raise TranslationError(
                f"Cannot translate from {source.semantic_type()} into {self.semantic_type()}"
            )
        report = UpdateReport()
        self.update_self(source)
        for pair in self.child_collections(source):
            self._reconcile_collection(pair, report)
        return report

    def update_self(self, source: "UxNode") -> None:
        raise NotImplementedError(f"{type(self).__name__} must implement update_self")

    def child_collections(self, source: "UxNode") -> List[ChildCollectionPair]:
        raise NotImplementedError(f"{type(self).__name__} must implement child_collections")

    def children(self) -> List["UxNode"]:
        result: List[UxNode] = []
        try:
            for pair in self.child_collections(self):
                result.extend(pair.self_children)
        except NotImplementedError:
            pass
        return result

    def snapshot_fields(self) -> dict:
        return {}

    def _reconcile_collection(self, pair: ChildCollectionPair, report: UpdateReport) -> None:
        self._consumed_ids: set = set()
        reconciled: List[UxNode] = []

        for source_child in pair.source_children:
            match = self._find_match(source_child, pair.self_children)
            if match is not None:
                self._consumed_ids.add(id(match))
                match.translate_from(source_child)
                reconciled.append(match)
                report.add_exact_match(match.name)
            else:
                new_child = pair.load(source_child)
                new_child.translate_from(source_child)
                reconciled.append(new_child)
                report.add_new(new_child, parent_name=self.name)

        for existing in pair.self_children:
            if id(existing) not in self._consumed_ids:
                report.add_removed(existing, parent_name=self.name)

        pair.self_children[:] = reconciled

    def _find_match(
        self,
        source: "UxNode",
        candidates: List["UxNode"],
    ) -> Optional["UxNode"]:
        for candidate in candidates:
            if id(candidate) not in self._consumed_ids and candidate.name == source.name:
                return candidate
        for candidate in candidates:
            if (
                id(candidate) not in self._consumed_ids
                and candidate.sequential_order == source.sequential_order
            ):
                return candidate
        return None

    def _renumber(self, nodes: List["UxNode"]) -> None:
        for index, node in enumerate(nodes):
            node.sequential_order = index

