class CrossLayerNamingScanner(TypeScriptScanner):
    """Check that domain method names are consistent across all layers."""

    RULE = "cross-layer-method-naming"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []

        for domain_path in self._find_domain_packages(root):
            violations += self._check_domain(domain_path)

        return violations

    def _check_domain(self, domain_path: Path) -> List[Violation]:
        violations: List[Violation] = []

        shared_methods = self._extract_shared_methods(domain_path)
        if not shared_methods:
            return violations

        server_methods = self._extract_server_methods(domain_path)
        http_functions = self._extract_http_functions(domain_path)

        for method in shared_methods:
            base = method.lower()
            if base in _CRUD_GENERICS:
                continue

            if server_methods and method not in server_methods:
                for srv_method in server_methods:
                    if srv_method.lower() in _CRUD_GENERICS and base not in _CRUD_GENERICS:
                        violations.append(
                            self.v(
                                f"Domain method '{method}' in domain core has no matching "
                                f"server method. Server uses CRUD-generic "
                                f"'{srv_method}' instead. Rename to '{method}'.",
                                str(domain_path / "server.ts"),
                                severity="warning",
                            )
                        )
                        break

            if http_functions and method not in http_functions:
                for fn in http_functions:
                    if fn.startswith("fetch") and method in fn.lower():
                        violations.append(
                            self.v(
                                f"Domain method '{method}' in domain core has no matching "
                                f"HTTP client function. Client uses 'fetch'-prefixed "
                                f"'{fn}' instead. Rename to '{method}'.",
                                str(self._client_file(domain_path) or domain_path / "client.tsx"),
                                severity="warning",
                            )
                        )
                        break

        return violations

    def _extract_shared_methods(self, domain_path: Path) -> Set[str]:
        methods: Set[str] = set()
        core = self._domain_core_file(domain_path)
        if core is None:
            return methods
        content = self._read_file_content(core)
        if content is None:
            return methods
        for m in _METHOD_RE.finditer(content):
            name = m.group(1)
            if name[0].islower() and not name.startswith("constructor"):
                methods.add(name)
        return methods

    def _extract_server_methods(self, domain_path: Path) -> Set[str]:
        methods: Set[str] = set()
        server = self._server_file(domain_path)
        if server is None:
            return methods
        content = self._read_file_content(server)
        if content is None:
            return methods
        for m in _METHOD_RE.finditer(content):
            name = m.group(1)
            if name[0].islower() and not name.startswith("constructor"):
                methods.add(name)
        return methods

    def _extract_http_functions(self, domain_path: Path) -> Set[str]:
        fns: Set[str] = set()
        client = self._client_file(domain_path)
        if client is None:
            return fns
        content = self._read_file_content(client)
        if content is None:
            return fns
        for m in _EXPORT_FUNCTION_RE.finditer(content):
            fns.add(m.group(1))
        return fns

class _FrameworkPlacement:
    package: str
    allowed_tier: str

class _DeclaredDeps:
    names: Set[str]

    def is_undeclared(self, pkg: str) -> bool:
        if pkg in _NODE_BUILTINS:
            return False
        scoped = pkg.startswith("@") and pkg.count("/") == 1
        bare = not pkg.startswith("@")
        return (scoped or bare) and pkg not in self.names

class DependencyDeclarationsScanner(TypeScriptScanner):
    """Checks that every external import is declared in package.json."""

    RULE = "include-all-external-dependencies"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        project_root = root

        root_deps = self._load_all_deps(project_root / "package.json")
        violations += self._check_root_dev_deps(project_root, root_deps)

        for domain_path in self._find_domain_packages(project_root):
            for tier in ("shared", "server", "client"):
                tier_dir = domain_path / tier
                if not tier_dir.exists():
                    continue
                tier_deps = self._load_all_deps(tier_dir / "package.json")
                all_deps = root_deps | tier_deps
                violations += self._check_tier_imports(tier_dir, all_deps)
                violations += self._check_tier_restrictions(
                    _TierScan(tier_dir, tier, domain_path.name)
                )

        return violations

    # ------------------------------------------------------------------ #
    # package.json loading                                                 #
    # ------------------------------------------------------------------ #

    def _load_all_deps(self, pkg_json_path: Path) -> Set[str]:
        """Load all dep names from a package.json (deps + devDeps + peerDeps)."""
        if not pkg_json_path.exists():
            return set()
        try:
            data = json.loads(pkg_json_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return set()
        deps: Set[str] = set()
        for key in ("dependencies", "devDependencies", "peerDependencies"):
            deps.update(data.get(key, {}).keys())
        return deps

    # ------------------------------------------------------------------ #
    # Root dev dependencies check                                          #
    # ------------------------------------------------------------------ #

    def _check_root_dev_deps(self, project_root: Path, root_deps: Set[str]) -> List[Violation]:
        violations: List[Violation] = []
        pkg_json = project_root / "package.json"

        if not (project_root / "tests").exists():
            return violations

        for pkg, desc in _REQUIRED_DEV_DEPS.items():
            if pkg not in root_deps:
                violations.append(
                    self.v(f"Root package.json is missing '{pkg}' in devDependencies. {desc}.", str(pkg_json))
                )

        return violations

    # ------------------------------------------------------------------ #
    # Import vs. declaration cross-check                                   #
    # ------------------------------------------------------------------ #

    def _check_tier_imports(self, tier_dir: Path, all_deps: Set[str]) -> List[Violation]:
        violations: List[Violation] = []
        for ts_file in self.source_files(tier_dir):
            violations.extend(self._undeclared_imports_in(ts_file, _DeclaredDeps(all_deps)))
        return violations

    def _undeclared_imports_in(self, ts_file: Path, deps: _DeclaredDeps) -> List[Violation]:
        parsed_root = self.parse_file(ts_file)
        if parsed_root is None:
            return []
        violations: List[Violation] = []
        for imp in self.imports:
            hit = self._undeclared_package_hit(
                _ImportSite(ts_file, imp.source, imp.start_line), deps
            )
            if hit is not None:
                violations.append(hit)
        return violations

    def _undeclared_package_hit(self, site: _ImportSite, deps: _DeclaredDeps):
        pkg = self._extract_package_name(site.source)
        if pkg is None or not deps.is_undeclared(pkg):
            return None
        imported = site.source if pkg.startswith("@") else pkg
        return self.v(
            f"'{site.path.name}' imports '{imported}' but "
            f"'{pkg}' is not declared in any package.json. "
            "Add it to the appropriate package.json "
            "dependencies.",
            str(site.path),
            site.start_line,
        )

    def _extract_package_name(self, source: str) -> Optional[str]:
        """Extract the npm package name from an import source string."""
        if source.startswith(".") or source.startswith("/"):
            return None  # relative import
        if source.startswith("node:"):
            return None  # explicit node built-in
        if "/" in source and not source.startswith("@"):
            return source.split("/")[0]
        if source.startswith("@") and "/" in source:
            parts = source.split("/")
            return f"{parts[0]}/{parts[1]}"
        return source

    # ------------------------------------------------------------------ #
    # Framework tier restriction checks                                    #
    # ------------------------------------------------------------------ #

    def _check_tier_restrictions(self, scan: _TierScan) -> List[Violation]:
        violations: List[Violation] = []
        for pkg, allowed_tier in _TIER_RESTRICTIONS.items():
            if scan.tier == allowed_tier:
                continue
            violations.extend(
                self._forbidden_framework_imports(scan, _FrameworkPlacement(pkg, allowed_tier))
            )
        return violations

    def _forbidden_framework_imports(
        self, scan: _TierScan, placement: _FrameworkPlacement
    ) -> List[Violation]:
        violations: List[Violation] = []
        for ts_file in self.source_files(scan.directory):
            parsed_root = self.parse_file(ts_file)
            if parsed_root is None or not self.has_import_from(placement.package):
                continue
            violations.append(
                self.v(
                    f"'{scan.domain_name}/{scan.tier}/{ts_file.name}' imports "
                    f"'{placement.package}' which must only be used in "
                    f"'{placement.allowed_tier}/'. "
                    "This is a layer purity violation.",
                    str(ts_file),
                )
            )
        return violations

class Destination:
    """Base annotation to define the installation destination of a tool."""

    flag = ""

    def annotate(self, fn: Callable[..., Any]) -> Callable[..., Any]:
        setattr(fn, self.flag, True)
        name = getattr(self, "name", None)
        if name is not None:
            setattr(fn, f"{self.flag}_name", name)
        return fn

    def __call__(self, fn: Callable[..., Any]) -> Callable[..., Any]:
        return self.annotate(fn)

class DrawIOClass(DiagramClass):
    """Draw.io UML class cell."""

    def html(self) -> str:
        name_html = html.escape(self.display_name())
        stereo = self._stereotype_html()
        return (
            f'<p style="margin:0px;margin-top:4px;text-align:center;">'
            f'{stereo}<b>{name_html}</b></p><hr size="1"/>'
            f'<p style="margin:0px;margin-left:4px;font-size:10px;">{self._properties_html()}</p>'
            f'<hr size="1"/>'
            f'<p style="margin:0px;margin-left:4px;font-size:10px;">{self._operations_html()}</p>'
        )

    def style(self) -> str:
        return CLASS_STYLE

    def _properties_html(self) -> str:
        bits = ''.join(
            (
                f"+ {html.escape(p.name)}"
                f"{(': ' + html.escape(p.type_hint) if p.type_hint else '')}<br/>"
                for p in self.properties
            )
        )
        return bits or '<br/>'

    def _operations_html(self) -> str:
        bits = ''.join(
            (
                f"{('- ' if op.name.startswith('_') else '+ ')}"
                f"{html.escape(op.name)}({', '.join(op.parameters)})"
                f"{(': ' + html.escape(op.return_type) if op.return_type else '')}<br/>"
                for op in self.operations
            )
        )
        return bits or '<br/>'

    def _stereotype_html(self) -> str:
        stereotypes = self.tactical_stereotypes()
        if not stereotypes:
            return ''
        label = ' '.join(stereotypes)
        return f'<i style="font-size:9px;color:#888;">{html.escape(label)}</i><br/>'

class DrawIOModule(DiagramModule):
    """Draw.io rounded modules-view cell."""

    def load_class(self, source: OoadClass) -> DrawIOClass:
        loaded = DrawIOClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def html(self) -> str:
        name_html = html.escape(self.name)
        purpose_html = html.escape(self.purpose_line())
        terms = self.public_terms()
        if not terms:
            return f'<b style="font-size: 14px;">{name_html}</b><br><i>{purpose_html}</i>'
        bullets = self._seam_bullets()
        return (
            f'<b style="font-size: 14px;">{name_html}</b><br><i>{purpose_html}</i>'
            f'<hr>{bullets}'
        )

    def style(self) -> str:
        if self.nested:
            return MODULE_CHILD_STYLE
        return MODULE_STYLE

    def parse_html(self, value: str) -> Tuple[Optional[str], str, List[str]]:
        text = html.unescape(value)
        m = re.search('<b[^>]*>([^<]+)</b>', text, re.IGNORECASE)
        name = m.group(1).strip() if m else None
        if not name:
            return (None, '', [])
        purpose = self._purpose_from_html(text)
        return (name, purpose, self._terms_from_html(text))

    def _seam_bullets(self) -> str:
        shown = self.shown_seam_terms()
        return '<br>'.join((f'\u2022 {html.escape(t)}' for t in shown))

    def _purpose_from_html(self, text: str) -> str:
        im = re.search('<i[^>]*>([^<]*)</i>', text, re.IGNORECASE)
        if im:
            return im.group(1).strip()
        return ''

    def _terms_from_html(self, text: str) -> List[str]:
        terms: List[str] = []
        for bullet in re.findall('[\u2022\\-]\\s*([^<]+)', text):
            term = bullet.strip()
            if term and (not term.startswith('{')):
                terms.append(term)
            elif term.startswith('{') and term.endswith('}'):
                continue
            elif term:
                terms.append(term)
        if terms:
            return terms
        for li in re.findall('<li[^>]*>(?:<[^>]+>)*([^<]+)', text, re.IGNORECASE):
            term = li.strip()
            if term and 'stack' not in term.lower():
                terms.append(term)
        return terms

class MiroClass(DiagramClass):
    """OoadClass as a Mermaid classDiagram block."""

    def mermaid_id(self) -> str:
        identifier = re.sub(r'\W+', '_', self.display_name()).strip('_')
        if identifier and identifier[0].isdigit():
            identifier = f'class_{identifier}'
        return identifier or 'UnnamedClass'

    def mermaid_lines(self) -> List[str]:
        class_id = self.mermaid_id()
        lines = [f'    %% local: {class_id}', f'    class {class_id} {{']
        for stereotype in self.tactical_stereotypes():
            lines.append(f'        <<{stereotype}>>')
        for prop in self.properties:
            lines.append(f"        +{prop.type_hint or 'object'} {prop.name}")
        for operation in self.operations:
            parameters = ', '.join(operation.parameters)
            lines.append(
                f'        +{operation.name}({parameters}) {operation.return_type or "void"}'
            )
        lines.append('    }')
        return lines

class MiroImportedClass(ImportedClass):
    """Dashed-by-convention imported class in a Mermaid classDiagram."""

    def mermaid_id(self) -> str:
        identifier = re.sub(r'\W+', '_', self.display_name()).strip('_')
        if identifier and identifier[0].isdigit():
            identifier = f'class_{identifier}'
        return identifier or 'UnnamedClass'

    def mermaid_lines(self) -> List[str]:
        class_id = self.mermaid_id()
        lines = [f'    %% imported: {class_id}', f'    class {class_id} {{']
        lines.append(f'        <<from {self.from_module}>>')
        for stereotype in self.tactical_stereotypes():
            lines.append(f'        <<{stereotype}>>')
        for prop in self.key_properties():
            lines.append(f"        +{prop.type_hint or 'object'} {prop.name}")
        lines.append('    }')
        return lines

class MiroModule(DiagramModule):
    """Module as a Mermaid flowchart node or subgraph."""

    def load_class(self, source: OoadClass) -> MiroClass:
        loaded = MiroClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def mermaid_id(self) -> str:
        return re.sub(r'[^a-zA-Z0-9]', '_', self.name)

    def mermaid_label(self) -> str:
        parts = [self.name]
        if self.description.strip():
            parts.append(self.purpose_line())
        terms = self.public_terms()
        if terms:
            parts.append('---')
            parts.extend(f'\u2022 {term}' for term in terms)
        return '\\n'.join(parts)

class DiagramStoryMap:
    """Wraps a canonical StoryMap and exposes positions/dimensions per node."""

    def __init__(self, story_map: StoryMap):
        self._story_map = story_map

    @classmethod
    def create(cls) -> "DiagramStoryMap":
        return cls(StoryMap())

    @property
    def story_map(self) -> StoryMap:
        return self._story_map

    @property
    def epics(self) -> List[Epic]:
        return self._story_map.epics

    def append_epic(self, epic: Epic) -> None:
        self._story_map.append_epic(epic)

    def remove_epic(self, name: str) -> Epic:
        return self._story_map.remove_epic(name)

    def max_sub_epic_depth(self) -> int:
        deepest = 0
        for epic in self._story_map.epics:
            for sub in epic.sub_epics:
                deepest = max(deepest, self._depth_from(sub, current=0))
        return deepest

    def epic_row_y(self) -> int:
        return 0

    def sub_epic_row_y(self, depth: int) -> int:
        return (depth + 1) * ROW_HEIGHT

    def actor_row_y(self) -> int:
        return (self.max_sub_epic_depth() + 2) * ROW_HEIGHT

    def story_row_y(self) -> int:
        return (self.max_sub_epic_depth() + 3) * ROW_HEIGHT

    def epic_width(self, epic: Epic) -> int:
        if not epic.sub_epics:
            return BASE_WIDTH
        return sum(self.sub_epic_width(s) for s in epic.sub_epics)

    def sub_epic_width(self, sub_epic: SubEpic) -> int:
        # diagram_span_columns already counts own stories + nested children
        return BASE_WIDTH * max(sub_epic.diagram_span_columns(), 1)

    def epic_x(self, epic: Epic) -> int:
        offset = 0
        for candidate in self._story_map.epics:
            if candidate is epic:
                return offset
            offset += self.epic_width(candidate)
        raise KeyError(f"Epic {epic.name!r} not part of this diagram")

    def sub_epic_x(self, sub_epic: SubEpic) -> int:
        for epic in self._story_map.epics:
            self._sub_epic_search_base_x = self.epic_x(epic)
            x = self._find_sub_epic_x(sub_epic, epic.sub_epics)
            if x is not None:
                return x
        raise KeyError(f"SubEpic {sub_epic.name!r} not part of this diagram")

    def sub_epic_y(self, sub_epic: SubEpic) -> int:
        return self.sub_epic_row_y(self.sub_epic_depth(sub_epic))

    def sub_epic_depth(self, sub_epic: SubEpic) -> int:
        for epic in self._story_map.epics:
            self._sub_epic_search_depth = 0
            depth = self._depth_of(sub_epic, epic.sub_epics)
            if depth is not None:
                return depth
        raise KeyError(f"SubEpic {sub_epic.name!r} not part of this diagram")

    def story_x(self, story: Story) -> int:
        parent = self._parent_sub_epic_of_story(story)
        return self.sub_epic_x(parent)

    def story_y(self, story: Story) -> int:
        return self.story_row_y()

    def actor_y(self) -> int:
        return self.actor_row_y()

    def place_child_under_parent(self, child, parent) -> None:
        # WHY: single guard on all invalid placements - every rejection leaf
        # collapses to a check on the type pair (parent, child).
        if isinstance(parent, Story):
            raise PlacementError("Stories cannot have child nodes")
        if isinstance(parent, SubEpic) and isinstance(child, Epic):
            raise PlacementError("An Epic cannot live under a SubEpic")
        if isinstance(parent, Story) and isinstance(child, SubEpic):
            raise PlacementError("A SubEpic cannot live under a Story")
        if child is None or parent is None:
            raise PlacementError("Both child and parent are required")
        if isinstance(child, Epic) and parent is not None and not isinstance(
            parent, StoryMap
        ):
            raise PlacementError("An Epic can only sit under the Story Map itself")

    def _depth_from(self, sub_epic: SubEpic, current: int) -> int:
        if not sub_epic.sub_epics:
            return current
        return max(self._depth_from(s, current + 1) for s in sub_epic.sub_epics)

    def _find_sub_epic_x(self, target: SubEpic, siblings: List[SubEpic]) -> Optional[int]:
        offset = self._sub_epic_search_base_x
        for sibling in siblings:
            if sibling is target:
                return offset
            saved = self._sub_epic_search_base_x
            self._sub_epic_search_base_x = offset
            inner = self._find_sub_epic_x(target, sibling.sub_epics)
            if inner is not None:
                return inner
            self._sub_epic_search_base_x = saved
            offset += self.sub_epic_width(sibling)
        return None

    def _depth_of(self, target: SubEpic, siblings: List[SubEpic]) -> Optional[int]:
        depth = self._sub_epic_search_depth
        for sibling in siblings:
            if sibling is target:
                return depth
            self._sub_epic_search_depth = depth + 1
            inner = self._depth_of(target, sibling.sub_epics)
            if inner is not None:
                return inner
            self._sub_epic_search_depth = depth
        return None

    def _all_sub_epics_recursive(
        self, siblings: Iterable[SubEpic]
    ) -> Iterable[SubEpic]:
        for sibling in siblings:
            yield sibling
            yield from self._all_sub_epics_recursive(sibling.sub_epics)

    def _parent_sub_epic_of_story(self, story: Story) -> SubEpic:
        for epic in self._story_map.epics:
            for sub in self._all_sub_epics_recursive(epic.sub_epics):
                if story in sub.stories:
                    return sub
        raise KeyError(f"Story {story.name!r} not part of this diagram")

class DistinctAnchorPointsScanner(DrawioScanner):
    RULE = "distinct-anchor-points"

    def scan_page(self, page_root) -> list:
        anchors = self._check_shared_anchors(page_root)
        return [
            self.violation(
                f"[{self._scan_page_name}] {cls_name} {side}: {len(descs)} edges share "
                f"default anchor - {', '.join(descs)}",
                location=str(self._scan_file_path),
            )
            for cls_name, side, descs in anchors
        ]

class MERNScanner(Scanner):
    """Base class for domain-first MERN architecture scanners.

    Concrete scanners override ``scan(self, root, files)`` (project-wide
    checks - package structure, cross-file naming) or ``scan_file`` (one file
    at a time, via the inherited ``Scanner.scan`` loop).
    """

    RULE: str = ""

    def v(
        self,
        message: str,
        location: str = "",
        line: int = 0,
        severity: str = "error",
    ) -> Violation:
        """Old-world shorthand for ``self.violation(...)`` - kept so ported
        scanner bodies need no call-site changes beyond the base class."""
        return self.violation(message, location=location, line=line, severity=severity)

    def _find_domain_packages(self, project_root: Path) -> List[Path]:
        """Domain dirs under packages/ — either top-level or nested inside a
        feature package (e.g. ``packages/wires/recipients/``). A domain dir
        has the three-file layout (``<domain>.ts``, ``<domain>-server.ts``,
        ``<domain>-client.tsx``) or legacy ``shared/`` / ``client/`` /
        ``server/`` folders. Excludes composition roots."""
        packages_dir = project_root / "packages"
        if not packages_dir.exists():
            return []

        excluded = {"node_modules"}
        domain_packages: List[Path] = []

        def consider(path: Path) -> None:
            if self._is_domain_dir(path) and path not in domain_packages:
                domain_packages.append(path)

        for child in packages_dir.iterdir():
            if not child.is_dir():
                continue
            if child.name in excluded or child.name.startswith("."):
                continue
            consider(child)
            # Feature packages nest domain modules one level down
            # (packages/wires/recipients/).
            if self._domain_core_file(child) is None:
                for nested in child.iterdir():
                    if not nested.is_dir() or nested.name.startswith("."):
                        continue
                    if nested.name in {"node_modules", "dist", "build"}:
                        continue
                    consider(nested)
        return domain_packages

    def _is_domain_dir(self, path: Path) -> bool:
        if self._domain_core_file(path) is not None and (
            self._server_file(path) is not None or self._client_file(path) is not None
        ):
            return True
        return any((path / tier).is_dir() for tier in ("shared", "client", "server"))

    def _domain_core_file(self, domain_path: Path) -> Path | None:
        """``<domain>.ts`` — framework-free domain core (was shared/)."""
        candidates = [
            domain_path / f"{domain_path.name}.ts",
            domain_path / f"{domain_path.name.rstrip('s')}.ts",
        ]
        for path in candidates:
            if path.is_file():
                return path
        for path in sorted(domain_path.glob("*.ts")):
            name = path.name
            if name in {"index.ts", "app.ts", "serve.ts", "main.ts"}:
                continue
            if name.endswith("-server.ts"):
                continue
            if name.endswith(".test.ts") or name.endswith(".spec.ts"):
                continue
            if name.endswith("-client.ts"):
                continue
            return path
        return None

    def _server_file(self, domain_path: Path) -> Path | None:
        """``<domain>-server.ts`` (not feature-package ``serve.ts`` / ``app.ts``)."""
        singular = domain_path.name.rstrip("s")
        for name in (
            f"{singular}-server.ts",
            f"{domain_path.name}-server.ts",
        ):
            path = domain_path / name
            if path.is_file():
                return path
        matches = sorted(domain_path.glob("*-server.ts"))
        return matches[0] if matches else None

    def _client_file(self, domain_path: Path) -> Path | None:
        """``<domain>-client.tsx`` (or legacy ``client.tsx``)."""
        singular = domain_path.name.rstrip("s")
        for name in (
            f"{singular}-client.tsx",
            f"{singular}-client.ts",
            f"{domain_path.name}-client.tsx",
            f"{domain_path.name}-client.ts",
            "client.tsx",
            "client.ts",
        ):
            path = domain_path / name
            if path.is_file():
                return path
        matches = sorted(domain_path.glob("*-client.tsx")) + sorted(
            domain_path.glob("*-client.ts")
        )
        return matches[0] if matches else None

    def _find_tier_files(self, domain_path: Path, tier: str, pattern: str = "*.ts") -> List[Path]:
        """Files for one tier. Prefers the three-file layout; falls back to
        legacy ``<tier>/`` directories."""
        if tier in ("shared", "domain", "core"):
            core = self._domain_core_file(domain_path)
            return [core] if core is not None else []
        if tier == "server":
            server = self._server_file(domain_path)
            if server is not None:
                return [server]
        if tier == "client":
            client = self._client_file(domain_path)
            if client is not None:
                return [client]
        tier_dir = domain_path / tier
        if not tier_dir.exists():
            return []
        return list(tier_dir.glob(pattern))

    def _find_test_folders(self, project_root: Path) -> List[Path]:
        """Lowest-level sub-epic test folders under tests/."""
        tests_dir = project_root / "tests"
        if not tests_dir.exists():
            return []

        sub_epic_folders = []
        for epic_dir in tests_dir.iterdir():
            if not epic_dir.is_dir() or epic_dir.name.startswith("."):
                continue
            for sub_epic_dir in epic_dir.rglob("*"):
                if not sub_epic_dir.is_dir():
                    continue
                has_test_files = any(
                    f.name.endswith((".test.ts", ".test.tsx", ".spec.ts"))
                    for f in sub_epic_dir.iterdir()
                    if f.is_file()
                )
                if has_test_files:
                    sub_epic_folders.append(sub_epic_dir)
        return sub_epic_folders

    def _read_file_content(self, file_path: Path) -> Optional[str]:
        try:
            return file_path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            return None

class DomainStructureScanner(LERNScanner):
    """Checks domain packages have <domain>.ts + <domain>-server.ts + <domain>-client.tsx."""

    RULE = "organize-by-domain-module"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        project_root = root

        domain_packages = self._find_domain_packages(project_root)

        if not domain_packages:
            packages_dir = project_root / "packages"
            if packages_dir.exists():
                violations.append(
                    self.v(
                        "No domain packages found under packages/. "
                        "Expected at least one domain folder with "
                        "<domain>.ts, <domain>-server.ts, and <domain>-client.tsx.",
                        str(packages_dir),
                    )
                )
            return violations

        for domain_path in domain_packages:
            domain_name = domain_path.name
            singular = domain_name.rstrip("s")

            if self._domain_core_file(domain_path) is None:
                violations.append(
                    self.v(
                        f"Domain '{domain_name}' is missing required "
                        f"'{domain_name}.ts' (domain core).",
                        str(domain_path),
                    )
                )

            if not (domain_path / "package.json").exists():
                violations.append(
                    self.v(
                        f"Domain '{domain_name}' is missing required "
                        "file 'package.json'.",
                        str(domain_path),
                    )
                )

            if self._server_file(domain_path) is None:
                violations.append(
                    self.v(
                        f"Domain '{domain_name}' is missing required "
                        f"'{singular}-server.ts' (server tier).",
                        str(domain_path),
                    )
                )

            if self._client_file(domain_path) is None:
                violations.append(
                    self.v(
                        f"Domain '{domain_name}' is missing required "
                        f"'{singular}-client.tsx' (client tier with views).",
                        str(domain_path),
                    )
                )

        return violations

class DotMarkup:
    def id_of(self, node_id: str) -> str:
        return self.quoted(node_id)

    def label_of(self, node: Node) -> str:
        semantic = node.semantic_type()
        practice = getattr(node, 'practice', '')
        name = self.display_name(node)
        if practice:
            return self.quoted(f'{semantic}\\n{name}\\n({practice})')
        return self.quoted(f'{semantic}\\n{name}')

    def display_name(self, node: Node) -> str:
        name = getattr(node, 'name', '') or type(node).__name__
        if len(name) > 72:
            return name[:69] + '...'
        return name

    def quoted(self, value: str) -> str:
        escaped = (
            value.replace('\\', '\\\\')
            .replace('"', '\\"')
            .replace('\n', '\\n')
            .replace('\r', '')
        )
        return f'"{escaped}"'

