class DrawioUxMap(UxMap):
    def parse(self, content: str) -> UxMap:
        stripped = content.strip()
        if stripped.startswith("{"):
            return JsonUxMap.create().parse(stripped)
        return self._parse_mxfile(stripped)

    def render(self, ux_map: UxMap) -> str:
        """Render Detailed IA + Site Map through the vendored drawio-ux CLI."""
        if not _CLI.is_file():
            raise FileNotFoundError(f"drawio-ux CLI missing: {_CLI}")
        with tempfile.TemporaryDirectory(prefix="ux-drawio-") as tmp:
            tmp_path = Path(tmp)
            out_path = tmp_path / "information-architecture.drawio"
            state_path = tmp_path / "state.json"
            state = ux_map_to_cli_state(ux_map, str(out_path))
            state_path.write_text(json.dumps(state, indent=2), encoding="utf-8")
            result = subprocess.run(
                ["node", str(_CLI), "write", str(out_path), str(state_path)],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode != 0 or not out_path.is_file():
                raise RuntimeError(
                    "drawio-ux write failed:\n"
                    f"{result.stdout}\n{result.stderr}"
                )
            return out_path.read_text(encoding="utf-8")

    @classmethod
    def from_workspace(cls, root: Path) -> Optional[UxMap]:
        root = Path(root)
        loader = cls.create()
        for candidate in (
            root / ".context" / "information-architecture.drawio",
            root / ".context" / "ia.drawio",
            root / "information-architecture.drawio",
            root / "ia.drawio",
            root / "site-map.drawio",
        ):
            if candidate.is_file():
                return loader.parse(candidate.read_text(encoding="utf-8"))
        matches = sorted((root / ".context").glob("*.drawio")) if (root / ".context").is_dir() else []
        matches += sorted(root.glob("*.drawio"))
        if matches:
            return loader.parse(matches[0].read_text(encoding="utf-8"))
        return None

    def _parse_mxfile(self, text: str) -> UxMap:
        ux_map = type(self).create()
        try:
            root_el = ET.fromstring(text)
        except ET.ParseError:
            ux_map.context.notes.append("drawio parse failed - invalid XML")
            return ux_map

        site_map = self._diagram_by_name(root_el, "Site Map")
        detailed = self._diagram_by_name(root_el, "Detailed IA")
        source = site_map if site_map is not None else root_el
        self._id_to_screen = self._append_site_screens(ux_map, source)
        if detailed is not None:
            self._append_detailed_regions(ux_map, detailed)
        self._append_transitions(ux_map, source)
        return ux_map

    def _append_site_screens(self, ux_map: UxMap, source: ET.Element) -> dict[str, Screen]:
        id_to_screen: dict[str, Screen] = {}
        for cell in source.iter("mxCell"):
            if cell.get("vertex") != "1" or cell.get("parent") != "1":
                continue
            name = self._strip_html(cell.get("value", ""))
            if not name or self._is_annotation(name):
                continue
            screen = Screen(name, len(ux_map.screens))
            ux_map.append_screen(screen)
            id_to_screen[cell.get("id", "")] = screen
        return id_to_screen

    def _append_detailed_regions(self, ux_map: UxMap, detailed: ET.Element) -> None:
        name_to_screen = {screen.name: screen for screen in ux_map.screens}
        detailed_ids: dict[str, Screen] = {}
        for cell in detailed.iter("mxCell"):
            if cell.get("vertex") != "1" or cell.get("parent") != "1":
                continue
            title = self._strip_html(cell.get("value", ""))
            if title in name_to_screen:
                detailed_ids[cell.get("id", "")] = name_to_screen[title]
        for cell in detailed.iter("mxCell"):
            parent = cell.get("parent", "")
            if cell.get("vertex") != "1" or parent not in detailed_ids:
                continue
            if "strokeColor=none" in cell.get("style", ""):
                continue
            region_name = self._strip_html(cell.get("value", ""))
            if not region_name or self._is_annotation(region_name):
                continue
            screen = detailed_ids[parent]
            if any(region.name == region_name for region in screen.regions):
                continue
            screen.append_region(Region(region_name, len(screen.regions)))

    def _append_transitions(self, ux_map: UxMap, source: ET.Element) -> None:
        for cell in source.iter("mxCell"):
            if cell.get("edge") != "1":
                continue
            src = self._id_to_screen.get(cell.get("source", ""))
            tgt = self._id_to_screen.get(cell.get("target", ""))
            if src is None or tgt is None:
                continue
            trigger = self._strip_html(cell.get("value", "")) or f"{src.name} -> {tgt.name}"
            self._edge_src = src
            self._edge_tgt = tgt
            self._append_edge_transitions(ux_map, trigger)

    def _append_edge_transitions(self, ux_map: UxMap, trigger: str) -> None:
        src = self._edge_src
        tgt = self._edge_tgt
        if " / " not in trigger:
            ux_map.transitions.append(
                Transition(
                    trigger,
                    len(ux_map.transitions),
                    from_screen=src.name,
                    to_screen=tgt.name,
                    trigger=trigger,
                )
            )
            return
        left, right = [part.strip() for part in trigger.split(" / ", 1)]
        ux_map.transitions.append(
            Transition(
                left,
                len(ux_map.transitions),
                from_screen=src.name,
                to_screen=tgt.name,
                trigger=left,
            )
        )
        ux_map.transitions.append(
            Transition(
                right,
                len(ux_map.transitions),
                from_screen=tgt.name,
                to_screen=src.name,
                trigger=right,
            )
        )

    def _diagram_by_name(self, root_el: ET.Element, name: str) -> Optional[ET.Element]:
        for diagram in root_el.findall("diagram"):
            if diagram.get("name") == name:
                return diagram
        return None

    def _is_annotation(self, name: str) -> bool:
        lower = name.lower()
        return lower.startswith("stories:") or "domain terms:" in lower

    def _strip_html(self, value: str) -> str:
        plain = re.sub(r"<[^>]+>", " ", value or "")
        return html.unescape(re.sub(r"\s+", " ", plain)).strip()

class EdgesApproachPerpendicularScanner(DrawioScanner):
    RULE = 'edges-approach-perpendicular'

    def scan_page(self, page_root) -> list:
        return [self.violation(f'[{self._scan_page_name}] {desc}: {end} segment goes {actual} but anchor is on the {side} side (expected {expected})', location=str(self._scan_file_path)) for desc, end, side, expected, actual in self._check_edges_approach_perpendicular(page_root)]

    def _classify_edge(self, style: str) -> str:
        style = (style or '').lower()
        if 'endarrow=block' in style and 'startarrow=block' not in style:
            if 'endfill=0' in style:
                return 'inheritance-orthogonal' if 'orthogonal' in style else 'inheritance'
            return 'association'
        if 'startarrow=diamondthin' in style or 'startarrow=diamond' in style:
            return 'composition' if 'startfill=1' in style else 'aggregation'
        return 'association'

    def _anchor_side(self, frac_x: float | None, frac_y: float | None) -> str | None:
        if frac_x is None or frac_y is None:
            return None
        if abs(frac_x - 0) < 0.001:
            return 'left'
        if abs(frac_x - 1) < 0.001:
            return 'right'
        if abs(frac_y - 0) < 0.001:
            return 'top'
        if abs(frac_y - 1) < 0.001:
            return 'bottom'
        return None

    def _parse_style(self, style: str) -> dict[str, float]:
        out: dict[str, float] = {}
        for kv in (style or '').split(';'):
            if '=' not in kv:
                continue
            key, value = kv.split('=', 1)
            try:
                out[key] = float(value)
            except ValueError:
                continue
        return out

    def _segment_direction(self, seg) -> str | None:
        (x1, y1), (x2, y2) = seg
        dx = abs(x2 - x1)
        dy = abs(y2 - y1)
        if dx < 1 and dy < 1:
            return None
        if dx < 1:
            return 'v'
        if dy < 1:
            return 'h'
        return None

    def _segment_direction_signed(self, seg) -> str | None:
        (x1, y1), (x2, y2) = seg
        dx = x2 - x1
        dy = y2 - y1
        if abs(dx) < 1 and abs(dy) < 1:
            return None
        if abs(dx) >= abs(dy):
            return 'right' if dx > 0 else 'left'
        return 'down' if dy > 0 else 'up'

    def _expected_direction_for_side(self, side: str | None) -> str | None:
        if side in ('left', 'right'):
            return 'h'
        if side in ('top', 'bottom'):
            return 'v'
        return None

    def _outward_direction(self, side: str | None) -> str | None:
        return {'left': 'left', 'right': 'right', 'top': 'up', 'bottom': 'down'}.get(side or '')

    def _inward_direction(self, side: str | None) -> str | None:
        return {'left': 'right', 'right': 'left', 'top': 'down', 'bottom': 'up'}.get(side or '')

    def _check_edges_approach_perpendicular(self, root):
        classes = self._get_all_classes(root)
        self._id_to_name = {cid: name for cid, name, *_ in classes}
        self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        violations = []
        for cell in root.findall('mxCell'):
            self._record_edge_approach(cell, violations)
        return violations

    def _record_edge_approach(self, cell, violations) -> None:
        if cell.get('edge') != '1':
            return
        src_id = cell.get('source', '')
        tgt_id = cell.get('target', '')
        if src_id not in self._id_to_name or tgt_id not in self._id_to_name:
            return
        style = cell.get('style', '')
        attrs = self._parse_style(style)
        segs, _ = self._compute_edge_segments_ex(cell, self._id_to_geo)
        if not segs:
            return
        etype = self._classify_edge(style)
        desc = f'{self._id_to_name[src_id]}->{self._id_to_name[tgt_id]} ({etype})'
        self._approach_desc = desc
        self._approach_end = 'source'
        self._approach_side = self._anchor_side(attrs.get('exitX'), attrs.get('exitY'))
        self._append_end_approach(violations, segs[0])
        self._approach_end = 'target'
        self._approach_side = self._anchor_side(attrs.get('entryX'), attrs.get('entryY'))
        self._append_end_approach(violations, segs[-1])

    def _append_end_approach(self, violations, seg) -> None:
        side = self._approach_side
        end = self._approach_end
        desc = self._approach_desc
        expected = self._expected_direction_for_side(side)
        actual = self._segment_direction(seg)
        if expected and actual and (actual != expected):
            violations.append((desc, end, side, expected, actual))
            return
        want = self._outward_direction(side) if end == 'source' else self._inward_direction(side)
        got = self._segment_direction_signed(seg)
        if want and got and (got != want):
            violations.append((desc, end, side, want, got))

class EdgesDoNotCrossClassesScanner(DrawioScanner):
    RULE = "edges-do-not-cross-classes"

    def scan_page(self, page_root) -> list:
        crossings = self._check_edges_crossing_classes(page_root)
        # Definitive only - approximate auto-router guesses are warnings elsewhere.
        definitive = [
            (edge, cls) for edge, cls in crossings if "(approx)" not in edge
        ]
        return [
            self.violation(
                f"[{self._scan_page_name}] Edge {edge} crosses through {cls}",
                location=str(self._scan_file_path),
            )
            for edge, cls in definitive
        ]

class EdgesDoNotCrossOtherEdgesScanner(DrawioScanner):
    RULE = 'edges-do-not-cross-other-edges'

    def scan_page(self, page_root) -> list:
        classes = self._get_all_classes(page_root)
        id_to_name = {cid: name for cid, name, *_ in classes}
        id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
        edges = [c for c in page_root.findall('mxCell') if c.get('edge') == '1']
        edge_segs = [(ec, self._compute_edge_segments(ec, id_to_geo)) for ec in edges]
        crossings = []
        for i, (ec_a, segs_a) in enumerate(edge_segs):
            for j in range(i + 1, len(edge_segs)):
                ec_b, segs_b = edge_segs[j]
                shared = {ec_a.get('source'), ec_a.get('target')} & {ec_b.get('source'), ec_b.get('target')}
                found = False
                for sa in segs_a:
                    for sb in segs_b:
                        crossed, pt = self._segments_cross(sa, (sb, 2))
                        if not crossed:
                            continue
                        if shared and pt is not None:
                            skip = False
                            for sid in shared:
                                geo = id_to_geo.get(sid)
                                if not geo:
                                    continue
                                gx, gy, gw, gh = geo
                                if abs(pt[0] - (gx + gw / 2)) < gw / 2 + 5 and abs(pt[1] - (gy + gh / 2)) < gh / 2 + 5:
                                    skip = True
                                    break
                            if skip:
                                continue
                        crossings.append((self._describe_edge(ec_a, id_to_name), self._describe_edge(ec_b, id_to_name), f'cross at ~({int(pt[0])},{int(pt[1])})'))
                        found = True
                        break
                    if found:
                        break
        return [self.violation(f'[{self._scan_page_name}] {desc_a} crosses {desc_b}: {detail}', location=str(self._scan_file_path)) for desc_a, desc_b, detail in crossings]

    def _segments_cross(self, seg_a, _rest):
        seg_b, endpoint_tol = _rest
        (ax1, ay1), (ax2, ay2) = seg_a
        (bx1, by1), (bx2, by2) = seg_b
        a_horiz = abs(ay2 - ay1) < 2
        a_vert = abs(ax2 - ax1) < 2
        b_horiz = abs(by2 - by1) < 2
        b_vert = abs(bx2 - bx1) < 2
        if a_horiz and b_vert:
            y = (ay1 + ay2) / 2
            x = (bx1 + bx2) / 2
            a_lo_x, a_hi_x = sorted((ax1, ax2))
            b_lo_y, b_hi_y = sorted((by1, by2))
            if a_lo_x + endpoint_tol < x < a_hi_x - endpoint_tol and b_lo_y + endpoint_tol < y < b_hi_y - endpoint_tol:
                return (True, (x, y))
        if a_vert and b_horiz:
            x = (ax1 + ax2) / 2
            y = (by1 + by2) / 2
            a_lo_y, a_hi_y = sorted((ay1, ay2))
            b_lo_x, b_hi_x = sorted((bx1, bx2))
            if a_lo_y + endpoint_tol < y < a_hi_y - endpoint_tol and b_lo_x + endpoint_tol < x < b_hi_x - endpoint_tol:
                return (True, (x, y))
        return (False, None)

    def _describe_edge(self, edge_cell, id_to_name):
        src = id_to_name.get(edge_cell.get('source', ''), '?')
        tgt = id_to_name.get(edge_cell.get('target', ''), '?')
        return f'{src} -> {tgt}'

class EdgesDoNotOverlapEdgesScanner(DrawioScanner):
    RULE = "edges-do-not-overlap-edges"

    def scan_page(self, page_root) -> list:
