class PythonStoryMap(CodeStoryMap):
    LEAF_EXTENSION = "_story.test.py"
    LANGUAGE_LINE_COMMENT = "#"

    def _make_story_map(self) -> _PythonStoryMap:
        return _PythonStoryMap()

    def _make_epic(self, name: str, order: int) -> PythonEpic:
        return PythonEpic(name, order)

    def _make_sub_epic(self, name: str, order: int) -> PythonSubEpic:
        return PythonSubEpic(name, order)

    def render(
        self,
        canonical: StoryMap,
        previous: Optional[Dict[str, str]] = None,
    ) -> Dict[str, str]:
        tree = PythonTree().render(canonical, self.tests_root)
        if previous:
            for path, body in list(tree.items()):
                if path in previous and path.endswith(self.LEAF_EXTENSION):
                    tree[path] = self._preserve_hand_written(previous[path], body)
        return tree

    def leaf_files_of(self, tree: Dict[str, str]) -> List[str]:
        return sorted(p for p in tree if p.endswith(self.LEAF_EXTENSION))

    def _epic_helper_path(self, epic_root: str, epic: Epic) -> str:
        from practices.stories.model.code_story_map import to_snake

        return f"{epic_root}/{to_snake(epic.name)}_helper.py"

    def _render_epic_helper(self, epic: Epic) -> Optional[str]:
        return None

    def _render_leaf_file(self, sub_epic: SubEpic, owning_epic: Epic) -> str:
        raise NotImplementedError("PythonStoryMap.render uses PythonTree")

    def parse(self, external: Dict[str, str]) -> StoryMap:
        if not isinstance(external, dict):
            raise CodeStoryMapError("Python story map parse expects a path->content dict")
        story_map = self._make_story_map()
        for path, content in sorted(external.items()):
            if not path.endswith(self.LEAF_EXTENSION):
                continue
            parts = path.strip("/").split("/")
            if parts and parts[0] == self.tests_root:
                parts = parts[1:]
            if len(parts) < 4:
                continue
            epic_slug = parts[0]
            story_slug = parts[-2]
            sub_slugs = parts[1:-2]
            if not sub_slugs:
                continue
            epic = self._ensure_epic(story_map, epic_slug)
            sub = self._ensure_sub_path(epic, sub_slugs)
            story = self._parse_story_file(content, story_slug)
            if story is not None:
                sub.stories.append(story)
        return story_map

    def _ensure_epic(self, story_map: StoryMap, epic_slug: str) -> Epic:
        for epic in story_map.epics:
            if to_kebab(epic.name) == epic_slug:
                return epic
        epic = self._make_epic(epic_slug.replace("-", " ").title(), len(story_map.epics) + 1)
        story_map.append_epic(epic)
        return epic

    def _ensure_sub_path(self, epic: Epic, sub_slugs: List[str]) -> SubEpic:
        parent_subs = epic.sub_epics
        current: SubEpic | None = None
        for slug in sub_slugs:
            found = next((s for s in parent_subs if to_kebab(s.name) == slug), None)
            if found is None:
                found = self._make_sub_epic(
                    slug.replace("-", " ").title(), len(parent_subs) + 1
                )
                parent_subs.append(found)
            current = found
            parent_subs = found.sub_epics
        assert current is not None
        return current

    def _parse_story_file(self, content: str, story_slug: str) -> Story | None:
        name_match = re.search(r"^Story:\s*(.+)$", content, re.MULTILINE)
        story_name = (
            name_match.group(1).strip()
            if name_match
            else story_slug.replace("-", " ").title()
        )
        story_name = re.sub(r"\s*\(tier-neutral\)\.?\s*$", "", story_name).strip()
        story = Story(story_name, 1)
        actor_match = re.search(r"^Actor:\s*(.+)$", content, re.MULTILINE)
        if actor_match:
            story.users = [actor_match.group(1).strip()]
        domain_match = re.search(r"^Domain terms:\s*(.+)$", content, re.MULTILINE)
        if domain_match:
            story.domain_terms = [t.strip() for t in domain_match.group(1).split(",") if t.strip()]
        for i, sc_name in enumerate(
            re.findall(r"SCENARIO:\s*(.+)", content), start=1
        ):
            story.scenarios.append(Scenario(name=sc_name.strip(), sequential_order=i))
        return story

class VocabularyHelper:
    AGENT_SUFFIXES = ["er", "or", "ar", "ant", "ent"]
    GERUND_SUFFIX = "ing"

    def _has_synsets(self, word: str, pos) -> bool:
        try:
            word_lower = word.lower()
            synsets = wn.synsets(word_lower, pos=pos)
            return len(synsets) > 0
        except Exception as error:
            print(f"Warning: WordNet synsets failed for {word}: {error}", file=sys.stderr)
            return False

    def is_verb(self, word: str) -> bool:
        return self._has_synsets(word, wn.VERB)

    def is_noun(self, word: str) -> bool:
        return self._has_synsets(word, wn.NOUN)

    def is_agent_noun(self, word: str) -> Tuple[bool, Optional[str], Optional[str]]:
        word_lower = word.lower()

        for suffix in self.AGENT_SUFFIXES:
            if word_lower.endswith(suffix) and len(word_lower) > len(suffix) + 2:
                base = word_lower[: -len(suffix)]

                if self.is_verb(base):
                    return (True, base, suffix)

                if suffix == "er" or suffix == "or":
                    base_with_e = base + "e"
                    if self.is_verb(base_with_e):
                        return (True, base_with_e, suffix)

        return (False, None, None)

    def is_gerund(self, word: str) -> Tuple[bool, Optional[str]]:
        word_lower = word.lower()

        if not word_lower.endswith(self.GERUND_SUFFIX):
            return (False, None)

        if len(word_lower) <= len(self.GERUND_SUFFIX) + 2:
            return (False, None)

        base = word_lower[: -len(self.GERUND_SUFFIX)]

        if self.is_verb(base):
            return (True, base)

        base_with_e = base + "e"
        if self.is_verb(base_with_e):
            return (True, base_with_e)

        if len(base) > 1 and base[-1] == base[-2]:
            base_single = base[:-1]
            if self.is_verb(base_single):
                return (True, base_single)

        return (False, None)

    def pos_tags(self, text: str) -> List[Tuple[str, str]]:
        try:
            tokens = word_tokenize(text)
            tokens = [t for t in tokens if t.isalnum() or any(c.isalnum() for c in t)]
            return pos_tag(tokens)
        except Exception as error:
            print(f"Warning: POS tagging failed: {error}", file=sys.stderr)
            return []

    def is_verb_tag(self, tag: str) -> bool:
        verb_tags = ["VB", "VBP", "VBZ", "VBD", "VBG", "VBN"]
        return tag in verb_tags

    def is_noun_tag(self, tag: str) -> bool:
        noun_tags = ["NN", "NNS", "NNP", "NNPS"]
        return tag in noun_tags

    def is_proper_noun_tag(self, tag: str) -> bool:
        proper_noun_tags = ["NNP", "NNPS"]
        return tag in proper_noun_tags

    def is_actor_or_role(self, word: str) -> bool:
        try:
            return self._hypernym_is_actor(word.lower())
        except Exception as error:
            print(f"Warning: actor check failed for {word}: {error}", file=sys.stderr)
            return False

    def _hypernym_is_actor(self, word_lower: str) -> bool:
        synsets = wn.synsets(word_lower)
        if not synsets:
            return False
        for synset in synsets:
            hypernyms = set()
            for path in synset.hypernym_paths():
                hypernyms.update(path)
            for hypernym in hypernyms:
                name = hypernym.name().split(".")[0]
                if name in ["person", "user", "system", "agent", "entity", "causal_agent"]:
                    return True
        return False

