class FileInstallation(Installation):
    """Write skill, command, and rules markdown files."""

    channel = "markdown"

    def __init__(
        self,
        ide: str,
        path: Path | str,
        destination: str = "",
        mcp_mode: bool = False,
        repo: Path | str | None = None,
    ) -> None:
        super().__init__(ide, path, repo=repo)
        self.destination = destination
        self.mcp_mode = mcp_mode

    def relative_path(
        self, destination: str, toolset: Any, member: Any, name: str | None = None
    ) -> Path:
        name = name or getattr(member, "__name__", "tool")
        folder = self.folder_for(toolset)
        op = self._op_slug(name)
        if destination == "skill":
            return Path("skills") / self._skill_folder(toolset, op) / "SKILL.md"
        if destination == "command":
            base = Path("prompts") if self.ide == "VS Code" else Path("commands")
            return base / self._command_folder(toolset, folder) / f"{self._command_stem(toolset, op)}.md"
        if destination == "rules":
            kebab = self._kebab_folder(folder)
            if getattr(toolset, "practice_guidance", None) is not None:
                stem = self._command_stem(toolset, kebab.name)
                parent = kebab.parent if kebab.name else kebab
                return Path("rules") / parent / f"{stem}.mdc"
            return Path("rules") / kebab.with_suffix(".mdc")
        return folder / str(name)

    def _op_slug(self, name: str) -> str:
        return re.sub(r"([a-z0-9])([A-Z])", r"\1-\2", name).replace("_", "-").lower()

    def _kebab_folder(self, folder: Path) -> Path:
        parts: list[str] = []
        for part in folder.parts:
            if part in {"/", "\\"} or (len(part) == 2 and part.endswith(":")):
                parts.append(part)
            else:
                parts.append(self._op_slug(part))
        return Path(*parts) if parts else folder

    def _command_folder(self, toolset: Any, folder: Path) -> Path:
        kebab = self._kebab_folder(folder)
        if getattr(toolset, "practice_guidance", None) is not None:
            return kebab.parent if kebab.name else kebab
        return kebab

    def _command_stem(self, toolset: Any, op: str) -> str:
        if getattr(toolset, "practice_guidance", None) is not None:
            slug = getattr(toolset, "slug", None)
            if slug:
                return self._op_slug(str(slug))
        return op

    def _skill_ops(self, toolset: Any) -> list[str]:
        bag = getattr(toolset, "tools", None) or {}
        values = bag.values() if isinstance(bag, dict) else bag
        names: list[str] = []
        for tool in values:
            if not getattr(tool, "install_to_skill", False):
                continue
            names.append(self._op_slug(getattr(tool, "deploy_name", None) or tool.name))
        return names

    def _skill_folder(self, toolset: Any, op: str) -> Path:
        folder = self._kebab_folder(self.folder_for(toolset))
        if getattr(toolset, "practice_guidance", None) is not None:
            slug = getattr(toolset, "slug", None)
            if slug:
                parent = folder.parent if folder.name else folder
                return parent / self._op_slug(str(slug))
        if op in {"instructions", "rules-markdown"}:
            return folder
        last = folder.name
        if len(self._skill_ops(toolset)) > 1:
            return folder / op
        if op == last:
            return folder
        return folder / op

    def _body_for(self, kind: str, tool: Any, toolset: Any) -> str:
        if self.mcp_mode:
            return tool.docstring
        try:
            result = getattr(toolset, tool.name, None)
        except Exception:
            return tool.docstring
        if isinstance(result, str) and result.strip():
            return result.strip()
        if kind == "rules":
            markdown = getattr(result, "markdown", None)
            if isinstance(markdown, str) and markdown.strip():
                return markdown.strip()
            format_rules = getattr(result, "format_rules", None)
            if callable(format_rules):
                return str(format_rules()).strip()
        return tool.docstring

    def _fidelity_one_liner(self, child: Any) -> str:
        name = getattr(child, "name", "") or ""
        overview = (getattr(child, "overview", None) or "").strip()
        summary = ""
        for line in overview.splitlines():
            stripped = line.strip()
            if stripped and not stripped.startswith("#") and not stripped.startswith("**"):
                summary = stripped
                break
        return f"{name} — {summary}" if summary else name

    def _fidelity_invoke_parts(self, toolset: Any) -> list[str]:
        entries = getattr(getattr(toolset, "fidelities", None), "entries", None) or {}
        parts: list[str] = []
        for _name, child in entries.items():
            member = getattr(type(child), "instructions", None)
            getter = getattr(member, "fget", member)
            invoke = (
                f"Use MCP tool: `{getattr(child, 'slug', '')}()`"
                if getattr(getter, "_mcp", False)
                else ""
            )
            parts.append(
                "\n\n".join(piece for piece in (self._fidelity_one_liner(child), invoke) if piece)
            )
        return parts

    def render(self, section: str, member: Any, tool: Any | None = None) -> str:
        body = section.rstrip()
        return f"{body}\n" if body else ""

    def write(self, tool: Any) -> None:
        kind = self.destination
        if tool.kind == "tool":
            if kind not in {"skill", "command", "rules"}:
                return
        if not kind:
            return
        member = tool.callable
        toolset = tool.toolset
        parts = [self._body_for(kind, tool, toolset)]
        if self.mcp_mode:
            from harness.mcp.mcp_server import McpOperationDefinition

            fidelity_parts = (
                self._fidelity_invoke_parts(toolset)
                if tool.name == "instructions"
                else []
            )
            if fidelity_parts:
                parts.extend(fidelity_parts)
            else:
                parts.append(McpOperationDefinition.from_tool(tool).invoke_line())
        text = self.render("\n\n".join(p for p in parts if p), member, toolset)
        rel = self.relative_path(kind, toolset, member, tool.deploy_name)
        if kind == "rules":
            from harness.guidance.rule import AppliesTo

            text = AppliesTo.strip_fence(text)
            text = self._rules_front_matter(text, toolset) + text
        elif kind == "skill":
            text = self._skill_front_matter(rel.parent.name, self._skill_overview(toolset, parts)) + text
        dest = self.path / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(text, encoding="utf-8")
        self.track_write(dest)

    def _skill_overview(self, toolset: Any, parts: list[str]) -> str:
        raw = getattr(toolset, "overview", None)
        source = raw.strip() if isinstance(raw, str) and raw.strip() else (parts[0] if parts else "")
        return self._without_mcp_invoke(source)

    def _without_mcp_invoke(self, text: str) -> str:
        lines = [
            line
            for line in text.splitlines()
            if not line.strip().lower().startswith("use mcp tool:")
        ]
        return "\n".join(lines).strip()

    def _skill_front_matter(self, name: str, overview: str) -> str:
        description = overview.strip() or name
        return f"---\nname: {name}\n{self._folded_yaml_field('description', description)}---\n\n"

    def _folded_yaml_field(self, key: str, value: str) -> str:
        indented = "\n".join(f"  {line}" if line else "  " for line in value.splitlines())
        return f"{key}: >-\n{indented}\n"

    def _rules_front_matter(self, body: str, toolset: Any = None) -> str:
        description = "Practice rules."
        for line in body.splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("#") or stripped.startswith("-"):
                continue
            if stripped.startswith("```"):
                continue
            description = stripped.replace('"', "'")
            break
        applies = getattr(getattr(toolset, "rules", None), "appliesTo", None)
        always_apply = True
        globs = ""
        if applies is not None:
            globs = getattr(applies, "globs", "") or ""
            flagged = getattr(applies, "always_apply", None)
            if flagged is not None:
                always_apply = bool(flagged)
            elif globs:
                always_apply = False
        lines = [
            "---",
            f"alwaysApply: {'true' if always_apply else 'false'}",
            f'description: "{description}"',
        ]
        if globs:
            lines.append(f"globs: {globs}")
        lines.append("---")
        return "\n".join(lines) + "\n\n"

class McpOperationDefinition:
    mcp_name: str
    kind: str
    tool: Any
    operation: str
    member: Any
    description: str = ""

    @classmethod
    def from_tool(cls, tool: Any) -> McpOperationDefinition:
        kind = "tool" if tool.kind == "tool" else "prompt"
        toolset = tool.toolset
        if getattr(toolset, "practice_guidance", None) is not None:
            mcp_name = tool.slug
        else:
            mcp_name = f"{tool.slug}.{tool.name}"
        return cls(
            mcp_name=mcp_name,
            kind=kind,
            tool=toolset,
            operation=tool.name,
            member=tool.callable,
            description=tool.description,
        )

    def invoke_line(self) -> str:
        try:
            signature = inspect.signature(self.member)
            params = inspect.Signature(
                [p for n, p in signature.parameters.items() if n != "self"]
            )
            suffix = str(params)
        except (TypeError, ValueError):
            suffix = "()"
        return f"Use MCP tool: `{self.mcp_name}{suffix}`"

class Filter:
    def __init__(
        self,
        path: str = "",
        name: str = "",
        node_id: str = "",
        file: str = "",
        practice: str = "",
        practices: list[str] | None = None,
        semantic_type: str = "",
        semantic_types: list[str] | None = None,
        fidelity: str = "",
        stages: list[str] | None = None,
        violations: bool = False,
        rule: str = "",
        rules: list[str] | None = None,
        related_to: "Filter | None" = None,
        relationship_type: str = "",
        relationship_types: list[str] | None = None,
        kind: str = "",
    ) -> None:
        self.path = path
        self.name = name
        self.node_id = node_id
        self.file = file
        self.practice = practice
        self.practices = practices
        self.semantic_type = semantic_type
        self.semantic_types = semantic_types
        self.fidelity = fidelity
        self.stages = stages
        self.violations = violations
        self.rule = rule
        self.rules = rules
        self.related_to = related_to
        self.relationship_type = relationship_type
        self.relationship_types = relationship_types
        self.kind = kind

    @classmethod
    def from_value(cls, value: Any) -> Filter:
        if value in (None, "", {}, []):
            return cls()
        if isinstance(value, cls):
            return value
        if isinstance(value, str):
            stripped = value.strip()
            if stripped.startswith("{"):
                return cls.from_value(json.loads(stripped))
            return cls(path=stripped)
        if not isinstance(value, dict):
            raise TypeError(f"Filter expected an object, got {type(value).__name__}")
        fields = cls()._canonical_fields(value)
        related = fields.get("related_to")
        if related not in (None, "", {}):
            fields["related_to"] = cls.from_value(related)
        allowed = cls.__init__.__code__.co_varnames[1:]
        return cls(**{key: fields[key] for key in fields if key in allowed})

    @property
    def constrains(self) -> bool:
        return bool(
            self.path
            or self.name
            or self.node_id
            or self.file
            or self.practice
            or self.practices
            or self.semantic_type
            or self.semantic_types
            or self.fidelity
            or self.stages
            or self.violations
            or self.rule
            or self.rules
            or self.related_to
            or self.relationship_type
            or self.relationship_types
            or self.kind
        )

    def scope(self) -> Filter:
        return Filter(path=self.path, name=self.name, node_id=self.node_id)

    def without_scope(self) -> Filter:
        fields = dict(self.__dict__)
        fields["path"] = ""
        fields["name"] = ""
        fields["node_id"] = ""
        allowed = self.__init__.__code__.co_varnames[1:]
        return Filter(**{key: fields[key] for key in allowed if key in fields})

    def _canonical_fields(self, value: dict) -> dict:
        fields: dict[str, Any] = {}
        for key, raw in value.items():
            fields[_ALIASES.get(key, key)] = raw
        return fields

    def listed(self, keys: tuple[str, ...]) -> list[str] | None:
        values: list[str] = []
        for key in keys:
            raw = getattr(self, key, None)
            if raw in (None, "", [], ()):
                continue
            if isinstance(raw, (list, tuple)):
                values.extend(str(item) for item in raw if str(item).strip())
            else:
                values.append(str(raw))
        return values or None

    def matches(self, node: Any) -> bool:
        if not self._match_path(node):
            return False
        if not self._match_identity(node):
            return False
        if not self._match_source(node):
            return False
        if not self._match_related(node):
            return False
        return self._match_rules(node)

    def expand_ids(self, seeds: Iterable[str], graph: Any) -> set[str]:
        seed_ids = {node_id for node_id in seeds if node_id in graph.nodes}
        keep = set(seed_ids)
        for node_id in seed_ids:
            node = graph.nodes[node_id]
            for ancestor in node.ancestors():
                keep.add(ancestor.node_id)
            for child in node.descendants():
                keep.add(child.node_id)
            for other in node.incident():
                keep.add(other.node_id)
        return keep

    def subtree_ids(self, seeds: Iterable[str], graph: Any) -> set[str]:
        seed_ids = {node_id for node_id in seeds if node_id in graph.nodes}
        keep = set(seed_ids)
        for node_id in seed_ids:
            for child in graph.nodes[node_id].descendants():
                keep.add(child.node_id)
        return keep

    def _match_path(self, node: Any) -> bool:
        path = str(self.path or "").strip()
        if not path:
            return True
        keys = [part.strip().casefold() for part in path.split(".") if part.strip()]
        hits = {item.node_id for item in self._nodes_along(node.graph, keys)}
        return node.node_id in hits

    def _match_identity(self, node: Any) -> bool:
        names = self.listed(("name",))
        if names and self._name_key(node) not in {item.casefold() for item in names}:
            return False
        if self.node_id and node.node_id != str(self.node_id):
            return False
        practices = self.listed(("practices", "practice"))
        if practices and (getattr(node, "practice", "") or "") not in practices:
            return False
        types = self.listed(("semantic_types", "semantic_type"))
        if types and node.semantic_type() not in types:
            return False
        stages = self.listed(("stages", "fidelity"))
        stage = getattr(node, "fidelity", None) or getattr(node, "stage", "") or ""
        if stages and stage not in stages:
            return False
        return True

    def _match_source(self, node: Any) -> bool:
        file = str(self.file or "").replace("\\", "/").casefold()
        if not file:
            return True
        src = str(getattr(getattr(node, "source", None), "file", "") or "").replace("\\", "/")
        return file in src.casefold()

    def _match_related(self, node: Any) -> bool:
        kinds = self.listed(("relationship_types", "relationship_type"))
        if kinds and not node.has_kind(kinds):
            return False
        related = self.related_to
        if related is None:
            return True
        others = node.incident()
        kind = str(related.kind or related.relationship_type or "")
        if kind:
            others = [item for item in others if self._edge_kind(node, item) == kind]
        return any(related.matches(item) for item in others)

    def _match_rules(self, node: Any) -> bool:
        hits = list(node.graph.violations_for(node))
        rules = self.listed(("rules", "rule"))
        if self.violations in _TRUE:
            if not hits:
                return False
            if rules:
                return any(hit.rule_slug in rules for hit in hits)
            return True
        if not rules:
            return True
        if any(hit.rule_slug in rules for hit in hits):
            return True
        names = list(getattr(node, "applicable_rules", None) or [])
        return any(slug in names for slug in rules)

    def _nodes_along(self, graph: Any, keys: list[str]):
        if not keys:
            return list(graph.nodes.values())
        current = [node for node in graph.nodes.values() if self._key_matches(node, keys[0])]
        for key in keys[1:]:
            current = [
                child
                for node in current
                for child in node.children()
                if self._key_matches(child, key)
            ]
        return current

    def _key_matches(self, node: Any, key: str) -> bool:
        return self._name_key(node) == key or node.node_id.casefold() == key

    def _name_key(self, node: Any) -> str:
        return str(getattr(node, "name", "") or node.semantic_type()).casefold()

    def _edge_kind(self, node: Any, other: Any) -> str:
        for edge in node.graph.edges_at(node):
            if edge.from_node is other or edge.to_node is other:
                return edge.kind
        return ""

class NodeWalk:
    """Walk ownership and incident edges from this node."""

    def children(self) -> List["Node"]:
        owned = self.related(Kind.OWNS)
        return owned if owned else self.related()

    def ancestors(self) -> List["Node"]:
        found: List[Node] = []
        current: Node = self
        for _ in range(16):
            parents = current.related(Kind.BELONGS_TO) or current.related(
                Kind.OWNS, direction="in"
            )
            if not parents:
                break
            current = parents[0]
            found.append(current)
        return found

    def descendants(self) -> List["Node"]:
        found: List[Node] = []
        stack = list(self.children())
        seen = {self.node_id}
        while stack:
            child = stack.pop()
            if child.node_id in seen:
                continue
            seen.add(child.node_id)
            found.append(child)
            stack.extend(child.children())
        return found

    def incident(self) -> List["Node"]:
        return self.related() + self.related(direction="in")

    def has_kind(self, kinds: list[str]) -> bool:
        names = set(kinds)
        return any(edge.kind in names for edge in self.graph.edges_at(self))

    def matches_source(self, file: str, line: int) -> bool:
        src = getattr(self, "source", None)
        node_file = str(getattr(src, "file", "") or "").replace("\\", "/")
        if not node_file or line <= 0:
            return False
        hit = file.replace("\\", "/")
        if not (
            node_file.endswith(hit)
            or hit.endswith(node_file)
            or node_file.split("/")[-1] == hit.split("/")[-1]
        ):
            return False
        start = int(getattr(src, "line", 0) or 0)
        end = int(getattr(src, "end_line", 0) or start)
        if start <= 0:
            return False
        return start <= line <= max(end, start)

    def owner_class(self):
        for kind in (Kind.BELONGS_TO, Kind.OWNS):
            for other in self.related(kind):
                if other.semantic_type() == "OoadClass":
                    return other
        for other in self.used_by:
            if other.semantic_type() == "OoadClass":
                return other
        return None

class NodeRelations:
    """Record and read this node's relationships."""

    def relate(self, kind: str, to: "Node") -> Relationship:
        return self.graph.relate(Relationship(kind, self, to))

    def related(self, kind: Optional[str] = None, *, direction: str = "out") -> List["Node"]:
        if direction == "out":
            return self._unique(
                [
                    edge.to_node
                    for edge in self.graph.edges_from(self)
                    if kind is None or edge.kind == kind
                ]
            )
        if direction != "in":
            raise ValueError("direction must be 'out' or 'in'")
        nodes: List[Node] = []
        if kind is None or kind == Kind.USED_BY:
            for source_id in self.graph.users_of(self):
                nodes.append(self.graph.nodes[source_id])
        if kind not in (None, Kind.USED_BY):
            nodes.extend(
                edge.from_node
                for edge in self.graph.edges_to(self)
                if edge.kind == kind
            )
        elif kind is None:
            nodes.extend(edge.from_node for edge in self.graph.edges_to(self))
        return self._unique(nodes)

    def outgoing(self, kind: Optional[str] = None) -> List[tuple]:
        return [
            (edge.kind, edge.to_node)
            for edge in self.graph.edges_from(self)
            if kind is None or edge.kind == kind
        ]

    def invoked_operations(self, *, depth: int = 3) -> List["Node"]:
        self._invoke_found = []
        self._invoke_seen: set[str] = set()
        self._invoke_path: set[str] = set()
        self._walk_invokes(self, depth)
        return self._invoke_found

    def _walk_invokes(self, op: "Node", remaining: int) -> None:
        if remaining <= 0 or op.node_id in self._invoke_path:
            return
        self._invoke_path.add(op.node_id)
        for callee in op.related(Kind.INVOKES):
            if callee.semantic_type() != "Operation":
                continue
            if callee.node_id in self._invoke_seen:
                continue
            self._invoke_seen.add(callee.node_id)
            self._invoke_found.append(callee)
            self._walk_invokes(callee, remaining - 1)
        self._invoke_path.discard(op.node_id)

    def _unique(self, nodes: List["Node"]) -> List["Node"]:
        seen: set[str] = set()
        out: List[Node] = []
        for node in nodes:
            if node.node_id in seen:
                continue
            seen.add(node.node_id)
            out.append(node)
        return out

