class Responsibilities:
    def hits_for_keep_classes(self, hits: Iterable[dict]) -> List[dict]:
        refined: List[dict] = []
        for class_name, tokens_by_operation in self._tokens_by_class(hits).items():
            if not self._mixed_responsibilities(tokens_by_operation):
                continue
            clusters = self._cluster_operations(tokens_by_operation)
            message = (
                f"Class '{class_name}' has {len(tokens_by_operation)} public operations "
                f"whose nouns cluster into {len(clusters)} responsibilities."
            )
            for operation in tokens_by_operation:
                refined.append(
                    {"name": class_name, "message": message, "contributor": operation}
                )
        return refined

    def nouns_in(self, tokens: Iterable[str]) -> Set[str]:
        words = [token.lower() for token in tokens if token]
        nouns: Set[str] = set()
        for index, word in enumerate(words):
            as_noun = bool(wn.synsets(word, wn.NOUN))
            as_verb = bool(wn.synsets(word, wn.VERB))
            if as_verb and (not as_noun or index == 0):
                continue
            if as_noun:
                nouns.add(self._stem_noun(word))
        return nouns

    def _stem_noun(self, token: str) -> str:
        lemma = wn.morphy(token.lower(), wn.NOUN)
        return lemma or token.lower()

    def _cluster_operations(self, tokens_by_operation: Mapping[str, Set[str]]) -> List[Set[str]]:
        parent = {name: name for name in tokens_by_operation}

        def find(name: str) -> str:
            while parent[name] != name:
                parent[name] = parent[parent[name]]
                name = parent[name]
            return name

        def union(left: str, right: str) -> None:
            root_left, root_right = find(left), find(right)
            if root_left != root_right:
                parent[root_right] = root_left

        nouns_by_op = {
            name: self.nouns_in(tokens) for name, tokens in tokens_by_operation.items()
        }
        named = [name for name, nouns in nouns_by_op.items() if nouns]
        for index, left in enumerate(named):
            for right in named[index + 1 :]:
                if nouns_by_op[left] & nouns_by_op[right]:
                    union(left, right)
        clusters: Dict[str, Set[str]] = defaultdict(set)
        for name in named:
            clusters[find(name)].add(name)
        return list(clusters.values())

    def _tokens_by_class(self, hits: Iterable[dict]) -> Dict[str, Dict[str, Set[str]]]:
        by_class: Dict[str, Dict[str, Set[str]]] = defaultdict(lambda: defaultdict(set))
        for hit in hits:
            class_name = hit.get("name") or ""
            operation = hit.get("contributor") or ""
            token = hit.get("message") or ""
            if class_name and operation:
                by_class[class_name][operation].add(token)
        return by_class

    def _mixed_responsibilities(self, tokens_by_operation: Mapping[str, Set[str]]) -> bool:
        if len(tokens_by_operation) <= _MIN_PUBLIC_OPERATIONS:
            return False
        return len(self._cluster_operations(tokens_by_operation)) >= _MIN_NOUN_CLUSTERS

class StoryNames:
    def _words(self, label: str) -> List[str]:
        return [part.lower() for part in (label or "").replace("_", " ").split() if part]

    def rows_for_verb_noun(self, rows: Iterable[dict]) -> List[dict]:
        refined: List[dict] = []
        seen = set()
        for row in rows:
            label = row.get("message") or ""
            if label in seen:
                continue
            words = self._words(label)
            if not words:
                continue
            first = words[0]
            rest = words[1:]
            vocabulary = VocabularyHelper()
            gerund, _ = vocabulary.is_gerund(first)
            verb = vocabulary.is_verb(first)
            noun = any(vocabulary.is_noun(word) for word in rest)
            if len(words) >= 2 and verb and noun and not gerund:
                continue
            seen.add(label)
            refined.append(
                {
                    "name": row.get("name") or "",
                    "message": f"Story '{label}' is not verb-noun format.",
                    "contributor": row.get("contributor") or "",
                }
            )
        return refined

    def rows_for_vague_mechanic(self, rows: Iterable[dict]) -> List[dict]:
        refined: List[dict] = []
        seen = set()
        for row in rows:
            label = row.get("message") or ""
            if label in seen:
                continue
            words = self._words(label)
            if len(words) < 2:
                continue
            first = words[0]
            rest = words[1:]
            if not VocabularyHelper().is_verb(first) or first not in _VAGUE_VERBS:
                continue
            if not any(word in _GENERIC_NOUNS for word in rest):
                continue
            seen.add(label)
            refined.append(
                {
                    "name": row.get("name") or "",
                    "message": f"Story '{label}' does not name a system mechanic.",
                    "contributor": row.get("contributor") or "",
                }
            )
        return refined

class AssetLocator:
    def __init__(
        self,
        instance: Any,
        label: str,
        *,
        group: str | None = None,
        filter_key: str | None = None,
    ) -> None:
        self._instance = instance
        self._label = label
        self._group = group
        self._filter_key = filter_key
        self._module_dir = Path(".")
        self._domain_slug = ""
        self._search_root_path = Path(".")
        self._active_format: str | None = None

    def class_file_directory(self) -> Path:
        instance = self._instance
        practice = getattr(instance, "practice_guidance", None)
        if practice is not None:
            instance = practice
        stored = getattr(instance, "module_dir", None)
        if stored is not None:
            return Path(stored)
        try:
            return Path(inspect.getfile(type(instance))).resolve().parent
        except (TypeError, OSError):
            return Path(".")

    def _active_resource(self, key: str | None) -> str | None:
        if not key:
            return None
        if key == "fidelity":
            return self._current_fidelity()
        value = getattr(self._instance, key, None)
        return str(value) if value else None

    def _current_fidelity(self) -> str | None:
        current = getattr(getattr(self._instance, "fidelities", None), "current", None)
        if current is None:
            value = getattr(self._instance, "fidelity", None)
            return str(value) if value else None
        value = getattr(current, "fidelity", None) or getattr(current, "name", None)
        return str(value) if value else None

    def _fidelity_scope(self) -> str | None:
        """Fidelity section name on Guidance only — not WorkSession.name or AgentToolSet.name."""
        if getattr(self._instance, "practice_guidance", None) is not None:
            value = getattr(self._instance, "name", None)
            return str(value) if value else None
        for cls in type(self._instance).__mro__:
            scoped = self._declared_name_scope(cls)
            if scoped is not _MISSING:
                return scoped
        return None

    def _declared_name_scope(self, cls: type) -> str | None | object:
        if cls is object:
            return _MISSING
        declared = cls.__dict__.get("name", _MISSING)
        if declared is _MISSING:
            return _MISSING
        if isinstance(declared, property):
            return None
        value = getattr(self._instance, "name", None)
        return str(value) if value else None

    @property
    def fidelity(self) -> str | None:
        return self._active_resource("fidelity")

    @property
    def format(self) -> str | None:
        return self._active_resource("format")

    def _stamp(self, location: AssetLocation) -> AssetLocation:
        fidelity = location.fidelity
        if location.kind == "folder":
            fidelity = fidelity or self.fidelity
        return replace(
            location,
            label=self._label,
            fidelity=fidelity,
            format=location.format or self.format,
        )

    def locate(self) -> AssetLocation:
        return self._stamp(self._locate())

    def _locate(self) -> AssetLocation:
        self._module_dir = self.class_file_directory()
        self._domain_slug = self._module_dir.name
        filter_value = self._active_resource(self._filter_key) if self._filter_key else None
        if self._label == "templates":
            return self._locate_template_or_missing(filter_value)
        self._search_root_path = self._search_root(self._module_dir, filter_value)
        return self._locate_under()

    def _locate_template_or_missing(self, filter_value: str | None) -> AssetLocation:
        self._active_format = filter_value or self._active_resource("format")
        located = self._locate_templates()
        if located.path is not None and located.path.is_file():
            return located
        return AssetLocation(
            "file",
            self._module_dir,
            self._domain_slug,
            path=(self._module_dir / ".no-template").resolve(),
        )

    def _search_root(self, module_dir: Path, filter_value: str | None) -> Path:
        root = module_dir
        if self._group:
            root = root / self._group
        if not filter_value:
            return root
        as_dir = root / filter_value
        if as_dir.is_dir():
            return as_dir
        return root

    def _locate_under(self) -> AssetLocation:
        fidelity_name = self._fidelity_scope()
        if fidelity_name:
            return AssetLocation(
                "section",
                self._module_dir,
                self._domain_slug,
                section_file=self._canonical_domain_md().resolve(),
                section_heading=_section_heading(self._label),
                fidelity=str(fidelity_name),
            )
        folder = self._search_root_path / self._label
        if folder.is_dir():
            return AssetLocation("folder", self._module_dir, self._domain_slug, folder=folder.resolve())
        for name in (self._label, f"{self._label}.md"):
            candidate = self._search_root_path / name
            if candidate.is_file():
                return AssetLocation("file", self._module_dir, self._domain_slug, path=candidate.resolve())
        first = self._first_extension_match(self._search_root_path)
        if first:
            return AssetLocation("file", self._module_dir, self._domain_slug, path=first.resolve())
        return AssetLocation(
            "section",
            self._module_dir,
            self._domain_slug,
            section_file=self._canonical_domain_md().resolve(),
            section_heading=_section_heading(self._label),
        )

    def _first_extension_match(self, search_root: Path) -> Path | None:
        if not search_root.is_dir():
            return None
        matches = sorted(c for c in search_root.glob(f"{self._label}.*") if c.is_file())
        return matches[0] if matches else None

    def _canonical_domain_md(self) -> Path:
        for root in (self._module_dir, self._search_root_path):
            found = self._domain_md_in(root)
            if found is not None:
                return found
        return self._module_dir / f"{self._domain_slug}.md"

    def _domain_md_in(self, root: Path) -> Path | None:
        for slug in _slug_variants(self._domain_slug):
            candidate = root / f"{slug}.md"
            if candidate.is_file():
                return candidate
        return None

    def _locate_templates(self) -> AssetLocation:
        fidelity = self._active_resource("fidelity")
        if fidelity:
            located = self._named_template_file(fidelity, practice=False)
            if located is not None:
                return located
        located = self._named_template_file(self._domain_slug, practice=True)
        if located is not None:
            return located
        return AssetLocation(
            "file",
            self._module_dir,
            self._domain_slug,
            path=(self._module_dir / ".no-template").resolve(),
        )

    def _named_template_file(self, name: str, *, practice: bool) -> AssetLocation | None:
        stems = list(_slug_variants(name))
        if practice:
            stems = [
                extra
                for slug in _slug_variants(name)
                for extra in (slug, f"{slug}-templates", f"{slug}-template")
            ]
        self._template_stems = stems
        self._template_ext = _FORMAT_TEMPLATE_EXT.get(self._active_format or "", "")
        for folder in self._template_folders():
            located = self._template_in_folder(folder)
            if located is not None:
                return located
        return None

    def _template_folders(self) -> list[Path]:
        folders: list[Path] = []
        shared = self._module_dir / "templates"
        if self._active_format:
            alias = _FORMAT_DIR_ALIAS.get(self._active_format, self._active_format)
            folders.append(shared / alias)
            folders.append(self._module_dir / "formats" / self._active_format)
        folders.append(shared)
        return folders

    def _template_in_folder(self, folder: Path) -> AssetLocation | None:
        if not folder.is_dir():
            return None
        if self._template_ext:
            return self._template_with_ext(folder)
        return self._template_any_ext(folder)

    def _template_with_ext(self, folder: Path) -> AssetLocation | None:
        for stem in self._template_stems:
            path = folder / f"{stem}{self._template_ext}"
            if path.is_file() and "sketch" not in path.stem.casefold():
                return AssetLocation(
                    "file", self._module_dir, self._domain_slug, path=path.resolve()
                )
        return None

    def _template_any_ext(self, folder: Path) -> AssetLocation | None:
        for stem in self._template_stems:
            for path in sorted(folder.glob(f"{stem}.*")):
                if path.is_file() and "sketch" not in path.stem.casefold():
                    return AssetLocation(
                        "file", self._module_dir, self._domain_slug, path=path.resolve()
                    )
        return None

class SessionPaths:
    """Where files go relative to a workspace path.

    Durable artifacts (sketches, generated markdown, grill-answers) live in
    ``{working_path}/.context/``. Session temps (session.md, handoff, logs) live
    at ``{repository_root}/.sessions/{name}/``. Closed sessions archive to
    ``{repository_root}/.sessions/closed/{name}/``. Those two roots are never the
    same folder.
    """

    def repository_root(self, path: str | Path) -> Path:
        """Git primary clone root for *path*, or *path* itself when not in a repo."""
        found = Repo(path).find_root()
        if found is not None:
            return Path(found)
        return Path(path)

    def sessions_root(self, working_path: str | Path) -> Path:
        """Active session folders: ``{repository_root}/.sessions/``."""
        return self.repository_root(working_path) / ".sessions"

    def legacy_sessions_root(self, working_path: str | Path) -> Path:
        """Pre-migration session root: ``{repository_root}/.context/sessions/``."""
        return self.repository_root(working_path) / ".context" / "sessions"

    def is_session_folder(self, destination: str | Path) -> bool:
        dest = Path(destination)
        if not dest.name or dest.name == "closed":
            return False
        parent = dest.parent
        if parent.name == ".sessions":
            return True
        return parent.name == "sessions" and parent.parent.name == ".context"

    def docs_dir(self, destination: str | Path) -> Path:
        """Durable artifact dir: ``{path}/.context/`` (sketches, generate, grill-answers).

        Never returns a session folder. If *destination* is already ``.context``, a
        session folder, or a mistaken sibling under ``.context``, walk up to that
        ``.context``. Otherwise ``{destination}/.context/``.
        """
        dest = Path(destination)
        if dest.name == ".context":
            return dest
        if dest.name == ".sessions":
            return self.repository_root(dest) / ".context"
        if dest.name == "sessions" and dest.parent.name == ".context":
            return dest.parent
        if self.is_session_folder(dest):
            parent = dest.parent
            if parent.name == "sessions" and parent.parent.name == ".context":
                return parent.parent
            return self.repository_root(dest) / ".context"
        if dest.parent.name == ".context" and dest.name not in ("sessions", ".sessions"):
            return dest.parent
        return dest / ".context"

    def session_dir(self, working_path: str | Path, name: str = "") -> Path:
        """Session temp dir: ``{repository_root}/.sessions/{name}/``.

        *working_path* is the active checkout (primary clone or worktree).
        If *working_path* is already a session folder, return it. Otherwise *name*
        is required.
        """
        dest = Path(working_path)
        if self.is_session_folder(dest):
            return dest
        slug = (name or "").strip()
        if not slug:
            raise ValueError(
                "session name is required when destination is not a session folder"
            )
        return self.sessions_root(dest) / slug

    def migrate_legacy_session_folder(self, repo_root: Path, dest: Path) -> bool:
        """Move ``.context/sessions/{name}/`` to ``.sessions/{name}/`` when present."""
        legacy = self.legacy_sessions_root(repo_root) / dest.name
        if not legacy.is_dir() or dest.exists():
            return False
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(legacy), str(dest))
        return True

class Guidance:
    default_format: str = ""
    name: str | None = None
    domain_slug: str | None = None

    @property
    def registration_name(self) -> str:
        typ = type(self)
        return f"{typ.__module__}:{typ.__name__}"

    @property
    def slug(self) -> str:
        if self.domain_slug:
            return str(self.domain_slug).replace("_", "-")
        return re.sub(r"(?<!^)(?=[A-Z])", "-", type(self).__name__).lower()

    @property
    def install_folder(self) -> Path:
        return AssetLocator(self, "").class_file_directory()

    @property
    def module_dir(self) -> Path:
        try:
            return Path(inspect.getfile(type(self))).resolve().parent
        except (TypeError, OSError):
            return Path(".")

    @markdownCollection("shared rules")
    @rules
    @agent_tool
    def rules(self) -> RulesCollection:
        """Shared rules as a collection."""

    def __init__(
        self,
        format: str | None = None,
        path: str | None = None,
        session: str | None = None,
        workspace: Any = None,
    ) -> None:
        self.format = format if format is not None else self.default_format
        self.path = path
        self.session = session
        self.workspace = workspace

    @markdown
    def overview(self) -> str:
        """Overview section for this Guidance."""

    @markdown
    def guidance(self) -> str:
        """Guidance section body."""

    @markdown
    def templates(self) -> str:
        """Active template file for this Guidance format and fidelity."""

    @property
    @echo
    @skill
    @mcp
    @agent_instructions
    def instructions(self) -> str:
        """overview"""
        return "\n\n".join(
            part
            for part in (
                (self.overview or "").strip(),
                (self.guidance or "").strip(),
                (self.rules.markdown or "").strip(),
                (self.templates or "").strip(),
            )
            if part
        )

class GuidanceCollection(MarkdownCollection, Guidance):
    def __init__(self, entries: dict[str, Guidance] | None = None, parent: Any = None) -> None:
        MarkdownCollection.__init__(self, entries, parent=parent)
        Guidance.__init__(self)
        self.current: Guidance | None = None

    def child_for_stage(self, stage: str) -> Guidance:
        values = self.entries.values() if isinstance(self.entries, dict) else self.entries
        for child in values:
            if getattr(child, "stage", "") == stage:
                return child
        raise KeyError(stage)

    @classmethod
    def child(cls, name: str, body: str = "") -> FidelityGuidance:
        return FidelityGuidance(name=name)

    @collect
    def overview(self) -> str: ...

    @collect
    def guidance(self) -> str: ...

    @collect
    def rules(self) -> RulesCollection: ...

    @collect
    def templates(self) -> str: ...

    @collect
    @echo
    @mcp
    @skill
    @agent_instructions
    def instructions(self) -> str: ...

class PromptEcho:
    """Echo detected action, practice, fidelity, and guideline names on preToolUse."""

    _catalog: ClassVar[list[tuple[str, str]] | None] = None
    _echo_toolsets: ClassVar[list | None] = None

    def __init__(self) -> None:
        self.repo: Path | None = None
        self.toast_roots: list | None = None
        self.echo = ""
        self.toast_stamp = ""
        self.tool_name = ""
        self.echo_kind = ""
        self.echo_label = ""
        self.skill_kind = ""
        self.skill_found: dict[str, str] = {}
        self._begin_tools: dict = {}
        self._begin_toolset = None
        self._toast_dest: Path | None = None

    @property
    def catalog(self) -> list[tuple[str, str]]:
        if type(self)._catalog is not None:
            return type(self)._catalog
        found: dict[str, str] = {}
        skills = _REPO_ROOT / ".cursor" / "skills"
        self.skill_found = found
        self.skill_kind = "action"
        self._walk_skill_tree(skills / "actions")
        self.skill_kind = "practice"
        self._walk_skill_tree(skills / "practices")
        self._walk_rule_tree(_REPO_ROOT / ".cursor" / "rules" / "practices", found)
        for name in _FALLBACK_ACTIONS:
            found.setdefault(name.replace("_", "-"), "action")
        type(self)._catalog = sorted(found.items(), key=lambda item: len(item[0]), reverse=True)
        return type(self)._catalog

    @Hook("preToolUse")
    def on_pre_tool_use(self, hook_payload: dict) -> dict:
        self.install_ide_toast_extension()
        result = self.handle(hook_payload, toolsets=self.echo_toolsets())
        message = result.get("user_message")
        if message:
            self.show_ide_toast(str(message))
        return result

    def handle(self, hook_payload: dict, toolsets: list | None = None) -> dict:
        tool_name = hook_payload.get("tool_name", "")
        if not tool_name:
            return {"permission": "allow"}
        detected = self._detected(hook_payload, toolsets)
        if not detected:
            return {"permission": "allow"}
        kind, label = detected
        self.tool_name = str(tool_name)
        self.echo_kind = kind
        self.echo_label = label
        self._log_echo()
        return {"permission": "allow", "user_message": f"{kind.title()}{_ARROW}{label}"}

    def detect_echo(
        self, hook_payload: dict, toolsets: list | None = None
    ) -> tuple[str, str] | None:
        invoked = self._mcp_tool_name(hook_payload)
        if not invoked:
            return None
        hosts = self._walk_toolsets(
            toolsets if toolsets is not None else self.echo_toolsets()
        )
        for toolset in hosts:
            found = self._echo_on_toolset(invoked, toolset)
            if found is not None:
                return found
        return None

    def detect(self, hook_payload: dict) -> tuple[str, str] | None:
        named = self._yaml_action(hook_payload)
        if named:
            return "action", named
        invoked = self._mcp_tool_name(hook_payload)
        tool_name = str(hook_payload.get("tool_name") or "")
        action_names = {invoked, tool_name}
        return self._catalog_match(self._haystacks(hook_payload), action_names)

    def echo_toolsets(self, repo: Path | None = None) -> list:
        if repo is None and type(self)._echo_toolsets is not None:
            return type(self)._echo_toolsets
        loaded = self._load_echo_toolsets(repo)
        if repo is None:
            type(self)._echo_toolsets = loaded
        return loaded

    def show_ide_toast(self, echo: str) -> Path:
        dest = self._toast_path(self.repo)
        self._toast_dest = dest
        self.echo = echo
        self.toast_stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        message = self._burst_message()
        notice = json.dumps({"message": message, "at": self.toast_stamp}, ensure_ascii=False) + "\n"
        self._write_notice(dest, notice)
        for path in self._toast_destinations(dest):
            self._write_notice(path, notice)
        return dest

    def inject_rules_toast(self, source: str, labels: list[str]) -> str:
        return f"{source}{_ARROW}rules : {', '.join(labels)}"

    def toast_notice(self, echo: str) -> dict[str, str]:
        return {
            "message": echo,
            "at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        }

    def install_ide_toast_extension(self) -> Path:
        source = Path(__file__).resolve().parent / "ide_toast"
        dest = Path.home() / ".cursor" / "extensions" / IDE_TOAST_EXTENSION
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copytree(source, dest, dirs_exist_ok=True)
        return dest

    def _detected(self, hook_payload: dict, toolsets: list | None) -> tuple[str, str] | None:
        if toolsets is not None:
            marked = self.detect_echo(hook_payload, toolsets=toolsets)
            if marked:
                return marked
        return self.detect(hook_payload)

    def _log_echo(self) -> None:
        stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        sys.stderr.write(
            f"{stamp} [prompt-echo] tool={self.tool_name} {self.echo_kind}={self.echo_label}\n"
        )

    def _catalog_match(
        self, haystacks: list[str], action_names: set[str]
    ) -> tuple[str, str] | None:
        for hay in haystacks:
            for token, kind in self.catalog:
                if not self._token_in(hay, token):
                    continue
                if kind == "action" and hay not in action_names:
                    continue
                if "/rules/" in hay.replace("\\", "/").lower():
                    return "guideline", token
                return kind, token
        return None

    def _echo_on_toolset(self, invoked: str, toolset) -> tuple[str, str] | None:
        tools = getattr(toolset, "tools", None) or {}
        if not isinstance(tools, dict):
            return None
        match = next(
            (tool for tool in tools.values() if self._name_matches(invoked, tool)),
            None,
        )
        if match is None:
            return None
        if self._has_echo(match.callable):
            return self._echo_kind_label(match)
        if match.name == "instructions" and self._inherited_echo(toolset, "instructions"):
            return self._echo_kind_label(match)
        self._begin_tools = tools
        self._begin_toolset = toolset
        return self._begin_echo(match)

    def _begin_echo(self, match) -> tuple[str, str] | None:
        begin = self._begin_tools.get("begin")
        if begin is None or match.name in _SKIP_BEGIN_FALLBACK:
            return None
        if not self._has_echo(begin.callable):
            return None
        return "action", str(getattr(self._begin_toolset, "slug", match.name)).replace("_", "-")

    def _load_echo_toolsets(self, repo: Path | None) -> list:
        from installation.installer import Installer
        from harness.agent_tools.agent_tools import AgentToolSet

        installer = Installer(repo=repo or _REPO_ROOT)
        return AgentToolSet.from_items(installer.collect_toolsets(), skip_errors=True)

    def _toast_path(self, repo: Path | None) -> Path:
        root = Path(repo) if repo is not None else _REPO_ROOT
        return root / TOAST_NOTICE

    def _write_notice(self, dest: Path, notice: str) -> None:
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(notice, encoding="utf-8")

    def _toast_destinations(self, primary: Path) -> list[Path]:
        seen = {primary.resolve()}
        extra: list[Path] = []
        for root in self.toast_roots or []:
            dest = Path(str(root)) / TOAST_NOTICE
            try:
                resolved = dest.resolve()
            except OSError:
                continue
            if resolved in seen:
                continue
            seen.add(resolved)
            extra.append(dest)
        return extra

    def _burst_message(self) -> str:
        dest = self._toast_dest
        echo = self.echo
        stamp = self.toast_stamp
        if dest is None or not dest.is_file():
            return echo
        previous = self._read_toast(dest)
        prev_msg = str(previous.get("message") or "")
        prev_at = self._parse_toast_time(str(previous.get("at") or ""))
        now = self._parse_toast_time(stamp)
        if not prev_msg or prev_at is None or now is None:
            return echo
        if abs((now - prev_at).total_seconds()) > _SAME_BURST_SECONDS:
            return echo
        return self._join_arrow_toasts(prev_msg, echo)

    def _read_toast(self, dest: Path) -> dict:
        try:
            previous = json.loads(dest.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError, TypeError):
            return {}
        return previous if isinstance(previous, dict) else {}

    def _compact(self, text: str) -> str:
        stepped = re.sub(r"([a-z0-9])([A-Z])", r"\1-\2", text)
        return re.sub(r"[^a-z0-9]+", "-", stepped.lower()).strip("-")

    def _walk_skill_tree(self, root: Path) -> None:
        if not root.is_dir():
            return
        found = self.skill_found
        top_kind = self.skill_kind
        for child in root.iterdir():
            if not child.is_dir():
                continue
            token = child.name.replace("_", "-")
            found.setdefault(token, top_kind)
            if top_kind != "practice":
                continue
            self._walk_practice_leaves(child)

    def _walk_practice_leaves(self, child: Path) -> None:
        found = self.skill_found
        for leaf in child.iterdir():
            if leaf.is_dir():
                found.setdefault(leaf.name.replace("_", "-"), "fidelity")

    def _walk_rule_tree(self, root: Path, found: dict[str, str]) -> None:
        if not root.is_dir():
            return
        for child in root.iterdir():
            if child.suffix == ".mdc":
                found.setdefault(child.stem.replace("_", "-"), "guideline")
                continue
            if not child.is_dir():
                continue
            found.setdefault(child.name.replace("_", "-"), "guideline")
            for leaf in child.glob("*.mdc"):
                found.setdefault(
                    f"{child.name}-{leaf.stem}".replace("_", "-"),
                    "guideline",
                )

    def _mcp_tool_name(self, hook_payload: dict) -> str:
        name = str(hook_payload.get("tool_name") or "")
        raw = hook_payload.get("tool_input")
        inp = raw if isinstance(raw, dict) else {}
        nested = inp.get("toolName") or inp.get("tool_name") or inp.get("name")
        if isinstance(nested, str) and nested.strip():
            if "mcp" in name.lower() or name in {"CallMcpTool", "call_mcp_tool"}:
                return nested.strip()
            if "." in nested or "-" in nested:
                return nested.strip()
        return name

    def _paths(self, hook_payload: dict) -> list[str]:
        raw = hook_payload.get("tool_input")
        inp = raw if isinstance(raw, dict) else {}
        found: list[str] = []
        for key in ("path", "file_path", "command"):
            value = inp.get(key)
            if isinstance(value, str) and value.strip():
                found.append(value)
        return found

    def _haystacks(self, hook_payload: dict) -> list[str]:
        values = [self._mcp_tool_name(hook_payload), str(hook_payload.get("tool_name") or "")]
        values.extend(self._paths(hook_payload))
        return [item for item in values if item]

    def _token_in(self, hay: str, token: str) -> bool:
        compacted_hay = f"-{self._compact(hay)}-"
        compacted_token = f"-{self._compact(token)}-"
        return compacted_token in compacted_hay

    def _yaml_action(self, hook_payload: dict) -> str | None:
        for text in self._paths(hook_payload):
            match = _YAML_ACTION.search(text)
            if match:
                return match.group(1).replace("_", "-")
        return None

    def _has_echo(self, operation) -> bool:
        target = operation.fget if isinstance(operation, property) else operation
        inner = getattr(target, "__func__", target)
        return bool(getattr(inner, "_echo", False) or getattr(target, "_echo", False))

    def _echo_kind_label(self, tool) -> tuple[str, str]:
        toolset = tool.toolset
        if tool.name == "instructions":
            if getattr(toolset, "practice_guidance", None) is not None:
                return "fidelity", tool.slug
            return "practice", getattr(toolset, "slug", tool.name)
        if tool.name == "begin":
            return "action", getattr(toolset, "slug", tool.name)
        return "action", tool.name.replace("_", "-")

    def _inherited_echo(self, toolset, name: str) -> bool:
        for cls in type(toolset).mro():
            member = cls.__dict__.get(name)
            if member is None:
                continue
            target = member.fget if isinstance(member, property) else member
            if self._has_echo(target):
                return True
        return False

    def _mcp_aliases(self, tool) -> set[str]:
        toolset = tool.toolset
        slug = str(getattr(toolset, "slug", "") or "")
        names = {f"{slug}.{tool.name}", f"{slug}_{tool.name}", tool.name}
        if getattr(toolset, "practice_guidance", None) is not None:
            names.add(tool.slug)
        if tool.name == "instructions" and slug:
            names.add(slug)
            names.add(f"{slug}.instructions")
        return {item for item in names if item}

    def _name_matches(self, invoked: str, tool) -> bool:
        compact_invoked = self._compact(invoked)
        return any(self._compact(name) == compact_invoked for name in self._mcp_aliases(tool))

    def _walk_toolsets(self, toolsets: list) -> list:
        found: list = []
        for toolset in toolsets:
            found.append(toolset)
            for child in getattr(toolset, "child_toolsets", lambda: ())():
                found.append(child)
        return found

    def _parse_toast_time(self, stamp: str) -> datetime | None:
        try:
            return datetime.strptime(stamp, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
        except ValueError:
            return None

    def _guidance_names_from_toast_rest(self, rest: str) -> list[str]:
        text = rest.strip()
        lowered = text.lower()
        if lowered.startswith("rules :") or lowered.startswith("rules:"):
            text = text.split(":", 1)[1]
        names: list[str] = []
        for chunk in text.split(","):
            name = chunk.strip()
            if name.endswith(" rules"):
                name = name[: -len(" rules")].strip()
            if name and name not in names:
                names.append(name)
        return names

    def _join_arrow_toasts(self, previous: str, incoming: str) -> str:
        if incoming in previous:
            return previous
        if _ARROW not in previous or _ARROW not in incoming:
            return f"{previous}; {incoming}"
        prev_src, prev_rest = previous.split(_ARROW, 1)
        inc_src, inc_rest = incoming.split(_ARROW, 1)
        if prev_src.strip() != inc_src.strip():
            return f"{previous}; {incoming}"
        names: list[str] = []
        for name in self._guidance_names_from_toast_rest(
            prev_rest
        ) + self._guidance_names_from_toast_rest(inc_rest):
            if name not in names:
                names.append(name)
        return f"{prev_src.strip()}{_ARROW}rules : {', '.join(names)}"

class Hook(Destination):
    flag = "_hook"
    EVENTS = frozenset(
        {
            "sessionStart",
            "beforeSubmitPrompt",
            "afterAgentResponse",
            "afterAgentThought",
            "stop",
            "sessionEnd",
            "preCompact",
            "preToolUse",
            "postToolUse",
            "postToolUseFailure",
            "beforeReadFile",
            "subagentStart",
        }
    )

    def __new__(cls, fn: Any = None, event: str | None = None):
        if isinstance(fn, str):
            event = fn
            fn = None
        if not event:
            raise ValueError(
                'Hook requires a Cursor event: @Hook("sessionStart") or @Hook(event="sessionStart")'
            )
        if event not in cls.EVENTS:
            raise ValueError(
                f"Unknown Cursor event {event!r}. Valid events: {sorted(cls.EVENTS)}"
            )
        inst = object.__new__(cls)
        inst.name = event
        if callable(fn):
            return inst.annotate(fn)
        return inst

    @classmethod
    def normalize_event(cls, event: str) -> str:
        stepped = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", event)
        return stepped.replace("-", "_").lower()

class HelperMethod:
    def __init__(self, name: str, phase: str, display_text: str) -> None:
        self.name = name
        self.phase = phase
        self.display_text = display_text
        self._seen: Dict[Tuple[str, str], HelperMethod] = {}
        self._ordered: List[HelperMethod] = []

    def strip_md_emphasis(self, value: str) -> str:
        """Strip markdown bold/italic/backtick markers, keeping the inner text."""
        return _BACKTICK.sub(r"\1", _ITALIC.sub(r"\1", _BOLD.sub(r"\1", value)))

    def display_clause_text(self, text: str) -> str:
        """Text for a given()/when()/then() call - strips the And/But continuation
        marker (the call site is already scoped to its phase) and markdown."""
        return self.strip_md_emphasis(_CONTINUATION.sub("", text)).strip()

    def clause_method_name(self, phase: str, text: str) -> str:
        """Mechanical method name: phase + PascalCase(every word in the clause)."""
        cleaned = self.display_clause_text(text)
        words = [w for w in re.split(r"[^0-9A-Za-z]+", cleaned) if w]
        tail = "".join(w[:1].upper() + w[1:].lower() for w in words)
        return f"{phase}{tail}" if tail else phase

    def seam_for_story(self, story) -> Tuple[List["HelperMethod"], MethodLookup]:
        """One HelperMethod per distinct clause across every scenario on `story`."""
        self._seen = {}
        self._ordered = []
        for scenario in getattr(story, "scenarios", None) or []:
            for clause in scenario.given:
                self._add("given", clause.text)
            for interaction in scenario.interactions:
                for clause in interaction.when:
                    self._add("when", clause.text)
                for clause in interaction.then:
                    self._add("then", clause.text)

        def method_for(phase: str, text: str) -> HelperMethod:
            key = (phase, self.display_clause_text(text).lower())
            return self._seen[key]

        return self._ordered, method_for

    def _add(self, phase: str, text: str) -> None:
        display = self.display_clause_text(text)
        key = (phase, display.lower())
        if key in self._seen:
            return
        method = HelperMethod(
            name=self.clause_method_name(phase, text),
            phase=phase,
            display_text=display,
        )
        self._seen[key] = method
        self._ordered.append(method)


    @classmethod
    def from_story(cls, story) -> Tuple[List["HelperMethod"], MethodLookup]:
        return cls("", "", "").seam_for_story(story)

