class HookResult:
    """Fields Cursor reads back from the hook process."""

    def __init__(
        self,
        permission: str = "allow",
        continue_flag: bool | None = None,
        user_message: Any = None,
        agent_message: Any = None,
        followup_message: Any = None,
        additional_context: Any = None,
    ) -> None:
        self.permission = permission
        self.continue_flag = continue_flag
        self.user_message = self._optional_text(user_message)
        self.agent_message = self._optional_text(agent_message)
        self.followup_message = self._optional_text(followup_message)
        self.additional_context = self._optional_text(additional_context)

    def _optional_text(self, value: Any) -> str | None:
        if not value:
            return None
        return str(value)

    @classmethod
    def from_handler(cls, raw: dict[str, Any] | None) -> HookResult:
        if not raw:
            return cls()
        continue_flag = False if raw.get("continue") is False else None
        return cls(
            permission=str(raw.get("permission") or "allow"),
            continue_flag=continue_flag,
            user_message=raw.get("user_message"),
            agent_message=raw.get("agent_message"),
            followup_message=raw.get("followup_message"),
            additional_context=raw.get("additional_context"),
        )

    def with_description(self, description: str) -> HookResult:
        text = description.strip()
        if not text:
            return self
        existing = (self.agent_message or "").strip()
        if existing == text:
            return self
        if existing:
            text = f"{text}\n{existing}"
        return HookResult(
            self.permission,
            self.continue_flag,
            self.user_message,
            text,
            self.followup_message,
            self.additional_context,
        )

    def merge(self, other: HookResult) -> HookResult:
        permission = "deny" if "deny" in (self.permission, other.permission) else "allow"
        continue_flag = False if False in (self.continue_flag, other.continue_flag) else None
        return HookResult(
            permission,
            continue_flag,
            self._join_lines(self.user_message, other.user_message),
            self._join_lines(self.agent_message, other.agent_message),
            other.followup_message or self.followup_message,
            self._join_unique_context(other),
        )

    def _join_lines(self, first: str | None, second: str | None) -> str | None:
        parts = [part for part in (first, second) if part]
        return "\n".join(parts) or None

    def _join_unique_context(self, other: HookResult) -> str | None:
        parts: list[str] = []
        for item in (self.additional_context, other.additional_context):
            if item and item not in parts:
                parts.append(item)
        return "\n\n".join(parts) or None

    def as_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"permission": self.permission}
        if self.continue_flag is False:
            payload["continue"] = False
        if self.user_message:
            payload["user_message"] = self.user_message
        if self.agent_message:
            payload["agent_message"] = self.agent_message
        if self.followup_message:
            payload["followup_message"] = self.followup_message
        if self.additional_context:
            payload["additional_context"] = self.additional_context
        return payload

class HookHandler:
    """One marked operation that may run for an event."""

    def __init__(self, tool: Any, event: CursorEvent, repo_root: Path) -> None:
        self.tool = tool
        self.event = event
        self.operation = tool.name
        self.owner = type(tool.toolset)

    def is_enabled(self) -> bool:
        return not bool(getattr(self.owner, "_hooks_disabled", False))

    def invoke(self, payload: HookPayload) -> HookResult:
        toolset = self.tool.toolset
        operation = self._bound_operation(toolset)
        raw = operation(payload.as_dict())
        result = HookResult.from_handler(raw)
        if result.additional_context or not raw:
            return result
        return result.with_description(self.tool.docstring)

    def _bound_operation(self, toolset: Any) -> Any:
        own = getattr(type(toolset), self.operation, None)
        if callable(own) and getattr(own, "_hook", False):
            bound_own = getattr(toolset, self.operation, None)
            if bound_own is not None:
                return bound_own
        if self.operation == "inject_rules":
            rules = getattr(toolset, "rules", None)
            bound = getattr(rules, "inject_rules", None) if rules is not None else None
            if bound is not None:
                return bound
        return getattr(toolset, self.operation, None) or self.tool.callable

class HandlerCatalog:
    """Loaded AgentToolSets. Hook operations come from ``toolset.tools``."""

    def __init__(
        self,
        toolsets: list[Any] | None = None,
        repo_root: Path | None = None,
        *,
        handlers: Path | str | None = None,
    ) -> None:
        self.repo_root = repo_root
        self.failures: list[tuple[str, BaseException]] = []
        self.toolsets: list[Any] = []
        self._load_items(self._source_items(toolsets, handlers))

    def _source_items(
        self, toolsets: list[Any] | None, handlers: Path | str | None
    ) -> list[Any]:
        if handlers is not None:
            return list(self.refs_from_handlers(handlers))
        if toolsets is None:
            return self._refs_from_file() or self._collect_refs()
        return list(toolsets)

    def _load_items(self, items: list[Any]) -> None:
        for item in items:
            try:
                loaded = AgentToolSet.from_items([item])
            except Exception as error:
                self.failures.append((self.ref_label(item), error))
                continue
            self._append_loaded(loaded)

    def _append_loaded(self, loaded: list[Any]) -> None:
        for instance in loaded:
            if type(instance).__name__ in {"RulesCollection", "FidelityGuidance"}:
                continue
            self.toolsets.append(instance)

    def refs_from_handlers(self, handlers: Path | str) -> tuple[str, ...]:
        path = Path(handlers)
        if not path.is_file():
            return ()
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return ()
        refs: list[str] = []
        for item in payload.get("handlers") or []:
            ref = item.get("ref")
            if ref and str(ref) not in refs:
                refs.append(str(ref))
        return tuple(refs)

    def ref_label(self, item: Any) -> str:
        if isinstance(item, str):
            return item
        if isinstance(item, dict):
            return str(item.get("toolset") or item)
        registration = getattr(item, "registration_name", None)
        if isinstance(registration, str) and registration:
            return registration
        typ = item if isinstance(item, type) else type(item)
        return f"{typ.__module__}:{typ.__name__}"

    def _refs_from_file(self) -> list[str]:
        return list(self.refs_from_handlers((self.repo_root or Path()) / ".cursor" / "hook-handlers.json"))

    def _collect_refs(self) -> list[str]:
        from installation.installer import Installer

        return list(Installer(repo=self.repo_root).collect_toolsets())

    def for_event(self, event: CursorEvent) -> list[HookHandler]:
        handlers: list[HookHandler] = []
        seen: set[tuple[str, str]] = set()
        repo_root = self.repo_root or Path()
        for toolset in self.toolsets:
            try:
                tools = toolset.tools_for(InstallDestination.HOOK)
            except Exception as error:
                self.failures.append((self.ref_label(toolset), error))
                continue
            for tool in tools:
                if getattr(tool.callable, "_hook_name", None) != event.name:
                    continue
                key = (type(toolset).__name__, tool.name)
                if key in seen:
                    continue
                seen.add(key)
                handlers.append(HookHandler(tool, event, repo_root))
        return handlers

class SessionLogs:
    """Active session folder and hook runtime logs under the repo root."""

    ACTIVE = Path(".sessions") / "_active"
    LEGACY_ACTIVE = Path(".context") / "sessions" / "_active"
    DEFAULT_SESSION = "default"
    LEGACY_LOG_PATHS = (
        Path(".context") / "prompt-log.txt",
        Path("installation/hooks/dispatch.debug"),
        Path("harness/hooks/dispatch.debug"),
        Path("installation/hooks/prompt_echo.debug"),
        Path("tools/prompt_echo.debug"),
        Path("tools/prompt_echo/prompt_echo.debug"),
        Path("tools/prompt_log.debug"),
        Path("tools/prompt_log/prompt_log.debug"),
    )

    def __init__(self, repo_root: Path) -> None:
        self.repo_root = repo_root

    def write_active_session(self, name: str) -> None:
        slug = (name or "").strip() or self.DEFAULT_SESSION
        legacy_active = self.repo_root / self.LEGACY_ACTIVE
        if legacy_active.is_file():
            legacy_active.unlink()
        path = self.repo_root / self.ACTIVE
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(slug, encoding="utf-8")
        self.session_folder(slug).mkdir(parents=True, exist_ok=True)
        self.logs_dir_for(slug).mkdir(parents=True, exist_ok=True)

    def clear_active_session(self) -> None:
        path = self.repo_root / self.ACTIVE
        if path.is_file():
            path.unlink()

    def active_session_name(self) -> str:
        for rel in (self.ACTIVE, self.LEGACY_ACTIVE):
            path = self.repo_root / rel
            if path.is_file():
                text = path.read_text(encoding="utf-8").strip()
                if text:
                    return text
        return self.DEFAULT_SESSION

    def session_folder(self, name: str) -> Path:
        slug = (name or "").strip() or self.DEFAULT_SESSION
        dest = self.repo_root / ".sessions" / slug
        legacy = self.repo_root / ".context" / "sessions" / slug
        if legacy.is_dir() and not dest.exists():
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(legacy), str(dest))
        return dest

    def logs_dir_for(self, name: str) -> Path:
        return self.session_folder(name) / "logs"

    def ensure_default_session(self) -> Path:
        """Create ``.sessions/default/`` at repo root when no session is active."""
        folder = self.session_folder(self.DEFAULT_SESSION)
        folder.mkdir(parents=True, exist_ok=True)
        self.logs_dir_for(self.DEFAULT_SESSION).mkdir(parents=True, exist_ok=True)
        session_md = folder / "session.md"
        if not session_md.is_file():
            session_md.write_text(self._default_session_markdown(), encoding="utf-8")
        return folder

    def _default_session_markdown(self) -> str:
        return "\n".join(
            [
                f"# Session: {self.DEFAULT_SESSION}",
                "",
                "## Start",
                "",
                f"- **date:** {date.today().isoformat()}",
                "- **note:** implicit default — no named work session open",
                "",
            ]
        )

    def session_logs_dir(self) -> Path:
        active = self.repo_root / self.ACTIVE
        if active.is_file():
            name = self.active_session_name()
        else:
            self.ensure_default_session()
            name = self.DEFAULT_SESSION
        return self.logs_dir_for(name)

    def session_log_path(self, filename: str) -> Path:
        directory = self.session_logs_dir()
        directory.mkdir(parents=True, exist_ok=True)
        return directory / filename

    def consolidate_logs_for_close(self, session_name: str) -> None:
        """Move hook runtime logs into the session folder before archiving to closed."""
        slug = (session_name or "").strip() or self.DEFAULT_SESSION
        dest_logs = self.logs_dir_for(slug)
        dest_logs.mkdir(parents=True, exist_ok=True)
        self._move_default_logs_into(dest_logs)
        for rel in self.LEGACY_LOG_PATHS:
            self._move_log_into(self.repo_root / rel, dest_logs)
        self.clear_active_session()

    def _move_default_logs_into(self, dest_logs: Path) -> None:
        default_logs = self.logs_dir_for(self.DEFAULT_SESSION)
        if not default_logs.is_dir() or default_logs == dest_logs:
            return
        for item in list(default_logs.iterdir()):
            if item.is_file():
                self._move_log_into(item, dest_logs)
        if default_logs.is_dir() and not any(default_logs.iterdir()):
            default_logs.rmdir()

    def _move_log_into(self, file_path: Path, dest_logs: Path) -> None:
        if not file_path.is_file():
            return
        target = dest_logs / file_path.name
        if target.exists():
            target.unlink()
        try:
            shutil.move(str(file_path), str(target))
        except OSError:
            shutil.copy2(str(file_path), str(target))
            file_path.unlink(missing_ok=True)

class Hooks:
    """Class annotation: disable every hook operation on the toolset."""

    def __new__(cls, target: Any = None, *, disabled: bool = False):
        inst = object.__new__(cls)
        inst.disabled = disabled
        if isinstance(target, type):
            return inst.annotate(target)
        return inst

    def __call__(self, cls: type) -> type:
        return self.annotate(cls)

    def annotate(self, cls: type) -> type:
        cls._hooks_disabled = self.disabled
        return cls

class HookInstallation(Installation):
    """Write Cursor ``hooks.json`` dispatch and ``hook-handlers.json`` refs."""

    channel = "hook"
    DISPATCH_SCRIPT = "harness/hooks/hook_server.py"

    def __init__(
        self,
        ide: str,
        path: Path | str,
        *,
        python: str | None = None,
        repo: Path | str | None = None,
    ) -> None:
        super().__init__(ide, path, repo=repo)
        self.python = python or sys.executable
        self._handlers: list[dict[str, str]] = []
        self.server: Any = None
        self.diagnosis: dict[str, Any] | None = None

    @property
    def dispatch_command(self) -> str:
        repo = self.repo or Path(__file__).resolve().parents[2]
        script = (repo / self.DISPATCH_SCRIPT).resolve()
        return f"{self.python} -u {script}"

    def write(self, tool: Any) -> None:
        if not tool.install_to_hook:
            return
        if self._omit_inject_rules(tool):
            return
        event = getattr(tool.callable, "_hook_name", None)
        if not event:
            return
        record = {
            "event": str(event),
            "operation": tool.name,
            "ref": tool.registration_name,
        }
        if record in self._handlers:
            return
        self._handlers.append(record)
        self.write_hooks_manifest()
        self.write_handlers()

    def _omit_inject_rules(self, tool: Any) -> bool:
        if tool.name != "inject_rules":
            return False
        host = type(getattr(tool, "toolset", None)).__name__
        if host in {"RulesCollection", "FidelityGuidance"}:
            return True
        bound = getattr(getattr(tool, "callable", None), "__self__", None)
        parent = getattr(bound, "parent", None)
        return type(parent).__name__ == "FidelityGuidance"

    def write_handlers(self) -> None:
        if not self._handlers:
            return
        dest = self.path / "hook-handlers.json"
        dest.write_text(
            json.dumps({"handlers": self._handlers}, indent=2) + "\n",
            encoding="utf-8",
        )
        self.track_write(dest)

    def write_hooks_manifest(self) -> None:
        if not self._handlers:
            return
        dest = self.path / "hooks.json"
        hooks = self._existing_hooks(dest)
        self._strip_dispatch_command(hooks)
        self._attach_dispatch_command(hooks)
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(
            json.dumps({"version": 1, "hooks": hooks}, indent=2) + "\n",
            encoding="utf-8",
        )
        self.track_write(dest)

    def _existing_hooks(self, dest: Path) -> dict[str, list[dict[str, Any]]]:
        if not dest.is_file():
            return {}
        try:
            existing = json.loads(dest.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return dict(existing.get("hooks") or {})

    def _strip_dispatch_command(self, hooks: dict[str, list[dict[str, Any]]]) -> None:
        dispatch_cmd = self.dispatch_command
        for event_name in list(hooks.keys()):
            kept = [item for item in hooks[event_name] if item.get("command") != dispatch_cmd]
            if kept:
                hooks[event_name] = kept
            else:
                del hooks[event_name]

    def _attach_dispatch_command(self, hooks: dict[str, list[dict[str, Any]]]) -> None:
        hook_def: dict[str, Any] = {
            "command": self.dispatch_command,
            "timeout": 30,
            "failClosed": False,
        }
        for event in sorted({item["event"] for item in self._handlers}):
            if event == "afterAgentResponse":
                hooks[event] = [dict(hook_def)]
                continue
            bucket = hooks.setdefault(event, [])
            if not any(item.get("command") == hook_def["command"] for item in bucket):
                bucket.append(dict(hook_def))

    def standup(self) -> Any:
        from harness.hooks.hook_server import HookServer

        self.server = HookServer.from_handlers(
            self.path / "hook-handlers.json", repo=self.repo
        )
        return self.server

    def diagnose(self) -> dict[str, Any]:
        server = self.server if self.server is not None else self.standup()
        self.diagnosis = server.diagnose()
        return self.diagnosis

class HtmlUxMap(UxMap):
    """Render a review shell: mockup on the left, story names at the bottom."""

    @classmethod
    def parse(cls, content: str) -> UxMap:
        """Scaffold parse: if JSON embedded in a comment marker, reuse JsonUxMap."""
        marker = "<!-- ux-map-json:"
        if marker in content:
            start = content.index(marker) + len(marker)
            end = content.index("-->", start)
            return JsonUxMap.create().parse(content[start:end].strip())
        ux_map = cls.create()
        ux_map.context.notes.append("html parse stub - structural DOM parser later")
        return ux_map

    @classmethod
    def render(cls, ux_map: UxMap) -> str:
        story_names = ux_map.all_story_names()
        story_imports = "\n".join(
            f'  <script type="module" src="{path}" data-ux-story-ref></script>'
            for path in ux_map.story_references
        )
        object_imports = "\n".join(
            f'  <script type="module" src="{path}" data-ux-object-ref></script>'
            for path in ux_map.object_references
        )
        ensure_hint = ""
        if not ux_map.story_references and not ux_map.object_references:
            ensure_hint = (
                "  <!-- Bind story/object JS via Ux.ensure_javascript "
                "(Stories/CE transform to javascript) then set story_references / "
                "object_references on the UxMap. -->\n"
            )
        screens_html = []
        for screen in ux_map.screens:
            hidden = " hidden" if screen != ux_map.screens[0] else ""
            regions = []
            for region in screen.regions:
                controls = "".join(
                    _render_control(control) for control in region.controls
                ) or f'<p class="region-placeholder">{region.name}</p>'
                regions.append(
                    f'<section class="region" data-slot="{region.slot}" '
                    f'data-region="{region.name}">'
                    f"<h3>{region.name}</h3>{controls}</section>"
                )
            story_trace = " . ".join(screen.story_names)
            layout_attr = f' data-layout="{screen.layout}"' if screen.layout else ""
            screens_html.append(
                f'<article class="screen" data-slug="{screen.slug}"'
                f"{layout_attr}{hidden}>"
                f"<h2>{screen.name}</h2>"
                f'<p class="layout">{screen.layout or "-"}</p>'
                f'<div class="regions">{"".join(regions)}</div>'
                f'<p class="screen-stories">Stories: {story_trace or "-"}</p>'
                f"</article>"
            )
        stories_list = (
            "".join(f"<li>{name}</li>" for name in story_names)
            or "<li>(waiting for story JS modules)</li>"
        )
        model_json = JsonUxMap.create().render(ux_map).replace("-->", "")
        transitions_js = ",\n".join(
            f'    {{from: "{t.from_screen}", to: "{t.to_screen}", '
            f'trigger: "{t.trigger}"}}'
            for t in ux_map.transitions
        )
        shell = _SHELL_PATH.read_text(encoding="utf-8")
        return (
            shell.replace("@@TITLE@@", ux_map.scope or ux_map.name)
            .replace("@@SCREENS@@", "".join(screens_html) or "<p>No screens yet.</p>")
            .replace("@@STORIES_LIST@@", stories_list)
            .replace("@@ENSURE_HINT@@", ensure_hint)
            .replace("@@STORY_IMPORTS@@", story_imports)
            .replace("@@OBJECT_IMPORTS@@", object_imports)
            .replace("@@TRANSITIONS_JS@@", transitions_js)
            .replace("@@MODEL_JSON@@", model_json)
        )

    @classmethod
    def from_workspace(cls, root: Path) -> Optional[UxMap]:
        root = Path(root)
        preferred = [
            root / f"{root.name}.html",
            root / "index.html",
            root / "mockup.html",
            root / "ux.html",
        ]
        for candidate in preferred:
            if candidate.is_file():
                return cls.parse(candidate.read_text(encoding="utf-8"))
        html_files = sorted(p for p in root.glob("*.html") if p.is_file())
        if html_files:
            return cls.parse(html_files[0].read_text(encoding="utf-8"))
        return None

class McpInstallation(Installation):
    """Record ``@Mcp`` ops, write ``mcp.json``, enroll at server start."""

    channel = "mcp"

    def __init__(self, ide: str, path: Path | str, toolset_ref: str = "", repo: Path | str | None = None) -> None:
        super().__init__(ide, path, toolset_ref, repo=repo)
        self.mcp_operations: list[McpOperationDefinition] = []
        self._bound = False
        self.host: McpHost | None = None
        self.diagnosis: dict[str, Any] | None = None

    def write(self, tool: Any) -> None:
        if not tool.install_to_mcp:
            return
        self.record_operation(tool)
        self.write_mcp_manifest()

    def record_operation(self, tool: Any) -> None:
        if not tool.install_to_mcp:
            return
        self.mcp_operations.append(McpOperationDefinition.from_tool(tool))

    def write_mcp_manifest(self) -> None:
        if not self.mcp_operations:
            return
        from installation.installer import Installer

        repo = self.repo or Path(__file__).resolve().parents[2]
        host = repo / "harness" / "mcp" / "scripts" / "start_host.py"
        payload = {
            "mcpServers": {
                "cdd": {
                    "type": "stdio",
                    "command": sys.executable,
                    "args": ["-u", str(host)],
                    "env": {
                        "PYTHONPATH": Installer(repo=repo).pythonpath(),
                        "PYTHONIOENCODING": "utf-8",
                    },
                }
            }
        }
        dest = self.path / "mcp.json"
        dest.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(payload, indent=2) + "\n"
        if dest.is_file() and dest.read_text(encoding="utf-8") == text:
            self.track_write(dest)
            return
        dest.write_text(text, encoding="utf-8")
        self.track_write(dest)

    def bind(self, server: Any) -> None:
        self._bound = True
        for op in self.mcp_operations:
            server.enroll(op)

    def standup(self) -> McpHost:
        self.host = McpHost.standup(self.path / "mcp.json", repo=self.repo)
        return self.host

    def diagnose(self) -> dict[str, Any]:
        host = self.host if self.host is not None else self.standup()
        self.diagnosis = host.diagnose()
        return self.diagnosis

    def cursor_host_is_running(self) -> bool:
        return HostPid.from_ide(self.path).is_running()

    def ensure_cursor_host(self) -> str:
        manifest = self.path / "mcp.json"
        spec = McpHost.from_refs((), repo=str(self.repo), project=str(self.repo)).server_entry_from_manifest(
            manifest
        )
        repo_cursor = (Path(self.repo) / ".cursor").resolve() if self.repo is not None else None
        canonical = repo_cursor is not None and Path(self.path).resolve() == repo_cursor
        cursor = CursorMcpJson()
        if canonical and spec and cursor.sync_user_cursor_server(spec, canonical=True):
            cursor.touch_mcp_manifest(manifest, bump_env=True)
            return "nudged"
        if self.cursor_host_is_running():
            return "running"
        if not manifest.is_file():
            return "missing"
        nudge_file = self.path / NUDGE_NAME
        now = time.time()
        try:
            last = float(nudge_file.read_text(encoding="utf-8").strip())
        except (OSError, ValueError):
            last = 0.0
        if now - last < NUDGE_MIN_SECONDS:
            return "waiting"
        cursor.touch_mcp_manifest(manifest, bump_env=True)
        nudge_file.write_text(str(now), encoding="utf-8")
        return "nudged"

