class LayerPurityScanner(MERNScanner):
    """Checks domain core has no framework imports and tiers don't cross-import."""

    RULE = "maintain-layer-purity"

    FORBIDDEN_IN_CORE = [
        r"from\s+['\"]express['\"]",
        r"from\s+['\"]react['\"]",
        r"from\s+['\"]react-dom['\"]",
        r"from\s+['\"]mongodb['\"]",
        r"from\s+['\"]mongoose['\"]",
        r"from\s+['\"]@tanstack",
        r"from\s+['\"]zustand['\"]",
        r"from\s+['\"]redux['\"]",
        r"from\s+['\"]@reduxjs",
        r"import\s+.*\s+from\s+['\"]express['\"]",
        r"import\s+.*\s+from\s+['\"]react['\"]",
        r"import\s+.*\s+from\s+['\"]mongodb['\"]",
        r"import\s+.*\s+from\s+['\"]mongoose['\"]",
        r"require\(['\"]express['\"]\)",
        r"require\(['\"]react['\"]\)",
        r"require\(['\"]mongodb['\"]\)",
        r"require\(['\"]mongoose['\"]\)",
    ]

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        domain_packages = self._find_domain_packages(root)

        for domain_path in domain_packages:
            domain_name = domain_path.name

            violations.extend(self._check_core_purity(domain_path, domain_name))
            violations.extend(
                self._check_no_cross_import(
                    _CrossImportScan(domain_path, domain_name, "server", "client")
                )
            )
            violations.extend(
                self._check_no_cross_import(
                    _CrossImportScan(domain_path, domain_name, "client", "server")
                )
            )

        return violations

    def _check_core_purity(self, domain_path: Path, domain_name: str) -> List[Violation]:
        violations: List[Violation] = []
        for file_path in self._find_tier_files(domain_path, "shared"):
            violations.extend(self._forbidden_core_imports(file_path, domain_name))
        return violations

    def _forbidden_core_imports(self, file_path: Path, domain_name: str) -> List[Violation]:
        content = self._read_file_content(file_path)
        if content is None:
            return []
        violations: List[Violation] = []
        for line_num, line in enumerate(content.split("\n"), start=1):
            if not self._core_line_is_forbidden(line):
                continue
            violations.append(
                self.v(
                    f"Domain '{domain_name}' core file has forbidden "
                    f"framework import: {line.strip()}",
                    str(file_path),
                    line_num,
                )
            )
        return violations

    def _core_line_is_forbidden(self, line: str) -> bool:
        return any(re.search(pattern, line) for pattern in self.FORBIDDEN_IN_CORE)

    def _check_no_cross_import(self, scan: _CrossImportScan) -> List[Violation]:
        violations: List[Violation] = []
        for file_path in self._find_tier_files(scan.domain_path, scan.source_tier):
            violations.extend(self._cross_import_hits(file_path, scan))
        return violations

    def _cross_import_hits(self, file_path: Path, scan: _CrossImportScan) -> List[Violation]:
        content = self._read_file_content(file_path)
        if content is None:
            return []
        violations: List[Violation] = []
        for line_num, line in enumerate(content.split("\n"), start=1):
            if not self._line_imports_forbidden_tier(line, scan):
                continue
            violations.append(
                self.v(
                    f"Domain '{scan.domain_name}/{scan.source_tier}' "
                    f"imports from '{scan.forbidden_tier}' - "
                    f"cross-tier import violation: {line.strip()}",
                    str(file_path),
                    line_num,
                )
            )
        return violations

    def _line_imports_forbidden_tier(self, line: str, scan: _CrossImportScan) -> bool:
        return any(re.search(pattern, line) for pattern in self._cross_patterns(scan))

    def _cross_patterns(self, scan: _CrossImportScan) -> List[str]:
        return [
            rf"from\s+['\"]\.\/{scan.forbidden_tier}['\"]",
            rf"from\s+['\"].*/{scan.forbidden_tier}['\"/]",
            rf"from\s+['\"]@[\w-]+/{scan.domain_name}/{scan.forbidden_tier}['\"]",
        ]

class LeafNodesNotInHorizontalRowScanner(DrawioScanner):
    RULE = 'leaf-nodes-not-in-horizontal-row'

    def scan_page(self, page_root) -> list:
        return [self.violation(f'[{self._scan_page_name}] {message}', location=str(self._scan_file_path)) for message in self._check_page(page_root)]

    def _get_vertex_geo(self, root: ET.Element) -> dict[str, tuple[float, float, float, float]]:
        geo: dict[str, tuple[float, float, float, float]] = {}
        for cell in root.findall('mxCell'):
            if cell.get('vertex') != '1':
                continue
            geometry = cell.find('mxGeometry')
            if geometry is None:
                continue
            width = geometry.get('width')
            height = geometry.get('height')
            if width is None or height is None:
                continue
            geo[cell.get('id', '')] = (float(geometry.get('x', 0)), float(geometry.get('y', 0)), float(width), float(height))
        return geo

    def _get_edges(self, root: ET.Element) -> list[tuple[str, str]]:
        edges = []
        for cell in root.findall('mxCell'):
            if cell.get('edge') != '1':
                continue
            src = cell.get('source')
            tgt = cell.get('target')
            if src and tgt:
                edges.append((src, tgt))
        return edges

    def _check_page(self, root: ET.Element) -> list[str]:
        self._page_root = root
        self._page_geo = self._get_vertex_geo(root)
        neighbours = self._outgoing_neighbours()
        violations = []
        for hub_id, leaf_ids in neighbours.items():
            violations.extend(self._hub_row_violations(hub_id, leaf_ids))
        return violations

    def _outgoing_neighbours(self) -> dict[str, set[str]]:
        neighbours: dict[str, set[str]] = {}
        for src, tgt in self._get_edges(self._page_root):
            if src in self._page_geo:
                neighbours.setdefault(src, set()).add(tgt)
        return neighbours

    def _hub_row_violations(self, hub_id, leaf_ids) -> list[str]:
        if len(leaf_ids) < MIN_ROW_SIZE:
            return []
        violations = []
        self._hub_id = hub_id
        for members in self._row_groups(leaf_ids).values():
            message = self._wide_row_message(members)
            if message:
                violations.append(message)
        return violations

    def _row_groups(self, leaf_ids) -> dict[int, list[str]]:
        row_groups: dict[int, list[str]] = {}
        geo = self._page_geo
        for leaf_id in leaf_ids:
            if leaf_id not in geo:
                continue
            bucket = round(geo[leaf_id][1] / Y_TOLERANCE)
            row_groups.setdefault(bucket, []).append(leaf_id)
        return row_groups

    def _wide_row_message(self, members):
        if len(members) < MIN_ROW_SIZE:
            return None
        geo = self._page_geo
        y_vals = [geo[m][1] for m in members]
        x_vals = [geo[m][0] for m in members]
        y_spread = max(y_vals) - min(y_vals)
        x_spread = max(x_vals) - min(x_vals)
        if y_spread > Y_TOLERANCE or x_spread <= 600:
            return None
        hub_name = self._hub_display_name(self._hub_id)
        return f'{hub_name} has {len(members)} leaf neighbours in a horizontal row (y~{int(sum(y_vals) / len(y_vals))}, x-span={int(x_spread)}px)'

    def _hub_display_name(self, hub_id) -> str:
        hub_cell = self._page_root.find(f"mxCell[@id='{hub_id}']")
        if hub_cell is None:
            return hub_id
        raw = hub_cell.get('value') or hub_id
        text = re.sub('<[^>]+>', '', raw)
        text = re.sub('&[a-z]+;', ' ', text)
        return re.split('[\\s+]', text.strip())[0] or hub_id

