class ModuleContext:
    def __init__(self, py_file: Path) -> None:
        self.py_file = py_file
        self.folder = py_file.parent
        self.path = self.folder / ".context" / "module-context.md"

    def exists(self) -> bool:
        return self.path.is_file()

    def as_record(self) -> dict:
        return {
            "path": str(self.path),
            "folder": self.folder.name,
            "exists": self.exists(),
        }

    def update_self(self, source: "ModuleContext") -> None:
        self.py_file = source.py_file
        self.folder = source.folder
        self.path = source.path

    def read(self) -> str:
        try:
            return self.path.read_text(encoding="utf-8")
        except OSError:
            return ""

    def missing_hit(self, row: dict) -> dict | None:
        if self.py_file.suffix.lower() != ".py" or self.exists():
            return None
        return _hit(
            row,
            f"Module folder '{self.folder.name}' defines classes but has no "
            f".context/module-context.md. "
            f"Add one with at minimum: Purpose, Seam, Dependencies.",
        )

    def modules_heading_hit(self, row: dict) -> dict | None:
        if not self.exists() or not _MODULES_HEADING.search(self.read()):
            return None
        return _hit(
            row,
            f"Module '{self.path.parent.parent.name}' module-context has a "
            f"'Modules' heading. Language and modules are one ## Language "
            f"section — drop ## Modules.",
        )

    def public_seam_hits(self, row: dict) -> List[dict]:
        if not self.exists():
            return []
        hits: List[dict] = []
        content = self.read()
        folder = self.path.parent.parent.name
        for line in content.splitlines():
            match = _HEADING.match(line)
            if not match:
                continue
            heading = match.group(1).strip()
            key_heading = heading.lower()
            if key_heading in _FORBIDDEN_HEADINGS or "internal" in key_heading:
                hits.append(
                    _hit(
                        row,
                        f"Module '{folder}' module-context heading '{heading}' is "
                        f"not part of the public seam.",
                    )
                )
        for match in _PRIVATE_NAME.finditer(content):
            hits.append(
                _hit(
                    row,
                    f"Module '{folder}' module-context names private '{match.group(1)}'.",
                )
            )
        return hits

    def model_block_hits(self, row: dict) -> List[dict]:
        if not self.exists():
            return []
        hits: List[dict] = []
        content = self.read()
        folder = self.path.parent.parent.name
        for pattern, detail in (
            (_SIX_DASHES, "typed `------` member dump"),
            (_SOURCES, "**Sources / context** that lists this folder's own files"),
            (_LIVE_INSTANCE, "'Live instance:' name inventory"),
        ):
            if pattern.search(content):
                hits.append(_hit(row, f"Module '{folder}' module-context has {detail}"))
        return hits

class MutationResponseScanner(TypeScriptScanner):
    """Check that all mutations return a consistent aggregate snapshot."""

    RULE = "standard-mutation-response"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []

        for domain_path in self._find_domain_packages(root):
            violations += self._check_server_routes(domain_path)
            violations += self._check_http_client(domain_path)

        return violations

    def _check_server_routes(self, domain_path: Path) -> List[Violation]:
        server = self._server_file(domain_path)
        if server is None:
            return []
        content = self._read_file_content(server)
        if content is None:
            return []
        return self._success_envelope_hits(server, content)

    def _success_envelope_hits(self, server: Path, content: str) -> List[Violation]:
        violations: List[Violation] = []
        for match in _RES_JSON_RE.finditer(content):
            if not _SUCCESS_PATTERN_RE.match(match.group(1)):
                continue
            violations.append(
                self.v(
                    "Route returns { success/message/ok } instead of "
                    "an aggregate snapshot. All mutations must return the "
                    "same snapshot type.",
                    str(server),
                    content[: match.start()].count("\n") + 1,
                    severity="error",
                )
            )
        return violations

    def _check_http_client(self, domain_path: Path) -> List[Violation]:
        client = self._client_file(domain_path)
        if client is None:
            return []
        content = self._read_file_content(client)
        if content is None:
            return []
        mutation_types = {m.group(1) for m in _RETURN_TYPE_RE.finditer(content) if m.group(1) != "void"}
        if len(mutation_types) <= 1:
            return []
        return [
            self.v(
                f"HTTP client in {client.name} returns multiple different "
                f"types from mutations: {sorted(mutation_types)}. All "
                "mutations on the same aggregate should return the same "
                "snapshot type.",
                str(client),
                severity="warning",
            )
        ]

class StepBody:
    def _code_lines(self, body: str) -> List[str]:
        stripped_lines: List[str] = []
        for raw in body.splitlines():
            line = raw.strip()
            if not line or self._is_comment(line):
                continue
            stripped_lines.append(line)
        return stripped_lines

    def _is_comment(self, line: str) -> bool:
        if line.startswith("//") or line.startswith("#"):
            return True
        if line.startswith("/*") or line.startswith("*") or line.startswith("*/"):
            return True
        return bool(re.match(r'^(?:"""|\'\'\')', line))

    def _is_empty_stub(self, joined: str) -> bool:
        if _TODO_MARKERS.search(joined):
            return True
        if re.search(r"raise\s+NotImplementedError\b", joined):
            return True
        if re.search(r"throw\s+new\s+Error\s*\(\s*['\"`]not implemented", joined, re.IGNORECASE):
            return True
        return joined in ("pass", "pass;", "{}", "return;", "return null;", "return;")

    def is_stub(self, body: str) -> bool:
        stripped_lines = self._code_lines(body)
        if not stripped_lines:
            return True
        return self._is_empty_stub("\n".join(stripped_lines))

    def case_is_stub(self, body: str) -> bool:
        return self.is_stub(body)

    def unimplemented_typescript(self, text: str) -> List[str]:
        return [
            m.group("key")
            for m in _TS_STEP.finditer(text)
            if self.is_stub(m.group("body") or "")
        ]

    def unimplemented_javascript(self, text: str) -> List[str]:
        return self.unimplemented_typescript(text)

    def unimplemented_python(self, text: str) -> List[str]:
        found: List[str] = []
        for pattern in (_PY_STEP_DEF, _PY_STEP_DEF_PRIVATE):
            for m in pattern.finditer(text):
                body_no_doc = "\n".join(
                    line for line in (m.group("body") or "").splitlines()
                    if not re.match(r'^\s*(?:"""|\'\'\')', line)
                )
                if self.is_stub(body_no_doc):
                    found.append(m.group("name"))
        return found

    def unimplemented_java(self, text: str) -> List[str]:
        return [
            m.group("key")
            for m in _JAVA_STEP_LAMBDA.finditer(text)
            if self.is_stub(m.group("body") or "")
        ]

