class OneJsonStorePerAggregateScanner(TypeScriptScanner):
    """Flags a shared JSON database and multi-aggregate default data objects."""

    RULE = "one-json-store-per-aggregate"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        path_owners: Dict[str, List[str]] = {}

        for domain_path in self._find_domain_packages(root):
            server = self._server_file(domain_path)
            if server is None:
                continue
            content = self._read_file_content(server)
            if content is None:
                continue
            domain_name = domain_path.name
            violations += self._check_shared_filenames(server, content)
            violations += self._check_default_data_shape(server, content)
            for match in _PRESET_PATH_RE.finditer(content):
                store_path = match.group(1).replace("\\", "/")
                path_owners.setdefault(store_path, []).append(domain_name)
                if not self._path_names_aggregate(store_path, domain_name):
                    violations.append(
                        self.v(
                            f"Repository in '{domain_name}' opens '{store_path}', "
                            "which does not include this aggregate's name. "
                            "Use data/<aggregate>.json owned by this root only.",
                            str(server),
                            content[: match.start()].count("\n") + 1,
                        )
                    )

        for store_path, owners in path_owners.items():
            unique = sorted(set(owners))
            if len(unique) > 1:
                violations.append(
                    self.v(
                        f"JSON store '{store_path}' is opened by multiple aggregates "
                        f"({', '.join(unique)}). Each aggregate root owns its own file.",
                        store_path,
                    )
                )
        return violations

    def _check_shared_filenames(self, server: Path, content: str) -> List[Violation]:
        violations: List[Violation] = []
        lower = content.lower()
        for name in _SHARED_STORE_NAMES:
            if name in lower:
                line = next(
                    (i for i, row in enumerate(content.splitlines(), 1) if name in row.lower()),
                    1,
                )
                violations.append(
                    self.v(
                        f"Shared JSON database filename '{name}' found. "
                        "Give each aggregate its own data/<aggregate>.json file.",
                        str(server),
                        line,
                    )
                )
        return violations

    def _check_default_data_shape(self, server: Path, content: str) -> List[Violation]:
        violations: List[Violation] = []
        for match in _DEFAULT_DATA_RE.finditer(content):
            keys = _ARRAY_KEY_RE.findall(match.group(1))
            if len(keys) > 1:
                line = content[: match.start()].count("\n") + 1
                violations.append(
                    self.v(
                        f"lowdb default data has {len(keys)} collections "
                        f"({', '.join(keys)}). One JSON store holds one aggregate.",
                        str(server),
                        line,
                    )
                )
        return violations

    def _path_names_aggregate(self, store_path: str, domain_name: str) -> bool:
        stem = Path(store_path).stem.lower()
        slug = domain_name.lower()
        singular = slug[:-1] if slug.endswith("s") else slug
        return slug in stem or singular in stem

class PackageNamesScanner(TypeScriptScanner):
    """Checks npm package names and TypeScript import path consistency."""

    RULE = "use-valid-package-names"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        project_root = root

        pkg_violations, declared_names = self._check_package_jsons(project_root)
        violations += pkg_violations
        violations += self._check_import_paths(project_root, declared_names)

        return violations

    # ------------------------------------------------------------------ #
    # package.json validation                                              #
    # ------------------------------------------------------------------ #

    def _check_package_jsons(self, project_root: Path) -> Tuple[List[Violation], Set[str]]:
        violations: List[Violation] = []
        declared_names: Set[str] = set()
        packages_dir = project_root / "packages"
        if not packages_dir.exists():
            return violations, declared_names

        for pkg_json in sorted(packages_dir.rglob("package.json")):
            if "node_modules" in pkg_json.parts:
                continue
            try:
                data = json.loads(pkg_json.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                continue

            name: Optional[str] = data.get("name", "")
            if not name:
                continue

            declared_names.add(name)

            exports = data.get("exports", {})
            if isinstance(exports, dict):
                for export_key in exports:
                    if export_key != "." and export_key.startswith("./"):
                        sub_path = export_key[2:]
                        declared_names.add(f"{name}/{sub_path}")

            for placeholder in _PLACEHOLDER_SCOPES:
                if name.startswith(placeholder):
                    violations.append(
                        self.v(
                            f"Package '{name}' uses a generic placeholder scope "
                            f"'{placeholder}'. Derive the scope from the "
                            "application's business purpose (e.g. @pawplace, "
                            "@taskflow, @shopfront).",
                            str(pkg_json),
                        )
                    )
                    break

            if name.count("/") > 1:
                violations.append(
                    self.v(
                        f"Package name '{name}' contains multiple slashes. "
                        "npm only allows @scope/name - flatten with hyphens: "
                        f"'{name.replace('/', '-', 1)}'.",
                        str(pkg_json),
                    )
                )
                continue

            if name.startswith("@") and not _VALID_PACKAGE_NAME_RE.match(name):
                violations.append(
                    self.v(
                        f"Package name '{name}' is not a valid scoped npm name. "
                        "Use @scope/domain-tier with lowercase letters and hyphens.",
                        str(pkg_json),
                    )
                )

            # Feature packages nest domain modules; skip process-boot-only dirs.
            parent_name = folder.parent.name if folder.parent else ""
            if parent_name == "packages":
                for legacy_suffix in ("-shared", "-server", "-client"):
                    if name.endswith(legacy_suffix):
                        violations.append(
                            self.v(
                                f"Package '{name}' uses the legacy tier suffix "
                                f"'{legacy_suffix}'. Use one feature package "
                                f"'@{name.split('/')[0][1:]}/{folder.name}' with "
                                "nested domain folders and subpath exports.",
                                str(pkg_json),
                            )
                        )
                        break

        return violations, declared_names

    # ------------------------------------------------------------------ #
    # Import path validation                                               #
    # ------------------------------------------------------------------ #

    def _check_import_paths(self, project_root: Path, declared_names: Set[str]) -> List[Violation]:
        violations: List[Violation] = []
        if not declared_names:
            return violations

        scopes: Set[str] = {name.split("/")[0] for name in declared_names if name.startswith("@")}

        packages_dir = project_root / "packages"
        tests_dir = project_root / "tests"

        search_dirs = []
        if packages_dir.exists():
            search_dirs.append(packages_dir)
        if tests_dir.exists():
            search_dirs.append(tests_dir)

        for search_dir in search_dirs:
            for ts_file in self.source_files(search_dir):
                parsed_root = self.parse_file(ts_file)
                if parsed_root is None:
                    continue
                for imp in self.imports:
                    src = imp.source
                    if not src.startswith("@"):
                        continue
                    if src.count("/") > 1:
                        if src in declared_names:
                            continue
                        violations.append(
                            self.v(
                                f"Import path '{src}' contains multiple slashes - "
                                "this is not a valid npm package name. "
                                "Use the flat @scope/domain-tier package name, "
                                "or declare sub-path exports in package.json.",
                                str(ts_file),
                                imp.start_line,
                            )
                        )
                        continue
                    scope = src.split("/")[0]
                    if scope not in scopes:
                        continue
                    if src not in declared_names:
                        violations.append(
                            self.v(
                                f"Import '{src}' references an undeclared package "
                                f"(not found in any package.json). Declared packages: "
                                f"{', '.join(sorted(declared_names))}.",
                                str(ts_file),
                                imp.start_line,
                            )
                        )

        return violations

class _DeclaredPackages:
    names: Set[str]
    scopes: Set[str]

    def scoped_issue(self, source: str) -> Optional[str]:
        if not source.startswith("@"):
            return None
        if source.count("/") > 1:
            return self._multi_slash_issue(source)
        if source.split("/")[0] not in self.scopes or source in self.names:
            return None
        declared = ", ".join(sorted(self.names))
        return (
            f"Import '{source}' references an undeclared package "
            f"(not found in any package.json). Declared packages: {declared}."
        )

    def _multi_slash_issue(self, source: str) -> Optional[str]:
        if source in self.names:
            return None
        return (
            f"Import path '{source}' contains multiple slashes - "
            "this is not a valid npm package name. "
            "Use the flat @scope/domain-tier package name, "
            "or declare sub-path exports in package.json."
        )

class PlanTurns:
    """Edit and delete Turns on a Plan."""

    def __init__(self, plan: Plan) -> None:
        self._plan = plan

    def edit(self, turn: Turn, **fields: Any) -> Turn:
        for field_name, field_value in fields.items():
            setattr(turn, field_name, field_value)
        return turn

    def delete(self, turn: Turn) -> None:
        turns = self._plan._turns
        if turn in turns:
            turns.remove(turn)

