class PythonTree:
    def render(self, story_map: StoryMap, tests_root: str = "tests") -> Dict[str, str]:
        tree: Dict[str, str] = {}
        self._tree = tree
        self._root = tests_root.strip("/") or "tests"
        for epic in getattr(story_map, "epics", []) or []:
            self._render_epic(epic)
        return tree

    def _render_epic(self, epic: Epic) -> None:
        epic_slug = to_kebab(epic.name)
        helper = self._render_epic_helper(epic)
        if helper is not None:
            self._tree[f"{self._root}/{epic_slug}/{to_snake(epic.name)}_helper.py"] = helper
        self._epic = epic
        for sub in getattr(epic, "sub_epics", []) or []:
            self._render_sub_epic(sub, f"{self._root}/{epic_slug}")

    def _render_epic_helper(self, epic: Epic) -> str:
        factories = epic.collected_example_factories()
        factories_py = PythonExampleFactories()
        helper_class = f"{to_pascal(epic.name)}Helper"
        lines: list[str] = [
            '"""Epic helper - ExampleFactory accessors; AI fills given_* bodies."""',
            "",
            "from __future__ import annotations",
            "",
        ]
        lines.extend(factories_py.render_imports(factories))
        lines.append(f"class {helper_class}:")
        lines.append('    """Shared ExampleFactory accessors. Tier test-helpers import this to build real collaborators."""')
        lines.append("")
        lines.extend(factories_py.render_accessors(factories))
        if not factories:
            lines.append(f"    # No example_factories declared on epic {epic.name!r}")
            lines.append("    pass")
            lines.append("")
        return "\n".join(lines).rstrip() + "\n"

    def _render_sub_epic(self, sub: SubEpic, parent: str) -> None:
        folder = f"{parent}/{to_kebab(sub.name)}"
        for nested in getattr(sub, "sub_epics", []) or []:
            self._render_sub_epic(nested, folder)
        for story in getattr(sub, "stories", []) or []:
            self._render_story(story, folder)

    def _render_story(self, story: Story, parent: str) -> None:
        if not getattr(story, "scenarios", None):
            return
        story_folder = f"{parent}/{to_kebab(story.name)}"
        self._tree[f"{story_folder}/{to_snake(story.name)}_story.test.py"] = render_story_file(story)

class RepositoryOwnsAggregateLifecycleScanner(TypeScriptScanner):
    """Domain-core *Repository interfaces must cover the aggregate-root lifecycle."""

    RULE = "repository-owns-aggregate-lifecycle"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        for domain_path in self._find_domain_packages(root):
            core = self._domain_core_file(domain_path)
            if core is None:
                continue
            parsed = self.parse_file(core)
            if parsed is None:
                violations += self._regex_fallback(core, domain_path.name)
                continue
            repo_ifaces = [
                iface
                for iface in self.interfaces
                if iface.name.endswith("Repository")
            ]
            if not repo_ifaces:
                violations.append(
                    self.v(
                        f"Domain '{domain_path.name}' core has no *Repository interface. "
                        "Compartment the aggregate behind a repository that load/create/"
                        "search/update the aggregate root.",
                        str(core),
                    )
                )
                continue
            for iface in repo_ifaces:
                names = {n.lower() for n in iface.method_names}
                missing = [op for op in _REQUIRED if op not in names]
                if missing:
                    violations.append(
                        self.v(
                            f"Interface '{iface.name}' is missing {', '.join(missing)}(). "
                            "A Repository returns the aggregate root via load, create, "
                            "search, and update.",
                            str(core),
                            iface.start_line,
                        )
                    )
        return violations

    def _regex_fallback(self, core: Path, domain_name: str) -> List[Violation]:
        content = core.read_text(encoding="utf-8", errors="replace")
        if "Repository" not in content:
            return [
                self.v(
                    f"Domain '{domain_name}' core has no *Repository interface.",
                    str(core),
                )
            ]
        present: Set[str] = set()
        for op in _REQUIRED:
            if f"{op}(" in content or f"{op} (" in content:
                present.add(op)
        missing = [op for op in _REQUIRED if op not in present]
        if missing:
            return [
                self.v(
                    f"Repository in '{core.name}' is missing {', '.join(missing)}(). "
                    "A Repository returns the aggregate root via load, create, "
                    "search, and update.",
                    str(core),
                )
            ]
        return []

class RouteDelegationScanner(LERNScanner):
    """Checks route handlers delegate to domain-server rather than calling repo directly."""

    RULE = "delegate-routes-to-domain-server"

    REPO_CALL = re.compile(r"\b(?:repo|repository)\.\w+\(", re.IGNORECASE)
    SHARED_DOMAIN_IN_ROUTE = re.compile(
        r"new\s+\w+\s*\([^)]*\)\s*\.\s*(?:filter|search|map|reduce)\w*\(",
    )
    ROUTER_HANDLER = re.compile(r"router\.(get|post|put|patch|delete)\s*\(")

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        project_root = root

        for routes_file in project_root.rglob("*.routes.ts"):
            if "node_modules" in routes_file.parts or "examples" in routes_file.parts:
                continue
            violations.extend(self._check_file(routes_file, handlers_only=False))

        for router_file in project_root.rglob("*Router.ts"):
            if "node_modules" in router_file.parts or "examples" in router_file.parts:
                continue
            violations.extend(self._check_file(router_file, handlers_only=False))

        for server_file in project_root.rglob("*-server.ts"):
            if "node_modules" in server_file.parts or "examples" in server_file.parts:
                continue
            violations.extend(self._check_file(server_file, handlers_only=True))

        return violations

    def _check_file(self, path: Path, *, handlers_only: bool) -> List[Violation]:
        content = self._read_file_content(path)
        if content is None:
            return []
        if handlers_only and not self.ROUTER_HANDLER.search(content):
            return []

        lines = content.splitlines()
        if handlers_only:
            ranges = self._handler_line_ranges(content)
            if not ranges:
                return []
            check_lines = [
                (i, lines[i - 1])
                for start, end in ranges
                for i in range(start, end + 1)
                if 1 <= i <= len(lines)
            ]
        else:
            check_lines = list(enumerate(lines, start=1))

        violations: List[Violation] = []
        for i, line in check_lines:
            stripped = line.strip()
            if stripped.startswith("//"):
                continue
            if self.REPO_CALL.search(line):
                violations.append(
                    self.v(
                        "Route handler calls repository directly - delegate to "
                        "server-side domain class instead.",
                        str(path),
                        i,
                    )
                )
            if self.SHARED_DOMAIN_IN_ROUTE.search(line):
                violations.append(
                    self.v(
                        "Route handler applies shared domain logic inline - "
                        "move to server-side domain class.",
                        str(path),
                        i,
                    )
                )
        return violations

    def _handler_line_ranges(self, content: str) -> List[Tuple[int, int]]:
        """Return 1-based (start, end) line ranges for each router.* callback body."""
        ranges: List[Tuple[int, int]] = []
        for match in self.ROUTER_HANDLER.finditer(content):
            ranges.extend(self._callback_line_range(content, match.end()))
        return ranges

    def _callback_line_range(self, content: str, after: int) -> List[Tuple[int, int]]:
        brace = content.find("{", after)
        if brace < 0:
            return []
        end = self._matching_brace_end(content, brace)
        return [(content[:brace].count("\n") + 1, content[:end].count("\n") + 1)]

    def _matching_brace_end(self, content: str, brace: int) -> int:
        depth = 0
        for index in range(brace, len(content)):
            depth = self._brace_depth_after(content[index], depth)
            if depth == 0:
                return index
        return brace

    def _brace_depth_after(self, char: str, depth: int) -> int:
        if char == "{":
            return depth + 1
        if char == "}":
            return depth - 1
        return depth

