class StartHost:
    """Parse start_host CLI flags and load toolset refs."""

    FALLBACK_REPO = Path(__file__).resolve().parents[3]

    def toolset_refs(self, value: str) -> tuple[str, ...]:
        return tuple(ref.strip() for ref in value.split(",") if ref.strip())

    def arg_after(self, args: list[str], flag: str) -> str:
        if flag not in args:
            return ""
        index = args.index(flag)
        if index + 1 >= len(args):
            return ""
        return str(args[index + 1])

    def find_cdd_repo(self, start: Path | str | None = None) -> Path:
        """Workspace first, then this script's checkout. Worktrees must not pin __file__."""
        here = Path(start or os.getcwd()).resolve()
        for candidate in (here, *here.parents):
            if (candidate / "installation" / "installer.py").is_file():
                return candidate
        return self.FALLBACK_REPO

class StereotypeAboveClassNameScanner(DrawioScanner):
    RULE = RULE

    def scan_page(self, page_root) -> list:
        violations = []
        for cell in page_root.iter("mxCell"):
            if cell.get("vertex") != "1":
                continue
            raw = cell.get("value") or ""
            if not raw:
                continue
            text = self._unescape(html.unescape(raw))
            match = re.search(r"<b[^>]*>(.*?)</b>", text, re.IGNORECASE | re.DOTALL)
            if not match:
                continue
            title = match.group(1)
            if _STEREOTYPE.search(title):
                violations.append(
                    self.violation(
                        f"[{self._scan_page_name}] Stereotype sits on the same line as the "
                        f"class name inside <b>: "
                        f"{re.sub(r'<[^>]+>', '', title)[:80]!r}",
                        location=str(self._scan_file_path),
                    )
                )
        return violations

class NodeSnapshot:
    """Recursive before-state of a StoryNode captured at the start of translate_from.

    Immutable value: two snapshots with the same fields are interchangeable.
    """

    node_id: int  # identity of the captured node - used to guard reverse against a foreign report
    name: str
    sequential_order: int
    extra_fields: dict = field(default_factory=dict)
    child_snapshots: List["NodeSnapshot"] = field(default_factory=list)

    @classmethod
    def from_node(cls, node: "StoryNode") -> "NodeSnapshot":
        return cls(
            node_id=id(node),
            name=node.name,
            sequential_order=node.sequential_order,
            extra_fields=node.snapshot_fields(),
            child_snapshots=[cls.from_node(child) for child in node.children()],
        )

    def restore_into(self, node: "StoryNode") -> None:
        node.name = self.name
        node.sequential_order = self.sequential_order
        node.restore_snapshot_fields(self.extra_fields)
        children = node.children()
        for i, child_snapshot in enumerate(self.child_snapshots):
            if i < len(children):
                child_snapshot.restore_into(children[i])

class _Background:
    all = None
    each = None

class StoryNodeTransformer(nodetransformers.TransformToSpecsNodeTransformer):
    STORY = frozenset({"story"})
    STRUCTURE = frozenset({"background", "scenario"})
    STEPS = frozenset({"given", "when", "then", "and_"})

    def visit_With(self, node: ast.With) -> ast.AST:
        name = self._get_name(node)
        if name in self.STORY:
            return self._transform_story(node)
        if name in self.STRUCTURE or name in self.STEPS:
            return node
        node = super(StoryNodeTransformer, self).generic_visit(node)  # type: ignore[attr-defined]
        return super().visit_With(node)

    def _background_scope(self, node: ast.With) -> str:
        context_expr = self._context_expr_for(node)
        if isinstance(context_expr, ast.Attribute) and isinstance(
            context_expr.value, ast.Name
        ):
            if context_expr.value.id == "background" and context_expr.attr in (
                "all",
                "each",
            ):
                return context_expr.attr
        return "each"

    def _is_background_with(self, node: ast.With) -> bool:
        return self._get_name(node) == "background"

    def visit_Module(self, node: ast.Module) -> ast.Module:
        node = super().visit_Module(node)
        expanded: list[ast.stmt] = []
        for stmt in node.body:
            if isinstance(stmt, ast.With) and self._is_background_with(stmt):
                _story_givens, scenarios = self._expand_background(stmt)
                expanded.extend(scenarios)
                continue
            if isinstance(stmt, ast.With) and self._get_name(stmt) == "scenario":
                expanded.append(self._transform_scenario(stmt, []))
                continue
            expanded.append(stmt)
        node.body = expanded
        return node

    def _transform_story(self, node: ast.With) -> ast.ClassDef:
        context_expr = self._context_expr_for(node)
        story_name = self._human_readable_context_expr(context_expr)
        body: list[ast.stmt] = []
        story_givens: list[list[ast.stmt]] = []

        for stmt in node.body:
            if isinstance(stmt, ast.With) and self._is_background_with(stmt):
                scope = self._background_scope(stmt)
                bg_story_givens, scenarios = self._expand_background(stmt)
                if scope == "all":
                    story_givens.extend(bg_story_givens)
                body.extend(scenarios)
            else:
                transformed = self.visit(stmt)
                if isinstance(transformed, ast.stmt):
                    body.append(transformed)

        if story_givens:
            self._inject_node = node
            body = self._inject_story_givens(body, story_givens)

        return ast.copy_location(
            ast.ClassDef(
                name=self._prefix_with_sequence(f"Story_{_slug(story_name)}"),
                bases=[],
                keywords=[],
                body=body,
                decorator_list=[
                    self._set_attribute("_example_group", True),
                    self._set_attribute("_example_name", story_name),
                    self._set_attribute("_tags", []),
                    self._set_attribute("_pending", False),
                    self._set_attribute("_shared", False),
                ],
            ),
            node,
        )

    def _expand_background(
        self, node: ast.With
    ) -> tuple[list[list[ast.stmt]], list[ast.ClassDef]]:
        scope = self._background_scope(node)
        background_givens: list[list[ast.stmt]] = []
        scenarios: list[ast.ClassDef] = []

        for stmt in node.body:
            if not isinstance(stmt, ast.With):
                continue
            step = self._get_name(stmt)
            if step == "given":
                background_givens.append(stmt.body)
            elif step == "scenario":
                per_scenario_givens = (
                    background_givens if scope == "each" else []
                )
                scenarios.append(
                    self._transform_scenario(stmt, per_scenario_givens)
                )

        story_givens = background_givens if scope == "all" else []
        return story_givens, scenarios

    def _inject_story_givens(
        self,
        body: list[ast.stmt],
        givens: list[list[ast.stmt]],
    ) -> list[ast.stmt]:
        extra: list[ast.stmt] = [stmt for block in givens for stmt in block]
        for index, stmt in enumerate(body):
            if isinstance(stmt, ast.FunctionDef) and stmt.name == "before_all":
                merged = list(stmt.body) + extra
                body[index] = ast.copy_location(
                    ast.FunctionDef(
                        name="before_all",
                        args=stmt.args,
                        body=merged,
                        decorator_list=stmt.decorator_list,
                    ),
                    stmt,
                )
                return body

        body.insert(
            0,
            ast.copy_location(
                ast.FunctionDef(
                    name="before_all",
                    args=self._generate_argument("self"),
                    body=extra,
                    decorator_list=[],
                ),
                self._inject_node,
            ),
        )
        return body

    def _transform_scenario(
        self,
        node: ast.With,
        background_givens: list[list[ast.stmt]],
    ) -> ast.ClassDef:
        context_expr = self._context_expr_for(node)
        scenario_name = self._human_readable_context_expr(context_expr)

        scenario_givens: list[list[ast.stmt]] = []
        whens: list[list[ast.stmt]] = []
        thens: list[tuple[str, list[ast.stmt]]] = []
        last_kind: str | None = None

        for stmt in node.body:
            if not isinstance(stmt, ast.With):
                continue
            step = self._get_name(stmt)
            label = self._human_readable_context_expr(self._context_expr_for(stmt))
            if step == "given":
                scenario_givens.append(stmt.body)
                last_kind = "given"
            elif step == "when":
                whens.append(stmt.body)
                last_kind = "when"
            elif step == "and_":
                if last_kind in ("when", "and_when"):
                    whens.append(stmt.body)
                    last_kind = "and_when"
                elif last_kind in ("then", "and_then"):
                    thens.append((label, stmt.body))
                    last_kind = "and_then"
                else:
                    whens.append(stmt.body)
                    last_kind = "when"
            elif step == "then":
                thens.append((label, stmt.body))
                last_kind = "then"

        setup_body: list[ast.stmt] = []
        for block in (*background_givens, *scenario_givens, *whens):
            setup_body.extend(block)

        class_body: list[ast.stmt] = []
        if setup_body:
            class_body.append(
                ast.copy_location(
                    ast.FunctionDef(
                        name="before_all",
                        args=self._generate_argument("self"),
                        body=setup_body,
                        decorator_list=[],
                    ),
                    node,
                )
            )

        for index, (label, body) in enumerate(thens):
            example_name = f"Then {label}" if index == 0 else label
            display_name = f"it Then {label}" if index == 0 else f"it {label}"
            class_body.append(
                self._make_example_function(example_name, display_name, body, node)
            )

        return ast.copy_location(
            ast.ClassDef(
                name=self._prefix_with_sequence(f"Scenario_{_slug(scenario_name)}"),
                bases=[],
                keywords=[],
                body=class_body,
                decorator_list=[
                    self._set_attribute("_example_group", True),
                    self._set_attribute("_example_name", scenario_name),
                    self._set_attribute("_tags", []),
                    self._set_attribute("_pending", False),
                    self._set_attribute("_shared", False),
                ],
            ),
            node,
        )

    def _make_example_function(
        self,
        function_name: str,
        example_name: str,
        body: list[ast.stmt],
        node: ast.AST,
    ) -> ast.FunctionDef:
        return ast.copy_location(
            ast.FunctionDef(
                name=self._prefix_with_sequence(function_name),
                args=self._generate_argument("self"),
                body=body,
                decorator_list=[
                    self._set_attribute("_example", True),
                    self._set_attribute("_example_name", example_name),
                    self._set_attribute("_tags", []),
                    self._set_attribute("_pending", False),
                ],
            ),
            node,
        )

class StoryExampleCollector(ExampleCollector):
    STORY_SUFFIXES = (".e2e.py", ".front-end.py", ".back-end.py")

    def __init__(
        self, paths: list[str], node_transformer: StoryNodeTransformer
    ) -> None:
        super().__init__(paths)
        self._node_transformer = node_transformer

    def _collect_files_containing_examples(self) -> list[str]:
        collected: list[str] = []
        for path in self.paths:
            if not os.path.exists(path):
                continue
            if os.path.isdir(path):
                collected.extend(self._collect_story_files_in_directory(path))
            elif self._is_story_file(path):
                collected.append(path)
        collected.sort()
        return collected

    def _collect_story_files_in_directory(self, directory: str) -> list[str]:
        found: list[str] = []
        for root, _dirs, files in os.walk(directory):
            for name in files:
                if self._is_story_file(name):
                    found.append(os.path.join(self._normalize_path(root), name))
        return found

    def _is_story_file(self, path: str) -> bool:
        name = os.path.basename(path)
        if name.endswith("_story.test.py"):
            return True
        return any(path.endswith(suffix) for suffix in self.STORY_SUFFIXES)

class JavaTree:
    def render(self, story_map: StoryMap, tests_root: str = "tests") -> Dict[str, str]:
        self._tree: Dict[str, str] = {}
        self._root = tests_root.strip("/") or "tests"
        self._epic: Epic | None = None
        self._parent = self._root
        for epic in getattr(story_map, "epics", []) or []:
            self._render_epic(epic)
        return self._tree

    def _render_epic(self, epic: Epic) -> None:
        self._epic = epic
        epic_slug = to_kebab(epic.name)
        helper_class = f"{to_pascal(epic.name)}Helper"
        self._tree[f"{self._root}/{epic_slug}/{helper_class}.java"] = self._helper(
            helper_class
        )
        self._parent = f"{self._root}/{epic_slug}"
        for sub in getattr(epic, "sub_epics", []) or []:
            self._render_sub(sub)

    def _helper(self, helper_class: str) -> str:
        factories = self._epic.collected_example_factories()
        lines = [
            f"/** Epic helper - ExampleFactory accessors; AI fills given_* bodies. */",
            f"public class {helper_class} {{",
            "  // Explore/spec accessor. Tier test-helpers import this to build real collaborators.",
        ]
        for name in factories:
            method = name[0].lower() + name[1:]
            lines.append(f"  public {name} {method}() {{ return new {name}(); }}")
        if not factories:
            lines.append(f"  // No example_factories on epic {self._epic.name!r}")
        lines.append("}")
        lines.append("")
        return "\n".join(lines)

    def _render_sub(self, sub: SubEpic) -> None:
        folder = f"{self._parent}/{to_kebab(sub.name)}"
        saved_parent = self._parent
        self._parent = folder
        for nested in getattr(sub, "sub_epics", []) or []:
            self._render_sub(nested)
        self._parent = saved_parent
        for story in getattr(sub, "stories", []) or []:
            if not story.scenarios:
                continue
            story_folder = f"{folder}/{to_kebab(story.name)}"
            class_name = f"{to_pascal(story.name)}Story"
            self._tree[f"{story_folder}/{class_name}.java"] = render_story_file(story)

class TypeSafetyScanner(TypeScriptScanner):
    """AST + regex checks for type safety in Express controllers."""

    RULE = "ensure-type-safe-routes"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        project_root = root

        for domain_path in self._find_domain_packages(project_root):
            server = self._server_file(domain_path)
            if server is not None:
                violations += self._check_controller(server)

        packages_dir = project_root / "packages"
        if packages_dir.exists():
            for app_file in packages_dir.rglob("app.ts"):
                if "node_modules" not in app_file.parts:
                    violations += self._check_controller(app_file)

        return violations

    def _check_controller(self, ts_file: Path) -> List[Violation]:
        content = self._read_file_content(ts_file)
        if content is None:
            return []
        violations = self._missing_express_augmentation(ts_file, content)
        violations.extend(self._as_any_req_hits(ts_file, content))
        violations.extend(self._ts_suppress_hits(ts_file, content))
        violations.extend(self._untyped_lambda_hits(ts_file, content))
        return violations

    def _missing_express_augmentation(self, ts_file: Path, content: str) -> List[Violation]:
        if not _REQ_CUSTOM_PROP_RE.search(content) or _DECLARE_GLOBAL_RE.search(content):
            return []
        return [
            self.v(
                f"'{ts_file.name}' accesses req.user/req.session/req.auth "
                "but has no Express type augmentation. Add:\n"
                "  declare global { namespace Express { "
                "interface Request { user?: { id: string } } } }\n"
                "Otherwise tsc --noEmit will fail with TS2339.",
                str(ts_file),
            )
        ]

    def _as_any_req_hits(self, ts_file: Path, content: str) -> List[Violation]:
        return [
            self.v(
                f"'{ts_file.name}' uses (req as any).user to bypass type "
                "checking. Use a global type augmentation instead of "
                "casting to any.",
                str(ts_file),
                line_num,
            )
            for line_num, line in enumerate(content.splitlines(), 1)
            if _AS_ANY_REQ_RE.search(line)
        ]

    def _ts_suppress_hits(self, ts_file: Path, content: str) -> List[Violation]:
        return [
            self.v(
                f"'{ts_file.name}' uses @ts-ignore/@ts-expect-error to "
                "suppress a type error. Fix the underlying type issue "
                "instead of suppressing the diagnostic.",
                str(ts_file),
                line_num,
            )
            for line_num, line in enumerate(content.splitlines(), 1)
            if _TS_IGNORE_RE.search(line) or _TS_EXPECT_ERROR_RE.search(line)
        ]

    def _untyped_lambda_hits(self, ts_file: Path, content: str) -> List[Violation]:
        violations: List[Violation] = []
        for line_num, line in enumerate(content.splitlines(), 1):
            if not _IMPLICIT_ANY_MAP_RE.search(line) or _TYPED_LAMBDA_RE.search(line):
                continue
            match = re.search(r"\.(map|filter|forEach|find)\s*\(\s*([a-zA-Z_]\w*)\s*=>", line)
            if match is None:
                continue
            violations.append(
                self.v(
                    f"'{ts_file.name}' has an untyped lambda parameter "
                    f"'{match.group(2)}' in .{match.group(1)}(). "
                    "Add an explicit type: "
                    f".{match.group(1)}(({match.group(2)}: DomainType) => ...)",
                    str(ts_file),
                    line_num,
                    severity="warning",
                )
            )
        return violations

class TypeScriptProperty(PropertyField):
    def ts_type(self) -> str:
        return _ts_type(self.type_hint) if self.type_hint else "any"

    def constructor_parameter(self) -> str:
        return f"{_camel_identifier(self.name)}: {self.ts_type()}"

    def render(self) -> str:
        return f"  {_camel_identifier(self.name)}: {self.ts_type()};"

class TypeScriptOperation(OperationField):
    def render(self, *, signature_only: bool = False) -> str:
        if self.name.startswith("_") and signature_only:
            return ""
        params = ", ".join(self.parameters)
        ret = _ts_type(self.return_type) if self.return_type else "void"
        camel = _camel_identifier(self.name)
        if signature_only:
            return f"  {camel}({params}): {ret};"
        access = "private " if self.name.startswith("_") else ""
        return f"  {access}{camel}({params}): {ret} {{ }}"

class TypeScriptOoadClass(OoadClass):
    def load_property_field(self, source: PropertyField) -> TypeScriptProperty:
        loaded = TypeScriptProperty(name=source.name)
        loaded.update_self(source)
        return loaded

    def load_operation_field(self, source: OperationField) -> TypeScriptOperation:
        loaded = TypeScriptOperation(name=source.name)
        loaded.update_self(source)
        return loaded

    def child_collections(self, source: OoadNode) -> List[ChildCollectionPair]:
        assert isinstance(source, OoadClass)
        return [
            ChildCollectionPair(self.properties, source.properties, self.load_property_field),
            ChildCollectionPair(self.operations, source.operations, self.load_operation_field),
            ChildCollectionPair(self.relationships, source.relationships, self.load_relationship),
        ]

    def update_self(self, source: OoadNode) -> None:
        assert isinstance(source, OoadClass)
        self.intent = source.intent
        self.collaborators = list(source.collaborators)
        self.line = source.line

    def render(self, known_names: Optional[List[str]] = None) -> str:
        names = known_names or []
        lines: List[str] = []
        if self.intent:
            lines.append(f"/** {self.intent} */")
        if is_interface_name(self.name):
            lines.append(f"interface {self.name} {{")
            for property_row in self.properties:
                lines.append(property_row.render())
            for operation in self.operations:
                rendered = operation.render(signature_only=True) if hasattr(operation, "render") else ""
                if rendered:
                    lines.append(rendered)
            lines.append("}")
            return "\n".join(lines)
        iface = companion_interface_name(self.name, names)
        if iface:
            lines.append(f"abstract class {self.name} implements {iface} {{")
        else:
            lines.append(f"class {self.name} {{")
        for property_row in self.properties:
            lines.append(property_row.render())
        if self.properties:
            lines.append("")
            params = ", ".join(
                property_row.constructor_parameter()
                if hasattr(property_row, "constructor_parameter")
                else _camel_identifier(property_row.name)
                for property_row in self.properties
            )
            lines.append(f"  constructor({params}) {{")
            for property_row in self.properties:
                camel = _camel_identifier(property_row.name)
                lines.append(f"    this.{camel} = {camel};")
            lines.append("  }")
            lines.append("")
        for operation in self.operations:
            lines.append(operation.render())
        lines.append("}")
        return "\n".join(lines)

class TypeScriptModule(Module):
    def load_class(self, source: OoadClass) -> TypeScriptOoadClass:
        loaded = TypeScriptOoadClass(name=source.name, sequential_order=source.sequential_order)
        loaded.update_self(source)
        return loaded

    def render(self, known_names: Optional[List[str]] = None) -> str:
        return "\n\n".join(loaded.render(known_names) for loaded in self.classes)

class UbiquitousLanguageScanner(TypeScriptScanner):
    """AST checks for domain-language naming across all tiers."""

    RULE = "use-ubiquitous-language"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []
        project_root = root

        for domain_path in self._find_domain_packages(project_root):
            for tier in ("shared", "server", "client"):
                tier_dir = domain_path / tier
                if not tier_dir.exists():
                    continue
                for ts_file in sorted(tier_dir.glob("*.ts")) + sorted(tier_dir.glob("*.tsx")):
                    violations += self._check_file(ts_file, tier, domain_path.name)

        tests_dir = project_root / "tests"
        if tests_dir.exists():
            for ts_file in tests_dir.rglob("*.ts"):
                if "node_modules" not in ts_file.parts:
                    violations += self._check_test_names(ts_file)
            for tsx_file in tests_dir.rglob("*.tsx"):
                if "node_modules" not in tsx_file.parts:
                    violations += self._check_test_names(tsx_file)

        return violations

    def _check_file(self, ts_file: Path, tier: str, domain_name: str) -> List[Violation]:
        violations: List[Violation] = []
        parsed_root = self.parse_file(ts_file)
        if parsed_root is None:
            return violations

        for cls in self.classes:
            violations += self._check_class_name(cls, ts_file, tier)
            violations += self._check_method_names(cls, ts_file, tier)

        return violations

    def _check_class_name(self, cls, ts_file: Path, tier: str) -> List[Violation]:
        violations: List[Violation] = []
        name = cls.name

        for suffix in _FORBIDDEN_SUFFIXES:
            if name.endswith(suffix) and name != suffix:
                violations.append(
                    self.v(
                        f"Class '{name}' uses the technical suffix '{suffix}'. "
                        "Name domain classes after the concept they represent "
                        f"(e.g. '{name.replace(suffix, '')}' or a specific domain noun). "
                        "Reserve 'Service' only for application-layer orchestrators.",
                        str(ts_file),
                        cls.start_line,
                    )
                )

        if name.endswith(_SERVICE_SUFFIX) and tier != "server":
            violations.append(
                self.v(
                    f"Class '{name}' uses the 'Service' suffix but is in "
                    f"'{tier}/'. 'Service' suffix is only appropriate for "
                    "application-layer orchestrators in server/.",
                    str(ts_file),
                    cls.start_line,
                )
            )

        return violations

    def _check_method_names(self, cls, ts_file: Path, tier: str) -> List[Violation]:
        violations: List[Violation] = []
        for method in cls.methods:
            if method.name in ("constructor", "toString", "toJSON"):
                continue
            if "private" in method.modifiers:
                continue
            if method.name in _TECHNICAL_METHOD_NAMES:
                violations.append(
                    self.v(
                        f"Method '{cls.name}.{method.name}()' uses a generic "
                        f"technical verb '{method.name}'. Replace with a domain "
                        "verb that expresses business intent, e.g. "
                        "calculateTotal(), placeOrder(), validateEligibility().",
                        str(ts_file),
                        method.start_line,
                    )
                )
        return violations

    def _check_test_names(self, ts_file: Path) -> List[Violation]:
        """Test descriptions must use domain/scenario language, not HTTP."""
        violations: List[Violation] = []
        content = self._read_file_content(ts_file)
        if content is None:
            return violations

        lines = content.splitlines()
        for line_num, line in enumerate(lines, 1):
            if not _DESCRIBE_IT_RE.search(line):
                continue
            if _HTTP_TEST_PATTERN.search(line):
                violations.append(
                    self.v(
                        f"Test name uses HTTP route language: {line.strip()!r}. "
                        "Test names must mirror Gherkin scenario titles in domain "
                        'language, e.g. "user views list of active stores".',
                        str(ts_file),
                        line_num,
                    )
                )
            if _STATUS_CODE_PATTERN.search(line):
                violations.append(
                    self.v(
                        f"Test name references HTTP status code: {line.strip()!r}. "
                        "Use domain outcomes instead of status codes in test names.",
                        str(ts_file),
                        line_num,
                    )
                )

        return violations

class ViewNamingScanner(TypeScriptScanner):
    """Check that client.tsx components follow the {Domain}View naming."""

    RULE = "consistent-view-naming"

    def scan(self, root: Path, files: List[Path]) -> List[Violation]:
        violations: List[Violation] = []

        for domain_path in self._find_domain_packages(root):
            violations += self._check_client(domain_path)

        return violations

    def _check_client(self, domain_path: Path) -> List[Violation]:
        violations: List[Violation] = []
        client = self._client_file(domain_path)
        if client is None:
            return violations

        content = self._read_file_content(client)
        if content is None:
            return violations

        for m in _EXPORT_COMPONENT_RE.finditer(content):
            comp_name = m.group(1)
            if any(comp_name.startswith(p) for p in _NON_VIEW_PREFIXES):
                continue
            # Classes (RecipientClient, RecipientHttpClient) are not views.
            if "Client" in comp_name or "Http" in comp_name:
                continue
            if comp_name.endswith("View"):
                continue

            matched_suffix = False
            for suffix in _WRONG_SUFFIXES:
                if comp_name.endswith(suffix):
                    base = comp_name[: -len(suffix)]
                    violations.append(
                        self.v(
                            f"Component '{comp_name}' in {client.name} uses "
                            f"suffix '{suffix}'. Rename to '{base}View' to "
                            "follow the consistent View naming convention.",
                            str(client),
                            severity="warning",
                        )
                    )
                    matched_suffix = True
                    break
            if not matched_suffix:
                violations.append(
                    self.v(
                        f"Component '{comp_name}' in {client.name} does not "
                        f"end with 'View'. Rename to '{comp_name}View'.",
                        str(client),
                        severity="warning",
                    )
                )

        return violations

class SessionModel:
    """Persist the preferred Cursor/IDE model under ``{repository_root}/.sessions/{name}/model``.

    When no work session is active, use ``.sessions/default`` under the repository root.
    """

    DEFAULT_SESSION = "default"
    FILENAME = "model"
    _FALLBACK_MODELS = (
        "composer-2.5-fast",
        "cursor-grok-4.5-high-fast",
        "cursor-grok-4.6-medium",
        "kimi-k3-max",
        "inherit",
    )

    def __init__(self, workspace: str | Path = ".") -> None:
        self._workspace = workspace

    def session_slug(self, name: str = "") -> str:
        slug = (name or "").strip()
        if slug.startswith("session/"):
            slug = slug[len("session/") :]
        return slug or self.DEFAULT_SESSION

    def file_path(self, session: str = "") -> Path:
        return SessionPaths().session_dir(self._workspace, self.session_slug(session)) / self.FILENAME

    def read(self, session: str = "") -> str:
        path = self.file_path(session)
        if not path.is_file():
            return ""
        try:
            return path.read_text(encoding="utf-8").strip()
        except OSError:
            return ""

    def write(self, model: str, session: str = "") -> Path:
        value = (model or "").strip()
        if not value:
            raise ValueError("model is required")
        path = self.file_path(session)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(value + "\n", encoding="utf-8")
        return path

    def copy_into(self, dest_folder: str | Path, session: str = "") -> Path | None:
        """Copy model into *dest_folder* when missing — session first, then default."""
        dest = Path(dest_folder) / self.FILENAME
        if dest.is_file():
            return None
        slug = self.session_slug(session)
        for candidate in (slug, self.DEFAULT_SESSION):
            src = self.file_path(candidate)
            if not src.is_file():
                continue
            try:
                text = src.read_text(encoding="utf-8").strip()
            except OSError:
                continue
            if not text:
                continue
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(text + "\n", encoding="utf-8")
            return dest
        return None

    def list_available(self) -> list[str]:
        """Prefer ``cursor-agent --list-models``; fall back to known Cursor model ids."""
        found: list[str] = []
        try:
            proc = subprocess.run(
                ["cursor-agent", "--list-models"],
                capture_output=True,
                text=True,
                timeout=20,
                check=False,
            )
            blob = (proc.stdout or "") + "\n" + (proc.stderr or "")
            for line in blob.splitlines():
                token = line.strip().split()[0] if line.strip() else ""
                if not token or token.startswith("-") or ":" in token:
                    continue
                if token.lower() in {"model", "models", "name", "id"}:
                    continue
                if token not in found:
                    found.append(token)
        except (OSError, subprocess.SubprocessError, FileNotFoundError):
            pass
        if found:
            return found
        return list(self._FALLBACK_MODELS)

class Correction:
    """Correction — linked from the fix commit to mistake introducing SHAs."""

    improved: str = ""
    how: str = ""
    status: str = "open"
    mistakes: list[Mistake] = field(default_factory=list)
    fix_commit: str | None = None

    def add(self, mistake: Mistake) -> None:
        if mistake not in self.mistakes:
            self.mistakes.append(mistake)
        mistake.correction = self

    def link(self, git: GitRepo, fix_commit: str) -> None:
        self.fix_commit = fix_commit
        self.status = "fixed"
        entry_ids = [m.entry_id for m in self.mistakes]
        git.note(
            fix_commit,
            {
                "improved": self.improved,
                "how": self.how,
                "status": self.status,
                "entry_ids": ",".join(entry_ids),
                "fix_commit": fix_commit,
            },
        )
        for mistake in self.mistakes:
            if not mistake.introducing_commit:
                continue
            prior = git.read_notes(mistake.introducing_commit)
            prior["fixed_by"] = fix_commit
            git.note(mistake.introducing_commit, prior)

    def correction_commit_message(self, *, subject: str = "correction") -> str:
        lines = [
            subject,
            "",
            f"improved: {self.improved}",
            f"how: {self.how}",
            f"status: {self.status}",
            "",
        ]
        for mistake in self.mistakes:
            lines.append(f"Fixes-Mistake: {mistake.entry_id}")
            if mistake.introducing_commit:
                lines.append(f"Introducing-Commit: {mistake.introducing_commit}")
        return "\n".join(lines)

