def _ensure_worktree_venv(self) -> None:
    """Point at this checkout's .venv — one interpreter for the CDD repo."""
    git = self.git
    if getattr(git, "_memory", False):
        return
    venv = Path(git.root) / ".venv"
    python = venv / ("Scripts" if os.name == "nt" else "bin") / (
        "python.exe" if os.name == "nt" else "python"
    )
    self.venv_note = "" if python.is_file() else f"no venv at {venv}"

def _abbrev_repo_name(folder: str) -> str:
    """Abbreviate a clone folder: first token, then first letter of each later token."""
    tokens = [part for part in re.split(r"[-_]+", folder or "") if part]
    if not tokens:
        return folder
    if len(tokens) == 1:
        return tokens[0]
    return tokens[0] + "-" + "".join(token[0] for token in tokens[1:])

def _try_push(self) -> None:
    try:
        self.git.push()
    except GitConnectError:
        return

def _land_on_default_branch(self) -> None:
    if not self.isolate or self._session_branch_is_default():
        self._try_push()
        return
    default = self.git.default_branch
    for candidate in (default, f"origin/{default}", "main", "origin/main"):
        try:
            self.git.merge_from(
                candidate,
                message=f"merge {candidate} into {self.session_branch}",
            )
            break
        except GitConnectError:
            continue
    self._try_push()
    try:
        self.git.push_to(default)
    except GitConnectError:
        pass
    occupier = self.git.worktree_for(default)
    if occupier is None:
        try:
            self.git._git("branch", "-f", default, "HEAD")
        except GitConnectError:
            return
        return
    if occupier.path.resolve() == Path(self.git.root).resolve():
        return
    other = GitRepo(occupier.path)
    other.clear_stash()
    if other.is_dirty():
        return
    try:
        other.merge_from(
            self.session_branch,
            message=f"merge {self.session_branch} into {default}",
        )
    except GitConnectError:
        return

def _remove_session_worktree_if_clean(self) -> None:
    git = self.git
    if getattr(git, "_memory", False) or not self.isolate:
        return
    self._try_push()
    # Shared/session stash must not keep worktrees around — drop it and remove.
    git.clear_stash()
    # Untracked .context session temps must not block removal — agent BDD and
    # finish_work_session leave disposable CliAgent files that are gitignored.
    if git.is_dirty(untracked=False) or git.has_unpushed_commits():
        return
    if git.is_linked_worktree():
        try:
            GitRepo(git.primary_root()).remove_worktree(git.root)
        except GitConnectError:
            pass
    self._remove_empty_checkout_dir()

def _remove_empty_checkout_dir(self) -> None:
    root = Path(self.path)
    if not root.is_dir():
        return
    try:
        if any(root.iterdir()):
            return
        root.rmdir()
    except OSError:
        return

def _closed_archive_search_roots(self) -> list[Path]:
    """Checkouts that may hold ``.sessions/closed/{name}/`` from a prior close."""
    roots: list[Path] = []
    seen: set[str] = set()

    def add(root: Path) -> None:
        try:
            key = str(root.resolve())
        except OSError:
            key = str(root)
        if key in seen:
            return
        seen.add(key)
        closed = root / ".sessions" / "closed"
        if closed.is_dir():
            roots.append(closed)

    try:
        add(self._archive_root())
    except (AttributeError, TypeError, ValueError):
        pass
    add(Path(self.path or self.workspace.path))
    add(self._repository_root())
    git = self.git
    if git is not None and not getattr(git, "_memory", False):
        try:
            add(Path(git.primary_root()))
        except (AttributeError, TypeError, ValueError):
            pass
    return roots

def _closed_archive_content_root(closed_dir: Path, name: str) -> Path | None:
    nested = closed_dir / name
    if (nested / "session.md").is_file():
        return nested
    if (closed_dir / "session.md").is_file():
        return closed_dir
    try:
        if closed_dir.is_dir() and any(closed_dir.iterdir()):
            return closed_dir
    except OSError:
        return None
    return None

def _force_rmtree(path: Path) -> None:
    """Remove a directory tree on Windows even when files are read-only."""
    if not path.exists():
        return
    for root, dirs, files in os.walk(path, topdown=False):
        for name in files:
            item = Path(root) / name
            try:
                item.chmod(stat.S_IWRITE)
                item.unlink(missing_ok=True)
            except OSError:
                pass
        for name in dirs:
            item = Path(root) / name
            try:
                item.chmod(stat.S_IWRITE)
                item.rmdir()
            except OSError:
                pass
    try:
        path.chmod(stat.S_IWRITE)
        path.rmdir()
    except OSError:
        shutil.rmtree(path, ignore_errors=True)

def _move_tree_contents(self, source: Path, dest: Path) -> None:
    dest.mkdir(parents=True, exist_ok=True)
    for item in source.iterdir():
        target = dest / item.name
        if target.exists():
            if target.is_dir():
                try:
                    self._force_rmtree(target)
                except OSError:
                    self._move_tree_contents(item, target)
            else:
                try:
                    target.chmod(stat.S_IWRITE)
                    target.unlink(missing_ok=True)
                except OSError:
                    pass
        shutil.move(str(item), str(target))

def _find_closed_session_archive(self) -> tuple[Path, Path] | None:
    """Return ``(closed_entry, content_root)`` for the best closed archive match."""
    name = (self.name or "").strip()
    if not name:
        return None
    candidates: list[Path] = []
    for closed_root in self._closed_archive_search_roots():
        exact = closed_root / name
        if exact.is_dir():
            candidates.append(exact)
        prefix = f"{name}-"
        try:
            for item in closed_root.iterdir():
                if item.is_dir() and item.name.startswith(prefix):
                    candidates.append(item)
        except OSError:
            continue
    if not candidates:
        return None
    exact_matches = [path for path in candidates if path.name == name]
    pool = exact_matches or candidates
    pool.sort(
        key=lambda path: path.stat().st_mtime if path.exists() else 0,
        reverse=True,
    )
    for closed_dir in pool:
        content = self._closed_archive_content_root(closed_dir, name)
        if content is not None:
            return closed_dir, content
    return None

def _restore_closed_session_if_needed(self) -> bool:
    """Move ``.sessions/closed/{name}/`` back to ``.sessions/{name}/`` on reopen."""
    found = self._find_closed_session_archive()
    if found is None:
        return False
    closed_dir, content = found
    dest = self.folder
    dest.mkdir(parents=True, exist_ok=True)
    self._move_tree_contents(content, dest)
    if closed_dir != content:
        for item in closed_dir.iterdir():
            if item.resolve() == content.resolve():
                continue
            target = dest / item.name
            if item.is_dir():
                if target.exists():
                    self._move_tree_contents(item, target)
                    self._force_rmtree(item)
                else:
                    shutil.move(str(item), str(target))
            elif not target.exists():
                shutil.move(str(item), str(target))
    self._force_rmtree(closed_dir)
    return True

def _reactivate_on_reopen(self) -> None:
    """Drop ``## End`` on reopen — a resumed session is active again."""
    text = ""
    if self.session_md.is_file():
        text = self.session_md.read_text(encoding="utf-8")
    if self._END_HEADING not in text and not self.ended:
        return
    self.ended = ""
    self.outcome = ""
    self.handoff = ""
    if self.session_md.is_file():
        self.session_md.write_text(self._render(), encoding="utf-8")

def _archive_session_folder(self) -> Path | None:
    """Move session temps to ``{checkout}/.sessions/closed/{name}/``."""
    if not self.name:
        return None
    try:
        source = self.folder
    except ValueError:
        return None
    if not source.is_dir():
        return None
    closed_dir = self._closed_sessions_dir(self._archive_root())
    dest = closed_dir / self.name
    if dest.exists():
        stamp = (self.ended or date.today().isoformat()).replace(":", "-")
        dest = closed_dir / f"{self.name}-{stamp}"
    shutil.move(str(source), str(dest))
    return dest

def _commit_closed_archive(self, archived: Path | None) -> None:
    if archived is None or not archived.is_dir():
        return
    closed_root = archived.parent
    if not closed_root.is_dir():
        return
    try:
        self.git.commit(
            [str(closed_root)],
            f"archive session {self.name}",
            untracked=True,
        )
    except (GitConnectError, ValueError):
        pass

def _commit_active_session_removal(self) -> None:
    """Stage tracked deletions under ``.sessions/{name}/`` after archive move."""
    slug = (self.name or "").strip()
    if not slug:
        return
    root = Path(self.path or self.git.root)
    session_path = SessionPaths().sessions_root(root) / slug
    if session_path.is_dir():
        return
    try:
        self.git.commit(
            [str(session_path)],
            f"remove active session {slug}",
        )
    except (GitConnectError, ValueError):
        pass

def _ticket_number_from_session_name(self) -> int | None:
    match = re.search(r"-(\d+)$", (self.name or "").strip())
    if not match:
        return None
    return int(match.group(1))

def _embed_ticket_context(self) -> None:
    """When the session slug ends in -{issue}, copy that ticket and linked sub-issues into session.md."""
    if (self.body or "").strip():
        return
    number = self._ticket_number_from_session_name()
    if number is None:
        return
    try:
        from workflow.work_ticket import format_session_ticket_context

        gh_repo = Repo.open(str(self._repository_root()))
    except (GitConnectError, ValueError):
        return
    body, contexts = format_session_ticket_context(gh_repo, number)
    if body and not (self.body or "").strip():
        self.body = body
    if contexts and not (self.contexts or "").strip():
        self.contexts = contexts

def _bind_active_session_logs(self) -> None:
    root = Path(self.path or self.git.root)
    SessionLogs(root).write_active_session(self.name or SessionModel.DEFAULT_SESSION)

def consume_handoff(self) -> str:
    """Read a live handoff once, then delete it.

    Deletes ``handoff-latest.md``, ``handoff.md``, and ``handoffs/`` under
    the session folder and docs_dir. A consumed handoff is not session state.
    """
    text = ""
    for root in self._handoff_search_roots():
        for name in ("handoff-latest.md", "handoff.md"):
            path = root / name
            if not path.is_file():
                continue
            if not text:
                text = path.read_text(encoding="utf-8")
            path.unlink()
        archive = root / "handoffs"
        if archive.is_dir():
            shutil.rmtree(archive)
    if text:
        self.handoff = ""
    return text

def _handoff_search_roots(self) -> list[Path]:
    roots: list[Path] = []
    try:
        roots.append(self.folder)
    except ValueError:
        pass
    roots.append(self.docs_dir)
    if self.name:
        sibling = self.docs_dir / self.name
        if sibling.is_dir() and sibling not in roots:
            roots.append(sibling)
    return roots

def save_chat(self, message: str, *, sha: str = "") -> None:
    text = (message or "").strip()
    if not text:
        return
    target = (sha or "").strip() or self.git.current_commit
    self.git.note(target, {"chat": text}, ref="refs/notes/chats")
    existing = [
        line
        for line in self.git.read_annotated_tag(self.chat_tag_name()).splitlines()
        if line.strip()
    ]
    if text not in existing:
        existing.append(text)
    self.git._annotated_tag_target = target
    self.git.write_annotated_tag(self.chat_tag_name(), "\n".join(existing))

def _session_slug(name: str) -> str:
    slug = (name or "").strip()
    if slug.startswith("session/"):
        return slug[len("session/") :]
    return slug

def current_cursor_chat_file(self) -> Path | None:
    """This chat's transcript — ``CURSOR_CONVERSATION_ID`` (per agent process, not mtime).

    Tests may set ``_conversation_id`` to a uuid, or to ``\"\"`` to ignore the process env.
    """
    if getattr(self, "_conversation_id", None) is not None:
        chat_id = (self._conversation_id or "").strip()
    else:
        chat_id = (os.environ.get("CURSOR_CONVERSATION_ID") or "").strip()
    if not chat_id:
        return None
    transcripts = (os.environ.get("AGENT_TRANSCRIPTS") or "").strip()
    if transcripts and getattr(self, "_conversation_id", None) is None:
        root = Path(transcripts)
        nested = root / chat_id / f"{chat_id}.jsonl"
        flat = root / f"{chat_id}.jsonl"
        if nested.is_file():
            return nested
        if flat.is_file():
            return flat
        return nested
    return self.cursor_chat_file(chat_id)

def _running_chat_paths(self) -> list[str]:
    """CliAgent doer/judge chats when bound, plus this Cursor chat when present."""
    paths: list[str] = []
    seen: set[str] = set()

    def _add(path: str) -> None:
        if path and path not in seen:
            seen.add(path)
            paths.append(path)

    current = self.current_cursor_chat_file()
    if current is not None:
        _add(str(current))
    for chat_id in (self.cli_doer, self.cli_judge):
        if not chat_id:
            continue
        _add(str(self.cursor_chat_file(chat_id)))
    return paths

def _wipe_session_logs(self) -> None:
    """Remove events.log only — hook logs move to closed archive on close."""
    log_dir = self.log
    events = log_dir / "events.log"
    if events.is_file():
        events.unlink()

def __init__(self, work_session: WorkSession) -> None:
    self._work_session = work_session
    self.module_dir = work_session.folder

def _write_last_chat_injected(self, body: str) -> None:
    destination = self._last_chat_injected_path()
    if destination is None:
        return
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(body, encoding="utf-8")

def _matching_work_session_rule(
    self, work_session_rule: WorkSessionRule
) -> WorkSessionRule | None:
    found = self.entries.get(work_session_rule.slug)
    if isinstance(found, WorkSessionRule):
        return found
    return None

def _matching_practice_rule(self, work_session_rule: WorkSessionRule) -> Rule | None:
    # -> practiceGuidance.rules
    if not work_session_rule.slug:
        return None
    practice = self._practice_guidance(work_session_rule)
    if practice is None:
        return None
    for bag in self._practice_rule_bags(practice):
        found = bag.entries.get(work_session_rule.slug)
        if isinstance(found, Rule):
            return found
    return None

def _matching_rules(
    self, payload: dict[str, Any] | None = None
) -> list[WorkSessionRule]:
    # match when rule.guidance is empty or equals that generate's guidance
    # and rule.fidelity is empty or equals that generate's fidelity
    # last fail at exclude turns ago or older → not injected
    # same match for specific, practice-wide, and global
    data = payload or {}
    guidances = self._names(
        data.get("injected_practices") or data.get("guidance")
    )
    fidelities = self._names(
        data.get("injected_fidelities") or data.get("fidelity")
    )
    injected_slugs = self._injected_slugs(
        (data.get("additional_context") or "").strip()
    )
    matched = [
        rule
        for rule in self
        if isinstance(rule, WorkSessionRule)
        and rule.last_fail < self.exclude
        and self._in_injected_set(rule, injected_slugs, guidances, fidelities)
    ]
    matched.sort(key=lambda rule: rule.star, reverse=True)
    return matched

def _place_by_star(self, work_session_rule: WorkSessionRule) -> None:
    ranked = sorted(
        (
            rule
            for rule in self.entries.values()
            if isinstance(rule, WorkSessionRule)
        ),
        key=lambda rule: rule.star,
        reverse=True,
    )
    self.entries = {rule.slug: rule for rule in ranked}

def _apply_practice_rule(self, work_session_rule: WorkSessionRule) -> None:
    practice_rule = self._matching_practice_rule(work_session_rule)
    if practice_rule is None:
        return
    if not work_session_rule.slug:
        work_session_rule.slug = practice_rule.slug
    if not work_session_rule.body:
        work_session_rule.body = practice_rule.body

def _practice_guidance(self, work_session_rule: WorkSessionRule) -> PracticeGuidance | None:
    name = work_session_rule.guidance
    if not name:
        return None
    from harness.agent_tools.agent_tools import AgentToolSet

    module = name.replace("-", "_")
    class_name = "".join(part.title() for part in module.split("_"))
    return AgentToolSet.instantiate(
        f"practices.{module}.{module}:{class_name}"
    )

def _practice_rule_bags(self, practice: PracticeGuidance) -> list[RulesCollection]:
    bags = [practice.rules]
    fidelities = getattr(practice, "fidelities", None)
    if fidelities is None:
        return bags
    for child in fidelities:
        child_rules = getattr(child, "rules", None)
        if isinstance(child_rules, RulesCollection):
            bags.append(child_rules)
    return bags

def _last_chat_injected_path(self) -> Path | None:
    path = getattr(self.parent, "path", None)
    if path is None:
        return None
    return Path(path).parent / "last-chat-injected-rules.md"

def _injected_slugs(self, injected: str) -> set[str]:
    slugs: set[str] = set()
    for line in injected.splitlines():
        stripped = line.strip()
        if re.match(r"^[-*]\s+", stripped):
            slugs.add(Rule.from_bullet(stripped).slug)
    return slugs

def from_markdown(cls, text: str, fidelity: str | None = None) -> WorkSessionRule:
    lines = text.splitlines()
    rule = cls.from_bullet(lines[0] if lines else "", fidelity=fidelity)
    for line in lines[1:]:
        rule.apply_field(line)
    return rule

def from_bullet(cls, text: str, fidelity: str | None = None) -> WorkSessionRule:
    parsed = Rule.from_bullet(text, fidelity=fidelity)
    return cls(slug=parsed.slug, body=parsed.body, fidelity=parsed.fidelity)

def apply_field(self, line: str) -> None:
    field = self._field(line)
    if field is None:
        return
    name, value = field
    if name == "star":
        self.star = int(value or "0")
    elif name == "guidance":
        self.guidance = value or None
    elif name == "fidelity":
        self.fidelity = value or None
    elif name == "mistake":
        self.examples.add(Example(mistake=value))
    elif name == "correction":
        if self.examples:
            self.examples[-1].correction = value
        else:
            self.examples.add(Example(correction=value))
    elif name == "last-fail":
        self.last_fail = int(value or "0")

def _field(line: str) -> tuple[str, str] | None:
    if not line[:1].isspace() or ":" not in line:
        return None
    name, value = line.strip().split(":", 1)
    name = name.strip()
    if name not in (
        "star",
        "guidance",
        "fidelity",
        "mistake",
        "correction",
        "last-fail",
    ):
        return None
    return name, value.strip()

def __init__(self, mistake: str = "", correction: str = "") -> None:
    self.mistake = mistake
    self.correction = correction

def matching(
    self,
    export_name: str,
    file_path: str,
) -> List["Example"]:
    index = self._index
    export_lower = export_name.lower()
    if export_lower in index:
        return index[export_lower]
    stem = Path(file_path).stem.replace(".examples", "").replace("-", " ")
    if stem.lower() in index:
        return index[stem.lower()]
    out: List[Example] = []
    for examples in index.values():
        for example in examples:
            if export_lower in example.name.lower() or example.name.lower() in export_lower:
                out.append(example)
    return out

def wire_demonstrates(self, graph: "PracticeGraph", entries: List[dict]) -> None:
    self._index: Dict[str, List[Example]] = {}
    for example in graph.nodes_of_type(Example):
        self._index.setdefault(example.name.lower(), []).append(example)
    for entry in entries:
        self._wire_demonstrates_entry(graph, entry)

def _wire_demonstrates_entry(self, graph: "PracticeGraph", entry: dict) -> None:
    self._demonstrate_entry = entry
    for class_name in entry.get("demonstrates") or []:
        self._demonstrate_class(graph, class_name)

def _demonstrate_class(self, graph: "PracticeGraph", class_name: str) -> None:
    owned = graph.class_named(class_name)
    if owned is None:
        return
    entry = self._demonstrate_entry
    for example in self.matching(entry.get("export_name") or "", entry.get("file") or ""):
        example.demonstrates(owned)

def add(self, example: Example) -> Example:
    self.entries.append(example)
    return example

def _git(self) -> GitRepo:
    session = self.work_session
    if session is not None:
        return session.git
    root = Repo(Path.cwd()).find_root()
    if root is None:
        raise GitConnectError("work session lives at the repository root")
    return GitRepo(root)

def _ensure_named(self) -> None:
    if not self.context_tool and self.tool_keys:
        self.context_tool = self.tool_keys[0]
    if (self.message or "").strip():
        return
    if self.subject:
        self.message = self._compact_subject(self.subject) or self.subject.strip()
        return
    parts = [p for p in (self.context_tool, self.action, self.utility) if p]
    self.message = " ".join(parts) if parts else "checkpoint"

def _trailers(self) -> dict[str, str]:
    trailers: dict[str, str] = {}
    if self.context_tool:
        trailers["Context-Tool"] = self.context_tool
    if self.action:
        trailers["Action"] = self.action
    if self.utility:
        trailers["Utility"] = self.utility
    compact = self._compact_subject(self.subject)
    if compact:
        trailers["Subject"] = compact
    return trailers

def bind_from_tool(self, tool: Any, *, action: str = "") -> None:
    key = getattr(tool, "context_index_key", "") or getattr(
        type(tool), "context_index_key", ""
    )
    if key:
        self.context_tool = key
        if key not in self.tool_keys:
            self.tool_keys.append(key)
    if action:
        self.action = action
    artifact = getattr(tool, "artifact_path", "") or ""
    if artifact and not self.subject:
        self.subject = str(artifact)

def _note_turn(self, git: GitRepo, sha: str) -> None:
    payload = {
        "turn_id": self.id,
        "context_tool": self.context_tool,
        "action": self.action,
        "utility": self.utility,
        "subject": self._compact_subject(self.subject),
        "message": self.message,
    }
    if self.tool_calls:
        payload["tool_calls"] = "; ".join(
            f"{c.toolset}.{c.name}" for c in self.tool_calls[:12]
        )
    git.note(sha, payload, ref=self.TURN_NOTES_REF)

def _commit_payload(change: TurnCommit | None) -> dict[str, Any] | None:
    if change is None:
        return None
    return {
        "name": change.name,
        "branch": change.branch,
        "session_name": change.branch,
        "context_tool": change.context_tool,
        "action": change.action,
        "utility": change.utility,
        "subject": change.subject,
        "sha": change.sha,
    }

def __init__(
    self,
    root: str | Path,
    *,
    memory: bool = False,
    owner: str = "",
    repo_name: str = "",
) -> None:
    self.root = Path(root).resolve()
    self.default_branch = "main"
    self._memory = memory
    self._owner = owner
    self._repo_name = repo_name
    self._project: Project | None = None
    self._tickets: dict[int, Ticket] = {}
    self._ticket_project_state: dict[int, str] = {}
    self._ticket_project_theme: dict[int, str] = {}
    self._ticket_project_fields: dict[int, dict[str, str]] = {}
    self._ticket_children: dict[int, list[int]] = {}
    self._ticket_parents: dict[int, int] = {}
    self._ticket_comments: dict[int, list[str]] = {}
    self._closed_tickets: set[int] = set()
    self._archived_project_tickets: set[int] = set()
    self._annotated_tag_target = "HEAD"
    if memory:
        self._init_memory_state()

def open(cls, start: str | Path) -> Repo:
    root = cls(start).find_root()
    if root is None:
        raise GitConnectError(f"not a git clone: {start!r}")
    return cls(root)

def push(self) -> None:
    if self._memory:
        self._pushes.append(self.current_branch)
        return
    self._git( "push", "-u", "origin", self.current_branch)

def fetch(self) -> None:
    if self._memory:
        self._fetches.append("origin")
        return
    self._git("fetch", "origin")

def write_annotated_tag(self, name: str, message: str) -> None:
    name = (name or "").strip()
    if not name:
        raise ValueError("annotated tag requires a name")
    if self._memory:
        self._annotated_tags[name] = message
        return
    self._git("tag", "-f", "-a", name, "-m", message, self._annotated_tag_target)

def checkout_or_create(self, name: str) -> str:
    if self.current_branch == name:
        return name
    if self.is_dirty():
        raise DirtyBranchSwitchError(self.current_branch, name)
    if self._memory:
        self._branch_names.add(name)
        self._branch = name
        return name
    existing = self._git( "branch", "--list", name)
    if existing:
        self._git( "checkout", name)
    else:
        self._git( "checkout", "-b", name)
    return name

def _init_memory_state(self) -> None:
    self._branch_names: set[str] = {"main"}
    self._branch = "main"
    self._commit = "sha-init"
    self._commits: list[tuple[list[str], str]] = []
    self._pushes: list[str] = []
    self._dirty = False
    self._notes: dict[str, dict[str, str]] = {}
    self._project_links: list[tuple[str, int, str]] = []
    self._org_issue_types: list[dict[str, str]] = []
    self._worktrees: list[Worktree] = [Worktree(self.root, "main")]
    self._fetches: list[str] = []
    self._pulls: list[str] = []
    self._stash = False
    self._annotated_tags: dict[str, str] = {}
    self._notes_by_ref: dict[tuple[str, str], dict[str, str]] = {}

def find_root(self) -> Path | None:
    current = self.root
    if current.is_file():
        current = current.parent
    for candidate in (current, *current.parents):
        if (candidate / ".git").exists():
            return candidate
    return None

def current_branch(self, name: str) -> None:
    if self.is_dirty() and name != self.current_branch:
        raise DirtyBranchSwitchError(self.current_branch, name)
    if self._memory:
        if name not in self._branch_names:
            raise GitConnectError(f"unknown branch {name}")
        self._branch = name
        return
    self._git( "checkout", name)

def is_dirty(
    self, path: str | Path | None = None, *, untracked: bool = True
) -> bool:
    if self._memory:
        return self._dirty
    args = [
        "status",
        "--porcelain",
        "--untracked-files=normal" if untracked else "--untracked-files=no",
    ]
    if path is not None:
        args.extend(["--", self._rel(path)])
    return any(
        not self._is_runtime_log(line)
        for line in self._git(*args).splitlines()
        if line.strip()
    )

def mark_dirty(self, dirty: bool = True) -> None:
    if not self._memory:
        raise RuntimeError("mark_dirty is only supported on Repo.memory()")
    self._dirty = dirty

def create_branch(self, name: str) -> None:
    if self._memory:
        self._branch_names.add(name)
        return
    self._git("branch", name)

def has_unpushed_commits(self) -> bool:
    if self._memory:
        return False
    try:
        count = self._git("rev-list", "@{upstream}..HEAD", "--count").strip()
        return int(count or "0") > 0
    except GitConnectError:
        return False

def list_worktrees(self) -> list[Worktree]:
    if self._memory:
        return list(self._worktrees)
    trees: list[Worktree] = []
    path = ""
    branch = ""
    for line in self._git("worktree", "list", "--porcelain").splitlines():
        path, branch, trees = self._accumulate_worktree_line(
            line, path, branch, trees
        )
    return self._flush_worktree(
        Worktree(Path(path), branch) if path else None, trees
    )

def _flush_worktree(
    self, tree: Worktree | None, trees: list[Worktree]
) -> list[Worktree]:
    if tree is None:
        return trees
    return trees + [tree]

def _branch_from_porcelain(self, line: str) -> str:
    ref = line[len("branch ") :]
    if ref.startswith("refs/heads/"):
        return ref[len("refs/heads/") :]
    return ref

def worktree_for(self, branch: str) -> Worktree | None:
    wanted = (branch or "").strip()
    for tree in self.list_worktrees():
        if tree.branch == wanted:
            return tree
    return None

def add_worktree(self, path: str | Path, branch: str) -> Path:
    dest = Path(path)
    existing = self.worktree_for(branch)
    if existing is not None:
        return existing.path
    if self._memory:
        self._branch_names.add(branch)
        self._worktrees.append(Worktree(dest, branch))
        return dest
    dest.parent.mkdir(parents=True, exist_ok=True)
    if self._ref_exists(f"refs/heads/{branch}"):
        self._git("worktree", "add", str(dest), branch)
    else:
        start = self._worktree_start_point()
        args = ["worktree", "add", "-b", branch, str(dest)]
        if start:
            args.append(start)
        self._git(*args)
    return dest.resolve()

def _ref_exists(self, ref: str) -> bool:
    try:
        self._git("show-ref", "--verify", "--quiet", ref)
        return True
    except GitConnectError:
        return False

def _worktree_start_point(self) -> str:
    for candidate in (
        f"origin/{self.default_branch}",
        "origin/main",
        "origin/master",
    ):
        try:
            self._git("rev-parse", "--verify", candidate)
            return candidate
        except GitConnectError:
            continue
    return ""

def remove_worktree(self, path: str | Path) -> None:
    dest = Path(path)
    if self._memory:
        self._worktrees = [tree for tree in self._worktrees if tree.path != dest]
        return
    try:
        self._git("worktree", "remove", "--force", str(dest))
    except GitConnectError as exc:
        logger.info("worktree remove failed; forcing directory delete: %s", exc)
        self._force_remove_directory_windows(dest)
    if dest.exists():
        shutil.rmtree(dest, ignore_errors=True)
    if dest.exists():
        self._force_remove_directory_windows(dest)
    if dest.exists():
        return
    try:
        self._git("worktree", "prune")
    except GitConnectError as exc:
        logger.info("worktree prune failed: %s", exc)

def _force_remove_directory_windows(self, path: Path) -> bool:
    """Last resort when git/shutil cannot delete a locked checkout (Windows only)."""
    if os.name != "nt":
        return False
    target = path.resolve()
    if not target.exists():
        return True
    user = os.environ.get("USERNAME", "").strip()
    if not user:
        return False
    self._take_windows_ownership(target, user)
    self._rmtree_logged(target)
    if target.exists():
        self._powershell_remove_item(target)
    return not target.exists()

def _take_windows_ownership(self, target: Path, user: str) -> None:
    for args in (
        ("takeown", "/f", str(target), "/r", "/d", "y"),
        ("icacls", str(target), "/grant", f"{user}:(F)", "/t"),
    ):
        try:
            subprocess.run(list(args), capture_output=True, check=False)
        except OSError as exc:
            logger.info("windows ownership command failed: %s", exc)

def _rmtree_logged(self, target: Path) -> None:
    try:
        shutil.rmtree(target, ignore_errors=True)
    except OSError as exc:
        logger.info("rmtree failed for %s: %s", target, exc)

def _powershell_remove_item(self, target: Path) -> None:
    try:
        subprocess.run(
            [
                "powershell",
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                (
                    f'Remove-Item -LiteralPath "{target}" '
                    "-Recurse -Force -ErrorAction SilentlyContinue"
                ),
            ],
            capture_output=True,
            check=False,
        )
    except OSError as exc:
        logger.info("powershell Remove-Item failed for %s: %s", target, exc)

def pull(self) -> None:
    if self._memory:
        self._pulls.append(self.current_branch)
        return
    self._git("pull", "--ff-only")

def fetch_pull(self) -> None:
    self.fetch()
    self.pull()

def push_to(self, branch: str) -> None:
    if self._memory:
        self._pushes.append(branch)
        return
    self._git("push", "origin", f"HEAD:{branch}")

def has_stash(self) -> bool:
    if self._memory:
        return self._stash
    return bool(self._git("stash", "list"))

def clear_stash(self) -> None:
    """Drop every stash entry. Session close must not leave worktrees for stash."""
    if self._memory:
        self._stash = False
        return
    if not self.has_stash():
        return
    self._git("stash", "clear")

def read_notes(self, sha: str, *, ref: str | None = None) -> dict[str, str]:
    note_ref = ref or self.NOTES_REF
    if self._memory:
        keyed = self._notes_by_ref.get((note_ref, sha))
        if keyed is not None:
            return dict(keyed)
        if note_ref == self.NOTES_REF:
            return dict(self._notes.get(sha, {}))
        return {}
    try:
        raw = self._git("notes", f"--ref={note_ref}", "show", sha)
    except GitConnectError:
        return {}
    return Commit(sha="", message=raw).note_payload()

def _memory_mistakes(self, wanted: set[str]) -> list[dict[str, str]]:
    found: list[dict[str, str]] = []
    for sha, payload in self._notes.items():
        if payload.get("entry_id") in wanted:
            row = dict(payload)
            row.setdefault("introducing_commit", sha)
            found.append(row)
    return found

def _listed_mistakes(
    self, note_ref: str, wanted: set[str]
) -> list[dict[str, str]]:
    found: list[dict[str, str]] = []
    listing = self._git("notes", f"--ref={note_ref}", "list")
    for line in listing.splitlines():
        parts = line.split()
        if len(parts) < 2:
            continue
        sha = parts[1]
        payload = self.read_notes(sha, ref=note_ref)
        if payload.get("entry_id") in wanted:
            payload.setdefault("introducing_commit", sha)
            found.append(payload)
    return found

def _github_ticket(self, ref: str) -> Ticket | None:
    number = Ticket.from_number(ref)
    try:
        raw = self.run_gh(
            "issue",
            "view",
            str(number),
            "--json",
            "number,title,body,url,state,parent,subIssues",
        )
    except GhConnectError as exc:
        message = str(exc).lower()
        if "could not resolve" in message or "not found" in message:
            return None
        raise
    payload = json.loads(raw or "{}")
    if not payload:
        return None
    return self._ticket_from_payload(payload)

def _register_on_workspace(plan: Plan) -> None:
    workspace = plan.workspace
    if workspace is None:
        return
    plans = getattr(workspace, "plans", None)
    if plans is None:
        workspace.plans = []  # type: ignore[attr-defined]
        plans = workspace.plans
    plans.append(plan)

def _load_prebaked_turns(self, workflow_name: str) -> None:
    for template in _PREBAKED_WORKFLOWS.get(workflow_name, []):
        self.add_turn(
            action=template.action,
            fidelity=template.fidelity,
            format=template.format,
            context=template.context,
            tool_keys=list(template.tool_keys),
        )

def add_turn(self, turn: Turn | None = None, **fields: Any) -> Turn:
    if turn is None:
        turn = Turn()
    for field_name, field_value in fields.items():
        setattr(turn, field_name, field_value)
    if not hasattr(turn, "state") or turn.state is None:  # type: ignore[attr-defined]
        turn.state = TicketState.backlog()  # type: ignore[attr-defined]
    if not hasattr(turn, "judge_checkpoint"):
        turn.judge_checkpoint = None  # type: ignore[attr-defined]
    if not hasattr(turn, "hil_check"):
        turn.hil_check = None  # type: ignore[attr-defined]
    self._turns.append(turn)
    return turn

def _apply_context(self, built: Plan, context: str) -> None:
    if not context.strip():
        return
    for turn in built.turns:
        existing = getattr(turn, "context", "") or ""
        turn.context = f"{existing} {context}".strip() if existing else context

def execute_turn(self) -> Turn | None:
    turn = self._open_turn()
    if turn is None:
        return None
    if hasattr(turn, "perform_turn"):
        turn.perform_turn()
    if not getattr(turn, "result", ""):
        turn.result = turn.action or "executed"
    return turn

def _open_turn(self) -> Turn | None:
    session = self._plan.work_session
    if session is None:
        return None
    return session.open_turn

def validate_with_human(self, validation: str) -> HILCheck | None:
    turn = self._open_turn()
    if turn is None:
        return None
    return self._plan.attachments.add_hil(turn, HILCheck(validation=validation))

def evaluate_results(self, judge_result: str) -> JudgeCheckpoint | None:
    turn = self._open_turn()
    if turn is None:
        return None
    check = getattr(turn, "judge_checkpoint", None)
    if check is None:
        return None
    check.judge_result = judge_result
    return check

def review_progress(self) -> ProgressView | None:
    turn = self._open_turn()
    if turn is None:
        return None
    hil = getattr(turn, "hil_check", None)
    judge = getattr(turn, "judge_checkpoint", None)
    return ProgressView(
        state=getattr(turn, "state", None),
        result=getattr(turn, "result", None),
        hil_validation=getattr(hil, "validation", None) if hil else None,
        judge_result=getattr(judge, "judge_result", None) if judge else None,
    )

def advance_turn(self) -> Turn | None:
    session = self._plan.work_session
    turn = self._open_turn()
    if session is None or turn is None:
        return None
    turn.state = TicketState.done()  # type: ignore[attr-defined]
    turn.finish(
        prompt=getattr(turn, "prompt", ""),
        result=getattr(turn, "result", ""),
        context=getattr(turn, "context", ""),
    )
    return self._promote_next(session, turn)

def _promote_next(self, session: WorkSession, current: Turn) -> Turn | None:
    turns = self._plan.turns
    idx = turns.index(current) if current in turns else -1
    nxt = turns[idx + 1] if 0 <= idx < len(turns) - 1 else None
    if nxt is not None:
        nxt.state = TicketState.in_progress()  # type: ignore[attr-defined]
        session.open_turn = nxt
    else:
        session.open_turn = None
    return nxt

def fix_and_rerun(self, mistake: str, correction: str) -> Turn | None:
    turn = self._open_turn()
    if turn is None:
        return None
    if hasattr(turn, "record_mistake"):
        turn.record_mistake(mistake)
    if hasattr(turn, "record_correction"):
        turn.record_correction(correction)
    return self.execute_turn()

def enough_context(body: str) -> bool:
    text = (body or "").strip()
    if not text:
        return False
    lowered = text.lower()
    if any(marker in lowered for marker in _ENOUGH_MARKERS):
        return True
    return len(text) >= _MIN_ENOUGH_CHARS

def parse_theme(context: str) -> str:
    text = (context or "").strip()
    if not text:
        return ""
    match = _THEME_RE.search(text)
    if match:
        return match.group("theme").strip()
    if text.startswith("theme:"):
        return text.split(":", 1)[1].strip()
    return text

def load_state(self) -> SmallWorkState | None:
    path = self._state_path
    if not path.is_file():
        return None
    raw = json.loads(path.read_text(encoding="utf-8"))
    return SmallWorkState(**raw)

def clear_state(self) -> None:
    path = self._state_path
    if path.is_file():
        path.unlink()

def _complete_issue(self, state: SmallWorkState, issue: ThemedIssue) -> None:
    # Logical Workflow spine: Backlog → In Progress → Done (no live branch).
    state.report.append(
        {
            "number": issue.number,
            "title": issue.title,
            "outcome": "done",
            "context_enough": issue.context_enough,
            "ticket_flow": ["Backlog", "In Progress", "Done"],
        }
    )

def edit_hil(self, turn: Turn, hil: HILCheck) -> HILCheck:
    turn.hil_check = hil  # type: ignore[attr-defined]
    return hil

def edit_judge(self, turn: Turn, rubric: str) -> JudgeCheckpoint:
    check = getattr(turn, "judge_checkpoint", None)
    if check is None:
        check = JudgeCheckpoint(rubric=rubric)
    else:
        check.rubric = rubric
    turn.judge_checkpoint = check  # type: ignore[attr-defined]
    return check

def render(
    self, canonical: StoryMap, previous: Optional[Dict[str, str]] = None
) -> Dict[str, str]:
    tree = render_ts_tree(canonical, tests_root=self.tests_root, include_shared=True)
    if previous:
        for path, body in list(tree.items()):
            if path in previous and self._is_gwt_leaf(path):
                tree[path] = self._preserve_hand_written(previous[path], body)
    return tree

def parse(self, external: Dict[str, str]) -> StoryMap:
    if not isinstance(external, dict):
        raise CodeStoryMapError("TypeScript story map parse expects a path->content dict")
    story_map = self._make_story_map()
    seen: set[tuple[str, ...]] = set()
    for path, content in sorted(external.items()):
        if not self._is_gwt_leaf(path):
            continue
        parts = path.strip("/").replace("\\", "/").split("/")
        stripped = self.strip_tests_root_prefix(parts)
        if stripped is None:
            continue
        parts = stripped
        if len(parts) < 3:
            continue
        filename = parts[-1]
        story_slug = self._story_slug_from_filename(filename)
        if not story_slug:
            continue
        epic_slug, sub_slugs = parts[0], parts[1:-1]
        if sub_slugs and sub_slugs[-1] == story_slug:
            sub_slugs = sub_slugs[:-1]
        if not sub_slugs:
            continue
        key = (epic_slug, *sub_slugs, story_slug)
        if key in seen:
            continue
        seen.add(key)
        epic = self._ensure_epic(story_map, epic_slug)
        sub = self._ensure_sub_path(epic, sub_slugs)
        story = self._parse_story_file(content, story_slug)
        if story:
            sub.stories.append(story)
    return story_map

def from_workspace(cls, root: Path) -> List[TestSuite]:
    """Find and parse all TypeScript test files under *root*."""
    root = Path(root).resolve()
    if root.is_file():
        if root.suffix in (".ts", ".tsx"):
            return [cls()._parse_file(root, root.parent)]
        return []
    seen: set = set()
    suites: List[TestSuite] = []
    for pattern in _GLOBS:
        for p in root.glob(pattern):
            if p in seen or not p.is_file():
                continue
            seen.add(p)
            suites.append(cls()._parse_file(p, root))
    return suites

def _ensure_epic(self, story_map: StoryMap, epic_slug: str) -> Epic:
    for epic in story_map.epics:
        if to_kebab(epic.name) == epic_slug:
            return epic
    epic = self._make_epic(epic_slug.replace("-", " ").title(), len(story_map.epics) + 1)
    story_map.append_epic(epic)
    return epic

def _tier(self, name: str) -> Tier:
    m = _TIER_TEST.search(name)
    if m:
        return Tier(m.group("tier"))
    # Acceptance layout: `{story_snake}_story.test.ts`.
    if name in {"story-test.ts", "givens.ts"} or name.startswith("story-test."):
        return Tier("")
    m = _TIER_SEAM.search(name)
    if m and m.group("tier") not in {"ts", "tsx"}:
        return Tier(m.group("tier"))
    return Tier("")

def _imports_real(self, text: str) -> bool:
    for line in text.splitlines():
        m = re.match(r"^\s*import\s.+from\s+['\"](?P<mod>[^'\"]+)['\"]", line)
        if not m:
            continue
        mod = m.group("mod")
        if mod.startswith(("vitest", "jest", "@testing-library")):
            continue
        return True
    return False

def _is_gwt_leaf(self, path: str) -> bool:
    name = path.replace("\\", "/").rsplit("/", 1)[-1]
    if name in _SKIP_NAMES or name.endswith("-helper.ts"):
        return False
    if "/examples/" in path.replace("\\", "/"):
        return False
    return name.endswith(_STORY_TEST_SUFFIX)

def _story_slug_from_filename(self, name: str) -> str | None:
    if not name.endswith(_STORY_TEST_SUFFIX):
        return None
    stem = name[: -len(_STORY_TEST_SUFFIX)]
    return stem.replace("_", "-")

def __init__(self, repo: Repo, name: str) -> None:
    self._repo = repo
    self.name = name

def checkout(self) -> Branch:
    self._repo.checkout_or_create(self.name)
    return self

def from_message(cls, text: str) -> CliAgentBinding:
    data = Commit(sha="", message=text).note_payload()
    binding = cls()
    return cls(
        status=(data.get("status") or "closed").strip() or "closed",
        doer=(data.get("doer") or "").strip(),
        doer_pid=binding._as_pid(data.get("doer_pid")),
        judge=(data.get("judge") or "").strip(),
        judge_pid=binding._as_pid(data.get("judge_pid")),
    )

def pid_is_alive(self, pid: int) -> bool:
    if pid <= 0:
        return False
    if os.name == "nt":
        return self._windows_pid_is_alive(pid)
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True

def _as_pid(self, raw: str | None) -> int:
    text = (raw or "").strip()
    if not text.isdigit():
        return 0
    return int(text)

def write_tag(self, repo: Repo, branch_name: str) -> None:
    repo._annotated_tag_target = branch_name
    repo.write_annotated_tag(
        repo.cli_agent_tag_name(branch_name),
        self.message(),
    )

def trailers(self) -> dict[str, str]:
    lines = (self.message or "").splitlines()
    if not lines:
        return {}
    data: dict[str, str] = {}
    for line in lines[1:]:
        if ": " not in line:
            continue
        key, value = line.split(": ", 1)
        data[key.strip()] = value.strip()
    return data

def note_payload(self) -> dict[str, str]:
    out: dict[str, str] = {}
    for line in (self.message or "").splitlines():
        if ": " not in line:
            continue
        key, value = line.split(": ", 1)
        out[key.strip()] = value
    return out

def state_named(self, name: str) -> TicketState:
    options = self.status_option_names()
    resolved = self.github_status_option(name, options)
    candidates = options or [state.name for state in self.states]
    for state_name in candidates:
        if state_name.lower() == resolved.lower():
            return TicketState(state_name)
    raise ValueError(
        f"unknown project state: {name!r}; board columns: {candidates}"
    )

def refresh_states(self) -> list[str]:
    """Load Status column names from GitHub and replace the in-memory state list."""
    names = self.status_option_names()
    if names:
        self.states = [TicketState(name) for name in names]
    return names

def github_status_option(
    cls, state_name: str, option_names: list[str] | tuple[str, ...] | None = None
) -> str:
    """Pick a Status option: exact match first, then a known synonym."""
    wanted = (state_name or "").strip()
    names = [str(item).strip() for item in (option_names or ()) if str(item).strip()]
    if wanted in names:
        return wanted
    aliases = GITHUB_STATUS_ALIASES.get(wanted, ())
    for alias in aliases:
        if not names or alias in names:
            return alias
    return wanted

def _project_scope_error(self, exc: GhConnectError) -> GhConnectError:
    message = str(exc)
    if "read:project" in message or "missing required scopes" in message:
        return GhConnectError(f"{message} {GH_PROJECT_SCOPES_HINT}")
    return exc

def _option_names_for_field(self, field_name: str, payload: object) -> list[str]:
    fields = payload
    if isinstance(payload, dict):
        fields = payload.get("fields") or payload.get("items") or []
    names: list[str] = []
    for field in fields or []:
        names.extend(self._labels_from_field(field, field_name))
    return names

def _memory_ticket_rows(self) -> list[dict[str, str | int]]:
    rows: list[dict[str, str | int]] = []
    for number, ticket in self._repo.tickets.items():
        status = self._repo._ticket_project_state.get(number, "")
        if not status:
            continue
        rows.append(
            {
                "number": number,
                "title": ticket.title,
                "url": ticket.url,
                "status": status,
            }
        )
    return rows

def _ticket_rows_from_items(
    self, items: list[dict[str, object]]
) -> list[dict[str, str | int]]:
    rows: list[dict[str, str | int]] = []
    for item in items:
        content = item.get("content")
        if not isinstance(content, dict) or content.get("type") != "Issue":
            continue
        rows.append(
            {
                "number": int(content.get("number") or 0),
                "title": str(content.get("title") or item.get("title") or ""),
                "url": str(content.get("url") or ""),
                "status": str(item.get("status") or ""),
            }
        )
    return rows

def _option_id_for_name(
    self, field_options: list[dict[str, object]], name: str
) -> str:
    wanted = (name or "").strip()
    for option in field_options:
        label = str(option.get("name") or "").strip()
        if label == wanted or label.lower() == wanted.lower():
            option_id = str(option.get("id") or "")
            if option_id:
                return option_id
    raise ValueError(f"unknown project option: {name!r}")

def github_theme_option(
    cls, theme: str, option_names: list[str] | tuple[str, ...] | None = None
) -> str:
    """Pick a project Theme option matching the slug (case-insensitive)."""
    wanted = theme_slug(theme)
    if not wanted:
        return ""
    names = [str(item).strip() for item in (option_names or ()) if str(item).strip()]
    if wanted in names:
        return wanted
    lower = wanted.lower()
    for name in names:
        if name.lower() == lower:
            return name
    return wanted

def _labels_from_field(self, field: object, field_name: str) -> list[str]:
    if not isinstance(field, dict):
        return []
    if str(field.get("name") or "") != field_name:
        return []
    names: list[str] = []
    for option in field.get("options") or []:
        if isinstance(option, dict):
            label = str(option.get("name") or "").strip()
        else:
            label = str(option).strip()
        if label:
            names.append(label)
    return names

def close(self) -> None:
    repo = self._require_repo("close")
    if repo.in_memory:
        if not repo.has_ticket(self.number):
            raise TicketNotFoundError(f"GitHub issue not found: {self.number}")
        repo.mark_closed(self.number)
        self.data["closed"] = "true"
        return
    repo.run_gh("issue", "close", str(self.number))
    self.data["closed"] = "true"

def update(self, *, title: str | None = None, body: str | None = None) -> Ticket:
    """Update supplied issue fields while leaving omitted fields unchanged."""
    repo = self._require_repo("update")
    arguments = ["issue", "edit", str(self.number)]
    if title is not None:
        arguments.extend(["--title", title])
    if body is not None:
        arguments.extend(["--body-file", "-"])
    if len(arguments) == 3:
        return self
    if not repo.in_memory:
        repo.run_gh(*arguments, stdin=body)
    self.title = title if title is not None else self.title
    self.body = body if body is not None else self.body
    return self

def from_number(cls, ref: str | int) -> int:
    if isinstance(ref, int):
        return ref
    cleaned = str(ref).strip()
    if not cleaned:
        raise ValueError(f"not a GitHub issue reference: {ref!r}")
    if cleaned.startswith("#"):
        return int(cleaned[1:])
    if "#" in cleaned:
        suffix = cleaned.rsplit("#", 1)[-1]
        if _ISSUE_NUMBER.match(suffix):
            return int(suffix)
    if "/issues/" in cleaned:
        suffix = cleaned.rstrip("/").split("/")[-1]
        if _ISSUE_NUMBER.match(suffix):
            return int(suffix)
    if _ISSUE_NUMBER.match(cleaned):
        return int(cleaned)
    raise ValueError(f"not a GitHub issue reference: {ref!r}")

def bind_repo(self, repo: Repo) -> Ticket:
    self._repo = repo
    return self

def add_label(self, name: str) -> Ticket:
    """Put a label on this issue (sidebar chip). Empty name is a no-op."""
    label = (name or "").strip()
    if not label:
        return self
    repo = self._require_repo("add_label")
    if label not in self.labels:
        self.labels.append(label)
    if repo.in_memory:
        return self
    repo.run_gh("label", "create", label, "--force")
    repo.run_gh("issue", "edit", str(self.number), "--add-label", label)
    return self

def remove_label(self, name: str) -> Ticket:
    """Take a label off this issue. Empty or absent name is a quiet no-op."""
    label = (name or "").strip()
    if not label:
        return self
    repo = self._require_repo("remove_label")
    if label in self.labels:
        self.labels.remove(label)
    if repo.in_memory:
        return self
    repo.run_gh("issue", "edit", str(self.number), "--remove-label", label)
    return self

def project_item_id(self, project: Project) -> str:
    try:
        return project.item_id_for(self.number)
    except ValueError:
        logger.info("adding missing project item for issue %s", self.number)
    item_id = project.add_item(self.url)
    if not item_id:
        raise GhConnectError("Could not add issue to project.")
    return item_id

def attach_environment(self, environment: Environment, root: "Transformer" | None = None) -> None:
    self._environment = environment
    self._file_root = root or self
    if root is None:
        self._files = {}
    for child in self.children():
        if isinstance(child, Transformer):
            child.attach_environment(environment, self._file_root)

def _ensure_file_store(self) -> None:
    if getattr(self, "_file_root", None) is None:
        self._file_root = self
        self._files = {}
    if getattr(self, "_environment", None) is None:
        self._environment = None

def _apply_template(self, template) -> None:
    path = self._output_path()
    if not path:
        return
    self._file_root._files[path] = template.render(node=self)

def _render_child(self, child: Any, kind: str) -> None:
    if not isinstance(child, Transformer):
        return
    child._tests_folder = self._child_folder()
    child.render(kind)

def determine_practices_from(self, sketch: str) -> list:
    practices = []
    if _has_lens(sketch, "stories:"):
        practices.append(Stories())
    return practices

def parse(self, text: str) -> "MarkdownStoryMap":
    if not isinstance(text, str) or text.strip() == "":
        return MarkdownStoryMap()
    lines = text.splitlines()
    if self._looks_like_scenario_document(lines):
        return self._parse_scenario_document(text)
    self._guard_has_structure(lines)
    if self._contains_outline_structure(lines):
        return self._parse_outline_lines(lines)
    return self._parse_lines(lines)

def from_workspace(cls, root: "Path") -> Optional["MarkdownStoryMap"]:
    """Find story-map.md files under *root*, merge, and return; None if absent."""
    root = Path(root).resolve()
    if root.is_file():
        candidates = [root]
    else:
        candidates = (
            [root / "story-map.md"] if (root / "story-map.md").exists()
            else list(root.rglob("story-map.md"))
        )
    if not candidates:
        return None
    merged = cls()
    for md_path in candidates:
        text = md_path.read_text(encoding="utf-8")
        try:
            parsed = cls().parse(text)
        except MarkdownParseError:
            continue
        for epic in parsed.epics:
            merged.epics.append(epic)
        if root.is_file():
            rel = root.name
        else:
            rel = str(md_path.relative_to(root)).replace("\\", "/")
        merged.attach_source_locations(text, rel)
        if not getattr(merged, "source", None):
            from practices.stories.model.source_location import SourceLocation as _SL
            merged.source = _SL(rel, 1)
    return merged if merged.epics else None

def _render_epic(self, epic: MarkdownEpic, lines: List[str], depth: int) -> None:
    lines.append(f"{'#' * depth} {epic.name}")
    factory_line = render_md_factory_line(epic.collected_example_factories())
    if factory_line:
        lines.append(factory_line)
    for sub in epic.sub_epics:
        self._render_sub_epic(sub, lines, depth + 1)

def _render_sub_epic(self, sub: MarkdownSubEpic, lines: List[str], depth: int) -> None:
    lines.append(f"{'#' * depth} {sub.name}")
    for nested in sub.sub_epics:
        self._render_sub_epic(nested, lines, depth + 1)
    for story in sub.stories:
        lines.append(f"- {story.name}")
        for scenario in story.scenarios:
            lines.append(f"  - {scenario.name}")

def attach_source_locations(self, text: str, rel_file: str) -> None:
    """Stamp SourceLocation onto each Epic/SubEpic/Story from the markdown text."""
    lines = text.splitlines()
    is_outline = any(
        _OUTLINE_EPIC_RE.match(l) or _OUTLINE_STORY_RE.match(l) for l in lines
    )
    epic_index = 0
    for i, raw in enumerate(lines, start=1):
        if not raw.strip():
            continue
        m_epic_out = _OUTLINE_EPIC_RE.match(raw)
        m_story_out = _OUTLINE_STORY_RE.match(raw)
        m_heading = _HEADING_RE.match(raw)
        m_bullet = _BULLET_RE.match(raw)

        if m_epic_out:
            indent = len(m_epic_out.group(1)) // 4
            name = self.strip_backticks(m_epic_out.group(2))
            if indent == 0:
                if epic_index < len(self.epics):
                    self.epics[epic_index].source = SourceLocation(rel_file, i)
                    epic_index += 1
            else:
                self._stamp_sub_epic(name, SourceLocation(rel_file, i))
            continue
        if m_story_out:
            name = self.strip_backticks(m_story_out.group(2).split("-->", 1)[-1] if "-->" in m_story_out.group(2) else m_story_out.group(2))
            self._stamp_story(name, SourceLocation(rel_file, i))
            continue
        if is_outline:
            continue
        if m_heading:
            depth = len(m_heading.group(1))
            name = m_heading.group(2).strip()
            if any(name.lower().startswith(p) for p in _DOC_TITLE_PREFIXES):
                continue
            if depth == 1 and epic_index < len(self.epics):
                self.epics[epic_index].source = SourceLocation(rel_file, i)
                epic_index += 1
            elif depth >= 2:
                self._stamp_sub_epic(name, SourceLocation(rel_file, i))
            continue
        if m_bullet:
            self._stamp_story(m_bullet.group(2).strip(), SourceLocation(rel_file, i))

def _should_render_outline(self, story_map: "MarkdownStoryMap", previous: Optional[str]) -> bool:
    if previous and self._contains_outline_structure(previous.splitlines()):
        return True
    for epic in story_map.epics:
        if getattr(epic, "estimate", ""):
            return True
        for sub in epic.sub_epics:
            if self._sub_tree_has_outline_signal(sub):
                return True
    return False

def _contains_outline_structure(self, lines: List[str]) -> bool:
    return any(
        _OUTLINE_EPIC_PATTERN.match(l) or _OUTLINE_STORY_PATTERN.match(l)
        for l in lines
    )

def _sub_tree_has_outline_signal(self, sub: MarkdownSubEpic) -> bool:
    if getattr(sub, "estimate", ""):
        return True
    for nested in sub.sub_epics:
        if self._sub_tree_has_outline_signal(nested):
            return True
    return False

def _render_outline_stories(self, sub: MarkdownSubEpic, story_pad: str) -> None:
    for story in sub.stories:
        actor = story.users[0] if story.users else ""
        name = self.strip_backticks(story.name)
        if actor:
            actor_name = self.strip_backticks(actor)
            self._outline_lines.append(f"{story_pad}(S) {actor_name} --> {name}")
            continue
        self._outline_lines.append(f"{story_pad}(S) --> {name}")

def _guard_has_structure(self, lines: List[str]) -> None:
    for line in lines:
        if (
            _HEADING_PATTERN.match(line) or _BULLET_PATTERN.match(line)
            or _OUTLINE_EPIC_PATTERN.match(line) or _OUTLINE_STORY_PATTERN.match(line)
            or _OUTLINE_ESTIMATE_PATTERN.match(line)
        ):
            return
    raise MarkdownParseError("Not a valid Markdown story map: no recognised structure found")

def _stamp_sub_epic(self, name: str, loc: SourceLocation) -> None:
    for sub in self.all_sub_epics():
        if sub.name == name and not getattr(sub, "source", None):
            sub.source = loc
            return

def _stamp_story(self, name: str, loc: SourceLocation) -> None:
    for story in self.all_stories():
        if story.name == name and not getattr(story, "source", None):
            story.source = loc
            return

def _skip_ignored_section(self) -> bool:
    heading = _HEADING_PATTERN.match(self._raw_line)
    if self._ignored_heading_depth is None:
        return False
    if heading is None:
        return True
    if len(heading.group(1)) > self._ignored_heading_depth:
        return True
    self._ignored_heading_depth = None
    return False

def _accept_map_heading(self) -> bool:
    heading = _HEADING_PATTERN.match(self._raw_line)
    if heading is None:
        return False
    depth = len(heading.group(1))
    name = heading.group(2).strip()
    if self._is_document_title(name):
        return True
    if self._is_non_story_section_heading(name):
        self._ignored_heading_depth = depth
        return True
    if name.lower().startswith("story:"):
        self._append_named_story(name.split(":", 1)[1].strip() or name)
        return True
    if self._is_epic_heading(depth):
        self._begin_epic(name, depth)
        return True
    if self._current_epic is not None:
        self._accept_nested_heading(name, depth)
    return True

def _accept_map_bullet(self) -> bool:
    bullet = _BULLET_PATTERN.match(self._raw_line)
    if bullet is None:
        return False
    indent = len(bullet.group(1)) // 2
    text = bullet.group(2).strip()
    if indent == 0 and self._current_epic is not None:
        self._append_named_story(text)
        return True
    if indent >= 1 and self._current_story is not None:
        self._current_story.scenarios.append(
            MarkdownScenario(text, len(self._current_story.scenarios) + 1, self._current_story.name)
        )
    return True

def _accept_map_numbered(self) -> bool:
    numbered = _NUMBERED_PATTERN.match(self._raw_line)
    if numbered is None or self._current_story is None:
        return False
    text = numbered.group(2).strip()
    text = re.sub(r"^\*\*(WHEN|THEN|AND|BUT)\*\*\s*", "", text, flags=re.IGNORECASE)
    self._current_story.scenarios.append(
        MarkdownScenario(text, len(self._current_story.scenarios) + 1, self._current_story.name)
    )
    return True

def _accept_map_factory_line(self) -> None:
    factories = parse_md_factory_line(self._raw_line.strip())
    if not factories or self._current_epic is None:
        return
    for factory in factories:
        if factory not in self._current_epic.example_factories:
            self._current_epic.example_factories.append(factory)

def _is_document_title(self, name: str) -> bool:
    lower = name.lower()
    return any(lower.startswith(p) for p in _DOC_TITLE_PREFIXES)

def _is_epic_heading(self, depth: int) -> bool:
    if self._current_epic is None:
        return True
    if depth == 1:
        return True
    if self._epic_heading_depth is not None and depth <= self._epic_heading_depth:
        return True
    return False

def _ensure_sub_epic(self) -> MarkdownSubEpic:
    if self._sub_epic_stack:
        return self._sub_epic_stack[-1]
    if self._current_epic is None:
        self._current_epic = MarkdownEpic("Imported", len(self._story_map.epics) + 1)
        self._story_map.epics.append(self._current_epic)
    sub = MarkdownSubEpic(self._current_epic.name, len(self._current_epic.sub_epics) + 1)
    self._current_epic.sub_epics.append(sub)
    self._sub_epic_stack.append(sub)
    return sub

def _accept_outline_story(self) -> bool:
    match = _OUTLINE_STORY_PATTERN.match(self._raw_line)
    if match is None or self._current_epic is None:
        return False
    if not self._sub_epic_stack:
        self._ensure_sub_epic()
    actor, story_name = self._split_outline_story(match.group(2))
    story = MarkdownStory(story_name, len(self._sub_epic_stack[-1].stories) + 1, StoryType.USER)
    if actor:
        story.users = [actor]
    self._sub_epic_stack[-1].stories.append(story)
    return True

def _accept_outline_estimate(self) -> bool:
    match = _OUTLINE_ESTIMATE_PATTERN.match(self._raw_line)
    if match is None:
        return False
    estimate = match.group(2).strip()
    if self._sub_epic_stack:
        self._sub_epic_stack[-1].estimate = estimate
        return True
    if self._current_epic is not None:
        self._current_epic.estimate = estimate
    return True

def __init__(self, always_apply: bool | None = None, globs: str = "") -> None:
    self.always_apply = always_apply
    self.globs = globs

def strip_fence(cls, text: str) -> str:
    from harness.markdown.markdown import strip_yaml_fences

    return strip_yaml_fences(text)

def from_value(cls, value: Any) -> AppliesTo:
    if isinstance(value, cls):
        return value
    if not isinstance(value, dict):
        return cls()
    always = value.get("alwaysApply", value.get("always_apply"))
    globs: Any = value.get("globs", "")
    if not isinstance(globs, str):
        globs = "" if globs is None else str(globs)
    always_apply = None
    if isinstance(always, bool):
        always_apply = always
    elif always not in (None, ""):
        always_apply = str(always).casefold() in {"true", "yes", "1"}
    return cls(always_apply=always_apply, globs=globs)

def validate(self) -> str:
    text = instructions(
        f"Evaluate the current context against this rule ({self.slug}):",
        self.body,
    )
    if self.scanner is not None:
        tools(self.scanner.scan)
        text = text + "\nRun the scanner for this rule."
    return text

def bind_scanner(self, module_dir: Path | None) -> None:
    if module_dir is None:
        return
    script = module_dir / "scanners" / f"{self.slug}_scanner.py"
    if not script.is_file():
        return
    class _BoundRuleScan:
        def scan(self, *args: Any, **kwargs: Any) -> str:
            return str({"ok": True, "violations": [], "rules": [slug]})

    slug = self.slug
    self.scanner = _BoundRuleScan()

def from_bullet(cls, text: str, fidelity: str | None = None) -> Rule:
    line = text.strip().lstrip("-*").strip()
    slug = ""
    body = line
    named = re.match(r"\*\*`?([^`*]+)`?\*\*\s*[—:-]\s*(.+)$", line)
    if named:
        slug = named.group(1).strip()
        body = named.group(2).strip()
    else:
        coded = re.match(r"`([^`]+)`\s*[—:-]\s*(.+)$", line)
        if coded:
            slug = coded.group(1).strip()
            body = coded.group(2).strip()
    if not slug:
        slug = re.sub(r"[^a-z0-9]+", "-", body.casefold()).strip("-") or "rule"
    return cls(slug=slug, body=body, fidelity=fidelity)

def __iter__(self) -> Iterator[Rule]:
    for value in self.entries.values():
        if isinstance(value, RulesCollection):
            yield from value
        else:
            yield value

def matches(self, path: str) -> bool:
    if not path:
        return False
    if self.always_apply and not str(self.glob or "").strip():
        return True
    if not self.glob:
        return False
    posix = Path(path).as_posix()
    name = Path(path).name
    for pattern in (part.strip().strip("\"'") for part in self.glob.split(",")):
        if self._pattern_matches(posix, name, pattern):
            return True
    return False

def _payload_path(self, hook_payload: dict[str, Any]) -> str:
    raw = hook_payload.get("tool_input") or {}
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError:
            return ""
    if not isinstance(raw, dict):
        return ""
    return str(raw.get("path") or raw.get("file_path") or raw.get("target_notebook") or "")

def _owner_practice(self) -> Any:
    node = self.parent
    if node is None:
        return None
    return self._practice_on(node) or self._practice_on(getattr(node, "parent", None))

def _practice_on(self, node: Any) -> Any:
    if node is None:
        return None
    practice = getattr(node, "practice_guidance", None)
    if practice is not None:
        return practice
    if getattr(node, "fidelities", None) is not None:
        return node
    return None

def _rule_bags(self) -> list[RulesCollection]:
    practice = self._owner_practice()
    if practice is None:
        return [self]
    bags: list[RulesCollection] = []
    shared = getattr(practice, "rules", None)
    if isinstance(shared, RulesCollection):
        bags.append(shared)
    fidelities = getattr(practice, "fidelities", None)
    if fidelities is None:
        return bags or [self]
    for child in fidelities:
        child_rules = getattr(child, "rules", None)
        if isinstance(child_rules, RulesCollection):
            bags.append(child_rules)
    return bags

def _unique_bags(self, bags: list[RulesCollection]) -> list[RulesCollection]:
    included: list[RulesCollection] = []
    seen: set[int] = set()
    for bag in bags:
        key = id(bag)
        if key in seen:
            continue
        seen.add(key)
        included.append(bag)
    return included

def _pattern_matches(self, posix: str, name: str, pattern: str) -> bool:
    if not pattern:
        return False
    if Path(posix).match(pattern) or fnmatch.fnmatch(posix, pattern):
        return True
    leaf = pattern.rsplit("/", 1)[-1]
    if leaf in {"", "*", "**"}:
        return False
    return fnmatch.fnmatch(name, leaf)

def _append_original_markdown(
    self, chunks: list[str], seen: set[str], text: str | None
) -> None:
    block = (text or "").strip()
    if not block or block in seen:
        return
    seen.add(block)
    chunks.append(block)

def parse_thin_slice(self, text: str) -> List[MiroIncrement]:
    """Parse a thin-slice SVG back into increment nodes.

    The foreignObject body contains an HTML table; ET parses it with the SVG
    namespace inherited from the root, so all lookups use namespace-agnostic
    tag matching (split on "}" to get local name).
    """
    try:
        root_el = ET.fromstring(
            text.split("\n", 1)[1] if text.startswith("<?") else text
        )
    except ET.ParseError as err:
        raise MiroParseError(f"Not valid SVG: {err}") from err

    fo = self._find_foreign_object(root_el, "table")
    if fo is None:
        raise MiroParseError("No table foreignObject found in thin-slice SVG")

    def _local(el: ET.Element) -> str:
        tag = el.tag
        return tag.split("}")[-1] if "}" in tag else tag

    # Find tbody using namespace-agnostic iteration
    tbody_el: ET.Element | None = None
    for el in fo.iter():
        if _local(el) == "tbody":
            tbody_el = el
            break
    if tbody_el is None:
        return []

    increments: List[MiroIncrement] = []
    order = 1
    for tr_el in tbody_el:
        if _local(tr_el) != "tr":
            continue
        cells = [td_el.text or "" for td_el in tr_el if _local(td_el) == "td"]
        if not cells:
            continue
        inc_name = cells[0].strip()
        if not inc_name:
            continue
        inc = MiroIncrement(inc_name, order)
        for story_name in cells[1:]:
            story_name = story_name.strip()
            if story_name:
                inc.stories.append(story_name)
        increments.append(inc)
        order += 1
    return increments

def _story_row_y(self, story_map: StoryMap) -> int:
    deepest_bottom = self._subepic_y_for_depth(self._max_sub_epic_depth(story_map)) + SUBEPIC_HEIGHT
    return max(
        STORY_ROW_Y,
        deepest_bottom + ACTOR_LABEL_HEIGHT + ACTOR_LABEL_GAP + DETAIL_BELOW_SUBEPIC_PAD,
    )

def _epic_width(self, epic: Epic) -> int:
    if not epic.sub_epics:
        return STORY_PITCH_X
    return sum(
        max(sub_epic.diagram_span_columns(), 1) * STORY_PITCH_X
        for sub_epic in epic.sub_epics
    )

def _collect_leaf_sub_epics(
    self, sub: SubEpic, out: List[SubEpic]
) -> None:
    if not sub.sub_epics:
        out.append(sub)
    else:
        for child in sub.sub_epics:
            self._collect_leaf_sub_epics(child, out)

def _leaf_sub_epics(self, sub: SubEpic) -> List[SubEpic]:
    if not sub.sub_epics:
        return [sub]
    result: List[SubEpic] = []
    for child in sub.sub_epics:
        result.extend(self._leaf_sub_epics(child))
    return result

def _find_foreign_object(
    self, root_el: ET.Element, data_type: str
) -> Optional[ET.Element]:
    for el in root_el.iter():
        tag = el.tag.split("}")[-1] if "}" in el.tag else el.tag
        if tag == "foreignObject" and el.get("data-type") == data_type:
            return el
    return None

def _walk_stories_with_scenarios(self, canonical: StoryMap) -> List[Story]:
    result: List[Story] = []
    for epic in canonical.epics:
        for sub in epic.sub_epics:
            self._collect_stories_with_scenarios(sub, result)
    return result

def _max_sub_epic_depth(self, story_map: StoryMap) -> int:
    def depth_of(sub_epic: SubEpic, depth: int) -> int:
        if not sub_epic.sub_epics:
            return depth
        return max(depth_of(child, depth + 1) for child in sub_epic.sub_epics)

    return max(
        (
            depth_of(sub_epic, 0)
            for epic in story_map.epics
            for sub_epic in epic.sub_epics
        ),
        default=0,
    )

def _collect_stories_with_scenarios(
    self, sub_epic: SubEpic, out: List[Story]
) -> None:
    for story in sub_epic.stories:
        if getattr(story, "scenarios", None):
            out.append(story)
    for nested in sub_epic.sub_epics:
        self._collect_stories_with_scenarios(nested, out)

def _generate(self):
    from generate.generate import Generate

    return Generate()

def _grill_context(self) -> GrillContext:
    """GrillContext toolset for in-method composition (not a tool)."""
    return GrillContext()

def save(self) -> None:
    self.session_file.parent.mkdir(parents=True, exist_ok=True)
    self.session_file.write_text(
        json.dumps({"chat_id": self.chat_id}, indent=2),
        encoding="utf-8",
    )

def load(cls, session_file: Path) -> AgentSession | None:
    if not session_file.is_file():
        return None
    try:
        data = json.loads(session_file.read_text(encoding="utf-8"))
        chat_id = str(data.get("chat_id", "")).strip()
    except (OSError, json.JSONDecodeError):
        return None
    return cls(chat_id=chat_id, session_file=session_file) if chat_id else None

def _json_event(self, raw: str) -> dict[str, Any] | None:
    try:
        event = json.loads(raw.strip())
    except json.JSONDecodeError:
        return None
    return event if isinstance(event, dict) else None

def _narrative_from_event(self, event: dict[str, Any]) -> str:
    etype = event.get("type", "")
    if etype == "assistant":
        return self._assistant_text(event)
    if etype == "result":
        return str(event.get("result", "") or "")
    return ""

def judge_session(self) -> str | None:
    if not self.session:
        return None
    path = Path(self.session)
    stem = path.stem
    return path.with_name(f"{stem}-judge.json").as_posix()

def _find_marker_command(self) -> str | None:
    for line in self._source.splitlines():
        command = self._marker_command_from_line(line)
        if command is not None:
            return command
        if self._stops_header_scan(line):
            return None
    return None

def _infer_repo_root(self) -> Path:
    for parent in [self._root_start, *self._root_start.parents]:
        if (parent / "harness").is_dir() and (parent / "contexts").is_dir():
            return parent
    return self._root_start.parent.parent

def _marker_command_from_line(self, line: str) -> str | None:
    stripped = line.strip()
    if not stripped.startswith("#"):
        return None
    body = stripped.lstrip("#").strip()
    if AGENT_SPEC_MARKER not in body:
        return None
    remainder = body.split(AGENT_SPEC_MARKER, 1)[1].strip()
    if remainder.startswith(":"):
        remainder = remainder[1:].strip()
    return remainder or None

def _stops_header_scan(self, line: str) -> bool:
    stripped = line.strip()
    if stripped.startswith("#"):
        return False
    if not stripped or stripped.startswith('"""') or stripped.startswith("'''"):
        return False
    return True

def _ingest_node(self, node: ast.AST) -> None:
    if isinstance(node, ast.With):
        self._ingest_with(node)
    if isinstance(node, ast.Call):
        self._ingest_call(node)

def _append_remaining_setup(self) -> None:
    if not self._setup_steps:
        return
    self._collected.append(
        _RunbookScenario(
            name=self._current_name,
            session=self._current_session,
            setup=list(self._setup_steps),
        )
    )

def _merged_scenarios(self) -> list[_RunbookScenario]:
    by_name: dict[str, _RunbookScenario] = {}
    for scenario in self._collected:
        self._merge_named_scenario(by_name, scenario)
    merged = list(by_name.values())
    if merged or not self._manifest.session:
        return merged
    return [
        _RunbookScenario(name="default", session=self._manifest.session, setup=self._setup_steps),
    ]

def _ingest_with(self, node: ast.With) -> None:
    context_name = self._with_context_name(node)
    if context_name:
        self._begin_named_context(context_name)
    it_desc = self._it_description(node)
    if it_desc:
        self._pending_it = it_desc

def _ingest_call(self, node: ast.Call) -> None:
    if isinstance(node.func, ast.Attribute):
        self._ingest_attribute_call(node)
    if self._is_expect_call(node):
        self._record_expect(node)

def _with_context_name(self, node: ast.With) -> str | None:
    for item in node.items:
        name = self._context_call_name(item.context_expr)
        if name is not None:
            return name
    return None

def _begin_named_context(self, context_name: str) -> None:
    if self._setup_steps or self._pending_it:
        self._collected.append(
            _RunbookScenario(
                name=self._current_name,
                session=self._current_session,
                setup=list(self._setup_steps),
            )
        )
        self._setup_steps = []
    self._current_name = context_name
    if "agent" in context_name.lower():
        self._current_session = self._manifest.session

def _it_description(self, node: ast.With) -> str | None:
    for item in node.items:
        name = self._it_call_name(item.context_expr)
        if name is not None:
            return name
    return None

def _ingest_attribute_call(self, node: ast.Call) -> None:
    attr = node.func.attr
    if attr in {"instruct", "instruct_use_tool"}:
        self._record_instruct(node, attr)
        return
    if attr == "ai_judge":
        self._record_judge(node)

def _record_instruct(self, node: ast.Call, attr: str) -> None:
    prompt = self._prompt_arg(node, 0)
    if not prompt:
        return
    self._setup_steps.append(
        _RunbookStep(
            kind=attr,
            prompt=prompt,
            save_as=self._assignment_target(node),
            timeout_seconds=self._keyword_int(node, "timeout_seconds"),
        )
    )

def _prompt_arg(self, node: ast.Call, index: int) -> str | None:
    literal = self._string_arg(node, index)
    if literal is not None:
        return literal
    if len(node.args) <= index:
        return None
    return self._resolve_string_expr(node.args[index])

def _keyword_int(self, node: ast.Call, name: str) -> int | None:
    for keyword in node.keywords:
        if keyword.arg == name and isinstance(keyword.value, ast.Constant):
            if isinstance(keyword.value.value, int):
                return keyword.value.value
    return None

def _scenario_for_expect(self) -> _RunbookScenario:
    if self._collected and self._collected[-1].name == self._current_name and not self._collected[-1].setup:
        return self._collected[-1]
    for scenario in self._collected:
        if scenario.name == self._current_name:
            return scenario
    scenario = _RunbookScenario(
        name=self._current_name,
        session=self._current_session,
        setup=list(self._setup_steps),
    )
    self._collected.append(scenario)
    return scenario

def _merge_named_scenario(
    self, by_name: dict[str, _RunbookScenario], scenario: _RunbookScenario
) -> None:
    existing = by_name.get(scenario.name)
    if existing is None:
        by_name[scenario.name] = scenario
        return
    existing.setup.extend(scenario.setup)
    existing.assertions.extend(scenario.assertions)
    existing.judges.extend(scenario.judges)
    if scenario.session:
        existing.session = scenario.session

def _context_call_name(self, expr: ast.AST) -> str | None:
    if not isinstance(expr, ast.Call):
        return None
    func = expr.func
    named = isinstance(func, ast.Name) and func.id == "context"
    attributed = isinstance(func, ast.Attribute) and func.attr == "context"
    if not (named or attributed):
        return None
    if expr.args and isinstance(expr.args[0], ast.Constant):
        return str(expr.args[0].value)
    return None

def _it_call_name(self, expr: ast.AST) -> str | None:
    if not isinstance(expr, ast.Call):
        return None
    func = expr.func
    if not (isinstance(func, ast.Name) and func.id == "it"):
        return None
    if expr.args and isinstance(expr.args[0], ast.Constant):
        return str(expr.args[0].value)
    return None

def _string_arg(self, node: ast.Call, index: int) -> str | None:
    if len(node.args) <= index:
        return None
    arg = node.args[index]
    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
        return arg.value
    return None

def _resolve_string_expr(self, arg: ast.AST) -> str | None:
    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
        return arg.value
    if isinstance(arg, ast.JoinedStr):
        return self._joined_string(arg)
    segment = ast.get_source_segment(self._source, arg)
    if segment is None:
        return None
    if (segment.startswith('"') and segment.endswith('"')) or (
        segment.startswith("'") and segment.endswith("'")
    ):
        return ast.literal_eval(segment)
    if segment.startswith('f"') or segment.startswith("f'"):
        return None
    return segment

def _joined_string(self, arg: ast.JoinedStr) -> str | None:
    parts: list[str] = []
    for piece in arg.values:
        if isinstance(piece, ast.Constant) and isinstance(piece.value, str):
            parts.append(piece.value)
            continue
        if not isinstance(piece, ast.FormattedValue):
            return None
        resolved = self._resolve_formatted_value(piece)
        if resolved is None:
            return None
        parts.append(resolved)
    return "".join(parts)

def _resolve_formatted_value(self, piece: ast.FormattedValue) -> str | None:
    value = piece.value
    if isinstance(value, ast.Name):
        return self._assigned_name_value(value.id)
    if isinstance(value, ast.Constant):
        return str(value.value)
    return ast.get_source_segment(self._source, value)

def _assigned_name_value(self, name: str) -> str | None:
    for stmt in self._tree.body:
        if not isinstance(stmt, ast.Assign):
            continue
        for target in stmt.targets:
            if isinstance(target, ast.Name) and target.id == name:
                if isinstance(stmt.value, ast.Constant):
                    return str(stmt.value.value)
    return None

def _assign_name_for_call(self, call_node: ast.Call) -> str | None:
    self._call_node = call_node
    self._call_line = getattr(call_node, "lineno", None)
    if self._call_line is None:
        return None
    for node in ast.walk(self._tree):
        found = self._target_if_matching_assign(node)
        if found is not None:
            return found
    return None

def _target_if_matching_assign(self, node: ast.AST) -> str | None:
    if not isinstance(node, ast.Assign) or not isinstance(node.value, ast.Call):
        return None
    if not self._assign_matches_call(node.value):
        return None
    if len(node.targets) != 1:
        return None
    return self._name_from_assign_target(node.targets[0])

def _assign_matches_call(self, value: ast.Call) -> bool:
    if value is self._call_node:
        return True
    return (
        getattr(value, "lineno", None) == self._call_line
        and getattr(value, "col_offset", None) == getattr(self._call_node, "col_offset", None)
    )

def _name_from_assign_target(self, target: ast.AST) -> str | None:
    if isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name):
        return f"{target.value.id}.{target.attr}"
    if isinstance(target, ast.Name):
        return target.id
    return None

def from_stdout(cls, stdout: str, elapsed_seconds: float = 0.0) -> JudgeResult:
    parsed = cls(verdict="ERROR", reason="")._parsed(stdout)
    return cls(
        verdict=parsed.verdict,
        reason=parsed.reason,
        elapsed_seconds=elapsed_seconds,
    )

def _parsed(self, stdout: str) -> JudgeResult:
    line_verdict = self._verdict_from_json_lines(stdout)
    if line_verdict is not None:
        return JudgeResult(verdict=line_verdict[0], reason=line_verdict[1])
    embedded = self._preferred_embedded_verdict(stdout)
    if embedded is not None:
        return JudgeResult(verdict=embedded[0], reason=embedded[1])
    return JudgeResult(
        verdict="ERROR",
        reason=f"no parseable verdict in output:\n{stdout[:500]}",
    )

def _verdict_from_json_lines(self, stdout: str) -> tuple[str, str] | None:
    last_fail: tuple[str, str] | None = None
    for line in reversed(stdout.splitlines()):
        parsed = self._parse_judge_json(line.strip())
        if parsed is None:
            continue
        verdict, reason = parsed
        if verdict == "PASS":
            return verdict, reason
        if verdict == "FAIL":
            last_fail = (verdict, reason)
    return last_fail

def _preferred_embedded_verdict(self, stdout: str) -> tuple[str, str] | None:
    embedded = self._embedded_judge_verdicts(stdout)
    for verdict, reason in reversed(embedded):
        if verdict == "PASS":
            return verdict, reason
    for verdict, reason in reversed(embedded):
        if verdict == "FAIL":
            return verdict, reason
    return None

def _parse_judge_json(self, text: str) -> tuple[str, str] | None:
    if not text.startswith("{"):
        return None
    try:
        obj = json.loads(text)
    except json.JSONDecodeError:
        return None
    if not isinstance(obj, dict):
        return None
    verdict = str(obj.get("verdict", "")).strip().upper()
    reason = str(obj.get("reason", "")).strip()
    if verdict not in {"PASS", "FAIL"}:
        return None
    return verdict, reason

def _embedded_judge_verdicts(self, text: str) -> list[tuple[str, str]]:
    self._judge_text = text
    self._decoder = json.JSONDecoder()
    found: list[tuple[str, str]] = []
    index = 0
    while index < len(self._judge_text):
        start = self._next_verdict_start(index)
        if start < 0:
            break
        parsed, index = self._decode_embedded_verdict(start)
        if parsed is not None:
            found.append(parsed)
    return found

def _next_verdict_start(self, index: int) -> int:
    start = self._judge_text.find('{"verdict"', index)
    if start >= 0:
        return start
    return self._judge_text.find('{"Verdict"', index)

def current(self) -> Any:
    block = getattr(self._local, "block", None)
    if block is None:
        raise RuntimeError("instruct/instruct_use_tool/ai_judge called outside of `with agent(...)`")
    return block

def opened(cls, workspace: Path, session_file: Path) -> Iterator["_ChatAgentBlock"]:
    """Establish one in-chat agent session backed by inbox files."""
    yield cls(workspace, session_file)

def _wait_for_inbox(self, prefix: str, prompt: str, *, timeout_seconds: int) -> str:
    response_path = self._prepare_inbox(prefix, prompt)
    text = self._poll_inbox_response(response_path, timeout_seconds)
    if text:
        return text
    raise ChatInboxPending(
        f"timed out waiting for inbox response at {response_path}",
        prefix=prefix,
        log_dir=self._log_dir,
    )

def _finalize_run_response(self, prefix: str, cli_output: str) -> RunResponse:
    self._write_artifact(f"{prefix}-cli-output.yaml", cli_output)
    ai_response = RunResponse.from_cli_output(cli_output)
    self._write_artifact(
        f"{prefix}-ai-response.yaml",
        self._yaml.dump_manifest(
            {k: v for k, v in {
                "ok": ai_response.ok,
                "toolset": ai_response.toolset,
                "tool": ai_response.tool,
                "action": ai_response.action,
                "result": ai_response.result,
                "instructions": ai_response.instructions,
                "tools": ai_response.tools,
                "arguments": ai_response.arguments,
                "resources": ai_response.resources,
            }.items() if v is not None}
        ),
    )
    return ai_response

def _poll_inbox_response(self, response_path: Path, timeout_seconds: int) -> str:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        if response_path.is_file():
            text = response_path.read_text(encoding="utf-8").strip()
            if text:
                return text
        time.sleep(INBOX_POLL_SECONDS)
    return ""

def assert_authenticated(self) -> None:
    exe = AgentSession.launcher()
    if exe is None:
        raise RuntimeError("cursor-agent not found on PATH")
    completed = subprocess.run([exe, "status"], capture_output=True, text=True, timeout=30)
    if completed.returncode != 0:
        raise RuntimeError("cursor-agent not authenticated - run `cursor-agent login` first")

def resolve_near(cls, segment_path: str | Path) -> Path | None:
    """Walk up from a segment file to session ``.context/*-index.md``."""
    path = Path(segment_path)
    start = path.parent
    if start.name == ".context":
        start = start.parent
    for folder in [start, *start.parents]:
        context_dir = folder / ".context"
        if not context_dir.is_dir():
            continue
        indexes = sorted(context_dir.glob("*-index.md"))
        if indexes:
            return indexes[0].resolve()
    return None

def _completeness_from_text(cls, text: str) -> SegmentCompletenessConfig:
    raw = cls._parse_config(text)
    return SegmentCompletenessConfig(
        min_body_chars=cls._min_body_chars(raw),
        non_entry_headers=cls._non_entry_headers(raw),
        short_body_pattern=cls._short_body_pattern(raw),
    )

def _min_body_chars(raw: dict[str, Any]) -> int:
    chars_raw = raw.get("min-body-chars", 120)
    try:
        return int(chars_raw)
    except (TypeError, ValueError):
        return 120

def _non_entry_headers(raw: dict[str, Any]) -> frozenset[str]:
    headers_raw = raw.get("non-entry-headers", [])
    if isinstance(headers_raw, str):
        parts = re.split(r"[\n|,;]+", headers_raw)
    else:
        parts = list(headers_raw or [])
    return frozenset(
        str(part).upper().strip() for part in parts if str(part).strip()
    )

def _short_body_pattern(raw: dict[str, Any]) -> re.Pattern[str] | None:
    pattern_raw = raw.get("short-body-pattern")
    if not pattern_raw:
        return None
    return re.compile(str(pattern_raw), re.I)

def _read_partition_index(
    self, segment_path: Path, index_path: str
) -> PartitionIndex | None:
    resolved = (
        Path(index_path)
        if index_path.strip()
        else PartitionIndex.resolve_near(segment_path)
    )
    if resolved is None or not resolved.is_file():
        return None
    return PartitionIndex.from_text(
        resolved.resolve(),
        resolved.read_text(encoding="utf-8", errors="replace"),
    )

def from_text(
    cls,
    path: Path,
    text: str,
    config: SegmentCompletenessConfig,
    *,
    expected_names: str = "",
) -> Segment:
    """Build a segment from already-loaded text."""
    names = (
        cls._split_names(expected_names) if expected_names.strip() else None
    )
    return cls(path, text, config, expected_names=names)

def _split_names(raw: str) -> list[str]:
    names: list[str] = []
    for part in re.split(r"[\n|,;]+", raw):
        name = part.strip().strip("-").strip()
        if not name or name.startswith("#"):
            continue
        names.append(name)
    seen: set[str] = set()
    out: list[str] = []
    for name in names:
        key = name.casefold()
        if key in seen:
            continue
        seen.add(key)
        out.append(name)
    return out

def _entry_for(self, name: str, lines: list[str]) -> SegmentEntry:
    header = name.upper().strip()
    idxs = [i for i, line in enumerate(lines) if line.strip() == header]
    if not idxs:
        return SegmentEntry(name, None, self._config)
    body = self._body_after_header(lines, idxs[0], header)
    return SegmentEntry(name, body, self._config)

def _report_rows(
    self, entries: list[SegmentEntry], incomplete: int, total: int
) -> list[str]:
    rows = [
        f"| {entry.name} | {entry.status} | {entry.body_chars} |"
        for entry in entries
        if not entry.is_complete
    ]
    if incomplete == 0 and total > 0:
        rows.append(
            f"| - | (all expected entries) | OK | "
            f">={self._config.min_body_chars} |"
        )
    return rows

def _is_entry_header(self, candidate: str, current_header: str) -> bool:
    if not _ALL_CAPS.match(candidate):
        return False
    if (
        candidate in self._config.non_entry_headers
        or candidate == current_header
    ):
        return False
    if re.fullmatch(r"\d{2,3}", candidate):
        return False
    return True

def __init__(self, root: Path) -> None:
    self.root = Path(root)
    self._pending_batch = {}
    self._pending_results = None
    self._database_language = "python"

def executable(self) -> str:
    path = shutil.which("codeql")
    if path is None:
        raise CodeQLRunError("codeql is not on PATH")
    return path

def repo_root(self) -> Path:
    for candidate in (self.root.resolve(), *self.root.resolve().parents):
        if (candidate / ".git").exists() and (candidate / "practices").is_dir():
            return candidate
    return self.root.resolve()

def ensure_database(self, language: str = "python") -> Path:
    working = self.root / ".codeql" / f"{language}-working-copy"
    ready = self._ready_database(language)
    if ready is not None:
        return ready
    self._retire_database(working)
    self._database_language = language
    return self._create_database(working)

def _ready_database(self, language: str = "python") -> Path | None:
    working = self.root / ".codeql" / f"{language}-working-copy"
    master = self.root / ".codeql" / f"{language}-master"
    if self._database_ready(working):
        return working
    if self._database_ready(master):
        return master
    return None

def _retire_database(self, database: Path) -> None:
    if not database.exists():
        return
    retired = database.with_name(database.name + ".retired")
    for _ in range(6):
        if retired.exists():
            shutil.rmtree(retired, ignore_errors=True)
        try:
            database.rename(retired)
            shutil.rmtree(retired, ignore_errors=True)
        except OSError:
            shutil.rmtree(database, ignore_errors=True)
        if not database.exists():
            return
        time.sleep(0.4)

def _unlock_databases(self) -> None:
    detach_query_server()
    path = self.repo_root() / ".codeql" / "query-server.json"
    if not path.is_file():
        return
    try:
        pid = int(json.loads(path.read_text(encoding="utf-8")).get("pid") or 0)
    except (OSError, json.JSONDecodeError, TypeError, ValueError):
        return
    if pid in (0, os.getpid()):
        return
    try:
        os.kill(pid, signal.SIGTERM)
    except OSError:
        return
    time.sleep(0.5)

def _install_created_database(self, created: Path, database: Path) -> Path:
    self._retire_database(database)
    try:
        created.rename(database)
        return database
    except OSError:
        return self._copy_created_database(created, database)

def _failed_codeql(self, run) -> CodeQLRunError:
    detail = "\n".join(part for part in (run.stderr, run.stdout) if part)
    return CodeQLRunError(f"codeql failed: {detail}")

def _copy_database(self, source: Path, destination: Path) -> None:
    self._retire_database(destination)
    if destination.is_file() or destination.is_symlink():
        destination.unlink()
    if destination.exists():
        shutil.copytree(source, destination, dirs_exist_ok=True)
        return
    shutil.copytree(source, destination)

