def rules_for_node(
    self,
    *,
    practice: str,
    semantic_type: str,
    fidelity: Optional[str] = None,
    direct_only: bool = False,
) -> List[GraphRule]:
    matched: List[GraphRule] = []
    closest = closest_fidelity(practice, semantic_type)
    for rule in self.rules:
        if rule.practice != practice:
            continue
        if fidelity is not None and rule.fidelity != fidelity and not rule.shared:
            continue
        if rule.shared:
            if semantic_type not in rule.applies_to and not fidelity:
                continue
        elif semantic_type not in rule.applies_to:
            continue
        if direct_only:
            if rule.shared:
                continue
            if rule.fidelity != closest:
                continue
        matched.append(rule)
    return matched

def from_entry(cls, graph, entry: dict):
    node_id = entry.get("node_id") or ""
    if node_id and node_id in graph.nodes:
        return graph.nodes[node_id]
    semantic = entry.get("semantic_type") or ""
    name = entry.get("node_name") or ""
    for node in graph.nodes.values():
        if node.semantic_type() != semantic:
            continue
        if node.name != name:
            continue
        return node
    return None

def belongs_on(self, node) -> bool:
    message = self.message
    labeled = re.search(r"Operation '([^']+)'", message)
    if labeled and "." in labeled.group(1):
        cls, _, op = labeled.group(1).rpartition(".")
        owner = node.owner_class()
        return node.name == op and owner is not None and owner.name == cls
    size = re.search(r" is (\d+) (lines|statements)", message)
    if size:
        if size.group(2) == "statements":
            return True
        src = getattr(node, "source", None)
        start = int(getattr(src, "line", 0) or 0)
        end = int(getattr(src, "end_line", 0) or start)
        return start > 0 and (end - start + 1) == int(size.group(1))
    attr = re.search(r"private attribute '([^']+)'", message) or re.search(
        r"via '([^']+)'", message
    )
    if attr:
        text = str(getattr(getattr(node, "source", None), "text", "") or "")
        return bool(text) and attr.group(1) in text
    return False

def fidelity(self, name: str) -> "NodeRules":
    return NodeRules(
        self._node,
        practice=self._practice,
        fidelity=name,
    )

def violations(self) -> List[RuleViolation]:
    hits = self._matching()
    if self._practice is not None:
        hits = [hit for hit in hits if hit.practice == self._practice]
    if self._fidelity is not None:
        hits = [hit for hit in hits if hit.fidelity == self._fidelity]
    if self._direct_only:
        closest = closest_fidelity(self._node.practice, self._node.semantic_type())
        hits = [hit for hit in hits if hit.fidelity == closest]
    if self._rule_slug is not None:
        hits = [hit for hit in hits if hit.rule_slug == self._rule_slug]
    return hits

def _dedupe(self, violations: List[RuleViolation]) -> List[RuleViolation]:
    seen: set[tuple] = set()
    out: List[RuleViolation] = []
    for violation in violations:
        key = (violation.rule_slug, violation.node_id, violation.message)
        if key in seen:
            continue
        seen.add(key)
        out.append(violation)
    return out

def _inherited(self, node: Node) -> List[RuleViolation]:
    inherited: List[RuleViolation] = []
    for parent in node.related(Kind.OWNS, direction="in"):
        for violation in self.graph.violations_for(parent):
            if violation.rule_slug in (
                "scenario-scopes-example",
                "keep-classes-single-responsibility",
            ):
                continue
            inherited.append(violation)
        inherited.extend(self._inherited(parent))
    return inherited

def _nodes_along(self, graph, parts: list[str]):
    keys = [part.strip().casefold() for part in parts if part.strip()]
    if not keys:
        return list(graph.nodes.values())
    current = [node for node in graph.nodes.values() if self._key_matches(node, keys[0])]
    for key in keys[1:]:
        current = [
            child
            for node in current
            for child in self._children(node)
            if self._key_matches(child, key)
        ]
    return current

def _markdown_instructions(self, graph, rule) -> list[str]:
    texts: list[str] = []
    for item in graph.rule_registry.rules:
        if rule is not None and item.slug != rule.slug:
            continue
        if getattr(item, "graphQuery", None) is not None:
            continue
        texts.append(item.validate())
    return texts

def _nodes_as_json(self, filt: Filter) -> list[dict]:
    matched: list[dict] = []
    for graph in self._graphs():
        seeds = {
            node.node_id
            for node in graph.nodes.values()
            if filt.matches(node)
        }
        kept = filt.expand_ids(seeds, graph) if filt.constrains else set(graph.nodes)
        for node in graph.nodes.values():
            if node.node_id not in kept:
                continue
            matched.append(
                self._node_as_json(
                    node,
                    graph,
                    seed=node.node_id in seeds,
                    kept=kept,
                )
            )
    return matched

def _graph_violation_prompts(self, graph, filt: Filter) -> list[str]:
    kept = self._violation_subtree_ids(graph, filt)
    hit = filt.without_scope()
    hit.violations = True
    prompts: list[str] = []
    for node in graph.nodes.values():
        if node.node_id not in kept:
            continue
        if not hit.matches(node):
            continue
        self._prompt_filter = hit
        prompts.extend(self._node_violation_prompts(node))
    return prompts

def _violation_subtree_ids(self, graph, filt: Filter) -> set:
    scope = filt.scope()
    if not scope.constrains:
        return set(graph.nodes)
    seeds = {
        node.node_id
        for node in graph.nodes.values()
        if scope.matches(node)
    }
    return filt.subtree_ids(seeds, graph)

def _node_violation_prompts(self, node) -> list[str]:
    filt = self._prompt_filter
    graph = node.graph
    rules = filt.listed(("rules", "rule"))
    prompts: list[str] = []
    for hit in graph.violations_for(node):
        if rules and hit.rule_slug not in rules:
            continue
        prompts.append(self._violation_prompt(node, hit, graph))
    return prompts

def _source_span(self, src) -> str:
    if src is None:
        return ""
    file = str(getattr(src, "file", "") or "")
    if not file:
        return ""
    start = int(getattr(src, "line", 0) or 0)
    end = int(getattr(src, "end_line", 0) or 0)
    if start >= 1:
        return f"{file}:{start}-{end}"
    return file

def _rule_body(self, graph, slug: str) -> str:
    for item in getattr(graph.rule_registry, "rules", []) or []:
        if getattr(item, "slug", "") == slug:
            return str(
                getattr(item, "body", None) or getattr(item, "markdown", None) or ""
            )
    return ""

def __init__(self, root: Path, rule_registry: RuleRegistry | None = None) -> None:
    self.root = root.resolve()
    self.story_map = None
