def __eq__(self, other: object) -> bool:
    if isinstance(other, ReferencePaths):
        return self._paths == other._paths
    if isinstance(other, list):
        return self._paths == other
    return NotImplemented

def __init__(self, paths: Iterable[str] | None = None) -> None:
    self._paths: List[str] = []
    if paths:
        self.replace(paths)

def replace(self, paths: Iterable[str]) -> None:
    self._paths = []
    for path in paths:
        self.add(path)

def add(self, path: str) -> None:
    normalized = (path or "").strip()
    if normalized and normalized not in self._paths:
        self._paths.append(normalized)

def story_references(self, paths: Iterable[str] | ReferencePaths) -> None:
    if isinstance(paths, ReferencePaths):
        self._story_references.replace(paths.as_list())
    else:
        self._story_references.replace(paths)

