    self.sequential_order = source.sequential_order

def normalize_factory_name(self, name: str) -> str:
    raw = (name or "").strip()
    if not raw:
        return ""
    if raw.endswith("ExampleFactory"):
        return raw
    return f"{raw}ExampleFactory"

def _add_factory_names(self, node: object) -> None:
    for raw in getattr(node, "example_factories", None) or []:
        self._remember_factory(raw)
    for concept in getattr(node, "domain_concepts", None) or []:
        if str(concept).endswith("ExampleFactory"):
            self._remember_factory(str(concept))

def _walk_factory_subs(self, subs: Iterable["SubEpic"]) -> None:
    for sub in subs or []:
        self._add_factory_names(sub)
        self._walk_factory_subs(getattr(sub, "sub_epics", None) or [])

def _remember_factory(self, raw: str) -> None:
    name = self.normalize_factory_name(raw)
    if not name or name in self._factory_seen or not self._factory_pattern.match(name):
        return
    self._factory_seen.add(name)
    self._factory_names.append(name)

def sync_tree_from_legacy(self) -> None:
    """Build Background / Step / Example children from legacy clause and row fields."""
    self.backgrounds = []
    self.steps = []
    self.examples = []

    if self.background:
        bg = Background("background", 1)
        for index, clause in enumerate(self.background, start=1):
            bg.steps.append(Step.from_clause(clause, index))
        self.backgrounds = [bg]

    order = 0
    for clause in self.given:
        order += 1
        self.steps.append(Step.from_clause(clause, order))
    for interaction in self.interactions:
        for clause in interaction.when:
            order += 1
            self.steps.append(Step.from_clause(clause, order))
        for clause in interaction.then:
            order += 1
            self.steps.append(Step.from_clause(clause, order))

    for index, row in enumerate(self.example_rows, start=1):
        label = str(row.get("example") or row.get("name") or f"example-{index}")
        self.examples.append(Example(label, index, dict(row)))

def sync_legacy_from_tree(self) -> None:
    """Rebuild legacy clause fields from tree children (for format renderers)."""
    self.background = []
    self.given = []
    self.interactions = []
    self.example_rows = []

    if self.backgrounds:
        self.background = [step.to_clause() for step in self.backgrounds[0].steps]

    interaction: Interaction | None = None
    for step in self.steps:
        clause = step.to_clause()
        if step.phase == Phase.GIVEN:
            self.given.append(clause)
        elif step.phase == Phase.WHEN:
            interaction = Interaction()
            self.interactions.append(interaction)
            interaction.when.append(clause)
        elif step.phase == Phase.THEN:
            if interaction is None:
                interaction = Interaction()
                self.interactions.append(interaction)
            interaction.then.append(clause)

    self.example_rows = [dict(example.fields) for example in self.examples]

def owner_of(self, entry: dict):
    scenarios = self._scenarios
    backgrounds = self._backgrounds
    if entry.get("scenario"):
        key = (
            StoryMap().normalized_file(entry.get("file") or ""),
            Node().slug(entry.get("story") or ""),
            (entry.get("scenario") or "").lower(),
        )
        found = scenarios.get(key)
        if found is not None:
            return found
        for (_file, story_slug, scenario_name), scenario in scenarios.items():
            if scenario_name == (entry.get("scenario") or "").lower() and story_slug == Node().slug(
                entry.get("story") or ""
            ):
                return scenario
    if entry.get("background"):
        for bg_entry, background in backgrounds:
            if Node().slug(bg_entry.get("story") or "") != Node().slug(entry.get("story") or ""):
                continue
            if (bg_entry.get("name") or "background") == (entry.get("background") or "background"):
                return background
    return None

def wire_calls(self, graph: "PracticeGraph", story_calls: List[dict]) -> None:
    self._graph = graph
    for story_call in story_calls:
        self._step_text = story_call.get("step_text") or ""
        step = self.at(
            story_call.get("story_file") or "",
            int(story_call.get("line") or 0),
        )
        operation = graph.operation_named(
            story_call.get("callee_class") or "",
            story_call.get("callee_operation") or "",
        )
        if step is None or operation is None:
            continue
        step.invokes(operation)

def at(self, story_file: str, line: int) -> Optional["Step"]:
    self._lookup_file = story_file.replace("\\", "/").lstrip("./")
    self._lookup_line = line
    by_text = self._step_matching_text()
    if by_text is not None:
        return by_text
    return self._step_near_line()

def _owned_member(self):
    for owned in self._owned_class.related(Kind.OWNS):
        if self._is_observed_member(owned):
            return owned
    return None

def _is_observed_member(self, owned) -> bool:
    kind = self._observation.get("member_kind")
    name = self._observation.get("target_member")
    if kind == "operation" and isinstance(owned, self._operation_type):
        return owned.name == name
    if kind == "property" and isinstance(owned, self._property_type):
        return owned.name == name
    return False

def _step_matching_text(self) -> Optional["Step"]:
    step_text = self._step_text
    if not step_text:
        return None
    for step in self._graph.nodes_of_type(Step):
        if step_text.lower() in step.text.lower():
            return step
    return None

def _step_near_line(self) -> Optional["Step"]:
    best: Tuple[int, Optional[Step]] = (1_000_000, None)
    for step in self._graph.nodes_of_type(Step):
        src = getattr(step, "source", None)
        if src is None:
            continue
        src_file = str(src.file).replace("\\", "/").lstrip("./")
        if src_file != self._lookup_file and not src_file.endswith(self._lookup_file):
            continue
        if self._lookup_line <= 0:
            return step
        delta = abs(int(src.line) - self._lookup_line)
        if delta < best[0]:
            best = (delta, step)
    if best[1] is not None and best[0] <= 5:
        return best[1]
    return None

def load_background(self, source: "Background") -> "Background":
    from .background import Background

    return Background(source.name, source.sequential_order)

def load_example(self, source: "Example") -> "Example":
    from .example import Example

    return Example(source.name, source.sequential_order, dict(source.fields), source.scope)

def load_scenario(self, source: "Scenario") -> "Scenario":
    from .scenario import Scenario  # lazy import to avoid cycle
    return Scenario(source.name, source.sequential_order, source.story_name)

def update_self(self, source: "StoryMap") -> None:
    self.name = source.name
    self.sequential_order = source.sequential_order

def append_epic(self, epic: Epic) -> None:
    self.epics.append(epic)
    self._renumber(self.epics)

def remove_epic(self, epic_name: str) -> Epic:
    for i, epic in enumerate(self.epics):
        if epic.name == epic_name:
            removed = self.epics.pop(i)
            self._renumber(self.epics)
            return removed
    raise KeyError(f"Epic {epic_name!r} not found")

def owner_of_example(self, entry: dict):
    kind = entry.get("owner_kind") or ""
    owner = entry.get("owner") or ""
    if kind == "story_map":
        graph = getattr(self, "_example_graph", None)
        if graph is not None and graph.story_map is not None:
            return graph.story_map
        return self
    if kind == "epic":
        return self._example_epics.get(Node().slug(owner))
    if kind == "sub_epic":
        return self._sub_epic_named(owner)
    if kind == "story":
        return self._example_stories.get(Node().slug(owner))
    return self._example_owner_by_slug(owner)

def _sub_epic_named(self, owner: str):
    owner_slug = Node().slug(owner)
    for (_epic, sub_slug), sub in self._example_subs.items():
        if sub_slug == owner_slug:
            return sub
    return None

def _example_owner_by_slug(self, owner: str):
    owner_slug = Node().slug(owner) if owner else ""
    if owner_slug in self._example_epics:
        return self._example_epics[owner_slug]
    found = self._sub_epic_named(owner)
    if found is not None:
        return found
    if not owner_slug:
        return self
    return None

def _display_name(self, name: str) -> str:
    if not name:
        return ""
    if " " in name:
        return name
    return name.replace("-", " ").replace("_", " ").title()

def _ensure_examples(self, entries: List[dict]) -> None:
    existing = {ex.name.lower(): ex for ex in self._example_graph.nodes_of_type(Example)}
    for entry in entries:
        name = entry.get("export_name") or ""
        example = existing.get(name.lower())
        if example is not None:
            continue
        owner = self.owner_of_example(entry)
        if owner is None:
            owner = self._example_graph.story_map
        self._example_entry = entry
        self._example_name = name
        example = self._new_example(owner)
        self._example_graph.register(example)
        existing[name.lower()] = example
        if owner is not None:
            if getattr(owner, "_graph", None) is None:
                self._example_graph.register(owner)
            owner.examples.append(example)
            owner.relate(Kind.SCOPES, example)

def _wire_demonstrated_through(self, graph: "PracticeGraph", created_steps) -> None:
    by_name: Dict[str, Example] = {}
    for example in graph.nodes_of_type(Example):
        by_name[example.name] = example
        by_name[example.name.lower()] = example
    for entry, step in created_steps:
        for name in entry.get("uses_examples") or []:
            example = by_name.get(name) or by_name.get(name.lower())
            if example is None:
                continue
            step.demonstrated_through(example)

def _new_example(self, owner):
    order = len(getattr(owner, "examples", []) or []) + 1 if owner is not None else 1
    scope = self._example_entry.get("owner_kind") or "story"
    if owner is not None and hasattr(owner, "load_example"):
        return owner.load_example(Example(self._example_name, order, {}, scope=scope))
    return Example(self._example_name, order, {}, scope=scope)

def _renumber(self, nodes: List[StoryNode]) -> None:
    for i, node in enumerate(nodes, start=1):
        node.sequential_order = i

def reorder_epics(self, new_name_order: List[str]) -> None:
    by_name = {epic.name: epic for epic in self.epics}
    if set(by_name) != set(new_name_order):
        raise ValueError("new_name_order must be a permutation of existing Epic names")
    self.epics = [by_name[name] for name in new_name_order]
    self._renumber(self.epics)

def append_increment(self, increment: Increment) -> None:
    self.increments.append(increment)
    self._renumber(self.increments)

def attach_scenarios(self, scenarios) -> None:
    """Link each Scenario to its parent Story by name."""
    stories_by_name: dict = {}
    for story in self.all_stories():
        stories_by_name.setdefault(story.name.strip(), []).append(story)
    attached_story_examples: set = set()
    for scenario in scenarios:
        target = (getattr(scenario, "story_name", None) or "").strip()
        if not target:
            continue
        extras = list(getattr(scenario, "story_examples", None) or [])
        for story in stories_by_name.get(target, []):
            story.scenarios.append(scenario)
            if extras and id(story) not in attached_story_examples:
                story.examples.extend(extras)
                attached_story_examples.add(id(story))

def all_sub_epics(self) -> List:
    """All SubEpic nodes in the tree, depth-first left-to-right."""
    result = []
    for epic in self.epics:
        self._collect_sub_epics(epic, result)
    return result

def all_stories(self) -> List:
    """All Story nodes in the tree, depth-first left-to-right."""
    result = []
    for epic in self.epics:
        for sub in epic.sub_epics:
            result.extend(sub.all_stories_recursive())
    return result

def find_epic(self, name: str) -> Epic:
    for epic in self.epics:
        if epic.name == name:
            return epic
    raise KeyError(f"Epic {name!r} not found")

def remove_increment(self, increment_name: str) -> Increment:
    for i, inc in enumerate(self.increments):
        if inc.name == increment_name:
            removed = self.increments.pop(i)
            self._renumber(self.increments)
            return removed
    raise KeyError(f"Increment {increment_name!r} not found")

def reorder_increments(self, new_name_order: List[str]) -> None:
    by_name = {inc.name: inc for inc in self.increments}
    if set(by_name) != set(new_name_order):
        raise ValueError(
            "new_name_order must be a permutation of existing Increment names"
        )
    self.increments = [by_name[name] for name in new_name_order]
    self._renumber(self.increments)

def attach_test_suites(self, suites) -> None:
    """Attach each TestSuite to the SubEpic whose name slug appears in the suite's file path."""
    import re
    self._subs_by_slug: dict = {}
    for sub in self.all_sub_epics():
        slug = re.sub(r"[^a-z0-9]+", "-", sub.name.strip().lower()).strip("-")
        self._subs_by_slug.setdefault(slug, []).append(sub)
    for suite in suites:
        self._attach_suite(suite)
    self.attach_test_cases(suites)

def _attach_suite(self, suite) -> None:
    import re
    if not (suite.source and suite.source.file):
        return
    for part in re.split(r"[\\/]+", suite.source.file):
        slug = re.sub(r"[^a-z0-9]+", "-", part.strip().lower()).strip("-")
        matches = self._subs_by_slug.get(slug)
        if not matches:
            continue
        for sub in matches:
            sub.test_suites.append(suite)
        return

def attach_test_cases(self, suites) -> None:
    """Copy TestCases onto Stories when names/paths match (language-agnostic)."""
    self._stories = list(self.all_stories())
    for suite in suites:
        self._attach_suite_cases(suite)

def _attach_suite_cases(self, suite) -> None:
    path = (suite.source.file if suite.source else "") or ""
    path_norm = self._normalized(path.replace("\\", "/"))
    for case in suite.cases:
        target = self._story_for_case(suite, path_norm)
        if target is not None:
            target.test_cases.append(case)

def _story_for_case(self, suite, path_norm: str):
    target = self._story_matching_text(path_norm)
    if target is not None:
        return target
    target = self._story_matching_text(self._normalized(suite.name))
    if target is not None:
        return target
    return self._sole_story_for_suite(suite)

def _story_matching_text(self, haystack: str):
    for story in self._stories:
        name = self._normalized(story.name)
        if name and name in haystack:
            return story
    return None

def _sole_story_for_suite(self, suite):
    if not self._stories:
        return None
    for sub in self.all_sub_epics():
        if suite in sub.test_suites and len(sub.stories) == 1:
            return sub.stories[0]
    return None

def _collect_sub_epics(self, node, out: List) -> None:
    for sub in getattr(node, "sub_epics", []):
        out.append(sub)
        self._collect_sub_epics(sub, out)

def diagram_span_columns(self) -> int:
    """DrawIO sub-epic bar width in story-pitch columns (stories + estimate text).

    Own stories and nested sub-epics both consume columns (own stories first,
    then nested children left-to-right). Estimates only widen leaf bars.
    """
    nested = sum(s.diagram_span_columns() for s in self.sub_epics)
    story_cols = len(self.stories)
    if self.sub_epics:
        return max(nested + story_cols, 1)
    estimate = self.estimate.strip()
    if not estimate:
        return max(story_cols, 1)
    if story_cols == 0:
        return max(2, min(8, (len(estimate) + 12) // 18))
    extra = max(1, min(5, (len(estimate) + 15) // 22))
    return story_cols + extra

def all_stories_recursive(self) -> List["Story"]:
    result: List[Story] = []
    for sub in self.sub_epics:
        result.extend(sub.all_stories_recursive())
    result.extend(self.stories)
    return result

def layout_column_count(self) -> int:
    """Story grid columns - named stories only (estimates are not story cells)."""
    nested = sum(s.layout_column_count() for s in self.sub_epics)
    own = len(self.stories)
    if self.sub_epics:
        return max(nested + own, 1)
    return own

