def __init__(self, instance: Any, label: str) -> None:
    self._instance = instance
    self._label = label

def extract(self) -> str:
    text = self.raw()
    YamlBinder(self._instance).bind_yaml(text)
    return strip_yaml_fences(text)

def fidelity_format(self, body: str) -> str:
    fields = YamlBinder().yaml_fields(body)
    token = fields.get("default_format") or fields.get("defaultFormat")
    if isinstance(token, str) and token.strip():
        return canonical_format(token.split()[0].strip("()`"))
    rest = self._fidelity_labeled_line(body, "Default format")
    if not rest:
        return ""
    return canonical_format(rest.split()[0].strip("()`"))

def coerce(self, text: str, return_type: Any) -> Any:
    origin = get_origin(return_type) or return_type
    if return_type is HTML or origin is HTML:
        return HTML.from_markdown(text)
    if return_type is str or return_type is inspect.Signature.empty or return_type is None:
        return MarkdownSlot(text)
    if origin is dict:
        return self.templates_path_map()
    from harness.guidance.rule import RulesCollection

    if return_type is RulesCollection:
        return RulesCollection.from_markdown(text, parent=self._instance)
    from_markdown = getattr(return_type, "from_markdown", None)
    if callable(from_markdown):
        return from_markdown(text)
    return text

def as_property(self, fn: _F) -> property:
    prop_label = self._label
    def getter(owner: Any) -> Any:
        md = Markdown.from_label(owner, prop_label)
        hints = md._return_hints(fn)
        return_type = hints.get("return", str)
        raw = md.raw()
        YamlBinder(owner).bind_yaml(raw)
        text = strip_yaml_fences(raw)
        if return_type is HTML:
            return HTML.from_markdown(text)
        origin = get_origin(return_type)
        if origin is not None:
            args = get_args(return_type)
            if origin is dict:
                return md.coerce(text, return_type)
            if args and args[0] is HTML:
                return HTML.from_markdown(text)
        if return_type is str or return_type is inspect.Signature.empty or return_type is None:
            return MarkdownSlot(text)
        result = md.coerce(raw, return_type)
        YamlBinder(result).bind_yaml(raw)
        from harness.guidance.rule import RulesCollection

        if isinstance(result, RulesCollection):
            class_dir = AssetLocator(owner, prop_label).class_file_directory()
            for rule in result:
                rule.bind_scanner(class_dir)
        return result

    getter.__doc__ = fn.__doc__
    getter.__name__ = fn.__name__
    getter.__annotations__ = dict(getattr(fn, "__annotations__", {}))
    _copy_marks(fn, getter)
    return property(getter)

def _return_hints(self, fn: Callable[..., Any]) -> dict[str, Any]:
    try:
        return get_type_hints(fn, globalns=getattr(fn, "__globals__", None))
    except Exception:
        annot = getattr(fn, "__annotations__", {}) or {}
        return dict(annot)

def templates_path_map(self) -> dict[str, str]:
    class_dir = AssetLocator(self._instance, self._label).class_file_directory()
    self._templates_folder = class_dir / "templates"
    mapping: dict[str, str] = {}
    if not self._templates_folder.is_dir():
        return mapping
    for path in sorted(self._templates_folder.rglob("*")):
        if not path.is_file() or path.name.startswith("."):
            continue
        rel = path.relative_to(class_dir).as_posix()
        key = self._format_key_for_template(path)
        if not key:
            continue
        mapping[key] = rel
    return mapping

def _format_key_for_template(self, path: Path) -> str:
    parts = path.relative_to(self._templates_folder).parts
    if len(parts) > 1:
        folder_key = _FORMAT_ALIASES.get(parts[0].casefold())
        if folder_key:
            return folder_key
    ext = path.suffix.lstrip(".").lower()
    return _EXT_TO_FORMAT.get(ext, ext)

def fidelity_clean_engineering(self, body: str) -> str:
    # **Clean Engineering:** {modules|model|code}; omit or empty → ""
    ...

def _read_stdout(self, proc: subprocess.Popen) -> None:
    try:
        assert proc.stdout
        for raw in proc.stdout:
            self.raw_lines.append(raw)
            try:
                event = json.loads(raw.strip())
            except json.JSONDecodeError:
                continue
            self.collect_shell_capture(event)
    except Exception as exc:  # noqa: BLE001
        self.thread_errors.append(f"stdout: {exc}")

def _read_stderr(self, proc: subprocess.Popen) -> None:
    try:
        assert proc.stderr
        self.stderr_chunks.append(proc.stderr.read())
    except Exception as exc:  # noqa: BLE001
        self.thread_errors.append(f"stderr: {exc}")

def collect_shell_capture(self, event: dict[str, Any]) -> None:
    etype = event.get("type")
    if etype == "assistant":
        self._collect_assistant(event)
        return
    if etype == "tool_result":
        self._collect_tool_result(event)
        return
    if etype == "tool_call":
        self._collect_tool_call(event)
        return
    if etype == "result":
        self._collect_result(event)

def _collect_assistant(self, event: dict[str, Any]) -> None:
    for block in (event.get("message") or {}).get("content") or []:
        if not isinstance(block, dict):
            continue
        self._collect_assistant_block(block)

def _collect_tool_result(self, event: dict[str, Any]) -> None:
    output = self.extract_shell_output(event, event)
    command = self.pending_shell_commands.pop(0) if self.pending_shell_commands else ""
    if output:
        self.shell_captures.append(_ShellCapture(command=command, output=output))

def _collect_tool_call(self, event: dict[str, Any]) -> None:
    subtype = str(event.get("subtype") or event.get("state") or "")
    tool_call = event.get("tool_call") or {}
    if not isinstance(tool_call, dict):
        tool_call = {}
    if subtype in ("started", "start", "running", "pending"):
        self._note_started_command(tool_call)
        return
    if subtype in ("completed", "complete", "succeeded", "success", "finished"):
        self._note_completed_command(tool_call, event)

def _collect_result(self, event: dict[str, Any]) -> None:
    text = str(event.get("result", ""))
    if text:
        self.narrative.append(text)

def _collect_assistant_block(self, block: dict[str, Any]) -> None:
    if block.get("type") == "text":
        text = str(block.get("text", ""))
        if text:
            self.narrative.append(text)
        return
    if block.get("type") != "tool_use":
        return
    command = self.shell_command_from_tool_use(block)
    if command:
        self.pending_shell_commands.append(command)

def shell_command_from_tool_use(self, block: dict[str, Any]) -> str | None:
    name = str(block.get("name", ""))
    if "shell" not in name.lower() and "terminal" not in name.lower():
        return None
    tool_input = block.get("input")
    if not isinstance(tool_input, dict):
        return None
    command = tool_input.get("command") or tool_input.get("cmd")
    return str(command) if command else None

def extract_shell_output(self, tool_call: dict[str, Any], event: dict[str, Any] | None = None) -> str | None:
    for root in (tool_call, event or {}):
        found = self._shell_output_in(root)
        if found and (self._tools_run_yaml.looks_like_tools_run_output(found) or "error" in found.lower()):
            return found
    return None

def _note_started_command(self, tool_call: dict[str, Any]) -> None:
    command = self.shell_command_from_tool_call(tool_call)
    if command:
        self.pending_shell_commands.append(command)

def _note_completed_command(self, tool_call: dict[str, Any], event: dict[str, Any]) -> None:
    output = self.extract_shell_output(tool_call, event)
    command = self.shell_command_from_tool_call(tool_call) or ""
    if not output and command and _TOOLS_RUN.search(command):
        output = command
    command = self._resolve_pending_command(command)
    if output:
        self.shell_captures.append(_ShellCapture(command=command, output=output))

def shell_command_from_tool_call(self, tool_call: dict[str, Any]) -> str | None:
    if not tool_call:
        return None
    nested = self._command_from_nested_tool_call(tool_call)
    if nested:
        return nested
    command = tool_call.get("command") or tool_call.get("cmd")
    return str(command) if command else None

def _resolve_pending_command(self, command: str) -> str:
    if not self.pending_shell_commands:
        return command
    if not command:
        return self.pending_shell_commands.pop(0)
    self.pending_shell_commands.pop(0)
    return command

def _command_from_nested_tool_call(self, tool_call: dict[str, Any]) -> str | None:
    for key in (
        "shellToolCall",
        "ShellToolCall",
        "runTerminalCommandToolCall",
        "terminalToolCall",
    ):
        if key not in tool_call or not isinstance(tool_call[key], dict):
            continue
        inner = tool_call[key]
        args = inner.get("args") if isinstance(inner.get("args"), dict) else inner
        command = args.get("command") or args.get("cmd")
        if command:
            return str(command)
    return None

def _shell_output_in(self, node: object) -> str | None:
    if isinstance(node, str):
        return self._shell_output_from_text(node)
    if not isinstance(node, dict):
        return None
    from_keys = self._shell_output_from_keys(node)
    if from_keys:
        return from_keys
    return self._shell_output_from_nested(node)

def _shell_output_from_text(self, node: str) -> str | None:
    stripped = node.strip()
    if not stripped:
        return None
    if _TOOLS_RUN.search(stripped) and not self._tools_run_yaml.looks_like_tools_run_output(stripped):
        return None
    return stripped

def _shell_output_from_keys(self, node: dict[str, Any]) -> str | None:
    for key in ("stdout", "stderr", "output", "text", "content"):
        value = node.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None

def _shell_output_from_nested(self, node: dict[str, Any]) -> str | None:
    for key, value in node.items():
        if key in ("command", "cmd", "args", "input"):
            continue
        found = self._shell_output_in(value)
        if found:
            return found
    return None

def tools_run_output(self) -> str | None:
    from_shell = self._output_from_shell_captures()
    if from_shell:
        return from_shell
    from_text = self._output_from_agent_text()
    if from_text:
        return from_text
    return self._output_from_raw_lines()

def _output_from_shell_captures(self) -> str | None:
    yaml_run = ToolsRunYaml(self.workspace)
    for shell in reversed(self.shell_captures):
        found = self._output_from_shell(yaml_run, shell)
        if found:
            return found
    return None

def _output_from_agent_text(self) -> str | None:
    yaml_run = ToolsRunYaml(self.workspace)
    for text in (self.agent_result.text, "".join(self.raw_lines)):
        found = yaml_run.fenced_yaml_from_text(text)
        if found:
            return found
    return None

def _output_from_raw_lines(self) -> str | None:
    yaml_run = ToolsRunYaml(self.workspace)
    for raw in reversed(self.raw_lines):
        found = yaml_run.fenced_yaml_from_text(raw)
        if found:
            return found
    return None

def _output_from_shell(self, yaml_run: ToolsRunYaml, shell: _ShellCapture) -> str | None:
    if yaml_run.looks_like_tools_run_output(shell.output):
        return shell.output
    for candidate in (shell.command, shell.output):
        if not _TOOLS_RUN.search(candidate):
            continue
        replayed = yaml_run.replay(candidate)
        if replayed:
            return replayed
    return None

def __eq__(self, other: object) -> bool:
    if isinstance(other, ExpansionMode):
        return self.value == other.value
    if isinstance(other, str):
        return self.value == other
    return NotImplemented

def __post_init__(self) -> None:
    if self.value not in ("instructions", "tool"):
        raise ValueError(f"mode must be 'instructions' or 'tool', got {self.value!r}")

def __init__(self, entries: dict[str, Any] | None = None, parent: Any = None) -> None:
    self.entries: dict[str, Any] = dict(entries or {})
    self.parent = parent

def tools(self) -> dict[str, AgentTool]:
    """Tools declared on this collection, not on its entries."""
    found: dict[str, AgentTool] = {}
    for name, member in AgentToolSet()._marked_members(type(self)):
        found[name] = AgentTool(
            name=name,
            callable=self._bound_callable(name, member),
            toolset=self,
        )
    return found

def bind(self, instance: Any, name: str | None = None) -> None:
    from harness.markdown.markdown import MarkdownCollection

    MarkdownCollection.bind(self, instance, name)

def _bound_callable(self, name: str, member: Any) -> Any:
    attr = getattr(type(self), name, None)
    if inspect.isfunction(member) and attr is member:
        return getattr(self, name)
    return member

def __init__(
    self,
    entries: dict[str, Any] | list[Any] | None = None,
    parent: Any = None,
) -> None:
    self.entries: dict[str, Any] | list[Any] = entries if entries is not None else {}
    self.parent = parent
    self._markdown = ""
    self.yaml: dict[str, str] = {}
    for child in self:
        child.parent = self

def __iter__(self):
    values = self.entries.values() if isinstance(self.entries, dict) else self.entries
    return iter(values)

def bind(self, instance: Any, name: str | None = None) -> None:
    self.parent = instance
    previous = vars(instance).get(name) if name else None
    if name is not None:
        vars(instance)[name] = self
    for attr, value in list(vars(instance).items()):
        if value is self:
            continue
        if value is previous or (name is None and type(value) is type(self)):
            vars(instance)[attr] = self

def from_markdown(cls, text: str, parent: Any = None) -> MarkdownCollection:
    entries: dict[str, Any] = {}
    for name, body in MarkdownText(text).section_child_blocks():
        entry = cls.child(name, body)
        if entry is None:
            continue
        YamlBinder(entry).bind_yaml(body)
        entries[name] = entry
    collection = cls(entries, parent=parent)
    collection.markdown = text
    return collection

def coerce(cls, markdown: Markdown, return_type: Any, parent: Any = None) -> Any:
    text = markdown.raw()
    origin = get_origin(return_type) or return_type
    if origin is list:
        return cls.from_list(markdown)
    builder = getattr(return_type, "from_markdown", None)
    if callable(builder) and return_type is not cls:
        try:
            result = builder(text, parent=parent)
        except TypeError:
            result = builder(text)
        holder = cls(parent=parent)
        holder.markdown = text
        holder.keep_extract(result)
        return result
    return cls.from_markdown(text, parent=parent)

def keep_extract(self, result: Any) -> None:
    if result is None:
        return
    result.markdown = self._markdown

def markdown_collection(
    self, fn: _F | str | None = None, *, label: str | None = None
) -> property | Callable[[_F], property]:
    if callable(fn):
        return self.as_property(fn)

    def decorator(inner: _F) -> property:
        holder = MarkdownCollection()
        holder._label = str(label or fn or inner.__name__)
        return holder.as_property(inner)

    return decorator

def description(self) -> str:
    from harness.markdown.markdown import Markdown

    expanded = Markdown.from_label(self.toolset, "").expand_docstring(self.docstring)
    if expanded:
        return expanded
    if self.name == "instructions":
        overview = getattr(self.toolset, "overview", None)
        if callable(overview):
            overview = overview()
        if isinstance(overview, str) and overview.strip():
            return overview.strip()
    return self.docstring or self.callable.__name__

def response(self) -> str | None:
    sig = inspect.signature(self.callable)
    if sig.return_annotation is inspect.Signature.empty:
        return None
    return self._format_type(sig.return_annotation)

def parameters(self) -> dict[str, str]:
    sig = inspect.signature(self.callable)
    parameters: dict[str, str] = {}
    for name, param in sig.parameters.items():
        if name in ("self", "cls"):
            continue
        if param.kind in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):
            continue
        parameters[name] = self._format_type(param.annotation)
    return parameters

def _format_type_from_string(self, annotation_text: str) -> str:
    origin_name, _, args_text = annotation_text.partition("[")
    if origin_name == "list":
        element_text = args_text.rstrip("]") if args_text else "str"
        return f"list[{self._format_type(element_text)}]"
    return annotation_text

def _format_builtin_type(self, annotation: Any, origin: Any) -> str:
    if annotation is str:
        return "str"
    if annotation is int:
        return "int"
    if annotation is float:
        return "float"
    if annotation is bool:
        return "bool"
    if annotation in (None, type(None)):
        return "None"
    if origin is not None:
        return getattr(annotation, "__name__", str(origin))
    return getattr(annotation, "__name__", str(annotation))

def _property(self, fn: Callable[..., Any]) -> property:
    name = fn.__name__
    return_type = self._return_type(fn)

    def getter(owner: Any) -> Any:
        return type(self).of(owner, name, return_type)

    getter.__doc__ = fn.__doc__
    getter.__name__ = name
    getter.__annotations__ = dict(getattr(fn, "__annotations__", {}))
    type(self)._copy_marks(fn, getter)
    return property(getter)

def _copy_marks(cls, src: Any, dest: Any) -> None:
    for attr in _COLLECT_MARKS:
        if hasattr(src, attr):
            setattr(dest, attr, getattr(src, attr))

def _wrap(cls, collection: Any, name: str, return_type: Any) -> Any:
    collector = object.__new__(cls)
    entries = getattr(collection, "entries", None)
    if not isinstance(entries, dict):
        entries = {
            getattr(child, "name", str(index)): child
            for index, child in enumerate(collection)
        }
    bundled = {key: collector._value(child, name) for key, child in entries.items()}
    try:
        return return_type(bundled, parent=collection)
    except TypeError:
        return return_type(bundled)

def _value(self, child: Any, name: str) -> Any:
    value = getattr(child, name, None)
    if callable(value):
        return value()
    return value

def name(self) -> str:
    stored = getattr(self, "_name", None)
    if isinstance(stored, str) and stored:
        return stored
    return self._slugify_class_name(type(self).__name__)

def install_folder(self) -> Path:
    try:
        return Path(inspect.getfile(type(self))).resolve().parent
    except (TypeError, OSError):
        return Path(self.slug)

def tools(self) -> dict[str, AgentTool]:
    merged: dict[str, AgentTool] = {}
    merged.update(self.operations)
    merged.update(self._discover_instruction_members())
    for name, tool in self._discover_hook_members().items():
        merged.setdefault(name, tool)
    merged.update(self._discover_collection_tools())
    return merged

def toolset_collections(self) -> list[Any]:
    found: list[Any] = []
    for name, member in self._annotated_members(type(self)):
        if name in self._COLLECTION_SKIP:
            continue
        if not getattr(member, "_is_toolset_collection", False):
            continue
        value = getattr(self, name, None)
        if value is None or value is self:
            continue
        found.append(value)
    return found

def child_toolsets(self):
    for collection in self.toolset_collections:
        yield from collection

def prompt(self) -> tuple[str, ...]:
    self._scan()
    return tuple(self._prompt)

def tools(self) -> list[str]:
    self._scan()
    return list(dict.fromkeys(self._tools))

def self_member_name(self, node: ast.AST) -> str | None:
    if isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id == "self":
            return func.attr
        return None
    if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id == "self":
        return node.attr
    return None

def for_callable(
    cls,
    callable: Callable[..., Any],
    instance: AgentToolSet | None = None,
) -> AgentInstructions:
    if instance is not None:
        if isinstance(callable, property):
            callable = callable.fget
        return instance._discover_instruction_members()[callable.__name__]
    return cls(
        name=callable.__name__,
        callable=callable,
        toolset=AgentToolSet(),
    )

def result_template(self) -> str:
    function_def = self._require_function_def(self.callable)
    result_template = self._result_template_from(function_def)
    if not result_template and self._is_empty_action_body(function_def):
        result_template = self._resolve_parent_result_template()
    if not result_template:
        result_template = f"Instructions for {self.callable.__name__}"
    return result_template

def _require_function_def(self, action_func: Callable[..., Any]) -> ast.FunctionDef:
    module = self.parse_source(action_func)
    function_def = module.body[0]
    if not isinstance(function_def, ast.FunctionDef):
        raise AgentToolValidationError(
            "action body is not a function",
            class_name=action_func.__qualname__,
            action_name=action_func.__name__,
        )
    return function_def

def _is_empty_action_body(self, function_def: ast.FunctionDef) -> bool:
    skipped_docstring = False
    saw_ellipsis = False
    saw_valued_return = False
    for statement in function_def.body:
        if isinstance(statement, ast.Pass):
            continue
        if isinstance(statement, ast.Return):
            if not self._is_empty_return(statement):
                saw_valued_return = True
            continue
        if isinstance(statement, ast.Expr):
            expr_value = statement.value
            if self._is_leading_docstring(statement, skipped_docstring):
                skipped_docstring = True
                continue
            if self._is_ellipsis_expr(expr_value):
                saw_ellipsis = True
                continue
            return False
        return False
    if saw_valued_return and not saw_ellipsis:
        return False
    return True

def _bind_parameter_defaults(self) -> None:
    try:
        signature = inspect.signature(self.callable)
    except (TypeError, ValueError):
        return
    for parameter in signature.parameters.values():
        if parameter.name in {"self", "cls"} or parameter.name in self._execution_locals:
            continue
        if parameter.kind in (
            inspect.Parameter.VAR_POSITIONAL,
            inspect.Parameter.VAR_KEYWORD,
        ):
            continue
        default = parameter.default
        self._execution_locals[parameter.name] = (
            None if default is inspect.Parameter.empty else default
        )

def _walk_statements(self, function_def: ast.FunctionDef) -> None:
    skipped_docstring = False
    for statement in function_def.body:
        if isinstance(statement, ast.Return):
            if statement.value is not None:
                try:
                    value = self._eval_expr(statement.value)
                except Exception:
                    value = self._expression_text(statement.value)
                if isinstance(value, str) and value.strip():
                    self._add_prompt(value.strip())
            continue
        if isinstance(statement, ast.Expr) and self._is_ellipsis_expr(statement.value):
            continue
        if self._is_leading_docstring(statement, skipped_docstring):
            skipped_docstring = True
            self._add_prompt(statement.value.value.strip())
            continue
        self._dispatch_statement(statement)

def _merge_from(self, other: AgentInstructions) -> None:
    self._tools.extend(other.deferred_tools())
    for part in other.deferred_prompt():
        self._add_prompt(part)

def _add_prompt(self, text: str) -> None:
    if text and text not in self._seen_prompt:
        self._prompt.append(text)
        self._seen_prompt.add(text)

def _effective_mode(self, target: Any) -> str:
    if target is self.toolset:
        return self._mode
    loop_mode = self._loop_item_modes.get(id(target))
    if loop_mode is not None:
        return loop_mode
    mode = getattr(target, "mode", "instructions")
    return mode.value if isinstance(mode, ExpansionMode) else str(mode)

def _find_parent_action(self, after_class: type | None) -> tuple[Callable[..., Any], type] | None:
    own_class = type(self.toolset)
    method_name = self.callable.__name__
    own_func = own_class.__dict__.get(method_name)
    past_anchor = after_class is None
    for klass in own_class.__mro__:
        if not past_anchor:
            past_anchor = klass is after_class
            continue
        if method_name not in klass.__dict__:
            continue
        func = klass.__dict__[method_name]
        if after_class is None and func is own_func:
            continue
        if callable(func) and getattr(func, "_is_agent_instructions", False):
            return func, klass
    return None

def _resolve_super_func(
    self,
    after_class: type | None = None,
) -> tuple[Callable[..., Any], type] | None:
    if type(self.toolset).__dict__.get(self.callable.__name__) is None:
        return None
    return self._find_parent_action(after_class)

def _is_empty_return(self, statement: ast.Return) -> bool:
    if statement.value is None:
        return True
    if isinstance(statement.value, ast.Constant) and statement.value.value in ("", None):
        return True
    return False

def _super_call_name(self, node: ast.AST) -> str | None:
    if not isinstance(node, ast.Call):
        return None
    func = node.func
    if not isinstance(func, ast.Attribute):
        return None
    receiver = func.value
    if not isinstance(receiver, ast.Call):
        return None
    if not isinstance(receiver.func, ast.Name):
        return None
    if receiver.func.id != "super":
        return None
    return func.attr

def _wrapped_member_name(self, node: ast.AST | None) -> str | None:
    if node is None:
        return None
    self_name = self.self_member_name(node)
    if self_name is not None:
        return self_name
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        return node.func.attr
    if isinstance(node, ast.Attribute):
        return node.attr
    return None

def _resolve_provider(self, instance: Any, provider_name: str) -> Any:
    raw = getattr(instance, provider_name)
    if getattr(type(raw), "_is_agent_toolset", False):
        return raw
    return raw() if callable(raw) else raw

def _expand_target_member(self, member: str, target: Any) -> None:
    if target is None:
        self._tools.append(member)
        return
    target_cls = type(target)
    if member in self.toolset.instruction_names(target_cls):
        self._expand_member(member, target)
        return
    if member in self.toolset.marked_tool_names(target_cls):
        self._tools.append(member)

def _mode_assign_value(self, statement: ast.stmt) -> str | None:
    if not isinstance(statement, ast.Assign) or len(statement.targets) != 1:
        return None
    target = statement.targets[0]
    if not isinstance(target, ast.Attribute) or target.attr != "mode":
        return None
    is_self = isinstance(target.value, ast.Name) and target.value.id == "self"
    if not is_self:
        return None
    if isinstance(statement.value, ast.Constant) and isinstance(statement.value.value, str):
        return statement.value.value
    return None

def _loop_var_mode_assign(self, statement: ast.stmt, var_name: str) -> str | None:
    if not isinstance(statement, ast.Assign) or len(statement.targets) != 1:
        return None
    target = statement.targets[0]
    if not (
        isinstance(target, ast.Attribute)
        and isinstance(target.value, ast.Name)
        and target.value.id == var_name
        and target.attr == "mode"
    ):
        return None
    if isinstance(statement.value, ast.Constant) and isinstance(statement.value.value, str):
        return statement.value.value
    return None

def _loop_item_instructions(self, arg: ast.AST) -> bool:
    if self._loop_item is None or self._loop_var is None:
        return False
    names = self._attr_chain(arg)
    if not names or names[0] != self._loop_var:
        return False
    target: Any = self._loop_item
    for name in names[1:-1]:
        target = getattr(target, name, None)
        if target is None:
            return False
    member = names[-1]
    self._expand_target_member(member, target)
    return True

def _expand_loop_attr_tool(self, arg: ast.AST) -> bool:
    loop_var = self._loop_var
    if not loop_var or not isinstance(arg, ast.Call):
        return False
    if not isinstance(arg.func, ast.Attribute):
        return False
    if not isinstance(arg.func.value, ast.Name) or arg.func.value.id != loop_var:
        return False
    self._expand_target_member(arg.func.attr, self._loop_item)
    return True

def _expand_self_tool_arg(self, arg: ast.AST) -> bool:
    if self._loop_var is not None:
        return False
    member_name = self.self_member_name(arg)
    if not member_name:
        return False
    self._expand_target_member(member_name, self.toolset)
    return True

def _dispatch_tools_arg(self, arg: ast.AST | None) -> bool:
    if arg is None:
        return False
    if self._expand_cross_arg(arg):
        return True
    if self._expand_loop_attr_tool(arg):
        return True
    if self._expand_self_tool_arg(arg):
        return True
    member = self._wrapped_member_name(arg)
    if member:
        self._tools.append(member)
        return True
    return False

def _walk_for_each_wrapped(self, body_stmt: ast.stmt) -> bool:
    if not isinstance(body_stmt, ast.Expr) or not isinstance(body_stmt.value, ast.Call):
        return False
    call = body_stmt.value
    if not isinstance(call.func, ast.Name) or call.func.id not in ("tools", "instructions"):
        return False
    arg = call.args[0] if call.args else None
    if arg is None:
        return False
    var_name = self._loop_var
    target_item = self._loop_item
    if call.func.id == "tools":
        return self._dispatch_tools_arg(arg)
    if isinstance(arg, ast.Call) and isinstance(arg.func, ast.Attribute):
        if isinstance(arg.func.value, ast.Name) and arg.func.value.id == var_name:
            self._expand_target_member(arg.func.attr, target_item)
            return True
    if isinstance(arg, ast.Attribute) and isinstance(arg.value, ast.Name):
        if arg.value.id == var_name:
            self._expand_target_member(arg.attr, target_item)
            return True
    if self._loop_item_instructions(arg):
        return True
    return self._expand_cross_arg(arg)

def _is_companion_for(self, stmt: ast.For) -> bool:
    if not isinstance(stmt.target, ast.Name):
        return False
    if not isinstance(stmt.iter, ast.Call):
        return False
    return self.self_member_name(stmt.iter) is not None

def _execution_env(self) -> dict[str, Any]:
    import builtins

    env: dict[str, Any] = {
        "__builtins__": builtins,
        "self": self.toolset,
        "tools": self._expander_stub_tools,
        "instructions": self._expander_stub_instructions,
    }
    module = inspect.getmodule(self.callable)
    if module is not None:
        env.update(vars(module))
    env.update(self._execution_locals)
    return env

def _sync_execution_locals(self, env: dict[str, Any]) -> None:
    reserved = {"__builtins__", "self", "tools", "instructions"}
    for name, value in env.items():
        if name in reserved or name.startswith("__"):
            continue
        self._execution_locals[name] = value

def _run_expr(self, node: ast.expr) -> None:
    try:
        value = self._eval_expr(node)
    except Exception:  # noqa: BLE001
        return
    if isinstance(value, str) and value.strip():
        self._add_prompt(value.strip())
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            if isinstance(item, str) and item.strip():
                self._add_prompt(item.strip())

def _dispatch_statement(self, statement: ast.stmt) -> None:
    mode_value = self._mode_assign_value(statement)
    if mode_value is not None:
        self._mode = mode_value
        return
    if self._dispatch_compound_statement(statement):
        return
    self._dispatch_simple_statement(statement)

def _walk_generic_for(self, stmt: ast.For) -> None:
    if not isinstance(stmt.target, ast.Name):
        self._execute_statement(stmt)
        return
    var_name = stmt.target.id
    try:
        items = self._eval_expr(stmt.iter)
    except Exception:  # noqa: BLE001
        items = []
    if not isinstance(items, (list, tuple)):
        items = list(items) if items is not None else []
    previous = self._execution_locals.get(var_name, _EXEC_LOCAL_MISSING)
    for item in items:
        self._execution_locals[var_name] = item
        self._dispatch_for_body(stmt.body, loop_var=var_name, loop_item=item)
    if previous is _EXEC_LOCAL_MISSING:
        self._execution_locals.pop(var_name, None)
    else:
        self._execution_locals[var_name] = previous
    for body_stmt in stmt.orelse:
        self._dispatch_statement(body_stmt)

def _dispatch_instructions_arg(self, arg: ast.AST | None) -> bool:
    if arg is None:
        return False
    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
        self._add_prompt(arg.value.strip())
        return True
    if isinstance(arg, ast.JoinedStr):
        self._add_prompt(self._joined_string(arg))
        return True
    if self._loop_item_instructions(arg):
        return True
    if self._expand_instructions_cross(arg):
        return True
    member = self._wrapped_member_name(arg)
    if member and member in self.toolset.instruction_names(type(self.toolset)):
        self._expand_member(member, self.toolset)
        return True
    try:
        value = self._eval_expr(arg)
    except Exception:
        value = None
    if isinstance(value, str) and value.strip():
        self._add_prompt(value.strip())
        return True
    return False

def _dispatch_expr_statement(self, statement: ast.Expr) -> None:
    value = statement.value
    if isinstance(value, ast.Constant) and isinstance(value.value, str):
        self._add_prompt(value.value.strip())
        return
    if self._super_call_name(value) is not None:
        self._walk_super()
        return
    if isinstance(value, ast.Call) and isinstance(value.func, ast.Name):
        arg = value.args[0] if value.args else None
        if value.func.id == "tools":
            if self._dispatch_tools_arg(arg):
                return
        if value.func.id == "instructions":
            if self._dispatch_instructions_arg(arg):
                return
    if isinstance(value, ast.Call):
        self._expand_call_member(value)
        return
    self._run_expr(value)

def _expand_call_member(self, value: ast.Call) -> None:
    member = self._wrapped_member_name(value)
    if not member:
        self._run_expr(value)
        return
    target = self.toolset
    if isinstance(value.func, ast.Attribute) and isinstance(value.func.value, ast.Call):
        provider = self.self_member_name(value.func.value)
        if provider:
            target = self._resolve_provider(self.toolset, provider)
    self._expand_target_member(member, target)
    if member in self.toolset.marked_tool_names(type(target)):
        self._run_expr(value)

def _dispatch_if_statement(self, statement: ast.If) -> None:
    try:
        take_body = bool(self._eval_expr(statement.test))
    except Exception:  # noqa: BLE001
        take_body = False
    branch = statement.body if take_body else statement.orelse
    for body_stmt in branch:
        self._dispatch_statement(body_stmt)

def _dispatch_try_statement(self, statement: ast.Try) -> None:
    for body_stmt in statement.body:
        self._dispatch_statement(body_stmt)

def _dispatch_for_statement(self, statement: ast.For) -> None:
    if self._is_companion_for(statement):
        self._walk_for_each_statement(statement)
        return
    self._walk_generic_for(statement)

def _walk_for_each_statement(self, stmt: ast.For) -> None:
    iter_node, loop_var = stmt.iter, stmt.target
    if not (isinstance(loop_var, ast.Name) and isinstance(iter_node, ast.Call)):
        return
    iter_member = self.self_member_name(iter_node)
    if iter_member is None:
        return
    try:
        items = getattr(self.toolset, iter_member)()
    except Exception:  # noqa: BLE001
        items = []
    if not isinstance(items, (list, tuple)):
        items = []
    if not items:
        items = [None]
    for target_item in items:
        self._dispatch_for_body(stmt.body, loop_var=loop_var.id, loop_item=target_item)

def _dispatch_compound_statement(self, statement: ast.stmt) -> bool:
    if isinstance(statement, ast.If):
        self._dispatch_if_statement(statement)
        return True
    if isinstance(statement, ast.Try):
        self._dispatch_try_statement(statement)
        return True
    if isinstance(statement, ast.For):
        self._dispatch_for_statement(statement)
        return True
    return False

def _dispatch_simple_statement(self, statement: ast.stmt) -> None:
    if isinstance(statement, ast.With):
        self._execute_statement(statement)
        return
    if isinstance(statement, ast.Expr):
        self._dispatch_expr_statement(statement)
        return
    if isinstance(statement, ast.Pass):
        return
    self._execute_statement(statement)

def _validate_wrapper_arg(self, wrapper: str, arg: ast.AST | None) -> bool:
    if arg is None:
        if wrapper == "tools":
            raise AgentToolValidationError(
                f"{wrapper}(...) requires one argument",
                class_name=self._class_name,
                action_name=self._action_name,
            )
        return False
    if self._host.provider_cross_call(arg) is not None:
        return True
    if self._loop_vars and self._host.provider_cross_call(
        arg, frozenset(self._loop_vars)
    ) is not None:
        return True
    if isinstance(arg, ast.Call) and isinstance(arg.func, ast.Attribute):
        if isinstance(arg.func.value, ast.Name) and arg.func.value.id in self._loop_vars:
            return True
    if isinstance(arg, ast.Attribute) and isinstance(arg.value, ast.Name):
        if arg.value.id in self._loop_vars:
            return True
    member = self._instructions.self_member_name(arg)
    if member is not None:
        self._check_member(member)
        return True
    if wrapper == "tools":
        raise AgentToolValidationError(
            f"{wrapper}(...) argument is not a recognized tool step",
            class_name=self._class_name,
            action_name=self._action_name,
        )
    return False

def _check_member(self, member_name: str) -> None:
    if member_name in self._allowed_names or member_name in self._all_providers:
        return
    raise AgentToolValidationError(
        f"{member_name!r} is not an allowed tool step",
        class_name=self._class_name,
        action_name=self._action_name,
    )

def visit_Call(self, node: ast.Call) -> None:
    if isinstance(node.func, ast.Name) and node.func.id == "tools":
        if self._validate_wrapper_arg("tools", node.args[0] if node.args else None):
            return
    if isinstance(node.func, ast.Name) and node.func.id == "instructions":
        if self._validate_wrapper_arg(
            "instructions", node.args[0] if node.args else None
        ):
            return
    self.generic_visit(node)

def install_to(self, destination: str) -> bool:
    if destination == InstallDestination.MCP:
        return self.install_to_mcp
    if destination == InstallDestination.HOOK:
        return self.install_to_hook
    if destination == InstallDestination.SKILL:
        return self.install_to_skill
    if destination == InstallDestination.COMMAND:
        return self.install_to_command
    if destination == InstallDestination.RULE:
        return self.install_to_rule
    return False

def destinations(self) -> list[str]:
    destinations: list[str] = []
    if self.install_to_mcp:
        destinations.append(InstallDestination.MCP)
    if self.install_to_skill:
        destinations.append(InstallDestination.SKILL)
    if self.install_to_command:
        destinations.append(InstallDestination.COMMAND)
    if self.install_to_rule:
        destinations.append(InstallDestination.RULE)
    if self.install_to_hook:
        destinations.append(InstallDestination.HOOK)
    return destinations

def __new__(cls, fn: Callable[..., Any] | None = None):
    mark = object.__new__(cls)
    if callable(fn):
        return mark.annotate(fn)
    return mark

def annotate(self, fn: Callable[..., Any]) -> Callable[..., Any]:
    setattr(fn, self.flag, True)
    return fn

def __new__(cls, fn: Callable[..., Any] | None = None):
    mark = object.__new__(cls)
    if callable(fn):
        return mark.annotate(fn)
    return mark

def annotate(self, fn: Callable[..., Any]) -> Callable[..., Any]:
    setattr(fn, self.flag, True)
    return fn

def __get__(self, instance: Any, owner: type | None = None) -> "ToolsetManifest":
    cls = owner if owner is not None else self._toolset_cls
    if cls is None:
        return self
    bound = ToolsetManifest(cls)
    return bound

def signature(self) -> dict[str, dict[str, Any]]:
    if self._toolset_cls is None:
        return {}
    instance = self._toolset_cls()
    signature: dict[str, dict[str, Any]] = {}
    for name, tool in instance.tools.items():
        kind = "action" if tool.kind == "instructions" else tool.kind
        entry: dict[str, Any] = {"kind": kind}
        nested = getattr(tool, "tools", None)
        if nested:
            entry["tools"] = list(nested)
        prompt = getattr(tool, "prompt", None)
        if prompt:
            entry["instructions"] = "\n".join(prompt)
        signature[name] = entry
    return signature

def __new__(cls, target: type | None = None):
    mark = object.__new__(cls)
    if isinstance(target, type):
        return mark.annotate(target)
    return mark

def annotate(self, toolset_cls: type) -> type:
    if "_is_agent_toolset" in toolset_cls.__dict__:
        return toolset_cls
    if getattr(toolset_cls, "_is_agent_toolset", False):
        AgentToolSet()._validate_toolset(toolset_cls)
        return toolset_cls
    if issubclass(toolset_cls, AgentToolSet):
        raise TypeError(
            f"{toolset_cls.__name__} must use @agent_toolset — do not subclass AgentToolSet directly"
        )
    merged = type(
        toolset_cls.__name__,
        (toolset_cls, AgentToolSet),
        {
            attribute_name: attribute_value
            for attribute_name, attribute_value in vars(toolset_cls).items()
            if attribute_name not in ("__dict__", "__weakref__")
        },
    )
    merged.__doc__ = toolset_cls.__doc__
    merged.__module__ = toolset_cls.__module__
    merged.__qualname__ = toolset_cls.__qualname__
    setattr(merged, "_is_agent_toolset", True)
    merged.manifest = ToolsetManifest(merged)
    AgentToolSet()._validate_toolset(merged)
    return merged

def __new__(cls, target: Any = None):
    mark = object.__new__(cls)
    if target is not None:
        return mark.annotate(target)
    return mark

def annotate(self, target: Any) -> Any:
    if not inspect.isclass(target):
        fn = getattr(target, "fget", target)
        setattr(fn, self.flag, True)
        return target
    if "_is_toolset_collection" in target.__dict__:
        return target
    if getattr(target, "_is_toolset_collection", False):
        return target
    if issubclass(target, ToolSetCollection):
        raise TypeError(
            f"{target.__name__} must use @toolset_collection — do not subclass ToolSetCollection directly"
        )
    merged = type(
        target.__name__,
        (target, ToolSetCollection),
        {
            attribute_name: attribute_value
            for attribute_name, attribute_value in vars(target).items()
            if attribute_name not in ("__dict__", "__weakref__")
        },
    )
    merged.__doc__ = target.__doc__
    merged.__module__ = target.__module__
    merged.__qualname__ = target.__qualname__
    setattr(merged, "_is_toolset_collection", True)
    return merged

def create(cls, token: Optional[str] = None) -> "MiroApiClient":
    client = cls(token)
    if client.token:
        return client
    raise MiroAuthError(
        "Miro API token not found. "
        "Set MIRO_TOKEN env var, create ~/.miro-token, "
        "or get a PAT at https://miro.com/app/settings/user-profile/apps"
    )

def _resolve_token(self) -> Optional[str]:
    tok = os.environ.get("MIRO_TOKEN", "").strip()
    if tok:
        return tok
    for candidate in [
        os.path.expanduser("~/.miro-token"),
        os.path.join(".cursor", "miro-token.txt"),
    ]:
        if os.path.isfile(candidate):
            raw = open(candidate, encoding="utf-8-sig").read().strip()
            return raw or None
    return None

def delete_shape(self, board_id: str, shape_id: str) -> None:
    """Delete one shape. Silently ignores 404 (already gone)."""
    try:
        self._request("DELETE", f"/boards/{self._encode(board_id)}/shapes/{shape_id}")
    except MiroApiError as exc:
        if exc.status != 404:
            raise

def list_shapes(self, board_id: str) -> Iterator[dict]:
    """Paginate through all shapes on the board."""
    cursor: Optional[str] = None
    while True:
        params: dict[str, Any] = {"limit": 50}
        if cursor:
            params["cursor"] = cursor
        page = self._request("GET", f"/boards/{self._encode(board_id)}/shapes", params=params)
        for item in page.get("data", []):
            yield item
        cursor = page.get("cursor")
        has_more = page.get("has_more", False)
        if not has_more or not cursor:
            break

def read_tiers(
    self,
    architecture_context_path: Optional[Path],
    tests_root: Optional[Path] = None,
) -> Tuple[str, ...]:
    if architecture_context_path is not None and architecture_context_path.exists():
        tiers = self._read_from_prose(architecture_context_path.read_text(encoding="utf-8"))
        if tiers:
            return tiers
    if tests_root is not None and tests_root.exists():
        return self._infer_from_filesystem(tests_root)
    return ()

def _collect_tier_bullets(self, lines: Sequence[str], heading_index: int) -> list[str]:
    collected: list[str] = []
    for j in range(heading_index + 1, len(lines)):
        raw = lines[j]
        if raw.startswith("#"):
            break
        m = self._TIER_BULLET.match(raw)
        if not m:
            if raw.strip() == "" or raw.startswith(" ") or raw.startswith("\t"):
                continue
            if raw.strip() and not raw.startswith("-") and not raw.startswith("*"):
                break
            continue
        tier = m.group("tier").lower()
        if tier in self._KNOWN_TIER_HINTS or self._looks_like_tier(tier):
            collected.append(tier)
    return collected

def _dedupe_ordered(self, items: Iterable[str]) -> Tuple[str, ...]:
    seen: set[str] = set()
    ordered: list[str] = []
    for item in items:
        if item in seen:
            continue
        seen.add(item)
        ordered.append(item)
    return tuple(ordered)

def source_files(self, directory: Path) -> List[Path]:
    files: List[Path] = []
    for f in sorted(directory.rglob("*.ts")):
        if "node_modules" not in f.parts:
            files.append(f)
    for f in sorted(directory.rglob("*.tsx")):
        if "node_modules" not in f.parts:
            files.append(f)
    return files

def parse_file(self, path: Path):
    self._tree = None
    if not _TREE_SITTER_AVAILABLE:
        return None
    try:
        content = path.read_bytes()
        parser = _TSX_PARSER if path.suffix == ".tsx" else _TS_PARSER
        self._tree = parser.parse(content).root_node
        return self._tree
    except Exception:
        return None

def _find_all(self, node, *types: str) -> list:
    results: list = []
    if node.type in types:
        results.append(node)
    for child in node.children:
        results.extend(self._find_all(child, *types))
    return results

def _get_modifiers(self, node) -> List[str]:
    mods: List[str] = []
    for child in node.children:
        if child.type in self._MODIFIER_TYPES:
            mods.append(child.type)
        elif child.type == "accessibility_modifier":
            mods.append(self._txt(child))
    return mods

def _first_type_in_clause(self, clause) -> str:
    for item in clause.children:
        name = self._type_name_from_item(item)
        if name:
            return name
    return ""

def _type_names_in_clause(self, clause) -> List[str]:
    names: List[str] = []
    for item in clause.children:
        name = self._type_name_from_item(item)
        if name:
            names.append(name)
    return names

def _specifier_names(self, named_imports) -> List[str]:
    names: List[str] = []
    for spec in named_imports.children:
        if spec.type != "import_specifier":
            continue
        nm = spec.child_by_field_name("name")
        if nm:
            names.append(self._txt(nm))
    return names

def _append_exported_interfaces(self, root, interfaces: List[InterfaceInfo]) -> None:
    for node in self._find_all(root, "export_statement"):
        inner = node.child_by_field_name("declaration")
        if inner is None or inner.type != "interface_declaration":
            continue
        name = self._txt(inner.child_by_field_name("name"))
        if any(i.name == name for i in interfaces):
            continue
        methods, properties = self._interface_members(inner.child_by_field_name("body"))
        interfaces.append(
            InterfaceInfo(
                name=name,
                method_names=methods,
                property_names=properties,
                is_exported=True,
                start_line=inner.start_point[0] + 1,
            )
        )

def _parse_calls_from_root(self, root) -> List[CallInfo]:
    calls: List[CallInfo] = []
    for node in self._find_all(root, "call_expression"):
        fn_node = node.child_by_field_name("function")
        args_node = node.child_by_field_name("arguments")
        calls.append(
            CallInfo(
                callee=self._txt(fn_node) if fn_node else "",
                args_text=self._txt(args_node) if args_node else "",
                start_line=node.start_point[0] + 1,
            )
        )
    return calls

def _classes_from_tree(self, root) -> List[ClassInfo]:
    classes: List[ClassInfo] = []
    seen_names: set = set()
    for node in self._find_all(root, "export_statement"):
        inner = node.child_by_field_name("declaration")
        if inner and inner.type == "class_declaration":
            ci = self._parse_class_node(inner, is_exported=True)
            seen_names.add(ci.name)
            classes.append(ci)
    for node in self._find_all(root, "class_declaration"):
        if node.parent is not None and node.parent.type == "export_statement":
            continue
        ci = self._parse_class_node(node, is_exported=False)
        if ci.name not in seen_names:
            classes.append(ci)
    return classes

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []

    for domain_path in self._find_domain_packages(root):
        violations += self._check_domain(domain_path)

    return violations

def _extract_param_names(self, params_str: str) -> List[str]:
    names = []
    for part in params_str.split(","):
        part = part.strip()
        if not part:
            continue
        m = _PARAM_NAME_RE.match(part)
        if m:
            names.append(m.group(1))
    return names

def _extract_methods_with_params(self, path: Path) -> Dict[str, List[str]]:
    result: Dict[str, List[str]] = {}
    try:
        content = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return result
    for m in _METHOD_WITH_PARAMS_RE.finditer(content):
        name = m.group(1)
        if name == "constructor" or name[0].isupper():
            continue
        params = self._extract_param_names(m.group(2))
        if params:
            result[name] = params
    return result

def _check_domain(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []

    shared_dir = domain_path / "shared"
    server_dir = domain_path / "server"
    if not shared_dir.exists() or not server_dir.exists():
        return violations

    shared_methods: Dict[str, List[str]] = {}
    for ts_file in shared_dir.glob("*.ts"):
        if ts_file.name in ("index.ts",) or ts_file.name.endswith(".schema.ts"):
            continue
        shared_methods.update(self._extract_methods_with_params(ts_file))

    service_methods: Dict[str, List[str]] = {}
    for ts_file in server_dir.glob("*.service.ts"):
        service_methods.update(self._extract_methods_with_params(ts_file))

    for method_name, shared_params in shared_methods.items():
        if method_name in service_methods:
            service_params = service_methods[method_name]
            service_domain_params = [p for p in service_params if p not in ("req", "res", "body")]
            for i, (sp, svc_p) in enumerate(zip(shared_params, service_domain_params)):
                if sp != svc_p:
                    violations.append(
                        self.v(
                            f"Arg name drift in '{method_name}': shared/ uses "
                            f"'{sp}' but service uses '{svc_p}' at position {i}. "
                            "Keep the same name across layers.",
                            str(server_dir),
                            severity="warning",
                        )
                    )

    return violations

def _find_domain_packages(self, project_root: Path) -> List[Path]:
    """Domain dirs under packages/ — either top-level or nested inside a
    feature package (e.g. ``packages/wires/recipients/``). A domain dir
    has the three-file layout (``<domain>.ts``, ``<domain>-server.ts``,
    ``<domain>-client.tsx``) or legacy ``shared/`` / ``client/`` /
    ``server/`` folders. Excludes composition roots."""
    packages_dir = project_root / "packages"
    if not packages_dir.exists():
        return []

    excluded = {"node_modules"}
    domain_packages: List[Path] = []

    def consider(path: Path) -> None:
        if self._is_domain_dir(path) and path not in domain_packages:
            domain_packages.append(path)

    for child in packages_dir.iterdir():
        if not child.is_dir():
            continue
        if child.name in excluded or child.name.startswith("."):
            continue
        consider(child)
        # Feature packages nest domain modules one level down
        # (packages/wires/recipients/).
        if self._domain_core_file(child) is None:
            for nested in child.iterdir():
                if not nested.is_dir() or nested.name.startswith("."):
                    continue
                if nested.name in {"node_modules", "dist", "build"}:
                    continue
                consider(nested)
    return domain_packages

def _find_tier_files(self, domain_path: Path, tier: str, pattern: str = "*.ts") -> List[Path]:
    """Files for one tier. Prefers the three-file layout; falls back to
    legacy ``<tier>/`` directories."""
    if tier in ("shared", "domain", "core"):
        core = self._domain_core_file(domain_path)
        return [core] if core is not None else []
    if tier == "server":
        server = self._server_file(domain_path)
        if server is not None:
            return [server]
    if tier == "client":
        client = self._client_file(domain_path)
        if client is not None:
            return [client]
    tier_dir = domain_path / tier
    if not tier_dir.exists():
        return []
    return list(tier_dir.glob(pattern))

def _read_file_content(self, file_path: Path) -> Optional[str]:
    try:
        return file_path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None

def _domain_core_file(self, domain_path: Path) -> Path | None:
    """``<domain>.ts`` — framework-free domain core (was shared/)."""
    candidates = [
        domain_path / f"{domain_path.name}.ts",
        domain_path / f"{domain_path.name.rstrip('s')}.ts",
    ]
    for path in candidates:
        if path.is_file():
            return path
    for path in sorted(domain_path.glob("*.ts")):
        name = path.name
        if name in {"index.ts", "app.ts", "serve.ts", "main.ts"}:
            continue
        if name.endswith("-server.ts"):
            continue
        if name.endswith(".test.ts") or name.endswith(".spec.ts"):
            continue
        if name.endswith("-client.ts"):
            continue
        return path
    return None

def _server_file(self, domain_path: Path) -> Path | None:
    """``<domain>-server.ts`` (not feature-package ``serve.ts`` / ``app.ts``)."""
    singular = domain_path.name.rstrip("s")
    for name in (
        f"{singular}-server.ts",
        f"{domain_path.name}-server.ts",
    ):
        path = domain_path / name
        if path.is_file():
            return path
    matches = sorted(domain_path.glob("*-server.ts"))
    return matches[0] if matches else None

def _is_domain_dir(self, path: Path) -> bool:
    if self._domain_core_file(path) is not None and (
        self._server_file(path) is not None or self._client_file(path) is not None
    ):
        return True
    return any((path / tier).is_dir() for tier in ("shared", "client", "server"))

def _find_test_folders(self, project_root: Path) -> List[Path]:
    """Lowest-level sub-epic test folders under tests/."""
    tests_dir = project_root / "tests"
    if not tests_dir.exists():
        return []

    sub_epic_folders = []
    for epic_dir in tests_dir.iterdir():
        if not epic_dir.is_dir() or epic_dir.name.startswith("."):
            continue
        for sub_epic_dir in epic_dir.rglob("*"):
            if not sub_epic_dir.is_dir():
                continue
            has_test_files = any(
                f.name.endswith((".test.ts", ".test.tsx", ".spec.ts"))
                for f in sub_epic_dir.iterdir()
                if f.is_file()
            )
            if has_test_files:
                sub_epic_folders.append(sub_epic_dir)
    return sub_epic_folders

def _read_grill_answers(self, root: Path) -> str | None:
    direct = self._grill_answers_path(root)
    if direct.is_file():
        return direct.read_text(encoding="utf-8", errors="replace")
    sessions = root / ".context" / "sessions"
    if sessions.is_dir():
        matches = sorted(sessions.rglob("grill-answers.md"))
        if matches:
            return matches[0].read_text(encoding="utf-8", errors="replace")
    return None

def update_self(self, source: "StoryNode") -> None:
    raise NotImplementedError(
        f"{type(self).__name__} must implement update_self"
    )

def child_collections(self, source: "StoryNode") -> List[ChildCollectionPair]:
    raise NotImplementedError(
        f"{type(self).__name__} must implement child_collections"
    )

def translate_from(self, source: "StoryNode") -> UpdateReport:
    if self.semantic_type() != source.semantic_type():
        raise TranslationError(
            f"Cannot translate from {source.semantic_type()} into "
            f"{self.semantic_type()}"
        )
    report = UpdateReport()
    report.capture_snapshot(self)
    self.update_self(source)
    for pair in self.child_collections(source):
        self._reconcile_collection(pair, report)
    return report

def _reconcile_collection(
    self, pair: ChildCollectionPair, report: UpdateReport
) -> None:
    self._consumed_ids: set = set()
    reconciled: List[StoryNode] = []

    for source_child in pair.source_children:
        match = self._find_match(source_child, pair.self_children)
        if match is not None:
            old_name = match.name
            self._consumed_ids.add(id(match))
            match.translate_from(source_child)
            reconciled.append(match)
            if old_name == source_child.name:
                report.add_exact_match(match.name, source_child.name)
            else:
                report.add_rename(old_name, source_child.name, confidence=1.0)
        else:
            new_child = pair.load(source_child)
            new_child.translate_from(source_child)
            reconciled.append(new_child)
            report.add_new(new_child, parent_name=self.name)

    for existing in pair.self_children:
        if id(existing) not in self._consumed_ids:
            report.add_removed(existing, parent_name=self.name)

    previous_kept_order = [c for c in pair.self_children if id(c) in self._consumed_ids]
    for i, node in enumerate(reconciled):
        if i >= len(previous_kept_order):
            break
        if previous_kept_order[i] is not node:
            report.add_reorder(previous_kept_order[i].name, node.name)
            break

    pair.self_children[:] = reconciled

def _find_match(
    self,
    source_child: "StoryNode",
    candidates: List["StoryNode"],
) -> Optional["StoryNode"]:
    for candidate in candidates:
        if id(candidate) in self._consumed_ids:
            continue
        if candidate.name == source_child.name:
            return candidate
    for candidate in candidates:
        if id(candidate) in self._consumed_ids:
            continue
        if candidate.sequential_order == source_child.sequential_order:
            return candidate
    return None

def children(self) -> List["StoryNode"]:
    # WHY: NodeSnapshot walks the tree without knowing shape; pull children from
    # the same pairs that translate_from reconciles, using self as its own source.
    result: List[StoryNode] = []
    try:
        for pair in self.child_collections(self):
            result.extend(pair.self_children)
    except NotImplementedError:
        pass
    return result

