def parse_detailed(self, text: str) -> ParsedPython:
    """Single parse entry - prefer ast (metrics); fall back to regex stubs."""
    self._text = text
    lines = text.split("\n")
    try:
        tree = ast.parse(text)
    except SyntaxError:
        model = self._parse_regex(text)
        return ParsedPython(model=model, content=text, lines=lines, tree=None)
    model = self._parse_ast(tree)
    return ParsedPython(model=model, content=text, lines=lines, tree=tree)

def _parse_ast(self, tree: ast.AST) -> "PythonCleanEngineeringModel":
    model = type(self)(name="", sequential_order=1)
    module = PythonModule(name="", sequential_order=1)
    class_order = 1
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        module.classes.append(self._class_from_ast(node, class_order))
        class_order += 1
    self._attach_top_level_ops(module, tree)
    if module.classes:
        model.modules.append(module)
    return model

def _populate_classes_regex(self, text: str, module: PythonModule) -> None:
    order = len(module.classes) + 1
    for m in _CLASS_PATTERN.finditer(text):
        oclass = PythonOoadClass(
            name=m.group(1),
            sequential_order=order,
            intent=m.group(2).strip(),
        )
        module.classes.append(oclass)
        order += 1
    if not module.classes:
        for m in _CLASS_NAME_ONLY.finditer(text):
            module.classes.append(PythonOoadClass(name=m.group(1), sequential_order=order))
            order += 1

def _operations_from_class(self, class_node: ast.ClassDef) -> list[Operation]:
    ops: list[Operation] = []
    for node in class_node.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            ops.append(self._operation_from_function(node))
    return ops

def _properties_from_class(self, class_node: ast.ClassDef) -> list[Property]:
    props: list[Property] = []
    for node in class_node.body:
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            hint = ast.unparse(node.annotation) if node.annotation else ""
            props.append(Property(name=node.target.id, type_hint=hint))
    return props

def _max_nesting(self, body: list, depth: int) -> int:
    deepest = depth
    for node in body:
        if isinstance(node, _NESTING_TYPES):
            child_depth = depth + 1
            for field_name in ("body", "orelse", "handlers", "finalbody"):
                children = getattr(node, field_name, None)
                if children:
                    deepest = max(deepest, self._max_nesting(children, child_depth))
        elif hasattr(node, "body") and isinstance(node.body, list):
            deepest = max(deepest, self._max_nesting(node.body, depth))
    return deepest

def _collect_callees(self, func: ast.AST) -> list[str]:
    names: list[str] = []
    for child in ast.walk(func):
        if isinstance(child, ast.Call):
            if isinstance(child.func, ast.Name):
                names.append(child.func.id)
            elif isinstance(child.func, ast.Attribute):
                names.append(child.func.attr)
    return names

def _collect_literals(self, func: ast.AST) -> list[str]:
    out: list[str] = []
    for child in ast.walk(func):
        if isinstance(child, ast.Constant) and isinstance(child.value, str):
            out.append(child.value)
    return out

def _has_validation(self, func: ast.AST) -> bool:
    for child in ast.walk(func):
        if isinstance(child, ast.Call) and isinstance(child.func, ast.Attribute):
            if any(
                child.func.attr.startswith(v)
                for v in ("validate", "check", "verify", "assert", "ensure")
            ):
                return True
        if isinstance(child, ast.If) and isinstance(child.test, ast.Compare):
            if any(isinstance(stmt, ast.Raise) for stmt in child.body):
                return True
    return False

def _collect_assigned_names(self, func: ast.AST) -> list[tuple[str, int]]:
    names: list[tuple[str, int]] = []
    for child in ast.walk(func):
        if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Store):
            names.append((child.id, child.lineno))
        elif isinstance(child, ast.arg) and child.arg not in {"self", "cls"}:
            names.append((child.arg, getattr(child, "lineno", 0) or 0))
    return names

def _collect_loop_targets(self, func: ast.AST) -> list[tuple[str, int]]:
    targets: list[tuple[str, int]] = []
    for child in ast.walk(func):
        if isinstance(child, (ast.For, ast.AsyncFor)):
            if isinstance(child.target, ast.Name):
                targets.append((child.target.id, child.target.lineno))
            elif isinstance(child.target, ast.Tuple):
                for elt in child.target.elts:
                    if isinstance(elt, ast.Name):
                        targets.append((elt.id, elt.lineno))
    return targets

def _constructed_types(self, func: ast.AST) -> list[tuple[str, int]]:
    out: list[tuple[str, int]] = []
    for child in ast.walk(func):
        if isinstance(child, ast.Call) and isinstance(child.func, ast.Name):
            if child.func.id and child.func.id[0].isupper():
                out.append((child.func.id, child.lineno))
    return out

def _public_attr_assigns(self, func: ast.AST) -> list[tuple[str, int]]:
    out: list[tuple[str, int]] = []
    for child in ast.walk(func):
        if not isinstance(child, ast.Assign):
            continue
        for target in child.targets:
            if (
                isinstance(target, ast.Attribute)
                and isinstance(target.value, ast.Name)
                and target.value.id == "self"
                and not target.attr.startswith("_")
            ):
                out.append((target.attr, child.lineno))
    return out

def _returns_private_attr(self, func: ast.AST) -> bool:
    for child in ast.walk(func):
        if not isinstance(child, ast.Return) or child.value is None:
            continue
        val = child.value
        if (
            isinstance(val, ast.Attribute)
            and isinstance(val.value, ast.Name)
            and val.value.id == "self"
            and val.attr.startswith("_")
        ):
            return True
    return False

def _render_properties(self, lines: List[str], oclass: OoadClass) -> None:
    iface = companion_interface_name(oclass.name, self._known_names)
    for prop in oclass.properties:
        hint = prop.type_hint or "object"
        if is_interface_name(oclass.name) or not iface:
            lines.append("    @property")
            lines.append("    @abstractmethod")
            lines.append(f"    def {prop.name}(self) -> {hint}: ...")
            lines.append("")
        else:
            lines.append(f"    {prop.name}: {hint}")
    if oclass.properties and not is_interface_name(oclass.name) and iface:
        lines.append("")

def _render_init(self, lines: List[str], oclass: OoadClass) -> None:
    if not oclass.properties:
        return
    param_sig = ", ".join(
        f"{p.name}: {p.type_hint}" if p.type_hint else p.name for p in oclass.properties
    )
    lines.append("    @abstractmethod")
    lines.append(f"    def __init__(self, {param_sig}) -> None: ...")
    lines.append("")

