def render(
    self,
    canonical: StoryMap,
    previous: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    """Return a `{file_path: content}` mapping for the whole canonical tree.

    If `previous` is provided, every hand-written region in a matching
    existing file is copied through byte-for-byte.
    """

    tree: Dict[str, str] = {}
    previous_tree = previous or {}
    for epic in canonical.epics:
        self._render_epic(
            epic=epic,
            epic_slug=self._folder_slug(epic, canonical.epics),
            tree=tree,
            previous_tree=previous_tree,
        )
    return tree

def parse(self, external: Dict[str, str]) -> StoryMap:
    # WHY: reconstruct by walking every leaf file path - the shape encodes
    # the Epic/SubEpic hierarchy uniquely.
    if not isinstance(external, dict):
        raise CodeStoryMapError("Tree must be a mapping of paths to file content")

    story_map = self._make_story_map()
    epics_by_slug: Dict[str, Epic] = {}

    for path in sorted(external):
        parts = path.split("/")
        if not parts or parts[0] != self._tests_root:
            continue
        if len(parts) < 3:
            continue
        _, epic_slug, *rest = parts

        epic = epics_by_slug.get(epic_slug)
        if epic is None:
            epic = self._make_epic(epic_slug, len(story_map.epics) + 1)
            epics_by_slug[epic_slug] = epic
            story_map.epics.append(epic)

        if len(rest) < 2:
            continue
        *sub_epic_slugs, _file_name = rest

        current_sub_epics = epic.sub_epics
        current_sub_epic: Optional[SubEpic] = None
        for slug in sub_epic_slugs:
            existing = next(
                (s for s in current_sub_epics if to_kebab(s.name) == slug),
                None,
            )
            if existing is None:
                existing = self._make_sub_epic(slug, len(current_sub_epics) + 1)
                current_sub_epics.append(existing)
            current_sub_epics = existing.sub_epics
            current_sub_epic = existing

        if current_sub_epic is not None:
            self._leaf_file_name = _file_name
            self._leaf_content = external[path]
            self._hydrate_leaf_sub_epic_from_content(current_sub_epic)

    if not story_map.epics and external:
        raise CodeStoryMapError(
            "Tree contains no recognisable Epic folders under the tests root"
        )
    return story_map

def strip_tests_root_prefix(self, parts: list[str]) -> list[str] | None:
    """Drop the workspace-relative deploy prefix from a rendered file path."""
    if not self._tests_root:
        return parts
    root_parts = [p for p in self._tests_root.split("/") if p]
    if not root_parts:
        return parts
    if len(parts) < len(root_parts) or parts[: len(root_parts)] != root_parts:
        return None
    return parts[len(root_parts) :]

def _folder_slug(
    self,
    node: Union[Epic, SubEpic],
    siblings: List[Union[Epic, SubEpic]],
) -> str:
    base = to_kebab(node.name)
    duplicate_count = sum(
        1 for sibling in siblings if to_kebab(sibling.name) == base
    )
    if duplicate_count <= 1:
        return base
    return f"{base}--{node.sequential_order}"

def _make_story_map(self) -> StoryMap:
    """Factory - overridden by concrete subclasses to return format-typed root."""
    return StoryMap()

def _make_epic(self, name: str, order: int) -> Epic:
    """Factory - overridden by concrete subclasses to return format-typed Epic."""
    return Epic(name, order)

def _make_sub_epic(self, name: str, order: int) -> SubEpic:
    """Factory - overridden by concrete subclasses to return format-typed SubEpic."""
    return SubEpic(name, order)

def leaf_files_of(self, tree: Dict[str, str]) -> List[str]:
    return sorted(
        p for p in tree if p.endswith(self.LEAF_EXTENSION) and self._is_leaf_path(p)
    )

def folders_of(self, tree: Dict[str, str]) -> List[str]:
    folders: set = set()
    for path in tree:
        parts = path.split("/")
        for i in range(1, len(parts)):
            folders.add("/".join(parts[:i]))
    return sorted(folders)

def _render_epic_helper(self, epic: Epic) -> Optional[str]:
    # WHY: TypeScript backend needs no per-Epic helper file; Python/Java do.
    return None

def _preserve_hand_written(self, previous: str, generated: str) -> str:
    # WHY: every HAND-WRITTEN region in `previous` survives regeneration
    # byte-for-byte. Blocks whose label matches a placeholder in `generated`
    # are inlined at that placeholder; every other hand-written block is
    # appended to the end of the generated file in original order.
    line_comment = self.LANGUAGE_LINE_COMMENT
    marker_start = f"{line_comment} HAND-WRITTEN START"
    marker_end = f"{line_comment} HAND-WRITTEN END"
    pattern = re.compile(
        re.escape(marker_start) + r"\s*(\S*)\s*\n(.*?)\n" + re.escape(marker_end),
        re.DOTALL,
    )

    found_blocks = []
    for match in pattern.finditer(previous):
        found_blocks.append((match.group(1), match.group(2)))
    if not found_blocks:
        return generated

    labels_in_generated = {m.group(1) for m in pattern.finditer(generated)}

    def substitute(match: re.Match) -> str:
        label = match.group(1)
        for stored_label, stored_body in found_blocks:
            if stored_label == label:
                return f"{marker_start} {label}\n{stored_body}\n{marker_end}"
        return match.group(0)

    result = pattern.sub(substitute, generated)

    appended = [
        f"{marker_start} {label}\n{body}\n{marker_end}"
        for label, body in found_blocks
        if label not in labels_in_generated
    ]
    if appended:
        if not result.endswith("\n"):
            result += "\n"
        result += "\n" + "\n".join(appended) + "\n"
    return result

def load_property(self, source: SourceProperty) -> Property:
    return Property(
        source.name,
        source.sequential_order,
        type_hint=source.type_hint,
        description=source.description,
    )

def read(self, location: SourceLocation) -> SourceLocation:
    start, end, text = self._read_span(location)
    if not text:
        return SourceLocation(
            file=location.file,
            line=location.line,
            end_line=location.end_line or location.line,
            text=location.text,
        )
    return SourceLocation(file=location.file, line=start, end_line=end, text=text)

def bind(self, node: Node, row: dict) -> None:
    file = str(row.get("file") or "").replace("\\", "/")
    start = int(row.get("line") or 0)
    end = int(row.get("end_line") or start)
    if not file:
        return
    text = str(row.get("text") or "")
    location = SourceLocation(file=file, line=start, end_line=end or start, text=text)
    if self._root is not None and start > 0:
        location = self.read(location)
    node.source = location

def _python_block_end(self, lines: list[str], start_index: int) -> int:
    header = lines[start_index]
    matched = re.match(r"^(\s*)(?:async\s+)?(?:class|def)\b", header)
    if not matched:
        return start_index
    indent = len(matched.group(1))
    end = self._signature_end(lines, start_index)
    for index in range(end + 1, len(lines)):
        line = lines[index]
        if line.strip() == "":
            end = index
            continue
        if len(line) - len(line.lstrip(" ")) <= indent:
            break
        end = index
    return end

def _brace_block_end(self, lines: list[str], start_index: int) -> int:
    depth = 0
    seen = False
    for index in range(start_index, len(lines)):
        for ch in lines[index]:
            if ch == "{":
                depth += 1
                seen = True
            elif ch == "}":
                depth -= 1
                if seen and depth == 0:
                    return index
    return start_index

def _signature_end(self, lines: list[str], start_index: int) -> int:
    depth = 0
    for index in range(start_index, len(lines)):
        line = lines[index]
        depth += line.count("(") - line.count(")")
        if depth <= 0 and ":" in line:
            return index
    return start_index

def sync_tree_from_legacy(self) -> None:
    self.property_nodes = [
        GraphProperty.from_field(field, index)
        for index, field in enumerate(self.properties, start=1)
    ]
    self.operation_nodes = [
        GraphOperation.from_field(field, index)
        for index, field in enumerate(self.operations, start=1)
    ]

def load_property(self, source: Property) -> "GraphProperty":
    return GraphProperty(
        source.name,
        source.sequential_order,
        type_hint=source.type_hint,
        description=source.description,
    )

def __init__(self, graph: PracticeGraph) -> None:
    self.graph = graph
    self.root: Path = graph.root
    self.results_path: Path | None = None
    self.export: CodeQLPracticeGraphExport
    self.modules: Dict[str, GraphModule] = {}
    self.classes: Dict[str, OoadClass] = {}
    self._module_order = 1
    self._examples_by_name: Dict[str, List[GraphExample]] = {}

def _ensure_properties(self) -> None:
    for prop in self.export.properties:
        cls = self.classes.get(prop.class_name.lower())
        if cls is None:
            continue
        if any(p.name == prop.name for p in cls.property_nodes):
            continue
        self._add_property(cls, prop)

def _ensure_operations(self) -> None:
    for op in self.export.operations:
        cls = self.classes.get(op.class_name.lower())
        if cls is None:
            continue
        if any(o.name == op.name for o in cls.operation_nodes):
            continue
        self._add_operation(cls, op)

def _ensure_ce_nodes(self) -> None:
    self.modules = {}
    for mod in self.graph.nodes_of_type(GraphModule):
        self.modules[mod.name.lower()] = mod
    self.classes = {}
    for cls in self.graph.nodes.values():
        if isinstance(cls, OoadClass):
            self.classes[cls.name.lower()] = cls
    self._module_order = 1
    self._ensure_modules_and_classes()
    self._ensure_properties()
    self._ensure_operations()

def _wire_codeql_calls(self) -> None:
    for call in self.export.calls:
        caller = self.graph.find_operation(call.caller_class, call.caller_operation)
        callee = self.graph.find_operation(call.callee_class, call.callee_operation)
        if caller is None or callee is None:
            continue
        caller.relate(Kind.INVOKES, callee)

def _wire_story_calls(self) -> None:
    for story_call in self.export.story_calls:
        step = self._find_step(story_call)
        operation = self.graph.find_operation(
            story_call.callee_class, story_call.callee_operation
        )
        if step is None or operation is None:
            continue
        step.relate(Kind.INVOKES, operation)

def _wire_story_observations(self) -> None:
    for obs in self.export.story_observations:
        step = self._find_step(obs)
        if step is None:
            continue
        cls = self.graph.find_class(obs.target_class)
        if cls is None:
            continue
        target = self._observation_target(cls, obs)
        if target is None:
            continue
        step.relate(Kind.OBSERVES, target)

def _wire_example_demonstrates(self) -> None:
    self._examples_by_name = {}
    for example in self.graph.nodes_of_type(GraphExample):
        self._examples_by_name.setdefault(example.name.lower(), []).append(example)
    for entry in self.export.example_exports:
        if not entry.demonstrates:
            continue
        self._relate_demonstrates(entry)

def _ensure_modules_and_classes(self) -> None:
    for entry in self.export.classes:
        mod = self._module_for(entry)
        self._class_for(entry, mod)

def _find_step(self, story_call) -> Optional[GraphStep]:
    step_text = getattr(story_call, "step_text", "")
    normalized = story_call.story_file.replace("\\", "/").lstrip("./")
    best: Tuple[int, Optional[GraphStep]] = (1_000_000, None)
    for step in self.graph.nodes_of_type(GraphStep):
        if step_text and step_text.lower() in step.text.lower():
            return step
        src = getattr(step, "source", None)
        if src is None:
            continue
        src_file = str(src.file).replace("\\", "/").lstrip("./")
        if src_file != normalized and not src_file.endswith(normalized):
            continue
        if story_call.line <= 0:
            return step
        delta = abs(int(src.line) - story_call.line)
        if delta < best[0]:
            best = (delta, step)
    if best[1] is not None and best[0] <= 5:
        return best[1]
    return None

def _observation_target(self, cls, obs):
    for owned in self.graph.outgoing_nodes(cls, Kind.OWNS):
        if (
            obs.member_kind == "operation"
            and isinstance(owned, GraphOperation)
            and owned.name == obs.target_member
        ):
            return owned
        if (
            obs.member_kind == "property"
            and isinstance(owned, GraphProperty)
            and owned.name == obs.target_member
        ):
            return owned
    return None

def _relate_demonstrates(self, entry) -> None:
    for example in self._match_examples(entry):
        self._demonstrate_classes(example, entry.demonstrates)

def _match_examples(self, entry) -> List[GraphExample]:
    export_lower = entry.export_name.lower()
    if export_lower in self._examples_by_name:
        return self._examples_by_name[export_lower]
    stem = Path(entry.file).stem.replace(".examples", "").replace("-", " ")
    if stem.lower() in self._examples_by_name:
        return self._examples_by_name[stem.lower()]
    out: List[GraphExample] = []
    for examples in self._examples_by_name.values():
        for ex in examples:
            if export_lower in ex.name.lower() or ex.name.lower() in export_lower:
                out.append(ex)
    return out

def _demonstrate_classes(self, example: GraphExample, cls_names: List[str]) -> None:
    for class_name in cls_names:
        cls = self.graph.find_class(class_name)
        if cls is None:
            continue
        example.relate(Kind.DEMONSTRATES, cls)

def walk_hierarchy(
    root: Node,
    *,
    kinds: Iterable[str] = HIERARCHY_KINDS,
) -> Iterator[Tuple[int, Node]]:
    """Yield ``(depth, node)`` depth-first over owned and scoped descendants."""
    kind_set = frozenset(kinds)
    seen: Set[str] = set()
    stack: List[Tuple[int, Node, bool]] = [(0, root, True)]

    while stack:
        depth, node, expand = stack.pop()
        if node.node_id in seen:
            if not expand:
                yield depth, node
            continue
        seen.add(node.node_id)
        yield depth, node
        children = [
            (kind, child)
            for kind, child in node.outgoing()
            if kind in kind_set
        ]
        children.sort(key=lambda pair: _hierarchy_rank(pair[1]))
        for kind, child in reversed(children):
            if child.node_id in seen and kind != Kind.DEMONSTRATED_THROUGH:
                continue
            stack.append((depth + 1, child, kind != Kind.DEMONSTRATED_THROUGH))

def graph_name_matches(module_name: str, graphs: list[str] | None) -> bool:
    if not graphs:
        return True
    name = (module_name or "").replace("\\", "/").replace(".", "/")
    for wanted in graphs:
        token = (wanted or "").replace("\\", "/").replace(".", "/").strip().strip("/")
        if token and (name == token or name.endswith("/" + token) or token in name):
            return True
    return False

def dot_graph_from_node(
    root: Node,
    *,
    kinds: Iterable[str] = HIERARCHY_KINDS,
    graph_name: str = "practice_graph",
) -> str:
    """Return a DOT digraph for *root* and every descendant via hierarchy edges."""
    kind_set = frozenset(kinds)
    nodes, edges = _collect_hierarchy(root, kind_set)
    return _render_dot(nodes, edges, graph_name=graph_name)

def dot_graph_from_roots(
    roots: Iterable[Node],
    *,
    kinds: Iterable[str] = HIERARCHY_KINDS,
    graph_name: str = "practice_graph",
) -> str:
    """Merge hierarchy subgraphs for multiple roots into one DOT digraph."""
    kind_set = frozenset(kinds)
    all_nodes: List[Node] = []
    all_edges: List[Tuple[Node, str, Node]] = []
    seen_nodes: Set[str] = set()
    seen_edges: Set[Tuple[str, str, str]] = set()

    for root in roots:
        nodes, edges = _collect_hierarchy(root, kind_set)
        for node in nodes:
            if node.node_id in seen_nodes:
                continue
            seen_nodes.add(node.node_id)
            all_nodes.append(node)
        for from_node, kind, to_node in edges:
            key = (from_node.node_id, kind, to_node.node_id)
            if key in seen_edges:
                continue
            seen_edges.add(key)
            all_edges.append((from_node, kind, to_node))

    return _render_dot(all_nodes, all_edges, graph_name=graph_name)

def contains(self, pos: int) -> bool:
    if self.body_start < 0 or self.body_end < 0:
        return False
    return self.body_start <= pos < self.body_end

def _scenarios(self) -> List[CodeQLScenario]:
    scenarios: List[CodeQLScenario] = []
    for call in self._scenario_calls:
        scenarios.append(
            CodeQLScenario(call.text, self._story_for(call.start), self._file, line=call.line)
        )
    return scenarios

def _iter_files(self) -> Iterable[Path]:
    for path in self.root.rglob("*"):
        if not path.is_file():
            continue
        if any(part in _SKIP_DIRS for part in path.parts):
            continue
        yield path

def _attach_bodies(self, calls: List[_Call]) -> None:
    for call in calls:
        if call.name not in {"story", "scenario", "background"}:
            continue
        span = self._callback_body_span(call.start)
        if span is None:
            continue
        call.body_start, call.body_end = span

def _display(self, slug: str) -> str:
    if not slug:
        return ""
    if " " in slug:
        return slug
    return slug.replace("-", " ").replace("_", " ").title()

def _skip_comment(self, i: int) -> int:
    source = self._source
    if source.startswith("//", i):
        nl = source.find("\n", i)
        return len(source) if nl < 0 else nl + 1
    if source.startswith("/*", i):
        end = source.find("*/", i + 2)
        return len(source) if end < 0 else end + 2
    return i

def _skip_string(self, start: int) -> int:
    _text, end = self._read_string(start)
    return end

def _scan_chain_call(self, i: int) -> Optional[int]:
    source = self._source
    n = len(source)
    if source[i] != "." or i + 1 >= n:
        return None
    if not self._is_ident_start(source[i + 1]):
        return None
    name, j = self._read_ident(i + 1)
    if name not in _CHAIN_NAMES:
        return None
    j = self._skip_ws(j)
    if j >= n or source[j] != "(":
        return None
    text, _end = self._first_string_arg(j)
    if text is not None:
        self._calls.append(_Call(name, text, i, self._line(i)))
    return j + 1

def _scan_named_call(self, i: int) -> Optional[int]:
    source = self._source
    n = len(source)
    if not self._is_ident_start(source[i]):
        return None
    if i != 0 and self._is_ident_char(source[i - 1]):
        return None
    name, j = self._read_ident(i)
    if name not in _CALL_NAMES:
        return None
    j = self._skip_ws(j)
    if j >= n or source[j] != "(":
        return None
    text, _end = self._first_string_arg(j)
    if name == "background":
        self._calls.append(_Call(name, text or "background", i, self._line(i)))
        return j + 1
    if text is not None:
        self._calls.append(_Call(name, text, i, self._line(i)))
    return j + 1

def _skip_ws(self, i: int) -> int:
    source = self._source
    n = len(source)
    while i < n and source[i] in " \t\r\n":
        i += 1
    return i

def _callback_body_span(self, call_pos: int) -> Optional[Tuple[int, int]]:
    paren_at = self._source.find("(", call_pos)
    if paren_at < 0:
        return None
    return self._skip_in_parens(paren_at + 1)

def _body_after_arrow(self, saw_arrow: bool, i: int) -> Optional[Tuple[int, int]]:
    if not saw_arrow:
        return None
    if self._source[i] != "{":
        return None
    end = self._match_brace(i)
    if end < 0:
        return None
    return (i, end)

def stop(self) -> None:
    process = self._process
    self._process = None
    self._registered.clear()
    if process is None:
        return
    if process.stdin is not None:
        try:
            process.stdin.close()
        except OSError:
            pass
    if process.poll() is None:
        process.terminate()
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self._kill_tree(process.pid)
            process.wait(timeout=5)
    elif process.pid:
        self._kill_tree(process.pid)

def pid(self) -> int | None:
    if self._process is None:
        return None
    return self._process.pid

def run_queries(self, queries, database: Path, on_line) -> dict[str, Path]:
    """Evaluate one batch on the warm server. Returns resolved query path to bqrs."""
    with self._lock:
        if not self.alive:
            raise QueryServerDown("codeql query server is not running")
        self._on_line = on_line
        self._last_progress = ""
        db = str(Path(database).resolve())
        self._register(db)
        folder = Path(database) / "results" / "query-server"
        folder.mkdir(parents=True, exist_ok=True)
        inputs = []
        outputs: dict[str, Path] = {}
        for query in queries:
            resolved = str(Path(query).resolve())
            bqrs = folder / f"{Path(query).stem}.bqrs"
            dil = bqrs.with_suffix(".dil")
            inputs.append(
                {
                    "queryPath": resolved,
                    "outputPath": str(bqrs),
                    "dilPath": str(dil),
                }
            )
            outputs[resolved] = bqrs
        result = self._request(
            "evaluation/runQueries",
            {
                "inputOutputPaths": inputs,
                "db": db,
                "additionalPacks": [],
                "externalInputs": {},
                "singletonExternalInputs": {},
            },
        )
        failures: list[str] = []
        produced: dict[str, Path] = {}
        by_path = {
            str(Path(path).resolve()): value
            for path, value in (result or {}).items()
            if isinstance(value, dict)
        }
        for resolved, bqrs in outputs.items():
            entry = by_path.get(resolved) or {}
            result_type = entry.get("resultType", 1)
            if result_type != 0 or not bqrs.is_file():
                message = entry.get("message") or f"resultType={result_type}"
                failures.append(f"{Path(resolved).stem}: {message}")
            else:
                produced[resolved] = bqrs
            dil = bqrs.with_suffix(".dil")
            if dil.is_file():
                dil.unlink()
        if failures and not produced:
            raise CodeQLRunError("codeql query server failed: " + "; ".join(failures))
        if failures and on_line is not None:
            on_line("query-server partial: " + "; ".join(failures))
        return produced

def from_repo(cls, repo: Path | str) -> CodeQLQueryServer:
    root = Path(repo)
    return cls(root, CodeQL(root))

def _drain_stderr(self) -> None:
    process = self._process
    if process is None or process.stderr is None:
        return
    for line in process.stderr:
        text = line.decode("utf-8", errors="replace").rstrip("\r\n")
        if text and self._on_line is not None:
            self._on_line(text)

def _kill_tree(self, pid: int) -> None:
    if sys.platform == "win32":
        subprocess.run(
            ["taskkill", "/F", "/T", "/PID", str(pid)],
            check=False,
            capture_output=True,
        )
        return
    try:
        os.kill(pid, 9)
    except OSError:
        logger = __import__("logging").getLogger(__name__)
        logger.debug("process %s already gone", pid)
        return

def _register(self, database: str) -> None:
    if database in self._registered:
        return
    self._request("evaluation/registerDatabases", {"databases": [database]})
    self._registered.add(database)

def _note_progress(self, params: dict) -> None:
    message = str(params.get("message") or "").strip()
    if not message or message == self._last_progress or message.startswith("("):
        return
    self._last_progress = message
    phase = message.split(" ", 1)[0]
    if ".ql" not in message and phase not in _PHASES:
        return
    if self._on_line is not None:
        self._on_line(message)

def _connect(self, path: Path) -> QueryServerClient | None:
    if not path.is_file():
        return None
    try:
        state = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return None
    host = state.get("host") or _HOST
    port = state.get("port")
    if not port:
        return None
    try:
        result = _rpc(host, int(port), {"method": "ping"})
    except OSError:
        return None
    if not result.get("ok"):
        return None
    return QueryServerClient(host, int(port), state.get("pid"))

def _row(self, decoder, item: list) -> dict:
    first = item[0]
    name = decoder.entity_name(first)
    message = item[1] if len(item) > 1 else ""
    if isinstance(message, dict):
        message = message.get("label", "")
    contributor = item[2] if len(item) > 2 else None
    if isinstance(contributor, dict):
        contributor = contributor.get("label")
    file, line = decoder.entity_location(first)
    row = {"name": name, "message": str(message)}
    kind = decoder.entity_kind(first)
    if kind:
        row["kind"] = kind
    if file:
        row["file"] = file
    if line:
        row["line"] = line
    if contributor:
        row["contributor"] = str(contributor)
    return row

def _rows(self, payload: dict) -> List[dict]:
    from .codeql import Rows as CodeQLRows

    decoder = CodeQLRows()
    tuples = payload.get("#select", {}).get("tuples", [])
    rows: List[dict] = []
    for item in tuples:
        if not item:
            continue
        rows.append(self._row(decoder, item))
    return rows

def _database(self, root: Path) -> Optional[Path]:
    codeql = root / ".codeql"
    if not codeql.is_dir():
        return None
    for child in codeql.iterdir():
        if child.is_dir() and child.name.endswith("-db"):
            return child
    return None

def run(self) -> None:
    threading.Thread(
        target=self._start_codeql_server,
        name="codeql-query-server",
        daemon=True,
    ).start()
    try:
        while True:
            try:
                anyio.run(self.run_stdio)
                return
            except (KeyboardInterrupt, SystemExit):
                raise
            except Exception:
                logger.exception("MCP stdio host crashed; restarting")
    finally:
        self._stop_codeql_server()

def notify_exceptions(self) -> None:
    text = self.notice()
    if text:
        print(text, file=sys.stderr)

def input_schema_for_callable(self, callable: Callable[..., object]) -> dict[str, Any]:
    hints = self._callable_hints(callable)
    properties: dict[str, Any] = {}
    required: list[str] = []
    for name, param in inspect.signature(callable).parameters.items():
        if not self._is_schema_parameter(name, param):
            continue
        properties[name] = self._parameter_schema(hints, name, param)
        if param.default is inspect.Parameter.empty:
            required.append(name)
    result: dict[str, Any] = {"type": "object", "properties": properties}
    if required:
        result["required"] = required
    return result

def refs_from_manifest(self, manifest: Path | str) -> tuple[str, ...]:
    args = [str(item) for item in self.server_entry_from_manifest(manifest).get("args") or []]
    raw = self._arg_after(args, "--toolsets")
    return tuple(ref.strip() for ref in raw.split(",") if ref.strip())

def server_entry_from_manifest(
    self, servers: Mapping[str, Any] | Path | str
) -> dict[str, Any]:
    raw = self._mcp_servers(servers)
    if not isinstance(raw, Mapping):
        return {}
    preferred = raw.get("cdd")
    if isinstance(preferred, dict) and preferred:
        return preferred
    named = self._named_cdd_server(raw)
    if named:
        return named
    hosted = self._hosted_cdd_server(raw)
    if hosted:
        return hosted
    first = next(iter(raw.values()), {})
    return first if isinstance(first, dict) else {}

def _register_handlers(self) -> None:
    @self._server.list_tools()
    async def handle_list_tools() -> list[types.Tool]:
        tools = [
            types.Tool(
                name=BUILTIN_PING_TOOL,
                description="Health check for the CDD MCP host process.",
                inputSchema={"type": "object", "properties": {}},
            )
        ]
        tools.extend(
            listed
            for listed in (
                self._listed_tool(tool) for tool in self._runtime._tools.values()
            )
            if listed is not None
        )
        tools.extend(
            listed
            for listed in (
                self._listed_prompt_tool(prompt)
                for prompt in self._runtime._prompts.values()
            )
            if listed is not None
        )
        return tools

    @self._server.call_tool()
    async def handle_call_tool(
        name: str, arguments: dict[str, object] | None
    ) -> Sequence[types.TextContent | types.ImageContent | types.EmbeddedResource]:
        try:
            name = self._runtime.resolve_call_name(name)
            if name == BUILTIN_PING_TOOL:
                return self._content_blocks("pong")
            if name in self._runtime._prompts:
                return self._content_blocks(
                    self._runtime.invoke_prompt(name, dict(arguments or {}))
                )
            return self._content_blocks(
                self._runtime.invoke_tool(name, dict(arguments or {}))
            )
        except Exception as error:
            logger.exception("MCP tool %s failed", name)
            return self._content_blocks(f"{type(error).__name__}: {error}")

    @self._server.list_prompts()
    async def handle_list_prompts() -> list[types.Prompt]:
        return []

    @self._server.get_prompt()
    async def handle_get_prompt(
        name: str, arguments: dict[str, str] | None
    ) -> types.GetPromptResult:
        prompt = self._runtime._prompts.get(name)
        if prompt is None:
            raise ValueError(f"unknown prompt: {name}")
        return types.GetPromptResult(
            description=prompt.prompt_text or None,
            messages=[
                types.PromptMessage(
                    role="user",
                    content=types.TextContent(
                        type="text",
                        text=prompt.prompt_text or "",
                    ),
                )
            ],
        )

def _callable_hints(self, callable: Callable[..., object]) -> dict[str, Any]:
    function = getattr(callable, "__func__", callable)
    try:
        return get_type_hints(function)
    except (NameError, TypeError, AttributeError):
        return {}

def _is_schema_parameter(self, name: str, param: inspect.Parameter) -> bool:
    if name == "self":
        return False
    return param.kind in (
        inspect.Parameter.POSITIONAL_OR_KEYWORD,
        inspect.Parameter.KEYWORD_ONLY,
    )

def _object_schema(self, annotation: object) -> dict[str, Any]:
    args = get_args(annotation)
    schema: dict[str, Any] = {"type": "object"}
