def _wait_for_root(self, page) -> None:
    try:
        page.wait_for_function(
            "() => { const r = document.querySelector('#root'); return !!(r && r.childElementCount > 0); }",
            timeout=10_000,
        )
    except Exception:
        _log.exception("Root content did not appear at %s", self._page_url)
        page.wait_for_timeout(1500)

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []

    for domain_path in self._find_domain_packages(root):
        violations += self._check_domain(domain_path)

    return violations

def _check_domain(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []

    shared_methods = self._extract_shared_methods(domain_path)
    if not shared_methods:
        return violations

    server_methods = self._extract_server_methods(domain_path)
    http_functions = self._extract_http_functions(domain_path)

    for method in shared_methods:
        base = method.lower()
        if base in _CRUD_GENERICS:
            continue

        if server_methods and method not in server_methods:
            for srv_method in server_methods:
                if srv_method.lower() in _CRUD_GENERICS and base not in _CRUD_GENERICS:
                    violations.append(
                        self.v(
                            f"Domain method '{method}' in domain core has no matching "
                            f"server method. Server uses CRUD-generic "
                            f"'{srv_method}' instead. Rename to '{method}'.",
                            str(domain_path / "server.ts"),
                            severity="warning",
                        )
                    )
                    break

        if http_functions and method not in http_functions:
            for fn in http_functions:
                if fn.startswith("fetch") and method in fn.lower():
                    violations.append(
                        self.v(
                            f"Domain method '{method}' in domain core has no matching "
                            f"HTTP client function. Client uses 'fetch'-prefixed "
                            f"'{fn}' instead. Rename to '{method}'.",
                            str(self._client_file(domain_path) or domain_path / "client.tsx"),
                            severity="warning",
                        )
                    )
                    break

    return violations

def _extract_shared_methods(self, domain_path: Path) -> Set[str]:
    methods: Set[str] = set()
    core = self._domain_core_file(domain_path)
    if core is None:
        return methods
    content = self._read_file_content(core)
    if content is None:
        return methods
    for m in _METHOD_RE.finditer(content):
        name = m.group(1)
        if name[0].islower() and not name.startswith("constructor"):
            methods.add(name)
    return methods

def _extract_server_methods(self, domain_path: Path) -> Set[str]:
    methods: Set[str] = set()
    server = self._server_file(domain_path)
    if server is None:
        return methods
    content = self._read_file_content(server)
    if content is None:
        return methods
    for m in _METHOD_RE.finditer(content):
        name = m.group(1)
        if name[0].islower() and not name.startswith("constructor"):
            methods.add(name)
    return methods

def _extract_http_functions(self, domain_path: Path) -> Set[str]:
    fns: Set[str] = set()
    client = self._client_file(domain_path)
    if client is None:
        return fns
    content = self._read_file_content(client)
    if content is None:
        return fns
    for m in _EXPORT_FUNCTION_RE.finditer(content):
        fns.add(m.group(1))
    return fns

def is_undeclared(self, pkg: str) -> bool:
    if pkg in _NODE_BUILTINS:
        return False
    scoped = pkg.startswith("@") and pkg.count("/") == 1
    bare = not pkg.startswith("@")
    return (scoped or bare) and pkg not in self.names

def _load_all_deps(self, pkg_json_path: Path) -> Set[str]:
    """Load all dep names from a package.json (deps + devDeps + peerDeps)."""
    if not pkg_json_path.exists():
        return set()
    try:
        data = json.loads(pkg_json_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return set()
    deps: Set[str] = set()
    for key in ("dependencies", "devDependencies", "peerDependencies"):
        deps.update(data.get(key, {}).keys())
    return deps

def _check_root_dev_deps(self, project_root: Path, root_deps: Set[str]) -> List[Violation]:
    violations: List[Violation] = []
    pkg_json = project_root / "package.json"

    if not (project_root / "tests").exists():
        return violations

    for pkg, desc in _REQUIRED_DEV_DEPS.items():
        if pkg not in root_deps:
            violations.append(
                self.v(f"Root package.json is missing '{pkg}' in devDependencies. {desc}.", str(pkg_json))
            )

    return violations

def _check_tier_imports(self, tier_dir: Path, all_deps: Set[str]) -> List[Violation]:
    violations: List[Violation] = []
    for ts_file in self.source_files(tier_dir):
        violations.extend(self._undeclared_imports_in(ts_file, _DeclaredDeps(all_deps)))
    return violations

def _check_tier_restrictions(self, scan: _TierScan) -> List[Violation]:
    violations: List[Violation] = []
    for pkg, allowed_tier in _TIER_RESTRICTIONS.items():
        if scan.tier == allowed_tier:
            continue
        violations.extend(
            self._forbidden_framework_imports(scan, _FrameworkPlacement(pkg, allowed_tier))
        )
    return violations

def _undeclared_imports_in(self, ts_file: Path, deps: _DeclaredDeps) -> List[Violation]:
    parsed_root = self.parse_file(ts_file)
    if parsed_root is None:
        return []
    violations: List[Violation] = []
    for imp in self.imports:
        hit = self._undeclared_package_hit(
            _ImportSite(ts_file, imp.source, imp.start_line), deps
        )
        if hit is not None:
            violations.append(hit)
    return violations

def _undeclared_package_hit(self, site: _ImportSite, deps: _DeclaredDeps):
    pkg = self._extract_package_name(site.source)
    if pkg is None or not deps.is_undeclared(pkg):
        return None
    imported = site.source if pkg.startswith("@") else pkg
    return self.v(
        f"'{site.path.name}' imports '{imported}' but "
        f"'{pkg}' is not declared in any package.json. "
        "Add it to the appropriate package.json "
        "dependencies.",
        str(site.path),
        site.start_line,
    )

def _extract_package_name(self, source: str) -> Optional[str]:
    """Extract the npm package name from an import source string."""
    if source.startswith(".") or source.startswith("/"):
        return None  # relative import
    if source.startswith("node:"):
        return None  # explicit node built-in
    if "/" in source and not source.startswith("@"):
        return source.split("/")[0]
    if source.startswith("@") and "/" in source:
        parts = source.split("/")
        return f"{parts[0]}/{parts[1]}"
    return source

def _forbidden_framework_imports(
    self, scan: _TierScan, placement: _FrameworkPlacement
) -> List[Violation]:
    violations: List[Violation] = []
    for ts_file in self.source_files(scan.directory):
        parsed_root = self.parse_file(ts_file)
        if parsed_root is None or not self.has_import_from(placement.package):
            continue
        violations.append(
            self.v(
                f"'{scan.domain_name}/{scan.tier}/{ts_file.name}' imports "
                f"'{placement.package}' which must only be used in "
                f"'{placement.allowed_tier}/'. "
                "This is a layer purity violation.",
                str(ts_file),
            )
        )
    return violations

def annotate(self, fn: Callable[..., Any]) -> Callable[..., Any]:
    setattr(fn, self.flag, True)
    name = getattr(self, "name", None)
    if name is not None:
        setattr(fn, f"{self.flag}_name", name)
    return fn

def style(self) -> str:
    if self.nested:
        return MODULE_CHILD_STYLE
    return MODULE_STYLE

def _terms_from_html(self, text: str) -> List[str]:
    terms: List[str] = []
    for bullet in re.findall('[\u2022\\-]\\s*([^<]+)', text):
        term = bullet.strip()
        if term and (not term.startswith('{')):
            terms.append(term)
        elif term.startswith('{') and term.endswith('}'):
            continue
        elif term:
            terms.append(term)
    if terms:
        return terms
    for li in re.findall('<li[^>]*>(?:<[^>]+>)*([^<]+)', text, re.IGNORECASE):
        term = li.strip()
        if term and 'stack' not in term.lower():
            terms.append(term)
    return terms

def mermaid_lines(self) -> List[str]:
    class_id = self.mermaid_id()
    lines = [f'    %% local: {class_id}', f'    class {class_id} {{']
    for stereotype in self.tactical_stereotypes():
        lines.append(f'        <<{stereotype}>>')
    for prop in self.properties:
        lines.append(f"        +{prop.type_hint or 'object'} {prop.name}")
    for operation in self.operations:
        parameters = ', '.join(operation.parameters)
        lines.append(
            f'        +{operation.name}({parameters}) {operation.return_type or "void"}'
        )
    lines.append('    }')
    return lines

def mermaid_lines(self) -> List[str]:
    class_id = self.mermaid_id()
    lines = [f'    %% imported: {class_id}', f'    class {class_id} {{']
    lines.append(f'        <<from {self.from_module}>>')
    for stereotype in self.tactical_stereotypes():
        lines.append(f'        <<{stereotype}>>')
    for prop in self.key_properties():
        lines.append(f"        +{prop.type_hint or 'object'} {prop.name}")
    lines.append('    }')
    return lines

def max_sub_epic_depth(self) -> int:
    deepest = 0
    for epic in self._story_map.epics:
        for sub in epic.sub_epics:
            deepest = max(deepest, self._depth_from(sub, current=0))
    return deepest

def _depth_from(self, sub_epic: SubEpic, current: int) -> int:
    if not sub_epic.sub_epics:
        return current
    return max(self._depth_from(s, current + 1) for s in sub_epic.sub_epics)

def epic_width(self, epic: Epic) -> int:
    if not epic.sub_epics:
        return BASE_WIDTH
    return sum(self.sub_epic_width(s) for s in epic.sub_epics)

def epic_x(self, epic: Epic) -> int:
    offset = 0
    for candidate in self._story_map.epics:
        if candidate is epic:
            return offset
        offset += self.epic_width(candidate)
    raise KeyError(f"Epic {epic.name!r} not part of this diagram")

def sub_epic_x(self, sub_epic: SubEpic) -> int:
    for epic in self._story_map.epics:
        self._sub_epic_search_base_x = self.epic_x(epic)
        x = self._find_sub_epic_x(sub_epic, epic.sub_epics)
        if x is not None:
            return x
    raise KeyError(f"SubEpic {sub_epic.name!r} not part of this diagram")

def _find_sub_epic_x(self, target: SubEpic, siblings: List[SubEpic]) -> Optional[int]:
    offset = self._sub_epic_search_base_x
    for sibling in siblings:
        if sibling is target:
            return offset
        saved = self._sub_epic_search_base_x
        self._sub_epic_search_base_x = offset
        inner = self._find_sub_epic_x(target, sibling.sub_epics)
        if inner is not None:
            return inner
        self._sub_epic_search_base_x = saved
        offset += self.sub_epic_width(sibling)
    return None

def sub_epic_depth(self, sub_epic: SubEpic) -> int:
    for epic in self._story_map.epics:
        self._sub_epic_search_depth = 0
        depth = self._depth_of(sub_epic, epic.sub_epics)
        if depth is not None:
            return depth
    raise KeyError(f"SubEpic {sub_epic.name!r} not part of this diagram")

def _depth_of(self, target: SubEpic, siblings: List[SubEpic]) -> Optional[int]:
    depth = self._sub_epic_search_depth
    for sibling in siblings:
        if sibling is target:
            return depth
        self._sub_epic_search_depth = depth + 1
        inner = self._depth_of(target, sibling.sub_epics)
        if inner is not None:
            return inner
        self._sub_epic_search_depth = depth
    return None

def _parent_sub_epic_of_story(self, story: Story) -> SubEpic:
    for epic in self._story_map.epics:
        for sub in self._all_sub_epics_recursive(epic.sub_epics):
            if story in sub.stories:
                return sub
    raise KeyError(f"Story {story.name!r} not part of this diagram")

def place_child_under_parent(self, child, parent) -> None:
    # WHY: single guard on all invalid placements - every rejection leaf
    # collapses to a check on the type pair (parent, child).
    if isinstance(parent, Story):
        raise PlacementError("Stories cannot have child nodes")
    if isinstance(parent, SubEpic) and isinstance(child, Epic):
        raise PlacementError("An Epic cannot live under a SubEpic")
    if isinstance(parent, Story) and isinstance(child, SubEpic):
        raise PlacementError("A SubEpic cannot live under a Story")
    if child is None or parent is None:
        raise PlacementError("Both child and parent are required")
    if isinstance(child, Epic) and parent is not None and not isinstance(
        parent, StoryMap
    ):
        raise PlacementError("An Epic can only sit under the Story Map itself")

def _all_sub_epics_recursive(
    self, siblings: Iterable[SubEpic]
) -> Iterable[SubEpic]:
    for sibling in siblings:
        yield sibling
        yield from self._all_sub_epics_recursive(sibling.sub_epics)

