def from_workspace(cls, root: Path) -> Optional[UxMap]:
    root = Path(root)
    loader = cls.create()
    for candidate in (
        root / ".context" / "information-architecture.drawio",
        root / ".context" / "ia.drawio",
        root / "information-architecture.drawio",
        root / "ia.drawio",
        root / "site-map.drawio",
    ):
        if candidate.is_file():
            return loader.parse(candidate.read_text(encoding="utf-8"))
    matches = sorted((root / ".context").glob("*.drawio")) if (root / ".context").is_dir() else []
    matches += sorted(root.glob("*.drawio"))
    if matches:
        return loader.parse(matches[0].read_text(encoding="utf-8"))
    return None

def _diagram_by_name(self, root_el: ET.Element, name: str) -> Optional[ET.Element]:
    for diagram in root_el.findall("diagram"):
        if diagram.get("name") == name:
            return diagram
    return None

def _append_site_screens(self, ux_map: UxMap, source: ET.Element) -> dict[str, Screen]:
    id_to_screen: dict[str, Screen] = {}
    for cell in source.iter("mxCell"):
        if cell.get("vertex") != "1" or cell.get("parent") != "1":
            continue
        name = self._strip_html(cell.get("value", ""))
        if not name or self._is_annotation(name):
            continue
        screen = Screen(name, len(ux_map.screens))
        ux_map.append_screen(screen)
        id_to_screen[cell.get("id", "")] = screen
    return id_to_screen

def _append_detailed_regions(self, ux_map: UxMap, detailed: ET.Element) -> None:
    name_to_screen = {screen.name: screen for screen in ux_map.screens}
    detailed_ids: dict[str, Screen] = {}
    for cell in detailed.iter("mxCell"):
        if cell.get("vertex") != "1" or cell.get("parent") != "1":
            continue
        title = self._strip_html(cell.get("value", ""))
        if title in name_to_screen:
            detailed_ids[cell.get("id", "")] = name_to_screen[title]
    for cell in detailed.iter("mxCell"):
        parent = cell.get("parent", "")
        if cell.get("vertex") != "1" or parent not in detailed_ids:
            continue
        if "strokeColor=none" in cell.get("style", ""):
            continue
        region_name = self._strip_html(cell.get("value", ""))
        if not region_name or self._is_annotation(region_name):
            continue
        screen = detailed_ids[parent]
        if any(region.name == region_name for region in screen.regions):
            continue
        screen.append_region(Region(region_name, len(screen.regions)))

def _append_transitions(self, ux_map: UxMap, source: ET.Element) -> None:
    for cell in source.iter("mxCell"):
        if cell.get("edge") != "1":
            continue
        src = self._id_to_screen.get(cell.get("source", ""))
        tgt = self._id_to_screen.get(cell.get("target", ""))
        if src is None or tgt is None:
            continue
        trigger = self._strip_html(cell.get("value", "")) or f"{src.name} -> {tgt.name}"
        self._edge_src = src
        self._edge_tgt = tgt
        self._append_edge_transitions(ux_map, trigger)

def _check_edges_approach_perpendicular(self, root):
    classes = self._get_all_classes(root)
    self._id_to_name = {cid: name for cid, name, *_ in classes}
    self._id_to_geo = {cid: (x, y, w, h) for cid, name, x, y, w, h in classes}
    violations = []
    for cell in root.findall('mxCell'):
        self._record_edge_approach(cell, violations)
    return violations

def _anchor_side(self, frac_x: float | None, frac_y: float | None) -> str | None:
    if frac_x is None or frac_y is None:
        return None
    if abs(frac_x - 0) < 0.001:
        return 'left'
    if abs(frac_x - 1) < 0.001:
        return 'right'
    if abs(frac_y - 0) < 0.001:
        return 'top'
    if abs(frac_y - 1) < 0.001:
        return 'bottom'
    return None

def _parse_style(self, style: str) -> dict[str, float]:
    out: dict[str, float] = {}
    for kv in (style or '').split(';'):
        if '=' not in kv:
            continue
        key, value = kv.split('=', 1)
        try:
            out[key] = float(value)
        except ValueError:
            continue
    return out

def _segment_direction(self, seg) -> str | None:
    (x1, y1), (x2, y2) = seg
    dx = abs(x2 - x1)
    dy = abs(y2 - y1)
    if dx < 1 and dy < 1:
        return None
    if dx < 1:
        return 'v'
    if dy < 1:
        return 'h'
    return None

def _segment_direction_signed(self, seg) -> str | None:
    (x1, y1), (x2, y2) = seg
    dx = x2 - x1
    dy = y2 - y1
    if abs(dx) < 1 and abs(dy) < 1:
        return None
    if abs(dx) >= abs(dy):
        return 'right' if dx > 0 else 'left'
    return 'down' if dy > 0 else 'up'

def _expected_direction_for_side(self, side: str | None) -> str | None:
    if side in ('left', 'right'):
        return 'h'
    if side in ('top', 'bottom'):
        return 'v'
    return None

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []

    for domain_path in self._find_domain_packages(root):
        violations += self._check_shared_entities(domain_path)
        violations += self._check_server_repositories(domain_path)

    return violations

def _check_shared_entities(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    shared_dir = domain_path / "shared"
    if not shared_dir.exists():
        return violations

    for ts_file in sorted(shared_dir.glob("*.ts")):
        if ts_file.name in ("index.ts",):
            continue
        if ts_file.stem.endswith(".schema"):
            continue

        parsed_root = self.parse_file(ts_file)
        if parsed_root is None:
            continue

        for cls in self.classes:
            if self._is_exempt_class(cls):
                continue
            violations.extend(self._check_entity_methods(cls, ts_file))
            violations.extend(self._check_no_async_on_entity(cls, ts_file))
            if self._is_collection_class(cls.name):
                violations.extend(self._check_collection_query_methods(cls, ts_file))

    return violations

def _is_exempt_class(self, cls) -> bool:
    """Return True for error/exception classes and pure value objects."""
    if cls.extends in self._EXEMPT_EXTENDS:
        return True
    if any(cls.name.endswith(s) for s in self._EXEMPT_NAME_SUFFIXES):
        return True
    if cls.properties and all("readonly" in p.modifiers for p in cls.properties):
        return True
    return False

def _entity_violations_in(self, ts_file: Path) -> List[Violation]:
    parsed_root = self.parse_file(ts_file)
    if parsed_root is None:
        return []
    violations: List[Violation] = []
    for cls in self.classes:
        if self._is_exempt_class(cls):
            continue
        violations.extend(self._check_entity_methods(cls, ts_file))
        violations.extend(self._check_no_async_on_entity(cls, ts_file))
        if self._is_collection_class(cls.name):
            violations.extend(self._check_collection_query_methods(cls, ts_file))
    return violations

def _check_no_async_on_entity(self, cls, ts_file: Path) -> List[Violation]:
    """Domain entity methods must be synchronous (no async)."""
    violations: List[Violation] = []
    for method in cls.methods:
        if method.is_async and "private" not in method.modifiers:
            violations.append(
                self.v(
                    f"Class '{cls.name}'.{method.name}() is async - domain "
                    "entities must be pure synchronous. Move async operations "
                    "to the repository or service layer.",
                    str(ts_file),
                    method.start_line,
                )
            )
    return violations

def _is_collection_class(self, name: str) -> bool:
    """Heuristic: plural class names without 'Schema'/'Type'/'Info' are collections."""
    if name.endswith(("Schema", "Type", "Info", "DTO", "Error", "Status")):
        return False
    if name.endswith("s") and not name.endswith("ss"):
        return True
    return False

def render_imports(
    self,
    factories: Sequence[str],
    ce_module: str = "example_factories",
) -> List[str]:
    if not factories:
        return []
    lines = [
        f"# Example factories (clean_engineering) - adjust `{ce_module}` to match CE layout",
    ]
    for name in factories:
        lines.append(f"from {ce_module} import {name}")
    lines.append("")
    return lines

def render_accessors(self, factories: Sequence[str]) -> List[str]:
    if not factories:
        return []
    lines = [
        "    # -- Example factories - imported by tier test-helpers to build real collaborators --",
        "",
    ]
    for name in factories:
        method = self._pascal_to_snake(name)
        lines.append(f"    def {method}(self) -> {name}:")
        lines.append(
            f'        """Return {name}; callers use factory methods for scenario objects."""'
        )
        lines.append(f"        return {name}()")
        lines.append("")
    return lines

def _pascal_to_camel(self, name: str) -> str:
    if not name:
        return name
    return name[0].lower() + name[1:]

def _render_epic(self, epic: Epic) -> None:
    epic_slug = to_kebab(epic.name)
    helper = self._render_epic_helper(epic)
    if helper is not None:
        self._tree[f"{self._root}/{epic_slug}/{epic_slug}-helper.js"] = helper
    self._epic = epic
    self._depth = 2
    for sub in getattr(epic, "sub_epics", []) or []:
        self._render_sub_epic(sub, f"{self._root}/{epic_slug}")

def _render_sub_epic(self, sub: SubEpic, parent: str) -> None:
    folder = f"{parent}/{to_kebab(sub.name)}"
    saved_depth = self._depth
    self._depth = saved_depth + 1
    for nested in getattr(sub, "sub_epics", []) or []:
        self._render_sub_epic(nested, folder)
    for story in getattr(sub, "stories", []) or []:
        self._render_story(story, folder)
    self._depth = saved_depth

def _render_tree(self, story_map: StoryMap, tests_root: str) -> Dict[str, str]:
    tree: Dict[str, str] = {}
    root = tests_root.strip("/") or "tests"
    if self._include_shared:
        _types_body, test_body = self._read_shared_templates()
        tree[f"{root}/story-test.js"] = test_body
    self._tree = tree
    self._root = root
    for epic in getattr(story_map, "epics", []) or []:
        self._render_epic(epic)
    return tree

def _render_story(self, story: Story, parent: str) -> None:
    if not getattr(story, "scenarios", None):
        return
    story_folder = f"{parent}/{to_kebab(story.name)}"
    relative_story_test = "../" * self._depth + "story-test.js"
    self._tree[f"{story_folder}/{to_snake(story.name)}_story.test.js"] = render_story_file(
        story,
        relative_story_test_path=relative_story_test,
    )

def render(
    self,
    canonical: StoryMap,
    previous: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    tree = PythonTree().render(canonical, self.tests_root)
    if previous:
        for path, body in list(tree.items()):
            if path in previous and path.endswith(self.LEAF_EXTENSION):
                tree[path] = self._preserve_hand_written(previous[path], body)
    return tree

def parse(self, external: Dict[str, str]) -> StoryMap:
    if not isinstance(external, dict):
        raise CodeStoryMapError("Python story map parse expects a path->content dict")
    story_map = self._make_story_map()
    for path, content in sorted(external.items()):
        if not path.endswith(self.LEAF_EXTENSION):
            continue
        parts = path.strip("/").split("/")
        if parts and parts[0] == self.tests_root:
            parts = parts[1:]
        if len(parts) < 4:
            continue
        epic_slug = parts[0]
        story_slug = parts[-2]
        sub_slugs = parts[1:-2]
        if not sub_slugs:
            continue
        epic = self._ensure_epic(story_map, epic_slug)
        sub = self._ensure_sub_path(epic, sub_slugs)
        story = self._parse_story_file(content, story_slug)
        if story is not None:
            sub.stories.append(story)
    return story_map

def from_workspace(cls, root: Path) -> List[TestSuite]:
    """Find and parse all Python test files under *root*."""
    root = Path(root).resolve()
    if root.is_file():
        if root.suffix == ".py":
            return [cls._parse_file(root, root.parent)]
        return []
    seen: set = set()
    suites: List[TestSuite] = []
    for pattern in _GLOBS:
        for p in root.glob(pattern):
            if p in seen or not p.is_file():
                continue
            seen.add(p)
            suites.append(cls._parse_file(p, root))
    return suites

def _ensure_epic(self, story_map: StoryMap, epic_slug: str) -> Epic:
    for epic in story_map.epics:
        if to_kebab(epic.name) == epic_slug:
            return epic
    epic = self._make_epic(epic_slug.replace("-", " ").title(), len(story_map.epics) + 1)
    story_map.append_epic(epic)
    return epic

def _parse_story_file(self, content: str, story_slug: str) -> Story | None:
    name_match = re.search(r"^Story:\s*(.+)$", content, re.MULTILINE)
    story_name = (
        name_match.group(1).strip()
        if name_match
        else story_slug.replace("-", " ").title()
    )
    story_name = re.sub(r"\s*\(tier-neutral\)\.?\s*$", "", story_name).strip()
    story = Story(story_name, 1)
    actor_match = re.search(r"^Actor:\s*(.+)$", content, re.MULTILINE)
    if actor_match:
        story.users = [actor_match.group(1).strip()]
    domain_match = re.search(r"^Domain terms:\s*(.+)$", content, re.MULTILINE)
    if domain_match:
        story.domain_terms = [t.strip() for t in domain_match.group(1).split(",") if t.strip()]
    for i, sc_name in enumerate(
        re.findall(r"SCENARIO:\s*(.+)", content), start=1
    ):
        story.scenarios.append(Scenario(name=sc_name.strip(), sequential_order=i))
    return story

def _has_synsets(self, word: str, pos) -> bool:
    try:
        word_lower = word.lower()
        synsets = wn.synsets(word_lower, pos=pos)
        return len(synsets) > 0
    except Exception as error:
        print(f"Warning: WordNet synsets failed for {word}: {error}", file=sys.stderr)
        return False

def pos_tags(self, text: str) -> List[Tuple[str, str]]:
    try:
        tokens = word_tokenize(text)
        tokens = [t for t in tokens if t.isalnum() or any(c.isalnum() for c in t)]
        return pos_tag(tokens)
    except Exception as error:
        print(f"Warning: POS tagging failed: {error}", file=sys.stderr)
        return []

def is_actor_or_role(self, word: str) -> bool:
    try:
        return self._hypernym_is_actor(word.lower())
    except Exception as error:
        print(f"Warning: actor check failed for {word}: {error}", file=sys.stderr)
        return False

def _hypernym_is_actor(self, word_lower: str) -> bool:
    synsets = wn.synsets(word_lower)
    if not synsets:
        return False
    for synset in synsets:
        hypernyms = set()
        for path in synset.hypernym_paths():
            hypernyms.update(path)
        for hypernym in hypernyms:
            name = hypernym.name().split(".")[0]
            if name in ["person", "user", "system", "agent", "entity", "causal_agent"]:
                return True
    return False

def load_module(self, source: Module) -> "GraphModule":
    if isinstance(source, BoundedContext):
        return GraphBoundedContext(source.name, source.sequential_order)
    if isinstance(source, Aggregate):
        return GraphAggregate(source.name, source.sequential_order)
    return GraphModule(source.name, source.sequential_order)

