def write(self, tool: Any) -> None:
    kind = self.destination
    if tool.kind == "tool":
        if kind not in {"skill", "command", "rules"}:
            return
    if not kind:
        return
    member = tool.callable
    toolset = tool.toolset
    parts = [self._body_for(kind, tool, toolset)]
    if self.mcp_mode:
        from harness.mcp.mcp_server import McpOperationDefinition

        fidelity_parts = (
            self._fidelity_invoke_parts(toolset)
            if tool.name == "instructions"
            else []
        )
        if fidelity_parts:
            parts.extend(fidelity_parts)
        else:
            parts.append(McpOperationDefinition.from_tool(tool).invoke_line())
    text = self.render("\n\n".join(p for p in parts if p), member, toolset)
    rel = self.relative_path(kind, toolset, member, tool.deploy_name)
    if kind == "rules":
        from harness.guidance.rule import AppliesTo

        text = AppliesTo.strip_fence(text)
        text = self._rules_front_matter(text, toolset) + text
    elif kind == "skill":
        text = self._skill_front_matter(rel.parent.name, self._skill_overview(toolset, parts)) + text
    dest = self.path / rel
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(text, encoding="utf-8")
    self.track_write(dest)

def _skill_folder(self, toolset: Any, op: str) -> Path:
    folder = self._kebab_folder(self.folder_for(toolset))
    if getattr(toolset, "practice_guidance", None) is not None:
        slug = getattr(toolset, "slug", None)
        if slug:
            parent = folder.parent if folder.name else folder
            return parent / self._op_slug(str(slug))
    if op in {"instructions", "rules-markdown"}:
        return folder
    last = folder.name
    if len(self._skill_ops(toolset)) > 1:
        return folder / op
    if op == last:
        return folder
    return folder / op

def _command_folder(self, toolset: Any, folder: Path) -> Path:
    kebab = self._kebab_folder(folder)
    if getattr(toolset, "practice_guidance", None) is not None:
        return kebab.parent if kebab.name else kebab
    return kebab

def _command_stem(self, toolset: Any, op: str) -> str:
    if getattr(toolset, "practice_guidance", None) is not None:
        slug = getattr(toolset, "slug", None)
        if slug:
            return self._op_slug(str(slug))
    return op

def _skill_ops(self, toolset: Any) -> list[str]:
    bag = getattr(toolset, "tools", None) or {}
    values = bag.values() if isinstance(bag, dict) else bag
    names: list[str] = []
    for tool in values:
        if not getattr(tool, "install_to_skill", False):
            continue
        names.append(self._op_slug(getattr(tool, "deploy_name", None) or tool.name))
    return names

def _fidelity_invoke_parts(self, toolset: Any) -> list[str]:
    entries = getattr(getattr(toolset, "fidelities", None), "entries", None) or {}
    parts: list[str] = []
    for _name, child in entries.items():
        member = getattr(type(child), "instructions", None)
        getter = getattr(member, "fget", member)
        invoke = (
            f"Use MCP tool: `{getattr(child, 'slug', '')}()`"
            if getattr(getter, "_mcp", False)
            else ""
        )
        parts.append(
            "\n\n".join(piece for piece in (self._fidelity_one_liner(child), invoke) if piece)
        )
    return parts

def from_tool(cls, tool: Any) -> McpOperationDefinition:
    kind = "tool" if tool.kind == "tool" else "prompt"
    toolset = tool.toolset
    if getattr(toolset, "practice_guidance", None) is not None:
        mcp_name = tool.slug
    else:
        mcp_name = f"{tool.slug}.{tool.name}"
    return cls(
        mcp_name=mcp_name,
        kind=kind,
        tool=toolset,
        operation=tool.name,
        member=tool.callable,
        description=tool.description,
    )

def matches(self, node: Any) -> bool:
    if not self._match_path(node):
        return False
    if not self._match_identity(node):
        return False
    if not self._match_source(node):
        return False
    if not self._match_related(node):
        return False
    return self._match_rules(node)

def from_value(cls, value: Any) -> Filter:
    if value in (None, "", {}, []):
        return cls()
    if isinstance(value, cls):
        return value
    if isinstance(value, str):
        stripped = value.strip()
        if stripped.startswith("{"):
            return cls.from_value(json.loads(stripped))
        return cls(path=stripped)
    if not isinstance(value, dict):
        raise TypeError(f"Filter expected an object, got {type(value).__name__}")
    fields = cls()._canonical_fields(value)
    related = fields.get("related_to")
    if related not in (None, "", {}):
        fields["related_to"] = cls.from_value(related)
    allowed = cls.__init__.__code__.co_varnames[1:]
    return cls(**{key: fields[key] for key in fields if key in allowed})

def _canonical_fields(self, value: dict) -> dict:
    fields: dict[str, Any] = {}
    for key, raw in value.items():
        fields[_ALIASES.get(key, key)] = raw
    return fields

def _match_path(self, node: Any) -> bool:
    path = str(self.path or "").strip()
    if not path:
        return True
    keys = [part.strip().casefold() for part in path.split(".") if part.strip()]
    hits = {item.node_id for item in self._nodes_along(node.graph, keys)}
    return node.node_id in hits

def _match_identity(self, node: Any) -> bool:
    names = self.listed(("name",))
    if names and self._name_key(node) not in {item.casefold() for item in names}:
        return False
    if self.node_id and node.node_id != str(self.node_id):
        return False
    practices = self.listed(("practices", "practice"))
    if practices and (getattr(node, "practice", "") or "") not in practices:
        return False
    types = self.listed(("semantic_types", "semantic_type"))
    if types and node.semantic_type() not in types:
        return False
    stages = self.listed(("stages", "fidelity"))
    stage = getattr(node, "fidelity", None) or getattr(node, "stage", "") or ""
    if stages and stage not in stages:
        return False
    return True

def _match_source(self, node: Any) -> bool:
    file = str(self.file or "").replace("\\", "/").casefold()
    if not file:
        return True
    src = str(getattr(getattr(node, "source", None), "file", "") or "").replace("\\", "/")
    return file in src.casefold()

def _match_related(self, node: Any) -> bool:
    kinds = self.listed(("relationship_types", "relationship_type"))
    if kinds and not node.has_kind(kinds):
        return False
    related = self.related_to
    if related is None:
        return True
    others = node.incident()
    kind = str(related.kind or related.relationship_type or "")
    if kind:
        others = [item for item in others if self._edge_kind(node, item) == kind]
    return any(related.matches(item) for item in others)

def _match_rules(self, node: Any) -> bool:
    hits = list(node.graph.violations_for(node))
    rules = self.listed(("rules", "rule"))
    if self.violations in _TRUE:
        if not hits:
            return False
        if rules:
            return any(hit.rule_slug in rules for hit in hits)
        return True
    if not rules:
        return True
    if any(hit.rule_slug in rules for hit in hits):
        return True
    names = list(getattr(node, "applicable_rules", None) or [])
    return any(slug in names for slug in rules)

def expand_ids(self, seeds: Iterable[str], graph: Any) -> set[str]:
    seed_ids = {node_id for node_id in seeds if node_id in graph.nodes}
    keep = set(seed_ids)
    for node_id in seed_ids:
        node = graph.nodes[node_id]
        for ancestor in node.ancestors():
            keep.add(ancestor.node_id)
        for child in node.descendants():
            keep.add(child.node_id)
        for other in node.incident():
            keep.add(other.node_id)
    return keep

def subtree_ids(self, seeds: Iterable[str], graph: Any) -> set[str]:
    seed_ids = {node_id for node_id in seeds if node_id in graph.nodes}
    keep = set(seed_ids)
    for node_id in seed_ids:
        for child in graph.nodes[node_id].descendants():
            keep.add(child.node_id)
    return keep

def _nodes_along(self, graph: Any, keys: list[str]):
    if not keys:
        return list(graph.nodes.values())
    current = [node for node in graph.nodes.values() if self._key_matches(node, keys[0])]
    for key in keys[1:]:
        current = [
            child
            for node in current
            for child in node.children()
            if self._key_matches(child, key)
        ]
    return current

def ancestors(self) -> List["Node"]:
    found: List[Node] = []
    current: Node = self
    for _ in range(16):
        parents = current.related(Kind.BELONGS_TO) or current.related(
            Kind.OWNS, direction="in"
        )
        if not parents:
            break
        current = parents[0]
        found.append(current)
    return found

def descendants(self) -> List["Node"]:
    found: List[Node] = []
    stack = list(self.children())
    seen = {self.node_id}
    while stack:
        child = stack.pop()
        if child.node_id in seen:
            continue
        seen.add(child.node_id)
        found.append(child)
        stack.extend(child.children())
    return found

def has_kind(self, kinds: list[str]) -> bool:
    names = set(kinds)
    return any(edge.kind in names for edge in self.graph.edges_at(self))

def matches_source(self, file: str, line: int) -> bool:
    src = getattr(self, "source", None)
    node_file = str(getattr(src, "file", "") or "").replace("\\", "/")
    if not node_file or line <= 0:
        return False
    hit = file.replace("\\", "/")
    if not (
        node_file.endswith(hit)
        or hit.endswith(node_file)
        or node_file.split("/")[-1] == hit.split("/")[-1]
    ):
        return False
    start = int(getattr(src, "line", 0) or 0)
    end = int(getattr(src, "end_line", 0) or start)
    if start <= 0:
        return False
    return start <= line <= max(end, start)

def owner_class(self):
    for kind in (Kind.BELONGS_TO, Kind.OWNS):
        for other in self.related(kind):
            if other.semantic_type() == "OoadClass":
                return other
    for other in self.used_by:
        if other.semantic_type() == "OoadClass":
            return other
    return None

def _unique(self, nodes: List["Node"]) -> List["Node"]:
    seen: set[str] = set()
    out: List[Node] = []
    for node in nodes:
        if node.node_id in seen:
            continue
        seen.add(node.node_id)
        out.append(node)
    return out

def _walk_invokes(self, op: "Node", remaining: int) -> None:
    if remaining <= 0 or op.node_id in self._invoke_path:
        return
    self._invoke_path.add(op.node_id)
    for callee in op.related(Kind.INVOKES):
        if callee.semantic_type() != "Operation":
            continue
        if callee.node_id in self._invoke_seen:
            continue
        self._invoke_seen.add(callee.node_id)
        self._invoke_found.append(callee)
        self._walk_invokes(callee, remaining - 1)
    self._invoke_path.discard(op.node_id)

