def hits_for_keep_classes(self, hits: Iterable[dict]) -> List[dict]:
    refined: List[dict] = []
    for class_name, tokens_by_operation in self._tokens_by_class(hits).items():
        if not self._mixed_responsibilities(tokens_by_operation):
            continue
        clusters = self._cluster_operations(tokens_by_operation)
        message = (
            f"Class '{class_name}' has {len(tokens_by_operation)} public operations "
            f"whose nouns cluster into {len(clusters)} responsibilities."
        )
        for operation in tokens_by_operation:
            refined.append(
                {"name": class_name, "message": message, "contributor": operation}
            )
    return refined

def _tokens_by_class(self, hits: Iterable[dict]) -> Dict[str, Dict[str, Set[str]]]:
    by_class: Dict[str, Dict[str, Set[str]]] = defaultdict(lambda: defaultdict(set))
    for hit in hits:
        class_name = hit.get("name") or ""
        operation = hit.get("contributor") or ""
        token = hit.get("message") or ""
        if class_name and operation:
            by_class[class_name][operation].add(token)
    return by_class

def _mixed_responsibilities(self, tokens_by_operation: Mapping[str, Set[str]]) -> bool:
    if len(tokens_by_operation) <= _MIN_PUBLIC_OPERATIONS:
        return False
    return len(self._cluster_operations(tokens_by_operation)) >= _MIN_NOUN_CLUSTERS

def _cluster_operations(self, tokens_by_operation: Mapping[str, Set[str]]) -> List[Set[str]]:
    parent = {name: name for name in tokens_by_operation}

    def find(name: str) -> str:
        while parent[name] != name:
            parent[name] = parent[parent[name]]
            name = parent[name]
        return name

    def union(left: str, right: str) -> None:
        root_left, root_right = find(left), find(right)
        if root_left != root_right:
            parent[root_right] = root_left

    nouns_by_op = {
        name: self.nouns_in(tokens) for name, tokens in tokens_by_operation.items()
    }
    named = [name for name, nouns in nouns_by_op.items() if nouns]
    for index, left in enumerate(named):
        for right in named[index + 1 :]:
            if nouns_by_op[left] & nouns_by_op[right]:
                union(left, right)
    clusters: Dict[str, Set[str]] = defaultdict(set)
    for name in named:
        clusters[find(name)].add(name)
    return list(clusters.values())

def nouns_in(self, tokens: Iterable[str]) -> Set[str]:
    words = [token.lower() for token in tokens if token]
    nouns: Set[str] = set()
    for index, word in enumerate(words):
        as_noun = bool(wn.synsets(word, wn.NOUN))
        as_verb = bool(wn.synsets(word, wn.VERB))
        if as_verb and (not as_noun or index == 0):
            continue
        if as_noun:
            nouns.add(self._stem_noun(word))
    return nouns

def rows_for_vague_mechanic(self, rows: Iterable[dict]) -> List[dict]:
    refined: List[dict] = []
    seen = set()
    for row in rows:
        label = row.get("message") or ""
        if label in seen:
            continue
        words = self._words(label)
        if len(words) < 2:
            continue
        first = words[0]
        rest = words[1:]
        if not VocabularyHelper().is_verb(first) or first not in _VAGUE_VERBS:
            continue
        if not any(word in _GENERIC_NOUNS for word in rest):
            continue
        seen.add(label)
        refined.append(
            {
                "name": row.get("name") or "",
                "message": f"Story '{label}' does not name a system mechanic.",
                "contributor": row.get("contributor") or "",
            }
        )
    return refined

def _named_template_file(self, name: str, *, practice: bool) -> AssetLocation | None:
    stems = list(_slug_variants(name))
    if practice:
        stems = [
            extra
            for slug in _slug_variants(name)
            for extra in (slug, f"{slug}-templates", f"{slug}-template")
        ]
    self._template_stems = stems
    self._template_ext = _FORMAT_TEMPLATE_EXT.get(self._active_format or "", "")
    for folder in self._template_folders():
        located = self._template_in_folder(folder)
        if located is not None:
            return located
    return None

def class_file_directory(self) -> Path:
    instance = self._instance
    practice = getattr(instance, "practice_guidance", None)
    if practice is not None:
        instance = practice
    stored = getattr(instance, "module_dir", None)
    if stored is not None:
        return Path(stored)
    try:
        return Path(inspect.getfile(type(instance))).resolve().parent
    except (TypeError, OSError):
        return Path(".")

def _active_resource(self, key: str | None) -> str | None:
    if not key:
        return None
    if key == "fidelity":
        return self._current_fidelity()
    value = getattr(self._instance, key, None)
    return str(value) if value else None

def _fidelity_scope(self) -> str | None:
    """Fidelity section name on Guidance only — not WorkSession.name or AgentToolSet.name."""
    if getattr(self._instance, "practice_guidance", None) is not None:
        value = getattr(self._instance, "name", None)
        return str(value) if value else None
    for cls in type(self._instance).__mro__:
        scoped = self._declared_name_scope(cls)
        if scoped is not _MISSING:
            return scoped
    return None

def _declared_name_scope(self, cls: type) -> str | None | object:
    if cls is object:
        return _MISSING
    declared = cls.__dict__.get("name", _MISSING)
    if declared is _MISSING:
        return _MISSING
    if isinstance(declared, property):
        return None
    value = getattr(self._instance, "name", None)
    return str(value) if value else None

def _stamp(self, location: AssetLocation) -> AssetLocation:
    fidelity = location.fidelity
    if location.kind == "folder":
        fidelity = fidelity or self.fidelity
    return replace(
        location,
        label=self._label,
        fidelity=fidelity,
        format=location.format or self.format,
    )

def _locate_template_or_missing(self, filter_value: str | None) -> AssetLocation:
    self._active_format = filter_value or self._active_resource("format")
    located = self._locate_templates()
    if located.path is not None and located.path.is_file():
        return located
    return AssetLocation(
        "file",
        self._module_dir,
        self._domain_slug,
        path=(self._module_dir / ".no-template").resolve(),
    )

def _search_root(self, module_dir: Path, filter_value: str | None) -> Path:
    root = module_dir
    if self._group:
        root = root / self._group
    if not filter_value:
        return root
    as_dir = root / filter_value
    if as_dir.is_dir():
        return as_dir
    return root

def _locate_under(self) -> AssetLocation:
    fidelity_name = self._fidelity_scope()
    if fidelity_name:
        return AssetLocation(
            "section",
            self._module_dir,
            self._domain_slug,
            section_file=self._canonical_domain_md().resolve(),
            section_heading=_section_heading(self._label),
            fidelity=str(fidelity_name),
        )
    folder = self._search_root_path / self._label
    if folder.is_dir():
        return AssetLocation("folder", self._module_dir, self._domain_slug, folder=folder.resolve())
    for name in (self._label, f"{self._label}.md"):
        candidate = self._search_root_path / name
        if candidate.is_file():
            return AssetLocation("file", self._module_dir, self._domain_slug, path=candidate.resolve())
    first = self._first_extension_match(self._search_root_path)
    if first:
        return AssetLocation("file", self._module_dir, self._domain_slug, path=first.resolve())
    return AssetLocation(
        "section",
        self._module_dir,
        self._domain_slug,
        section_file=self._canonical_domain_md().resolve(),
        section_heading=_section_heading(self._label),
    )

def _locate_templates(self) -> AssetLocation:
    fidelity = self._active_resource("fidelity")
    if fidelity:
        located = self._named_template_file(fidelity, practice=False)
        if located is not None:
            return located
    located = self._named_template_file(self._domain_slug, practice=True)
    if located is not None:
        return located
    return AssetLocation(
        "file",
        self._module_dir,
        self._domain_slug,
        path=(self._module_dir / ".no-template").resolve(),
    )

def _canonical_domain_md(self) -> Path:
    for root in (self._module_dir, self._search_root_path):
        found = self._domain_md_in(root)
        if found is not None:
            return found
    return self._module_dir / f"{self._domain_slug}.md"

def _first_extension_match(self, search_root: Path) -> Path | None:
    if not search_root.is_dir():
        return None
    matches = sorted(c for c in search_root.glob(f"{self._label}.*") if c.is_file())
    return matches[0] if matches else None

def _domain_md_in(self, root: Path) -> Path | None:
    for slug in _slug_variants(self._domain_slug):
        candidate = root / f"{slug}.md"
        if candidate.is_file():
            return candidate
    return None

def _template_in_folder(self, folder: Path) -> AssetLocation | None:
    if not folder.is_dir():
        return None
    if self._template_ext:
        return self._template_with_ext(folder)
    return self._template_any_ext(folder)

def _template_with_ext(self, folder: Path) -> AssetLocation | None:
    for stem in self._template_stems:
        path = folder / f"{stem}{self._template_ext}"
        if path.is_file() and "sketch" not in path.stem.casefold():
            return AssetLocation(
                "file", self._module_dir, self._domain_slug, path=path.resolve()
            )
    return None

def _template_any_ext(self, folder: Path) -> AssetLocation | None:
    for stem in self._template_stems:
        for path in sorted(folder.glob(f"{stem}.*")):
            if path.is_file() and "sketch" not in path.stem.casefold():
                return AssetLocation(
                    "file", self._module_dir, self._domain_slug, path=path.resolve()
                )
    return None

def from_markdown(
    cls,
    text: str,
    fidelity: str | None = None,
    parent: Any = None,
) -> RulesCollection:
    collection = super().from_markdown(text, fidelity=fidelity, parent=parent)
    practice = _practice_slug(parent)
    if not practice:
        return collection
    shared = getattr(parent, "fidelities", None) is not None
    for slug, rule in list(collection.entries.items()):
        if not isinstance(rule, Rule) or isinstance(rule, GraphRule):
            continue
        query = _PRACTICES / practice / "model" / "codeql" / f"{slug}.ql"
        if not query.is_file():
            continue
        collection.entries[slug] = GraphRule(rule, practice=practice, shared=shared)
    return collection

def inherit_annotations(
    child: Callable[..., Any] | None,
    parent: Callable[..., Any] | None,
) -> None:
    """Copy missing decorator markers from parent onto child (do not overwrite)."""
    if child is None or parent is None:
        return
    child_f = getattr(child, "__func__", child)
    parent_f = getattr(parent, "__func__", parent)
    if not callable(child_f) or not callable(parent_f):
        return
    for attr in _INHERITED_MARKER_ATTRS:
        if hasattr(child_f, attr):
            continue
        if hasattr(parent_f, attr):
            setattr(child_f, attr, getattr(parent_f, attr))

def inherit_annotations_from_bases(cls: type) -> None:
    """For each override on ``cls``, inherit markers from base definitions of the same name."""
    for name, child in list(cls.__dict__.items()):
        if name.startswith("__") or not callable(child):
            continue
        child_f = getattr(child, "__func__", child)
        for base in cls.__mro__[1:]:
            parent = base.__dict__.get(name)
            if parent is None or not callable(parent):
                continue
            parent_f = getattr(parent, "__func__", parent)
            if parent_f is child_f:
                continue
            inherit_annotations(child, parent)

def summarize_mapping(data: dict[str, Any] | None, *, limit: int = 120) -> str:
    if not data:
        return ""
    parts = [f"{key}={_short(value)}" for key, value in data.items()]
    text = ",".join(parts)
    if len(text) <= limit:
        return text
    return text[: limit - 1] + "..."

def _short(value: Any, *, max_len: int = 40) -> str:
    text = str(value).replace("\n", " ")
    if len(text) <= max_len:
        return text
    return text[: max_len - 1] + "..."

def docs_dir(self, destination: str | Path) -> Path:
    """Durable artifact dir: ``{path}/.context/`` (sketches, generate, grill-answers).

    Never returns a session folder. If *destination* is already ``.context``, a
    session folder, or a mistaken sibling under ``.context``, walk up to that
    ``.context``. Otherwise ``{destination}/.context/``.
    """
    dest = Path(destination)
    if dest.name == ".context":
        return dest
    if dest.name == ".sessions":
        return self.repository_root(dest) / ".context"
    if dest.name == "sessions" and dest.parent.name == ".context":
        return dest.parent
    if self.is_session_folder(dest):
        parent = dest.parent
        if parent.name == "sessions" and parent.parent.name == ".context":
            return parent.parent
        return self.repository_root(dest) / ".context"
    if dest.parent.name == ".context" and dest.name not in ("sessions", ".sessions"):
        return dest.parent
    return dest / ".context"

def repository_root(self, path: str | Path) -> Path:
    """Git primary clone root for *path*, or *path* itself when not in a repo."""
    found = Repo(path).find_root()
    if found is not None:
        return Path(found)
    return Path(path)

def is_session_folder(self, destination: str | Path) -> bool:
    dest = Path(destination)
    if not dest.name or dest.name == "closed":
        return False
    parent = dest.parent
    if parent.name == ".sessions":
        return True
    return parent.name == "sessions" and parent.parent.name == ".context"

def module_dir(self) -> Path:
    try:
        return Path(inspect.getfile(type(self))).resolve().parent
    except (TypeError, OSError):
        return Path(".")

def child_for_stage(self, stage: str) -> Guidance:
    values = self.entries.values() if isinstance(self.entries, dict) else self.entries
    for child in values:
        if getattr(child, "stage", "") == stage:
            return child
    raise KeyError(stage)

def inject_rules_toast(self, source: str, labels: list[str]) -> str:
    # always prefix the joined names with rules :
    ...

def detect_echo(
    self, hook_payload: dict, toolsets: list | None = None
) -> tuple[str, str] | None:
    invoked = self._mcp_tool_name(hook_payload)
    if not invoked:
        return None
    hosts = self._walk_toolsets(
        toolsets if toolsets is not None else self.echo_toolsets()
    )
    for toolset in hosts:
        found = self._echo_on_toolset(invoked, toolset)
        if found is not None:
            return found
    return None

def echo_toolsets(self, repo: Path | None = None) -> list:
    if repo is None and type(self)._echo_toolsets is not None:
        return type(self)._echo_toolsets
    loaded = self._load_echo_toolsets(repo)
    if repo is None:
        type(self)._echo_toolsets = loaded
    return loaded

def _walk_skill_tree(self, root: Path) -> None:
    if not root.is_dir():
        return
    found = self.skill_found
    top_kind = self.skill_kind
    for child in root.iterdir():
        if not child.is_dir():
            continue
        token = child.name.replace("_", "-")
        found.setdefault(token, top_kind)
        if top_kind != "practice":
            continue
        self._walk_practice_leaves(child)

def _walk_rule_tree(self, root: Path, found: dict[str, str]) -> None:
    if not root.is_dir():
        return
    for child in root.iterdir():
        if child.suffix == ".mdc":
            found.setdefault(child.stem.replace("_", "-"), "guideline")
            continue
        if not child.is_dir():
            continue
        found.setdefault(child.name.replace("_", "-"), "guideline")
        for leaf in child.glob("*.mdc"):
            found.setdefault(
                f"{child.name}-{leaf.stem}".replace("_", "-"),
                "guideline",
            )

def _detected(self, hook_payload: dict, toolsets: list | None) -> tuple[str, str] | None:
    if toolsets is not None:
        marked = self.detect_echo(hook_payload, toolsets=toolsets)
        if marked:
            return marked
    return self.detect(hook_payload)

def _log_echo(self) -> None:
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    sys.stderr.write(
        f"{stamp} [prompt-echo] tool={self.tool_name} {self.echo_kind}={self.echo_label}\n"
    )

def _mcp_tool_name(self, hook_payload: dict) -> str:
    name = str(hook_payload.get("tool_name") or "")
    raw = hook_payload.get("tool_input")
    inp = raw if isinstance(raw, dict) else {}
    nested = inp.get("toolName") or inp.get("tool_name") or inp.get("name")
    if isinstance(nested, str) and nested.strip():
        if "mcp" in name.lower() or name in {"CallMcpTool", "call_mcp_tool"}:
            return nested.strip()
        if "." in nested or "-" in nested:
            return nested.strip()
    return name

def _walk_toolsets(self, toolsets: list) -> list:
    found: list = []
    for toolset in toolsets:
        found.append(toolset)
        for child in getattr(toolset, "child_toolsets", lambda: ())():
            found.append(child)
    return found

def _echo_on_toolset(self, invoked: str, toolset) -> tuple[str, str] | None:
    tools = getattr(toolset, "tools", None) or {}
    if not isinstance(tools, dict):
        return None
    match = next(
        (tool for tool in tools.values() if self._name_matches(invoked, tool)),
        None,
    )
    if match is None:
        return None
    if self._has_echo(match.callable):
        return self._echo_kind_label(match)
    if match.name == "instructions" and self._inherited_echo(toolset, "instructions"):
        return self._echo_kind_label(match)
    self._begin_tools = tools
    self._begin_toolset = toolset
    return self._begin_echo(match)

def _yaml_action(self, hook_payload: dict) -> str | None:
    for text in self._paths(hook_payload):
        match = _YAML_ACTION.search(text)
        if match:
            return match.group(1).replace("_", "-")
    return None

def _catalog_match(
    self, haystacks: list[str], action_names: set[str]
) -> tuple[str, str] | None:
    for hay in haystacks:
        for token, kind in self.catalog:
            if not self._token_in(hay, token):
                continue
            if kind == "action" and hay not in action_names:
                continue
            if "/rules/" in hay.replace("\\", "/").lower():
                return "guideline", token
            return kind, token
    return None

def _burst_message(self) -> str:
    dest = self._toast_dest
    echo = self.echo
    stamp = self.toast_stamp
    if dest is None or not dest.is_file():
        return echo
    previous = self._read_toast(dest)
    prev_msg = str(previous.get("message") or "")
    prev_at = self._parse_toast_time(str(previous.get("at") or ""))
    now = self._parse_toast_time(stamp)
    if not prev_msg or prev_at is None or now is None:
        return echo
    if abs((now - prev_at).total_seconds()) > _SAME_BURST_SECONDS:
        return echo
    return self._join_arrow_toasts(prev_msg, echo)

def _write_notice(self, dest: Path, notice: str) -> None:
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(notice, encoding="utf-8")

def _toast_destinations(self, primary: Path) -> list[Path]:
    seen = {primary.resolve()}
    extra: list[Path] = []
    for root in self.toast_roots or []:
        dest = Path(str(root)) / TOAST_NOTICE
        try:
            resolved = dest.resolve()
        except OSError:
            continue
        if resolved in seen:
            continue
        seen.add(resolved)
        extra.append(dest)
    return extra

def _name_matches(self, invoked: str, tool) -> bool:
    compact_invoked = self._compact(invoked)
    return any(self._compact(name) == compact_invoked for name in self._mcp_aliases(tool))

def _has_echo(self, operation) -> bool:
    target = operation.fget if isinstance(operation, property) else operation
    inner = getattr(target, "__func__", target)
    return bool(getattr(inner, "_echo", False) or getattr(target, "_echo", False))

def _inherited_echo(self, toolset, name: str) -> bool:
    for cls in type(toolset).mro():
        member = cls.__dict__.get(name)
        if member is None:
            continue
        target = member.fget if isinstance(member, property) else member
        if self._has_echo(target):
            return True
    return False

def _begin_echo(self, match) -> tuple[str, str] | None:
    begin = self._begin_tools.get("begin")
    if begin is None or match.name in _SKIP_BEGIN_FALLBACK:
        return None
    if not self._has_echo(begin.callable):
        return None
    return "action", str(getattr(self._begin_toolset, "slug", match.name)).replace("_", "-")

def _parse_toast_time(self, stamp: str) -> datetime | None:
    try:
        return datetime.strptime(stamp, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    except ValueError:
        return None

def _join_arrow_toasts(self, previous: str, incoming: str) -> str:
    if incoming in previous:
        return previous
    if _ARROW not in previous or _ARROW not in incoming:
        return f"{previous}; {incoming}"
    prev_src, prev_rest = previous.split(_ARROW, 1)
    inc_src, inc_rest = incoming.split(_ARROW, 1)
    if prev_src.strip() != inc_src.strip():
        return f"{previous}; {incoming}"
    names: list[str] = []
    for name in self._guidance_names_from_toast_rest(
        prev_rest
    ) + self._guidance_names_from_toast_rest(inc_rest):
        if name not in names:
            names.append(name)
    return f"{prev_src.strip()}{_ARROW}rules : {', '.join(names)}"

def _walk_practice_leaves(self, child: Path) -> None:
    found = self.skill_found
    for leaf in child.iterdir():
        if leaf.is_dir():
            found.setdefault(leaf.name.replace("_", "-"), "fidelity")

def _paths(self, hook_payload: dict) -> list[str]:
    raw = hook_payload.get("tool_input")
    inp = raw if isinstance(raw, dict) else {}
    found: list[str] = []
    for key in ("path", "file_path", "command"):
        value = inp.get(key)
        if isinstance(value, str) and value.strip():
            found.append(value)
    return found

def _guidance_names_from_toast_rest(self, rest: str) -> list[str]:
    text = rest.strip()
    lowered = text.lower()
    if lowered.startswith("rules :") or lowered.startswith("rules:"):
        text = text.split(":", 1)[1]
    names: list[str] = []
    for chunk in text.split(","):
        name = chunk.strip()
        if name.endswith(" rules"):
            name = name[: -len(" rules")].strip()
        if name and name not in names:
            names.append(name)
    return names

def __new__(cls, fn: Any = None, event: str | None = None):
    if isinstance(fn, str):
        event = fn
        fn = None
    if not event:
        raise ValueError(
            'Hook requires a Cursor event: @Hook("sessionStart") or @Hook(event="sessionStart")'
        )
    if event not in cls.EVENTS:
        raise ValueError(
            f"Unknown Cursor event {event!r}. Valid events: {sorted(cls.EVENTS)}"
        )
    inst = object.__new__(cls)
    inst.name = event
    if callable(fn):
        return inst.annotate(fn)
    return inst

def __init__(self, name: str, phase: str, display_text: str) -> None:
    self.name = name
    self.phase = phase
    self.display_text = display_text
    self._seen: Dict[Tuple[str, str], HelperMethod] = {}
    self._ordered: List[HelperMethod] = []

def __init__(self, host: str | None = None, port: int | None = None) -> None:
    self.host = host or self.HOST
    self.port = port

def _write_json(self, conn: socket.socket, payload: dict) -> None:
    raw = json.dumps(payload).encode("utf-8")
    conn.sendall(f"{len(raw)}\n".encode("ascii") + raw)

def live_address(self, path: Path) -> tuple[str, int, int | None] | None:
    if not path.is_file():
        return None
    try:
        state = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return None
    host = state.get("host") or self.HOST
    port = state.get("port")
    if not port:
        return None
    probe = HookDaemon(host, int(port))
    try:
        result = probe._rpc({"method": "ping"})
    except OSError:
        return None
    if not result.get("ok"):
        return None
    return host, int(port), state.get("pid")

def skip(self, tool: str, error: BaseException) -> None:
    skipped = (
        error
        if isinstance(error, HookIllegitimateHandler)
        else HookIllegitimateHandler(tool, str(error), error)
    )
    self.exceptions.append(skipped)
    logger.error(
        "hook standup exception: skipped %s: %s",
        skipped.tool,
        skipped.reason,
        exc_info=skipped.cause,
    )

def ensure(cls, repo: Path) -> HookServer:
    path = cls.state_path(repo)
    connected = cls._connect(repo, path)
    if connected is not None:
        return connected
    cls._spawn(repo, path)
    connected = cls(repo)._wait_until_connected(path)
    if connected is None:
        raise HookStandupFailed(
            "ensure", None, "hook server daemon did not become ready"
        )
    return connected

def _connect(cls, repo: Path, path: Path) -> HookServer | None:
    from harness.hooks.hook_daemon import HookDaemon

    address = HookDaemon().live_address(path)
    if address is None:
        return None
    host, port, _pid = address
    return cls(repo, host=host, port=port)

def _spawn(cls, repo: Path, path: Path) -> None:
    from harness.hooks.hook_daemon import HookDaemon

    HookDaemon().spawn(repo, path)

def handle_stdin(self, raw: bytes) -> HookResult:
    if self._port is not None:
        from harness.hooks.hook_daemon import HookDaemon

        return HookResult.from_handler(
            HookDaemon(self._host or "127.0.0.1", self._port).call_handle_stdin(raw)
        )
    from harness.hooks.session_logs import SessionLogs

    SessionLogs(self._repo_root).ensure_default_session()
    if not raw.strip():
        return HookResult()
    try:
        payload = HookPayload.from_stdin(raw)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return HookResult()
    result = self.dispatch(payload)
    self._publish_context(result)
    self._write_last_chat_injected(result)
    if payload.hook_event_name == "stop":
        followup = self._consume_followup()
        if followup:
            result.followup_message = followup
    return result

def from_toolsets(
    cls, repo_root: Path, toolsets: list[Any] | None = None
) -> HookServer:
    return cls(repo_root, HandlerCatalog(toolsets, repo_root))

def _absorb_catalog_failures(self) -> None:
    if self._catalog is None:
        return
    for tool, error in self._catalog.failures:
        self.skip(tool, error)
    self._catalog.failures.clear()

def _wait_until_connected(self, path: Path) -> HookServer | None:
    attempts = int(_READY_WAIT_SECONDS / _READY_POLL_SECONDS)
    for _ in range(attempts):
        connected = type(self)._connect(self._repo_root, path)
        if connected is not None:
            return connected
        time.sleep(_READY_POLL_SECONDS)
    return None

def dispatch(self, payload: HookPayload) -> HookResult:
    self._payload = payload
    self._injected = {"practices": [], "fidelities": []}
    event = CursorEvent(payload.hook_event_name)
    fields = payload.as_dict()
    raw = fields.get("tool_input") or {}
    path = ""
    if isinstance(raw, dict):
        path = str(raw.get("path") or raw.get("file_path") or "")
    self._append_debug(
        f"EVENT {event.name!r} tool={fields.get('tool_name')!r} path={path!r} "
        f"conversation_id={payload.conversation_id!r} "
        f"payload_keys={sorted(fields.keys())}"
    )
    if not event.name:
        self._append_debug("NO_EVENT merged={}")
        return HookResult()
    results = self._invoke_enabled(event, payload)
    merged = HookResult()
    for item in results:
        merged = merged.merge(item)
    merged = self._merge_work_session(merged)
    self._append_debug(f"MERGED {json.dumps(merged.as_dict())}")
    return merged

def _record_injected(self, handler: HookHandler, result: HookResult) -> None:
    if not result.additional_context or self._payload is None:
        return
    practice, fidelities = self._injected_tags(handler, self._payload)
    if practice and practice not in self._injected["practices"]:
        self._injected["practices"].append(practice)
    for name in fidelities:
        if name not in self._injected["fidelities"]:
            self._injected["fidelities"].append(name)

def _consume_followup(self) -> str | None:
    dest = self._inject_path()
    if not dest.is_file():
        return None
    body = dest.read_text(encoding="utf-8")
    if self._already_sent(dest, body):
        return None
    self._mark_sent(dest, body)
    return "Injected rules for the edit you just made. Honor them on the next change.\n\n" + body

def _tool_path(self, payload: HookPayload) -> str:
    raw = payload.as_dict().get("tool_input") or {}
    if not isinstance(raw, dict):
        return ""
    return str(raw.get("path") or raw.get("file_path") or "")

def _bag_fidelity(self, bag: Any) -> str | None:
    parent = getattr(bag, "parent", None)
    if parent is None or getattr(parent, "fidelities", None) is not None:
        return None
    return getattr(parent, "name", None) or getattr(parent, "fidelity", None)

def _work_session_rules(self) -> Any:
    from types import SimpleNamespace

    from harness.hooks.session_logs import SessionLogs
    from workspace.workspace import WorkSessionRulesCollection

    logs = SessionLogs(self._repo_root)
    path = logs.session_folder(logs.active_session_name()) / "work-guidelines.md"
    if not path.is_file():
        return None
    return WorkSessionRulesCollection.from_markdown(
        path.read_text(encoding="utf-8"),
        parent=SimpleNamespace(path=path),
    )

def _event_names(self) -> list[str]:
    if self._catalog is None:
        return []
    names: list[str] = []
    for toolset in self._catalog.toolsets:
        try:
            tools = toolset.tools_for(InstallDestination.HOOK)
        except Exception as error:
            self.skip(self._catalog.ref_label(toolset), error)
            continue
        for tool in tools:
            event = getattr(tool.callable, "_hook_name", None)
            if event and event not in names:
                names.append(str(event))
    return names

def notify_exceptions(self) -> None:
    text = self.notice()
    if text:
        print(text, file=sys.stderr)

def standup(self) -> HookServer:
    self.notify_exceptions()
    return self

def from_stdin(cls, raw: bytes) -> HookPayload:
    text = raw.decode("utf-8-sig")
    while text.startswith("\ufeff"):
        text = text[1:]
    return cls(json.loads(text))

def as_dict(self) -> dict[str, Any]:
    payload: dict[str, Any] = {"permission": self.permission}
    if self.continue_flag is False:
        payload["continue"] = False
    if self.user_message:
        payload["user_message"] = self.user_message
    if self.agent_message:
        payload["agent_message"] = self.agent_message
    if self.followup_message:
        payload["followup_message"] = self.followup_message
    if self.additional_context:
        payload["additional_context"] = self.additional_context
    return payload

def _optional_text(self, value: Any) -> str | None:
    if not value:
        return None
    return str(value)

def from_handler(cls, raw: dict[str, Any] | None) -> HookResult:
    if not raw:
        return cls()
    continue_flag = False if raw.get("continue") is False else None
    return cls(
        permission=str(raw.get("permission") or "allow"),
        continue_flag=continue_flag,
        user_message=raw.get("user_message"),
        agent_message=raw.get("agent_message"),
        followup_message=raw.get("followup_message"),
        additional_context=raw.get("additional_context"),
    )

def with_description(self, description: str) -> HookResult:
    text = description.strip()
    if not text:
        return self
    existing = (self.agent_message or "").strip()
    if existing == text:
        return self
    if existing:
        text = f"{text}\n{existing}"
    return HookResult(
        self.permission,
        self.continue_flag,
        self.user_message,
        text,
        self.followup_message,
        self.additional_context,
    )

def invoke(self, payload: HookPayload) -> HookResult:
    toolset = self.tool.toolset
    operation = self._bound_operation(toolset)
    raw = operation(payload.as_dict())
    result = HookResult.from_handler(raw)
    if result.additional_context or not raw:
        return result
    return result.with_description(self.tool.docstring)

def _bound_operation(self, toolset: Any) -> Any:
    own = getattr(type(toolset), self.operation, None)
    if callable(own) and getattr(own, "_hook", False):
        bound_own = getattr(toolset, self.operation, None)
        if bound_own is not None:
            return bound_own
    if self.operation == "inject_rules":
        rules = getattr(toolset, "rules", None)
        bound = getattr(rules, "inject_rules", None) if rules is not None else None
        if bound is not None:
            return bound
    return getattr(toolset, self.operation, None) or self.tool.callable

def _load_items(self, items: list[Any]) -> None:
    for item in items:
        try:
            loaded = AgentToolSet.from_items([item])
        except Exception as error:
            self.failures.append((self.ref_label(item), error))
            continue
        self._append_loaded(loaded)

def _source_items(
    self, toolsets: list[Any] | None, handlers: Path | str | None
) -> list[Any]:
    if handlers is not None:
        return list(self.refs_from_handlers(handlers))
    if toolsets is None:
        return self._refs_from_file() or self._collect_refs()
    return list(toolsets)

def refs_from_handlers(self, handlers: Path | str) -> tuple[str, ...]:
    path = Path(handlers)
    if not path.is_file():
        return ()
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return ()
    refs: list[str] = []
    for item in payload.get("handlers") or []:
        ref = item.get("ref")
        if ref and str(ref) not in refs:
            refs.append(str(ref))
    return tuple(refs)

def _collect_refs(self) -> list[str]:
    from installation.installer import Installer

    return list(Installer(repo=self.repo_root).collect_toolsets())

def ref_label(self, item: Any) -> str:
    if isinstance(item, str):
        return item
    if isinstance(item, dict):
        return str(item.get("toolset") or item)
    registration = getattr(item, "registration_name", None)
    if isinstance(registration, str) and registration:
        return registration
    typ = item if isinstance(item, type) else type(item)
    return f"{typ.__module__}:{typ.__name__}"

def _append_loaded(self, loaded: list[Any]) -> None:
    for instance in loaded:
        if type(instance).__name__ in {"RulesCollection", "FidelityGuidance"}:
            continue
        self.toolsets.append(instance)

def for_event(self, event: CursorEvent) -> list[HookHandler]:
    handlers: list[HookHandler] = []
    seen: set[tuple[str, str]] = set()
    repo_root = self.repo_root or Path()
    for toolset in self.toolsets:
        try:
            tools = toolset.tools_for(InstallDestination.HOOK)
        except Exception as error:
            self.failures.append((self.ref_label(toolset), error))
            continue
        for tool in tools:
            if getattr(tool.callable, "_hook_name", None) != event.name:
                continue
            key = (type(toolset).__name__, tool.name)
            if key in seen:
                continue
            seen.add(key)
            handlers.append(HookHandler(tool, event, repo_root))
    return handlers

def active_session_name(self) -> str:
    for rel in (self.ACTIVE, self.LEGACY_ACTIVE):
        path = self.repo_root / rel
        if path.is_file():
            text = path.read_text(encoding="utf-8").strip()
            if text:
                return text
    return self.DEFAULT_SESSION

def clear_active_session(self) -> None:
    path = self.repo_root / self.ACTIVE
    if path.is_file():
        path.unlink()

def _move_default_logs_into(self, dest_logs: Path) -> None:
    default_logs = self.logs_dir_for(self.DEFAULT_SESSION)
    if not default_logs.is_dir() or default_logs == dest_logs:
        return
    for item in list(default_logs.iterdir()):
        if item.is_file():
            self._move_log_into(item, dest_logs)
    if default_logs.is_dir() and not any(default_logs.iterdir()):
        default_logs.rmdir()

def _move_log_into(self, file_path: Path, dest_logs: Path) -> None:
    if not file_path.is_file():
        return
    target = dest_logs / file_path.name
    if target.exists():
        target.unlink()
    try:
        shutil.move(str(file_path), str(target))
    except OSError:
        shutil.copy2(str(file_path), str(target))
        file_path.unlink(missing_ok=True)

def __new__(cls, target: Any = None, *, disabled: bool = False):
    inst = object.__new__(cls)
    inst.disabled = disabled
    if isinstance(target, type):
        return inst.annotate(target)
    return inst

def annotate(self, cls: type) -> type:
    cls._hooks_disabled = self.disabled
    return cls

def write(self, tool: Any) -> None:
    if not tool.install_to_hook:
        return
    if self._omit_inject_rules(tool):
        return
    event = getattr(tool.callable, "_hook_name", None)
    if not event:
        return
    record = {
        "event": str(event),
        "operation": tool.name,
        "ref": tool.registration_name,
    }
    if record in self._handlers:
        return
    self._handlers.append(record)
    self.write_hooks_manifest()
    self.write_handlers()

def _omit_inject_rules(self, tool: Any) -> bool:
    if tool.name != "inject_rules":
        return False
    host = type(getattr(tool, "toolset", None)).__name__
    if host in {"RulesCollection", "FidelityGuidance"}:
        return True
    bound = getattr(getattr(tool, "callable", None), "__self__", None)
    parent = getattr(bound, "parent", None)
    return type(parent).__name__ == "FidelityGuidance"

def write_handlers(self) -> None:
    if not self._handlers:
        return
    dest = self.path / "hook-handlers.json"
    dest.write_text(
        json.dumps({"handlers": self._handlers}, indent=2) + "\n",
        encoding="utf-8",
    )
    self.track_write(dest)

def _existing_hooks(self, dest: Path) -> dict[str, list[dict[str, Any]]]:
    if not dest.is_file():
        return {}
    try:
        existing = json.loads(dest.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return dict(existing.get("hooks") or {})

def _strip_dispatch_command(self, hooks: dict[str, list[dict[str, Any]]]) -> None:
    dispatch_cmd = self.dispatch_command
    for event_name in list(hooks.keys()):
        kept = [item for item in hooks[event_name] if item.get("command") != dispatch_cmd]
        if kept:
            hooks[event_name] = kept
        else:
            del hooks[event_name]

def _attach_dispatch_command(self, hooks: dict[str, list[dict[str, Any]]]) -> None:
    hook_def: dict[str, Any] = {
        "command": self.dispatch_command,
        "timeout": 30,
        "failClosed": False,
    }
    for event in sorted({item["event"] for item in self._handlers}):
        if event == "afterAgentResponse":
            hooks[event] = [dict(hook_def)]
            continue
        bucket = hooks.setdefault(event, [])
        if not any(item.get("command") == hook_def["command"] for item in bucket):
            bucket.append(dict(hook_def))

def parse(cls, content: str) -> UxMap:
    """Scaffold parse: if JSON embedded in a comment marker, reuse JsonUxMap."""
    marker = "<!-- ux-map-json:"
    if marker in content:
        start = content.index(marker) + len(marker)
        end = content.index("-->", start)
        return JsonUxMap.create().parse(content[start:end].strip())
    ux_map = cls.create()
    ux_map.context.notes.append("html parse stub - structural DOM parser later")
    return ux_map

def from_workspace(cls, root: Path) -> Optional[UxMap]:
    root = Path(root)
    preferred = [
        root / f"{root.name}.html",
        root / "index.html",
        root / "mockup.html",
        root / "ux.html",
    ]
    for candidate in preferred:
        if candidate.is_file():
            return cls.parse(candidate.read_text(encoding="utf-8"))
    html_files = sorted(p for p in root.glob("*.html") if p.is_file())
    if html_files:
        return cls.parse(html_files[0].read_text(encoding="utf-8"))
    return None

def write(self, tool: Any) -> None:
    if not tool.install_to_mcp:
        return
    self.record_operation(tool)
    self.write_mcp_manifest()

def bind(self, server: Any) -> None:
    self._bound = True
    for op in self.mcp_operations:
        server.enroll(op)

def record_operation(self, tool: Any) -> None:
    if not tool.install_to_mcp:
        return
    self.mcp_operations.append(McpOperationDefinition.from_tool(tool))

def write_mcp_manifest(self) -> None:
    if not self.mcp_operations:
        return
    from installation.installer import Installer

    repo = self.repo or Path(__file__).resolve().parents[2]
    host = repo / "harness" / "mcp" / "scripts" / "start_host.py"
    payload = {
        "mcpServers": {
            "cdd": {
                "type": "stdio",
                "command": sys.executable,
                "args": ["-u", str(host)],
                "env": {
                    "PYTHONPATH": Installer(repo=repo).pythonpath(),
                    "PYTHONIOENCODING": "utf-8",
                },
            }
        }
    }
    dest = self.path / "mcp.json"
    dest.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(payload, indent=2) + "\n"
    if dest.is_file() and dest.read_text(encoding="utf-8") == text:
        self.track_write(dest)
        return
    dest.write_text(text, encoding="utf-8")
    self.track_write(dest)

def start(
    self,
    toolset_refs: tuple[str, ...],
    *,
    constructor_context: dict[str, object] | None = None,
) -> None:
    context = dict(constructor_context or {})
    self.mcp_installations = []
    self._tools.clear()
    self._prompts.clear()
    self.exceptions = []
    for ref in toolset_refs:
        try:
            loaded = AgentToolSet.from_items([ref], context=context)
        except Exception as error:
            self.skip(str(ref), error)
            continue
        for toolset in loaded:
            try:
                self._enroll_toolset(toolset)
                for child in toolset.child_toolsets():
                    self._enroll_toolset(child)
            except Exception as error:
                self.skip(toolset.registration_name, error)
    self._started = True

def skip(self, tool: str, error: BaseException) -> None:
    skipped = (
        error
        if isinstance(error, McpIllegitimateTool)
        else McpIllegitimateTool(tool, str(error), error)
    )
    self.exceptions.append(skipped)
    logger.error(
        "MCP standup exception: skipped %s: %s",
        skipped.tool,
        skipped.reason,
        exc_info=skipped.cause,
    )

def bind_from(self, installation: McpInstallation) -> None:
    installation.bind(self)
    if installation not in self.mcp_installations:
        self.mcp_installations.append(installation)

def resolve_call_name(self, name: str) -> str:
    """Map Cursor's underscore tool id (`slug_op`) back to the enrolled `slug.op`."""
    if name in self._tools or name in self._prompts:
        return name
    as_dots = name.replace("_", ".")
    if as_dots in self._tools or as_dots in self._prompts:
        return as_dots
    if name == BUILTIN_PING_TOOL.replace(".", "_", 1):
        return BUILTIN_PING_TOOL
    for enrolled in (*self._tools, *self._prompts):
        if enrolled.replace(".", "_") == name or enrolled.replace(".", "_", 1) == name:
            return enrolled
    return name

def enroll(self, op: McpOperationDefinition) -> None:
    if not _is_legal_mcp_name(op.mcp_name):
        self.skip(
            op.mcp_name,
            McpIllegitimateTool(
                op.mcp_name,
                "illegal MCP tool name",
            ),
        )
        return
    if op.kind == "tool":
        self._tools[op.mcp_name] = McpTool(op)
    else:
        self._prompts[op.mcp_name] = McpPrompt(op)

def _apply_catalog_import_path(self) -> None:
    from installation.installer import Installer

    Installer(repo=self.repo).ensure_import_path()

def _enroll_toolset(self, toolset: Any) -> None:
    if getattr(toolset, "practice_guidance", "missing") is None:
        return
    installation = McpInstallation("Cursor", ".", toolset.registration_name)
    for tool in toolset.tools_for(InstallDestination.MCP):
        installation.record_operation(tool)
    installation.bind(self)
    self.mcp_installations.append(installation)

