def _check_server_repositories(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    server = self._server_file(domain_path)
    if server is None:
        return violations

    domain_name = domain_path.name
    content = server.read_text(encoding="utf-8", errors="replace")
    if "Repository" not in content:
        return violations

    parsed_root = self.parse_file(server)
    if parsed_root is None:
        if "implements" not in content:
            violations.append(
                self.v(
                    f"File '{server.name}' in {domain_name} has no "
                    "`implements` keyword. Repository classes must implement "
                    "the domain-core interface.",
                    str(server),
                )
            )
        return violations

    classes = self.classes
    for cls in classes:
        if "Repository" not in cls.name:
            continue
        if not cls.implements:
            violations.append(
                self.v(
                    f"Class '{cls.name}' in {domain_name}/server.ts does not "
                    "use the `implements` keyword. Without it TypeScript "
                    "won't catch missing interface methods at compile time.",
                    str(server),
                    cls.start_line,
                )
            )
            continue

        for line_num, line in enumerate(content.splitlines(), 1):
            if _NOT_IMPLEMENTED_RE.search(line):
                violations.append(
                    self.v(
                        "Stub method with 'not implemented' found in "
                        f"'{server.name}'. All interface methods must be "
                        "fully implemented - no throw stubs.",
                        str(server),
                        line_num,
                    )
                )

    return violations

def _check_service_depends_on_interface(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    server = self._server_file(domain_path)
    if server is None:
        return violations

    parsed_root = self.parse_file(server)
    if parsed_root is None:
        return violations

    classes = self.classes
    content = server.read_text(encoding="utf-8", errors="replace")
    lines = content.splitlines()
    for cls in classes:
        if "Server" not in cls.name and "Service" not in cls.name:
            continue
        ctor = next((m for m in cls.methods if m.name == "constructor"), None)
        if ctor is None:
            continue
        ctor_line = lines[ctor.start_line - 1] if ctor.start_line <= len(lines) else ""
        if re.search(r"Mongo\w+Repository\b", ctor_line):
            violations.append(
                self.v(
                    f"Class '{cls.name}' constructor injects a concrete "
                    "MongoDB repository class. Depend on the repository "
                    "INTERFACE instead so tests can inject a fake.",
                    str(server),
                    ctor.start_line,
                )
            )

    return violations

def _check_test_fake_repositories(self, project_root: Path) -> List[Violation]:
    violations: List[Violation] = []
    tests_dir = project_root / "tests"
    if not tests_dir.exists():
        return violations

    for ts_file in tests_dir.rglob("*.ts"):
        if "node_modules" in ts_file.parts:
            continue
        parsed_root = self.parse_file(ts_file)
        if parsed_root is None:
            continue

        for cls in self.classes:
            name_lower = cls.name.lower()
            if not any(kw in name_lower for kw in ("fake", "stub", "mock", "in_memory", "inmemory")):
                continue
            if not cls.implements:
                violations.append(
                    self.v(
                        f"Test class '{cls.name}' in {ts_file.name} looks like a "
                        "test double but doesn't use `implements`. TypeScript won't "
                        "catch if it diverges from the real interface.",
                        str(ts_file),
                        cls.start_line,
                    )
                )

    return violations

def _regex_check_implements(self, repo_file: Path, domain_name: str) -> List[Violation]:
    """Fallback regex check when tree-sitter is unavailable."""
    violations: List[Violation] = []
    content = repo_file.read_text(encoding="utf-8", errors="replace")
    if "implements" not in content:
        violations.append(
            self.v(
                f"File '{repo_file.name}' in {domain_name} has no "
                "`implements` keyword. Classes must implement repository interfaces.",
                str(repo_file),
            )
        )
    return violations

def _concrete_repository_injections(self, server: Path, parsed_root) -> List[Violation]:
    lines = server.read_text(encoding="utf-8", errors="replace").splitlines()
    violations: List[Violation] = []
    for cls in self.classes:
        if "Server" not in cls.name and "Service" not in cls.name:
            continue
        ctor = next((m for m in cls.methods if m.name == "constructor"), None)
        if ctor is None:
            continue
        ctor_line = lines[ctor.start_line - 1] if ctor.start_line <= len(lines) else ""
        if re.search(r"(?:Low(?:db)?|JSONFile)\w*Repository\b", ctor_line):
            violations.append(
                self.v(
                    f"Class '{cls.name}' constructor injects a concrete "
                    "lowdb repository class. Depend on the repository "
                    "INTERFACE instead so tests can inject a fake.",
                    str(server),
                    ctor.start_line,
                )
            )
    return violations

def _test_double_without_implements(self, ts_file: Path) -> List[Violation]:
    parsed_root = self.parse_file(ts_file)
    if parsed_root is None:
        return []
    violations: List[Violation] = []
    for cls in self.classes:
        name_lower = cls.name.lower()
        if not any(kw in name_lower for kw in ("fake", "stub", "mock", "in_memory", "inmemory")):
            continue
        if cls.implements:
            continue
        violations.append(
            self.v(
                f"Test class '{cls.name}' in {ts_file.name} looks like a "
                "test double but doesn't use `implements`. TypeScript won't "
                "catch if it diverges from the real interface.",
                str(ts_file),
                cls.start_line,
            )
        )
    return violations

def render(
    self, canonical: StoryMap, previous: Optional[Dict[str, str]] = None
) -> Dict[str, str]:
    tree = render_java_tree(canonical, tests_root=self.tests_root)
    if previous:
        for path, body in list(tree.items()):
            if path in previous and path.endswith(self.LEAF_EXTENSION):
                tree[path] = self._preserve_hand_written(previous[path], body)
    return tree

def parse(self, external: Dict[str, str]) -> StoryMap:
    if not isinstance(external, dict):
        raise CodeStoryMapError("Java story map parse expects a path->content dict")
    story_map = self._make_story_map()
    for path, content in sorted(external.items()):
        if not path.endswith(self.LEAF_EXTENSION) or path.endswith("Helper.java"):
            continue
        if "Spec" in path.split("/")[-1]:
            continue
        parts = path.strip("/").split("/")
        if parts and parts[0] == self.tests_root:
            parts = parts[1:]
        if len(parts) < 4:
            continue
        epic_slug, story_slug, sub_slugs = parts[0], parts[-2], parts[1:-2]
        if not sub_slugs:
            continue
        epic = self._ensure_epic(story_map, epic_slug)
        sub = self._ensure_sub_path(epic, sub_slugs)
        story = self._parse_story_file(content, story_slug)
        if story:
            sub.stories.append(story)
    return story_map

def from_workspace(cls, root: Path) -> List[TestSuite]:
    """Find and parse all Java test files under *root*."""
    root = Path(root).resolve()
    if root.is_file():
        if root.suffix == ".java":
            return [cls._parse_file(root, root.parent)]
        return []
    seen: set = set()
    suites: List[TestSuite] = []
    for pattern in _GLOBS:
        for p in root.glob(pattern):
            if p in seen or not p.is_file():
                continue
            seen.add(p)
            suites.append(cls._parse_file(p, root))
    return suites

def leaf_files_of(self, tree: Dict[str, str]) -> List[str]:
    return sorted(
        p
        for p in tree
        if p.endswith(self.LEAF_EXTENSION) and not p.endswith("Helper.java")
    )

def _ensure_epic(self, story_map: StoryMap, epic_slug: str) -> Epic:
    for epic in story_map.epics:
        if to_kebab(epic.name) == epic_slug:
            return epic
    epic = self._make_epic(epic_slug.replace("-", " ").title(), len(story_map.epics) + 1)
    story_map.append_epic(epic)
    return epic

def render(
    self,
    canonical: StoryMap,
    previous: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    tree = JavaScriptTree().render(canonical, self.tests_root)
    if previous:
        for path, body in list(tree.items()):
            if path in previous and path.endswith(self.LEAF_EXTENSION):
                tree[path] = self._preserve_hand_written(previous[path], body)
    return tree

def parse(self, external: Dict[str, str]) -> StoryMap:
    if not isinstance(external, dict):
        raise CodeStoryMapError("JavaScript story map parse expects a path->content dict")
    story_map = self._make_story_map()
    # Group *_story.js by epic / sub-epic / story folder
    for path, content in sorted(external.items()):
        if not path.endswith(self.LEAF_EXTENSION):
            continue
        parts = path.strip("/").split("/")
        # tests/epic/sub/story/name_story.js  -> need >= 5 parts with tests root
        if len(parts) < 4:
            continue
        # Drop tests_root if present
        if parts[0] == self.tests_root:
            parts = parts[1:]
        # epic / ...subs... / story-folder / file
        if len(parts) < 4:
            continue
        epic_slug = parts[0]
        story_slug = parts[-2]
        sub_slugs = parts[1:-2]
        if not sub_slugs:
            continue

        epic = self._ensure_epic(story_map, epic_slug)
        sub = self._ensure_sub_path(epic, sub_slugs)
        story = self._parse_story_file(content, story_slug)
        if story is not None:
            sub.stories.append(story)
    return story_map

def from_workspace(cls, root: Path) -> List[TestSuite]:
    """Find and parse all JavaScript test files under *root*."""
    root = Path(root).resolve()
    if root.is_file():
        if root.suffix in (".js", ".jsx"):
            return [cls._parse_file(root, root.parent)]
        return []
    seen: set = set()
    suites: List[TestSuite] = []
    for pattern in _GLOBS:
        for p in root.glob(pattern):
            if p in seen or not p.is_file():
                continue
            seen.add(p)
            suites.append(cls._parse_file(p, root))
    return suites

def leaf_files_of(self, tree: Dict[str, str]) -> List[str]:
    return sorted(
        p for p in tree if p.endswith(self.LEAF_EXTENSION) and "/story-test.js" not in p
    )

