        ScannerCollection,
    )

    folder = self.install_folder
    return ScannerCollection(module_dir=folder, root_path=folder / "scanners")

def missing_hit(self, row: dict) -> dict | None:
    if self.py_file.suffix.lower() != ".py" or self.exists():
        return None
    return _hit(
        row,
        f"Module folder '{self.folder.name}' defines classes but has no "
        f".context/module-context.md. "
        f"Add one with at minimum: Purpose, Seam, Dependencies.",
    )

def modules_heading_hit(self, row: dict) -> dict | None:
    if not self.exists() or not _MODULES_HEADING.search(self.read()):
        return None
    return _hit(
        row,
        f"Module '{self.path.parent.parent.name}' module-context has a "
        f"'Modules' heading. Language and modules are one ## Language "
        f"section — drop ## Modules.",
    )

def public_seam_hits(self, row: dict) -> List[dict]:
    if not self.exists():
        return []
    hits: List[dict] = []
    content = self.read()
    folder = self.path.parent.parent.name
    for line in content.splitlines():
        match = _HEADING.match(line)
        if not match:
            continue
        heading = match.group(1).strip()
        key_heading = heading.lower()
        if key_heading in _FORBIDDEN_HEADINGS or "internal" in key_heading:
            hits.append(
                _hit(
                    row,
                    f"Module '{folder}' module-context heading '{heading}' is "
                    f"not part of the public seam.",
                )
            )
    for match in _PRIVATE_NAME.finditer(content):
        hits.append(
            _hit(
                row,
                f"Module '{folder}' module-context names private '{match.group(1)}'.",
            )
        )
    return hits

def model_block_hits(self, row: dict) -> List[dict]:
    if not self.exists():
        return []
    hits: List[dict] = []
    content = self.read()
    folder = self.path.parent.parent.name
    for pattern, detail in (
        (_SIX_DASHES, "typed `------` member dump"),
        (_SOURCES, "**Sources / context** that lists this folder's own files"),
        (_LIVE_INSTANCE, "'Live instance:' name inventory"),
    ):
        if pattern.search(content):
            hits.append(_hit(row, f"Module '{folder}' module-context has {detail}"))
    return hits

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []

    for domain_path in self._find_domain_packages(root):
        violations += self._check_server_routes(domain_path)
        violations += self._check_http_client(domain_path)

    return violations

def _check_server_routes(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    server = self._server_file(domain_path)
    if server is None:
        return violations

    content = self._read_file_content(server)
    if content is None:
        return violations

    for m in _RES_JSON_RE.finditer(content):
        response_arg = m.group(1)
        if _SUCCESS_PATTERN_RE.match(response_arg):
            line_num = content[: m.start()].count("\n") + 1
            violations.append(
                self.v(
                    "Route returns { success/message/ok } instead of "
                    "an aggregate snapshot. All mutations must return the "
                    "same snapshot type.",
                    str(server),
                    line_num,
                    severity="error",
                )
            )

    return violations

def _check_http_client(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    client = self._client_file(domain_path)
    if client is None:
        return violations

    content = self._read_file_content(client)
    if content is None:
        return violations

    return_types: Set[str] = set()
    for m in _RETURN_TYPE_RE.finditer(content):
        return_types.add(m.group(1))

    mutation_types = {t for t in return_types if t != "void"}
    if len(mutation_types) > 1:
        violations.append(
            self.v(
                f"HTTP client in {client.name} returns multiple different "
                f"types from mutations: {sorted(mutation_types)}. All "
                "mutations on the same aggregate should return the same "
                "snapshot type.",
                str(client),
                severity="warning",
            )
        )

    return violations

def _success_envelope_hits(self, server: Path, content: str) -> List[Violation]:
    violations: List[Violation] = []
    for match in _RES_JSON_RE.finditer(content):
        if not _SUCCESS_PATTERN_RE.match(match.group(1)):
            continue
        violations.append(
            self.v(
                "Route returns { success/message/ok } instead of "
                "an aggregate snapshot. All mutations must return the "
                "same snapshot type.",
                str(server),
                content[: match.start()].count("\n") + 1,
                severity="error",
            )
        )
    return violations

def unimplemented_python(self, text: str) -> List[str]:
    found: List[str] = []
    for pattern in (_PY_STEP_DEF, _PY_STEP_DEF_PRIVATE):
        for m in pattern.finditer(text):
            body_no_doc = "\n".join(
                line for line in (m.group("body") or "").splitlines()
                if not re.match(r'^\s*(?:"""|\'\'\')', line)
            )
            if self.is_stub(body_no_doc):
                found.append(m.group("name"))
    return found

def _code_lines(self, body: str) -> List[str]:
    stripped_lines: List[str] = []
    for raw in body.splitlines():
        line = raw.strip()
        if not line or self._is_comment(line):
            continue
        stripped_lines.append(line)
    return stripped_lines

def _is_comment(self, line: str) -> bool:
    if line.startswith("//") or line.startswith("#"):
        return True
    if line.startswith("/*") or line.startswith("*") or line.startswith("*/"):
        return True
    return bool(re.match(r'^(?:"""|\'\'\')', line))

def _is_empty_stub(self, joined: str) -> bool:
    if _TODO_MARKERS.search(joined):
        return True
    if re.search(r"raise\s+NotImplementedError\b", joined):
        return True
    if re.search(r"throw\s+new\s+Error\s*\(\s*['\"`]not implemented", joined, re.IGNORECASE):
        return True
    return joined in ("pass", "pass;", "{}", "return;", "return null;", "return;")

def is_stub(self, body: str) -> bool:
    stripped_lines = self._code_lines(body)
    if not stripped_lines:
        return True
    return self._is_empty_stub("\n".join(stripped_lines))

def parse(cls, text: str, rel_file: str, line_offset: int = 0) -> List["MarkdownIncrement"]:
    """Parse a thin-slicing.md body into a list of MarkdownIncrement nodes."""
    increments: List[MarkdownIncrement] = []
    current: Optional[MarkdownIncrement] = None
    in_stories = False

    for idx, raw in enumerate(text.splitlines(), start=1 + line_offset):
        stripped = raw.strip()
        if not stripped:
            continue
        m_inc = _INCREMENT_H3.match(stripped)
        if m_inc:
            if current is not None:
                increments.append(current)
            current = cls(MarkdownScenario()._strip_markup(m_inc.group(1)), len(increments) + 1)
            current.source = SourceLocation(rel_file, idx)
            in_stories = False
            continue
        if current is None:
            continue
        markup = MarkdownScenario()
        if m := _KV_OUTCOME.match(stripped):
            current.outcome = markup._strip_markup(m.group(1))
            in_stories = False
        elif m := _KV_SLICING.match(stripped):
            current.slicing_notes = markup._strip_markup(m.group(1))
            in_stories = False
        elif m := _KV_DECISION.match(stripped):
            current.decision_prompt = markup._strip_markup(m.group(1))
            in_stories = False
        elif _KV_STORIES.match(stripped):
            in_stories = True
        elif _ANY_H2.match(raw) or _INCREMENT_H3.match(raw):
            in_stories = False
        elif in_stories:
            if m := _BULLET.match(raw):
                current.stories.append(markup._strip_markup(m.group(1)))
            else:
                in_stories = False

    if current is not None:
        increments.append(current)
    return increments

def accept(self, keyword: str, text: str) -> None:
    kw = keyword.lower()
    if kw == "given":
        self._parser.begin_clause(False, "Given")
        self._scenario.given.append(self._make_clause(text, Phase.GIVEN))
        self._active_phase = Phase.GIVEN
        self._active_interaction = None
        return
    if kw == "when":
        self._start_when(text)
        return
    if kw == "then":
        self._append_then(text)
        return
    if kw in ("and", "but"):
        self._accept_continuation(kw, text)

def _accept_continuation(self, kw: str, text: str) -> None:
    keyword = kw.capitalize()
    prefixed = f"{keyword} {text}"
    self._parser.begin_clause(True, keyword)
    if self._active_phase is Phase.GIVEN:
        self._scenario.given.append(self._make_clause(prefixed, Phase.GIVEN))
        return
    if self._active_phase is Phase.WHEN and self._active_interaction:
        self._active_interaction.when.append(self._make_clause(prefixed, Phase.WHEN))
        return
    if self._active_phase is Phase.THEN and self._active_interaction:
        self._active_interaction.then.append(self._make_clause(prefixed, Phase.THEN))

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []
    path_owners: Dict[str, List[str]] = {}

    for domain_path in self._find_domain_packages(root):
        server = self._server_file(domain_path)
        if server is None:
            continue
        content = self._read_file_content(server)
        if content is None:
            continue
        domain_name = domain_path.name
        violations += self._check_shared_filenames(server, content)
        violations += self._check_default_data_shape(server, content)
        for match in _PRESET_PATH_RE.finditer(content):
            store_path = match.group(1).replace("\\", "/")
            path_owners.setdefault(store_path, []).append(domain_name)
            if not self._path_names_aggregate(store_path, domain_name):
                violations.append(
                    self.v(
                        f"Repository in '{domain_name}' opens '{store_path}', "
                        "which does not include this aggregate's name. "
                        "Use data/<aggregate>.json owned by this root only.",
                        str(server),
                        content[: match.start()].count("\n") + 1,
                    )
                )

    for store_path, owners in path_owners.items():
        unique = sorted(set(owners))
        if len(unique) > 1:
            violations.append(
                self.v(
                    f"JSON store '{store_path}' is opened by multiple aggregates "
                    f"({', '.join(unique)}). Each aggregate root owns its own file.",
                    store_path,
                )
            )
    return violations

def _check_shared_filenames(self, server: Path, content: str) -> List[Violation]:
    violations: List[Violation] = []
    lower = content.lower()
    for name in _SHARED_STORE_NAMES:
        if name in lower:
            line = next(
                (i for i, row in enumerate(content.splitlines(), 1) if name in row.lower()),
                1,
            )
            violations.append(
                self.v(
                    f"Shared JSON database filename '{name}' found. "
                    "Give each aggregate its own data/<aggregate>.json file.",
                    str(server),
                    line,
                )
            )
    return violations

def _check_default_data_shape(self, server: Path, content: str) -> List[Violation]:
    violations: List[Violation] = []
    for match in _DEFAULT_DATA_RE.finditer(content):
        keys = _ARRAY_KEY_RE.findall(match.group(1))
        if len(keys) > 1:
            line = content[: match.start()].count("\n") + 1
            violations.append(
                self.v(
                    f"lowdb default data has {len(keys)} collections "
                    f"({', '.join(keys)}). One JSON store holds one aggregate.",
                    str(server),
                    line,
                )
            )
    return violations

def _check_import_paths(self, project_root: Path, declared_names: Set[str]) -> List[Violation]:
    if not declared_names:
        return []
    declared = _DeclaredPackages(
        names=declared_names,
        scopes={name.split("/")[0] for name in declared_names if name.startswith("@")},
    )
    violations: List[Violation] = []
    for ts_file in self._scoped_search_files(project_root):
        violations.extend(self._undeclared_scoped_imports(ts_file, declared))
    return violations

def _scoped_search_files(self, project_root: Path) -> List[Path]:
    files: List[Path] = []
    for folder in (project_root / "packages", project_root / "tests"):
        if folder.exists():
            files.extend(self.source_files(folder))
    return files

def _undeclared_scoped_imports(
    self, ts_file: Path, declared: _DeclaredPackages
) -> List[Violation]:
    parsed_root = self.parse_file(ts_file)
    if parsed_root is None:
        return []
    violations: List[Violation] = []
    for imp in self.imports:
        hit = self._scoped_import_hit(
            _ImportSite(ts_file, imp.source, imp.start_line), declared
        )
        if hit is not None:
            violations.append(hit)
    return violations

def _scoped_import_hit(self, site: _ImportSite, declared: _DeclaredPackages):
    message = declared.scoped_issue(site.source)
    if message is None:
        return None
    return self.v(message, str(site.path), site.start_line)

def scoped_issue(self, source: str) -> Optional[str]:
    if not source.startswith("@"):
        return None
    if source.count("/") > 1:
        return self._multi_slash_issue(source)
    if source.split("/")[0] not in self.scopes or source in self.names:
        return None
    declared = ", ".join(sorted(self.names))
    return (
        f"Import '{source}' references an undeclared package "
        f"(not found in any package.json). Declared packages: {declared}."
    )

def _multi_slash_issue(self, source: str) -> Optional[str]:
    if source in self.names:
        return None
    return (
        f"Import path '{source}' contains multiple slashes - "
        "this is not a valid npm package name. "
        "Use the flat @scope/domain-tier package name, "
        "or declare sub-path exports in package.json."
    )

def delete(self, turn: Turn) -> None:
    turns = self._plan._turns
    if turn in turns:
        turns.remove(turn)

def edit(self, turn: Turn, **fields: Any) -> Turn:
    for field_name, field_value in fields.items():
        setattr(turn, field_name, field_value)
    return turn

def render(self, story_map: StoryMap, tests_root: str = "tests") -> Dict[str, str]:
    tree: Dict[str, str] = {}
    self._tree = tree
    self._root = tests_root.strip("/") or "tests"
    for epic in getattr(story_map, "epics", []) or []:
        self._render_epic(epic)
    return tree

def _render_epic(self, epic: Epic) -> None:
    epic_slug = to_kebab(epic.name)
    helper = self._render_epic_helper(epic)
    if helper is not None:
        self._tree[f"{self._root}/{epic_slug}/{to_snake(epic.name)}_helper.py"] = helper
    self._epic = epic
    for sub in getattr(epic, "sub_epics", []) or []:
        self._render_sub_epic(sub, f"{self._root}/{epic_slug}")

def _render_sub_epic(self, sub: SubEpic, parent: str) -> None:
    folder = f"{parent}/{to_kebab(sub.name)}"
    for nested in getattr(sub, "sub_epics", []) or []:
        self._render_sub_epic(nested, folder)
    for story in getattr(sub, "stories", []) or []:
        self._render_story(story, folder)

def _render_story(self, story: Story, parent: str) -> None:
    if not getattr(story, "scenarios", None):
        return
    story_folder = f"{parent}/{to_kebab(story.name)}"
    self._tree[f"{story_folder}/{to_snake(story.name)}_story.test.py"] = render_story_file(story)

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []
    for domain_path in self._find_domain_packages(root):
        core = self._domain_core_file(domain_path)
        if core is None:
            continue
        parsed = self.parse_file(core)
        if parsed is None:
            violations += self._regex_fallback(core, domain_path.name)
            continue
        repo_ifaces = [
            iface
            for iface in self.interfaces
            if iface.name.endswith("Repository")
        ]
        if not repo_ifaces:
            violations.append(
                self.v(
                    f"Domain '{domain_path.name}' core has no *Repository interface. "
                    "Compartment the aggregate behind a repository that load/create/"
                    "search/update the aggregate root.",
                    str(core),
                )
            )
            continue
        for iface in repo_ifaces:
            names = {n.lower() for n in iface.method_names}
            missing = [op for op in _REQUIRED if op not in names]
            if missing:
                violations.append(
                    self.v(
                        f"Interface '{iface.name}' is missing {', '.join(missing)}(). "
                        "A Repository returns the aggregate root via load, create, "
                        "search, and update.",
                        str(core),
                        iface.start_line,
                    )
                )
    return violations

def scan(self, root: Path, files: List[Path]) -> List[Violation]:
    violations: List[Violation] = []
    project_root = root

    for routes_file in project_root.rglob("*.routes.ts"):
        if "node_modules" in routes_file.parts or "examples" in routes_file.parts:
            continue
        violations.extend(self._check_file(routes_file, handlers_only=False))

    for router_file in project_root.rglob("*Router.ts"):
        if "node_modules" in router_file.parts or "examples" in router_file.parts:
            continue
        violations.extend(self._check_file(router_file, handlers_only=False))

    for server_file in project_root.rglob("*-server.ts"):
        if "node_modules" in server_file.parts or "examples" in server_file.parts:
            continue
        violations.extend(self._check_file(server_file, handlers_only=True))

    return violations

def _check_file(self, path: Path, *, handlers_only: bool) -> List[Violation]:
    content = self._read_file_content(path)
    if content is None:
        return []
    if handlers_only and not self.ROUTER_HANDLER.search(content):
        return []

    lines = content.splitlines()
    if handlers_only:
        ranges = self._handler_line_ranges(content)
        if not ranges:
            return []
        check_lines = [
            (i, lines[i - 1])
            for start, end in ranges
            for i in range(start, end + 1)
            if 1 <= i <= len(lines)
        ]
    else:
        check_lines = list(enumerate(lines, start=1))

    violations: List[Violation] = []
    for i, line in check_lines:
        stripped = line.strip()
        if stripped.startswith("//"):
            continue
        if self.REPO_CALL.search(line):
            violations.append(
                self.v(
                    "Route handler calls repository directly - delegate to "
                    "server-side domain class instead.",
                    str(path),
                    i,
                )
            )
        if self.SHARED_DOMAIN_IN_ROUTE.search(line):
            violations.append(
                self.v(
                    "Route handler applies shared domain logic inline - "
                    "move to server-side domain class.",
                    str(path),
                    i,
                )
            )
    return violations

def _handler_line_ranges(self, content: str) -> List[Tuple[int, int]]:
    """Return 1-based (start, end) line ranges for each router.* callback body."""
    ranges: List[Tuple[int, int]] = []
    for match in self.ROUTER_HANDLER.finditer(content):
        ranges.extend(self._callback_line_range(content, match.end()))
    return ranges

def _matching_brace_end(self, content: str, brace: int) -> int:
    depth = 0
    for index in range(brace, len(content)):
        depth = self._brace_depth_after(content[index], depth)
        if depth == 0:
            return index
    return brace

def _brace_depth_after(self, char: str, depth: int) -> int:
    if char == "{":
        return depth + 1
    if char == "}":
        return depth - 1
    return depth

def _check_no_duplicate_schemas(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    for tier, getter in (("server", self._server_file), ("client", self._client_file)):
        path = getter(domain_path)
        if path is None:
            continue
        content = path.read_text(encoding="utf-8", errors="replace")
        if _ZOD_OBJECT_RE.search(content):
            violations.append(
                self.v(
                    f"Zod schema definition found in '{domain_path.name}/{path.name}'. "
                    "Schemas must live exclusively in the domain core "
                    f"({domain_path.name}.ts) - import them instead of redefining.",
                    str(path),
                )
            )
    return violations

def _check_http_client_hydrates(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    client = self._client_file(domain_path)
    if client is None:
        return violations

    content = client.read_text(encoding="utf-8", errors="replace")
    has_fetch = "fetch(" in content or "axios." in content
    if not has_fetch:
        return violations

    has_hydration = bool(_HYDRATE_RE.search(content))
    suspicious_returns: list[int] = []
    for line_num, line in enumerate(content.splitlines(), 1):
        stripped = line.strip()
        if (
            re.search(r"return\s+(data|res|response|json)\.(items|data|results|records)\b", stripped)
            or re.search(r"return\s+(?:await\s+)?\w+\.json\s*\(\s*\)", stripped)
        ):
            suspicious_returns.append(line_num)

    if suspicious_returns and not has_hydration:
        violations.append(
            self.v(
                f"HTTP client in '{client.name}' returns raw JSON without "
                "hydrating into domain instances. Call toDomainEntity(raw) "
                "or new DomainClass(raw) — plain objects don't have domain "
                "methods and crash at runtime.",
                str(client),
                suspicious_returns[0],
            )
        )
    return violations

def _first_raw_json_return(self, content: str) -> int | None:
    for line_num, line in enumerate(content.splitlines(), 1):
        if _RAW_JSON_RETURN_RE.search(line.strip()):
            return line_num
    return None

def arg_after(self, args: list[str], flag: str) -> str:
    if flag not in args:
        return ""
    index = args.index(flag)
    if index + 1 >= len(args):
        return ""
    return str(args[index + 1])

def find_cdd_repo(self, start: Path | str | None = None) -> Path:
    """Workspace first, then this script's checkout. Worktrees must not pin __file__."""
    here = Path(start or os.getcwd()).resolve()
    for candidate in (here, *here.parents):
        if (candidate / "installation" / "installer.py").is_file():
            return candidate
    return self.FALLBACK_REPO

def scan_page(self, page_root) -> list:
    violations = []
    for cell in page_root.iter("mxCell"):
        if cell.get("vertex") != "1":
            continue
        raw = cell.get("value") or ""
        if not raw:
            continue
        text = self._unescape(html.unescape(raw))
        match = re.search(r"<b[^>]*>(.*?)</b>", text, re.IGNORECASE | re.DOTALL)
        if not match:
            continue
        title = match.group(1)
        if _STEREOTYPE.search(title):
            violations.append(
                self.violation(
                    f"[{self._scan_page_name}] Stereotype sits on the same line as the "
                    f"class name inside <b>: "
                    f"{re.sub(r'<[^>]+>', '', title)[:80]!r}",
                    location=str(self._scan_file_path),
                )
            )
    return violations

def _is_leaf_folder(self, folder: Path) -> bool:
    try:
        return not any(child.is_dir() for child in folder.iterdir())
    except OSError:
        return False

def from_node(cls, node: "StoryNode") -> "NodeSnapshot":
    return cls(
        node_id=id(node),
        name=node.name,
        sequential_order=node.sequential_order,
        extra_fields=node.snapshot_fields(),
        child_snapshots=[cls.from_node(child) for child in node.children()],
    )

def restore_into(self, node: "StoryNode") -> None:
    node.name = self.name
    node.sequential_order = self.sequential_order
    node.restore_snapshot_fields(self.extra_fields)
    children = node.children()
    for i, child_snapshot in enumerate(self.child_snapshots):
        if i < len(children):
            child_snapshot.restore_into(children[i])

def visit_With(self, node: ast.With) -> ast.AST:
    name = self._get_name(node)
    if name in self.STORY:
        return self._transform_story(node)
    if name in self.STRUCTURE or name in self.STEPS:
        return node
    node = super(StoryNodeTransformer, self).generic_visit(node)  # type: ignore[attr-defined]
    return super().visit_With(node)

def __init__(
    self, paths: list[str], node_transformer: StoryNodeTransformer
) -> None:
    super().__init__(paths)
    self._node_transformer = node_transformer

def _collect_files_containing_examples(self) -> list[str]:
    collected: list[str] = []
    for path in self.paths:
        if not os.path.exists(path):
            continue
        if os.path.isdir(path):
            collected.extend(self._collect_story_files_in_directory(path))
        elif self._is_story_file(path):
            collected.append(path)
    collected.sort()
    return collected

def _collect_story_files_in_directory(self, directory: str) -> list[str]:
    found: list[str] = []
    for root, _dirs, files in os.walk(directory):
        for name in files:
            if self._is_story_file(name):
                found.append(os.path.join(self._normalize_path(root), name))
    return found

def _is_story_file(self, path: str) -> bool:
    name = os.path.basename(path)
    if name.endswith("_story.test.py"):
        return True
    return any(path.endswith(suffix) for suffix in self.STORY_SUFFIXES)

def _render_sub_epic(self, sub: SubEpic) -> None:
    self._folder = self._path_join(self._folder, to_kebab(sub.name))
    self._ensure_fixtures(sub)
    folder = self._folder
    for nested in getattr(sub, "sub_epics", []) or []:
        self._folder = folder
        self._render_sub_epic(nested)
    for story in getattr(sub, "stories", []) or []:
        if not story.scenarios:
            continue
        self._folder = folder
        self._render_story(story)

def _extract_aggregate_noun(self, name: str) -> str:
    pascal = to_pascal(name)
    for verb in (
        "Create", "Get", "Manage", "Settle", "Enter", "Know", "Complete",
        "Query", "Submit", "View", "Store", "Update", "Delete", "Place",
    ):
        if pascal.startswith(verb) and len(pascal) > len(verb):
            pascal = pascal[len(verb):]
    return pascal

