def _check_client(self, domain_path: Path) -> List[Violation]:
    violations: List[Violation] = []
    client = self._client_file(domain_path)
    if client is None:
        return violations

    content = self._read_file_content(client)
    if content is None:
        return violations

    for m in _EXPORT_COMPONENT_RE.finditer(content):
        comp_name = m.group(1)
        if any(comp_name.startswith(p) for p in _NON_VIEW_PREFIXES):
            continue
        # Classes (RecipientClient, RecipientHttpClient) are not views.
        if "Client" in comp_name or "Http" in comp_name:
            continue
        if comp_name.endswith("View"):
            continue

        matched_suffix = False
        for suffix in _WRONG_SUFFIXES:
            if comp_name.endswith(suffix):
                base = comp_name[: -len(suffix)]
                violations.append(
                    self.v(
                        f"Component '{comp_name}' in {client.name} uses "
                        f"suffix '{suffix}'. Rename to '{base}View' to "
                        "follow the consistent View naming convention.",
                        str(client),
                        severity="warning",
                    )
                )
                matched_suffix = True
                break
        if not matched_suffix:
            violations.append(
                self.v(
                    f"Component '{comp_name}' in {client.name} does not "
                    f"end with 'View'. Rename to '{comp_name}View'.",
                    str(client),
                    severity="warning",
                )
            )

    return violations

def _view_name_hit(self, client: Path, comp_name: str):
    if any(comp_name.startswith(prefix) for prefix in _NON_VIEW_PREFIXES):
        return None
    if "Client" in comp_name or "Http" in comp_name or comp_name.endswith("View"):
        return None
    for suffix in _WRONG_SUFFIXES:
        if comp_name.endswith(suffix):
            base = comp_name[: -len(suffix)]
            return self.v(
                f"Component '{comp_name}' in {client.name} uses "
                f"suffix '{suffix}'. Rename to '{base}View' to "
                "follow the consistent View naming convention.",
                str(client),
                severity="warning",
            )
    return self.v(
        f"Component '{comp_name}' in {client.name} does not "
        f"end with 'View'. Rename to '{comp_name}View'.",
        str(client),
        severity="warning",
    )

def copy_into(self, dest_folder: str | Path, session: str = "") -> Path | None:
    """Copy model into *dest_folder* when missing — session first, then default."""
    dest = Path(dest_folder) / self.FILENAME
    if dest.is_file():
        return None
    slug = self.session_slug(session)
    for candidate in (slug, self.DEFAULT_SESSION):
        src = self.file_path(candidate)
        if not src.is_file():
            continue
        try:
            text = src.read_text(encoding="utf-8").strip()
        except OSError:
            continue
        if not text:
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(text + "\n", encoding="utf-8")
        return dest
    return None

def list_available(self) -> list[str]:
    """Prefer ``cursor-agent --list-models``; fall back to known Cursor model ids."""
    found: list[str] = []
    try:
        proc = subprocess.run(
            ["cursor-agent", "--list-models"],
            capture_output=True,
            text=True,
            timeout=20,
            check=False,
        )
        blob = (proc.stdout or "") + "\n" + (proc.stderr or "")
        for line in blob.splitlines():
            token = line.strip().split()[0] if line.strip() else ""
            if not token or token.startswith("-") or ":" in token:
                continue
            if token.lower() in {"model", "models", "name", "id"}:
                continue
            if token not in found:
                found.append(token)
    except (OSError, subprocess.SubprocessError, FileNotFoundError):
        pass
    if found:
        return found
    return list(self._FALLBACK_MODELS)

def annotate(self, git: GitRepo) -> None:
    if not self.introducing_commit:
        raise ValueError("Mistake.annotate requires introducing_commit")
    git.note(
        self.introducing_commit,
        {
            "entry_id": self.entry_id,
            "artifact": self.artifact,
            "rule": self.rule,
            "wrong": self.wrong,
            "original": self.original,
            "tool": self.tool,
            "fidelity": self.fidelity,
            "introducing_commit": self.introducing_commit,
        },
    )

def add(self, mistake: Mistake) -> None:
    if mistake not in self.mistakes:
        self.mistakes.append(mistake)
    mistake.correction = self

def link(self, git: GitRepo, fix_commit: str) -> None:
    self.fix_commit = fix_commit
    self.status = "fixed"
    entry_ids = [m.entry_id for m in self.mistakes]
    git.note(
        fix_commit,
        {
            "improved": self.improved,
            "how": self.how,
            "status": self.status,
            "entry_ids": ",".join(entry_ids),
            "fix_commit": fix_commit,
        },
    )
    for mistake in self.mistakes:
        if not mistake.introducing_commit:
            continue
        prior = git.read_notes(mistake.introducing_commit)
        prior["fixed_by"] = fix_commit
        git.note(mistake.introducing_commit, prior)

