def _preview(text: str | None) -> str:
    if text is None:
        return ""
    if not isinstance(text, str):
        text = json.dumps(text, indent=2)
    lines = text.splitlines()
    if len(lines) <= _PREVIEW_LINES and len(text) <= _PREVIEW_CHARS:
        return text
    head = "\n".join(lines[:_PREVIEW_LINES])
    if len(head) > _PREVIEW_CHARS:
        head = head[:_PREVIEW_CHARS]
    return f"{head}\n... [{len(lines)} lines, {len(text)} chars total]"

def _render_scenario(scenario, method_for) -> List[str]:
    lines: List[str] = []
    lines.append(f'    scenario({_js_string(scenario.name)}, ({{ given, when, then }}) => {{')
    for clause in scenario.given:
        method = method_for("given", clause.text)
        lines.append(
            f'      given({_js_string(method.display_text)}, () => h.{method.name}());'
        )
    for interaction in scenario.interactions:
        for clause in interaction.when:
            method = method_for("when", clause.text)
            lines.append(
                f'      when({_js_string(method.display_text)}, () => h.{method.name}());'
            )
        then_lines: List[str] = []
        for i, clause in enumerate(interaction.then):
            method = method_for("then", clause.text)
            verb = "then" if i == 0 else ".and"
            indent = "      " if i == 0 else "        "
            then_lines.append(
                f"{indent}{verb}({_js_string(method.display_text)}, () => h.{method.name}())"
            )
        if then_lines:
            then_lines[-1] += ";"
            lines.extend(then_lines)
    lines.append("    });")
    lines.append("")
    return lines

