def ddd_graph_class_for(source: SourceClass) -> SourceClass:
    base = ddd_class_for(source)
    kind = base._semantic_type_name
    if kind == "OoadClass":
        return OoadClass(
            plain_class_name(source.name),
            source.sequential_order,
            intent=source.intent,
        )
    graph_cls = _BY_KIND[kind]
    node = graph_cls(
        plain_class_name(source.name),
        source.sequential_order,
        intent=source.intent,
    )
    if isinstance(base, SourceRepository) and base.accesses is not None:
        node.accesses = base.accesses
    if isinstance(base, SourceEntityRoot) and base.aggregate is not None:
        node.aggregate = base.aggregate
    if isinstance(base, SourceEntity) and base.identity:
        node.identity = list(base.identity)
    return node

def _rpc(host: str, port: int, payload: dict) -> dict:
    with socket.create_connection((host, port), timeout=600) as conn:
        _write_json(conn, payload)
        return _read_json(conn)

def _handle(conn: socket.socket, server: CodeQLQueryServer) -> None:
    raw = _read_json(conn)
    method = raw.get("method")
    if method == "ping":
        _write_json(conn, {"ok": True})
        return
    if method != "runQueries":
        _write_json(conn, {"error": f"unknown method {method}"})
        return
    log: list[str] = []
    try:
        produced = server.run_queries(
            [Path(path) for path in raw.get("queries") or []],
            Path(raw["database"]),
            log.append,
        )
        _write_json(
            conn,
            {
                "produced": {key: str(value) for key, value in produced.items()},
                "log": log,
            },
        )
    except Exception as error:
        _write_json(conn, {"error": str(error), "log": log})

def _write_json(conn: socket.socket, payload: dict) -> None:
    raw = json.dumps(payload).encode("utf-8")
    conn.sendall(f"{len(raw)}\n".encode("ascii") + raw)

