    ranked = sorted(
        (
            rule
            for rule in self.entries.values()
            if isinstance(rule, WorkSessionRule)
        ),
        key=lambda rule: rule.star,
        reverse=True,
    )
    self.entries = {rule.slug: rule for rule in ranked}

