def parse(self, external: Dict[str, str]) -> StoryMap:
    if not isinstance(external, dict):
        raise CodeStoryMapError("TypeScript story map parse expects a path->content dict")
    story_map = self._make_story_map()
    seen: set[tuple[str, ...]] = set()
    for path, content in sorted(external.items()):
        if not self._is_gwt_leaf(path):
            continue
        parts = path.strip("/").replace("\\", "/").split("/")
        stripped = self.strip_tests_root_prefix(parts)
        if stripped is None:
            continue
        parts = stripped
        if len(parts) < 3:
            continue
        filename = parts[-1]
        story_slug = self._story_slug_from_filename(filename)
        if not story_slug:
            continue
        epic_slug, sub_slugs = parts[0], parts[1:-1]
        if sub_slugs and sub_slugs[-1] == story_slug:
            sub_slugs = sub_slugs[:-1]
        if not sub_slugs:
            continue
        key = (epic_slug, *sub_slugs, story_slug)
        if key in seen:
            continue
        seen.add(key)
        epic = self._ensure_epic(story_map, epic_slug)
        sub = self._ensure_sub_path(epic, sub_slugs)
        story = self._parse_story_file(content, story_slug)
        if story:
            sub.stories.append(story)
    return story_map

def from_workspace(cls, root: Path) -> List[TestSuite]:
    """Find and parse all TypeScript test files under *root*."""
    root = Path(root).resolve()
    if root.is_file():
        if root.suffix in (".ts", ".tsx"):
            return [cls()._parse_file(root, root.parent)]
        return []
    seen: set = set()
    suites: List[TestSuite] = []
    for pattern in _GLOBS:
        for p in root.glob(pattern):
            if p in seen or not p.is_file():
                continue
            seen.add(p)
            suites.append(cls()._parse_file(p, root))
    return suites

