def _tier(self, name: str) -> Tier:
    m = _TIER_TEST.search(name)
    if m:
        return Tier(m.group("tier"))
    # Acceptance layout: `{story_snake}_story.test.ts`.
    if name in {"story-test.ts", "givens.ts"} or name.startswith("story-test."):
        return Tier("")
    m = _TIER_SEAM.search(name)
    if m and m.group("tier") not in {"ts", "tsx"}:
        return Tier(m.group("tier"))
    return Tier("")

def _imports_real(self, text: str) -> bool:
    for line in text.splitlines():
        m = re.match(r"^\s*import\s.+from\s+['\"](?P<mod>[^'\"]+)['\"]", line)
        if not m:
            continue
        mod = m.group("mod")
        if mod.startswith(("vitest", "jest", "@testing-library")):
            continue
        return True
    return False

def _is_gwt_leaf(self, path: str) -> bool:
    name = path.replace("\\", "/").rsplit("/", 1)[-1]
    if name in _SKIP_NAMES or name.endswith("-helper.ts"):
        return False
    if "/examples/" in path.replace("\\", "/"):
        return False
    return name.endswith(_STORY_TEST_SUFFIX)

def _story_slug_from_filename(self, name: str) -> str | None:
    if not name.endswith(_STORY_TEST_SUFFIX):
        return None
    stem = name[: -len(_STORY_TEST_SUFFIX)]
    return stem.replace("_", "-")

