            continue
        seen.add(key)
        included.append(bag)
    return included

def _pattern_matches(self, posix: str, name: str, pattern: str) -> bool:
    if not pattern:
        return False
    if Path(posix).match(pattern) or fnmatch.fnmatch(posix, pattern):
        return True
    leaf = pattern.rsplit("/", 1)[-1]
    if leaf in {"", "*", "**"}:
        return False
    return fnmatch.fnmatch(name, leaf)

