def _is_entry_header(self, candidate: str, current_header: str) -> bool:
    if not _ALL_CAPS.match(candidate):
        return False
    if (
        candidate in self._config.non_entry_headers
        or candidate == current_header
    ):
        return False
    if re.fullmatch(r"\d{2,3}", candidate):
        return False
    return True

