    name = Path(path).name
    if name.endswith("_spec.py") or name.startswith("test_"):
        return True
    if "/examples/" not in f"/{path}":
        return False
    root = self.root.resolve().as_posix().replace("\\", "/").lower()
    return root not in path.lower()

