def _as_workspace_relative(self, path: str) -> str:
    text = path.replace("\\", "/")
    root = str(Path(self.path).resolve()).replace("\\", "/")
    resolved = str(Path(path).resolve()).replace("\\", "/")
    if resolved == root:
        return "./"
    if resolved.startswith(root + "/"):
        return "./" + resolved[len(root) + 1 :]
    if text.startswith("./"):
        return text
    return text

