        relative = path
    posix_path = relative.as_posix()
    url = f"{self.repo_url.rstrip('/')}/blob/{self.ref}/{posix_path}"
    if lines:
        start, end = lines
        url += f"#L{start}-L{end}" if end != start else f"#L{start}"
    return url

