def _domain_type_names(self, type_raw: str) -> List[str]:
    """PascalCase type names from a CE type hint (returns, params, props)."""
    if not type_raw:
        return []
    names: List[str] = []
    for m in re.finditer(r"\b([A-Z][A-Za-z0-9]*)\b", type_raw):
        name = m.group(1)
        if name in self._NON_DOMAIN_TYPE_NAMES or name in names:
            continue
        names.append(name)
    return names

def _magic_numbers(self, func: ast.AST) -> list[tuple[float, int]]:
    safe = {0, 1, 2, -1, 0.0, 1.0, 0.5, 100, 10, True, False, None}
    out: list[tuple[float, int]] = []
    for child in ast.walk(func):
        if isinstance(child, ast.Constant) and isinstance(child.value, (int, float)):
            if child.value not in safe:
                out.append((float(child.value), child.lineno))
    return out

