def _module_name(self, py_file: Path, root: Path) -> str | None:
    try:
        rel = py_file.resolve().relative_to(root.resolve())
    except ValueError:
        return None
    if rel.stem == "__init__":
        parts = list(rel.parts[:-2]) + [rel.parent.name]
    else:
        parts = list(rel.parts[:-1]) + [rel.stem]
    return ".".join(parts)

