def _undeclared_package_hit(self, site: _ImportSite, deps: _DeclaredDeps):
    pkg = self._extract_package_name(site.source)
    if pkg is None or not deps.is_undeclared(pkg):
        return None
    imported = site.source if pkg.startswith("@") else pkg
    return self.v(
        f"'{site.path.name}' imports '{imported}' but "
        f"'{pkg}' is not declared in any package.json. "
        "Add it to the appropriate package.json "
        "dependencies.",
        str(site.path),
        site.start_line,
    )

def _undeclared_package_hit(self, site: _ImportSite, deps: _DeclaredDeps):
    pkg = self._extract_package_name(site.source)
    if pkg is None or not deps.is_undeclared(pkg):
        return None
    imported = site.source if pkg.startswith("@") else pkg
    return self.v(
        f"'{site.path.name}' imports '{imported}' but "
        f"'{pkg}' is not declared in any package.json. "
        "Add it to the appropriate package.json "
        "dependencies.",
        str(site.path),
        site.start_line,
    )

def _extract_package_name(self, source: str) -> Optional[str]:
    """Extract the npm package name from an import source string."""
    if source.startswith(".") or source.startswith("/"):
        return None  # relative import
    if source.startswith("node:"):
        return None  # explicit node built-in
    if "/" in source and not source.startswith("@"):
        return source.split("/")[0]
    if source.startswith("@") and "/" in source:
        parts = source.split("/")
        return f"{parts[0]}/{parts[1]}"
    return source

def annotate(self, fn: Callable[..., Any]) -> Callable[..., Any]:
    setattr(fn, self.flag, True)
    name = getattr(self, "name", None)
    if name is not None:
        setattr(fn, f"{self.flag}_name", name)
    return fn

def _terms_from_html(self, text: str) -> List[str]:
    terms: List[str] = []
    for bullet in re.findall('[\u2022\\-]\\s*([^<]+)', text):
        term = bullet.strip()
        if term and (not term.startswith('{')):
            terms.append(term)
        elif term.startswith('{') and term.endswith('}'):
            continue
        elif term:
            terms.append(term)
    if terms:
        return terms
    for li in re.findall('<li[^>]*>(?:<[^>]+>)*([^<]+)', text, re.IGNORECASE):
        term = li.strip()
        if term and 'stack' not in term.lower():
            terms.append(term)
    return terms

