def _parse_style(self, style: str) -> dict[str, float]:
    out: dict[str, float] = {}
    for kv in (style or '').split(';'):
        if '=' not in kv:
            continue
        key, value = kv.split('=', 1)
        try:
            out[key] = float(value)
        except ValueError:
            continue
    return out

def _segment_direction(self, seg) -> str | None:
    (x1, y1), (x2, y2) = seg
    dx = abs(x2 - x1)
    dy = abs(y2 - y1)
    if dx < 1 and dy < 1:
        return None
    if dx < 1:
        return 'v'
    if dy < 1:
        return 'h'
    return None

def _segment_direction_signed(self, seg) -> str | None:
    (x1, y1), (x2, y2) = seg
    dx = x2 - x1
    dy = y2 - y1
    if abs(dx) < 1 and abs(dy) < 1:
        return None
    if abs(dx) >= abs(dy):
        return 'right' if dx > 0 else 'left'
    return 'down' if dy > 0 else 'up'

def _expected_direction_for_side(self, side: str | None) -> str | None:
    if side in ('left', 'right'):
        return 'h'
    if side in ('top', 'bottom'):
        return 'v'
    return None

