def _concrete_repository_injections(self, server: Path, parsed_root) -> List[Violation]:
    lines = server.read_text(encoding="utf-8", errors="replace").splitlines()
    violations: List[Violation] = []
    for cls in self.classes:
        if "Server" not in cls.name and "Service" not in cls.name:
            continue
        ctor = next((m for m in cls.methods if m.name == "constructor"), None)
        if ctor is None:
            continue
        ctor_line = lines[ctor.start_line - 1] if ctor.start_line <= len(lines) else ""
        if re.search(r"(?:Low(?:db)?|JSONFile)\w*Repository\b", ctor_line):
            violations.append(
                self.v(
                    f"Class '{cls.name}' constructor injects a concrete "
                    "lowdb repository class. Depend on the repository "
                    "INTERFACE instead so tests can inject a fake.",
                    str(server),
                    ctor.start_line,
                )
            )
    return violations

