def _heading_at(self, bare: str) -> tuple[int, int, int, str] | None:
    if self._fence is not None:
        return None
    heading = re.match(r"^(#{1,6})\s+(.+?)\s*$", bare)
    if heading is None:
        return None
    offset = self._offset
    return (offset, offset + len(bare), len(heading.group(1)), heading.group(2))

