def unimplemented_python(self, text: str) -> List[str]:
    found: List[str] = []
    for pattern in (_PY_STEP_DEF, _PY_STEP_DEF_PRIVATE):
        for m in pattern.finditer(text):
            body_no_doc = "\n".join(
                line for line in (m.group("body") or "").splitlines()
                if not re.match(r'^\s*(?:"""|\'\'\')', line)
            )
            if self.is_stub(body_no_doc):
                found.append(m.group("name"))
    return found

def _code_lines(self, body: str) -> List[str]:
    stripped_lines: List[str] = []
    for raw in body.splitlines():
        line = raw.strip()
        if not line or self._is_comment(line):
            continue
        stripped_lines.append(line)
    return stripped_lines

def _is_comment(self, line: str) -> bool:
    if line.startswith("//") or line.startswith("#"):
        return True
    if line.startswith("/*") or line.startswith("*") or line.startswith("*/"):
        return True
    return bool(re.match(r'^(?:"""|\'\'\')', line))

def _is_empty_stub(self, joined: str) -> bool:
    if _TODO_MARKERS.search(joined):
        return True
    if re.search(r"raise\s+NotImplementedError\b", joined):
        return True
    if re.search(r"throw\s+new\s+Error\s*\(\s*['\"`]not implemented", joined, re.IGNORECASE):
        return True
    return joined in ("pass", "pass;", "{}", "return;", "return null;", "return;")

def is_stub(self, body: str) -> bool:
    stripped_lines = self._code_lines(body)
    if not stripped_lines:
        return True
    return self._is_empty_stub("\n".join(stripped_lines))

def parse(cls, text: str, rel_file: str, line_offset: int = 0) -> List["MarkdownIncrement"]:
    """Parse a thin-slicing.md body into a list of MarkdownIncrement nodes."""
    increments: List[MarkdownIncrement] = []
    current: Optional[MarkdownIncrement] = None
    in_stories = False

    for idx, raw in enumerate(text.splitlines(), start=1 + line_offset):
        stripped = raw.strip()
        if not stripped:
            continue
        m_inc = _INCREMENT_H3.match(stripped)
        if m_inc:
            if current is not None:
                increments.append(current)
            current = cls(MarkdownScenario()._strip_markup(m_inc.group(1)), len(increments) + 1)
            current.source = SourceLocation(rel_file, idx)
            in_stories = False
            continue
        if current is None:
            continue
        markup = MarkdownScenario()
        if m := _KV_OUTCOME.match(stripped):
            current.outcome = markup._strip_markup(m.group(1))
            in_stories = False
        elif m := _KV_SLICING.match(stripped):
            current.slicing_notes = markup._strip_markup(m.group(1))
            in_stories = False
        elif m := _KV_DECISION.match(stripped):
            current.decision_prompt = markup._strip_markup(m.group(1))
            in_stories = False
        elif _KV_STORIES.match(stripped):
            in_stories = True
        elif _ANY_H2.match(raw) or _INCREMENT_H3.match(raw):
            in_stories = False
        elif in_stories:
            if m := _BULLET.match(raw):
                current.stories.append(markup._strip_markup(m.group(1)))
            else:
                in_stories = False

    if current is not None:
        increments.append(current)
    return increments

