def from_node(cls, node: "StoryNode") -> "NodeSnapshot":
    return cls(
        node_id=id(node),
        name=node.name,
        sequential_order=node.sequential_order,
        extra_fields=node.snapshot_fields(),
        child_snapshots=[cls.from_node(child) for child in node.children()],
    )

def restore_into(self, node: "StoryNode") -> None:
    node.name = self.name
    node.sequential_order = self.sequential_order
    node.restore_snapshot_fields(self.extra_fields)
    children = node.children()
    for i, child_snapshot in enumerate(self.child_snapshots):
        if i < len(children):
            child_snapshot.restore_into(children[i])

def visit_With(self, node: ast.With) -> ast.AST:
    name = self._get_name(node)
    if name in self.STORY:
        return self._transform_story(node)
    if name in self.STRUCTURE or name in self.STEPS:
        return node
    node = super(StoryNodeTransformer, self).generic_visit(node)  # type: ignore[attr-defined]
    return super().visit_With(node)

def _collect_story_files_in_directory(self, directory: str) -> list[str]:
    found: list[str] = []
    for root, _dirs, files in os.walk(directory):
        for name in files:
            if self._is_story_file(name):
                found.append(os.path.join(self._normalize_path(root), name))
    return found

def _is_story_file(self, path: str) -> bool:
    name = os.path.basename(path)
    if name.endswith("_story.test.py"):
        return True
    return any(path.endswith(suffix) for suffix in self.STORY_SUFFIXES)

def _render_sub_epic(self, sub: SubEpic) -> None:
    self._folder = self._path_join(self._folder, to_kebab(sub.name))
    self._ensure_fixtures(sub)
    folder = self._folder
    for nested in getattr(sub, "sub_epics", []) or []:
        self._folder = folder
        self._render_sub_epic(nested)
    for story in getattr(sub, "stories", []) or []:
        if not story.scenarios:
            continue
        self._folder = folder
        self._render_story(story)

def _extract_aggregate_noun(self, name: str) -> str:
    pascal = to_pascal(name)
    for verb in (
        "Create", "Get", "Manage", "Settle", "Enter", "Know", "Complete",
        "Query", "Submit", "View", "Store", "Update", "Delete", "Place",
    ):
        if pascal.startswith(verb) and len(pascal) > len(verb):
            pascal = pascal[len(verb):]
    return pascal

def _render_epic(self, epic: Epic) -> None:
    self._epic = epic
    epic_slug = to_kebab(epic.name)
    helper_class = f"{to_pascal(epic.name)}Helper"
    self._tree[f"{self._root}/{epic_slug}/{helper_class}.java"] = self._helper(
        helper_class
    )
    self._parent = f"{self._root}/{epic_slug}"
    for sub in getattr(epic, "sub_epics", []) or []:
        self._render_sub(sub)

def _render_sub(self, sub: SubEpic) -> None:
    folder = f"{self._parent}/{to_kebab(sub.name)}"
    saved_parent = self._parent
    self._parent = folder
    for nested in getattr(sub, "sub_epics", []) or []:
        self._render_sub(nested)
    self._parent = saved_parent
    for story in getattr(sub, "stories", []) or []:
        if not story.scenarios:
            continue
        story_folder = f"{folder}/{to_kebab(story.name)}"
        class_name = f"{to_pascal(story.name)}Story"
        self._tree[f"{story_folder}/{class_name}.java"] = render_story_file(story)

