    return any((cell.get('vertex') == '1' and cell.get('id') == cell_id for cell in root.iter('mxCell')))

def __getattr__(name: str):
    from . import guidance as _guidance

    try:
        return getattr(_guidance, name)
    except AttributeError:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}") from None

def _camel_identifier(name: str) -> str:
    raw = (name or "").strip()
    if not raw:
        return raw
    raw = raw.split(":", 1)[0].strip()
    parts = re.split(r"_+", raw.lstrip("_"))
    if not parts:
        return raw
    return parts[0] + "".join(part[:1].upper() + part[1:] for part in parts[1:] if part)

def _append_line(lines: list[str], depth: int, node, graph: PracticeGraph) -> None:
    try:
        line = _hierarchy_line(depth, node)
        mark = _hierarchy_violations(node)
        lines.append(f"{line}  {mark}" if mark else line)
    except Exception as error:
        name = getattr(node, "name", "") or type(node).__name__
        graph.record_partial_failure(f"hierarchy {name}", error)
        lines.append(f"{'  ' * depth}ERROR: {name}: {error}")

