def _slugs_for(graph: PracticeGraph, practices: tuple[str, ...]) -> RuleSlugs:
    wanted = set(practices)
    return RuleSlugs(
        [
            rule.slug
            for rule in graph.rule_registry
            if rule.practice in wanted and rule.graph_evaluated
        ]
    )

